-- Gộp cấu hình người dùng đè lên mặc định.
-- Cách dùng: đặt getgenv().KaitunUserConfig = { ... } trước khi chạy (xem kaitun_config.lua).
-- Vẫn hỗ trợ kiểu cũ: tự đặt getgenv().SettingFarm = { ... } trước khi chạy.
do
    local G = getgenv()
    local user = G.KaitunUserConfig
    if type(user) ~= "table" and type(G.SettingFarm) == "table" and G.SettingFarm ~= G.Z9_MergedSettingFarm then
        user = G.SettingFarm
    end
    local function merge(dst, src)
        for k, v in pairs(src) do
            if type(v) == "table" and type(dst[k]) == "table" then
                merge(dst[k], v)
            else
                dst[k] = v
            end
        end
    end
    local cfg = G.Z9_DefaultSettingFarm
    if type(user) == "table" then merge(cfg, user) end
    G.SettingFarm = cfg
    G.Z9_MergedSettingFarm = cfg
end

-- =========================================================================
-- BỘ CHUẨN HÓA & THÍCH ỨNG CẤU HÌNH NGƯỜI DÙNG (USER CONFIG ADAPTER & NORMALIZER)
-- Tự động ánh xạ mọi định dạng bảng config do người dùng tự chế hoặc import từ script khác!
-- Bọc kín trong do ... end để không làm tăng số biến local toàn cục (0 local overhead).
-- =========================================================================
do
    local cfg = getgenv().SettingFarm
    if type(cfg) == "table" then
        -- 1. Chuẩn hóa Get Items & Get Rare Items
        if type(cfg["Get Items"]) ~= "table" then
            cfg["Get Items"] = {}
        end
        local gi = cfg["Get Items"]

        -- 1.1 Ánh xạ từ Get Rare Items sang Get Items (Rengoku, Dragon Trident, Pole, Gravity Blade, Tushita, Shisui, Saddi, Wando...)
        local gri = cfg["Get Rare Items"] or cfg["GetRareItems"]
        if type(gri) == "table" then
            for rName, rVal in pairs(gri) do
                if rVal == true then
                    gi[rName] = true
                    if rName == "Gravity Blade" then gi["Gravity Cane"] = true end
                    if rName == "Pole (1st Form)" then gi["Pole"] = true end
                end
            end
        end

        -- 1.2 Nhận diện các cờ đặc biệt nằm trong Get Items của config người dùng
        if gi["Auto Pull Lever"] ~= nil or gi["Farm Lever"] ~= nil then
            local plVal = (gi["Auto Pull Lever"] == true or gi["Farm Lever"] == true)
            cfg["Auto Pull Lever"] = cfg["Auto Pull Lever"] or {}
            if type(cfg["Auto Pull Lever"]) == "table" then
                cfg["Auto Pull Lever"]["Enabled"] = plVal
                cfg["Auto Pull Lever"]["Farm Lever"] = plVal
            end
        end

        if gi["Upgrade Race V2-V3"] ~= nil or gi["Race V3"] ~= nil or gi["RaceV3"] ~= nil then
            local r3Val = (gi["Upgrade Race V2-V3"] == true or gi["Race V3"] == true or gi["RaceV3"] == true)
            cfg["Auto Race"] = cfg["Auto Race"] or {}
            if type(cfg["Auto Race"]) == "table" then
                cfg["Auto Race"]["Race V3"] = r3Val
                cfg["Auto Race"]["Enabled"] = r3Val
            end
        end

        -- 1.3 Bổ sung các item mặc định cần thiết nếu chưa được cấu hình
        local defaultGetItems = {
            ["Saber"]              = true,
            ["Secret Quest"]       = true,
            ["True Triple Katana"] = true,
            ["Instinct V2"]        = true,
            ["Mirror Fractal"]     = true,
            ["Godhuman"]           = true,
            ["Yama"]               = true,
            ["Tushita"]            = true,
            ["Cursed Dual Katana"] = true,
            ["Skull Guitar"]       = true,
            ["Shark Anchor"]       = true,
            ["Rainbow Haki"]       = true,
        }
        for k, v in pairs(defaultGetItems) do
            if gi[k] == nil then
                gi[k] = v
            end
        end

        -- 2. Chuẩn hóa Haki (Buy Haki -> Buy Abilities & Buy Instinct)
        local bh = cfg["Buy Haki"] or cfg["BuyHaki"]
        if type(bh) == "table" then
            cfg["Buy Abilities"] = cfg["Buy Abilities"] or {}
            if type(cfg["Buy Abilities"]) == "table" then
                if bh["Enhancement"] ~= nil then cfg["Buy Abilities"]["Aura"] = (bh["Enhancement"] == true) end
                if bh["Aura"] ~= nil then cfg["Buy Abilities"]["Aura"] = (bh["Aura"] == true) end
                if bh["Skyjump"] ~= nil then cfg["Buy Abilities"]["Air Jump"] = (bh["Skyjump"] == true) end
                if bh["Air Jump"] ~= nil then cfg["Buy Abilities"]["Air Jump"] = (bh["Air Jump"] == true) end
                if bh["Flash Step"] ~= nil then cfg["Buy Abilities"]["Flash Step"] = (bh["Flash Step"] == true) end
            end

            cfg["Buy Instinct"] = cfg["Buy Instinct"] or {}
            if type(cfg["Buy Instinct"]) == "table" then
                if bh["Observation"] ~= nil then cfg["Buy Instinct"]["Instinct"] = (bh["Observation"] == true) end
                if bh["Instinct"] ~= nil then cfg["Buy Instinct"]["Instinct"] = (bh["Instinct"] == true) end
            end

            if bh["Observation V2"] ~= nil then
                gi["Instinct V2"] = (bh["Observation V2"] == true)
            end
        end

        -- 3. Chuẩn hóa AUTO BUY
        local ab = cfg["AUTO BUY"] or cfg["AutoBuy"] or cfg["Auto Buy"]
        if type(ab) == "table" then
            if ab["Sword Legendary"] == true then
                gi["True Triple Katana"] = true
                gi["Shisui"] = true
                gi["Saddi"] = true
                gi["Wando"] = true
            end
            if ab["Buy All Sword"] == true then
                gi["Sea1ShopItems"] = true
            end
            if ab["Buy Legendary Haki"] == true then
                gi["Rainbow Haki"] = true
                gi["LegendaryHakiColors"] = true
            end
        end

        -- 4. Chuẩn hóa Farm Mastery & Võ Thuật
        local fm = cfg["Farm Mastery"] or cfg["FarmMastery"]
        if type(fm) == "table" then
            if fm["Melee"] == true or gi["Godhuman"] == true then
                cfg["AutoBuyMelee"] = cfg["AutoBuyMelee"] or {
                    ["Enabled"] = true,
                    ["Melee V1"] = true,
                    ["Melee V2"] = true,
                }
            end
        end

        -- 5. Chuẩn hóa Settings farm (Weapon & ResetStatsForSword)
        if type(cfg["Settings farm"]) ~= "table" then
            cfg["Settings farm"] = {}
        end
        if cfg["Settings farm"]["Weapon"] == nil then
            cfg["Settings farm"]["Weapon"] = cfg["Weapon"] or "Melee"
        end
        if cfg["Settings farm"]["ResetStatsForSword"] == nil then
            if cfg["ResetStatsForSword"] ~= nil then
                cfg["Settings farm"]["ResetStatsForSword"] = cfg["ResetStatsForSword"]
            else
                cfg["Settings farm"]["ResetStatsForSword"] = true
            end
        end
        cfg["ResetStatsForSword"] = cfg["Settings farm"]["ResetStatsForSword"]

        if cfg["Settings farm"]["Auto Farm Level"] == nil then
            if cfg["Auto Farm Level"] ~= nil then
                cfg["Settings farm"]["Auto Farm Level"] = (cfg["Auto Farm Level"] == true or (type(cfg["Auto Farm Level"]) == "table" and cfg["Auto Farm Level"]["Enabled"] == true))
            elseif cfg["Farm Level"] ~= nil then
                cfg["Settings farm"]["Auto Farm Level"] = (cfg["Farm Level"] == true or (type(cfg["Farm Level"]) == "table" and cfg["Farm Level"]["Enabled"] == true))
            else
                cfg["Settings farm"]["Auto Farm Level"] = true
            end
        end

        -- 6. Chuẩn hóa Auto Third World (Tự qua Sea)
        if cfg["Auto Third World"] == nil and cfg["Auto Next Sea"] == nil and cfg["AutoThirdWorld"] == nil then
            cfg["Auto Third World"] = { ["Enabled"] = true }
        end

        -- 7. Chuẩn hóa Auto Fruit & Buddha
        if cfg["Auto Fruit"] == nil then
            cfg["Auto Fruit"] = {
                ["Random"] = true,
                ["StoreFruit"] = true,
                ["GrabFruit"] = true,
            }
        end
        if cfg["Auto Buddha"] == nil then
            cfg["Auto Buddha"] = {
                ["Transform"] = true,
                ["Awaken Z"] = true,
            }
        end
        if cfg["Auto Early Chest"] == nil or cfg["Auto Early Chest"] == true then
            cfg["Auto Early Chest"] = { ["Enabled"] = true }
        end
        if cfg["Auto Pull Lever"] == true then
            cfg["Auto Pull Lever"] = { ["Enabled"] = true, ["Farm Lever"] = true }
        end
        if cfg["Auto Race"] == true then
            cfg["Auto Race"] = { ["Race V3"] = true, ["Enabled"] = true }
        end
        if cfg["Auto Third World"] == true then
            cfg["Auto Third World"] = { ["Enabled"] = true }
        end
        if cfg["Berries"] == true then
            cfg["Berries"] = { ["Enabled"] = true }
        end
        if type(cfg["Buy Abilities"]) == "table" then
            if cfg["Buy Abilities"]["Instinct"] ~= nil then
                cfg["Buy Instinct"] = cfg["Buy Instinct"] or {}
                if type(cfg["Buy Instinct"]) == "table" then
                    cfg["Buy Instinct"]["Instinct"] = (cfg["Buy Abilities"]["Instinct"] == true)
                end
            end
            if cfg["Buy Abilities"]["Smart Dodge"] ~= nil or cfg["Buy Abilities"]["SmartDodge"] ~= nil then
                cfg["Smart Instinct"] = cfg["Smart Instinct"] or {}
                if type(cfg["Smart Instinct"]) == "table" then
                    cfg["Smart Instinct"]["Enabled"] = (cfg["Buy Abilities"]["Smart Dodge"] == true or cfg["Buy Abilities"]["SmartDodge"] == true)
                end
            end
        end
        if type(cfg["Auto Halloween"]) == "table" then
            if cfg["Auto Halloween"]["Enabled"] ~= nil and cfg["Auto Halloween"]["Hellfire Halloween Event"] == nil then
                cfg["Auto Halloween"]["Hellfire Halloween Event"] = (cfg["Auto Halloween"]["Enabled"] == true)
            end
            if cfg["Auto Halloween"]["MaxCandy"] ~= nil and cfg["Auto Halloween"]["Max Candy"] == nil then
                cfg["Auto Halloween"]["Max Candy"] = cfg["Auto Halloween"]["MaxCandy"]
            end
            if cfg["Auto Halloween"]["MinLevel"] ~= nil and cfg["Auto Halloween"]["Min Level"] == nil then
                cfg["Auto Halloween"]["Min Level"] = cfg["Auto Halloween"]["MinLevel"]
            end
        end
        if cfg["Farm Mastery"] == nil then
            cfg["Farm Mastery"] = { ["Melee"] = true, ["Sword"] = true, ["Gun"] = true }
        end
        if cfg["Farm Boss Drops"] == nil and cfg["FarmBossDrops"] == nil and cfg["Boss Drops"] == nil then
            cfg["Farm Boss Drops"] = {
                ["Enabled"] = true,
                ["Sea 1"]   = true,
                ["Sea 2"]   = true,
                ["Sea 3"]   = true,
            }
        elseif cfg["Farm Boss Drops"] == true or cfg["FarmBossDrops"] == true or cfg["Boss Drops"] == true then
            cfg["Farm Boss Drops"] = {
                ["Enabled"] = true,
                ["Sea 1"]   = true,
                ["Sea 2"]   = true,
                ["Sea 3"]   = true,
            }
        end

        -- 8. Chuẩn hóa Tối ưu FPS & Màn hình
        if type(cfg["Lock Fps"]) == "table" and cfg["Lock Fps"]["Enabled"] == true and type(setfpscap) == "function" then
            local fps = tonumber(cfg["Lock Fps"]["FPS"]) or 60
            pcall(function() setfpscap(fps) end)
        end

        -- 9. Chuẩn hóa TweenSpeed & Gộp Bypass TP
        if cfg["Movement"] ~= nil and type(cfg["Movement"]) == "table" then
            cfg["TweenSpeed"] = cfg["TweenSpeed"] or cfg["Movement"]
        end
        if type(cfg["TweenSpeed"]) == "table" then
            if cfg["TweenSpeed"]["Bypass TP"] ~= nil and cfg["Bypass TP"] == nil then
                cfg["Bypass TP"] = { ["Enabled"] = (cfg["TweenSpeed"]["Bypass TP"] == true) }
            end
        elseif cfg["Bypass TP"] ~= nil and cfg["TweenSpeed"] == nil then
            cfg["TweenSpeed"] = { ["Enabled"] = true, ["Speed"] = 350, ["Bypass TP"] = (cfg["Bypass TP"] == true or (type(cfg["Bypass TP"]) == "table" and cfg["Bypass TP"]["Enabled"] == true)) }
        elseif cfg["TweenSpeed"] == nil then
            cfg["TweenSpeed"] = { ["Speed"] = 350, ["Bypass TP"] = true }
        end
        if cfg["Auto Hop"] == nil then
            cfg["Auto Hop"] = { ["Enabled"] = true, ["Hop ping"] = false }
        end
        if cfg["Buy Abilities"] == nil then
            cfg["Buy Abilities"] = { ["Air Jump"] = true, ["Aura"] = true, ["Flash Step"] = true, ["Instinct"] = true, ["Smart Dodge"] = true }
        end

        -- 10. Chuẩn hóa Auto Stats
        if cfg["Auto Stats"] == nil then
            if cfg["Auto stats"] ~= nil then
                cfg["Auto Stats"] = cfg["Auto stats"]
            elseif cfg.AutoStats ~= nil then
                cfg["Auto Stats"] = cfg.AutoStats
            else
                cfg["Auto Stats"] = { ["Enabled"] = true, ["Build"] = "Melee-Defense-Sword" }
            end
        end
        if cfg["Auto Stats"] == true or cfg["Auto Stats"] == false then
            cfg["Auto Stats"] = { ["Enabled"] = cfg["Auto Stats"] }
        elseif type(cfg["Auto Stats"]) == "string" then
            cfg["Auto Stats"] = { ["Enabled"] = true, ["Build"] = cfg["Auto Stats"] }
        end

        -- 11. Chuẩn hóa Auto Bones
        if cfg["Auto Bones"] == nil then
            if cfg.AutoBones ~= nil then
                cfg["Auto Bones"] = cfg.AutoBones
            else
                cfg["Auto Bones"] = { ["Buy Random Surprise"] = true }
            end
        end
        if cfg["Auto Bones"] == true then
            cfg["Auto Bones"] = { ["Buy Random Surprise"] = true }
        elseif cfg["Auto Bones"] == false then
            cfg["Auto Bones"] = { ["Buy Random Surprise"] = false }
        end

        -- 12. Chuẩn hóa Pirate Raid & Dojo Trainer
        if cfg["Pirate Raid"] == nil then
            if cfg.PirateRaid ~= nil then
                cfg["Pirate Raid"] = cfg.PirateRaid
            else
                cfg["Pirate Raid"] = true
            end
        end
        if cfg["Dojo Trainer"] == nil then
            if cfg.DojoTrainer ~= nil or cfg["Auto Dojo"] ~= nil then
                cfg["Dojo Trainer"] = cfg.DojoTrainer or cfg["Auto Dojo"]
            else
                cfg["Dojo Trainer"] = true
            end
        end

        -- 13. Chuẩn hóa Buy Sea 1 Shop Items
        if cfg["Buy Sea 1 Shop Items"] == nil then
            if cfg.BuySea1ShopItems ~= nil or cfg["Sea1ShopItems"] ~= nil then
                cfg["Buy Sea 1 Shop Items"] = cfg.BuySea1ShopItems or cfg["Sea1ShopItems"]
            else
                cfg["Buy Sea 1 Shop Items"] = true
            end
        end

        -- 14. Chuẩn hóa Farm Fragments
        if cfg["Farm Fragments"] == nil then
            if cfg.FarmFragments ~= nil then
                cfg["Farm Fragments"] = cfg.FarmFragments
            else
                cfg["Farm Fragments"] = { ["Enabled"] = false, ["TargetFragment"] = 50000 }
            end
        end
        if cfg["Farm Fragments"] == true then
            cfg["Farm Fragments"] = { ["Enabled"] = true, ["TargetFragment"] = 50000 }
        end

        -- 15. Chuẩn hóa Optimization
        if cfg["Optimization"] == nil then
            if cfg.Optimization ~= nil then
                cfg["Optimization"] = cfg.Optimization
            else
                cfg["Optimization"] = { ["Clean Map"] = true, ["White Screen"] = false }
            end
        end
        if cfg["White Screen"] ~= nil then
            cfg["Optimization"] = cfg["Optimization"] or {}
            if type(cfg["Optimization"]) == "table" then
                cfg["Optimization"]["White Screen"] = (cfg["White Screen"] == true)
            end
        end
        if cfg["Clean Map"] ~= nil then
            cfg["Optimization"] = cfg["Optimization"] or {}
            if type(cfg["Optimization"]) == "table" then
                cfg["Optimization"]["Clean Map"] = (cfg["Clean Map"] == true)
            end
        end
    end
end

-- =========================================================================
-- KIỂM TRA CẤU HÌNH BẮT BUỘC (CONFIG CHECK)
-- =========================================================================
if not getgenv().SettingFarm or type(getgenv().SettingFarm) ~= "table" then
    local missingMsg = "[ x9runner ] Config is missing; run your config first"
    warn(missingMsg)
    pcall(function()
        game:GetService("StarterGui"):SetCore("SendNotification", {
            Title = "[ x9runner ]",
            Text = "Config is missing; run your config first",
            Duration = 10,
        })
    end)
    return
end

-- Các hàm getter helper đồng bộ linh hoạt giữa cấu trúc SettingFarm mới và cũ
local function GetSettingWeapon()
    if getgenv().SettingFarm then
        if type(getgenv().SettingFarm["Settings farm"]) == "table" and getgenv().SettingFarm["Settings farm"]["Weapon"] then
            return getgenv().SettingFarm["Settings farm"]["Weapon"]
        end
        if getgenv().SettingFarm.Weapon then
            return getgenv().SettingFarm.Weapon
        end
    end
    return "Melee"
end

local function SetSettingWeapon(w)
    if getgenv().SettingFarm then
        if type(getgenv().SettingFarm["Settings farm"]) == "table" then
            getgenv().SettingFarm["Settings farm"]["Weapon"] = w
        end
        getgenv().SettingFarm.Weapon = w
    end
end

local function GetSettingTweenSpeed()
    if getgenv().SettingFarm then
        local ts = getgenv().SettingFarm["TweenSpeed"] or getgenv().SettingFarm["Movement"]
        if type(ts) == "table" and ts["Enabled"] ~= false and tonumber(ts["Speed"] or ts["TweenSpeed"]) then
            return math.max(100, tonumber(ts["Speed"] or ts["TweenSpeed"]))
        elseif tonumber(ts) then
            return math.max(100, tonumber(ts))
        end
        if tonumber(getgenv().SettingFarm.Speed) then
            return math.max(100, tonumber(getgenv().SettingFarm.Speed))
        end
    end
    return 350
end

local function IsSettingFruitRandom()
    if getgenv().SettingFarm then
        local af = getgenv().SettingFarm["Auto Fruit"]
        if type(af) == "table" and af["Random"] ~= nil then
            return af["Random"] == true
        end
        if getgenv().SettingFarm.AutoRandom ~= nil then
            return getgenv().SettingFarm.AutoRandom == true
        end
    end
    return true
end

local function IsSettingFruitStore()
    if getgenv().SettingFarm then
        local af = getgenv().SettingFarm["Auto Fruit"]
        if type(af) == "table" and af["StoreFruit"] ~= nil then
            return af["StoreFruit"] == true
        end
        if getgenv().SettingFarm.AutoStoreFruit ~= nil then
            return getgenv().SettingFarm.AutoStoreFruit == true
        end
    end
    return true
end

local function IsSettingFruitGrab()
    if getgenv().SettingFarm then
        local af = getgenv().SettingFarm["Auto Fruit"]
        if type(af) == "table" and af["GrabFruit"] ~= nil then
            return af["GrabFruit"] == true
        end
        if getgenv().SettingFarm.AutoGrabFruit ~= nil then
            return getgenv().SettingFarm.AutoGrabFruit == true
        end
    end
    return true
end

local function IsAutoThirdWorldEnabled()
    if getgenv().SettingFarm then
        local atw = getgenv().SettingFarm["Auto Third World"]
                 or getgenv().SettingFarm["Auto Next Sea"]
                 or getgenv().SettingFarm["Auto World"]
                 or getgenv().SettingFarm.AutoThirdWorld
                 or getgenv().SettingFarm.AutoNextSea
        if type(atw) == "table" and atw["Enabled"] ~= nil then
            return atw["Enabled"] == true
        end
        if atw ~= nil and type(atw) == "boolean" then
            return atw
        end
    end
    return true
end

local function IsBuyAbilityEnabled(name)
    if getgenv().SettingFarm then
        local ba = getgenv().SettingFarm["Buy Abilities"] or getgenv().SettingFarm.BuyAbilities
        if type(ba) == "table" then
            if ba[name] ~= nil then
                return ba[name] == true
            end
        end
    end
    return true
end

local function IsBuyInstinctEnabled()
    if getgenv().SettingFarm then
        local bi = getgenv().SettingFarm["Buy Instinct"] or getgenv().SettingFarm.BuyInstinct
        if type(bi) == "table" then
            if bi["Instinct"] ~= nil then
                return bi["Instinct"] == true
            end
            if bi["Enabled"] ~= nil then
                return bi["Enabled"] == true
            end
        end
    end
    return true
end

local function IsSmartInstinctEnabled()
    if getgenv().SettingFarm then
        local si = getgenv().SettingFarm["Smart Instinct"] or getgenv().SettingFarm.SmartInstinct
        if type(si) == "table" and si["Enabled"] ~= nil then
            return si["Enabled"] == true
        end
        if getgenv().SettingFarm.AutoSmartInstinct ~= nil then
            return getgenv().SettingFarm.AutoSmartInstinct == true
        end
    end
    return true
end

local function IsAutoHalloweenEnabled()
    if getgenv().SettingFarm then
        local ah = getgenv().SettingFarm["Auto Halloween"] or getgenv().SettingFarm.AutoHalloween
        if type(ah) == "table" then
            if ah["Hellfire Halloween Event"] ~= nil then return ah["Hellfire Halloween Event"] == true end
            if ah["HellfireHalloweenEvent"] ~= nil then return ah["HellfireHalloweenEvent"] == true end
            if ah["Enabled"] ~= nil then return ah["Enabled"] == true end
        end
        if getgenv().SettingFarm.AutoHalloween ~= nil then
            return getgenv().SettingFarm.AutoHalloween == true
        end
    end
    return true
end

local function IsAutoBerriesEnabled()
    if getgenv().SettingFarm then
        local b = getgenv().SettingFarm["Berries"] or getgenv().SettingFarm.Berries
        if type(b) == "table" and b["Enabled"] ~= nil then
            return b["Enabled"] == true
        end
        if b ~= nil and type(b) == "boolean" then
            return b
        end
    end
    return false
end

local function IsAutoRaceV3Enabled()
    if getgenv().SettingFarm then
        local ar = getgenv().SettingFarm["Auto Race"] or getgenv().SettingFarm.AutoRace
        if type(ar) == "table" then
            if ar["Race V3"] ~= nil then return ar["Race V3"] == true end
            if ar["RaceV3"] ~= nil then return ar["RaceV3"] == true end
            if ar["Enabled"] ~= nil then return ar["Enabled"] == true end
        end
        if getgenv().SettingFarm.AutoRaceV3 ~= nil then
            return getgenv().SettingFarm.AutoRaceV3 == true
        end
    end
    return true
end

