local function IsAutoHopEnabled()
    -- 1. Tuyệt đối không hop khi đang cầm vật phẩm quý (Chalice, Torch, Fist of Darkness, Essence, Key)
    local lp = game:GetService("Players").LocalPlayer
    if lp then
        for _, c in ipairs({ lp.Character, lp.Backpack }) do
            if c and (
                c:FindFirstChild("God's Chalice")
                or c:FindFirstChild("Sweet Chalice")
                or c:FindFirstChild("Holy Torch")
                or c:FindFirstChild("Fist of Darkness")
                or c:FindFirstChild("Hallow Essence")
                or c:FindFirstChild("Fire Essence")
                or (not getgenv().Z9_DeathStepDoorOpened and c:FindFirstChild("Library Key"))
                or c:FindFirstChild("Water Key")
                or (not getgenv().Z9_HiddenKeyUsed and c:FindFirstChild("Hidden Key"))
                or c:FindFirstChild("Red Key")
            ) then
                return false
            end
        end
    end

    -- 2. Tuyệt đối không hop khi đang làm nhiệm vụ Human V3 (vì cần 3 Boss trong cùng 1 server)
    local getRV = getgenv().Z9_GetRaceVersion
    local isSwanUnl = getgenv().Z9_IsSwanRoomUnlocked
    local isSwanKill = getgenv().Z9_IsDonSwanKilled
    if type(IsAutoRaceV3Enabled) == "function" and IsAutoRaceV3Enabled() and type(getRV) == "function" and getRV() == "V2" then
        local pRace = (lp and lp:FindFirstChild("Data") and lp.Data:FindFirstChild("Race") and tostring(lp.Data.Race.Value)) or ""
        if pRace == "Human" and (type(isSwanUnl) == "function" and isSwanUnl()) and (type(isSwanKill) == "function" and isSwanKill()) then
            return false
        end
    end

    if getgenv().SettingFarm then
        local ah = getgenv().SettingFarm["Auto Hop"] or getgenv().SettingFarm.AutoHop
        if type(ah) == "table" and ah["Enabled"] ~= nil then
            return ah["Enabled"] == true
        end
        if ah ~= nil and type(ah) == "boolean" then
            return ah
        end
    end
    return true -- Mặc định bật để tự động đổi server khi Ping cao hoặc hết boss
end

local function IsHopPingEnabled()
    if not IsAutoHopEnabled() then return false end
    if getgenv().SettingFarm then
        local ah = getgenv().SettingFarm["Auto Hop"] or getgenv().SettingFarm.AutoHop
        if type(ah) == "table" then
            if ah["Hop ping"] ~= nil then
                return ah["Hop ping"] == true
            end
            if ah.HopPing ~= nil then
                return ah.HopPing == true
            end
        end
    end
    return true
end

