local function DismissRobloxErrorPrompt()
    local GuiService = game:GetService("GuiService")
    pcall(function()
        GuiService:ClearError()
    end)
    pcall(function()
        local coreGui = game:GetService("CoreGui")
        local robloxPrompt = coreGui:FindFirstChild("RobloxPromptGui")
        local promptOverlay = robloxPrompt and robloxPrompt:FindFirstChild("promptOverlay")
        local errPrompt = promptOverlay and promptOverlay:FindFirstChild("ErrorPrompt")
        if errPrompt then
            for _, b in ipairs(errPrompt:GetDescendants()) do
                if b:IsA("GuiButton") and b.Visible then
                    pcall(function()
                        local vim = game:GetService("VirtualInputManager")
                        local pos = b.AbsolutePosition + b.AbsoluteSize / 2
                        vim:SendMouseButtonEvent(pos.X, pos.Y, 0, true, game, 1)
                        task.wait(0.04)
                        vim:SendMouseButtonEvent(pos.X, pos.Y, 0, false, game, 1)
                    end)
                end
            end
        end
    end)
end

