-- Hệ thống Tối Ưu Hóa (Lock FPS, White Screen, Clean Map)
task.spawn(function()
    local lastAppliedFps = nil
    local wasLocked = false
    local mapCleaned = false
    local last3dState = nil
    while task.wait(1) do
        pcall(function()
            local cfg = getgenv().SettingFarm
            -- 1. Lock FPS
            local fpsCfg = cfg and cfg["Lock Fps"]
            if type(fpsCfg) == "table" and fpsCfg["Enabled"] == true then
                local targetFps = math.max(5, tonumber(fpsCfg["FPS"]) or 20)
                if setfpscap and lastAppliedFps ~= targetFps then
                    setfpscap(targetFps)
                    lastAppliedFps = targetFps
                    wasLocked = true
                end
            elseif wasLocked then
                if setfpscap then
                    setfpscap(240)
                end
                lastAppliedFps = nil
                wasLocked = false
            end

            -- 2. Tối Ưu Màn Hình (White Screen & Clean Map)
            local optCfg = cfg and (cfg["Optimization"] or cfg.Optimization)
            local whiteScreen = false
            local cleanMap = false
            if type(optCfg) == "table" then
                whiteScreen = (optCfg["White Screen"] == true or optCfg.WhiteScreen == true)
                cleanMap = (optCfg["Clean Map"] == true or optCfg.CleanMap == true)
            elseif cfg and (cfg["White Screen"] == true or cfg.WhiteScreen == true) then
                whiteScreen = true
            end

            -- White Screen: Bật/Tắt 3D Rendering (giảm tải 90% CPU/GPU khi treo máy)
            local target3d = not whiteScreen
            if last3dState ~= target3d then
                local RunService = game:GetService("RunService")
                if type(RunService.Set3dRenderingEnabled) == "function" then
                    pcall(function() RunService:Set3dRenderingEnabled(target3d) end)
                    last3dState = target3d
                end
            end

            -- Clean Map: Tối ưu ánh sáng, xóa sương mù & giảm hạt
            if cleanMap and not mapCleaned then
                mapCleaned = true
                pcall(function()
                    local Lighting = game:GetService("Lighting")
                    Lighting.GlobalShadows = false
                    Lighting.FogEnd = 9e9
                    Lighting.Brightness = 2
                    for _, v in ipairs(Lighting:GetChildren()) do
                        if v:IsA("PostProcessEffect") or v:IsA("Atmosphere") or v:IsA("Clouds") then
                            v.Enabled = false
                        end
                    end
                    local terrain = workspace:FindFirstChildOfClass("Terrain")
                    if terrain then
                        terrain.Decoration = false
                        terrain.WaterWaveSize = 0
                        terrain.WaterWaveSpeed = 0
                    end
                end)
            end
        end)
    end
end)

