local function RedeemSingleCode(code)
    if not code or code == "" then return false end
    local success = false
    -- 1. Gọi trực tiếp RemoteFunction Redeem của Blox Fruits
    pcall(function()
        local redeemRemote = ReplicatedStorage:FindFirstChild("Remotes") and ReplicatedStorage.Remotes:FindFirstChild("Redeem")
        if redeemRemote then
            local res = redeemRemote:InvokeServer(code)
            if res then success = true end
        end
    end)
    -- 2. Fallback qua CommF_
    if not success then
        pcall(function()
            local res = ReplicatedStorage.Remotes.CommF_:InvokeServer("Redeem", code)
            if res then success = true end
        end)
    end
    -- 3. Tương tác trực tiếp với UI "Redeem DLC Code" / "Reward Codes" trong Settings nếu có
    pcall(function()
        local pg = plr:FindFirstChild("PlayerGui")
        if not pg then return end
        for _, gui in ipairs({pg:FindFirstChild("Main"), pg:FindFirstChild("Settings"), pg:FindFirstChild("CodePrompt"), pg}) do
            if gui then
                local tb = gui:FindFirstChildWhichIsA("TextBox", true)
                if tb and (string.find(string.lower(tb.Name), "code") or string.find(string.lower(tb.PlaceholderText or ""), "code")) then
                    tb.Text = code
                    local btn = tb.Parent and (tb.Parent:FindFirstChildWhichIsA("TextButton") or tb.Parent:FindFirstChild("Redeem", true))
                    if btn and btn:IsA("GuiButton") then
                        pcall(function()
                            if getconnections then
                                for _, c in ipairs(getconnections(btn.MouseButton1Click) or getconnections(btn.Activated) or {}) do
                                    c:Fire()
                                end
                            end
                        end)
                    end
                end
            end
        end
    end)
    return success
end

