-- HỆ THỐNG AUTO STATS (TỰ CỘNG ĐIỂM CHỈ SỐ THEO getgenv().SettingFarm)
-- ==========================================
local StatNameMap = {
    ["melee"] = "Melee",
    ["defense"] = "Defense",
    ["sword"] = "Sword",
    ["gun"] = "Gun",
    ["blox fruit"] = "Demon Fruit",
    ["devil fruit"] = "Demon Fruit",
    ["demon fruit"] = "Demon Fruit",
    ["fruit"] = "Demon Fruit",
}

local function IsAutoStatsEnabled()
    if getgenv().SettingFarm then
        local as = getgenv().SettingFarm["Auto Stats"]
        if as == nil then as = getgenv().SettingFarm["Auto stats"] end
        if as == nil then as = getgenv().SettingFarm.AutoStats end
        if as == false then
            return false
        end
        if type(as) == "table" and as.Enabled == false then
            return false
        end
    end
    return true -- Mặc định luôn luôn tự động cộng điểm chỉ số để cày cấp (nó luôn bật ở chỗ xử lý)
end

local function GetNormalizedStatsList()
    local isFarmingSword = (getgenv()._isDoingRaidForF ~= true) and (GetSettingWeapon() == "Sword" or getgenv()._targetSwordName ~= nil)
    if isFarmingSword then
        -- Khi đang farm kiếm: Ưu tiên Kiếm (Sword) và Máu (Defense)
        return { "Sword", "Defense" }
    end

    local raw = nil
    if getgenv().SettingFarm then
        raw = getgenv().SettingFarm["Auto Stats"] or getgenv().SettingFarm["Auto stats"] or getgenv().SettingFarm.AutoStats
    end
    local list = {}
    if type(raw) == "table" then
        if type(raw.Build) == "string" then
            local bLower = string.lower(raw.Build)
            if string.find(bLower, "fruit") or string.find(bLower, "bloxfruit") then
                list = { "Melee", "Defense", "Demon Fruit" }
            elseif string.find(bLower, "gun") then
                list = { "Melee", "Defense", "Gun" }
            elseif string.find(bLower, "sword") then
                list = { "Melee", "Defense", "Sword" }
            end
        end
        if #list == 0 then
            for k, v in pairs(raw) do
                if type(k) == "number" and type(v) == "string" then
                    local mapped = StatNameMap[string.lower(v)] or v
                    table.insert(list, mapped)
                elseif type(k) == "string" and v == true and k ~= "Enabled" then
                    local mapped = StatNameMap[string.lower(k)] or k
                    table.insert(list, mapped)
                end
            end
        end
    end
    if #list == 0 then
        -- Mặc định cộng đều Melee (Năng lượng, Dame Võ V1) và Defense (Máu)
        list = {"Melee", "Defense"}
    end
    return list
end

local function GetStatCurrentLevel(statsFolder, statName)
    local statObj = statsFolder and statsFolder:FindFirstChild(statName)
    if not statObj then return 0 end
    local lvObj = statObj:FindFirstChild("Level")
    if lvObj and lvObj:IsA("ValueBase") then
        return lvObj.Value
    end
    if statObj:IsA("ValueBase") then
        return statObj.Value
    end
    return 0
end

task.spawn(function()
    while task.wait(1) do
        if IsAutoStatsEnabled() then
            pcall(function()
                local data = plr:FindFirstChild("Data")
                local pointsObj = data and data:FindFirstChild("Points")
                local statsFolder = data and data:FindFirstChild("Stats")
                if not pointsObj or not statsFolder or pointsObj.Value <= 0 then
                    return
                end

                local pLv = (data:FindFirstChild("Level") and data.Level.Value) or 2550
                local dynamicCap = 2550
                if pLv > 2600 then
                    dynamicCap = 3000
                elseif pLv > 2550 then
                    dynamicCap = 2600
                end
                for _, sName in ipairs({ "Melee", "Defense", "Sword", "Gun", "Demon Fruit" }) do
                    local sLv = GetStatCurrentLevel(statsFolder, sName)
                    if sLv > dynamicCap then
                        dynamicCap = (sLv <= 2600 and 2600) or 3000
                    end
                end

                local isFarmingSword = (GetSettingWeapon() == "Sword" or getgenv()._targetSwordName ~= nil)
                local targetStats = GetNormalizedStatsList()
                local candidates = {}
                for _, statName in ipairs(targetStats) do
                    local curLv = GetStatCurrentLevel(statsFolder, statName)
                    if curLv < dynamicCap then
                        table.insert(candidates, { Name = statName, Level = curLv })
                    end
                end

                -- Khi đã cộng Max các stat chính (Sword & Defense khi farm kiếm, hoặc Melee & Defense khi farm võ):
                -- Tự động dồn toàn bộ điểm thừa còn lại vào stat phụ ("còn thừa thì nâng còn lại vào melee")!
                if #candidates == 0 then
                    local overflowStats = isFarmingSword and { "Melee", "Gun", "Demon Fruit" } or { "Sword", "Gun", "Demon Fruit" }
                    for _, extraStat in ipairs(overflowStats) do
                        local exLv = GetStatCurrentLevel(statsFolder, extraStat)
                        if exLv < dynamicCap then
                            table.insert(candidates, { Name = extraStat, Level = exLv })
                            break
                        end
                    end
                end

                if #candidates == 0 then return end

                table.sort(candidates, function(a, b)
                    return a.Level < b.Level
                end)

                local ptsBefore = pointsObj.Value
                if #candidates >= 2 and ptsBefore >= #candidates then
                    local perStat = math.max(1, math.floor(ptsBefore / #candidates))
                    for _, cand in ipairs(candidates) do
                        if pointsObj.Value > 0 then
                            local toAdd = math.min(perStat, pointsObj.Value)
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("AddPoint", cand.Name, toAdd)
                        end
                    end
                else
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("AddPoint", candidates[1].Name, ptsBefore)
                end

                -- Fallback: Nếu server từ chối cộng thêm (hoặc đã max stat mục tiêu) -> Đẩy điểm còn lại vào stat thừa
                task.wait(0.2)
                if pointsObj.Value > 0 and pointsObj.Value == ptsBefore then
                    if isFarmingSword then
                        local melLv = GetStatCurrentLevel(statsFolder, "Melee")
                        if melLv < dynamicCap then
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("AddPoint", "Melee", pointsObj.Value)
                        else
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("AddPoint", "Gun", pointsObj.Value)
                        end
                    else
                        local swLv = GetStatCurrentLevel(statsFolder, "Sword")
                        if swLv < dynamicCap then
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("AddPoint", "Sword", pointsObj.Value)
                        else
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("AddPoint", "Gun", pointsObj.Value)
                        end
                    end
                end
            end)
        end
    end
end)

