-- Hàm định dạng số đẹp (VD: 1,234,567)
local function FormatNumber(n)
    n = tostring(n or 0)
    return n:reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
end

-- =========================================================================
-- DỊCH VỤ QUẢN LÝ VẬT PHẨM & TÚI ĐỒ (ITEM REPLICATION SERVICE & ITEM CONFIG)
-- =========================================================================
local ItemReplicationService = nil
local ItemConfig = nil
pcall(function() ItemReplicationService = require(ReplicatedStorage:WaitForChild("ItemReplicationService", 3)) end)
pcall(function() ItemConfig = require(ReplicatedStorage:WaitForChild("ItemConfig", 3)) end)

-- =========================================================================
-- HỆ THỐNG TỰ ĐỘNG LÀM SỰ KIỆN HALLOWEEN (HELLFIRE HALLOWEEN EVENT)
-- =========================================================================
local HW = {
    IgnoredPumpkins = setmetatable({}, { __mode = "k" }),
    IgnoredDoors = setmetatable({}, { __mode = "k" }),
    DoorCooldowns = setmetatable({}, { __mode = "k" }),
    DoorPositionCooldowns = {},
    CurrentTask = "Đang quét sự kiện...",
    LastSpookyGachaTick = 0,
    LastDoorResetHour = -1,
    LastDoorScanTick = 0,
    CachedDoor = nil,
    DoorArrivedTick = nil,
    CurrentDoorTarget = nil,
    CurrentDoorCF = nil,
    CurrentDoorStartTick = 0,
    CurrentDoorArrivedTick = nil,
    DoorStandCF = nil,
    LastScreenClick = 0,
    LastKeyE = 0,
    BusyAt = 0,
    CachedCandies = 0,
    LastInvCheck = 0,
    HasCheckedCandies = false,
}

function HW.GetDoorPosKey(cf)
    if not cf then return nil end
    local p = cf.Position
    return string.format("%d,%d,%d", math.floor(p.X / 10), math.floor(p.Y / 10), math.floor(p.Z / 10))
end

function HW.IsDoorOnCooldown(door, cf)
    local now = tick()
    if door and (HW.DoorCooldowns[door] or 0) > now then
        return true
    end
    if door and HW.IgnoredDoors[door] then
        return true
    end
    cf = cf or (HW.GetPivotCF and HW.GetPivotCF(door))
    if cf then
        local posKey = HW.GetDoorPosKey(cf)
        if posKey and (HW.DoorPositionCooldowns[posKey] or 0) > now then
            return true
        end
    end
    return false
end

function HW.SetDoorCooldown(door, cf, duration)
    local dur = duration or 120
    local expiry = tick() + dur
    if door then
        HW.DoorCooldowns[door] = expiry
    end
    cf = cf or (HW.GetPivotCF and HW.GetPivotCF(door))
    if cf then
        local posKey = HW.GetDoorPosKey(cf)
        if posKey then
            HW.DoorPositionCooldowns[posKey] = expiry
        end
    end
end

function HW.HasNobodyHomeOrBusyNotification()
    local pg = plr:FindFirstChild("PlayerGui")
    if not pg then return false end
    local skipTexts = { "nobody is home", "nobody's home", "still busy with another door", "still busy", "already visited", "try again" }
    local found = false
    pcall(function()
        for _, o in ipairs(pg:GetDescendants()) do
            if (o:IsA("TextLabel") or o:IsA("TextButton")) and o.Text ~= "" then
                local txt = string.lower(o.Text)
                for _, pat in ipairs(skipTexts) do
                    if txt:find(pat, 1, true) then
                        found = true
                        HW.BusyAt = tick()
                        pcall(function()
                            o.Text = ""
                            o.Visible = false
                            local parent = o.Parent
                            if parent and parent:IsA("GuiObject") and parent ~= pg then
                                parent.Visible = false
                            end
                        end)
                        break
                    end
                end
                if found then break end
            end
        end
    end)
    return found
end

function HW.EnsureBusyHook()
    if getgenv().__HW_BusyHooked then return end
    getgenv().__HW_BusyHooked = true
    pcall(function()
        local pg = plr:WaitForChild("PlayerGui", 5)
        if not pg then return end
        local skipTexts = { "nobody is home", "nobody's home", "still busy with another door", "still busy", "already visited", "try again" }
        local function checkLabel(o)
            if not o:IsA("TextLabel") and not o:IsA("TextButton") then return end
            local txt = string.lower(o.Text or "")
            if txt:find("obtained", 1, true) and (txt:find("candy corn", 1, true) or txt:find("pumpkin bits", 1, true)) then
                HW.GotPumpkinItemAt = tick()
            end
            for _, pat in ipairs(skipTexts) do
                if txt:find(pat, 1, true) then
                    HW.BusyAt = tick()
                    pcall(function()
                        o.Text = ""
                        o.Visible = false
                    end)
                    break
                end
            end
        end

        for _, o in ipairs(pg:GetDescendants()) do
            if o:IsA("TextLabel") or o:IsA("TextButton") then
                pcall(checkLabel, o)
                o:GetPropertyChangedSignal("Text"):Connect(function()
                    pcall(checkLabel, o)
                end)
            end
        end

        if getgenv().__HW_BusyHookConn then
            pcall(function() getgenv().__HW_BusyHookConn:Disconnect() end)
        end
        getgenv().__HW_BusyHookConn = pg.DescendantAdded:Connect(function(o)
            if o:IsA("TextLabel") or o:IsA("TextButton") then
                pcall(checkLabel, o)
                o:GetPropertyChangedSignal("Text"):Connect(function()
                    pcall(checkLabel, o)
                end)
            end
        end)
    end)
end

function HW.ClearTryAgainNotification()
    pcall(function()
        local pg = plr:FindFirstChild("PlayerGui")
        if not pg then return end
        local skipTexts = { "nobody is home", "nobody's home", "still busy with another door", "still busy", "already visited", "try again" }
        for _, o in ipairs(pg:GetDescendants()) do
            if o:IsA("TextLabel") or o:IsA("TextButton") then
                local txt = string.lower(o.Text or "")
                for _, pat in ipairs(skipTexts) do
                    if txt:find(pat, 1, true) then
                        pcall(function()
                            o.Text = ""
                            o.Visible = false
                            local parent = o.Parent
                            if parent and parent:IsA("GuiObject") and parent ~= pg then
                                parent.Visible = false
                            end
                        end)
                        break
                    end
                end
            end
        end
    end)
end

function HW.IsHarvestMoonTime()
    local curMin = tonumber(os.date("%M")) or (os.date("*t").min or 0)
    -- Sự kiện Harvest Moon (Trick-or-Treat gõ cửa) CHỈ mở từ phút 00 đến 09 của mỗi giờ tròn (10 phút đầu)
    return curMin >= 0 and curMin < 10
end

function HW.IsEventActive(hrp)
    if not IsAutoHalloweenEnabled() then
        return false
    end

    -- Yêu cầu cấp độ tối thiểu (Acc cấp 1 đi farm tầm cấp 50 rồi mới farm sự kiện)
    local pLv = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0
    local minLevel = (HW.GetMinLevel and HW.GetMinLevel()) or 50
    if pLv < minLevel then
        return false
    end

    -- Cập nhật số lượng Kẹo Ngô mới nhất
    local curCandies = HW.GetEventCandies() or 0
    local maxCandies = HW.GetMaxCandy() -- Mặc định 500 kẹo

    -- YÊU CẦU: Nếu đã đủ 500 Kẹo Ngô và không bị kẹt trong Hellfire Realm -> Dừng sự kiện, quay lại farm cấp!
    if curCandies >= maxCandies and not HW.IsInHellfireRealm(hrp) then
        return false
    end

    -- KHI CHƯA ĐỦ 500 KẸO NGÔ: SỰ KIỆN LUÔN LUÔN HOẠT ĐỘNG VÀ ĐƯỢC ƯU TIÊN TUYỆT ĐỐI 100%!
    return true
end

function HW.GetMaxCandy()
    if getgenv().SettingFarm then
        local ah = getgenv().SettingFarm["Auto Halloween"] or getgenv().SettingFarm.AutoHalloween
        if type(ah) == "table" then
            local mc = ah["Max Candy"] or ah["MaxCandy"] or ah["CandyLimit"] or ah["LimitCandy"]
            if tonumber(mc) then
                return tonumber(mc)
            end
        end
    end
    return 500 -- Mặc định: 500 Kẹo Ngô (đủ 1 lần quay Spooky Gacha nhận thưởng giới hạn)
end

function HW.GetMinLevel()
    if getgenv().SettingFarm then
        local ah = getgenv().SettingFarm["Auto Halloween"] or getgenv().SettingFarm.AutoHalloween
        if type(ah) == "table" then
            local ml = ah["Min Level"] or ah["MinLevel"] or ah["LevelMin"]
            if ml and tonumber(ml) then
                return tonumber(ml)
            end
        end
    end
    return 50 -- Mặc định: Cấp 50 (Acc cấp 1 đi farm tầm cấp 50 rồi mới farm sự kiện)
end

function HW.GetEventCandies()
    local now = tick()
    if (now - (HW.LastCandiesCheck or 0)) >= 5.0 or not HW.HasCheckedCandies then
        HW.LastCandiesCheck = now
        pcall(HW.UpdateCandies)
    end
    return HW.CachedCandies or 0
end

function HW.UpdateCandies()
    HW.HasCheckedCandies = true

    -- Hàm nhận diện chuẩn xác Kẹo Ngô (Candy Corn) của Halloween Event
    -- TUYỆT ĐỐI không khớp nhầm với Kẹo Giáng Sinh / Bánh Đảo ("Candy") hoặc các thành phần UI ("Corner", "UICorner", "Ping")
    local function isExactCandyCorn(name, id)
        local s1 = string.lower(tostring(name or ""))
        local s2 = string.lower(tostring(id or ""))
        -- LOẠI TRỪ NGAY LẬP TỨC: Các từ ngữ không liên quan nhưng có chữ "corn" như "corner", "uicorner", hoặc "ping", "fps", "cframe", "stat"
        if s1:find("corner") or s2:find("corner") or
           s1:find("uicorner") or s2:find("uicorner") or
           s1:find("ping") or s2:find("ping") or
           s1:find("fps") or s2:find("fps") or
           s1:find("cframe") or s2:find("cframe") or
           s1:find("level") or s2:find("level") then
            return false
        end
        -- Khớp chính xác Kẹo Ngô (Candy Corn / CandyCorn / Candy_Corn / Kẹo Ngô)
        if s1:find("candycorn") or s2:find("candycorn") or
           s1:find("candy corn") or s2:find("candy corn") or
           s1:find("candy_corn") or s2:find("candy_corn") or
           s1:find("kẹo ngô") or s1:find("keo ngo") or
           s1 == "candycorn" or s2 == "candycorn" or
           s1 == "candy corn" or s2 == "candy corn" or
           s1 == "candy_corn" or s2 == "candy_corn" or
           s1 == "corn" or s2 == "corn" then
            return true
        end
        return false
    end

    local foundCandyCorn = nil
    local scannedAnySource = false

    -- 1. Quét trực tiếp từ GUI Items / Stash (Kho đồ) trên màn hình (Chuẩn xác 100% với những gì người chơi thấy)
    pcall(function()
        local pg = plr:FindFirstChild("PlayerGui")
        if not pg then return end
        for _, desc in ipairs(pg:GetDescendants()) do
            if foundCandyCorn ~= nil then break end
            local dName = string.lower(tostring(desc.Name or ""))
            -- Bỏ qua toàn bộ UI của script Z9 để tránh vòng lặp đọc nhầm
            if not dName:find("z9") and not dName:find("corner") and not dName:find("ping") then
                local attrName = tostring(desc:GetAttribute("ItemName") or desc:GetAttribute("Name") or desc:GetAttribute("ItemId") or "")
                local isCornSlot = isExactCandyCorn(desc.Name, attrName)

                if not isCornSlot then
                    for _, ch in ipairs(desc:GetChildren()) do
                        if ch:IsA("TextLabel") or ch:IsA("TextButton") then
                            local t = string.lower(ch.Text or "")
                            if isExactCandyCorn(t, ch.Name) and not t:find("/500") and not t:find("tiến trình") and not t:find("khung giờ") then
                                isCornSlot = true
                                break
                            end
                        elseif ch:IsA("ImageLabel") or ch:IsA("ImageButton") then
                            local img = string.lower(tostring(ch.Image or ""))
                            if img:find("candycorn") or img:find("candy_corn") then
                                isCornSlot = true
                                break
                            end
                        end
                    end
                end

                if isCornSlot then
                    -- 1.1 Tìm trong thuộc tính Attribute của ô slot
                    local cAttr = desc:GetAttribute("Count") or desc:GetAttribute("Amount") or desc:GetAttribute("Quantity") or desc:GetAttribute("Value")
                    if tonumber(cAttr) and tonumber(cAttr) >= 0 then
                        foundCandyCorn = tonumber(cAttr)
                        break
                    end

                    -- 1.2 Tìm TextLabel hiển thị số lượng trong ô slot (ví dụ "152", "x152", "0")
                    for _, lbl in ipairs(desc:GetDescendants()) do
                        if lbl:IsA("TextLabel") or lbl:IsA("TextBox") then
                            local rawT = tostring(lbl.Text or ""):gsub(",", "")
                            local cleanLetters = rawT:gsub("[%d%s]", "")
                            if #cleanLetters <= 1 then
                                local num = tonumber(rawT:match("(%d+)"))
                                if num and num >= 0 and num < 10000000 then
                                    foundCandyCorn = num
                                    break
                                end
                            end
                        end
                    end
                end
            end
        end
    end)

    -- 2. Đọc từ Remote CommF_ ("getInventory", "getInventoryMaterials", "GetMaterials", "getMaterials", "getStash", "getStashMaterials", "getInventoryItems")
    -- Hỗ trợ cả 2 định dạng: Mảng các bảng ({Name="Candy Corn", Count=152}) hoặc Bảng ánh xạ ({["Candy Corn"]=152})
    if foundCandyCorn == nil then
        pcall(function()
            local remotes = {
                "getInventory",
                "getInventoryMaterials",
                "GetMaterials",
                "getMaterials",
                "getStash",
                "getStashMaterials",
                "getInventoryItems",
                "GetInventory"
            }
            for _, rName in ipairs(remotes) do
                if foundCandyCorn ~= nil then break end
                local ok, inv = pcall(function()
                    return ReplicatedStorage.Remotes.CommF_:InvokeServer(rName)
                end)
                if ok and type(inv) == "table" then
                    scannedAnySource = true
                    for key, it in pairs(inv) do
                        local itemName = ""
                        local itemAmt = nil
                        if type(it) == "table" then
                            itemName = tostring(it.Name or it.ItemId or it.Id or it.StorageKey or key or "")
                            local dName = tostring(it.DisplayName or it.ItemName or "")
                            if isExactCandyCorn(itemName, dName) then
                                itemAmt = tonumber(it.Count) or tonumber(it.Amount) or tonumber(it.Value) or tonumber(it.Quantity)
                            end
                        elseif type(it) == "number" then
                            itemName = tostring(key)
                            if isExactCandyCorn(itemName, itemName) then
                                itemAmt = it
                            end
                        end
                        if itemAmt and itemAmt >= 0 then
                            foundCandyCorn = itemAmt
                            break
                        end
                    end
                end
            end
        end)
    end

    -- 3. Đọc từ ItemReplicationService & ItemConfig của Blox Fruits (Chuẩn RAM client)
    if foundCandyCorn == nil then
        pcall(function()
            local req = (getrenv and getrenv().require) or require
            local IRS = ItemReplicationService
            if not IRS then
                pcall(function() IRS = req(ReplicatedStorage:WaitForChild("ItemReplicationService", 4)) end)
                if not IRS then pcall(function() IRS = require(ReplicatedStorage.ItemReplicationService) end) end
                if IRS then ItemReplicationService = IRS end
            end
            local IC = ItemConfig
            if not IC then
                pcall(function() IC = req(ReplicatedStorage:WaitForChild("ItemConfig", 4)) end)
                if not IC then pcall(function() IC = require(ReplicatedStorage.ItemConfig) end) end
                if IC then ItemConfig = IC end
            end

            if IRS and IRS.KEYS then
                local qKey = IRS.KEYS.QUANTITY
                local rawItems = nil
                pcall(function() rawItems = IRS:GetItems(qKey) end)
                if not rawItems and IRS.GetItems then
                    pcall(function() rawItems = IRS:GetItems() end)
                end
                if type(rawItems) == "table" then
                    scannedAnySource = true
                end

                local function checkItem(item, itemKey)
                    if not item then return false end
                    local val = nil
                    local iId = ""
                    local dName = ""
                    if type(item) == "table" then
                        val = tonumber(item.Value) or tonumber(item.Count) or tonumber(item.Amount) or tonumber(item.Quantity)
                        iId = tostring(item.ItemId or item.Id or item.Name or itemKey or "")
                        if IC and IC.match and (item.ItemId or item.Id) then
                            local ok, cfg = pcall(function() return IC.match(item.ItemId or item.Id):unwrap() end)
                            if ok and cfg then
                                dName = tostring((cfg.Display and (cfg.Display.Name or (cfg.Index and cfg.Index.StorageKey))) or (cfg.Index and cfg.Index.StorageKey) or cfg.Name or "")
                            end
                        end
                    elseif type(item) == "number" then
                        val = item
                        iId = tostring(itemKey or "")
                    end

                    if val and val >= 0 and isExactCandyCorn(dName, iId) then
                        foundCandyCorn = val
                        return true
                    end
                    return false
                end

                -- Quét direct key nếu có
                for _, k in ipairs({ "CandyCorn", "Candy Corn", "Candy_Corn", "candycorn" }) do
                    if foundCandyCorn ~= nil then break end
                    pcall(function()
                        if IRS.GetItemQuantity then
                            local q = IRS:GetItemQuantity(k)
                            if tonumber(q) and tonumber(q) >= 0 then foundCandyCorn = tonumber(q) end
                        end
                        if foundCandyCorn == nil and IRS.GetItemCount then
                            local q = IRS:GetItemCount(k)
                            if tonumber(q) and tonumber(q) >= 0 then foundCandyCorn = tonumber(q) end
                        end
                        if foundCandyCorn == nil and IRS.GetItem then
                            local it = IRS:GetItem(k)
                            if type(it) == "table" then
                                local q = tonumber(it.Value) or tonumber(it.Count) or tonumber(it.Amount) or tonumber(it.Quantity)
                                if q and q >= 0 then foundCandyCorn = q end
                            elseif tonumber(it) and tonumber(it) >= 0 then
                                foundCandyCorn = tonumber(it)
                            end
                        end
                    end)
                end

                if foundCandyCorn == nil and rawItems then
                    pcall(function()
                        for k, it in pairs(rawItems) do
                            if checkItem(it, k) then break end
                        end
                    end)
                end
            end
        end)
    end

    -- 4. Đọc từ Data / Attributes người chơi
    if foundCandyCorn == nil then
        pcall(function()
            local data = plr:FindFirstChild("Data")
            if data then
                scannedAnySource = true
                for _, child in ipairs(data:GetChildren()) do
                    if isExactCandyCorn(child.Name, child.Name) and tonumber(child.Value) and tonumber(child.Value) >= 0 then
                        foundCandyCorn = tonumber(child.Value)
                        break
                    end
                end
            end
            if foundCandyCorn == nil then
                for _, aName in ipairs({ "CandyCorn", "Candy Corn", "Candy_Corn", "Corn" }) do
                    local val = plr:GetAttribute(aName)
                    if tonumber(val) and tonumber(val) >= 0 and isExactCandyCorn(aName, aName) then
                        foundCandyCorn = tonumber(val)
                        break
                    end
                end
            end
        end)
    end

    -- Cập nhật vào HW.CachedCandies (Đồng bộ chuẩn xác với kho đồ)
    -- Nếu đã quét thành công kho đồ nhưng không hề có Kẹo Ngô (hoặc số lượng bằng 0), gán ngay về 0!
    if foundCandyCorn ~= nil then
        HW.CachedCandies = math.max(0, tonumber(foundCandyCorn) or 0)
    elseif scannedAnySource then
        HW.CachedCandies = 0
    end
end

-- =========================================================================
-- HÀM QUAY SPOOKY GACHA HALLOWEEN TỪ XA (BYPASS REMOTE GACHA TƯƠNG TỰ RANDOM TRÁI ZIOLES)
-- Không cần bay tới NPC, tự động gọi qua RF/GachaNetworkRF và CommF_ ở mọi nơi trên bản đồ!
-- =========================================================================
function HW.ExecuteRemoteSpookyGacha()
    -- Kiểm tra cooldown gacha: 5 phút (300s) chuẩn game
    if tick() < (HW.NextSpookyGachaTick or 0) then return false end

    -- Cập nhật số lượng kẹo mới nhất
    local curCandies = HW.GetEventCandies()
    -- Nếu đã quét ra kẹo và thực sự < 500 kẹo thì không gọi
    if HW.CachedCandies and HW.CachedCandies > 0 and HW.CachedCandies < 500 then
        return false
    end

    HW.NextSpookyGachaTick = tick() + 15 -- Set tạm thời 15s để tránh gọi liên tục
    HW.LastSpookyGachaTick = tick()

    local rolled = false
    local res = nil

    -- 1. BYPASS TỪ XA CHUẨN BANANA CAT HUB & TOPI: RF/GachaNetworkRF ("Halloween26Gacha")
    pcall(function()
        local net = ReplicatedStorage:FindFirstChild("Modules") and ReplicatedStorage.Modules:FindFirstChild("Net")
        local gachaNet = net and net:FindFirstChild("RF/GachaNetworkRF")
        if gachaNet then
            res = gachaNet:InvokeServer({
                Context = "Purchase",
                BoxName = "Halloween26Gacha",
            })
            if (type(res) == "table" and res.Success == true) or res == 1 or res == true then
                rolled = true
            end
        end
    end)

    -- 2. Dự phòng các tên box khác nếu server dùng tên khác
    if not rolled then
        pcall(function()
            local net = ReplicatedStorage:FindFirstChild("Modules") and ReplicatedStorage.Modules:FindFirstChild("Net")
            local gachaNet = net and net:FindFirstChild("RF/GachaNetworkRF")
            if gachaNet then
                for _, bName in ipairs({ "SpookyGacha", "HalloweenGacha", "HalloweenBox" }) do
                    local r = gachaNet:InvokeServer({
                        Context = "Purchase",
                        BoxName = bName,
                    })
                    if (type(r) == "table" and r.Success) or r == 1 or r == true then
                        rolled = true
                        res = r
                        break
                    end
                end
            end
        end)
    end

    -- 3. Dự phòng các remote CommF_ truyền thống của game
    if not rolled then
        pcall(function()
            local comm = ReplicatedStorage.Remotes.CommF_
            local r1 = comm:InvokeServer("Cousin", "Halloween26Gacha")
            if r1 == 1 or r1 == true or (type(r1) == "table" and r1.Success) then
                rolled = true
                res = r1
            else
                local r2 = comm:InvokeServer("Halloween26Gacha", "Buy")
                if r2 == 1 or r2 == true or (type(r2) == "table" and r2.Success) then
                    rolled = true
                    res = r2
                else
                    comm:InvokeServer("SpookyGacha", "Buy")
                    comm:InvokeServer("HalloweenGacha", "Buy")
                    comm:InvokeServer("Halloween", "BuyGacha")
                    comm:InvokeServer("BuySpookyGacha")
                end
            end
        end)
    end

    -- Đóng SpinnerWindow và UI quay thưởng để không làm phiền màn hình người chơi
    task.spawn(function()
        pcall(function()
            local pg = plr:FindFirstChild("PlayerGui")
            if pg then
                local sw = pg:FindFirstChild("SpinnerWindow")
                if sw then sw.Visible = false end
            end
        end)
    end)

    -- Cập nhật trừ ngay 500 Kẹo Ngô trong cache và reset debounce để quét lại từ Server
    HW.CachedCandies = math.max(0, (HW.CachedCandies or 500) - 500)
    HW.LastCandiesCheck = 0
    task.delay(1, function()
        pcall(HW.UpdateCandies)
    end)

    -- Đặt hồi chiêu chuẩn gacha: 5 phút (300 giây)
    HW.NextSpookyGachaTick = tick() + 300
    pcall(function()
        game:GetService("StarterGui"):SetCore("SendNotification", {
            Title = "🎃 Halloween Spooky Gacha",
            Text = "Đã tự động quay Spooky Gacha từ xa (-500 Kẹo Ngô) Hồi chiêu: 5 phút",
            Duration = 5
        })
    end)

    return true
end

-- Vòng lặp chạy nền cập nhật số lượng Kẹo Ngô & Tự động quay Spooky Gacha từ xa
task.spawn(function()
    pcall(HW.UpdateCandies)
    task.wait(2)
    while true do
        pcall(HW.UpdateCandies)
        pcall(function()
            if IsAutoHalloweenEnabled() then
                HW.ExecuteRemoteSpookyGacha()
            end
        end)
        task.wait(3)
    end
end)

function HW.GetStatusText()
    local ok, res = pcall(function()
        if not IsAutoHalloweenEnabled() then
            return "• Trạng thái: Tắt trong cài đặt"
        end
        local pLv = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0
        local minLevel = (HW.GetMinLevel and HW.GetMinLevel()) or 50
        if pLv < minLevel then
            return "• Trạng thái: Cần đạt Cấp " .. tostring(minLevel) .. "+ để mở khóa Sự Kiện (Hiện tại: Cấp " .. tostring(pLv) .. "/" .. tostring(minLevel) .. ")" ..
                   "\n• Tiến trình: Đang ưu tiên farm cấp lên " .. tostring(minLevel) .. " trước"
        end
        local candies = HW.GetEventCandies() or 0
        local maxCandies = HW.GetMaxCandy()
        local isHarvest = HW.IsHarvestMoonTime()
        local curMin = tonumber(os.date("%M")) or (os.date("*t").min or 0)
        local timeDesc = isHarvest and ("🌕 Đang có sự kiện (10 phút đầu: " .. tostring(curMin) .. "p/10p) - Chỉ gõ cửa & đánh Boss")
            or ("🎃 Ngoài sự kiện (" .. tostring(curMin) .. "p/60p) - " .. (candies < maxCandies and "Săn Bí Ngô gom kẹo" or "Đã đủ 500 kẹo, đi farm cấp"))
        local candyStr = (candies >= maxCandies) and ("🍬 " .. FormatNumber(candies) .. "/" .. FormatNumber(maxCandies) .. " (Đã đầy -> Farm Cấp)") or ("🍬 " .. FormatNumber(candies) .. "/" .. FormatNumber(maxCandies))
        local defaultTask = isHarvest and "Tìm Cửa Trick-or-Treat / Cổng Boss" or ((candies >= maxCandies) and "Đã đủ " .. tostring(maxCandies) .. " Kẹo Ngô (Đang farm cấp/võ)" or "Săn Bí Ngô gom kẹo")
        return "• Kẹo Ngô (Candy Corn): " .. candyStr ..
               "\n• Khung giờ: " .. timeDesc ..
               "\n• Tiến trình: " .. tostring(HW.CurrentTask or defaultTask)
    end)
    if ok and res then return res end
    return "• Trạng thái: Đang hoạt động\n• Tiến trình: " .. tostring(HW.CurrentTask or "Đang sẵn sàng")
end

local function SafeClickGuiButton(btn)
    if not btn then return false end

    pcall(function()
        if firesignal then
            firesignal(btn.MouseButton1Click)
            firesignal(btn.MouseButton1Down)
            firesignal(btn.MouseButton1Up)
            firesignal(btn.Activated)
        end
    end)

    pcall(function()
        if getconnections then
            for _, c in ipairs(getconnections(btn.MouseButton1Click)) do
                if type(c) == "table" or type(c) == "userdata" then
                    if c.Fire then pcall(function() c:Fire() end)
                    elseif c.Function then pcall(function() c.Function() end) end
                end
            end
            for _, c in ipairs(getconnections(btn.Activated)) do
                if type(c) == "table" or type(c) == "userdata" then
                    if c.Fire then pcall(function() c:Fire() end)
                    elseif c.Function then pcall(function() c.Function() end) end
                end
            end
        end
    end)

    pcall(function()
        local pos = btn.AbsolutePosition + (btn.AbsoluteSize / 2)
        if pos.X > 0 and pos.Y > 0 then
            local vu = game:GetService("VirtualUser")
            if vu then
                vu:CaptureController()
                vu:ClickButton1(Vector2.new(pos.X, pos.Y))
            end

            local vim = game:GetService("VirtualInputManager")
            if vim then
                vim:SendMouseButtonEvent(pos.X, pos.Y, 0, true, game, 1)
                task.wait(0.02)
                vim:SendMouseButtonEvent(pos.X, pos.Y, 0, false, game, 1)
                pcall(function()
                    vim:SendTouchEvent(1, 0, pos.X, pos.Y)
                    task.wait(0.02)
                    vim:SendTouchEvent(1, 2, pos.X, pos.Y)
                end)
            end
        end
    end)
    return true
end

