-- Lưu danh sách võ V1 & V2 đã đạt >= 400 Mastery và mức Mastery cao nhất đã ghi nhận
-- Cách ly hoàn toàn theo UserId của từng tài khoản Player (tránh dùng nhầm dữ liệu của acc cũ)
getgenv().Z9_CurrentMeleeUserId = tostring(plr and plr.UserId or 0)
getgenv()["Z9_MasteredV1Styles_" .. getgenv().Z9_CurrentMeleeUserId] = getgenv()["Z9_MasteredV1Styles_" .. getgenv().Z9_CurrentMeleeUserId] or {}
getgenv()["Z9_V1MasteryRecord_" .. getgenv().Z9_CurrentMeleeUserId] = getgenv()["Z9_V1MasteryRecord_" .. getgenv().Z9_CurrentMeleeUserId] or {}
local MasteredV1Styles = getgenv()["Z9_MasteredV1Styles_" .. getgenv().Z9_CurrentMeleeUserId]
local V1MasteryRecord = getgenv()["Z9_V1MasteryRecord_" .. getgenv().Z9_CurrentMeleeUserId]

getgenv()["Z9_MasteredV2Styles_" .. getgenv().Z9_CurrentMeleeUserId] = getgenv()["Z9_MasteredV2Styles_" .. getgenv().Z9_CurrentMeleeUserId] or {}
getgenv()["Z9_V2MasteryRecord_" .. getgenv().Z9_CurrentMeleeUserId] = getgenv()["Z9_V2MasteryRecord_" .. getgenv().Z9_CurrentMeleeUserId] or {}
V1StyleLookup.MasteredV2 = getgenv()["Z9_MasteredV2Styles_" .. getgenv().Z9_CurrentMeleeUserId]
V1StyleLookup.RecordsV2 = getgenv()["Z9_V2MasteryRecord_" .. getgenv().Z9_CurrentMeleeUserId]

function V1StyleLookup.IsFullV1Mastered()
    for _, s in ipairs(V1MeleeList) do
        local mas = V1MasteryRecord[s.Name] or 0
        if s.Name == "Dragon Claw" then
            mas = math.max(mas, V1MasteryRecord["Dragon Breath"] or 0, V1MasteryRecord["DragonClaw"] or 0)
            if (V1MasteryRecord["Dragon Breath"] or 0) >= 400 or (V1MasteryRecord["DragonClaw"] or 0) >= 400 then
                MasteredV1Styles["Dragon Claw"] = true
            end
        end
        if not MasteredV1Styles[s.Name] and mas < 400 then
            return false
        end
    end
    return true
end

function V1StyleLookup.IsPreGodhumanMastered()
    if not V1StyleLookup.IsFullV1Mastered() then
        return false
    end
    for _, s in ipairs(V1StyleLookup.V2List) do
        if s.Name ~= "Godhuman" then
            local isOwned = (V1StyleLookup.IsStyleOwned and V1StyleLookup.IsStyleOwned(s.Name))
                or (V1StyleLookup.FindMeleeTool and V1StyleLookup.FindMeleeTool(s.Name) ~= nil)
                or (V1StyleLookup.BoughtStyles and V1StyleLookup.BoughtStyles[s.Name] == true)
                or (getgenv()["Z9_MeleeBought_" .. tostring(s.Name)] == true)
            if not isOwned then
                return false
            end
            local mas = V1StyleLookup.RecordsV2[s.Name] or 0
            if not V1StyleLookup.MasteredV2[s.Name] and mas < 400 then
                return false
            end
        end
    end
    return true
end

function V1StyleLookup.GetActiveTargetStyle()
    -- 1. Nếu chưa full võ V1 (400 Mastery) -> Ưu tiên hoàn thành toàn bộ võ V1 trước
    if (IsSettingBuyMeleeV1() or IsSettingGetItem("Godhuman")) and not V1StyleLookup.IsFullV1Mastered() then
        for _, style in ipairs(V1MeleeList) do
            local mas = V1MasteryRecord[style.Name] or 0
            if style.Name == "Dragon Claw" then
                mas = math.max(mas, V1MasteryRecord["Dragon Breath"] or 0, V1MasteryRecord["DragonClaw"] or 0)
            end
            if CurrentSeaNum >= style.MinSea and not MasteredV1Styles[style.Name] and mas < 400 then
                return style, "V1"
            end
        end
        if not MasteredV1Styles["Electro"] then
            return V1StyleLookup["Electro"], "V1"
        end
    end

    -- 2. NẾU ĐÃ FULL VÕ V1 (400 MASTERY) -> MỞ KHÓA VÀ CÀY MELEE V2 (Superhuman ở Sea 2, Death Step / Sharkman / EClaw / DTalon / Godhuman)
    if V1StyleLookup.IsFullV1Mastered() and (IsSettingBuyMeleeV2() or IsSettingGetItem("Godhuman")) then
        for _, style in ipairs(V1StyleLookup.V2List) do
            local canDoInCurrentSea = (CurrentSeaNum >= (style.MinSea or 2))
            if canDoInCurrentSea then
                if style.Name == "Godhuman" then
                    if IsSettingGetItem("Godhuman") or IsSettingBuyMeleeV2() then
                        local mas = V1StyleLookup.RecordsV2[style.Name] or 0
                        if not V1StyleLookup.MasteredV2[style.Name] and mas < 400 then
                            -- Chỉ trả về Godhuman làm mục tiêu mua trực tiếp nếu đã có trên người HOẶC đã gom đủ 4 nguyên liệu Godhuman
                            local hasGHTool = V1StyleLookup.EquipByName("Godhuman")
                            local hasMats = (type(V1StyleLookup.ItemsSystem) == "table" and type(V1StyleLookup.ItemsSystem.HasAllGodhumanMaterials) == "function" and V1StyleLookup.ItemsSystem.HasAllGodhumanMaterials())
                            if hasGHTool or hasMats then
                                return style, "V2"
                            end
                        end
                    end
                else
                    local mas = V1StyleLookup.RecordsV2[style.Name] or 0
                    if not V1StyleLookup.MasteredV2[style.Name] and mas < 400 then
                        return style, "V2"
                    end
                end
            end
        end
    end

    return nil, nil
end

function V1StyleLookup.GetUnmasteredOwnedMelee()
    -- 1. Ưu tiên tìm trong các võ V2 người chơi đang có trên người hoặc trong balo (< 400 Mastery)
    for _, style in ipairs(V1StyleLookup.V2List) do
        if style.Name ~= "Godhuman" then
            local tool, inHand = V1StyleLookup.FindMeleeTool(style.Name)
            if tool then
                local mas = (tool:FindFirstChild("Level") and tool.Level.Value) or V1StyleLookup.RecordsV2[style.Name] or 0
                if mas < 400 then
                    return tool, style, mas
                end
            end
        end
    end
    -- 2. Kiểm tra tiếp các võ V1 người chơi đang có trên người hoặc trong balo (< 400 Mastery)
    for _, style in ipairs(V1MeleeList) do
        local tool, inHand = V1StyleLookup.FindMeleeTool(style.Name)
        if tool then
            local mas = (tool:FindFirstChild("Level") and tool.Level.Value) or V1MasteryRecord[style.Name] or 0
            if mas < 400 then
                return tool, style, mas
            end
        end
    end
    return nil, nil, nil
end

-- Cơ chế lưu trữ tiến trình võ vào tệp (File Persistence qua các lần Hop Server / Reconnect)
local MeleeStorage = {
    File = "Z9_MeleeMastery_" .. tostring(plr.UserId) .. ".json",
    CachedHasSaber = false,
    LastSaberCheck = 0
}

function MeleeStorage.Save(force)
    local now = tick()
    if not force and (now - (MeleeStorage.LastSaveTick or 0)) < 5.0 then
        return
    end
    MeleeStorage.LastSaveTick = now
    pcall(function()
        if writefile then
            local data = {
                Mastered = MasteredV1Styles or {},
                Records = V1MasteryRecord or {},
                MasteredV2 = V1StyleLookup.MasteredV2 or {},
                RecordsV2 = V1StyleLookup.RecordsV2 or {},
                BoughtStyles = V1StyleLookup.BoughtStyles or {},
                HasSaber = (MeleeStorage.CachedHasSaber == true) or (getgenv()["Z9_HasSaber_" .. tostring(plr.UserId)] == true),
                DeathStepDoorOpened = (V1StyleLookup.ItemsSystem and V1StyleLookup.ItemsSystem.DeathStepDoorOpened == true) or (getgenv().Z9_DeathStepDoorOpened == true),
                SharkmanKeySubmitted = (V1StyleLookup.ItemsSystem and V1StyleLookup.ItemsSystem.SharkmanKeySubmitted == true) or (getgenv().Z9_SharkmanKeySubmitted == true),
                ElectricClawQuestDone = (V1StyleLookup.ItemsSystem and V1StyleLookup.ItemsSystem.ElectricClawQuestDone == true) or (getgenv().Z9_ElectricClawQuestDone == true),
                DragonTalonUnlocked = (V1StyleLookup.ItemsSystem and V1StyleLookup.ItemsSystem.DragonTalonEssenceDone == true) or (getgenv().Z9_DragonTalonUnlocked == true),
                OwnedWeapons = (V1StyleLookup.ItemsSystem and V1StyleLookup.ItemsSystem.CachedOwnedWeapons) or {},
            }
            writefile(MeleeStorage.File, HttpService:JSONEncode(data))
        end
    end)
end

function MeleeStorage.Load()
    pcall(function()
        if isfile and readfile and isfile(MeleeStorage.File) then
            local raw = readfile(MeleeStorage.File)
            if raw and raw ~= "" then
                local data = HttpService:JSONDecode(raw)
                if data and type(data) == "table" then
                    if type(data.OwnedWeapons) == "table" and V1StyleLookup.ItemsSystem then
                        V1StyleLookup.ItemsSystem.CachedOwnedWeapons = V1StyleLookup.ItemsSystem.CachedOwnedWeapons or {}
                        for wName, wData in pairs(data.OwnedWeapons) do
                            V1StyleLookup.ItemsSystem.CachedOwnedWeapons[wName] = wData
                        end
                    end
                    if data.DeathStepDoorOpened == true then
                        getgenv().Z9_DeathStepDoorOpened = true
                        if V1StyleLookup.ItemsSystem then V1StyleLookup.ItemsSystem.DeathStepDoorOpened = true end
                    end
                    if data.SharkmanKeySubmitted == true then
                        getgenv().Z9_SharkmanKeySubmitted = true
                        if V1StyleLookup.ItemsSystem then V1StyleLookup.ItemsSystem.SharkmanKeySubmitted = true end
                    end
                    if data.ElectricClawQuestDone == true then
                        getgenv().Z9_ElectricClawQuestDone = true
                        if V1StyleLookup.ItemsSystem then V1StyleLookup.ItemsSystem.ElectricClawQuestDone = true end
                    end
                    if data.DragonTalonUnlocked == true then
                        local dtOwned = (V1StyleLookup.FindMeleeTool and V1StyleLookup.FindMeleeTool("Dragon Talon") ~= nil)
                            or (V1MasteryRecord and (V1MasteryRecord["Dragon Talon"] or 0) > 0)
                        if dtOwned then
                            getgenv().Z9_DragonTalonUnlocked = true
                            if V1StyleLookup.ItemsSystem then V1StyleLookup.ItemsSystem.DragonTalonEssenceDone = true end
                        end
                    end
                    if type(data.BoughtStyles) == "table" then
                        V1StyleLookup.BoughtStyles = V1StyleLookup.BoughtStyles or {}
                        for k, v in pairs(data.BoughtStyles) do
                            if v == true then
                                V1StyleLookup.BoughtStyles[k] = true
                                getgenv()["Z9_MeleeBought_" .. tostring(k)] = true
                            end
                        end
                    end
                    if data.HasSaber == true then
                        MeleeStorage.CachedHasSaber = true
                        getgenv()["Z9_HasSaber_" .. tostring(plr.UserId)] = true
                    end
                    local pLevel = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0
                    if type(data.Mastered) == "table" then
                        for k, v in pairs(data.Mastered) do
                            if v == true then
                                if pLevel >= 100 then
                                    MasteredV1Styles[k] = true
                                else
                                    local tool = V1StyleLookup.FindMeleeTool(k)
                                    if tool and tool:FindFirstChild("Level") and tool.Level.Value >= 400 then
                                        MasteredV1Styles[k] = true
                                    end
                                end
                            end
                        end
                    end
                    if type(data.Records) == "table" then
                        for k, v in pairs(data.Records) do
                            local n = tonumber(v) or 0
                            if pLevel < 100 then
                                local tool = V1StyleLookup.FindMeleeTool(k)
                                n = (tool and tool:FindFirstChild("Level") and tool.Level.Value) or 0
                            end
                            if n > (V1MasteryRecord[k] or 0) then
                                V1MasteryRecord[k] = n
                            end
                            if n >= 400 and (pLevel >= 100 or (V1StyleLookup.FindMeleeTool(k) and n >= 400)) then
                                MasteredV1Styles[k] = true
                            end
                        end
                    end
                    if type(data.MasteredV2) == "table" then
                        for k, v in pairs(data.MasteredV2) do
                            if v == true and pLevel >= 1500 then
                                V1StyleLookup.MasteredV2[k] = true
                            end
                        end
                    end
                    if type(data.RecordsV2) == "table" then
                        for k, v in pairs(data.RecordsV2) do
                            local n = tonumber(v) or 0
                            if pLevel < 1500 then
                                local tool = V1StyleLookup.FindMeleeTool(k)
                                n = (tool and tool:FindFirstChild("Level") and tool.Level.Value) or 0
                            end
                            if n > (V1StyleLookup.RecordsV2[k] or 0) then
                                V1StyleLookup.RecordsV2[k] = n
                            end
                            if n >= 400 and pLevel >= 1500 then
                                V1StyleLookup.MasteredV2[k] = true
                            end
                        end
                    end
                end
            end
        end
    end)

    -- Làm sạch dữ liệu sai lệch nếu là tài khoản tân thủ (< Lv. 100)
    local pLevel = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0
    if pLevel < 100 then
        local toCleanV1 = {}
        for k, _ in pairs(MasteredV1Styles) do
            local tool = V1StyleLookup.FindMeleeTool(k)
            if not tool or not (tool:FindFirstChild("Level") and tool.Level.Value >= 400) then
                table.insert(toCleanV1, k)
            end
        end
        for _, k in ipairs(toCleanV1) do
            MasteredV1Styles[k] = nil
            V1MasteryRecord[k] = 0
        end
        local toCleanV2 = {}
        for k, _ in pairs(V1StyleLookup.MasteredV2) do
            local tool = V1StyleLookup.FindMeleeTool(k)
            if not tool or not (tool:FindFirstChild("Level") and tool.Level.Value >= 400) then
                table.insert(toCleanV2, k)
            end
        end
        for _, k in ipairs(toCleanV2) do
            V1StyleLookup.MasteredV2[k] = nil
            V1StyleLookup.RecordsV2[k] = 0
        end
        MeleeStorage.Save()
    end
end

-- Tải dữ liệu lưu trữ từ tệp nếu có
MeleeStorage.Load()

-- Quét và đồng bộ mastery thực tế của tất cả vũ khí hiện có trên người
pcall(V1StyleLookup.UpdateAllMasteries)

local AllKnownMelees = {
    ["Combat"] = true,
    ["Black Leg"] = true,
    ["Dark Step"] = true,
    ["Electro"] = true,
    ["Electric"] = true,
    ["Fishman Karate"] = true,
    ["Water Kung-fu"] = true,
    ["Water Kung Fu"] = true,
    ["Dragon Claw"] = true,
    ["Dragon Breath"] = true,
    ["Superhuman"] = true,
    ["Death Step"] = true,
    ["Sharkman Karate"] = true,
    ["Electric Claw"] = true,
    ["Dragon Talon"] = true,
    ["Godhuman"] = true,
    ["Sanguine Art"] = true,
}

function V1StyleLookup.FindMeleeTool(styleName)
    local style = V1StyleLookup[styleName]
    local targets = {}
    if style and style.Aliases then
        for _, a in ipairs(style.Aliases) do
            targets[string.lower(a)] = true
        end
    end
    targets[string.lower(styleName)] = true

    local function matchTool(tool)
        if not tool or not tool:IsA("Tool") then return false end
        local nameLower = string.lower(tool.Name)
        -- Tránh trùng nhầm với võ V2
        if styleName == "Electro" and nameLower:find("claw") then return false end
        if styleName == "Black Leg" and nameLower:find("death") then return false end
        if styleName == "Fishman Karate" and nameLower:find("sharkman") then return false end
        if styleName == "Dragon Claw" and nameLower:find("talon") then return false end

        if targets[nameLower] then return true end
        for alias, _ in pairs(targets) do
            if nameLower:find(alias, 1, true) then return true end
        end
        return false
    end

    local char = plr.Character
    if char then
        for _, t in ipairs(char:GetChildren()) do
            if matchTool(t) then return t, true end
        end
    end
    local bp = plr:FindFirstChild("Backpack")
    if bp then
        for _, t in ipairs(bp:GetChildren()) do
            if matchTool(t) then return t, false end
        end
    end
    return nil, false
end

function V1StyleLookup.IsStyleOwned(styleName)
    if not styleName then return false end
    if V1StyleLookup.FindMeleeTool and V1StyleLookup.FindMeleeTool(styleName) then return true end

    local uid = tostring(getgenv().Z9_CurrentMeleeUserId or (plr and plr.UserId) or "0")
    local m1 = MasteredV1Styles or getgenv()["Z9_MasteredV1Styles_" .. uid] or {}
    local r1 = V1MasteryRecord or getgenv()["Z9_V1MasteryRecord_" .. uid] or {}
    local m2 = (V1StyleLookup and V1StyleLookup.MasteredV2) or getgenv()["Z9_MasteredV2Styles_" .. uid] or {}
    local r2 = (V1StyleLookup and V1StyleLookup.RecordsV2) or getgenv()["Z9_V2MasteryRecord_" .. uid] or {}

    if m1[styleName] == true then return true end
    if (r1[styleName] or 0) > 0 then return true end
    if styleName == "Dragon Claw" and ((r1["Dragon Breath"] or 0) > 0 or (r1["DragonClaw"] or 0) > 0) then return true end
    if m2[styleName] == true then return true end
    if (r2[styleName] or 0) > 0 then return true end

    if V1StyleLookup.BoughtStyles and V1StyleLookup.BoughtStyles[styleName] == true then return true end
    if getgenv()["Z9_MeleeBought_" .. tostring(styleName)] == true then return true end

    -- Quét trong Character và Backpack
    for _, c in ipairs({ plr.Character, plr:FindFirstChild("Backpack") }) do
        if c then
            for _, t in ipairs(c:GetChildren()) do
                if t:IsA("Tool") and (t.Name == styleName or (styleName == "Dragon Claw" and (t.Name == "Dragon Breath" or t.Name == "DragonClaw"))) then
                    return true
                end
            end
        end
    end

    return false
end

function V1StyleLookup.UpdateAllMasteries()
    local containers = { plr.Character, plr:FindFirstChild("Backpack") }
    for _, cont in ipairs(containers) do
        if cont then
            for _, item in ipairs(cont:GetChildren()) do
                if item:IsA("Tool") then
                    local matchedStyle = V1StyleLookup[item.Name]
                    if not matchedStyle then
                        local iNameLower = string.lower(item.Name)
                        for _, s in ipairs(V1MeleeList) do
                            if string.lower(s.Name) == iNameLower then
                                matchedStyle = s
                                break
                            elseif s.Aliases then
                                for _, al in ipairs(s.Aliases) do
                                    if string.lower(al) == iNameLower or iNameLower:find(string.lower(al), 1, true) then
                                        matchedStyle = s
                                        break
                                    end
                                end
                            end
                            if matchedStyle then break end
                        end
                    end
                    if matchedStyle then
                        local mas = (item:FindFirstChild("Level") and item.Level.Value) or 0
                        local isV2 = false
                        for _, v2s in ipairs(V1StyleLookup.V2List) do
                            if v2s.Name == matchedStyle.Name then isV2 = true; break end
                        end

                        if isV2 then
                            local prevMas = V1StyleLookup.RecordsV2[matchedStyle.Name] or 0
                            if mas > prevMas then
                                V1StyleLookup.RecordsV2[matchedStyle.Name] = mas
                            end
                            if (V1StyleLookup.RecordsV2[matchedStyle.Name] or 0) >= 400 then
                                V1StyleLookup.MasteredV2[matchedStyle.Name] = true
                            end
                        else
                            local prevMas = V1MasteryRecord[matchedStyle.Name] or 0
                            if mas > prevMas then
                                V1MasteryRecord[matchedStyle.Name] = mas
                            end
                            if (V1MasteryRecord[matchedStyle.Name] or 0) >= 400 then
                                MasteredV1Styles[matchedStyle.Name] = true
                            end
                        end
                        MeleeStorage.Save()
                    end
                end
            end
        end
    end
end

function V1StyleLookup.EquipByName(meleeName)
    local char = plr.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not char or not hum or hum.Health <= 0 then return false end

    local tool, inHand = V1StyleLookup.FindMeleeTool(meleeName)
    if tool then
        if inHand then return true end
        local currentTool = char:FindFirstChildOfClass("Tool")
        if currentTool then
            hum:UnequipTools()
            task.wait(0.05)
        end
        hum:EquipTool(tool)
        task.wait(0.1)
        return true
    end

    return false
end

function V1StyleLookup.GetNpcCFrame(style)
    if not style then return nil end

    local npcName = style.NpcName
    if workspace:FindFirstChild("NPCs") then
        local wNpc = workspace.NPCs:FindFirstChild(npcName)
        if wNpc then
            return wNpc:GetPivot()
        end
        for _, ch in ipairs(workspace.NPCs:GetChildren()) do
            if ch.Name == npcName or (ch:GetAttribute("DisplayName") == npcName) or ch.Name:find(npcName, 1, true) then
                return ch:GetPivot()
            end
        end
    end

    local okM, npcMgr = pcall(require, ReplicatedStorage:FindFirstChild("NPCManager"))
    if okM and npcMgr and npcMgr.getNPCsByName then
        local list = npcMgr.getNPCsByName(npcName)
        local inst = list and list[1] and list[1]._modelState and list[1]._modelState._instance
        if inst then
            return inst:GetPivot()
        end
    end

    local seaIndex = (World3 and 3) or (World2 and 2) or 1
    if style.Locations and style.Locations[seaIndex] then
        return style.Locations[seaIndex]
    end

    return style.FallbackCF
end

function V1StyleLookup.InteractAndBuy(targetStyle)
    if not targetStyle then return false end
    local char = plr.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum then return false end

    -- Kiểm tra trạng thái Quest của Electro (Blox Fruits Update 20+ yêu cầu Lightning Bolt)
    if targetStyle and targetStyle.Name == "Electro" then
        local remotes = ReplicatedStorage:FindFirstChild("Remotes")
        local commF = remotes and remotes:FindFirstChild("CommF_")
        if not commF then return false end

        local pg = plr:FindFirstChild("PlayerGui")
        local dg = pg and pg:FindFirstChild("DialogueGui")
        local isSys = V1StyleLookup and V1StyleLookup.ItemsSystem

        -- Hàm kiểm tra xem nhân vật đã cầm/có sẵn võ Electro (hoặc Electric) chưa
        local function getOwnedElectroTool()
            local validNames = { "Electro", "Electric" }
            for _, toolName in ipairs(validNames) do
                if (plr.Character and plr.Character:FindFirstChild(toolName))
                    or (plr.Backpack and plr.Backpack:FindFirstChild(toolName)) then
                    return toolName
                end
            end
            return nil
        end

        -- Hàm hỗ trợ trang bị võ an toàn
        local function equipElectro(foundName)
            if not V1StyleLookup or type(V1StyleLookup.EquipByName) ~= "function" then
                return false
            end
            local ok1, res1 = pcall(V1StyleLookup.EquipByName, "Electro")
            if ok1 and res1 then return true end
            if foundName and foundName ~= "Electro" then
                local ok2, res2 = pcall(V1StyleLookup.EquipByName, foundName)
                if ok2 and res2 then return true end
            end
            return false
        end

        -- 1. Nếu đã sở hữu sẵn Electro thì trang bị luôn và báo hoàn thành (true) để dừng TP
        local existingTool = getOwnedElectroTool()
        if existingTool then
            getgenv()._hasLightningBolt = nil
            equipElectro(existingTool)
            return true
        end

        -- 2. Kiểm tra điều kiện đã có Lightning Bolt chưa
        local hasBolt = (plr.Character and plr.Character:FindFirstChild("Lightning Bolt"))
            or (plr.Backpack and plr.Backpack:FindFirstChild("Lightning Bolt"))
            or (getgenv()._hasLightningBolt == true)

        if not hasBolt and isSys and type(isSys.GetCount) == "function" then
            local okCount, count = pcall(isSys.GetCount, "Lightning Bolt")
            if okCount and (tonumber(count) or 0) > 0 then
                hasBolt = true
            end
        end

        if not hasBolt then
            local okState, qState = pcall(function()
                return commF:InvokeServer("ElectroQuestState")
            end)
            if okState and qState == 4 then
                hasBolt = true
                getgenv()._hasLightningBolt = true
            end
        end

        if not hasBolt and dg and dg.Enabled then
            for _, gui in ipairs(dg:GetDescendants()) do
                if gui:IsA("TextLabel") and gui.Visible and gui.Text ~= "" then
                    local t = gui.Text:lower()
                    if t:find("return to the mad scientist") or t:find("you found one") or t:find("retrieved it") then
                        hasBolt = true
                        getgenv()._hasLightningBolt = true
                        break
                    end
                end
            end
        end

        -- 3. Xử lý nộp Lightning Bolt & Mua võ
        if hasBolt then
            pcall(function() commF:InvokeServer("DeliverLightningBolt") end)
            task.wait(0.25)
            pcall(function() commF:InvokeServer("BuyElectro") end)
            task.wait(0.35)

            if dg and dg.Enabled then
                for _, btn in ipairs(dg:GetDescendants()) do
                    if btn:IsA("GuiButton") and btn.Visible then
                        local btnText = btn:IsA("TextButton") and btn.Text or ""
                        local txt = string.lower(btn.Name .. " " .. btnText)
                        if txt:find("option1") or txt:find("buy") or txt:find("learn") or txt:find("yes") then
                            if type(SafeClickGuiButton) == "function" then
                                SafeClickGuiButton(btn)
                            end
                        end
                    end
                end
            end

            pcall(function()
                local dcMod = ReplicatedStorage:FindFirstChild("DialogueController")
                local dc = dcMod and require(dcMod)
                if dc and dc.Active then
                    pcall(dc.advance, dc)
                    pcall(dc.advance, dc)
                    pcall(dc.close, dc)
                end
            end)

            -- Đợi tối đa 2 giây để server cập nhật tool vào Backpack/Character
            local boughtToolName = nil
            for _ = 1, 10 do
                boughtToolName = getOwnedElectroTool()
                if boughtToolName then break end
                task.wait(0.2)
            end

            getgenv()._hasLightningBolt = nil

            if boughtToolName then
                equipElectro(boughtToolName)
                return true
            end

            return false
        else
            -- 4. Chưa có Lightning Bolt -> Đóng hội thoại và đi farm Đám Mây Đen
            pcall(function()
                local dcMod = ReplicatedStorage:FindFirstChild("DialogueController")
                local dc = dcMod and require(dcMod)
                if dc and dc.Active then
                    pcall(dc.close, dc)
                end
            end)
            if dg then dg.Enabled = false end

            if isSys and type(isSys.SecretQuest39) == "table" and type(isSys.SecretQuest39.DoMeleeUnlockStep) == "function" then
                isSys.SecretQuest39.DoMeleeUnlockStep("Electro")
            end
            return false
        end
    end

    -- 1. Bỏ trang bị vũ khí trên tay để tay trống (tránh xung đột khi nhận võ mới)
    pcall(function()
        hum:UnequipTools()
    end)
    task.wait(0.05)

    -- 2. Tìm model NPC trong workspace.NPCs
    local npc = nil
    if workspace:FindFirstChild("NPCs") then
        npc = workspace.NPCs:FindFirstChild(targetStyle.NpcName)
        if not npc then
            for _, ch in ipairs(workspace.NPCs:GetChildren()) do
                if ch.Name == targetStyle.NpcName or (ch:GetAttribute("DisplayName") == targetStyle.NpcName) or ch.Name:find(targetStyle.NpcName, 1, true) then
                    npc = ch
                    break
                end
            end
        end
    end

    -- 3. Kích hoạt ProximityPrompt hoặc ClickDetector trực tiếp trên NPC (nhanh, 0 lag)
    if npc then
        pcall(function()
            local prompt = npc:FindFirstChildWhichIsA("ProximityPrompt", true)
            if prompt then
                prompt.RequiresLineOfSight = false
                prompt.HoldDuration = 0
                if fireproximityprompt then
                    pcall(fireproximityprompt, prompt, 0)
                    pcall(fireproximityprompt, prompt, 1)
                end
            end
            local cd = npc:FindFirstChildWhichIsA("ClickDetector", true)
            if cd and fireclickdetector then
                pcall(fireclickdetector, cd)
            end
        end)
    end

    -- 4. Bật hội thoại qua DialogueCallback nếu có
    pcall(function()
        local okM, NpcList = pcall(require, ReplicatedStorage:FindFirstChild("NPCManager") and ReplicatedStorage.NPCManager:FindFirstChild("NPCList"))
        local item = okM and NpcList and NpcList.List and NpcList.List[targetStyle.NpcName]
        if item and item.DialogueCallback then
            local res = item.DialogueCallback()
            if type(res) == "table" and type(res.Get) == "function" then
                res = res:Get()
            end
            local okD, dc = pcall(require, ReplicatedStorage:FindFirstChild("DialogueController"))
            if okD and dc and dc.start then
                task.spawn(pcall, dc.start, res)
            end
        end
    end)

    -- 5. Gửi Remote mua chuẩn của Blox Fruits (chính xác như BananaCat, bnn, message.txt)
    pcall(function()
        local comm = ReplicatedStorage.Remotes.CommF_
        if targetStyle.Remote == "DragonClaw" then
            comm:InvokeServer("BlackbeardReward", "DragonClaw", "1")
            task.wait(0.2)
            comm:InvokeServer("BlackbeardReward", "DragonClaw", "2")
        else
            -- Blox Fruits chỉ cần duy nhất 1 remote sạch khi đứng gần NPC!
            comm:InvokeServer(targetStyle.Remote)
        end
    end)

    -- 6. Xử lý DialogueController nếu bảng thoại mở
    task.wait(0.2)
    pcall(function()
        local okD, dc = pcall(require, ReplicatedStorage:FindFirstChild("DialogueController"))
        if okD and dc and dc.Active then
            pcall(dc.advance)
            task.wait(0.1)
            local ok, res = pcall(dc.getActiveDialogue)
            local page = ok and res and res._pageStack and res._pageStack[#res._pageStack]
            local opts = page and page._options
            if opts and #opts > 0 then
                local chosen = nil
                for _, opt in ipairs(opts) do
                    local tStr = string.lower(type(opt._text) == "table" and table.concat(opt._text, " ") or tostring(opt._text or ""))
                    if tStr:find("buy") or tStr:find("learn") or tStr:find("yes") or tStr:find("mua") then
                        chosen = opt
                        break
                    end
                end
                pcall(dc.select, chosen or opts[1])
            end
        end
    end)

    -- 7. Xử lý nút click trong DialogueGui nếu giao diện đang hiển thị
    pcall(function()
        local pg = plr:FindFirstChild("PlayerGui")
        local dg = pg and pg:FindFirstChild("DialogueGui")
        if dg and dg.Enabled then
            for _, obj in ipairs(dg:GetDescendants()) do
                if obj:IsA("TextLabel") and obj.Visible then
                    local s = obj.Text:lower()
                    if s:find("lightning bolt") or s:find("dark cloud") or s:find("empty-handed") then
                        pcall(function()
                            local dc = require(ReplicatedStorage.DialogueController)
                            if dc and dc.Active then pcall(dc.close) end
                        end)
                        dg.Enabled = false
                        if type(V1StyleLookup.ItemsSystem) == "table" and type(V1StyleLookup.ItemsSystem.SecretQuest39) == "table" then
                            V1StyleLookup.ItemsSystem.SecretQuest39.DoMeleeUnlockStep("Electro")
                        end
                        break
                    end
                end
            end
            for _, btn in ipairs(dg:GetDescendants()) do
                if btn:IsA("GuiButton") and btn.Visible then
                    local txt = string.lower(btn.Name .. " " .. ((btn:IsA("TextButton") and btn.Text) or ""))
                    if txt:find("option1") or txt:find("buy") or txt:find("learn") or txt:find("yes") then
                        SafeClickGuiButton(btn)
                        if firesignal then
                            pcall(firesignal, btn.MouseButton1Click)
                            pcall(firesignal, btn.Activated)
                        end
                    end
                end
            end
        end
    end)

    -- 8. Đợi server replication và kiểm tra trang bị võ
    task.wait(0.4)
    if V1StyleLookup.EquipByName(targetStyle.Name) then
        return true
    end

    -- Thử lại remote 1 lần nữa phòng khi vừa load xong
    pcall(function()
        if targetStyle.Remote == "DragonClaw" then
            ReplicatedStorage.Remotes.CommF_:InvokeServer("BlackbeardReward", "DragonClaw", "2")
        else
            ReplicatedStorage.Remotes.CommF_:InvokeServer(targetStyle.Remote)
        end
    end)
    task.wait(0.3)
    local okEquipped = V1StyleLookup.EquipByName(targetStyle.Name)
    if not okEquipped and targetStyle.Name == "Electro" then
        getgenv()._ElectroLockedByQuest = true
    end
    return okEquipped
end

local function GetCurrentMeleeTool()
    V1StyleLookup.UpdateAllMasteries()
    local char = plr.Character
    if char then
        for _, item in ipairs(char:GetChildren()) do
            if item:IsA("Tool") and (item.ToolTip == "Melee" or AllKnownMelees[item.Name]) then
                local mas = (item:FindFirstChild("Level") and item.Level.Value) or 0
                return item, item.Name, mas
            end
        end
    end
    local bp = plr:FindFirstChild("Backpack")
    if bp then
        for _, item in ipairs(bp:GetChildren()) do
            if item:IsA("Tool") and (item.ToolTip == "Melee" or AllKnownMelees[item.Name]) then
                local mas = (item:FindFirstChild("Level") and item.Level.Value) or 0
                return item, item.Name, mas
            end
        end
    end
    return nil, "Không rõ", 0
end

local function FormatCostShort(costBeli, costFrag)
    local parts = {}
    if costBeli and costBeli > 0 then
        if costBeli >= 1000000 then
            table.insert(parts, string.format("$%.1fM", costBeli / 1000000):gsub("%.0M", "M"))
        elseif costBeli >= 1000 then
            table.insert(parts, string.format("$%dK", math.floor(costBeli / 1000)))
        else
            table.insert(parts, "$" .. tostring(costBeli))
        end
    end
    if costFrag and costFrag > 0 then
        table.insert(parts, "ƒ" .. FormatNumber(costFrag))
    end
    if #parts > 0 then
        return table.concat(parts, " + ")
    end
    return "Miễn phí"
end

-- ==========================================
-- HỆ THỐNG KIỂM TRA & THEO DÕI KIẾM SABER
-- ==========================================
local function HasSaberSword(forceRefresh)
    local uId = tostring(plr.UserId)
    -- 1. Kiểm tra cache trong getgenv() (tồn tại xuyên suốt phiên thực thi)
    if getgenv()["Z9_HasSaber_" .. uId] == true then
        MeleeStorage.CachedHasSaber = true
        return true
    end
    if MeleeStorage.CachedHasSaber then return true end

    -- 2. Kiểm tra tệp lưu trữ trên máy (Persistence qua Hop Server / Reconnect)
    local saberFile = "Z9_HasSaber_" .. uId .. ".txt"
    pcall(function()
        if isfile and readfile and isfile(saberFile) then
            local c = readfile(saberFile)
            if c and c:find("true") then
                MeleeStorage.CachedHasSaber = true
                getgenv()["Z9_HasSaber_" .. uId] = true
            end
        end
    end)
    if MeleeStorage.CachedHasSaber then return true end

    -- 3. Kiểm tra trực tiếp trên người (Character & Backpack)
    local function checkContainer(container)
        if not container then return false end
        for _, t in ipairs(container:GetChildren()) do
            if t:IsA("Tool") and t.Name:lower():find("saber") then
                return true
            end
        end
        return false
    end
    if checkContainer(plr.Character) or checkContainer(plr.Backpack) then
        MeleeStorage.CachedHasSaber = true
        getgenv()["Z9_HasSaber_" .. uId] = true
        pcall(function() if writefile then writefile(saberFile, "true") end end)
        return true
    end

    -- 4. Kiểm tra trong hệ thống quản lý kho đồ (ItemsSystem / InvMap)
    local isSys = V1StyleLookup and V1StyleLookup.ItemsSystem
    if isSys then
        if type(isSys.InvMap) == "table" then
            for k, _ in pairs(isSys.InvMap) do
                if tostring(k):lower():find("saber") then
                    MeleeStorage.CachedHasSaber = true
                    getgenv()["Z9_HasSaber_" .. uId] = true
                    pcall(function() if writefile then writefile(saberFile, "true") end end)
                    return true
                end
            end
        end
        if type(isSys.GetMastery) == "function" and isSys.GetMastery("Saber") > 0 then
            MeleeStorage.CachedHasSaber = true
            getgenv()["Z9_HasSaber_" .. uId] = true
            pcall(function() if writefile then writefile(saberFile, "true") end end)
            return true
        end
    end

    -- 5. Gọi Remote kiểm tra Kho đồ Blox Fruits (getInventory & getInventoryWeapons)
    if forceRefresh or (tick() - (MeleeStorage.LastSaberCheck or 0) > 4) then
        MeleeStorage.LastSaberCheck = tick()
        local remotesToCheck = { "getInventory", "getInventoryWeapons" }
        for _, rName in ipairs(remotesToCheck) do
            if MeleeStorage.CachedHasSaber then break end
            pcall(function()
                local inv = ReplicatedStorage.Remotes.CommF_:InvokeServer(rName)
                if type(inv) == "table" then
                    for _, it in pairs(inv) do
                        if type(it) == "table" and it.Name and tostring(it.Name):lower():find("saber") then
                            MeleeStorage.CachedHasSaber = true
                            getgenv()["Z9_HasSaber_" .. uId] = true
                            pcall(function() if writefile then writefile(saberFile, "true") end end)
                            if isSys and type(isSys.InvMap) == "table" then
                                isSys.InvMap["Saber"] = isSys.InvMap["Saber"] or { Count = 1, Mastery = tonumber(it.Mastery or it.Level) or 0, Type = "Sword" }
                            end
                            break
                        end
                    end
                end
            end)
        end
    end

    return MeleeStorage.CachedHasSaber == true
end

-- ==========================================
-- HỆ THỐNG KIỂM TRA & THEO DÕI HAKI QUAN SÁT (INSTINCT / KEN HAKI)
-- ==========================================
local LastInstinctCheck = 0

local function HasInstinct()
    local uId = tostring(plr and plr.UserId or 0)
    local instinctKey = "Z9_PurchasedInstinct_" .. uId
    if getgenv()[instinctKey] == true then
        return true
    end

    -- 0. Kiểm tra cấp độ tối thiểu: Ở Sea 1 cần tối thiểu Cấp 300 mới có thể mua Haki Quan Sát (Lord of Destruction)
    local pLevel = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0
    if (World1 or CurrentSeaNum == 1) and pLevel < 300 then
        getgenv()[instinctKey] = false
        return false
    end

    -- 1. Kiểm tra thuộc tính (Attributes) chính thức của nhân vật trong Blox Fruits
    if plr:GetAttribute("KenDodgesLeft") ~= nil or plr:GetAttribute("KenEXP") ~= nil or plr:GetAttribute("Observation") ~= nil or plr:GetAttribute("Dodges") ~= nil then
        getgenv()[instinctKey] = true
        return true
    end
    local char = plr.Character
    if char then
        if char:GetAttribute("KenDodgesLeft") ~= nil or char:GetAttribute("Dodges") ~= nil or (CollectionService and CollectionService:HasTag(char, "Ken")) then
            getgenv()[instinctKey] = true
            return true
        end
    end

    -- 2. Kiểm tra trên UI người chơi (Chỉ quét trong PlayerGui.Main, TUYỆT ĐỐI không quét bừa chữ "E" tránh nhầm với ProximityPrompt)
    local pg = plr:FindFirstChild("PlayerGui")
    local mainGui = pg and pg:FindFirstChild("Main")
    if mainGui then
        for _, name in ipairs({"Ken", "Observation", "Instinct", "ObservationButton"}) do
            local b = mainGui:FindFirstChild(name, true)
            if b and (b:IsA("GuiButton") or b:IsA("ImageButton") or b:IsA("TextButton")) and b.Visible ~= false then
                getgenv()[instinctKey] = true
                return true
            end
        end
    end

    -- 3. Nếu đang ở Sea 2 hoặc Sea 3: Người chơi lên Sea 2 hầu hết đã mua Haki Quan Sát
    if (World2 or World3 or (CurrentSeaNum or 1) >= 2) and pLevel >= 700 then
        getgenv()[instinctKey] = true
        return true
    end

    -- 4. Kiểm tra định kỳ qua Remote KenTalk Status từ Server (chỉ áp dụng ở Sea 1 khi Cấp >= 300)
    if (World1 or CurrentSeaNum == 1) and pLevel >= 300 and tick() - LastInstinctCheck > 10 then
        LastInstinctCheck = tick()
        pcall(function()
            local status = ReplicatedStorage.Remotes.CommF_:InvokeServer("KenTalk", "Status")
            if status ~= nil and status ~= false then
                if type(status) == "number" then
                    getgenv()[instinctKey] = true
                    return
                end
                local statusStr = tostring(status):lower()
                if not statusStr:find("750") and not statusStr:find("saber") and not statusStr:find("learn") and not statusStr:find("teach") then
                    getgenv()[instinctKey] = true
                end
            end
        end)
    end

    return getgenv()[instinctKey] == true
end

-- Bảng theo dõi các kỹ năng đã mua (Air Jump, Aura, Flash Step) cách ly theo UserId
getgenv()["Z9_PurchasedAbilities_" .. tostring(plr and plr.UserId or 0)] = getgenv()["Z9_PurchasedAbilities_" .. tostring(plr and plr.UserId or 0)] or {
    ["Air Jump"] = false,
    ["Aura"] = false,
    ["Flash Step"] = false,
}
local PurchasedAbilities = getgenv()["Z9_PurchasedAbilities_" .. tostring(plr and plr.UserId or 0)]

local function GetAbilitiesStatusText(beli)
    if not (World2 or World3 or CurrentSeaNum >= 2) then
        return "• Chưa lên Sea 2 (Tự động mua khi đến Sea 2)"
    end
    local list = {}
    local abilities = {
        { Name = "Air Jump", TechName = "Geppo", Cost = 10000 },
        { Name = "Aura", TechName = "Buso", Cost = 25000 },
        { Name = "Flash Step", TechName = "Soru", Cost = 100000 },
    }
    for _, ab in ipairs(abilities) do
        if not IsBuyAbilityEnabled(ab.Name) then
            table.insert(list, "• ❌ " .. ab.Name .. ": Tắt")
        elseif PurchasedAbilities[ab.Name] then
            table.insert(list, "• ✅ " .. ab.Name .. " (" .. FormatCostShort(ab.Cost, 0) .. "): Đã sở hữu")
        else
            local status = (beli >= ab.Cost) and "Đủ tiền (Đang mua)" or "Thiếu tiền (" .. FormatCostShort(ab.Cost, 0) .. ")"
            table.insert(list, "• ⬜ " .. ab.Name .. ": " .. status)
        end
    end
    if IsBuyInstinctEnabled() then
        if HasInstinct() then
            table.insert(list, "• ✅ Instinct ($750K): Đã sở hữu")
        elseif not HasSaberSword() then
            table.insert(list, "• ⬜ Instinct ($750K): Cần có Kiếm Saber trước")
        elseif not World2 and not World3 then
            table.insert(list, "• ⬜ Instinct ($750K): Chờ sang Sea 2 mới mua")
        else
            local status = (beli >= 750000) and "Đủ tiền (Đang mua)" or "Thiếu tiền ($750K)"
            table.insert(list, "• ⬜ Instinct ($750K): " .. status)
        end
    end
    return table.concat(list, "\n")
end

local function GetSaberQuestStatusText(lv)
    if not IsSettingGetItem("Saber") then
        return "• Trạng thái: Tắt trong cài đặt"
    end
    if HasSaberSword() then
        return "• Trạng thái: ✅ Đã sở hữu Kiếm Saber"
    end
    if not World1 and CurrentSeaNum > 1 then
        return "• Trạng thái: 🔥 Chưa có Saber -> Đang tự động quay lại Sea 1 để lấy"
    end
    if lv < 200 then
        return "• Trạng thái: Cần đạt Cấp 200+ (Hiện tại: " .. tostring(lv) .. "/200)"
    end
    return "• Trạng thái: 🔥 Đang tự động làm chuỗi nhiệm vụ lấy Saber"
end

local NextRandomFruitTick = 0

local function GetFruitGachaCost(lv)
    return (lv * 500) + 25000
end

local function GetGachaStatusText(lv, beli)
    if not IsSettingFruitRandom() then
        return "Tắt"
    end
    if lv < 50 then
        return "Cần Cấp 50+"
    end
    local cost = GetFruitGachaCost(lv)
    if beli < cost then
        return "Thiếu tiền (" .. FormatCostShort(cost, 0) .. ")"
    end
    if tick() < NextRandomFruitTick then
        local rem = math.ceil((NextRandomFruitTick - tick()) / 60)
        local h = math.floor(rem / 60)
        local m = rem % 60
        if h > 0 then
            return string.format("Chờ %dh %02dm", h, m)
        else
            return string.format("Chờ %d phút", m)
        end
    end
    return "Sẵn sàng (" .. FormatCostShort(cost, 0) .. ")"
end

local function GetV1MeleeStatusText(beli, frags)
    beli = tonumber(beli) or 0
    frags = tonumber(frags) or 0

    local uid = tostring(getgenv().Z9_CurrentMeleeUserId or (plr and plr.UserId) or "0")
    local m1 = MasteredV1Styles or getgenv()["Z9_MasteredV1Styles_" .. uid] or {}
    local r1 = V1MasteryRecord or getgenv()["Z9_V1MasteryRecord_" .. uid] or {}
    local m2 = (V1StyleLookup and V1StyleLookup.MasteredV2) or getgenv()["Z9_MasteredV2Styles_" .. uid] or {}
    local r2 = (V1StyleLookup and V1StyleLookup.RecordsV2) or getgenv()["Z9_V2MasteryRecord_" .. uid] or {}

    local curName = "Không rõ"
    local curMas = 0
    pcall(function()
        local _, cName, cMas = GetCurrentMeleeTool()
        if cName then curName = tostring(cName) end
        if cMas then curMas = tonumber(cMas) or 0 end
    end)

    local lines = {}
    local v1DoneCount = 0
    local pLevel = 0
    pcall(function()
        pLevel = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0
    end)

    local v1List = V1MeleeList or {}
    for _, style in ipairs(v1List) do
        local sName = tostring(style.Name or "Melee")
        local isCurrent = (curName == sName)
        if not isCurrent and style.Aliases then
            for _, al in ipairs(style.Aliases) do
                if al == curName or string.find(string.lower(curName), string.lower(al), 1, true) then
                    isCurrent = true
                    break
                end
            end
        end
        local recMas = isCurrent and curMas or (r1 and r1[sName]) or 0
        if pLevel < 100 and not isCurrent then
            recMas = 0
        end
        if (m1 and m1[sName] and pLevel >= 100) or (recMas >= 400 and (pLevel >= 100 or isCurrent)) then
            v1DoneCount = v1DoneCount + 1
        end
    end
    table.insert(lines, string.format("[I. Võ V1 - %d/%d Môn Đạt 400 Mastery]", v1DoneCount, #v1List))

    for idx, style in ipairs(v1List) do
        local sName = tostring(style.Name or "Melee")
        local isCurrent = (curName == sName)
        if not isCurrent and style.Aliases then
            for _, al in ipairs(style.Aliases) do
                if al == curName or string.find(string.lower(curName), string.lower(al), 1, true) then
                    isCurrent = true
                    break
                end
            end
        end
        local recMas = isCurrent and curMas or (r1 and r1[sName]) or 0
        if pLevel < 100 and not isCurrent then
            recMas = 0
        end
        local costShort = (type(FormatCostShort) == "function" and FormatCostShort(style.CostBeli or 0, style.CostFrag or 0)) or ""
        if (m1 and m1[sName] and pLevel >= 100) or (recMas >= 400 and (pLevel >= 100 or isCurrent)) then
            table.insert(lines, string.format("• %d. %s: Đã Max (400/400)", idx, sName))
        elseif isCurrent then
            table.insert(lines, string.format("• %d. %s: Đang cày (%d/400)", idx, sName, curMas))
        elseif (CurrentSeaNum or 1) < (style.MinSea or 1) then
            table.insert(lines, string.format("• %d. %s (%s): Cần lên Sea %d", idx, sName, costShort, style.MinSea or 1))
        else
            local isOwned = (recMas > 0)
            if not isOwned and V1StyleLookup and type(V1StyleLookup.IsStyleOwned) == "function" then
                pcall(function() isOwned = V1StyleLookup.IsStyleOwned(sName) == true end)
            end
            if isOwned then
                table.insert(lines, string.format("• %d. %s: Đã sở hữu (Mastery: %d/400)", idx, sName, recMas))
            else
                local missing = {}
                local reqBeli = style.CostBeli or 0
                local reqFrag = style.CostFrag or 0
                if beli < reqBeli then table.insert(missing, "Thiếu $" .. FormatNumber(reqBeli - beli)) end
                if frags < reqFrag then table.insert(missing, "Thiếu ƒ" .. FormatNumber(reqFrag - frags)) end
                local state = (#missing == 0) and "Đủ tiền & F (Chờ mua)" or table.concat(missing, ", ")
                table.insert(lines, string.format("• %d. %s (%s): %s", idx, sName, costShort, state))
            end
        end
    end

    local showV2 = false
    pcall(function()
        if (type(IsSettingBuyMeleeV2) == "function" and IsSettingBuyMeleeV2()) or (type(IsSettingGetItem) == "function" and IsSettingGetItem("Godhuman")) then
            showV2 = true
        end
    end)
    if showV2 then
        local v2List = (V1StyleLookup and V1StyleLookup.V2List) or {}
        local v2DoneCount = 0
        for _, style in ipairs(v2List) do
            local sName = tostring(style.Name or "")
            local isCurrent = (curName == sName)
            if not isCurrent and style.Aliases then
                for _, al in ipairs(style.Aliases) do
                    if al == curName or string.find(string.lower(curName), string.lower(al), 1, true) then
                        isCurrent = true; break
                    end
                end
            end
            local recMas = isCurrent and curMas or (r2 and r2[sName]) or 0
            if (m2 and m2[sName]) or recMas >= 400 then
                v2DoneCount = v2DoneCount + 1
            end
        end
        local isFullV1 = false
        if V1StyleLookup and type(V1StyleLookup.IsFullV1Mastered) == "function" then
            pcall(function() isFullV1 = V1StyleLookup.IsFullV1Mastered() == true end)
        end
        local v2ActiveStr = (isFullV1 and (World3 or (CurrentSeaNum or 1) >= 3))
            and "Đang kích hoạt"
            or "Chờ Full Võ V1 & Sea 3"
        table.insert(lines, string.format("\n[II. Võ V2 & Godhuman - %d/%d Môn (%s)]", v2DoneCount, #v2List, v2ActiveStr))

        for idx, style in ipairs(v2List) do
            local sName = tostring(style.Name or "")
            local isCurrent = (curName == sName)
            if not isCurrent and style.Aliases then
                for _, al in ipairs(style.Aliases) do
                    if al == curName or string.find(string.lower(curName), string.lower(al), 1, true) then
                        isCurrent = true; break
                    end
                end
            end
            local recMas = isCurrent and curMas or (r2 and r2[sName]) or 0
            local costShort = (type(FormatCostShort) == "function" and FormatCostShort(style.CostBeli or 0, style.CostFrag or 0)) or ""
            if (m2 and m2[sName]) or recMas >= 400 then
                table.insert(lines, string.format("• %d. %s: Đã Max (400/400)", idx, sName))
            elseif isCurrent then
                table.insert(lines, string.format("• %d. %s: Đang cày (%d/400)", idx, sName, curMas))
            else
                local isOwned = (recMas > 0)
                if not isOwned and V1StyleLookup and type(V1StyleLookup.IsStyleOwned) == "function" then
                    pcall(function() isOwned = V1StyleLookup.IsStyleOwned(sName) == true end)
                end
                if isOwned then
                    table.insert(lines, string.format("• %d. %s: Đã sở hữu (Mastery: %d/400)", idx, sName, recMas))
                else
                    local condStr = ""
                    pcall(function()
                        if sName == "Death Step" then
                            local opened = (getgenv().Z9_DeathStepDoorOpened == true) or (V1StyleLookup and V1StyleLookup.ItemsSystem and V1StyleLookup.ItemsSystem.DeathStepDoorOpened == true)
                            condStr = opened and " | Cửa: Đã mở" or " | Cửa: Chưa mở (Cần Library Key)"
                        elseif sName == "Sharkman Karate" then
                            local submitted = (getgenv().Z9_SharkmanKeySubmitted == true) or (V1StyleLookup and V1StyleLookup.ItemsSystem and V1StyleLookup.ItemsSystem.SharkmanKeySubmitted == true)
                            condStr = submitted and " | Water Key: Đã nộp" or " | Water Key: Chưa nộp"
                        elseif sName == "Electric Claw" then
                            local qDone = (getgenv().Z9_ElectricClawQuestDone == true) or (V1StyleLookup and V1StyleLookup.ItemsSystem and V1StyleLookup.ItemsSystem.ElectricClawQuestDone == true)
                            condStr = qDone and " | Quest 30s: Đã xong" or " | Quest 30s: Chưa làm"
                        elseif sName == "Dragon Talon" then
                            local dtDone = (getgenv().Z9_DragonTalonUnlocked == true) or (V1StyleLookup and V1StyleLookup.ItemsSystem and V1StyleLookup.ItemsSystem.DragonTalonEssenceDone == true)
                            condStr = dtDone and " | Fire Essence: Đã nộp" or " | Fire Essence: Chưa có"
                        elseif sName == "Godhuman" then
                            local isSys = V1StyleLookup and V1StyleLookup.ItemsSystem
                            local ft, ds, mo, md = 0, 0, 0, 0
                            if type(isSys) == "table" and type(isSys.InvMap) == "table" then
                                local e1 = isSys.InvMap["Fish Tail"]
                                local e2 = isSys.InvMap["Dragon Scale"]
                                local e3 = isSys.InvMap["Magma Ore"]
                                local e4 = isSys.InvMap["Mystic Droplet"]
                                ft = (e1 and tonumber(e1.Count)) or 0
                                ds = (e2 and tonumber(e2.Count)) or 0
                                mo = (e3 and tonumber(e3.Count)) or 0
                                md = (e4 and tonumber(e4.Count)) or 0
                            end
                            condStr = string.format(" | NL: FT %d/20, DS %d/10, MO %d/20, MD %d/10", ft, ds, mo, md)
                        end
                    end)

                    local missing = {}
                    local reqBeli = style.CostBeli or 0
                    local reqFrag = style.CostFrag or 0
                    if beli < reqBeli then table.insert(missing, "Thiếu $" .. FormatNumber(reqBeli - beli)) end
                    if frags < reqFrag then table.insert(missing, "Thiếu ƒ" .. FormatNumber(reqFrag - frags)) end
                    local state = (#missing == 0) and "Đủ tiền & F (Chờ mua)" or table.concat(missing, ", ")
                    table.insert(lines, string.format("• %d. %s (%s): %s%s", idx, sName, costShort, state, condStr))
                end
            end
        end
    end

    return #lines > 0 and table.concat(lines, "\n") or "[I. Võ V1]\n• 1. Black Leg: Đang cày (" .. tostring(curName) .. ")\n• 2. Electro: $500K\n• 3. Fishman Karate: $750K\n• 4. Dragon Claw: Sea 2 (ƒ1,500)"
end
-- Hàm kiểm tra phiên bản Race (V1/V2/V3/V4)
local CachedRaceVer = "V1"
local LastRaceCheck = 0
local function GetRaceVersion()
    if tick() - LastRaceCheck < 10 then
        return CachedRaceVer
    end
    LastRaceCheck = tick()
    pcall(function()
        if plr.Character and plr.Character:FindFirstChild("RaceTransformed") then
            CachedRaceVer = "V4"
            return
        end
        local v3 = ReplicatedStorage.Remotes.CommF_:InvokeServer("Wenlocktoad", "1")
        if v3 == -2 then
            CachedRaceVer = "V3"
            return
        end
        local v2 = ReplicatedStorage.Remotes.CommF_:InvokeServer("Alchemist", "1")
        if v2 == -2 then
            CachedRaceVer = "V2"
            return
        end
        CachedRaceVer = "V1"
    end)
    return CachedRaceVer
end

-- ==========================================
-- HỆ THỐNG KIỂM TRA ĐIỀU KIỆN RACE V3 (TREVOR & DON SWAN & ALCHEMIST & AROWE)
-- ==========================================
local function IsBartiloDone()
    if getgenv()._CachedBartiloDone then return true end
    getgenv()._lastBartiloCheck = getgenv()._lastBartiloCheck or 0
    if tick() - getgenv()._lastBartiloCheck < 4 then return getgenv()._CachedBartiloDone == true end
    getgenv()._lastBartiloCheck = tick()

    pcall(function()
        local bProg = ReplicatedStorage.Remotes.CommF_:InvokeServer("BartiloQuestProgress", "Bartilo")
        if bProg == 3 then
            getgenv()._CachedBartiloDone = true
        end
    end)
    return getgenv()._CachedBartiloDone == true
end

local CachedTrevorUnlocked = false
local LastTrevorCheck = 0

local function IsSwanRoomUnlocked()
    if CachedTrevorUnlocked then return true end
    if tick() - LastTrevorCheck < 5 then return CachedTrevorUnlocked end
    LastTrevorCheck = tick()

    pcall(function()
        local tStatus = ReplicatedStorage.Remotes.CommF_:InvokeServer("TalkTrevor", "1")
        if tStatus == 0 then
            CachedTrevorUnlocked = true
            return
        end
        local unlockables = ReplicatedStorage.Remotes.CommF_:InvokeServer("GetUnlockables")
        if unlockables and type(unlockables) == "table" and unlockables.FlamingoAccess ~= nil then
            CachedTrevorUnlocked = true
            return
        end
    end)
    return CachedTrevorUnlocked
end

local LastDonSwanCheck = 0

local function IsDonSwanKilled()
    local uId = tostring(plr and plr.UserId or 0)
    local swanKey = "Z9_DonSwanKilled_" .. uId
    if getgenv()[swanKey] == true then
        return true
    end
    if tick() - LastDonSwanCheck < 5 then return getgenv()[swanKey] == true end
    LastDonSwanCheck = tick()

    pcall(function()
        -- 1. Tiêu chí Race V3: Arowe (Wenlocktoad)
        -- Arowe chỉ trả lời 0 (sẵn sàng làm quest), 1 (đang làm), 2 (hoàn thành chờ 2M), hoặc -2 (đã là V3) khi Don Swan ĐÃ BỊ HẠ!
        local wProg = ReplicatedStorage.Remotes.CommF_:InvokeServer("Wenlocktoad", "1")
        if wProg == 0 or wProg == 1 or wProg == 2 or wProg == -2 then
            getgenv()[swanKey] = true
            return
        end

        -- 2. Kiểm tra phụ kiện rơi từ Don Swan (Swan Glasses) trong túi đồ
        if (plr.Backpack and plr.Backpack:FindFirstChild("Swan Glasses")) or (plr.Character and plr.Character:FindFirstChild("Swan Glasses")) then
            getgenv()[swanKey] = true
            return
        end

        -- 3. Kiểm tra qua ZQuestProgress (Nhiệm vụ Sea 3 King Red Head / rip_indra)
        local zCheck = ReplicatedStorage.Remotes.CommF_:InvokeServer("ZQuestProgress", "Check")
        if zCheck ~= nil and zCheck ~= false then
            getgenv()[swanKey] = true
            return
        end
    end)
    return getgenv()[swanKey] == true
end

