        table.insert(lines, "• Bước 3/4 - Boss Don Swan [Lv. 1000]: " .. (isSwan and "Đã tiêu diệt" or "Chưa tiêu diệt"))

        local zCheck = nil
        pcall(function()
            zCheck = ReplicatedStorage.Remotes.CommF_:InvokeServer("ZQuestProgress", "Check")
        end)
        if zCheck == 1 then
