        elseif zCheck == 0 then
            table.insert(lines, "• Bước 4/4 - Boss rip_indra: Đang chiến đấu tại Đấu Trường...")
        else
            table.insert(lines, "• Bước 4/4 - Boss rip_indra: Chờ hoàn thành Don Swan")
        end
        return table.concat(lines, "\n")
    else
