                local lines = {}
                local rawStatus = tostring(CurrentFarmStatus or "Đang chuẩn bị...")
                local inRaid = (type(V1StyleLookup) == "table" and V1StyleLookup.IsInRaid and V1StyleLookup.IsInRaid()) or (getgenv()._isDoingRaidForF == true)

                -- 1. Hoạt động chính
                local opType = "Auto Farm Cấp Độ"
                if inRaid then
                    local islandIdx = nil
                    if type(V1StyleLookup) == "table" and V1StyleLookup.GetLastRaidIsland then
                        local _, idx = V1StyleLookup.GetLastRaidIsland(plr.Character and plr.Character:FindFirstChild("HumanoidRootPart"))
                        islandIdx = idx
                    end
                    opType = "Auto Raid Kiếm Điểm F (Đảo " .. tostring(islandIdx or "?") .. "/5)"
                elseif CurrentTargetFruit ~= nil then
                    opType = "Nhặt Trái Ác Quỷ Rơi Trên Map"
                elseif rawStatus:find("%[Skull Guitar") then
                    opType = "Nhiệm Vụ Skull Guitar (Đàn Linh Hồn)"
                elseif rawStatus:find("%[Cursed Dual Katana") or rawStatus:find("%[CDK") then
                    opType = "Ghép Kiếm Cursed Dual Katana (CDK)"
                elseif rawStatus:find("%[Godhuman") then
                    opType = "Thu Thập Nguyên Liệu Godhuman"
                elseif rawStatus:find("%[Nhiệm vụ Sea 2") or rawStatus:find("%[Nhiệm vụ Sea 3") then
                    opType = "Chuỗi Nhiệm Vụ Chuyển Thế Giới"
                elseif rawStatus:find("%[Auto Race") then
                    opType = "Nâng Cấp Tộc (Race V2/V3)"
                elseif rawStatus:find("%[Auto Pull Lever") then
                    opType = "Gạt Cần Mở Khóa Tộc V4"
                elseif rawStatus:find("%[Mua Instinct") then
                    opType = "Mua Haki Quan Sát (Instinct)"
                elseif rawStatus:find("lấy/trang bị võ") or rawStatus:find("Mở Khóa Võ") then
                    opType = "Mua & Trang Bị Võ Thuật"
                elseif rawStatus:find("Dough King") or rawStatus:find("Sweet Chalice") or rawStatus:find("Cake Prince") then
                    opType = "Triệu Hồi Dough King (Mirror Fractal)"
                elseif rawStatus:find("Elite") or rawStatus:find("Diablo") or rawStatus:find("Deandre") or rawStatus:find("Urban") then
                    opType = "Săn Boss Elite Pirate (Kiếm Yama)"
                end
                table.insert(lines, "• Hoạt động: " .. opType)
                table.insert(lines, "• Chi tiết: " .. rawStatus)

                -- 2. Mục tiêu ưu tiên tiếp theo
                local goalText = nil
                if type(V1StyleLookup) == "table" and type(V1StyleLookup.GetActiveTargetStyle) == "function" then
                    local actStyle, tier = V1StyleLookup.GetActiveTargetStyle()
                    if actStyle then
                        local reqB = actStyle.CostBeli or 0
                        local reqF = actStyle.CostFrag or 0
                        local bStatus = (curBeli >= reqB) and "Đủ Beli" or ("Thiếu $" .. FormatNumber(reqB - curBeli))
                        local fStatus = (reqF <= 0 or curFrags >= reqF) and "Đủ F" or ("Thiếu ƒ" .. FormatNumber(reqF - curFrags) .. " [Có ƒ" .. FormatNumber(curFrags) .. "/ƒ" .. FormatNumber(reqF) .. "]")
                        local costInfo = ""
                        if reqB > 0 or reqF > 0 then
                            costInfo = " (" .. bStatus .. " | " .. fStatus .. ")"
                        end
                        local dtNotice = ""
                        if actStyle.Name == "Dragon Talon" and type(V1StyleLookup.ItemsSystem) == "table" and V1StyleLookup.ItemsSystem.IsBonesOnCooldown then
                            local isCd, secLeft = V1StyleLookup.ItemsSystem.IsBonesOnCooldown()
                            if isCd and secLeft > 0 then
                                dtNotice = " [Hết lượt quay - Hồi sau " .. tostring(math.ceil(secLeft / 60)) .. "p -> Farm Cấp]"
                            end
                        end
                        goalText = "Võ " .. actStyle.Name .. " [" .. tostring(tier or "V1") .. "]" .. costInfo .. dtNotice
                    end
                end

                if not goalText then
                    if curLv < 700 then
                        goalText = "Đạt Cấp 700 để sang Sea 2 (Còn thiếu " .. tostring(700 - curLv) .. " cấp)"
                    elseif curLv < 1500 and (World2 or CurrentSeaNum == 2) then
                        goalText = "Đạt Cấp 1,500 để sang Sea 3 (Còn thiếu " .. tostring(1500 - curLv) .. " cấp)"
                    elseif curLv < 2550 then
                        goalText = "Cày Cấp 2,550 Max Level (Hiện tại: " .. FormatNumber(curLv) .. "/2,550 - Còn " .. tostring(2550 - curLv) .. " cấp)"
                    else
                        goalText = "Đã đạt Cấp tối đa (2,550) - Hoàn thiện võ & vũ khí"
                    end
                end
                table.insert(lines, "• Mục tiêu: " .. goalText)

                -- 3. Nhiệm vụ hiện tại trong game
                local qTitle = (type(V1StyleLookup) == "table" and V1StyleLookup.GetQuestTitle and V1StyleLookup.GetQuestTitle()) or ""
                local qDesc = (type(V1StyleLookup) == "table" and V1StyleLookup.GetQuestText and V1StyleLookup.GetQuestText()) or ""
                qTitle = qTitle:gsub("^[%s%?|]+", ""):gsub("[%s%?|]+$", ""):match("^%s*(.-)%s*$") or ""
                if #qTitle < 3 or not qTitle:match("%a%a") or qTitle:match("^%?+$") then qTitle = "" end

                local cleanParts = {}
                local seenParts = {}
                if qTitle ~= "" then
                    seenParts[string.lower(qTitle)] = true
                end

                for part in qDesc:gmatch("[^|]+") do
                    local trimmed = part:gsub("^[%s%?|]+", ""):gsub("[%s%?|]+$", ""):match("^%s*(.-)%s*$") or ""
                    local low = string.lower(trimmed)
                    if trimmed ~= "" and trimmed:match("%w") and not trimmed:match("^%?+$") and not seenParts[low] then
                        seenParts[low] = true
                        table.insert(cleanParts, trimmed)
                    end
                end

                if qTitle == "" and #cleanParts > 0 then
                    local titleIdx = 1
                    for idx, cp in ipairs(cleanParts) do
                        if cp:find("Defeat") or cp:find("defeat") then
                            titleIdx = idx
                            break
                        end
                    end
                    qTitle = cleanParts[titleIdx]
                    table.remove(cleanParts, titleIdx)
                end

                if qTitle ~= "" then
                    local remaining = table.concat(cleanParts, " | ")
                    local qProg = (remaining ~= "") and (" (" .. remaining .. ")") or ""
                    table.insert(lines, "• Nhiệm vụ: " .. qTitle .. qProg)
                elseif #cleanParts > 0 then
                    table.insert(lines, "• Nhiệm vụ: " .. table.concat(cleanParts, " | "))
                end

                -- 4. Vũ khí và Mastery
                local isStatsInMelee = false
                pcall(function()
                    local data = plr:FindFirstChild("Data")
                    local statsFolder = data and data:FindFirstChild("Stats")
                    if statsFolder then
                        local swLv = GetStatCurrentLevel(statsFolder, "Sword")
                        local melLv = GetStatCurrentLevel(statsFolder, "Melee")
                        if melLv >= 800 and swLv < melLv * 0.5 then
                            isStatsInMelee = true
                        end
                    end
                end)

                local targetSw = getgenv()._targetSwordName
                if inRaid or isStatsInMelee then
                    targetSw = nil
                end
                if targetSw and targetSw ~= "" then
                    local swMas = (isSys and isSys.GetMastery and isSys.GetMastery(targetSw)) or 0
                    local reqMas = (targetSw == "Yama" or targetSw == "Tushita") and 350
                        or (targetSw == "True Triple Katana" and 350
                        or (targetSw == "Skull Guitar" and 300 or 350))
                    local masTarget = (swMas >= reqMas) and ("Đã Max " .. tostring(reqMas)) or ("Còn thiếu " .. tostring(reqMas - swMas) .. " Mas nữa để đạt " .. tostring(reqMas))
                    table.insert(lines, "• Vũ khí đang dùng: Kiếm " .. targetSw .. " (Mastery: " .. tostring(swMas) .. "/" .. tostring(reqMas) .. " - " .. masTarget .. ")")
                else
                    local mStr = tostring(mName or "Chưa trang bị")
                    if mMas and tonumber(mMas) then
                        local masNum = tonumber(mMas)
                        local masTarget = (masNum >= 400) and "Đã Max 400" or ("Còn thiếu " .. tostring(400 - masNum) .. " Mas nữa để đạt 400")
                        mStr = mStr .. " (Mastery: " .. tostring(masNum) .. "/400 - " .. masTarget .. ")"
                    end
                    table.insert(lines, "• Vũ khí đang dùng: " .. mStr)
                end

                return table.concat(lines, "\n")
            end

            task.spawn(function()
                pcall(function()
                    if FarmStatusPara then
                        FarmStatusPara:SetDesc(BuildDetailedFarmStatus(lv, beli, frags, meleeName, meleeMas))
                    end
                end)
            end)

            task.spawn(function()
                pcall(function()
                    local t = HW.GetStatusText()
                    if t and HalloweenStatusPara then HalloweenStatusPara:SetDesc(t) end
                end)
            end)

            task.spawn(function()
                pcall(function()
                    if PlayerStatsPara then
                        PlayerStatsPara:SetDesc(
                            "• Thế giới: " .. seaLabel .. " | Cấp độ: " .. FormatNumber(lv) .. "/2,550 | Vàng: $" .. FormatNumber(beli) .. " | Điểm F: ƒ" .. FormatNumber(frags) ..
                            "\n• Tộc: " .. tostring(race) .. " [" .. GetRaceVersion() .. "] | Võ đang cầm: " .. tostring(meleeName) .. " (Mastery: " .. tostring(meleeMas) .. "/400)" ..
                            "\n• Trái Ác Quỷ: " .. fruitText .. " | Gacha: " .. GetGachaStatusText(lv, beli) ..
                            "\n• Chỉ số: Melee (" .. tostring(meleeLv) .. "/2550) | Defense (" .. tostring(defLv) .. "/2550) | Điểm dư: " .. tostring(statPts) ..
                            "\n• Phụ kiện: " .. tostring(accStatus) .. " | Code X2 EXP: " .. expStatus ..
                            "\n• Ping Server: " .. tostring(curPing) .. "ms (Auto Hop: " .. hopDesc .. ")"
                        )
                    end
                end)
            end)

            task.spawn(function()
                pcall(function()
                    local t = GetRaceQuestDetailText(lv, beli)
                    if type(isSys) == "table" then
                        local leverLine = ""
                        if not isSys.IsFarmLeverEnabled() then
                            leverLine = "\n• Gạt Cần V4 (Farm Lever): 🔴 Tắt"
                        elseif isSys.LeverPulledDone or isSys.TempleDoorOpened then
                            leverLine = "\n• Gạt Cần V4 (Farm Lever): ✅ Đã mở khóa Cần Gạt Temple of Time"
                        elseif isSys.HasItem("Mirror Fractal") and isSys.HasItem("Valkyrie Helm") then
                            leverLine = "\n• Gạt Cần V4 (Farm Lever): 🔥 Đủ Mirror Fractal & Mũ Valkyrie (Chờ Đảo Mirage lấy Blue Gear)"
                        else
                            local mf = isSys.HasItem("Mirror Fractal") and "✅" or "⬜"
                            local vh = isSys.HasItem("Valkyrie Helm") and "✅" or "⬜"
                            leverLine = "\n• Gạt Cần V4 (Farm Lever): ⏳ Cần Mirror Fractal " .. mf .. " & Valkyrie Helm " .. vh
                        end
                        local ghoulStr = (isSys.GhoulUnlocked or tostring(race) == "Ghoul") and "✅ Đã mở khóa" or (isSys.HasToolOnPlayer("Hellfire Torch") and "🔥 Có Hellfire Torch" or "⏳ Chờ Cursed Captain")
                        local cyborgStr = (isSys.CyborgUnlocked or tostring(race) == "Cyborg") and "✅ Đã mở khóa" or (isSys.HasToolOnPlayer("Core Brain") and "🔥 Có Core Brain" or (isSys.CyborgFistInserted and "⏳ Đã nạp Fist (Săn Order)" or "⏳ Cần Fist + Core Brain"))
                        local hiddenRaceLine = "\n• Tộc Ẩn Sea 2: Ghoul (" .. ghoulStr .. ") | Cyborg (" .. cyborgStr .. ")"
                        t = (t or "") .. leverLine .. hiddenRaceLine
                    end
                    if t and RaceStatusPara then RaceStatusPara:SetDesc(t) end
                end)
            end)

            pcall(function()
                local bs = getgenv().Z9_BerrySystem
                if BerryStatusPara and type(bs) == "table" and type(bs.GetStatusText) == "function" then
                    BerryStatusPara:SetDesc(bs.GetStatusText())
                end
            end)

            task.spawn(function()
                pcall(function()
                    if not MeleeV1Para then return end
                    local ok, t = pcall(GetV1MeleeStatusText, beli, frags)
                    if ok and type(t) == "string" and t ~= "" then
                        MeleeV1Para:SetDesc(t)
                    else
                        local curM = tostring(meleeName or "Chưa trang bị")
                        MeleeV1Para:SetDesc(string.format("[I. Võ V1 - 4 Môn Cơ Bản]\n• Đang đồng bộ tiến trình võ... (Hiện cầm: %s)", curM))
                    end
                end)
            end)

            task.spawn(function()
                pcall(function()
                    local t = GetSea3QuestStatusText(lv)
                    if t and Sea3StatusPara then Sea3StatusPara:SetDesc(t) end
                end)
            end)

            pcall(function()
                if getgenv().Z9_GetItemsPara and type(isSys) == "table" and type(isSys.GetStatusText) == "function" then
                    getgenv().Z9_GetItemsPara:SetDesc(isSys.GetStatusText(lv, beli, frags))
                end
            end)

            pcall(function() if CompletedQuestsPara then CompletedQuestsPara:SetDesc(GetCombinedCompletedQuestsText()) end end)
        end)
    end
end)

-- ==========================================
-- HỆ THỐNG TWEEN CHỐNG GIẬT LÙI (ANTI-RUBBERBAND) & NOCLIP
-- ==========================================
local TpTagUntil = 0
local HasTpTag = false

local function RefreshTeleportTag()
    TpTagUntil = tick() + 1.5
    if not CollectionService:HasTag(plr, "Teleporting") then
        pcall(function()
            CollectionService:AddTag(plr, "Teleporting")
        end)
    end
    local char = plr.Character
    if char and not CollectionService:HasTag(char, "Teleporting") then
        pcall(function()
            CollectionService:AddTag(char, "Teleporting")
        end)
    end
    HasTpTag = true
end

task.spawn(function()
    while task.wait(0.1) do
        if HasTpTag and tick() >= TpTagUntil then
            pcall(function()
                CollectionService:RemoveTag(plr, "Teleporting")
            end)
            local char = plr.Character
            if char then
                pcall(function()
                    CollectionService:RemoveTag(char, "Teleporting")
                end)
            end
            HasTpTag = false
        end
    end
end)

local TweenState = {
    ActiveThread = nil,
    GoalCFrame = nil,
    Running = false,
    CancelFlag = false,
    SpeedCap = 350,
    NextRaise = 0,
}

local function EnsureFloatForce(hrp)
    if not hrp then return end
    local bv = hrp:FindFirstChild("Z9_BodyClip")
    if not bv then
        bv = Instance.new("BodyVelocity")
        bv.Name = "Z9_BodyClip"
        bv.MaxForce = Vector3.new(0, 100000, 0)
        bv.Velocity = Vector3.zero
        bv.P = 10000
        bv.Parent = hrp
    else
        bv.MaxForce = Vector3.new(0, 100000, 0)
    end
end

getgenv().StopTween = function()
    TweenState.CancelFlag = true
    TweenState.Running = false
    TweenState.GoalCFrame = nil
    if TweenState.ActiveThread and coroutine.status(TweenState.ActiveThread) == "suspended" then
        pcall(coroutine.close, TweenState.ActiveThread)
    end
    TweenState.ActiveThread = nil

    local char = plr.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if hrp and hrp:FindFirstChild("Z9_BodyClip") then
        hrp.Z9_BodyClip:Destroy()
    end
end

RunService.Stepped:Connect(function()
    if IsAutoFarmActive() then
        local char = plr.Character
        if char then
            for _, part in ipairs(char:GetDescendants()) do
                if part:IsA("BasePart") and part.CanCollide then
                    part.CanCollide = false
                end
            end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp then
                EnsureFloatForce(hrp)
            end
        end
    end
end)

local function HandlePortalGate(entranceVector, touchTargets, conditionCheck)
    if getgenv().StopTween then getgenv().StopTween() end
    local char = plr.Character
    local curHrp = char and char:FindFirstChild("HumanoidRootPart")
    if not curHrp then return false end

    -- Tạm thời hủy FloatForce và triệt tiêu vận tốc để chạm trigger cổng
    local ff = curHrp:FindFirstChild("Z9_FloatForce")
    if ff then ff:Destroy() end
    curHrp.AssemblyLinearVelocity = Vector3.zero
    curHrp.AssemblyAngularVelocity = Vector3.zero

    -- Gửi remote chính thức của game Blox Fruits để yêu cầu mở cổng
    pcall(function()
        ReplicatedStorage.Remotes.CommF_:InvokeServer("requestEntrance", entranceVector)
    end)

    local targetList = type(touchTargets) == "table" and touchTargets or { touchTargets }

    for _, targetCF in ipairs(targetList) do
        if typeof(targetCF) == "CFrame" then
            curHrp.CFrame = targetCF
            curHrp.AssemblyLinearVelocity = Vector3.zero
        end

        local stepStart = tick()
        while tick() - stepStart < 0.8 do
            task.wait(0.15)
            local c = plr.Character
            local h = c and c:FindFirstChild("HumanoidRootPart")
            if h and conditionCheck(h) then
                EnsureFloatForce(h)
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("SetSpawnPoint")
                end)
                return true
            end
        end

        pcall(function()
            ReplicatedStorage.Remotes.CommF_:InvokeServer("requestEntrance", entranceVector)
        end)
    end

    return false
end

local function TweenTo(targetCFrame)
    if typeof(targetCFrame) ~= "CFrame" then return end
    local char = plr.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum or hum.Health <= 0 then return end

    if hum.Sit then
        hum.Sit = false
        hum.Jump = true
    end

    EnsureFloatForce(hrp)

    -- Cổng dịch chuyển thông minh cho các đảo tách biệt (Underwater City, Upper Skylands, Cursed Ship)
    if World1 then
        -- Vị trí xoáy nước biển ngoài khơi (lệch sang phải bến tàu khoảng 35 studs trực tiếp vào tâm nước xoáy)
        local whirlpoolGate = CFrame.new(3895.0, 2.0, -1920.0)
        local fishmanExit = CFrame.new(61163.8203, 4.953, 1821.621)

        -- 1. Vào Đảo Người Cá (Underwater City) khi đang ở ngoài biển Sea 1:
        if hrp.Position.X < 50000 and targetCFrame.Position.X > 50000 then
            local distToWhirlpool = (hrp.Position - whirlpoolGate.Position).Magnitude
            if distToWhirlpool > 40 then
                targetCFrame = whirlpoolGate * CFrame.new(0, 15, 0)
            else
                CurrentFarmStatus = "Đang đi vào xoáy nước cổng Đảo Người Cá..."
                local whirlpoolTargets = {
                    CFrame.new(3895.0, 1.5, -1920.0), -- Lệch sang phải bến tàu vào mặt nước xoáy
                    CFrame.new(3910.0, 1.5, -1930.0), -- Tâm xoáy nước
                    CFrame.new(3890.0, 1.5, -1895.0), -- Góc nước xoáy
                    CFrame.new(3920.0, 1.0, -1915.0), -- Vùng trũng xoáy nước
                    CFrame.new(3875.0, 1.5, -1935.0),
                }
                -- Quét tìm Part xoáy nước trong Map.TeleportSpawn nếu có (không quét toàn bộ workspace gây lag)
                pcall(function()
                    local map = workspace:FindFirstChild("Map")
                    local tpSpawn = map and map:FindFirstChild("TeleportSpawn")
                    if tpSpawn then
                        for _, obj in ipairs(tpSpawn:GetDescendants()) do
                            if obj:IsA("BasePart") and (obj.Position - whirlpoolGate.Position).Magnitude <= 80 then
                                table.insert(whirlpoolTargets, 1, obj.CFrame * CFrame.new(0, 1.5, 0))
                                break
                            end
                        end
                    end
                end)
                HandlePortalGate(
                    Vector3.new(61163.8515625, 11.6796875, 1819.7841796875),
                    whirlpoolTargets,
                    function(h) return h.Position.X > 50000 end
                )
                return
            end
        -- 2. Rời khỏi Đảo Người Cá (Underwater City) ra lại biển Sea 1:
        elseif hrp.Position.X > 50000 and targetCFrame.Position.X < 50000 then
            local distToExit = (hrp.Position - fishmanExit.Position).Magnitude
            if distToExit > 30 then
                targetCFrame = fishmanExit * CFrame.new(0, 10, 0)
            else
                CurrentFarmStatus = "Đang rời Đảo Người Cá ra biển Sea 1..."
                HandlePortalGate(
                    Vector3.new(3864.6884765625, 6.736946105957, -1926.2141113281),
                    CFrame.new(61163.8203, 4.953, 1821.621),
                    function(h) return h.Position.X < 50000 end
                )
                return
            end
        end

        -- 3. Hỗ trợ dịch chuyển tức thì lên / xuống Upper Skylands (Sea 1) qua requestEntrance như bnn.lua
        if hrp.Position.Y < 3000 and targetCFrame.Position.Y > 4000 then
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("requestEntrance", Vector3.new(-7894.6201171875, 5545.49169921875, -380.2467346191406))
            end)
        elseif hrp.Position.Y > 4000 and targetCFrame.Position.Y < 3000 then
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("requestEntrance", Vector3.new(-4607.82275390625, 872.5422973632812, -1667.556884765625))
            end)
        end
    elseif World2 then
        local cursedShipDock = CFrame.new(-6508.558, 89.034, -132.839)
        local cursedShipInterior = CFrame.new(923.212, 126.976, 32852.832)

        -- Vào Cursed Ship từ Sea 2:
        if hrp.Position.Z < 25000 and targetCFrame.Position.Z > 25000 then
            local distToDock = (hrp.Position - cursedShipDock.Position).Magnitude
            if distToDock > 35 then
                targetCFrame = cursedShipDock * CFrame.new(0, 15, 0)
            else
                CurrentFarmStatus = "Đang đi vào Cursed Ship..."
                HandlePortalGate(
                    Vector3.new(923.21252441406, 126.9760055542, 32852.83203125),
                    CFrame.new(-6508.5581054688, 89.034996032715, -132.83953857422),
                    function(h) return h.Position.Z > 25000 end
                )
                return
            end
        -- Rời khỏi Cursed Ship ra lại Sea 2:
        elseif hrp.Position.Z > 25000 and targetCFrame.Position.Z < 25000 then
            local distToExitShip = (hrp.Position - cursedShipInterior.Position).Magnitude
            if distToExitShip > 35 then
                targetCFrame = cursedShipInterior * CFrame.new(0, 15, 0)
            else
                CurrentFarmStatus = "Đang rời Cursed Ship ra ngoài Sea 2..."
                HandlePortalGate(
                    Vector3.new(-6508.5581054688, 89.034996032715, -132.83953857422),
                    CFrame.new(923.21252441406, 126.9760055542, 32852.83203125),
                    function(h) return h.Position.Z < 25000 end
                )
                return
            end
        end
    end

    local dist = (targetCFrame.Position - hrp.Position).Magnitude

    -- Nếu đã ở rất gần mục tiêu thì đặt vị trí trực tiếp
    if dist <= 15 then
        TweenState.CancelFlag = true
        TweenState.Running = false
        TweenState.GoalCFrame = nil
        RefreshTeleportTag()
        hrp.CFrame = targetCFrame
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
        return
    end

    -- Cập nhật mục tiêu mới mà không hủy/tạo lại luồng di chuyển nếu luồng đang chạy
    TweenState.GoalCFrame = targetCFrame
    if TweenState.Running and TweenState.ActiveThread and coroutine.status(TweenState.ActiveThread) ~= "dead" then
        return
    end

    TweenState.CancelFlag = false
    TweenState.Running = true

    local moveThread
    moveThread = coroutine.create(function()
        local virtualPos = hrp.Position
        local bestDist = math.huge
        local lastProgressTick = tick()
        local rubberbandCheck = true
        local prevVirtualPos = nil
        local prevActualDist = nil

        while not TweenState.CancelFlag and TweenState.GoalCFrame do
            local curChar = plr.Character
            local curHrp = curChar and curChar:FindFirstChild("HumanoidRootPart")
            local curHum = curChar and curChar:FindFirstChildOfClass("Humanoid")
            if not curHrp or not curHum or curHum.Health <= 0 or curHrp.Anchored then
                break
            end

            local goalCF = TweenState.GoalCFrame
            local goalPos = goalCF.Position
            if (goalPos - virtualPos).Magnitude <= 3 then
                curHrp.CFrame = goalCF
                curHrp.AssemblyLinearVelocity = Vector3.zero
                curHrp.AssemblyAngularVelocity = Vector3.zero
                break
            end

            local dt = RunService.Heartbeat:Wait()
            if TweenState.CancelFlag or not TweenState.GoalCFrame then break end

            goalCF = TweenState.GoalCFrame
            goalPos = goalCF.Position
            local actualPos = curHrp.Position
            local actualDist = (goalPos - actualPos).Magnitude

            if actualDist < bestDist - 5 then
                bestDist = actualDist
                lastProgressTick = tick()
            elseif tick() - lastProgressTick > 2.5 then
                rubberbandCheck = false
            end

            -- Phát hiện khi bị Server kéo giật lùi (Rubber-band) -> Đồng bộ lại vị trí thật và giảm tốc mượt
            if rubberbandCheck and prevVirtualPos and prevActualDist and actualDist > prevActualDist + 40 then
                TweenState.SpeedCap = math.max(TweenState.SpeedCap * 0.7, 120)
                TweenState.NextRaise = tick() + 3
                virtualPos = actualPos
            elseif rubberbandCheck and prevVirtualPos and (actualPos - prevVirtualPos).Magnitude > 40 then
                virtualPos = actualPos
            end

            local maxSpeed = GetSettingTweenSpeed()
            local vec = goalPos - virtualPos
            local remDist = vec.Magnitude
            local step = math.min(maxSpeed, TweenState.SpeedCap) * dt

            if remDist > step and tick() >= TweenState.NextRaise then
                TweenState.SpeedCap = math.min(TweenState.SpeedCap * 1.08, maxSpeed)
                TweenState.NextRaise = tick() + 1.5
            end

            if remDist <= step or remDist <= 0.05 then
                virtualPos = goalPos
            else
                virtualPos = virtualPos + (vec / remDist) * step
            end

            RefreshTeleportTag()
            EnsureFloatForce(curHrp)
            curHrp.CFrame = CFrame.new(virtualPos) * goalCF.Rotation
            curHrp.AssemblyLinearVelocity = Vector3.zero
            curHrp.AssemblyAngularVelocity = Vector3.zero

            prevVirtualPos = virtualPos
            prevActualDist = actualDist
        end

        if TweenState.ActiveThread == moveThread then
            TweenState.Running = false
            TweenState.ActiveThread = nil
        end
    end)

    TweenState.ActiveThread = moveThread
    coroutine.resume(moveThread)
end

-- ==========================================
-- HỆ THỐNG VŨ KHÍ, HAKI, GOM QUÁI & FAST ATTACK (CẬP NHẬT MỚI)
-- ==========================================
function V1StyleLookup.EnsureSwordEquipped(swordName)
    if not swordName or swordName == "" then return false end
    local char = plr.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not char or not hum or hum.Health <= 0 then return false end

    -- 1. Nếu đang cầm trên tay đúng kiếm/súng mục tiêu -> Giữ nguyên, không làm gì cả
    local currentTool = char:FindFirstChildOfClass("Tool")
    if currentTool and currentTool.Name == swordName then
        return true
    end

    -- 2. Đang có trong Character -> Equip ngay
    local inChar = char:FindFirstChild(swordName)
    if inChar and inChar:IsA("Tool") then
        hum:EquipTool(inChar)
        return true
    end

    -- 3. Đang có trong Backpack -> Unequip vũ khí cũ và Equip kiếm, tuyệt đối KHÔNG gọi LoadItem
    -- (Trong Blox Fruits LoadItem là lệnh TOGGLE: gọi khi tool đã có trong Backpack sẽ cất kiếm ngược vào tủ đồ/rương!)
    local inBp = plr.Backpack and plr.Backpack:FindFirstChild(swordName)
    if inBp and inBp:IsA("Tool") then
        if currentTool then hum:UnequipTools() end
        hum:EquipTool(inBp)
        return true
    end

    -- 4. Kiếm THỰC SỰ chưa có trên người (đang cất trong tủ đồ/kho đồ):
    -- Chỉ gọi LoadItem duy nhất 1 lần (debounce 8 giây) để game nạp kiếm từ tủ đồ vào Backpack
    local now = tick()
    getgenv()._lastSwLoadAttempt = getgenv()._lastSwLoadAttempt or {}
    if (now - (getgenv()._lastSwLoadAttempt[swordName] or 0)) >= 8.0 then
        getgenv()._lastSwLoadAttempt[swordName] = now
        pcall(function()
            ReplicatedStorage.Remotes.CommF_:InvokeServer("LoadItem", swordName)
        end)
        task.delay(0.25, function()
            pcall(function()
                local t = plr.Backpack and plr.Backpack:FindFirstChild(swordName)
                if t and plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") then
                    local c = plr.Character:FindFirstChildOfClass("Tool")
                    if c then plr.Character.Humanoid:UnequipTools() end
                    plr.Character.Humanoid:EquipTool(t)
                end
            end)
        end)
    end
    return false
end

function V1StyleLookup.SyncTargetWeaponPriority()
    -- Nếu đang trong Raid hoặc đang đi Raid kiếm F -> Không chọn Kiếm/Súng để tập trung dùng Melee clear raid siêu nhanh!
    local inRaid = (getgenv()._isDoingRaidForF == true)
        or (type(V1StyleLookup) == "table" and V1StyleLookup.IsInRaid and V1StyleLookup.IsInRaid())
    if inRaid then
        if getgenv()._targetSwordName == "Yama" or getgenv()._targetSwordName == "Tushita" then
            getgenv()._targetSwordName = nil
            SetSettingWeapon("Melee")
        end
        return nil
    end

    -- Nếu Stats hiện tại đang dồn ở Melee & Máu (Kiếm chưa có điểm stat) -> Không chuyển sang Kiếm, tiếp tục dùng Melee farm cho nhanh!
    local isStatsInMelee = false
    pcall(function()
        local data = plr:FindFirstChild("Data")
        local statsFolder = data and data:FindFirstChild("Stats")
        if statsFolder then
            local swLv = GetStatCurrentLevel(statsFolder, "Sword")
            local melLv = GetStatCurrentLevel(statsFolder, "Melee")
            if melLv >= 800 and swLv < melLv * 0.5 then
                isStatsInMelee = true
            end
        end
    end)
    if isStatsInMelee then
        if getgenv()._targetSwordName == "Yama" or getgenv()._targetSwordName == "Tushita" then
            getgenv()._targetSwordName = nil
            SetSettingWeapon("Melee")
        end
        return nil
    end

    -- Khi toàn bộ võ V2 chưa đạt 400 Mastery -> Tuyệt đối không chọn Yama/Tushita, TRỪ KHI:
    -- Võ V2 mục tiêu là Dragon Talon chưa sở hữu (đang chờ Fire Essence / hồi lượt quay xương)
    -- VÀ toàn bộ các võ Melee người chơi đang có đều đã đạt >= 400 Mastery!
    local isPreGhDone = (type(V1StyleLookup.IsPreGodhumanMastered) == "function" and V1StyleLookup.IsPreGodhumanMastered())
    local targetStyle = type(V1StyleLookup) == "table" and type(V1StyleLookup.GetActiveTargetStyle) == "function" and V1StyleLookup.GetActiveTargetStyle()
    local isWaitingDT = (targetStyle and targetStyle.Name == "Dragon Talon" and not V1StyleLookup.FindMeleeTool("Dragon Talon"))
    local unmasteredMelee = (type(V1StyleLookup) == "table" and type(V1StyleLookup.GetUnmasteredOwnedMelee) == "function" and V1StyleLookup.GetUnmasteredOwnedMelee())
    local allowSwordTraining = isPreGhDone or (isWaitingDT and not unmasteredMelee)

    if not allowSwordTraining then
        if getgenv()._targetSwordName == "Yama" or getgenv()._targetSwordName == "Tushita" then
            getgenv()._targetSwordName = nil
            SetSettingWeapon("Melee")
        end
    end

    if getgenv()._targetSwordName and getgenv()._targetSwordName ~= "" then
        return getgenv()._targetSwordName
    end
    if type(V1StyleLookup) ~= "table" or type(V1StyleLookup.ItemsSystem) ~= "table" then
        return nil
    end
    local isSys = V1StyleLookup.ItemsSystem

    -- 1. ƯU TIÊN SONG KIẾM ODEN (CDK): Yama 350 Mas & Tushita 350 Mas
    -- CHỈ KÍCH HOẠT KHI TẤT CẢ VÕ V2 ĐÃ ĐẠT 400 MASTERY (hoặc đang chờ Dragon Talon và đã max hết võ đang có)!
    if allowSwordTraining and (IsSettingGetItem("Cursed Dual Katana") or IsSettingGetItem("Yama") or IsSettingGetItem("Tushita")) and (World3 or CurrentSeaNum == 3) and not isSys.HasItem("Cursed Dual Katana") then
        local hasYama = isSys.HasItem("Yama")
        local yamaMas = isSys.GetMastery("Yama")
        local hasTushita = isSys.HasItem("Tushita")
        local tushitaMas = isSys.GetMastery("Tushita")
        if hasYama and yamaMas < 350 then
            getgenv()._targetSwordName = "Yama"
            SetSettingWeapon("Sword")
            V1StyleLookup.EnsureSwordEquipped("Yama")
            return "Yama"
        elseif hasTushita and tushitaMas < 350 then
            getgenv()._targetSwordName = "Tushita"
            SetSettingWeapon("Sword")
            V1StyleLookup.EnsureSwordEquipped("Tushita")
            return "Tushita"
        end
    end

    -- 2. ƯU TIÊN TRUE TRIPLE KATANA (TTK): Shisui, Wando, Saddi 300 Mas
    if isSys.IsTTKEnabled and isSys.IsTTKEnabled() and not isSys.HasItem("True Triple Katana") then
        for _, ttkSw in ipairs(isSys.TTKSwords or { "Shisui", "Wando", "Saddi" }) do
            if isSys.HasItem(ttkSw) and isSys.GetMastery(ttkSw) < 300 then
                getgenv()._targetSwordName = ttkSw
                SetSettingWeapon("Sword")
                V1StyleLookup.EnsureSwordEquipped(ttkSw)
                return ttkSw
            end
        end
    end

    -- 3. CÁC VŨ KHÍ CẦN MASTERY KHÁC TRONG SETTING FARM
    if isSys.UnmasteredWeaponsList then
        for _, wp in ipairs(isSys.UnmasteredWeaponsList) do
            if isSys.HasItem(wp.Name) and isSys.GetMastery(wp.Name) < (wp.TargetMas or 350) then
                getgenv()._targetSwordName = wp.Name
                SetSettingWeapon(wp.WeaponType or "Sword")
                V1StyleLookup.EnsureSwordEquipped(wp.Name)
                return wp.Name
            end
        end
    end

    -- 4. ƯU TIÊN CÀY MASTERY SÚNG (GUN MASTERY - Soul Guitar 300, Kabucha 300, Serpent Bow...)
    local wantGun = (getgenv().SettingFarm and type(getgenv().SettingFarm["Farm Mastery"]) == "table" and getgenv().SettingFarm["Farm Mastery"]["Gun"] == true)
                 or (getgenv().SettingFarm and getgenv().SettingFarm["Farm Gun"] == true)
                 or IsSettingGetItem("Gun Mastery")
    if wantGun and isPreGhDone then
        local gunList = {
            { Name = "Soul Guitar", Target = 300 },
            { Name = "Skull Guitar", Target = 300 },
            { Name = "Kabucha", Target = 300 },
            { Name = "Acidum Rifle", Target = 300 },
            { Name = "Serpent Bow", Target = 300 },
            { Name = "Bizarre Rifle", Target = 300 },
        }
        for _, g in ipairs(gunList) do
            if isSys.HasItem(g.Name) and isSys.GetMastery(g.Name) < g.Target then
                getgenv()._targetSwordName = g.Name
                SetSettingWeapon("Gun")
                V1StyleLookup.EnsureSwordEquipped(g.Name)
                return g.Name
            end
        end
    end

    return nil
end

local function EquipSelectedWeapon()
    local char = plr.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not char or not hum or hum.Health <= 0 then return end

    local inRaid = (getgenv()._isDoingRaidForF == true)
        or (type(V1StyleLookup) == "table" and V1StyleLookup.IsInRaid and V1StyleLookup.IsInRaid())

    local isStatsInMelee = false
    pcall(function()
        local data = plr:FindFirstChild("Data")
        local statsFolder = data and data:FindFirstChild("Stats")
        if statsFolder then
            local swLv = GetStatCurrentLevel(statsFolder, "Sword")
            local melLv = GetStatCurrentLevel(statsFolder, "Melee")
            if melLv >= 800 and swLv < melLv * 0.5 then
                isStatsInMelee = true
            end
        end
    end)

    local currentTool = char:FindFirstChildOfClass("Tool")

    -- [QUY TẮC CỐT LÕI]: KHI Ở TRONG RAID HOẶC STATS ĐANG Ở MELEE & MÁU (KIẾM CHƯA CÓ ĐIỂM STAT)
    -- BẮT BUỘC DÙNG MELEE (VÕ) ĐỂ ĐÁNH CHO NHANH, SÁT THƯƠNG CAO, RAID SIÊU TỐC!
    -- TUYỆT ĐỐI KHÔNG DÙNG KIẾM KHI ĐI RAID HOẶC KHI STATS CHƯA RESET SANG KIẾM!
    if inRaid or isStatsInMelee then
        local targetStyle = type(V1StyleLookup) == "table" and V1StyleLookup.GetActiveTargetStyle and V1StyleLookup.GetActiveTargetStyle()
        if targetStyle then
            local tool, inHand = V1StyleLookup.FindMeleeTool(targetStyle.Name)
            if tool then
                if inHand then return end
                if currentTool then hum:UnequipTools() end
                hum:EquipTool(tool)
                return
            end
        end
        if currentTool and currentTool.ToolTip == "Melee" then
            return
        end
        for _, tool in ipairs(plr.Backpack:GetChildren()) do
            if tool:IsA("Tool") and tool.ToolTip == "Melee" then
                if currentTool then hum:UnequipTools() end
                hum:EquipTool(tool)
                return
            end
        end
        if inRaid then
            return
        end
    end

    local targetSw = getgenv()._targetSwordName
    if (not targetSw or targetSw == "") and type(V1StyleLookup) == "table" and V1StyleLookup.SyncTargetWeaponPriority then
        targetSw = V1StyleLookup.SyncTargetWeaponPriority()
    end

    -- CHỈ TRANG BỊ KIẾM / SÚNG KHI:
    -- 1. KHÔNG Ở TRONG RAID
    -- 2. STATS ĐÃ ĐƯỢC RESET SANG KIẾM (isStatsInMelee == false)
    if not inRaid and not isStatsInMelee and targetSw and targetSw ~= "" then
        V1StyleLookup.EnsureSwordEquipped(targetSw)
        return
    end

    local wantedType = GetSettingWeapon()
    if isStatsInMelee and wantedType == "Sword" then
        wantedType = "Melee"
    end

    -- Nếu vũ khí mong muốn là Melee và đang bật Tự động cày Mastery Võ (V1 hoặc V2 hoặc Godhuman):
    -- Ưu tiên trang bị đúng võ V1/V2 đang cần cày (chưa đạt 400 Mastery)
    if wantedType == "Melee" and (IsSettingBuyMeleeV1() or IsSettingBuyMeleeV2() or IsSettingGetItem("Godhuman")) then
        local targetStyle = V1StyleLookup.GetActiveTargetStyle()
        if targetStyle then
            if currentTool and (currentTool.Name == targetStyle.Name or (targetStyle.Aliases and table.find(targetStyle.Aliases, currentTool.Name))) then
                return
            end
            local tool, inHand = V1StyleLookup.FindMeleeTool(targetStyle.Name)
            if tool then
                if inHand then return end
                if currentTool then hum:UnequipTools() end
                hum:EquipTool(tool)
                return
            end
        end

        -- Nếu võ mục tiêu chưa sở hữu (ví dụ Dragon Talon đang chờ Fire Essence / hồi lượt quay xương):
        -- 1. Ưu tiên tìm trong Balo xem có võ Melee nào khác chưa đạt 400 Mastery (< 400 Mas) không để cày tiếp!
        local unTool = type(V1StyleLookup) == "table" and type(V1StyleLookup.GetUnmasteredOwnedMelee) == "function" and V1StyleLookup.GetUnmasteredOwnedMelee()
        if unTool then
            if currentTool and currentTool == unTool then
                return
            end
            if currentTool then hum:UnequipTools() end
            hum:EquipTool(unTool)
            return
        end

        -- 2. Nếu TOÀN BỘ võ Melee đang sở hữu đều đã Đạt >= 400 Mastery (như Sharkman Karate 600 Mas):
        -- Kiểm tra xem có Kiếm (Yama, Tushita, TTK...) hoặc Súng (Soul Guitar...) cần cày Mastery không.
        -- Nếu có -> Trang bị Kiếm/Súng đó để cày Mastery trong thời gian chờ mở khóa Dragon Talon, tránh lãng phí EXP!
        local altWeapon = type(V1StyleLookup) == "table" and type(V1StyleLookup.SyncTargetWeaponPriority) == "function" and V1StyleLookup.SyncTargetWeaponPriority()
        if altWeapon and altWeapon ~= "" then
            V1StyleLookup.EnsureSwordEquipped(altWeapon)
            return
        end
    end

    if currentTool and currentTool.ToolTip == wantedType then
        return
    end

    for _, tool in ipairs(plr.Backpack:GetChildren()) do
        if tool:IsA("Tool") and tool.ToolTip == wantedType then
            hum:EquipTool(tool)
            break
        end
    end
end

function V1StyleLookup.IsAutoFarmLevelEnabled()
    if getgenv().SettingFarm then
        local sf = getgenv().SettingFarm["Settings farm"]
        if type(sf) == "table" then
            if sf["Auto Farm Level"] ~= nil then return sf["Auto Farm Level"] == true end
            if sf["Farm Level"] ~= nil then return sf["Farm Level"] == true end
            if sf["Auto Level"] ~= nil then return sf["Auto Level"] == true end
        end
        local afl = getgenv().SettingFarm["Auto Farm Level"] or getgenv().SettingFarm["Farm Level"] or getgenv().SettingFarm["Auto Level"]
        if type(afl) == "table" and afl["Enabled"] ~= nil then
            return afl["Enabled"] == true
        end
        if afl ~= nil and type(afl) == "boolean" then
            return afl == true
        end
    end
    return true
end

-- =========================================================================
-- [TÍNH NĂNG NÂNG CAO 1]: TỰ ĐỘNG BIẾN HÌNH & DUY TRÌ FORM BUDDHA KHỔNG LỒ (Z)
-- =========================================================================
function V1StyleLookup.CheckAndMaintainBuddhaForm(hrp, hum)
    local autoB = getgenv().SettingFarm and getgenv().SettingFarm["Auto Buddha"]
    if autoB and autoB["Transform"] == false then return false end

    local df = plr:FindFirstChild("Data") and plr.Data:FindFirstChild("DemonFruit")
    local dfName = df and df.Value or ""
    if not string.find(string.lower(dfName), "buddha") then
        return false
    end

    local char = plr.Character
    if not char or not hum or hum.Health <= 0 then return false end

    -- Kiểm tra xem nhân vật đã ở trạng thái khổng lồ chưa
    local isGiant = false
    if char:FindFirstChild("Transform") or char:FindFirstChild("BuddhaTransform") or char:GetAttribute("Transformed") == true then
        isGiant = true
    elseif hum.HipHeight >= 4 or (hrp and hrp.Size.Y >= 4) then
        isGiant = true
    end

    if isGiant then
        return false
    end

    local now = tick()
    if now - (getgenv()._lastBuddhaTransformAttempt or 0) < 3.5 then
        return false
    end
    getgenv()._lastBuddhaTransformAttempt = now

    -- Bấm phím Z để kích hoạt biến hình khổng lồ
    local fruitTool = nil
    for _, t in ipairs(plr.Backpack:GetChildren()) do
        if t:IsA("Tool") and (t.ToolTip == "Demon Fruit" or string.find(string.lower(t.Name), "buddha")) then
            fruitTool = t
            break
        end
    end

    if fruitTool then
        hum:EquipTool(fruitTool)
        task.wait(0.15)
        pcall(function()
            local vim = game:GetService("VirtualInputManager")
            if vim then
                vim:SendKeyEvent(true, Enum.KeyCode.Z, false, game)
                task.wait(0.1)
                vim:SendKeyEvent(false, Enum.KeyCode.Z, false, game)
            end
        end)
        task.wait(0.25)
        EquipSelectedWeapon()
        return true
    else
        pcall(function()
            local vim = game:GetService("VirtualInputManager")
            if vim then
                vim:SendKeyEvent(true, Enum.KeyCode.Z, false, game)
                task.wait(0.1)
                vim:SendKeyEvent(false, Enum.KeyCode.Z, false, game)
            end
        end)
        task.wait(0.2)
        EquipSelectedWeapon()
        return true
    end
end

-- =========================================================================
-- [TÍNH NĂNG NÂNG CAO 2]: TỰ ĐỘNG ĂN TRÁI ÁC QUỶ MỤC TIÊU (AUTO EAT TARGET FRUIT)
-- =========================================================================
function V1StyleLookup.CheckAndEatTargetFruit()
    local ef = getgenv().SettingFarm and (getgenv().SettingFarm["Auto Eat Fruit"] or getgenv().SettingFarm.AutoEatFruit)
    if not ef or ef["Enabled"] == false then return false end

    local targetFruitNames = ef["Fruit"] or { "Human-Human: Buddha", "Buddha-Buddha", "Light-Light" }
    if type(targetFruitNames) == "string" then
        targetFruitNames = { targetFruitNames }
    end

    local currentDf = plr:FindFirstChild("Data") and plr.Data:FindFirstChild("DemonFruit") and plr.Data.DemonFruit.Value or ""
    -- Nếu đã đang dùng đúng trái mục tiêu rồi thì bỏ qua
    for _, fn in ipairs(targetFruitNames) do
        local cleanFn = string.lower(string.gsub(fn, "[%s%-_]", ""))
        local cleanCur = string.lower(string.gsub(currentDf, "[%s%-_]", ""))
        if string.find(cleanCur, cleanFn) or (string.find(cleanFn, "buddha") and string.find(cleanCur, "buddha")) then
            return false
        end
    end

    -- BẢO VỆ TUYỆT ĐỐI TRÁI VIP / MYTHICAL ĐANG DÙNG TRÊN NGƯỜI:
    -- Nếu người chơi đang dùng các trái xịn (Kitsune, Dragon, Leopard, Dough, Portal, Spirit, Venom, Mammoth, T-Rex, Shadow, Gas, Yeti...)
    -- Tuyệt đối KHÔNG BAO GIỜ ăn đè Buddha lên làm mất trái VIP của người chơi!
    local vipFruits = {
        "kitsune", "dragon", "leopard", "dough", "portal", "spirit",
        "venom", "shadow", "mammoth", "t-rex", "trex", "gas", "yeti",
        "blizzard", "sound", "control"
    }
    local lCurDf = string.lower(currentDf)
    for _, vip in ipairs(vipFruits) do
        if string.find(lCurDf, vip) then
            return false
        end
    end

    -- 1. Tìm trong Balo hoặc trên người
    local fruitTool = nil
    for _, container in ipairs({ plr:FindFirstChild("Backpack"), plr.Character }) do
        if container then
            for _, t in ipairs(container:GetChildren()) do
                if t:IsA("Tool") and (t.ToolTip == "Demon Fruit" or string.find(t.Name, "Fruit")) then
                    for _, fn in ipairs(targetFruitNames) do
                        if string.find(string.lower(t.Name), string.lower(fn)) or (string.find(string.lower(fn), "buddha") and string.find(string.lower(t.Name), "buddha")) then
                            fruitTool = t
                            break
                        end
                    end
                end
                if fruitTool then break end
            end
        end
        if fruitTool then break end
    end

    -- 2. Nếu chưa có trên người, thử lấy từ kho đồ ra (LoadFruit)
    if not fruitTool then
        local now = tick()
        if now - (getgenv()._lastEatUnstoreAttempt or 0) >= 6.0 then
            getgenv()._lastEatUnstoreAttempt = now
            for _, fn in ipairs(targetFruitNames) do
                local storeId = fn
                if not string.find(storeId, "-") and not string.find(storeId, ":") then
                    storeId = fn .. "-" .. fn
                end
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("LoadFruit", storeId)
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("LoadFruit", fn)
                end)
            end
        end
        return false
    end

    -- 3. Có trái trên tay -> Tiến hành Ăn (Eat)
    local char = plr.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if char and hum and hum.Health > 0 then
        if fruitTool.Parent ~= char then
            hum:EquipTool(fruitTool)
            task.wait(0.3)
        end
        CurrentFarmStatus = "[Auto Eat Fruit] 🍎 Đang ăn trái ác quỷ " .. tostring(fruitTool.Name) .. "..."
        local eatRemote = fruitTool:FindFirstChild("EatRemote")
        if eatRemote then
            pcall(function() eatRemote:InvokeServer("Eat") end)
        end
        pcall(function()
            ReplicatedStorage.Remotes.CommF_:InvokeServer("EatFruit", fruitTool.Name)
        end)
        task.wait(0.5)
        return true
    end
    return false
end

-- =========================================================================
-- [TÍNH NĂNG NÂNG CAO 3]: TỰ NHẶT RƯƠNG CHO ACC MỚI SEA 1 (EARLY CHEST FARM)
-- =========================================================================
function V1StyleLookup.DoEarlyChestFarmStep(hrp, curLv, curBeli)
    local ec = getgenv().SettingFarm and getgenv().SettingFarm["Auto Early Chest"]
    if ec and ec["Enabled"] == false then return false end

    -- Chỉ kích hoạt ở Sea 1, cấp <= 300 và khi số Beli dưới 50,000 (đang thiếu tiền mua Geppo/Buso/Võ)
    if (CurrentSeaNum == 1 or World1) and curLv <= 300 and curBeli < 50000 then
        local isSys = V1StyleLookup.ItemsSystem
        if type(isSys) == "table" and type(isSys.CollectNearestChest) == "function" then
            CurrentFarmStatus = "[Acc Mới] 💰 Đang gom rương kiếm Beli mua Geppo & Buso ($" .. FormatNumber(curBeli) .. "/$50,000)..."
            local collected = isSys.CollectNearestChest(hrp)
            if collected then
                return true
            end
        end
    end
    return false
end

-- ==========================================
-- HỆ THỐNG NHẬN DIỆN & QUẢN LÝ NHIỆM VỤ (QUEST SYSTEM)
-- Hỗ trợ cả UI Quest cũ (Main.Quest) và UI Quest mới (TrackedQuestFrame + GuideModule)
-- ==========================================
local QuestsModule = nil
local GuideModule = nil
pcall(function() QuestsModule = require(ReplicatedStorage:WaitForChild("Quests")) end)
pcall(function() GuideModule = require(ReplicatedStorage:WaitForChild("GuideModule")) end)

local function ReadTextFromInst(inst)
    if not inst then return nil end
    if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
        return inst.Text ~= "" and inst.Text or nil
    end
    for _, d in ipairs(inst:GetDescendants()) do
        if d:IsA("TextLabel") and d.Text ~= "" then
            return d.Text
        end
    end
    return nil
end

local function CollectAllText(root)
    local out = {}
    if not root then return out end
    local function add(i)
        if i:IsA("TextLabel") and i.Visible and i.Text ~= "" then
            local t = i.Text:gsub("^%s+", ""):gsub("%s+$", "")
            if t ~= "" and t ~= "?" and not t:match("^%?+$") and t:match("%w") then
                out[#out + 1] = t
            end
        end
    end
    add(root)
    for _, d in ipairs(root:GetDescendants()) do
        add(d)
    end
    return out
end

local function GetQuestTitle()
    local pg = plr:FindFirstChild("PlayerGui")
    if not pg then return "" end

    local function isValidTitle(str)
        if type(str) ~= "string" then return false end
        local clean = str:gsub("^[%s%?|]+", ""):gsub("[%s%?|]+$", "")
        if #clean < 3 or not clean:match("%a%a") then return false end
        if clean:match("^%?+$") or clean == "?" then return false end
        return true
    end

    local main = pg:FindFirstChild("Main") or pg:FindFirstChild("Main (minimal)")
    local q = main and main:FindFirstChild("Quest")
    if q and q.Visible then
        local c = q:FindFirstChild("Container")
        local qt = c and c:FindFirstChild("QuestTitle")
        local txt = ReadTextFromInst(qt and qt:FindFirstChild("Title"))
        if isValidTitle(txt) then return txt end
        -- Quét các TextLabel trong Container hoặc Quest tìm tiêu đề nhiệm vụ (ưu tiên Defeat)
        for _, desc in ipairs(q:GetDescendants()) do
            if desc:IsA("TextLabel") and desc.Visible then
                local t = ReadTextFromInst(desc)
                if isValidTitle(t) and (t:find("Defeat") or t:find("defeat") or desc.Name == "Title" or desc.Name == "QuestTitle") then
                    return t
                end
            end
        end
        -- Nếu không có chữ Defeat, lấy TextLabel đầu tiên có nội dung hợp lệ
        for _, desc in ipairs(q:GetDescendants()) do
            if desc:IsA("TextLabel") and desc.Visible then
                local t = ReadTextFromInst(desc)
                if isValidTitle(t) and not tonumber(t) and not t:find("^%d+/%d+$") then
                    return t
                end
            end
        end
    end

    local tr = pg:FindFirstChild("TrackedQuestFrame")
    if tr then
        local on = (tr:IsA("ScreenGui") and tr.Enabled) or (tr:IsA("GuiObject") and tr.Visible)
        local fr = tr:FindFirstChild("Frame")
        if on and fr and fr.Visible then
            local txt = ReadTextFromInst(fr:FindFirstChild("header"))
            if isValidTitle(txt) then return txt end
            for _, desc in ipairs(fr:GetDescendants()) do
                if desc:IsA("TextLabel") and desc.Visible then
                    local t = ReadTextFromInst(desc)
                    if isValidTitle(t) then return t end
                end
            end
        end
    end
    return ""
end

local function GetQuestText()
    local pg = plr:FindFirstChild("PlayerGui")
    if not pg then return "" end
    local parts = {}

    local main = pg:FindFirstChild("Main") or pg:FindFirstChild("Main (minimal)")
    local q = main and main:FindFirstChild("Quest")
    if q and q.Visible then
        for _, s in ipairs(CollectAllText(q)) do
            parts[#parts + 1] = s
        end
    end

    local tr = pg:FindFirstChild("TrackedQuestFrame")
    if tr then
        local on = (tr:IsA("ScreenGui") and tr.Enabled) or (tr:IsA("GuiObject") and tr.Visible)
        if on then
            for _, s in ipairs(CollectAllText(tr)) do
                parts[#parts + 1] = s
            end
        end
    end
    return table.concat(parts, " | ")
end

if type(V1StyleLookup) == "table" then
    V1StyleLookup.GetQuestTitle = GetQuestTitle
    V1StyleLookup.GetQuestText = GetQuestText
end

_questSeenUntil = 0
local function HasActiveQuest()
    local pg = plr:FindFirstChild("PlayerGui")
    if pg then
        local main = pg:FindFirstChild("Main") or pg:FindFirstChild("Main (minimal)")
        local q = main and main:FindFirstChild("Quest")
        if q and q.Visible then
            _questSeenUntil = tick() + 1
            return true
        end
        local tr = pg:FindFirstChild("TrackedQuestFrame")
        if tr and ((tr:IsA("ScreenGui") and tr.Enabled) or (tr:IsA("GuiObject") and tr.Visible)) then
            local fr = tr:FindFirstChild("Frame")
            if fr and fr.Visible then
                _questSeenUntil = tick() + 1
                return true
            end
        end
    end
    if GetQuestTitle() ~= "" or GetQuestText() ~= "" then
        _questSeenUntil = tick() + 1
        return true
    end
    if GuideModule and GuideModule.Data and GuideModule.Data.QuestData ~= nil then
        _questSeenUntil = tick() + 1
        return true
    end
    return tick() < _questSeenUntil
end

local function ResetQuestSeen()
    _questSeenUntil = 0
end

local function IsBartiloActiveQuest()
    local qTitle = (GetQuestTitle() or ""):lower()
    local qText = (GetQuestText() or ""):lower()
    return qTitle:find("swan") ~= nil or qText:find("swan") ~= nil or qTitle:find("bartilo") ~= nil or qText:find("bartilo") ~= nil
end

-- ==========================================
-- HỆ THỐNG QUẢN LÝ THÔNG MINH HAKI QUAN SÁT (SMART INSTINCT)
-- Yêu cầu:
-- 1. Khi farm cấp tự động kích hoạt Haki Quan Sát (Ken Haki / phím E).
-- 2. Nếu đã bật thì KHÔNG cần bật lại (tránh bị bật tắt liên tục).
-- 3. Nếu hết lượt né (KenDodgesLeft == 0) -> Tắt Haki để hồi phục lượt né.
-- 4. Khi hồi phục xong (đầy lượt né hoặc sau ~20s) -> Bật lại Haki tiếp tục farm!
-- ==========================================
local SmartKen = {
    IsRecharging = false,    -- Có đang trong quá trình tắt để sạc lại né không
    RechargeStartTime = 0,   -- Thời điểm bắt đầu tắt để hồi phục
    LastToggleTick = 0,      -- Tránh spam bấm phím E liên tục
    MaxDodges = 8,           -- Số lượt né tối đa
}

function SmartKen.GetButton()
    local pg = plr:FindFirstChild("PlayerGui")
    if not pg then return nil end
    local main = pg:FindFirstChild("Main")
    if main then
        for _, name in ipairs({"Ken", "KenButton", "Observation", "Instinct", "ObservationButton"}) do
            local b = main:FindFirstChild(name, true)
            if b and (b:IsA("GuiButton") or b:IsA("ImageButton") or b:IsA("TextButton")) and b.Visible ~= false then
                return b
            end
        end
    end
    return nil
end

function SmartKen.IsActiveNow()
    local char = plr.Character
    if char then
        if char:GetAttribute("ObservationActive") == true or char:GetAttribute("KenActive") == true then
            return true
        end
        if char:FindFirstChild("Observation") or char:FindFirstChild("Ken") then
            return true
        end
        if CollectionService and CollectionService:HasTag(char, "Ken") then
            return true
        end
    end
    if plr:GetAttribute("ObservationActive") == true or plr:GetAttribute("KenActive") == true then
        return true
    end

    local cam = workspace.CurrentCamera
    if cam and (cam:FindFirstChild("Observation") or cam:FindFirstChild("KenVision") or cam:FindFirstChild("VisionEffect")) then
        return true
    end
    local lighting = game:GetService("Lighting")
    if lighting then
        local ob = lighting:FindFirstChild("Observation") or lighting:FindFirstChild("Ken")
        if ob and (ob:IsA("PostProcessEffect") or ob:IsA("ColorCorrectionEffect")) and ob.Enabled then
            return true
        end
    end

    local btn = SmartKen.GetButton()
    if btn then
        for _, child in ipairs(btn:GetChildren()) do
            if child:IsA("UIStroke") and child.Enabled then
                return true
            end
            local cn = child.Name:lower()
            if (cn:find("select") or cn:find("active") or cn:find("highlight") or cn:find("outline") or cn:find("border")) and child:IsA("GuiObject") and child.Visible and child.Transparency < 0.7 then
                return true
            end
        end
    end

    return false
end

function SmartKen.TriggerToggle()
    -- Tuyệt đối KHÔNG toggle phím E khi đang làm sự kiện Halloween (tránh xung đột gõ cửa / vào cổng / đập bí ngô)
    if HW and (HW.IsDoingEvent or HW.IsHarvestMoonTime()) then return end
    if CurrentFarmStatus and (CurrentFarmStatus:find("Halloween") or CurrentFarmStatus:find("Sự Kiện")) then return end
    if not HasInstinct() then return end

    -- Cooldown tối thiểu 5 giây giữa các lần bật/tắt (tránh spam liên tục)
    if tick() - SmartKen.LastToggleTick < 5.0 then return end
    SmartKen.LastToggleTick = tick()

    pcall(function()
        local vim = game:GetService("VirtualInputManager")
        if vim then
            vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)
            task.wait(0.06)
            vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)
        end
    end)
    pcall(function()
        local btn = SmartKen.GetButton()
        if btn then
            SafeClickGuiButton(btn)
        end
    end)
end

function SmartKen.EnsureState(desiredActive)
    if HW and (HW.IsDoingEvent or HW.IsHarvestMoonTime()) then return end
    if CurrentFarmStatus and (CurrentFarmStatus:find("Halloween") or CurrentFarmStatus:find("Sự Kiện")) then return end
    if not HasInstinct() then return end

    local currentlyActive = SmartKen.IsActiveNow()
    if desiredActive then
        -- Yêu cầu: Nếu đã bật KHÔNG cần bật lại!
        if not currentlyActive then
            SmartKen.TriggerToggle()
        end
    else
        -- Tắt Haki để hồi né: nếu đang bật thì mới tắt
        if currentlyActive then
            SmartKen.TriggerToggle()
        end
    end
end

function SmartKen.GetDodges()
    local attr = plr:GetAttribute("KenDodgesLeft") or plr:GetAttribute("Dodges")
    if attr == nil and plr.Character then
        attr = plr.Character:GetAttribute("KenDodgesLeft") or plr.Character:GetAttribute("Dodges")
    end
    if attr ~= nil and tonumber(attr) ~= nil then
        return tonumber(attr)
    end

    local pg = plr:FindFirstChild("PlayerGui")
    if pg then
        for _, obj in ipairs(pg:GetDescendants()) do
            if obj:IsA("TextLabel") and obj.Visible then
                local txt = obj.Text or ""
                local cur, maxD = txt:match("(%d+)%s*/%s*(%d+)")
                if cur and maxD and tonumber(maxD) >= 2 and tonumber(maxD) <= 15 then
                    return tonumber(cur), tonumber(maxD)
                end
                local d1 = txt:match("[Dd]odge[s]?%s*:%s*(%d+)") or txt:match("(%d+)%s*[Dd]odge")
                if d1 then
                    return tonumber(d1)
                end
            end
        end
    end
    return nil
end

local function EnableKen()
    -- Tuyệt đối KHÔNG bật/tắt Haki Quan Sát khi đang làm sự kiện Halloween!
    if HW and (HW.IsDoingEvent or HW.IsHarvestMoonTime()) then return end
    if CurrentFarmStatus and (CurrentFarmStatus:find("Halloween") or CurrentFarmStatus:find("Sự Kiện")) then return end
    if not HasInstinct() then return end

    if not IsSmartInstinctEnabled() then
        SmartKen.EnsureState(true)
        return
    end

    if tick() - SmartKen.LastToggleTick < 5.0 then return end

    local curDodges, maxD = SmartKen.GetDodges()
    if maxD and maxD > SmartKen.MaxDodges then
        SmartKen.MaxDodges = maxD
    end
    if curDodges and curDodges > SmartKen.MaxDodges then
        SmartKen.MaxDodges = curDodges
    end

    -- TRƯỜNG HỢP 1: ĐANG TẮT ĐỂ HỒI PHỤC LƯỢT NÉ
    if SmartKen.IsRecharging then
        local elapsed = tick() - SmartKen.RechargeStartTime
        local isDone = false
        if curDodges ~= nil and curDodges >= SmartKen.MaxDodges then
            isDone = true
        elseif elapsed >= 20 then
            isDone = true
        end

        if isDone then
            -- ĐÃ HỒI XONG -> Bật lại Haki Quan Sát (phím E)!
            SmartKen.IsRecharging = false
            SmartKen.EnsureState(true)
        else
            -- Vẫn đang hồi -> Giữ Ken TẮT
            SmartKen.EnsureState(false)
        end
        return
    end

    -- TRƯỜNG HỢP 2: ĐANG FARM -> Kiểm tra nếu hết lượt né (curDodges == 0)
    if curDodges ~= nil and curDodges <= 0 and SmartKen.IsActiveNow() then
        -- HẾT LƯỢT NÉ -> Tắt Haki để bắt đầu hồi phục!
        SmartKen.IsRecharging = true
        SmartKen.RechargeStartTime = tick()
        SmartKen.EnsureState(false)
        return
    end

    -- Farm bình thường: Bật Haki Quan Sát (nếu đã bật không bật lại)
    SmartKen.EnsureState(true)
end

-- Reset trạng thái Ken khi nhân vật hồi sinh
pcall(function()
    plr.CharacterAdded:Connect(function()
        SmartKen.IsRecharging = false
    end)
end)

-- Vòng lặp nền quản lý Haki Quan Sát (tự bật khi farm, hết lượt né tự tắt để hồi và bật lại khi đầy)
task.spawn(function()
    while task.wait(1.0) do
        pcall(function()
            if HW and (HW.IsDoingEvent or HW.IsHarvestMoonTime()) then return end
            if CurrentFarmStatus and (CurrentFarmStatus:find("Halloween") or CurrentFarmStatus:find("Sự Kiện")) then return end
            if HasInstinct() and IsSmartInstinctEnabled() then
                local isFarming = HasActiveQuest() or getgenv()._currentTargetMobName ~= nil or (CurrentFarmStatus and (CurrentFarmStatus:find("quái") or CurrentFarmStatus:find("Boss") or CurrentFarmStatus:find("Saber") or CurrentFarmStatus:find("Mob") or CurrentFarmStatus:find("Farm") or CurrentFarmStatus:find("farm")))
                if isFarming or SmartKen.IsRecharging then
                    EnableKen()
                end
            end
        end)
    end
end)

local function EnableBuso()
    local char = plr.Character
    if char and not char:FindFirstChild("HasBuso") then
        pcall(function()
            ReplicatedStorage.Remotes.CommF_:InvokeServer("Buso")
        end)
    end
end

local function IsNetworkOwnerSafe(part)
    if not part then return false end
    local chars = workspace:FindFirstChild("Characters")
    if chars then
        for _, ch in ipairs(chars:GetChildren()) do
            if ch.Name ~= plr.Name and ch:FindFirstChild("HumanoidRootPart") then
                if (ch.HumanoidRootPart.Position - part.Position).Magnitude <= 300 then
                    return false
                end
            end
        end
    end
    return true
end

local function DisableMobCollision(mob)
    if not mob or not mob.Parent or not mob:FindFirstChild("HumanoidRootPart") then return end
    for _, part in ipairs(mob:GetDescendants()) do
        if (part:IsA("Part") or part:IsA("MeshPart")) and part.CanCollide then
            part.CanCollide = false
        end
    end
end

local AllBossMobs

local function StripMobLevelTag(rawName)
    if type(rawName) ~= "string" then return "" end
    return (rawName:gsub(" %p?Lv%.? %d+%p?", ""):gsub("^%s+", ""):gsub("%s+$", ""))
end


local function BringMobs(targetMob)
    if not targetMob or not targetMob.Parent then return end
    if Players:GetPlayerFromCharacter(targetMob) or Players:FindFirstChild(targetMob.Name) or targetMob:FindFirstChild("PlayerGui") then return end
    local targetHrp = targetMob:FindFirstChild("HumanoidRootPart")
    local targetHum = targetMob:FindFirstChildOfClass("Humanoid")
    if not targetHrp or not targetHum or targetHum.Health <= 0 then return end

    pcall(function()
        if sethiddenproperty then
            sethiddenproperty(plr, "SimulationRadius", math.huge)
        end
    end)

    DisableMobCollision(targetMob)

    local targetPos = targetHrp.Position
    local targetClean = string.lower(StripMobLevelTag(targetMob.Name))
    local isBoneTarget = (targetClean:find("skeleton") or targetClean:find("zombie") or targetClean:find("demonic") or targetClean:find("mummy"))

    local enemies = workspace:FindFirstChild("Enemies")
    if not enemies then return end

    local count = 0
    local maxBring = isBoneTarget and 8 or 5

    for _, mob in ipairs(enemies:GetChildren()) do
        if count >= maxBring then break end
        -- Tuyệt đối không gom Player
        if mob ~= targetMob and mob.Parent and not Players:GetPlayerFromCharacter(mob) and not Players:FindFirstChild(mob.Name) and not mob:FindFirstChild("PlayerGui") and not mob:FindFirstChildWhichIsA("ProximityPrompt", true) and not mob:FindFirstChildWhichIsA("Dialog", true) then
            local hum = mob:FindFirstChildOfClass("Humanoid")
            local hrp = mob:FindFirstChild("HumanoidRootPart")
            if hum and hrp and hum.Health > 0 then
                local mobClean = string.lower(StripMobLevelTag(mob.Name))
                if not AllBossMobs[mobClean] then
                    local canBring = false

                    if isBoneTarget then
                        -- Farm Xương (Haunted Castle): Gom toàn bộ quái xương (Reborn Skeleton & Living Zombie) trong bán kính nghĩa trang lại 1 cụm!
                        if mobClean:find("skeleton") or mobClean:find("zombie") or mobClean:find("demonic") or mobClean:find("mummy") then
                            canBring = true
                        end
                    elseif mobClean == targetClean then
                        canBring = true
                    elseif (hrp.Position - targetPos).Magnitude <= 200 then
                        canBring = true
                    end

                    if canBring then
                        local dist = (hrp.Position - targetPos).Magnitude
                        if dist <= 320 and dist > 3 then
                            DisableMobCollision(mob)
                            hrp.CFrame = targetHrp.CFrame * CFrame.new(math.random(-1, 1), 0, math.random(-1, 1))
                            hrp.AssemblyLinearVelocity = Vector3.zero
                            hrp.AssemblyAngularVelocity = Vector3.zero
                            pcall(function() hum.WalkSpeed = 0 end)
                            count = count + 1
                        end
                    end
                end
            end
        end
    end
end

-- Fast Attack mới nhất qua Modules.Net (Chỉ đánh đúng quái mục tiêu & lọc bỏ NPC nhiệm vụ ẩn như Escaped Prisoner)
getgenv().FastAttack = true

local RegisterAttack, RegisterHit

do
	local _lastToolAnim = 0
	local _lastHitSend = 0
	local _fastAttackDistance = 62
	local _aoeScanRadius = 45
	local _hitInterval = 0.08 -- Tránh spam remote quá dày gây drop hit / kick
	local _maxTargets = 20

	local netModuleCache = nil
	local lastResolveTick = 0
	local cachedCFModule = nil

	local function SafeStripMobLevelTag(name)
		if type(StripMobLevelTag) == "function" then
			local ok, res = pcall(StripMobLevelTag, name)
			if ok and type(res) == "string" then
				return res
			end
		end
		return tostring(name or ""):gsub("%s*%[Lv%.%s*%d+%s*%]", ""):gsub("^%s+", ""):gsub("%s+$", "")
	end

	local function IsPlayerEntity(obj)
		if not obj then
			return false
		end

		if Players:GetPlayerFromCharacter(obj) ~= nil then
			return true
		end

		if obj:FindFirstChild("PlayerGui") ~= nil or obj:FindFirstChild("Backpack") ~= nil then
			return true
		end

		if obj.Parent and obj.Parent.Name == "Characters" then
			return true
		end

		-- Chỉ coi là Player nếu có tên trùng với 1 Player đang online VÀ không nằm trong workspace.Enemies
		if obj.Parent ~= workspace:FindFirstChild("Enemies") and Players:FindFirstChild(obj.Name) ~= nil then
			return true
		end

		return false
	end

	local function ResolveFastAttackRemotes(force)
		local now = os.clock()
		if RegisterAttack and not RegisterAttack.Parent then
			RegisterAttack = nil
		end
		if RegisterHit and not RegisterHit.Parent then
			RegisterHit = nil
		end

		if not force and RegisterAttack and RegisterHit and (now - lastResolveTick < 2.5) then
			return RegisterAttack, RegisterHit
		end

		pcall(function()
			local Net = ReplicatedStorage:FindFirstChild("Modules")
				and ReplicatedStorage.Modules:FindFirstChild("Net")
				or ReplicatedStorage:FindFirstChild("Net", true)

			if Net and not netModuleCache then
				local okM, mod = pcall(require, Net)
				if okM and type(mod) == "table" then
					netModuleCache = mod
				end
			end

			if Net then
				RegisterAttack = Net:FindFirstChild("RE/RegisterAttack") or Net:FindFirstChild("RegisterAttack") or RegisterAttack
				RegisterHit = Net:FindFirstChild("RE/RegisterHit") or Net:FindFirstChild("RegisterHit") or RegisterHit
			end

			if netModuleCache and type(netModuleCache.RemoteEvent) == "function" then
				if not RegisterAttack then
					local okA, remA = pcall(function()
						return netModuleCache:RemoteEvent("RegisterAttack", true)
					end)
					if okA and remA then
						RegisterAttack = remA
					end
				end

				if not RegisterHit then
					local okH, remH = pcall(function()
						return netModuleCache:RemoteEvent("RegisterHit", true)
					end)
					if okH and remH then
						RegisterHit = remH
					end
				end
			end
		end)

		lastResolveTick = os.clock()
		return RegisterAttack, RegisterHit
	end

	ResolveFastAttackRemotes(true)
	getgenv()._z9ResolveFastAttackRemotes = ResolveFastAttackRemotes

	local function IsEnemyVulnerableAndValid(enemy, requiredMobName)
		if not enemy or not enemy.Parent or not enemy:IsA("Model") then
			return false
		end

		if IsPlayerEntity(enemy) then
			return false
		end

		local ig = enemy:FindFirstChild("Z9_IgnoreMob")
		if ig then
			if ig:IsA("NumberValue") then
				if tick() < ig.Value then
					return false
				else
					pcall(function() ig:Destroy() end)
				end
			else
				return false
			end
		end

		local isEventMob = false
		if type(HW) == "table" and type(HW.IsEventMob) == "function" then
			local ok, res = pcall(HW.IsEventMob, enemy)
			if ok and res then
				isEventMob = true
			end
		end

		if not isEventMob then
			if enemy:FindFirstChildWhichIsA("ProximityPrompt", true) or enemy:FindFirstChildWhichIsA("Dialog", true) then
				return false
			end
		end

		local eHum = enemy:FindFirstChildOfClass("Humanoid")
		local eHrp = enemy:FindFirstChild("HumanoidRootPart")
		if not eHum or not eHrp or not eHrp:IsA("BasePart") or eHum.Health <= 0 then
			return false
		end

		if requiredMobName and requiredMobName ~= "" then
			local cleanEnemy = string.lower(SafeStripMobLevelTag(enemy.Name))
			local cleanReq = string.lower(SafeStripMobLevelTag(requiredMobName))
			local disp = enemy:GetAttribute("DisplayName")
			local cleanDisp = disp and string.lower(SafeStripMobLevelTag(tostring(disp))) or ""

			local isReqBone = cleanReq:find("skeleton", 1, true)
				or cleanReq:find("zombie", 1, true)
				or cleanReq:find("demonic", 1, true)
				or cleanReq:find("mummy", 1, true)

			local isEnemyBone = cleanEnemy:find("skeleton", 1, true)
				or cleanEnemy:find("zombie", 1, true)
				or cleanEnemy:find("demonic", 1, true)
				or cleanEnemy:find("mummy", 1, true)

			if isReqBone and isEnemyBone then
				return true
			end

			if cleanEnemy ~= cleanReq and cleanDisp ~= cleanReq and string.lower(enemy.Name) ~= cleanReq then
				if cleanEnemy == cleanReq .. "s" or cleanEnemy .. "s" == cleanReq then
					return true
				end
				if not isEventMob then
					return false
				end
			end
		end

		return true
	end

	local function SendRegisterHitAoE(anchorPart, allTargets, attackDelayArg)
		local now = os.clock()
		if now - _lastHitSend < _hitInterval then
			return
		end

		local remAttack, remHit = ResolveFastAttackRemotes(false)
		if not anchorPart or not anchorPart.Parent or not anchorPart:IsA("BasePart") then
			return
		end

		if type(allTargets) ~= "table" or #allTargets == 0 or not remAttack or not remHit then
			return
		end

		local anchorPos = anchorPart.Position
		local primaryModel = anchorPart.Parent
		local restTargets = {}

		for i = 1, #allTargets do
			local entry = allTargets[i]
			local model = entry and entry[1]
			local part = entry and entry[2]
			if model and model.Parent and part and part.Parent and part:IsA("BasePart") then
				if not (model == primaryModel and part == anchorPart) and (part.Position - anchorPos).Magnitude <= 50 then
					table.insert(restTargets, { model, part })
				end
			end
		end

		_lastHitSend = now

		pcall(function()
			remAttack:FireServer(attackDelayArg or 0)
			remHit:FireServer(anchorPart, restTargets)
		end)
	end

	local function updateCombatFramework()
		pcall(function()
			if not cachedCFModule then
				local playerScripts = plr:FindFirstChild("PlayerScripts")
				local cf = playerScripts and playerScripts:FindFirstChild("CombatFramework")
				if cf then
					local ok, cfModule = pcall(require, cf)
					if ok and type(cfModule) == "table" then
						cachedCFModule = cfModule
					end
				end
			end

			local ac = cachedCFModule and cachedCFModule.activeController
			if ac then
				ac.timeToNextAttack = 0
				ac.attacking = false
				ac.blocking = false
				ac.timeToNextBlock = 0
				ac.hitboxMagnitude = _fastAttackDistance
			end
		end)
	end

	task.spawn(function()
		local hitPartPriority = {
			"UpperTorso", "LowerTorso", "Head",
			"RightUpperArm", "RightLowerArm", "RightHand",
			"LeftUpperArm", "LeftLowerArm", "LeftHand",
			"RightUpperLeg", "RightLowerLeg", "RightFoot",
			"LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
			"Torso", "HumanoidRootPart",
		}

		local protectedToolNames = {
			["Fire Essence"] = true,
			["Water Key"] = true,
			["Library Key"] = true,
			["Lightning Bolt"] = true,
			["Red Key"] = true,
			["God's Chalice"] = true,
			["Sweet Chalice"] = true,
			["Fist of Darkness"] = true,
			["Holy Torch"] = true,
			["Hallow Essence"] = true,
			["Hidden Key"] = true,
			["Special Microchip"] = true,
			["Torch"] = true,
			["Cup"] = true,
			["Relic"] = true,
			["Flower 1"] = true,
			["Flower 2"] = true,
			["Flower 3"] = true,
			["Core Brain"] = true,
			["Hellfire Torch"] = true,
			["Microchip"] = true,
		}

		local function getValidEnemyHitPart(enemy)
			for i = 1, #hitPartPriority do
				local p = enemy:FindFirstChild(hitPartPriority[i])
				if p and p:IsA("BasePart") then
					return p
				end
			end
			return enemy:FindFirstChildWhichIsA("BasePart")
		end

		while task.wait(0.05) do
			if not getgenv().FastAttack then
				continue
			end

			if tick() < (getgenv()._pauseFastAttackUntil or 0) then
				continue
			end

			pcall(function()
				local char = plr.Character
				local hrp = char and char:FindFirstChild("HumanoidRootPart")
				local hum = char and char:FindFirstChildOfClass("Humanoid")

				if not hrp or not hrp:IsA("BasePart") or not hum or hum.Health <= 0 then
					return
				end

				local stunObj = char:FindFirstChild("Stun")
				if stunObj and stunObj:IsA("ValueBase") and stunObj.Value ~= 0 then
					stunObj.Value = 0
				end

				local busyObj = char:FindFirstChild("Busy")
				if busyObj and busyObj:IsA("ValueBase") and busyObj.Value == true then
					busyObj.Value = false
				end

				local tool = char:FindFirstChildOfClass("Tool")
				if not tool then
					return
				end

				local toolName = tostring(tool.Name or "")
				if protectedToolNames[toolName]
					or tool:FindFirstChild("EatRemote", true)
					or tool:FindFirstChild("Eat", true)
				then
					return
				end

				local toolNameLower = string.lower(toolName)
				local isGuitarTool = string.find(toolNameLower, "guitar", 1, true) ~= nil
				if isGuitarTool then
					return
				end

				local leftClickRemote = tool:FindFirstChild("LeftClickRemote", true)
				local isFruitTool = (tool.ToolTip == "Blox Fruit") or (leftClickRemote ~= nil)

				updateCombatFramework()

				local reqMob = (not getgenv()._isDoingRaidForF) and getgenv()._currentTargetMobName or nil
				local bossTable = (type(AllBossMobs) == "table") and AllBossMobs or {}
				local scanned = {}
				local hrpPos = hrp.Position
				local enemiesFolder = workspace:FindFirstChild("Enemies")

				if enemiesFolder then
					local children = enemiesFolder:GetChildren()
					for i = 1, #children do
						local enemy = children[i]
						if enemy:IsA("Model") and enemy ~= char and not IsPlayerEntity(enemy) then
							local eHum = enemy:FindFirstChildOfClass("Humanoid")
							local eHrp = enemy:FindFirstChild("HumanoidRootPart")
							if eHum and eHrp and eHrp:IsA("BasePart") and eHum.Health > 0 then
								local dist = (eHrp.Position - hrpPos).Magnitude
								if dist <= _fastAttackDistance then
									local isValid = IsEnemyVulnerableAndValid(enemy, reqMob)

									if not isValid and dist <= _aoeScanRadius then
										local cleanName = string.lower(SafeStripMobLevelTag(enemy.Name))
										if not bossTable[cleanName] and IsEnemyVulnerableAndValid(enemy, nil) then
											isValid = true
										end
									end

									if isValid then
										local targetPart = getValidEnemyHitPart(enemy)
										if targetPart then
											table.insert(scanned, {
												enemy = enemy,
												part = targetPart,
												dist = dist,
											})
										end
									end
								end
							end
						end
					end
				end

				if type(HW) == "table"
					and HW.IsSmashingCurrentPumpkin
					and HW.CurrentPumpkinTarget
					and HW.CurrentPumpkinTarget.Parent
					and HW.CurrentPumpkinPart
					and HW.CurrentPumpkinPart.Parent
					and HW.CurrentPumpkinPart:IsA("BasePart")
				then
					local dist = (HW.CurrentPumpkinPart.Position - hrpPos).Magnitude
					if dist <= _fastAttackDistance then
						table.insert(scanned, {
							enemy = HW.CurrentPumpkinTarget,
							part = HW.CurrentPumpkinPart,
							dist = dist,
						})
					end
				end

				if #scanned == 0 then
					return
				end

				table.sort(scanned, function(a, b)
					return a.dist < b.dist
				end)

				local targets = {}
				local limit = math.min(#scanned, _maxTargets)
				for i = 1, limit do
					table.insert(targets, {
						scanned[i].enemy,
						scanned[i].part,
					})
				end

				local closestPart = targets[1] and targets[1][2]
				if not closestPart or not closestPart.Parent or not closestPart:IsA("BasePart") then
					return
				end

				if isFruitTool then
					if leftClickRemote and leftClickRemote:IsA("RemoteEvent") then
						local now = os.clock()
						if now - _lastHitSend >= _hitInterval then
							_lastHitSend = now
							local dir = (closestPart.Position - hrpPos).Unit
							leftClickRemote:FireServer(dir, 1)
						end
					end
					return
				end

				if tool.ToolTip == "Gun" then
					local remEvent = tool:FindFirstChild("RemoteEvent")
					if remEvent and remEvent:IsA("RemoteEvent") then
						remEvent:FireServer("TAP", closestPart.Position)
					end
				else
					local hasPlayerNearby = false
					for _, p in ipairs(Players:GetPlayers()) do
						if p ~= plr and p.Character then
							local pHrp = p.Character:FindFirstChild("HumanoidRootPart")
							local pHead = p.Character:FindFirstChild("Head")
							local pPart = (pHrp and pHrp:IsA("BasePart")) and pHrp or ((pHead and pHead:IsA("BasePart")) and pHead or nil)
							if pPart and (pPart.Position - hrpPos).Magnitude <= _aoeScanRadius then
								hasPlayerNearby = true
								break
							end
						end
					end

					local now = os.clock()
					if not hasPlayerNearby and (now - _lastToolAnim >= 0.35) then
						_lastToolAnim = now
						tool:Activate()
					end

					SendRegisterHitAoE(closestPart, targets, 0)
				end
			end)
		end
	end)
end

