AllBossMobs = {
    ["the gorilla king"] = true, ["gorilla king"] = true, ["bobby"] = true, ["the saw"] = true,
    ["yeti"] = true, ["mob leader"] = true, ["vice admiral"] = true, ["warden"] = true,
    ["chief warden"] = true, ["swan"] = true, ["magma admiral"] = true, ["fishman lord"] = true,
    ["wysper"] = true, ["thunder god"] = true, ["cyborg"] = true, ["saber expert"] = true,
    ["diamond"] = true, ["jeremy"] = true, ["fajita"] = true, ["don swan"] = true,
    ["smoke admiral"] = true, ["cursed captain"] = true, ["awakened ice admiral"] = true,
    ["tide keeper"] = true, ["darkbeard"] = true, ["order"] = true,
    ["stone"] = true, ["island empress"] = true, ["kilo admiral"] = true, ["captain elephant"] = true,
