}
do
local seenMobs = {}
for _, m in ipairs(AllQuestMobs) do seenMobs[m] = true end
if QuestsModule then
    for _, qs in pairs(QuestsModule) do
        if type(qs) == "table" then
            for _, qd in pairs(qs) do
                if type(qd) == "table" and qd.Task then
                    for mn, cnt in pairs(qd.Task) do
                        if cnt == 1 then
                            AllBossMobs[mn:lower()] = true
                        elseif cnt > 1 and not seenMobs[mn] then
                            seenMobs[mn] = true
                            table.insert(AllQuestMobs, mn)
                        end
                    end
                end
            end
        end
    end
end
end

local function EscapePattern(s)
    return (s:gsub("[%^%$%(%)%%%.%[%]%*%+%-%?]", "%%%0"))
end

-- Kiểm tra xem nhiệm vụ hiện tại có phải nhiệm vụ Boss (chỉ đánh 1 con Boss) hay không
local function IsActiveQuestBoss(targetFarmMob)
    -- Nếu quái đang định farm chính là mob này (ví dụ Swan Pirate), chắc chắn không phải boss cần bỏ qua
    if targetFarmMob and type(targetFarmMob) == "string" then
        local expLow = targetFarmMob:lower()
        if not AllBossMobs[expLow] then
            local qText = GetQuestText():lower()
            if qText:find(expLow, 1, true) or (getgenv()._lastStartedQuestMob == targetFarmMob and (tick() - (getgenv()._lastStartQuest or 0) < 300)) then
                return false, nil
            end
        end
    end

    -- 1. Kiểm tra GuideModule từ game:
    if GuideModule and GuideModule.Data and GuideModule.Data.QuestData and GuideModule.Data.QuestData.Task then
        for mobName, count in pairs(GuideModule.Data.QuestData.Task) do
            local cnt = tonumber(count) or 0
            if cnt > 1 then
                -- Yêu cầu diệt > 1 con quái (VD: 8 Swan Pirates) -> 100% là quái thường, không phải Boss!
                return false, nil
            elseif cnt == 1 then
                return true, tostring(mobName)
            end
        end
    end

    -- 2. Kiểm tra qua văn bản hiển thị trên GUI:
    local qText = GetQuestText():lower()
    if qText ~= "" then
        -- Nếu văn bản có chứa chỉ số của quái thường (0/8, 0/9, /8, /9, /7,...) -> 100% là quái thường!
        if qText:find("/[2-9]") or qText:find("/1[0-9]") or qText:find("%(0/[2-9]%)") or qText:find("8 ") or qText:find("9 ") then
            return false, nil
        end

        -- Nếu văn bản chứa quái thường (Swan Pirate, v.v.) thì loại trừ
        if qText:find("swan pirate") or qText:find("hải tặc swan") then
            return false, nil
        end

        for bossLower, _ in pairs(AllBossMobs) do
            -- Trường hợp đặc biệt: boss "swan" ở Sea 1 (Prison) không được nhận nhầm với "swan pirate" ở Sea 2
            if bossLower == "swan" and (qText:find("swan pirate") or qText:find("hải tặc swan") or qText:find("pirate")) then
                -- Bỏ qua
            else
                local pat = EscapePattern(bossLower)
                if qText:find("%f[%w]" .. pat .. "%f[%W]") then
                    if qText:find("/1%)") or qText:find(" 1 ") or qText:find("đánh bại 1") or qText:find("defeat 1") or not qText:find("/[2-9]") then
                        return true, bossLower
                    end
                end
            end
        end
    end
    return false, nil
end

local function GetActiveQuestMob()
    -- Ưu tiên 1: Lấy trực tiếp từ GuideModule.Data.QuestData.Task (chính xác 100% tên quái trong data game)
    if GuideModule and GuideModule.Data and GuideModule.Data.QuestData and GuideModule.Data.QuestData.Task then
        for mobName, count in pairs(GuideModule.Data.QuestData.Task) do
            if type(mobName) == "string" and mobName ~= "" and tonumber(count) ~= 1 then
                return mobName
            end
        end
    end

    -- Ưu tiên 2: Quét toàn bộ text trong Main.Quest và TrackedQuestFrame đối chiếu với AllQuestMobs (chỉ quái thường)
    local txt = GetQuestText():lower()
    if txt == "" then return nil end

    local best = nil
    for _, mn in ipairs(AllQuestMobs) do
        local pat = EscapePattern(mn:lower())
        if txt:find("%f[%w]" .. pat .. "s?%f[%W]") or txt:find(pat, 1, true) then
            if not best or #mn > #best then
                best = mn
            end
        end
    end
    return best
end

-- Lấy thông tin Quest tự động theo Level (CHỈ NHẬN NHIỆM VỤ QUÁI THƯỜNG, BỎ QUA 100% NHIỆM VỤ BOSS)
ExcludeQuests = {"BartiloQuest", "Trainees", "MarineQuest", "CitizenQuest"}

local function MakeQuestEntry(mob, mobs, qName, qId, qPos, mPos, sub)
    return {
        Mob = mob,
        Mobs = mobs or { mob },
        QuestName = qName,
        QuestId = qId,
        QuestPos = qPos,
        MobPos = mPos,
        Submerged = sub or false
    }
end

local function GetStaticNonBossQuestByLevel(lv)
    if World1 then
        -- Sea 1: Mọi mốc cấp của Boss (Lv 20 Gorilla King, Lv 55 Bobby, Lv 105 Yeti, Lv 130 Vice Admiral,
        -- Lv 220/230/240 Warden/Chief Warden/Swan, Lv 350 Magma Admiral, Lv 425 Fishman Lord,
        -- Lv 500 Wysper, Lv 575 Thunder God, Lv 675 Cyborg) đều được giữ ở nhiệm vụ quái thường trước đó!
        if lv >= 1 and lv <= 9 then
            return MakeQuestEntry("Bandit", {"Bandit"}, "BanditQuest1", 1, CFrame.new(1059.37, 15.45, 1550.42), CFrame.new(1045.96, 27.00, 1560.82))
        elseif lv >= 10 and lv <= 14 then
            return MakeQuestEntry("Monkey", {"Monkey"}, "JungleQuest", 1, CFrame.new(-1598.09, 35.55, 153.38), CFrame.new(-1448.52, 67.85, 11.47))
        elseif lv >= 15 and lv <= 29 then
            return MakeQuestEntry("Gorilla", {"Gorilla", "Monkey"}, "JungleQuest", 2, CFrame.new(-1598.09, 35.55, 153.38), CFrame.new(-1129.88, 40.46, -525.42))
        elseif lv >= 30 and lv <= 39 then
            return MakeQuestEntry("Pirate", {"Pirate"}, "BuggyQuest1", 1, CFrame.new(-1141.07, 4.10, 3831.55), CFrame.new(-1103.51, 13.75, 3896.09))
        elseif lv >= 40 and lv <= 59 then
            return MakeQuestEntry("Brute", {"Brute", "Pirate"}, "BuggyQuest1", 2, CFrame.new(-1141.07, 4.10, 3831.55), CFrame.new(-1140.08, 14.81, 4322.92))
        elseif lv >= 60 and lv <= 74 then
            return MakeQuestEntry("Desert Bandit", {"Desert Bandit"}, "DesertQuest", 1, CFrame.new(894.49, 5.14, 4392.43), CFrame.new(924.80, 6.45, 4481.59))
        elseif lv >= 75 and lv <= 89 then
            return MakeQuestEntry("Desert Officer", {"Desert Officer", "Desert Bandit"}, "DesertQuest", 2, CFrame.new(894.49, 5.14, 4392.43), CFrame.new(1608.28, 8.61, 4371.01))
        elseif lv >= 90 and lv <= 99 then
            return MakeQuestEntry("Snow Bandit", {"Snow Bandit"}, "SnowQuest", 1, CFrame.new(1389.74, 88.15, -1298.91), CFrame.new(1354.35, 87.27, -1393.95))
        elseif lv >= 100 and lv <= 119 then
