-- Force-load toàn bộ đảo trong Blox Fruits v30+ bằng tag LoDPosition (giúp load NPC & EnemySpawns ở mọi khoảng cách)
local function LoadIslandByFakePoint(target)
    pcall(function()
        local pos = nil
        if typeof(target) == "CFrame" then
            pos = target.Position
        elseif typeof(target) == "Vector3" then
            pos = target
        elseif target and type(target.GetPivot) == "function" then
            pos = target:GetPivot().Position
        elseif target and target:IsA("BasePart") then
            pos = target.Position
        end
        if pos then
            local p = Instance.new("Part")
            p.Transparency = 1
            p.CanCollide = false
            p.Anchored = true
            p.Size = Vector3.new(0, 0, 0)
            p.CFrame = CFrame.new(pos)
            CollectionService:AddTag(p, "LoDPosition")
            p.Parent = workspace.CurrentCamera
        end
    end)
end

task.spawn(function()
    pcall(function()
        for _, m in ipairs(workspace:GetChildren()) do
            if m:IsA("Model") and m:GetAttribute("LevelOfDetailDiameter") then
                LoadIslandByFakePoint(m)
            end
        end
        local mapFolder = workspace:FindFirstChild("Map")
        if mapFolder then
            for _, m in ipairs(mapFolder:GetChildren()) do
                if m:IsA("Model") then
                    LoadIslandByFakePoint(m)
                end
            end
        end
        local fakeIslands = ReplicatedStorage:FindFirstChild("FakeIslands")
        if fakeIslands then
            for _, m in ipairs(fakeIslands:GetChildren()) do
                if m:IsA("Model") then
                    LoadIslandByFakePoint(m)
                end
            end
        end
    end)
end)

-- Bộ nhớ đệm toàn bộ điểm Spawn thực tế của quái từ workspace._WorldOrigin.EnemySpawns & getnilinstances()
local TableMobSpawn = {}
local function CleanMobName(rawName)
    if type(rawName) ~= "string" then return "" end
    return (rawName:gsub(" %p?Lv%.? %d+%p?", ""):gsub("^%s+", ""):gsub("%s+$", ""))
end

local function RefreshMobSpawnCache()
    local seen = {}
    for _, part in ipairs(TableMobSpawn) do
        seen[part] = true
    end
    pcall(function()
        local origins = workspace:FindFirstChild("_WorldOrigin")
        local es = origins and origins:FindFirstChild("EnemySpawns")
        if es then
            for _, child in ipairs(es:GetChildren()) do
                if child:IsA("BasePart") and not seen[child] then
                    seen[child] = true
                    table.insert(TableMobSpawn, child)
                end
            end
        end
    end)
    pcall(function()
        if getnilinstances then
            for _, inst in ipairs(getnilinstances()) do
                if inst:IsA("BasePart") and not seen[inst] and (inst:GetAttribute("DisplayName") or string.find(inst.Name, "Lv%.")) then
                    seen[inst] = true
                    table.insert(TableMobSpawn, inst)
                end
            end
        end
    end)
end

task.spawn(function()
    RefreshMobSpawnCache()
    pcall(function()
        local origins = workspace:WaitForChild("_WorldOrigin", 10)
        local es = origins and origins:WaitForChild("EnemySpawns", 10)
        if es then
            es.ChildAdded:Connect(function(child)
                if child:IsA("BasePart") then
                    table.insert(TableMobSpawn, child)
                end
            end)
        end
    end)
end)

local function PartMatchesMob(part, mobName)
    if not part or not part:IsA("BasePart") or not mobName or mobName == "" or part:FindFirstChild("Z9_IgnoreSpawn") then
        return false
    end
    local cleanTarget = string.lower(CleanMobName(mobName))
    local cleanPart = string.lower(CleanMobName(part.Name))
    local disp = part:GetAttribute("DisplayName")
    local cleanDisp = disp and string.lower(CleanMobName(tostring(disp))) or nil
    -- Khớp chính xác hoặc số nhiều/số ít (VD: Isle Outlaw / Isle Outlaws)
    if cleanPart == cleanTarget or cleanPart == cleanTarget .. "s" or cleanPart .. "s" == cleanTarget
        or string.lower(part.Name) == string.lower(mobName)
        or (cleanDisp and (cleanDisp == cleanTarget or cleanDisp == cleanTarget .. "s")) then
        return true
    end
    if #cleanTarget >= 5 and (cleanPart:find(cleanTarget, 1, true) or cleanTarget:find(cleanPart, 1, true)) then
        if not cleanTarget:find("prisoner") or cleanPart == cleanTarget then
            return true
        end
    end
    return false
end

-- Tìm BasePart spawn thực tế của quái trên đảo (hỗ trợ đảo tuần tra qua nhiều bãi spawn cùng tên quái)
local function DetectPartSpawnMob(mobName, ignoreVisited)
    if not mobName or mobName == "" then return nil end

    -- 1. Quét trực tiếp trong workspace._WorldOrigin.EnemySpawns trước
    local origins = workspace:FindFirstChild("_WorldOrigin")
    local es = origins and origins:FindFirstChild("EnemySpawns")
    if es then
        for _, part in ipairs(es:GetChildren()) do
            if PartMatchesMob(part, mobName) and (not ignoreVisited or not part:FindFirstChild("Z9_SpawnVisited")) then
                return part
            end
        end
    end

    -- 2. Quét trong TableMobSpawn (bao gồm cả getnilinstances khi đảo ở xa)
    for _, part in ipairs(TableMobSpawn) do
        if PartMatchesMob(part, mobName) and (not ignoreVisited or not part:FindFirstChild("Z9_SpawnVisited")) then
            return part
        end
    end

    -- 3. Nếu chưa có trong cache thì làm mới cache từ getnilinstances()
    RefreshMobSpawnCache()
    for _, part in ipairs(TableMobSpawn) do
        if PartMatchesMob(part, mobName) and (not ignoreVisited or not part:FindFirstChild("Z9_SpawnVisited")) then
            return part
        end
    end

    return nil
end

local function ClearVisitedMobSpawns(mobName)
    local origins = workspace:FindFirstChild("_WorldOrigin")
    local es = origins and origins:FindFirstChild("EnemySpawns")
    if es then
        for _, part in ipairs(es:GetChildren()) do
            if not mobName or PartMatchesMob(part, mobName) then
                local v = part:FindFirstChild("Z9_SpawnVisited")
                if v then v:Destroy() end
            end
        end
    end
    for _, part in ipairs(TableMobSpawn) do
        if not mobName or PartMatchesMob(part, mobName) then
            local v = part:FindFirstChild("Z9_SpawnVisited")
            if v then v:Destroy() end
        end
    end
end

local function FindMobSpawnCFrame(mobName)
    local sp = DetectPartSpawnMob(mobName, false)
    if sp then
        return sp.CFrame
    end
    for _, m in ipairs(ReplicatedStorage:GetChildren()) do
        if m:IsA("Model") and m.Name == mobName and m:FindFirstChild("HumanoidRootPart") then
            return m.HumanoidRootPart.CFrame
        end
    end
    return nil
end

local function GetQuestByLevel()
    local lv = plr.Data.Level.Value

    -- Lấy nhiệm vụ tĩnh chuẩn làm nền tảng đảm bảo luôn có dữ liệu hợp lệ 100%
    local staticEntry = GetStaticNonBossQuestByLevel(lv)

    -- Ưu tiên 1: Tra cứu động từ GuideModule & QuestsModule
    local dynamicEntry = nil
    pcall(function()
        if QuestsModule and GuideModule and GuideModule.Data and GuideModule.Data.NPCList and not (World3 and lv >= 2600) then
            local effectiveLv = lv
            local levelMap = {}
            for qName, qList in pairs(QuestsModule) do
                if not table.find(ExcludeQuests, qName) and type(qList) == "table" then
                    for _, qData in pairs(qList) do
                        if type(qData) == "table" and qData.LevelReq and qData.Task then
                            local _, cnt = next(qData.Task)
                            if cnt and cnt > 1 then
                                levelMap[qData.LevelReq] = qName
                            end
                        end
                    end
                end
            end

            local bestLv = -1
            for npcInst, npcData in pairs(GuideModule.Data.NPCList) do
                if typeof(npcInst) ~= "Instance" or not npcInst.Parent or npcInst.Parent.Name ~= "Marine Leader" then
                    for qId, reqLv in pairs(npcData.Levels or {}) do
                        local qName = npcData.InternalQuestName or levelMap[reqLv]
                        if qName and not table.find(ExcludeQuests, qName) and QuestsModule[qName] then
                            local qEntry = QuestsModule[qName][qId]
                            if qEntry and qEntry.Task then
                                local mobName, count = next(qEntry.Task)
                                if count and count > 1 and not AllBossMobs[tostring(mobName):lower()] and reqLv <= effectiveLv and reqLv >= bestLv then
                                    local qPos = nil
                                    if typeof(npcData.Position) == "Vector3" then
                                        qPos = CFrame.new(npcData.Position)
                                    elseif typeof(npcData.Position) == "CFrame" then
                                        qPos = npcData.Position
                                    elseif staticEntry and staticEntry.QuestPos then
                                        qPos = staticEntry.QuestPos
                                    end

                                    if qPos then
                                        local validMobs = { mobName }
                                        if qId > 1 and QuestsModule[qName][qId - 1] and QuestsModule[qName][qId - 1].Task then
                                            for prevMob, prevCnt in pairs(QuestsModule[qName][qId - 1].Task) do
                                                if prevMob ~= mobName and prevCnt > 1 then
                                                    table.insert(validMobs, prevMob)
                                                    break
                                                end
                                            end
                                        end
                                        bestLv = reqLv
                                        dynamicEntry = {
                                            Mob = mobName,
                                            Mobs = validMobs,
                                            QuestName = qName,
                                            QuestId = qId,
                                            QuestPos = qPos,
                                            MobPos = (staticEntry and staticEntry.MobPos) or qPos
                                        }
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end)

    if dynamicEntry and dynamicEntry.QuestPos then
        return dynamicEntry
    end
    return staticEntry
end

-- Tìm quái gần nhất đang sống (Khớp chính xác tên quái & bỏ qua các NPC/Prisoner nhiệm vụ ẩn bất tử)
local function GetNearestAliveMob(mobName)
    local char = plr.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil end

    local enemies = workspace:FindFirstChild("Enemies")
    if not enemies then return nil end

    local bestMob, bestDist = nil, math.huge
    for _, mob in ipairs(enemies:GetChildren()) do
        if IsEnemyVulnerableAndValid(mob, mobName) then
            local mHrp = mob:FindFirstChild("HumanoidRootPart")
            if mHrp then
                local d = (mHrp.Position - hrp.Position).Magnitude
                if d < bestDist then
                    bestDist = d
                    bestMob = mob
                end
            end
        end
    end

    -- Nếu không tìm thấy mob nào do bị ignore tạm thời, nhưng trong Enemies vẫn còn quái sống khớp tên -> Xóa ignore tag để bot không bị đứng đợi quái
    if not bestMob then
        for _, mob in ipairs(enemies:GetChildren()) do
            local ig = mob:FindFirstChild("Z9_IgnoreMob")
            if ig and not mob:FindFirstChildWhichIsA("ProximityPrompt", true) and not mob:FindFirstChildWhichIsA("Dialog", true) then
                local hum = mob:FindFirstChildOfClass("Humanoid")
                local mHrp = mob:FindFirstChild("HumanoidRootPart")
                if hum and mHrp and hum.Health > 0 then
                    local cleanEnemy = string.lower(StripMobLevelTag(mob.Name))
                    local cleanReq = mobName and string.lower(StripMobLevelTag(mobName)) or ""
                    if cleanReq == "" or cleanEnemy == cleanReq or cleanEnemy == cleanReq .. "s" or cleanEnemy .. "s" == cleanReq or cleanEnemy:find(cleanReq, 1, true) then
                        ig:Destroy()
                        local d = (mHrp.Position - hrp.Position).Magnitude
                        if d < bestDist then
                            bestDist = d
                            bestMob = mob
                        end
                    end
                end
            end
        end
    end

    return bestMob
end

