local function ConvertFruitNameToStoreId(fruitDisplayName)
    if not fruitDisplayName or fruitDisplayName == "" or fruitDisplayName == "Fruit" or fruitDisplayName == "Fruit " then
        return nil
    end
    local clean = fruitDisplayName:gsub(" Fruit", "")
    if SpecialFruitIds[clean] then
        return SpecialFruitIds[clean]
    end
    return clean .. "-" .. clean
end

local function GetFruitStoreId(tool)
    if not tool then return nil end
    local orig = tool:GetAttribute("OriginalName")
    if orig and orig ~= "" then
        return orig
    end
    local eatRemote = tool:FindFirstChild("EatRemote", true)
    if eatRemote and eatRemote.Parent then
        local pOrig = eatRemote.Parent:GetAttribute("OriginalName")
        if pOrig and pOrig ~= "" then
            return pOrig
        end
    end
    return ConvertFruitNameToStoreId(tool.Name)
end

-- Lấy danh sách số lượng từng Trái Ác Quỷ đã lưu trong Kho Đồ của Player
local CachedStoredFruits = {}
local LastInvCheckTime = 0

local function GetStoredFruitsCountMap(forceRefresh)
    if not forceRefresh and (tick() - LastInvCheckTime < 3) then
        return CachedStoredFruits
    end
    LastInvCheckTime = tick()
    local counts = {}
    local success = false

    -- Ưu tiên 1: Đọc trực tiếp từ ItemReplicationService (Bản cập nhật mới nhất)
    if ItemReplicationService and ItemConfig and ItemReplicationService.KEYS then
        pcall(function()
            for _, item in ItemReplicationService:GetItems(ItemReplicationService.KEYS.QUANTITY) do
                if item.Value and item.Value > 0 then
                    local ok, cfg = pcall(function()
                        return ItemConfig.match(item.ItemId):unwrap()
                    end)
                    if ok and cfg and cfg.Display and cfg.Display.Category == "Blox Fruit" then
                        local key = (cfg.Index and cfg.Index.StorageKey) or cfg.Display.Name
                        if key then
                            counts[key] = item.Value
                            success = true
                        end
                    end
                end
            end
        end)
    end

    -- Ưu tiên 2: Fallback qua Remote getInventory nếu cần
    if not success then
        pcall(function()
            local inv = ReplicatedStorage.Remotes.CommF_:InvokeServer("getInventory")
            if type(inv) == "table" then
                for _, item in ipairs(inv) do
                    if item.Type == "Blox Fruit" and item.Name then
                        counts[item.Name] = item.Count or 1
                    end
                end
            end
        end)
    end

    CachedStoredFruits = counts
    return CachedStoredFruits
end

-- Kiểm tra xem Kho Đồ của Player còn chứa thêm được trái storeId này không (so với FruitCap)
local function CanStoreMoreOfFruit(storeId, forceRefresh)
    if not storeId or storeId == "" then return true end
    local data = plr:FindFirstChild("Data")
    local fruitCap = (data and data:FindFirstChild("FruitCap") and data.FruitCap.Value) or 1
    local storedMap = GetStoredFruitsCountMap(forceRefresh)
    local currentCount = storedMap[storeId] or 0
    return currentCount < fruitCap
end

-- Cất trái từ Balo / Nhân vật vào Kho (Chỉ cất khi Kho còn chỗ & không bao giờ spam cất lại trái đã đầy)
local function StoreFruitsFromContainer(container)
    if not container then return end
    for _, tool in ipairs(container:GetChildren()) do
        if tool:IsA("Tool") and not tool:FindFirstChild("Z9_StoreIgnored") and (tool.ToolTip == "Blox Fruit" or string.find(tool.Name, "Fruit") or tool:FindFirstChild("EatRemote", true)) then
            -- Nếu đây là trái mục tiêu cần ăn (ví dụ Buddha) và người chơi chưa ăn Buddha -> KHÔNG CẤT vào kho mà giữ lại để ăn!
            local shouldEat = false
            local ef = getgenv().SettingFarm and (getgenv().SettingFarm["Auto Eat Fruit"] or getgenv().SettingFarm.AutoEatFruit)
            if ef and ef["Enabled"] == true then
                local currentDf = plr:FindFirstChild("Data") and plr.Data:FindFirstChild("DemonFruit") and plr.Data.DemonFruit.Value or ""
                local targetFruitNames = ef["Fruit"] or { "Human-Human: Buddha", "Buddha-Buddha", "Light-Light" }
                if type(targetFruitNames) == "string" then targetFruitNames = { targetFruitNames } end
                local tName = string.lower(tool.Name)
                for _, fn in ipairs(targetFruitNames) do
                    local lfn = string.lower(fn)
                    if (string.find(tName, lfn) or (string.find(lfn, "buddha") and string.find(tName, "buddha"))) and not string.find(string.lower(currentDf), "buddha") then
                        -- Kiểm tra xem người chơi có đang dùng trái VIP không (nếu đang dùng trái VIP thì không ăn đè)
                        local isCurVip = false
                        local lCur = string.lower(currentDf)
                        for _, vip in ipairs({ "kitsune", "dragon", "leopard", "dough", "portal", "spirit", "venom", "shadow", "mammoth", "t-rex", "gas", "yeti", "blizzard", "sound", "control" }) do
                            if string.find(lCur, vip) then
                                isCurVip = true
                                break
                            end
                        end
                        if not isCurVip then
                            shouldEat = true
                            break
                        end
                    end
                end
            end
            if shouldEat then
                -- Bỏ qua không cất trái này, để V1StyleLookup.CheckAndEatTargetFruit() tự động ăn
            else
                local storeId = GetFruitStoreId(tool)
                if storeId then
                    if CanStoreMoreOfFruit(storeId, false) then
                        local storedOk = false
                        pcall(function()
                            local res = ReplicatedStorage.Remotes.CommF_:InvokeServer("StoreFruit", storeId, tool)
                            if res == true then
                                storedOk = true
                            end
                        end)
                        -- Cập nhật lại bộ nhớ đệm kho sau khi cất
                        GetStoredFruitsCountMap(true)
                        -- Nếu sau khi gọi StoreFruit mà trái vẫn nằm trên người (do kho đã đầy) -> Đánh dấu Z9_StoreIgnored để không spam nữa
                        if not storedOk and tool.Parent == container then
                            local tag = Instance.new("BoolValue")
                            tag.Name = "Z9_StoreIgnored"
                            tag.Parent = tool
                        end
                    else
                        -- Kho đã đạt giới hạn FruitCap cho trái này -> Đánh dấu bỏ qua ngay, không gọi StoreFruit
                        local tag = Instance.new("BoolValue")
                        tag.Name = "Z9_StoreIgnored"
                        tag.Parent = tool
                    end
                end
            end
        end
    end
end

local function AutoStoreAllFruits()
    if not IsSettingFruitStore() then return end
    -- Khi đang đi Raid kiếm điểm F mua võ hoặc đang lấy trái ra đổi Microchip thì KHÔNG tự cất trái lại vào kho
    if getgenv()._holdingFruitForRaidChip or getgenv()._isDoingRaidForF then return end
    pcall(function()
        StoreFruitsFromContainer(plr:FindFirstChild("Backpack"))
        StoreFruitsFromContainer(plr.Character)
    end)
end

-- Nhận diện tên trái spawn trên Map (cả Tool lẫn Model "Fruit ")
local function IdentifyMapFruitStoreId(obj)
    if not obj then return nil end
    if obj:IsA("Tool") then
        return GetFruitStoreId(obj)
    end
    local detectedName = nil
    for _, desc in ipairs(obj:GetDescendants()) do
        if desc:IsA("MeshPart") and MeshIdToFruitName[desc.MeshId] then
            detectedName = MeshIdToFruitName[desc.MeshId]
            break
        end
    end
    if not detectedName then
        local fModel = obj:FindFirstChild("Fruit")
        if fModel then
            if fModel:FindFirstChild("Retopo_Cube.001") then
                detectedName = "Spirit Fruit"
            elseif fModel:FindFirstChild("Gravity cube.026") then
                detectedName = fModel:FindFirstChild("Gravity cube.001") and "Blizzard Fruit" or "Portal Fruit"
            elseif fModel:FindFirstChild("Cube.011") then
                detectedName = "Rubber Fruit"
            end
        end
    end
    if detectedName then
        return ConvertFruitNameToStoreId(detectedName)
    end
    if obj.Name ~= "Fruit" and obj.Name ~= "Fruit " then
        return ConvertFruitNameToStoreId(obj.Name)
    end
    return nil
end

-- Kiểm tra xem trên người (Backpack/Character) đã cầm sẵn trái đó chưa
local function IsHoldingFruitStoreId(storeId)
    if not storeId then return false end
    for _, container in ipairs({plr:FindFirstChild("Backpack"), plr.Character}) do
        if container then
            for _, tool in ipairs(container:GetChildren()) do
                if tool:IsA("Tool") and GetFruitStoreId(tool) == storeId then
                    return true
                end
            end
        end
    end
    return false
end

