-- HỆ THỐNG AUTO RANDOM TRÁI ÁC QUỶ (COUSIN / ZIOLES GACHA)
-- Hỗ trợ: Auto di chuyển đến NPC Zioles khi sẵn sàng, tương tác Proximity/Dialog/UI Box,
-- click trực tiếp nút Random Fruit & nút Giá tiền Beli, gọi Remote, tự cất kho và hồi chiêu 2 giờ.
-- ==========================================
local GachaSystem = {}

function GachaSystem.GetCousinInfo()
    local candidates = { workspace:FindFirstChild("NPCs"), workspace, workspace:FindFirstChild("Map") }
    for _, cont in ipairs(candidates) do
        if cont then
            for _, obj in ipairs(cont:GetChildren()) do
                if obj:IsA("Model") then
                    local nm = string.lower(obj.Name)
                    if nm:find("cousin") or nm:find("gacha") or nm:find("zioles") then
                        local part = obj:FindFirstChild("HumanoidRootPart") or obj:FindFirstChild("Head") or obj:FindFirstChildWhichIsA("BasePart")
                        if part then
                            return part.CFrame, obj
                        end
                    end
                end
            end
        end
    end
    local npcsFolder = workspace:FindFirstChild("NPCs")
    if npcsFolder then
        for _, obj in ipairs(npcsFolder:GetDescendants()) do
            if obj:IsA("Model") then
                local nm = string.lower(obj.Name)
                if nm:find("cousin") or nm:find("gacha") or nm:find("zioles") then
                    local part = obj:FindFirstChild("HumanoidRootPart") or obj:FindFirstChild("Head") or obj:FindFirstChildWhichIsA("BasePart")
                    if part then
                        return part.CFrame, obj
                    end
                end
            end
        end
    end
    if World1 then
        return CFrame.new(-655.824, 15.5, 1436.679), nil
    elseif World2 then
        return CFrame.new(-385.6, 73.0, 298.0), nil
    elseif World3 then
        return CFrame.new(-12463.0, 332.0, -7560.0), nil
    end
    return nil, nil
end

function GachaSystem.GetCousinCFrame()
    local cf, _ = GachaSystem.GetCousinInfo()
    return cf
end

function GachaSystem.ParseCooldownFromText(text)
    if type(text) ~= "string" then return nil end
    local lower = string.lower(text)

    -- Nhận diện trực tiếp thông báo "Try again soon." của NPC Zioles khi gacha đang trong thời gian hồi chiêu
    if lower:find("try again soon") or lower:find("try again") then
        return 7200 -- Thời gian hồi chiêu chuẩn của Gacha Blox Fruit là 2 giờ (7200s)
    end

    local isCooldownMsg = lower:find("wait") or lower:find("cooldown") or lower:find("đợi")
        or lower:find("chờ") or lower:find("quay lại") or lower:find("again") or lower:find("hour")
        or lower:find("minute") or lower:find("phút") or lower:find("soon")

    local h, m, s = lower:match("(%d+):(%d+):(%d+)")
    if h and m and s then
        return tonumber(h) * 3600 + tonumber(m) * 60 + tonumber(s)
    end
    local m2, s2 = lower:match("(%d+):(%d+)")
    if isCooldownMsg and m2 and s2 then
        return tonumber(m2) * 60 + tonumber(s2)
    end

    if isCooldownMsg then
        local hours = tonumber(lower:match("(%d+)%s*hour")) or tonumber(lower:match("(%d+)%s*hr")) or tonumber(lower:match("(%d+)%s*giờ")) or tonumber(lower:match("(%d+)%s*h")) or 0
        local mins = tonumber(lower:match("(%d+)%s*min")) or tonumber(lower:match("(%d+)%s*phút")) or tonumber(lower:match("(%d+)%s*m")) or 0
        local secs = tonumber(lower:match("(%d+)%s*sec")) or tonumber(lower:match("(%d+)%s*giây")) or tonumber(lower:match("(%d+)%s*s")) or 0
        local total = (hours * 3600) + (mins * 60) + secs
        if total > 0 then
            return total
        end
        return 7200
    end
    return nil
end

function GachaSystem.ClearTryAgainNotification()
    pcall(function()
        local pg = plr:FindFirstChild("PlayerGui")
        if not pg then return end
        for _, desc in ipairs(pg:GetDescendants()) do
            if desc:IsA("TextLabel") and desc.Visible then
                local txt = string.lower(desc.Text or "")
                if txt:find("try again soon") or txt:find("try again") then
                    pcall(function()
                        desc.Text = ""
                        desc.Visible = false
                        local parent = desc.Parent
                        if parent and parent:IsA("GuiObject") and parent ~= pg then
                            parent.Visible = false
                        end
                        desc:Destroy()
                    end)
                end
            end
        end
    end)
end

function GachaSystem.CheckCooldownFromNotifications()
    local pg = plr:FindFirstChild("PlayerGui")
    if not pg then return nil end

    for _, desc in ipairs(pg:GetDescendants()) do
        if desc:IsA("TextLabel") and desc.Visible and desc.Text ~= "" then
            local cd = GachaSystem.ParseCooldownFromText(desc.Text)
            if cd then
                local low = string.lower(desc.Text)
                if low:find("try again soon") or low:find("try again") then
                    pcall(function()
                        desc.Text = ""
                        desc.Visible = false
                        local parent = desc.Parent
                        if parent and parent:IsA("GuiObject") and parent ~= pg then
                            parent.Visible = false
                        end
                        desc:Destroy()
                    end)
                end
                return cd
            end
        end
    end

    return nil
end

function GachaSystem.GetActiveDLCBoxName()
    local ok, bannerClient = pcall(function()
        return require(ReplicatedStorage.Controllers.BannerClient)
    end)
    if ok and type(bannerClient) == "table" and bannerClient.TryGetBannerItemIfActiveAsync then
        local banner = nil
        pcall(function() banner = bannerClient.TryGetBannerItemIfActiveAsync() end)
        if banner and banner.BoxName then
            return banner.BoxName
        end
    end
    return "DLCBoxData"
end

-- Tự động click dialogue [Random Fruit] và nút giá tiền Beli màu xanh trong Zioles' Gacha Box
function GachaSystem.InteractWithZiolesUI()
    local pg = plr:FindFirstChild("PlayerGui")
    if not pg then return false end
    local interacted = false

    -- 1. Click nút "Random Fruit" trong Menu Dialogue nếu đang mở (như ảnh người dùng gửi)
    for _, desc in ipairs(pg:GetDescendants()) do
        if desc:IsA("TextButton") or desc:IsA("ImageButton") or desc:IsA("TextLabel") then
            local txt = (desc:IsA("TextLabel") and desc.Text) or (desc:IsA("TextButton") and desc.Text) or ""
            local lowerTxt = string.lower(txt)
            if string.find(lowerTxt, "random fruit") and not string.find(lowerTxt, "spooky") then
                local btn = desc:IsA("GuiButton") and desc or desc:FindFirstAncestorWhichIsA("GuiButton")
                if btn and btn.Visible then
                    SafeClickGuiButton(btn)
                    interacted = true
                    task.wait(0.2)
                    break
                end
            end
        end
    end

    -- 2. Click nút giá tiền Beli trong popup "Zioles' Gacha Box" (nút màu xanh lá hoặc text số tiền dạng 161,950)
    for _, desc in ipairs(pg:GetDescendants()) do
        if desc.Visible then
            local txt = (desc:IsA("TextLabel") and desc.Text) or (desc:IsA("TextButton") and desc.Text) or ""
            local cleanTxt = string.gsub(txt, "[%s,%.%$]", "")
            local num = tonumber(cleanTxt)
            local isPriceText = num and num >= 25000 and num <= 10000000

            local btn = nil
            if desc:IsA("GuiButton") then
                btn = desc
            elseif isPriceText and desc:FindFirstAncestorWhichIsA("GuiButton") then
                btn = desc:FindFirstAncestorWhichIsA("GuiButton")
            end

            if btn and btn.Visible then
                local col = btn.BackgroundColor3
                local isGreenish = (col.G > 0.55 and col.G > col.R * 1.15 and col.G > col.B * 1.15)
                
                local inGachaBox = false
                local anc = btn.Parent
                while anc and anc ~= pg do
                    local nm = string.lower(anc.Name)
                    if nm:find("gacha") or nm:find("box") or nm:find("cousin") or nm:find("zioles") then
                        inGachaBox = true
                        break
                    end
                    anc = anc.Parent
                end

                if (isPriceText and (inGachaBox or isGreenish)) or (inGachaBox and isGreenish) then
                    SafeClickGuiButton(btn)
                    interacted = true
                    break
                end
            end
        end
    end

    return interacted
end

function GachaSystem.CloseSpinnerWindow()
    pcall(function()
        local Spinner = nil
        pcall(function()
            Spinner = require(game:GetService("ReplicatedStorage").Controllers.UI.Spinner)
        end)
        if Spinner and Spinner.Close then
            pcall(function() Spinner:Close() end)
        end

        local pg = plr:FindFirstChild("PlayerGui")
        if not pg then return end
        
        -- SpinnerWindow mặc định
        local spinner = pg:FindFirstChild("SpinnerWindow")
        if spinner and spinner.Enabled then
            local closeBtn = spinner:FindFirstChild("CloseButton", true)
                or (spinner:FindFirstChild("AboveSpinner") and spinner.AboveSpinner:FindFirstChild("Navigation") and spinner.AboveSpinner.Navigation:FindFirstChild("CloseButton"))
            if closeBtn and closeBtn.Visible then
                SafeClickGuiButton(closeBtn)
            end
            spinner.Enabled = false
        end

        -- Popup Zioles' Gacha Box & Dialogues: Tìm và bấm nút X hoặc Nevermind
        for _, g in ipairs(pg:GetChildren()) do
            if g:IsA("ScreenGui") and g.Enabled then
                local gName = string.lower(g.Name)
                if gName:find("gacha") or gName:find("cousin") or gName:find("dialog") then
                    for _, btn in ipairs(g:GetDescendants()) do
                        if (btn:IsA("TextButton") or btn:IsA("ImageButton")) and btn.Visible then
                            local txt = string.lower(btn.Text or "")
                            if txt == "x" or txt == "close" or txt:find("nevermind") then
                                SafeClickGuiButton(btn)
                            end
                        end
                    end
                end
            end
        end
    end)
end

local function CloseSpinnerWindow()
    GachaSystem.CloseSpinnerWindow()
end

-- Gọi remote an toàn có giới hạn thời gian (không bao giờ làm treo luồng game)
function GachaSystem.SafeInvoke(timeout, ...)
    local args = { ... }
    local done = false
    local result = nil
    task.spawn(function()
        pcall(function()
            result = ReplicatedStorage.Remotes.CommF_:InvokeServer(unpack(args))
        end)
        done = true
    end)
    local start = tick()
    while not done and (tick() - start) < timeout do
        task.wait(0.05)
    end
    return result
end

-- Kiểm tra chính xác xem Player đã random trái chưa (Hỏi server qua CheckTime để tránh spam vô nghĩa)
function GachaSystem.CheckCanRoll()
    local pData = plr:FindFirstChild("Data")
    local curLv = pData and pData:FindFirstChild("Level") and pData.Level.Value or 0
    local curBeli = pData and pData:FindFirstChild("Beli") and pData.Beli.Value or 0
    local reqCost = GetFruitGachaCost(curLv)

    if curLv < 50 then
        return false, "Cần Cấp 50+"
    end
    if curBeli < reqCost then
        return false, "Thiếu tiền (" .. FormatCostShort(reqCost, 0) .. ")"
    end

    -- Nếu đang trong thời gian hồi chiêu đã ghi nhận
    if tick() < NextRandomFruitTick then
        local rem = math.ceil((NextRandomFruitTick - tick()) / 60)
        local h = math.floor(rem / 60)
        local m = rem % 60
        local txt = (h > 0) and string.format("Chờ %dh %02dm", h, m) or string.format("Chờ %d phút", m)
        return false, txt
    end

    local boxName = GachaSystem.GetActiveDLCBoxName() or "DLCBoxData"

    -- 1. Hỏi Server game Blox Fruits qua remote "Cousin" - "CheckTime"
    -- Nếu chưa random (sẵn sàng): Server trả về đúng true!
    -- Nếu đã random rồi (đang hồi chiêu): Server KHÔNG trả về true (trả về false hoặc chuỗi thời gian còn lại)
    local checkTimeRes = GachaSystem.SafeInvoke(1.0, "Cousin", "CheckTime", boxName)
    if checkTimeRes == true then
        return true, "Sẵn sàng"
    elseif checkTimeRes ~= nil then
        -- Server thông báo chưa thể random (đã random rồi hoặc đang hồi chiêu)
        local cd = nil
        if type(checkTimeRes) == "number" and checkTimeRes > 0 then
            cd = checkTimeRes
        elseif type(checkTimeRes) == "string" then
            cd = GachaSystem.ParseCooldownFromText(checkTimeRes)
        end

        if cd and cd > 0 then
            NextRandomFruitTick = tick() + cd
            local remM = math.ceil(cd / 60)
            local remH = math.floor(remM / 60)
            local remM2 = remM % 60
            local txt = (remH > 0) and string.format("Chờ %dh %02dm", remH, remM2) or string.format("Chờ %d phút", remM2)
            return false, txt
        else
            -- Server báo chưa sẵn sàng -> Set tối thiểu 30 phút để tuyệt đối không spam
            NextRandomFruitTick = tick() + 1800
            return false, "Đang hồi chiêu (Chờ 30m)"
        end
    end

    -- 2. Kiểm tra thông báo trên giao diện xem có text hồi chiêu không
    local notifCd = GachaSystem.CheckCooldownFromNotifications()
    if notifCd and notifCd > 0 then
        NextRandomFruitTick = tick() + notifCd
        local remM = math.ceil(notifCd / 60)
        return false, string.format("Chờ %d phút", remM)
    end

    return true, "Sẵn sàng"
end

function GachaSystem.ExecuteBackgroundRoll()
    if not IsSettingFruitRandom() or getgenv()._isDoingRaidForF or CurrentTargetFruit ~= nil then
        return false
    end

    local pData = plr:FindFirstChild("Data")
    local curLv = pData and pData:FindFirstChild("Level") and pData.Level.Value or 0
    local curBeli = pData and pData:FindFirstChild("Beli") and pData.Beli.Value or 0
    local reqCost = GetFruitGachaCost(curLv)

    if curLv < 50 or curBeli < reqCost or tick() < NextRandomFruitTick then
        return false
    end

    -- Kiểm tra trước xem player đã random chưa, nếu đã random rồi thì dừng ngay không spam!
    local canRoll, reason = GachaSystem.CheckCanRoll()
    if not canRoll then
        return false
    end

    local beliBefore = curBeli
    local rolled = false
    local res = nil

    -- 1. Chạy thẳng lệnh mua gacha từ xa chuẩn Banana Cat Hub (RF/GachaNetworkRF - ZiolesGacha)
    pcall(function()
        local net = ReplicatedStorage:FindFirstChild("Modules") and ReplicatedStorage.Modules:FindFirstChild("Net")
        local gachaNet = net and net:FindFirstChild("RF/GachaNetworkRF")
        if gachaNet then
            res = gachaNet:InvokeServer({
                Context = "Purchase",
                BoxName = "ZiolesGacha",
            })
            if type(res) == "table" and res.Success == true then
                rolled = true
            elseif res == 1 or res == true then
                rolled = true
            end
        end
    end)

    -- 2. Dự phòng thêm các remote Cousin chuẩn game nếu RF/GachaNetworkRF chưa có
    if not rolled then
        local boxName = GachaSystem.GetActiveDLCBoxName() or "DLCBoxData"
        local r1 = GachaSystem.SafeInvoke(0.8, "Cousin", boxName)
        if r1 == 1 or r1 == true or (type(r1) == "table" and r1.Success) then
            rolled = true
            res = r1
        else
            local r2 = GachaSystem.SafeInvoke(0.8, "Cousin", "Buy")
            if r2 == 1 or r2 == true or (type(r2) == "table" and r2.Success) then
                rolled = true
                res = r2
            end
        end
    end

    task.wait(0.4)
    local pDataAfter = plr:FindFirstChild("Data")
    local beliAfter = (pDataAfter and pDataAfter:FindFirstChild("Beli") and pDataAfter.Beli.Value) or curBeli

    if beliAfter < beliBefore then
        -- MUA THÀNH CÔNG: Tiền Beli đã giảm thật sự -> Khóa hồi chiêu 2 giờ (7200s)!
        NextRandomFruitTick = tick() + 7200
        GachaSystem.CloseSpinnerWindow()
        AutoStoreAllFruits()
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = "Gacha Blox Fruit",
                Text = "Quay trái thành công (-$" .. FormatCostShort(beliBefore - beliAfter, 0) .. ")! Đã cất vào kho.",
                Duration = 5
            })
        end)
        return true
    end

    -- Tiền chưa giảm: tức là player đã random rồi hoặc server từ chối
    local cd = GachaSystem.ParseCooldownFromText(res) or GachaSystem.CheckCooldownFromNotifications()
    if cd and cd > 0 then
        NextRandomFruitTick = tick() + cd
    else
        -- Đã random rồi: set tối thiểu 30 phút để tuyệt đối không spam
        NextRandomFruitTick = tick() + 1800
    end
    GachaSystem.CloseSpinnerWindow()
    return false
end

-- Bước xử lý Gacha chính trong AutoFarm Loop (Tự động di chuyển tới trước mặt NPC Zioles để tương tác)
function GachaSystem.DoStep(hrp, hum)
    if not IsSettingFruitRandom() or getgenv()._isDoingRaidForF or CurrentTargetFruit ~= nil then
        return false
    end

    local pData = plr:FindFirstChild("Data")
    local curLv = pData and pData:FindFirstChild("Level") and pData.Level.Value or 0
    local curBeli = pData and pData:FindFirstChild("Beli") and pData.Beli.Value or 0
    local reqCost = GetFruitGachaCost(curLv)

    if curLv < 50 or curBeli < reqCost or tick() < NextRandomFruitTick then
        return false
    end

    -- KIỂM TRA QUAN TRỌNG: Xem player đã random chưa. Nếu rồi thì KHÔNG di chuyển tới NPC, KHÔNG spam!
    local canRoll, reason = GachaSystem.CheckCanRoll()
    if not canRoll then
        return false
    end

    -- Thử quay từ xa theo Banana Cat Hub trước (không làm gián đoạn farm)
    local beliBefore = curBeli
    local rolledBg = GachaSystem.ExecuteBackgroundRoll()
    local beliAfter = (pData and pData:FindFirstChild("Beli") and pData.Beli.Value) or curBeli
    if (beliAfter < beliBefore) or rolledBg or tick() < NextRandomFruitTick then
        return false
    end

    local cousinCF, cousinModel = GachaSystem.GetCousinInfo()
    if not cousinCF then
        return false
    end

    -- Vị trí đứng chuẩn: Đứng ngay trên mặt sàn phía trước mặt NPC Zioles (ngay trên vòng tròn tương tác màu xanh)
    local standCF = cousinCF * CFrame.new(0, -0.2, -3.8) * CFrame.Angles(0, math.pi, 0)
    local dist = (standCF.Position - hrp.Position).Magnitude

    if dist > 15 then
        CurrentFarmStatus = "[Random Trái] Đang di chuyển đến NPC Blox Fruit Gacha (Zioles)..."
        TweenTo(standCF)
        return true
    end

    -- Đã đứng ngay trước mặt NPC Zioles trên vòng tròn tương tác
    CurrentFarmStatus = "[Random Trái] Đang tương tác với Zioles để quay trái ác quỷ..."
    if getgenv().StopTween then getgenv().StopTween() end
    hrp.CFrame = standCF
    pcall(function() hrp.Velocity = Vector3.new(0, 0, 0) end)

    -- 1. Chạm vào NPC & vòng tròn tương tác trên sàn để kích hoạt sự kiện Touch
    pcall(function()
        if firetouchinterest and cousinModel then
            for _, p in ipairs(cousinModel:GetDescendants()) do
                if p:IsA("BasePart") then
                    firetouchinterest(hrp, p, 0)
                    task.wait()
                    firetouchinterest(hrp, p, 1)
                end
            end
        end
    end)

    -- 2. Kích hoạt ClickDetector / ProximityPrompt của NPC nếu có
    pcall(function()
        if cousinModel then
            for _, obj in ipairs(cousinModel:GetDescendants()) do
                if obj:IsA("ClickDetector") and fireclickdetector then
                    fireclickdetector(obj)
                elseif obj:IsA("ProximityPrompt") and fireproximityprompt then
                    fireproximityprompt(obj)
                end
            end
        end
    end)

    -- 3. Khởi chạy DialogueController (mở menu đối thoại Zioles chuẩn của Blox Fruits)
    pcall(function()
        local dList = require(ReplicatedStorage.DialoguesList)
        local dCtrl = require(ReplicatedStorage.DialogueController)
        if dList and dCtrl and dCtrl.Start then
            for k, v in pairs(dList) do
                local lk = string.lower(tostring(k))
                if lk:find("zioles") or lk:find("cousin") or lk:find("gacha") then
                    dCtrl:Start(v)
                    break
                end
            end
        end
    end)

    -- 4. Bấm trực tiếp nút GUI [Random Fruit] hoặc nút Giá tiền Beli
    GachaSystem.InteractWithZiolesUI()

    -- 5. Gọi đồng thời các Remote mua chuẩn với cơ chế SafeInvoke không bao giờ treo
    local boxName = GachaSystem.GetActiveDLCBoxName() or "DLCBoxData"
    local res = GachaSystem.SafeInvoke(0.8, "Cousin", boxName)

    if res ~= 1 and res ~= true then
        res = GachaSystem.SafeInvoke(0.8, "Cousin", "Buy")
    end

    task.wait(0.2)
    GachaSystem.InteractWithZiolesUI()
    task.wait(0.3)

    local pDataAfter = plr:FindFirstChild("Data")
    local beliAfterFinal = (pDataAfter and pDataAfter:FindFirstChild("Beli") and pDataAfter.Beli.Value) or curBeli

    if beliAfterFinal < beliBefore then
        -- Mua thành công! Beli đã giảm thật sự -> Hồi chiêu 2 giờ
        NextRandomFruitTick = tick() + 7200
        GachaSystem.CloseSpinnerWindow()
        AutoStoreAllFruits()
        CurrentFarmStatus = "[Random Trái] ✅ Quay trái thành công! Đang quay lại farm..."
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = "Gacha Blox Fruit",
                Text = "Quay trái thành công (-$" .. FormatCostShort(beliBefore - beliAfterFinal, 0) .. ")! Đã cất vào kho.",
                Duration = 5
            })
        end)
        return false -- Tiếp tục farm quái bình thường
    end

    -- Nếu tiền chưa giảm: kiểm tra thông báo hồi chiêu từ server hoặc dialogue
    local cd = GachaSystem.ParseCooldownFromText(res) or GachaSystem.CheckCooldownFromNotifications()
    if cd and cd > 0 then
        NextRandomFruitTick = tick() + cd
    else
        -- Đã random rồi: tạm hoãn ít nhất 30 phút để tuyệt đối không spam NPC
        NextRandomFruitTick = tick() + 1800
    end

    GachaSystem.CloseSpinnerWindow()
    CurrentFarmStatus = "[Random Trái] Đang trong thời gian hồi chiêu -> Quay lại farm..."
    return false -- Tiếp tục farm, không bị kẹt đứng yên
end

-- ==========================================
-- HỆ THỐNG TỰ ĐỘNG SĂN & MUA TRÁI ÁC QUỶ TRONG SHOP (SNIPER FRUIT SHOP)
-- Tự động kiểm tra kho hàng của Blox Fruit Dealer (Shop Thường) và Advanced Fruit Dealer (Shop Mirage Island).
-- Khi phát hiện các trái mục tiêu (Kitsune, Dragon, Leopard, Yeti, Gas...) đang OnSale và người chơi đủ Beli -> Mua ngay lập tức!
-- ==========================================
local SniperShopSystem = {}

function SniperShopSystem.IsEnabled()
    if getgenv().SettingFarm then
        local sf = getgenv().SettingFarm["Sniper Fruit Shop"] or getgenv().SettingFarm.SniperFruitShop
        if type(sf) == "table" and sf["Enabled"] ~= nil then
            return sf["Enabled"] == true
        end
    end
    return false
end

function SniperShopSystem.GetTargetMap()
    local map = {}
    local list = nil
    if getgenv().SettingFarm then
        local sf = getgenv().SettingFarm["Sniper Fruit Shop"] or getgenv().SettingFarm.SniperFruitShop
        if type(sf) == "table" and type(sf["Fruit"]) == "table" then
            list = sf["Fruit"]
        end
    end
    list = list or {"Leopard-Leopard", "Kitsune-Kitsune", "Dragon-Dragon", "Yeti-Yeti", "Gas-Gas"}
    for _, f in ipairs(list) do
        local str = tostring(f):lower():gsub("%s+", "")
        map[str] = true
        local short = str:split("-")[1]
        if short then map[short] = true end
    end
    return map
end

function SniperShopSystem.CheckAndBuy()
    if not SniperShopSystem.IsEnabled() then return end
    local targetMap = SniperShopSystem.GetTargetMap()
    local curBeli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
    if curBeli < 100000 then return end -- Tiền quá ít không đủ mua trái VIP

    -- Duyệt cả Shop Thường (false) và Shop Mirage (true)
    for _, isMirage in ipairs({false, true}) do
        local ok, fruitList = pcall(function()
            return ReplicatedStorage.Remotes.CommF_:InvokeServer("GetFruits", isMirage)
        end)

        if ok and type(fruitList) == "table" then
            for _, fruit in pairs(fruitList) do
                if type(fruit) == "table" and fruit.OnSale == true and fruit.Price and curBeli >= fruit.Price then
                    local fName = tostring(fruit.Name or "")
                    local fKey = fName:lower():gsub("%s+", "")
                    local fShort = (fName:split("-")[1] or ""):lower():gsub("%s+", "")

                    if targetMap[fKey] or targetMap[fShort] then
                        local shopTag = isMirage and "Shop Mirage" or "Shop Thường"
                        pcall(function()
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("PurchaseRawFruit", fName)
                        end)
                        CurrentFarmStatus = "[Sniper Shop] 🎉 Đã mua thành công trái " .. fName .. " (" .. shopTag .. " - $" .. FormatNumber(fruit.Price) .. ")!"
                        task.wait(0.5)
                        if type(AutoStoreAllFruits) == "function" then pcall(AutoStoreAllFruits) end
                        break
                    end
                end
            end
        end
    end
end

-- Chạy ngầm định kỳ mỗi 30 giây để tự động săn trái mà không tốn tài nguyên
task.spawn(function()
    task.wait(10)
    while true do
        pcall(SniperShopSystem.CheckAndBuy)
        task.wait(30)
    end
end)

-- Bảng lưu các trái trên Map đã nhặt/xử lý xong hoặc kho đã đầy để không bao giờ bị kẹt lại
local IgnoredMapFruits = setmetatable({}, { __mode = "k" })

-- Tìm trái ác quỷ spawn trên Map gần nhất còn nhặt được & kho còn chứa được
local function GetSpawnedFruitOnMap()
    local char = plr.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local bestFruit, bestDist = nil, math.huge

    for _, obj in ipairs(workspace:GetChildren()) do
        if not IgnoredMapFruits[obj] and (obj:IsA("Tool") or obj:IsA("Model")) and string.find(obj.Name, "Fruit") and not obj:FindFirstChild("Z9_IgnoreFruit") then
            local handle = obj:FindFirstChild("Handle")
            local hasTouch = handle and (handle:FindFirstChildOfClass("TouchTransmitter") or handle:FindFirstChild("TouchInterest"))
            if handle and handle:IsA("BasePart") and hasTouch and handle.Position.Y > -500 then
                -- Kiểm tra xem trái trên Map này trong kho đồ của Player còn chứa thêm được không (nếu kho đã đầy trái này thì bỏ qua luôn)
                local mapStoreId = IdentifyMapFruitStoreId(obj)
                if mapStoreId and not CanStoreMoreOfFruit(mapStoreId, false) then
                    IgnoredMapFruits[obj] = true
                else
                    if hrp then
                        local d = (handle.Position - hrp.Position).Magnitude
                        if d < bestDist then
                            bestDist = d
                            bestFruit = obj
                        end
                    else
                        return obj
                    end
                end
            end
        end
    end
    return bestFruit
end

