-- Tự động theo dõi và xóa sạch thông báo "Try again soon." của Zioles Gacha khi xuất hiện trên màn hình
pcall(function()
    local pg = plr:WaitForChild("PlayerGui", 5)
    if not pg then return end

    local function handleGachaTryAgain(lbl)
        if not lbl:IsA("TextLabel") then return end
        local txt = string.lower(lbl.Text or "")
        if txt:find("try again soon") or txt:find("try again") then
            -- Nhận diện ngay Zioles Gacha đang hồi chiêu: Khóa 2 giờ (7200s) để tuyệt đối không spam
            NextRandomFruitTick = math.max(NextRandomFruitTick, tick() + 7200)
            pcall(function()
                lbl.Text = ""
                lbl.Visible = false
                local parent = lbl.Parent
                if parent and parent:IsA("GuiObject") and parent ~= pg then
                    parent.Visible = false
                end
                lbl:Destroy()
            end)
        end
    end

    pg.DescendantAdded:Connect(function(desc)
        pcall(function()
            handleGachaTryAgain(desc)
            if desc:IsA("TextLabel") then
                desc:GetPropertyChangedSignal("Text"):Connect(function()
                    pcall(handleGachaTryAgain, desc)
                end)
            end
        end)
    end)

    for _, desc in ipairs(pg:GetDescendants()) do
        if desc:IsA("TextLabel") then
            pcall(function()
                handleGachaTryAgain(desc)
                desc:GetPropertyChangedSignal("Text"):Connect(function()
                    pcall(handleGachaTryAgain, desc)
                end)
            end)
        end
    end
end)

