-- =========================================================================
-- HỆ THỐNG TỰ ĐỘNG THU THẬP BERRY TRONG BỤI CÂY (AUTO COLLECT BERRIES)
-- Cơ chế: Quét toàn bộ CollectionService "BerryBush" trên map.
-- Nếu phát hiện có Berry xuất hiện trong bụi: Tạm dừng farm cấp để nhặt hết toàn bộ.
-- Khi hết sạch Berry trên map: Tự động quay trở lại farm cấp/nhiệm vụ như cũ.
-- Có hệ thống lưu trữ tiến độ (Z9_BerryProgress_<UserId>.json) ghi nhận tổng số Berry đã nhặt.
-- =========================================================================
local BerrySystem = {}
getgenv().Z9_BerrySystem = BerrySystem
BerrySystem.File = "Z9_BerryProgress_" .. tostring((plr and plr.UserId) or "Global") .. ".json"
BerrySystem.Data = {
    TotalCollected = 0,
    LastCollected = 0,
    BerryTypes = {}
}
BerrySystem.IgnoredBushes = {}
BerrySystem.AttemptCounts = {}
BerrySystem.CurrentBush = nil
BerrySystem.TouchTimer = nil

function BerrySystem.Save()
    pcall(function()
        if writefile then
            local data = {
                TotalCollected = BerrySystem.Data.TotalCollected or 0,
                LastCollected = BerrySystem.Data.LastCollected or 0,
                BerryTypes = BerrySystem.Data.BerryTypes or {}
            }
            writefile(BerrySystem.File, HttpService:JSONEncode(data))
        end
    end)
end

function BerrySystem.Load()
    pcall(function()
        if isfile and readfile and isfile(BerrySystem.File) then
            local raw = readfile(BerrySystem.File)
            if raw and raw ~= "" then
                local data = HttpService:JSONDecode(raw)
                if data and type(data) == "table" then
                    BerrySystem.Data.TotalCollected = tonumber(data.TotalCollected) or 0
                    BerrySystem.Data.LastCollected = tonumber(data.LastCollected) or 0
                    BerrySystem.Data.BerryTypes = (type(data.BerryTypes) == "table" and data.BerryTypes) or {}
                end
            end
        end
    end)
end

function BerrySystem.AddBerry(bType)
    BerrySystem.Data.TotalCollected = (BerrySystem.Data.TotalCollected or 0) + 1
    BerrySystem.Data.LastCollected = os.time()
    bType = tostring(bType or "Berry")
    BerrySystem.Data.BerryTypes[bType] = (BerrySystem.Data.BerryTypes[bType] or 0) + 1
    BerrySystem.Save()
end

function BerrySystem.HasBerry(bush)
    if not bush or not bush.Parent then return false, nil end

    -- Bỏ qua nếu bụi này đang bị tạm khóa (do lỗi kẹt/không thể nhặt)
    if BerrySystem.IgnoredBushes[bush] and (tick() - BerrySystem.IgnoredBushes[bush] < 60) then
        return false, nil
    end

    -- 1. Kiểm tra Attributes của Bush (Cơ chế chuẩn của Blox Fruits: bush:GetAttributes() chứa tên Berry tại các slot)
    local attrs = bush:GetAttributes()
    if attrs then
        for _, v in pairs(attrs) do
            if v and v ~= "" and v ~= false then
                return true, tostring(v)
            end
        end
    end

    -- 2. Kiểm tra trực tiếp các quả Berry con trong bush:GetChildren()
    for _, child in ipairs(bush:GetChildren()) do
        local p = child:FindFirstChild("ProximityPrompt") or child:FindFirstChildWhichIsA("ProximityPrompt", true)
        if p and p.Enabled then
            return true, tostring(p.ObjectText ~= "" and p.ObjectText or p.ActionText ~= "" and p.ActionText or child.Name)
        end
    end

    return false, nil
end

function BerrySystem.GetPivotOrCFrame(obj)
    if not obj then return nil end
    local cf = nil
    pcall(function()
        if obj:IsA("Model") then
            cf = obj.WorldPivot or obj:GetPivot()
        elseif obj:IsA("BasePart") then
            cf = obj.CFrame
        elseif obj.Parent then
            if obj.Parent:IsA("Model") then
                cf = obj.Parent.WorldPivot or obj.Parent:GetPivot()
            elseif obj.Parent:IsA("BasePart") then
                cf = obj.Parent.CFrame
            end
        end
    end)
    if not cf and obj.Parent then
        pcall(function()
            local attrCF = obj.Parent:GetAttribute("CFrame")
            if typeof(attrCF) == "CFrame" then
                cf = attrCF
            end
        end)
    end
    return cf
end

-- Lấy chính xác Model quả Berry con bên trong bush:GetChildren() cùng tọa độ WorldPivot và ProximityPrompt của quả Berry đó
function BerrySystem.GetBerryChildAndCF(bush)
    if not bush then return nil, nil, nil end
    for _, child in ipairs(bush:GetChildren()) do
        local prompt = child:FindFirstChild("ProximityPrompt") or child:FindFirstChildWhichIsA("ProximityPrompt", true)
        local childCF = nil
        pcall(function()
            if child:IsA("Model") then
                childCF = child.WorldPivot or child:GetPivot()
            elseif child:IsA("BasePart") then
                childCF = child.CFrame
            end
        end)
        if not childCF and prompt and prompt.Parent and prompt.Parent:IsA("BasePart") then
            childCF = prompt.Parent.CFrame
        end
        if childCF then
            return child, childCF, prompt
        end
    end
    return nil, nil, nil
end

function BerrySystem.GetActiveBushes()
    local result = {}
    if not CollectionService then return result end
    local tagged = CollectionService:GetTagged("BerryBush")
    for _, bush in ipairs(tagged) do
        local has, bName = BerrySystem.HasBerry(bush)
        if has then
            table.insert(result, { Bush = bush, Name = bName })
        end
    end
    return result
end

function BerrySystem.GetStatusText()
    local enabled = IsAutoBerriesEnabled()
    local statusStr = enabled and "🟢 Bật" or "🔴 Tắt trong cài đặt"
    local total = (BerrySystem.Data and BerrySystem.Data.TotalCollected) or 0
    local activeCount = #BerrySystem.GetActiveBushes()
    local activeDesc = (activeCount > 0)
        and ("🟡 Có " .. tostring(activeCount) .. " bụi có Berry trên map (Đang ưu tiên nhặt)")
        or "⚪ Không có Berry trên map (Đang farm cấp bình thường)"
    return "• Trạng thái: " .. statusStr ..
           "\n• Đã thu thập: " .. FormatNumber(total) .. " Berry" ..
           "\n• Bản đồ hiện tại: " .. activeDesc
end

function BerrySystem.DoStep(hrp, hum)
    if not IsAutoBerriesEnabled() then return false end

    -- ƯU TIÊN SỰ KIỆN: Khi đang bật Sự Kiện Halloween và chưa gom đủ 500 Kẹo Ngô -> TUYỆT ĐỐI không đi nhặt Berry
    local curCandies = (HW and HW.GetEventCandies and HW.GetEventCandies()) or 0
    local maxCandies = (HW and HW.GetMaxCandy and HW.GetMaxCandy()) or 500
    if IsAutoHalloweenEnabled() and curCandies < maxCandies then
        return false
    end

    -- Acc cấp 1 ưu tiên farm cấp lên 50 trước khi đi nhặt quả Berry
    local pLv = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0
    local minHwLv = (HW and HW.GetMinLevel and HW.GetMinLevel()) or 50
    if pLv < minHwLv then return false end

    -- Quét tất cả các bụi cây có Berry trên map
    local activeBushes = BerrySystem.GetActiveBushes()
    if #activeBushes == 0 then
        BerrySystem.CurrentBush = nil
        BerrySystem.TouchTimer = nil
        return false -- HẾT SẠCH BERRY TRÊN MAP -> Trả về false để code tiếp tục farm cấp bình thường!
    end

    -- Tìm bụi cây có Berry gần người chơi nhất
    local nearest = nil
    local minDist = math.huge
    local hrpPos = hrp.Position
    for _, item in ipairs(activeBushes) do
        local b = item.Bush
        local _, exactBerryCF, _ = BerrySystem.GetBerryChildAndCF(b)
        local cf = exactBerryCF or BerrySystem.GetPivotOrCFrame(b) or (b.Parent and BerrySystem.GetPivotOrCFrame(b.Parent))
        if cf then
            local dist = (hrpPos - cf.Position).Magnitude
            if dist < minDist then
                minDist = dist
                nearest = { Item = item, BushCF = cf }
            end
        end
    end

    if not nearest then return false end

    local targetBush = nearest.Item.Bush
    local berryName = nearest.Item.Name or "Berry"
    local totalActive = #activeBushes

    -- Kiểm tra xem Model quả Berry con bên trong targetBush:GetChildren() đã stream ra chưa
    local berryChild, exactBerryCF, prompt = BerrySystem.GetBerryChildAndCF(targetBush)
    local targetCF = exactBerryCF or nearest.BushCF

    CurrentFarmStatus = "[Auto Berry] Phát hiện " .. tostring(totalActive) .. " Berry trên map! Đang nhặt (" .. tostring(berryName) .. ") | Tổng đã nhặt: " .. tostring(BerrySystem.Data.TotalCollected)

    local dist = (hrp.Position - targetCF.Position).Magnitude

    -- GIAI ĐOẠN 1: Nếu còn cách vị trí quả Berry > 4.5 studs -> Bay sát tới tận nơi (tuyệt đối không dừng sớm ở 12 studs)
    if dist > 4.5 then
        TweenTo(targetCF)
        BerrySystem.TouchTimer = nil
        return true
    end

    -- GIAI ĐOẠN 2: Đã áp sát bụi/quả Berry (<= 4.5 studs)
    if getgenv().StopTween then getgenv().StopTween() end
    RefreshTeleportTag()
    hrp.CFrame = targetCF
    pcall(function() hrp.Velocity = Vector3.new(0, 0, 0) end)

    BerrySystem.TouchTimer = BerrySystem.TouchTimer or tick()

    -- Quét toàn bộ quả Berry con bên trong targetBush:GetChildren() để nhảy thẳng vào từng quả và fireproximityprompt
    local foundAnyChild = false
    for _, child in ipairs(targetBush:GetChildren()) do
        local cCF = nil
        pcall(function()
            if child:IsA("Model") then
                cCF = child.WorldPivot or child:GetPivot()
            elseif child:IsA("BasePart") then
                cCF = child.CFrame
            end
        end)
        local cPrompt = child:FindFirstChild("ProximityPrompt") or child:FindFirstChildWhichIsA("ProximityPrompt", true)
        if not cCF and cPrompt and cPrompt.Parent and cPrompt.Parent:IsA("BasePart") then
            cCF = cPrompt.Parent.CFrame
        end
        if cCF then
            foundAnyChild = true
            RefreshTeleportTag()
            hrp.CFrame = cCF
            pcall(function() hrp.Velocity = Vector3.new(0, 0, 0) end)
        end
        if cPrompt then
            foundAnyChild = true
            pcall(function()
                cPrompt.HoldDuration = 0
                cPrompt.MaxActivationDistance = 50
                cPrompt.RequiresLineOfSight = false
            end)
            pcall(function() fireproximityprompt(cPrompt) end)
            pcall(function() fireproximityprompt(cPrompt, 0) end)
            pcall(function() fireproximityprompt(cPrompt, math.huge) end)
        end
    end

    -- Dự phòng nếu ProximityPrompt nằm trực tiếp trong targetBush hoặc targetBush.Parent
    if not foundAnyChild then
        local fallbackPrompt = prompt
            or targetBush:FindFirstChildWhichIsA("ProximityPrompt", true)
            or (targetBush.Parent and targetBush.Parent:FindFirstChildWhichIsA("ProximityPrompt", true))
        if fallbackPrompt then
            if fallbackPrompt.Parent and fallbackPrompt.Parent:IsA("BasePart") then
                RefreshTeleportTag()
                hrp.CFrame = fallbackPrompt.Parent.CFrame
            end
            pcall(function()
                fallbackPrompt.HoldDuration = 0
                fallbackPrompt.MaxActivationDistance = 50
                fallbackPrompt.RequiresLineOfSight = false
            end)
            pcall(function() fireproximityprompt(fallbackPrompt) end)
            pcall(function() fireproximityprompt(fallbackPrompt, 0) end)
            pcall(function() fireproximityprompt(fallbackPrompt, math.huge) end)
        end
    end

    -- Bấm phím E dự phòng nếu executor cần tương tác trực tiếp khi đứng sát Berry
    pcall(function()
        local vim = game:GetService("VirtualInputManager")
        if vim then
            vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)
            task.wait(0.05)
            vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)
        end
    end)

    task.wait(0.15)

    -- Kiểm tra xem đã nhặt xong chưa
    local stillHas, _ = BerrySystem.HasBerry(targetBush)
    if not stillHas then
        BerrySystem.AddBerry(berryName)
        BerrySystem.AttemptCounts[targetBush] = nil
        BerrySystem.TouchTimer = nil
        CurrentFarmStatus = "[Auto Berry] ✅ Thu thập thành công " .. tostring(berryName) .. "! (Tổng cộng: " .. tostring(BerrySystem.Data.TotalCollected) .. ")"
    else
        -- Nếu đứng quá 4 giây tại bụi này mà vẫn chưa nhặt được -> Tăng attempt
        if tick() - BerrySystem.TouchTimer >= 4.0 then
            BerrySystem.AttemptCounts[targetBush] = (BerrySystem.AttemptCounts[targetBush] or 0) + 1
            if BerrySystem.AttemptCounts[targetBush] >= 2 then
                -- Tạm bỏ qua bụi này trong 60 giây để không làm kẹt bot
                BerrySystem.IgnoredBushes[targetBush] = tick()
                BerrySystem.AttemptCounts[targetBush] = nil
                BerrySystem.TouchTimer = nil
            end
        end
    end

    return true -- CÓ BERRY VÀ ĐANG NHẶT -> Tạm dừng farm cấp!
end

-- Tải dữ liệu tiến độ lưu trữ của Berry ngay khi khởi động
BerrySystem.Load()

-- ==========================================
-- HỆ THỐNG AUTO RAID KIẾM ĐIỂM F (FRAGMENTS) ĐỂ MUA VÕ V1 BẰNG F (DRAGON CLAW)
-- (Khi vào chế độ Raid: KHÔNG đi nhặt trái, KHÔNG làm việc khác cho tới khi đủ điểm F mua võ rồi farm lại như cũ)
-- ==========================================
local function HasSpecialMicrochip()
    return (plr:FindFirstChild("Backpack") and plr.Backpack:FindFirstChild("Special Microchip") ~= nil)
        or (plr.Character and plr.Character:FindFirstChild("Special Microchip") ~= nil)
end

local function GetLastRaidIsland(customHrp)
    local char = plr.Character
    local hrp = customHrp or (char and char:FindFirstChild("HumanoidRootPart"))
    if not hrp then return nil, 0 end

    local origins = workspace:FindFirstChild("_WorldOrigin")
    local locations = origins and origins:FindFirstChild("Locations")
    if not locations then return nil, 0 end

    local maxNum, lastIsl = 0, nil
    for _, loc in ipairs(locations:GetChildren()) do
        if loc:IsA("BasePart") and loc.Name:find("Island") then
            local numStr = loc.Name:match("%d+")
            local num = tonumber(numStr)
            if num and (hrp.Position - loc.Position).Magnitude < 3500 then
                if num > maxNum then
                    maxNum = num
                    lastIsl = loc
                end
            end
        end
    end
    return lastIsl, maxNum
end

local function IsInRaid()
    local pg = plr:FindFirstChild("PlayerGui")
    local mainGui = pg and pg:FindFirstChild("Main")
    local hasTimer = false
    if mainGui then
        local topHud = mainGui:FindFirstChild("TopHUDList")
        local raidTimer = topHud and topHud:FindFirstChild("RaidTimer")
        if raidTimer and raidTimer.Visible then
            hasTimer = true
        end
        local timer = mainGui:FindFirstChild("Timer")
        if timer and timer.Visible then
            hasTimer = true
        end
    end

    -- BẮT BUỘC: Chỉ khi giao diện của chính mình hiển thị RaidTimer ("Time Left:")
    -- thì mới tính là mình đang ở trong Raid! Tuyệt đối không nhầm sang Raid của người khác.
    if not hasTimer then
        return false
    end

    local char = plr.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if hrp then
        local isl, idx = GetLastRaidIsland(hrp)
        if isl and (isl.Position - hrp.Position).Magnitude < 3000 then
            return true
        end
    end
    return false
end

if type(V1StyleLookup) == "table" then
    V1StyleLookup.GetLastRaidIsland = GetLastRaidIsland
    V1StyleLookup.IsInRaid = IsInRaid
end

local function GetCheapestStoredFruit()
    local cheapestStorageKey = nil
    local cheapestDispName = nil
    local cheapestVal = math.huge

    local function evaluateFruitCandidate(storageKey, dispName, candidatePrice)
        if not storageKey or storageKey == "" then return end
        local sKey = tostring(storageKey)
        local dName = tostring(dispName or sKey)
        local price = GetFruitPriceFromItem(sKey, candidatePrice)
        if price <= 0 then
            price = GetFruitPriceFromItem(dName, candidatePrice)
        end
        if price <= 0 then
            local cleanBase = dName:gsub("%-.*", ""):gsub(" Fruit", ""):gsub(" ", "")
            price = GetFruitPriceFromItem(cleanBase, candidatePrice)
        end
        -- Trái đổi chip raid: giá trị <= 1,000,000 Beli (Rocket $5K, Spin $7.5K, Blade, Chop, Flame, Sand...)
        -- Tuyệt đối bảo vệ các trái đắt tiền (>= $1M như Buddha, Portal, Dragon, Kitsune...)
        if price > 0 and price <= 1000000 and price < cheapestVal then
            cheapestVal = price
            cheapestStorageKey = sKey
            cheapestDispName = dName
        end
    end

    -- 0. ƯU TIÊN 0: Quét trực tiếp remote "getInventory" (Chuẩn xác nhất cho mọi phiên bản Blox Fruits)
    pcall(function()
        local inv = ReplicatedStorage.Remotes.CommF_:InvokeServer("getInventory")
        if type(inv) == "table" then
            for k, it in pairs(inv) do
                if type(it) == "table" then
                    local sKey = it.Name or it.StorageKey or it.ItemId or k
                    local dName = it.DisplayName or it.Name or sKey
                    evaluateFruitCandidate(sKey, dName, it.Price or it.Value)
                elseif type(it) == "number" and it > 0 then
                    evaluateFruitCandidate(k, k)
                end
            end
        end
    end)

    -- 1. ƯU TIÊN 1 (Chuẩn Blox Fruits v30+): Đọc trực tiếp từ ItemReplicationService & ItemConfig
    if ItemReplicationService and ItemConfig and ItemReplicationService.KEYS then
        pcall(function()
            for _, item in ItemReplicationService:GetItems(ItemReplicationService.KEYS.QUANTITY) do
                if item.Value and item.Value > 0 then
                    local ok, cfg = pcall(function()
                        return ItemConfig.match(item.ItemId):unwrap()
                    end)
                    if ok and cfg and cfg.Display and cfg.Display.Category == "Blox Fruit" then
                        local storage = (cfg.Index and cfg.Index.StorageKey) or cfg.Display.Name
                        local disp = cfg.Display.Name or storage
                        evaluateFruitCandidate(storage, disp)
                    end
                end
            end
        end)
    end

    -- 2. Đọc từ hàm GetStoredFruitsCountMap(true) nếu có
    if not cheapestStorageKey and type(GetStoredFruitsCountMap) == "function" then
        pcall(function()
            local map = GetStoredFruitsCountMap(true)
            if type(map) == "table" then
                for fKey, count in pairs(map) do
                    if count and count > 0 then
                        evaluateFruitCandidate(fKey, fKey)
                    end
                end
            end
        end)
    end

    -- 3. Quét remote "getInventoryFruits" (Dự phòng cho server cũ)
    if not cheapestStorageKey then
        pcall(function()
            local fruitList = ReplicatedStorage.Remotes.CommF_:InvokeServer("getInventoryFruits")
            if type(fruitList) == "table" then
                for k, it in pairs(fruitList) do
                    if type(it) == "table" then
                        evaluateFruitCandidate(it.Name or it.StorageKey or it.Value, it.DisplayName or it.Name, it.Price or it.Value)
                    elseif type(it) == "string" then
                        evaluateFruitCandidate(it, it)
                    elseif type(k) == "string" and type(it) == "number" and it > 0 then
                        evaluateFruitCandidate(k, k, it)
                    end
                end
            end
        end)
    end

    -- 4. Quét UI PlayerGui (Nhận diện trực tiếp từ giao diện Items -> Treasure như trong ảnh)
    if not cheapestStorageKey then
        pcall(function()
            local pg = plr:FindFirstChild("PlayerGui")
            if pg then
                for _, desc in ipairs(pg:GetDescendants()) do
                    if desc:IsA("TextLabel") and desc.Visible and desc.Text ~= "" then
                        local t = desc.Text:gsub(" Fruit", ""):gsub(" ", "")
                        if FruitPricesMap and FruitPricesMap[t] and FruitPricesMap[t] <= 1000000 then
                            evaluateFruitCandidate(t, desc.Text)
                        end
                    end
                end
            end
        end)
    end

    return cheapestStorageKey, cheapestDispName, cheapestVal
end

local function HasPhysicalFruitOnPlayer()
    local dfName = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("DevilFruit") and plr.Data.DevilFruit.Value) or ""
    for _, cont in ipairs({plr:FindFirstChild("Backpack"), plr.Character}) do
        if cont then
            for _, tool in ipairs(cont:GetChildren()) do
                if tool:IsA("Tool") then
                    local isEatenSkill = tool:FindFirstChild("Skills") or tool:FindFirstChild("Client") or (dfName ~= "" and (tool.Name == dfName or string.find(dfName, tool.Name)))
                    if not isEatenSkill then
                        if string.find(tool.Name, "Fruit") or tool.ToolTip == "Blox Fruit" or tool:FindFirstChild("EatRemote", true) or tool:FindFirstChild("Eat", true) then
                            return true, tool
                        end
                    end
                end
            end
        end
    end
    return false, nil
end

local function GetRaidSummonButton()
    local map = workspace:FindFirstChild("Map")
    if not map then return nil end
    if World2 or CurrentSeaNum == 2 then
        local circle = map:FindFirstChild("CircleIsland")
        local summon = circle and (circle:FindFirstChild("RaidSummon2") or circle:FindFirstChild("RaidSummon"))
        local btn = summon and summon:FindFirstChild("Button")
        return btn and (btn:FindFirstChild("Main") or btn:FindFirstChildWhichIsA("BasePart"))
    elseif World3 or CurrentSeaNum == 3 then
        local castle = map:FindFirstChild("Boat Castle")
        local summon = castle and (castle:FindFirstChild("RaidSummon2") or castle:FindFirstChild("RaidSummon"))
        local btn = summon and summon:FindFirstChild("Button")
        return btn and (btn:FindFirstChild("Main") or btn:FindFirstChildWhichIsA("BasePart"))
    end
    return nil
end

local function ClickRaidSummonButton()
    local btnMain = GetRaidSummonButton()
    local cd = btnMain and (btnMain:FindFirstChildOfClass("ClickDetector") or btnMain:FindFirstChild("ClickDetector"))
    if not cd and workspace:FindFirstChild("Map") then
        local map = workspace.Map
        local island = (World2 or CurrentSeaNum == 2) and map:FindFirstChild("CircleIsland") or map:FindFirstChild("Boat Castle")
        local summon = island and (island:FindFirstChild("RaidSummon2") or island:FindFirstChild("RaidSummon"))
        cd = summon and summon:FindFirstChildWhichIsA("ClickDetector", true)
    end
    if cd and fireclickdetector then
        pcall(fireclickdetector, cd)
        pcall(fireclickdetector, cd, 0)
        pcall(fireclickdetector, cd, 1)
        return true
    end
    return false
end

local function GetNearestRaidMob()
    local char = plr.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil end

    local currentIsland, islandIdx = GetLastRaidIsland(hrp)
    if not currentIsland then return nil end

    local enemies = workspace:FindFirstChild("Enemies")
    if not enemies then return nil end

    local bestMob, bestDist = nil, math.huge
    for _, mob in ipairs(enemies:GetChildren()) do
        local hum = mob:FindFirstChildOfClass("Humanoid")
        local mHrp = mob:FindFirstChild("HumanoidRootPart")
        if hum and mHrp and hum.Health > 0 then
            local dFromMyIsland = (mHrp.Position - currentIsland.Position).Magnitude
            if dFromMyIsland <= 800 then
                local d = (mHrp.Position - hrp.Position).Magnitude
                if d < bestDist then
                    bestDist = d
                    bestMob = mob
                end
            end
        end
    end
    return bestMob, bestDist
end

LastChipBuyAttempt = 0
local function DoAutoRaidStep(hrp, hum, curFrags, targetFrags, styleName)
    -- 1. Đồng bộ và lưu mục tiêu Raid động (tránh bị gán cứng hoặc reset)
    if styleName and styleName ~= "" then
        getgenv()._raidTargetStyle = styleName
    else
        styleName = getgenv()._raidTargetStyle
    end
    if targetFrags and tonumber(targetFrags) and tonumber(targetFrags) > 0 then
        getgenv()._raidTargetFrags = tonumber(targetFrags)
    else
        targetFrags = getgenv()._raidTargetFrags
    end

    -- Nếu mục tiêu chưa xác định hoặc bị mặc định "Dragon Claw" nhưng người chơi đã có Dragon Claw / đang farm V2 (như Death Step 5k F)
    if (not styleName or styleName == "Dragon Claw") and type(V1StyleLookup) == "table" and type(V1StyleLookup.GetActiveTargetStyle) == "function" then
        local actStyle, tier = V1StyleLookup.GetActiveTargetStyle()
        if actStyle then
            local actCostFrag = actStyle.CostFrag or 0
            if actCostFrag > 0 and curFrags < actCostFrag then
                styleName = actStyle.Name
                targetFrags = actCostFrag
                getgenv()._raidTargetStyle = styleName
                getgenv()._raidTargetFrags = targetFrags
            end
        end
    end

    styleName = styleName or "Võ Thuật"
    targetFrags = targetFrags or 1500

    -- Nếu không ở bên trong Raid:
    if not IsInRaid() then
        -- A. Nếu số F hiện tại ĐÃ ĐỦ mục tiêu (curFrags >= targetFrags) -> NGỪNG RAID NGAY LẬP TỨC để quay lại mua võ / giải quest!
        if curFrags >= targetFrags then
            getgenv()._isDoingRaidForF = false
            getgenv()._holdingFruitForRaidChip = false
            getgenv()._waitingForRaidTeleport = false
            getgenv()._raidTargetStyle = nil
            getgenv()._raidTargetFrags = nil
            return
        end

        if getgenv()._isFetchingMelee then
            getgenv()._isDoingRaidForF = false
            getgenv()._holdingFruitForRaidChip = false
            return
        end
        if type(V1StyleLookup) == "table" and type(V1StyleLookup.ItemsSystem) == "table" and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem() then
            getgenv()._isDoingRaidForF = false
            getgenv()._holdingFruitForRaidChip = false
            V1StyleLookup.ItemsSystem.DoUrgentStep(hrp, hum)
            return
        end
        getgenv()._myRaidIslands = nil
        getgenv()._raidIslandArriveTick = nil
        if styleName and styleName ~= "Skull Guitar" and styleName ~= "Reset Stats Farm Kiếm" and styleName ~= "Farm Fragments" and styleName ~= "Tích Lũy Fragments" then
            local hasT = V1StyleLookup and V1StyleLookup.FindMeleeTool and (V1StyleLookup.FindMeleeTool(styleName) ~= nil)
            local hasM = ((V1MasteryRecord and V1MasteryRecord[styleName] or 0) > 0)
                or (styleName == "Dragon Claw" and V1MasteryRecord and ((V1MasteryRecord["Dragon Breath"] or 0) > 0 or (V1MasteryRecord["DragonClaw"] or 0) > 0))
            local isBought = (V1StyleLookup and V1StyleLookup.BoughtStyles and V1StyleLookup.BoughtStyles[styleName] == true)
                or (getgenv()["Z9_MeleeBought_" .. tostring(styleName)] == true)
                or (V1StyleLookup and V1StyleLookup.IsStyleOwned and V1StyleLookup.IsStyleOwned(styleName))

            -- Nếu đã mua hoặc đã sở hữu võ mục tiêu -> ngừng raid ngay!
            if isBought or hasT or hasM then
                getgenv()._isDoingRaidForF = false
                getgenv()._holdingFruitForRaidChip = false
                getgenv()._raidTargetStyle = nil
                getgenv()._raidTargetFrags = nil
                return
            end
        end
    end

    getgenv()._isDoingRaidForF = true

    -- Hủy nhiệm vụ farm cấp thường nếu đang nhận dở
    if HasActiveQuest() then
        pcall(function()
            ReplicatedStorage.Remotes.CommF_:InvokeServer("AbandonQuest")
        end)
        ResetQuestSeen()
    end

    -- TRƯỜNG HỢP 1: Đang ở bên trong Raid (Island 1 -> Island 5) -> Dọn sạch quái trên các đảo Raid của chính mình
    if IsInRaid() then
        getgenv()._waitingForRaidTeleport = false
        getgenv()._raidCountdownStartTick = nil
        getgenv()._holdingFruitForRaidChip = false
        pcall(function()
            if sethiddenproperty then
                sethiddenproperty(plr, "SimulationRadius", math.huge)
            end
        end)

        -- Tự động thức tỉnh chiêu Z của Buddha nếu đang dùng trái Buddha và đủ 500 Frag
        local autoB = getgenv().SettingFarm and getgenv().SettingFarm["Auto Buddha"]
        local wantAwakenZ = (not autoB or autoB["Awaken Z"] ~= false)
        local df = plr:FindFirstChild("Data") and plr.Data:FindFirstChild("DemonFruit")
        local dfName = df and df.Value or ""
        local frags = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Fragments") and plr.Data.Fragments.Value) or 0
        if wantAwakenZ and string.find(string.lower(dfName), "buddha") and frags >= 500 then
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("Awaken", 1)
                ReplicatedStorage.Remotes.CommF_:InvokeServer("Awaken", "Z")
            end)
        end

        -- Tự động đóng hộp thoại Awakening / Mysterious Entity nếu đã thắng raid (hoặc sau khi thức tỉnh)
        pcall(function()
            local dc = require(ReplicatedStorage:FindFirstChild("DialogueController"))
            if dc and dc.Active then
                pcall(dc.select, 1)
                pcall(dc.close)
            end
        end)

        local raidMob, mobDist = GetNearestRaidMob()
        local currentIsland, islandIdx, islands = GetLastRaidIsland(hrp)

        if raidMob and raidMob:FindFirstChild("HumanoidRootPart") then
            local eHum = raidMob:FindFirstChildOfClass("Humanoid")
            local eHp = eHum and eHum.Health or 100
            local eMaxHp = eHum and eHum.MaxHealth or 100
            local targetIslandNum = islandIdx or "?"

            DisableMobCollision(raidMob)
            EnableBuso()
            EquipSelectedWeapon()

            -- Bảo vệ sinh mệnh: Nếu máu player dưới 45%, bay lên cực cao (+175 studs) né toàn bộ chiêu thức và AOE của Boss để hồi máu
            local myHpPercent = (hum and hum.MaxHealth > 0) and (hum.Health / hum.MaxHealth) or 1
            if myHpPercent < 0.45 then
                getgenv()._isRaidHealing = true
            elseif myHpPercent >= 0.80 then
                getgenv()._isRaidHealing = false
            end

            local raidTag = (curFrags >= targetFrags)
                and ("[Auto Raid] 🏆 Đã đủ ƒ" .. FormatNumber(curFrags) .. "/ƒ" .. FormatNumber(targetFrags) .. " (" .. tostring(styleName) .. ") -")
                or ("[Auto Raid kiếm F mua " .. tostring(styleName) .. ": ƒ" .. FormatNumber(curFrags) .. "/ƒ" .. FormatNumber(targetFrags) .. "]")

            if getgenv()._isRaidHealing then
                CurrentFarmStatus = raidTag .. " [Đảo " .. tostring(targetIslandNum) .. "/5] Máu thấp (" .. math.floor(myHpPercent * 100) .. "%/80%) -> Đang bay cao (+175 studs) né chiêu để hồi máu an toàn..."
                TweenTo(raidMob.HumanoidRootPart.CFrame * CFrame.new(0, 175, 0))
            else
                CurrentFarmStatus = raidTag .. " Đang đánh quái Đảo " .. tostring(targetIslandNum) .. " (HP: " .. math.floor(eHp) .. "/" .. math.floor(eMaxHp) .. ")"
                BringMobs(raidMob)
                TweenTo(raidMob.HumanoidRootPart.CFrame * CFrame.new(0, 20, 0))

                -- Tấn công mạng thực tế (Network Attack) để gây sát thương thật trên server (KHÔNG dùng client fake kill)
                pcall(function()
                    local net = ReplicatedStorage:FindFirstChild("Modules") and ReplicatedStorage.Modules:FindFirstChild("Net")
                    local regAtk = net and net:FindFirstChild("RegisterAttack")
                    local regHit = net and net:FindFirstChild("RegisterHit")
                    if regAtk then regAtk:FireServer(0) end
                    if regHit and raidMob:FindFirstChild("HumanoidRootPart") then
                        regHit:FireServer(raidMob.HumanoidRootPart, { { raidMob, raidMob.HumanoidRootPart } })
                    end
                end)
            end
        else
            -- Không còn quái nào sống trên đảo hiện tại -> Bay thẳng tới đảo cao nhất hiện có (1 -> 2 -> 3 -> 4 -> 5)
            local raidTag2 = (curFrags >= targetFrags)
                and ("[Auto Raid] 🏆 Đã đủ ƒ" .. FormatNumber(curFrags) .. "/ƒ" .. FormatNumber(targetFrags) .. " -")
                or ("[Auto Raid kiếm F mua " .. tostring(styleName) .. ": ƒ" .. FormatNumber(curFrags) .. "/ƒ" .. FormatNumber(targetFrags) .. "]")
            if currentIsland and islandIdx and islandIdx > 0 then
                if islandIdx >= 5 then
                    CurrentFarmStatus = raidTag2 .. " Đã hoàn tất Đảo 5/5! Đang chờ nhận thưởng F & rời phòng Raid..."
                else
                    CurrentFarmStatus = raidTag2 .. " Đang ở Đảo " .. tostring(islandIdx) .. "/5 -> Chờ quái xuất hiện..."
                end
                TweenTo(currentIsland.CFrame * CFrame.new(0, 50, 0))
            else
                CurrentFarmStatus = raidTag2 .. " Đang đợi đảo Raid tiếp theo..."
            end
        end
        return
    end

    -- Tọa độ phòng Raid Lab & NPC Mysterious Scientist tại Sea 2 (Hot and Cold) và Sea 3 (Castle on the Sea)
    local labCF = (World3 or CurrentSeaNum == 3) and CFrame.new(-5033.51, 315.01, -2947.78) or CFrame.new(-6438.74, 250.65, -4501.51)
    local btnMain = GetRaidSummonButton()
    if btnMain then
        labCF = btnMain.CFrame
    else
        LoadIslandByFakePoint(labCF)
    end

    -- Tìm vị trí NPC Mysterious Scientist (người bán Special Microchip)
    local function GetRaidNpcCFrame()
        local npc = nil
        if workspace:FindFirstChild("NPCs") then
            npc = workspace.NPCs:FindFirstChild("Mysterious Scientist")
                or workspace.NPCs:FindFirstChild("Scientist")
            if not npc then
                for _, c in ipairs(workspace.NPCs:GetChildren()) do
                    local nLower = c.Name:lower()
                    if nLower:find("mysterious scientist") or (nLower:find("scientist") and not nLower:find("mad")) then
                        npc = c
                        break
                    end
                end
            end
        end
        if npc then
            return npc:GetPivot()
        end
        if World2 or CurrentSeaNum == 2 then
            return CFrame.new(-6503, 251, -4495)
        elseif World3 or CurrentSeaNum == 3 then
            return CFrame.new(-5500, 314, -2855)
        end
        return nil
    end

    -- Bục ống phóng capsule tube để được dịch chuyển vào đảo Raid khi đếm ngược kết thúc
    local tubeCF = (World2 or CurrentSeaNum == 2) and CFrame.new(-6475.25, 250.65, -4490.85) or CFrame.new(-5033.51, 315.01, -2947.78)
    local scientistCF = GetRaidNpcCFrame() or labCF

    -- TRƯỜNG HỢP 0: Đang trong thời gian đếm ngược vào Raid (đã bấm nút mở cổng, chip đã nộp, đứng đợi dịch chuyển)
    -- Tuyệt đối KHÔNG chạy ngược lại chỗ Mysterious Scientist để mua thêm chip!
    if getgenv()._waitingForRaidTeleport then
        local elapsed = tick() - (getgenv()._raidCountdownStartTick or 0)
        if elapsed < 25 then
            local remain = math.max(0, math.ceil(20 - elapsed))
            CurrentFarmStatus = "[Auto Raid] Đã kích hoạt cổng Raid! Đang đứng trong bục phóng chờ đếm ngược (" .. tostring(remain) .. "s)..."
            if getgenv().StopTween then getgenv().StopTween() end
            hrp.CFrame = tubeCF
            task.wait(0.35)
            return
        else
            getgenv()._waitingForRaidTeleport = false
            getgenv()._raidCountdownStartTick = nil
        end
    end

    -- TRƯỜNG HỢP 2: Đã có Special Microchip -> Di chuyển vào bục phóng capsule & kích hoạt nút mở cổng Raid
    if HasSpecialMicrochip() then
        getgenv()._holdingFruitForRaidChip = false
        local distTube = (hrp.Position - tubeCF.Position).Magnitude

        if distTube > 30 then
            CurrentFarmStatus = "[Auto Raid kiếm F mua " .. tostring(styleName) .. ": ƒ" .. FormatNumber(curFrags) .. "/ƒ" .. FormatNumber(targetFrags) .. "] Đã có Microchip -> Đang bay vào bục phóng Raid..."
            TweenTo(tubeCF)
            return
        else
            if getgenv().StopTween then getgenv().StopTween() end
            hrp.CFrame = tubeCF
            CurrentFarmStatus = "[Auto Raid] Đang kích hoạt mở cổng bắt đầu Raid..."

            -- Cầm Special Microchip trên tay khi kích hoạt
            local chip = plr.Backpack:FindFirstChild("Special Microchip") or (plr.Character and plr.Character:FindFirstChild("Special Microchip"))
            if chip and hum and chip.Parent ~= plr.Character then
                hum:EquipTool(chip)
                task.wait(0.1)
            end

            ClickRaidSummonButton()
            -- Khóa trạng thái chờ đếm ngược ngay lập tức (tránh bị nhảy về NPC mua chip khi game trừ mất chip)
            getgenv()._waitingForRaidTeleport = true
            getgenv()._raidCountdownStartTick = tick()
            task.wait(0.4)
            hrp.CFrame = tubeCF
            return
        end
    end

    -- TRƯỜNG HỢP 3: Chưa có Special Microchip -> Mua Special Microchip (Beli hoặc Tự động lấy trái rẻ trong kho ra đổi)
    -- 1. Thử gọi remote mua trước từ xa (giống cơ chế Gacha Random Fruit từ xa)
    if tick() - LastChipBuyAttempt >= 1.0 then
        LastChipBuyAttempt = tick()
        local beli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
        if beli >= 100000 then
            pcall(function() hum:UnequipTools() end)
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("RaidsNpc", "Check")
                ReplicatedStorage.Remotes.CommF_:InvokeServer("RaidsNpc", "Select", "Flame")
            end)
        end
    end

    if HasSpecialMicrochip() then
        getgenv()._holdingFruitForRaidChip = false
        CurrentFarmStatus = "[Auto Raid] Đã nhận Special Microchip từ xa thành công! Đang vào bục phóng..."
        return
    end

    -- 2. Nếu ở xa NPC (> 25 studs) -> Tự động Tween bay nhanh tới phòng Raid (Hot & Cold ở Sea 2 / Castle ở Sea 3)
    local distSci = (hrp.Position - scientistCF.Position).Magnitude
    if distSci > 25 then
        CurrentFarmStatus = "[Auto Raid kiếm F mua " .. tostring(styleName) .. ": ƒ" .. FormatNumber(curFrags) .. "/ƒ" .. FormatNumber(targetFrags) .. "] Đang bay tới phòng Raid để mua Special Microchip..."
        TweenTo(scientistCF * CFrame.new(0, 2, 2))
        return
    else
        -- 3. Đã đứng ngay trước mặt Mysterious Scientist:
        if getgenv().StopTween then getgenv().StopTween() end
        hrp.CFrame = scientistCF * CFrame.new(0, 1.5, 1.5)
        CurrentFarmStatus = "[Auto Raid] Đang tương tác mua Special Microchip tại Mysterious Scientist..."

        local beli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0

        -- Mua bằng $100K Beli (nếu đủ tiền và chưa thử gần đây trong 15s)
        local lastBeliBuy = getgenv()._lastRaidBeliBuyTick or 0
        if beli >= 100000 and (tick() - lastBeliBuy > 15) then
            getgenv()._lastRaidBeliBuyTick = tick()
            pcall(function() hum:UnequipTools() end)
            task.wait(0.05)
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("RaidsNpc", "Check")
                ReplicatedStorage.Remotes.CommF_:InvokeServer("RaidsNpc", "Select", "Flame")
            end)
            task.wait(0.2)
        end

        -- Nếu chưa có Chip (Beli đang trong thời gian hồi chiêu 2h hoặc thiếu Beli)
        -- -> Tự động lấy trái rẻ nhất từ trong rương/tủ đồ ra (LoadFruit) để đổi Chip!
        if not HasSpecialMicrochip() then
            local hasFruit, fruitTool = HasPhysicalFruitOnPlayer()

            if not hasFruit then
                local cheapestKey, cheapestDisp, cPrice = GetCheapestStoredFruit()
                local fruitNamesToTry = {}
                if cheapestKey then
                    table.insert(fruitNamesToTry, cheapestKey)
                end
                if cheapestDisp and cheapestDisp ~= cheapestKey then
                    table.insert(fruitNamesToTry, cheapestDisp)
                end
                -- Danh sách trái rẻ phổ biến dự phòng (tuyệt đối bảo vệ các trái >= 1M)
                local fallbackCheapList = {
                    "Rocket-Rocket", "Rocket",
                    "Spin-Spin", "Spin",
                    "Blade-Blade", "Blade",
                    "Chop-Chop", "Chop",
                    "Spring-Spring", "Spring",
                    "Bomb-Bomb", "Bomb",
                    "Smoke-Smoke", "Smoke",
                    "Spike-Spike", "Spike",
                    "Flame-Flame", "Flame",
                    "Falcon-Falcon", "Falcon",
                    "Ice-Ice", "Ice",
                    "Sand-Sand", "Sand"
                }
                for _, fn in ipairs(fallbackCheapList) do
                    table.insert(fruitNamesToTry, fn)
                end

                CurrentFarmStatus = "[Auto Raid] Beli hồi chiêu -> Đang rút trái rẻ (" .. tostring(cheapestDisp or cheapestKey or "Rocket") .. ") từ tủ đồ ra đổi Chip..."
                getgenv()._holdingFruitForRaidChip = true

                for _, fn in ipairs(fruitNamesToTry) do
                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("LoadFruit", fn)
                    end)
                    task.wait(0.2)
                    hasFruit, fruitTool = HasPhysicalFruitOnPlayer()
                    if hasFruit and fruitTool then
                        break
                    end
                end
            end

            if hasFruit and fruitTool then
                getgenv()._holdingFruitForRaidChip = true
                if hum and fruitTool.Parent ~= plr.Character then
                    hum:EquipTool(fruitTool)
                    task.wait(0.2)
                end
                CurrentFarmStatus = "[Auto Raid] Đang cầm " .. tostring(fruitTool.Name) .. " đổi Special Microchip..."

                -- Tương tác với NPC Mysterious Scientist để đổi chip bằng trái đang cầm
                local npc = workspace:FindFirstChild("NPCs") and (workspace.NPCs:FindFirstChild("Mysterious Scientist") or workspace.NPCs:FindFirstChild("Scientist"))
                if npc then
                    local prompt = npc:FindFirstChildWhichIsA("ProximityPrompt", true)
                    if prompt and fireproximityprompt then
                        pcall(fireproximityprompt, prompt, 0)
                        pcall(fireproximityprompt, prompt, 1)
                    end
                end

                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("RaidsNpc", "Select", "Flame")
                end)

                -- Xử lý DialogueController nếu bảng thoại mở
                pcall(function()
                    local dc = require(ReplicatedStorage:FindFirstChild("DialogueController"))
                    if dc and dc.Active then
                        pcall(dc.advance)
                        pcall(dc.select, 1)
                        pcall(dc.select, "Flame")
                        pcall(dc.advance)
                    end
                end)
                task.wait(0.3)
            end
        end

        task.wait(0.2)
        if HasSpecialMicrochip() then
            getgenv()._holdingFruitForRaidChip = false
            CurrentFarmStatus = "[Auto Raid] Đã nhận Special Microchip thành công! Đang vào bục phóng..."
        end
        return
    end
end

-- ==========================================
-- HỆ THỐNG TỰ ĐỘNG RESET STAT SANG KIẾM & MÁU (RESET STATS FOR SWORD)
-- Khi farm kiếm: Reset điểm dồn vào Kiếm (Sword) & Máu (Defense), còn thừa dồn Melee
-- Nếu thiếu Fragments (< 2,500 F): Tự động đi Raid kiếm đủ F rồi mới Reset!
-- ==========================================
function V1StyleLookup.CheckAndResetStatsForSword(hrp, hum)
    if getgenv().SettingFarm and getgenv().SettingFarm.ResetStatsForSword == false then
        return false
    end

    -- CHỈ CHO PHÉP RESET STATS SANG KIẾM KHI:
    -- 1. Toàn bộ võ V2 (Superhuman, Death Step, Sharkman, Electric Claw, Dragon Talon) đã hoàn thành 400 Mastery (isPreGhDone)!
    -- 2. Nếu võ V2 chưa xong (như Dragon Talon chưa mua / chưa 400 Mas) -> TUYỆT ĐỐI KHÔNG tiêu 2,500 F để Reset Stats!
    local isPreGhDone = (type(V1StyleLookup) == "table" and type(V1StyleLookup.IsPreGodhumanMastered) == "function" and V1StyleLookup.IsPreGodhumanMastered())
    if not isPreGhDone then
        return false
    end

    -- Nếu vẫn còn bất kỳ võ mục tiêu nào (V1, V2, Godhuman) chưa mua hoặc chưa max 400 Mas -> Tuyệt đối không reset stats sang Kiếm!
    local actStyle = (type(V1StyleLookup) == "table" and type(V1StyleLookup.GetActiveTargetStyle) == "function" and V1StyleLookup.GetActiveTargetStyle())
    if actStyle ~= nil then
        return false
    end

    local isFarmingSword = (GetSettingWeapon() == "Sword" or getgenv()._targetSwordName ~= nil)
    if not isFarmingSword then
        return false
    end

    local data = plr:FindFirstChild("Data")
    local statsFolder = data and data:FindFirstChild("Stats")
    if not data or not statsFolder then return false end

    local swLv = GetStatCurrentLevel(statsFolder, "Sword")
    local melLv = GetStatCurrentLevel(statsFolder, "Melee")
    local pts = (data:FindFirstChild("Points") and data.Points.Value) or 0

    -- Nếu đang còn nhiều hơn 500 điểm chưa cộng -> Để Auto Stats tự cộng vào Sword & Defense trước
    if pts > 500 then
        return false
    end

    -- Nếu Sword đã cao (>= 2000 hoặc >= Melee) -> Đã là build Kiếm chuẩn, không cần reset
    if swLv >= 2000 or (swLv >= melLv and swLv >= 800) then
        return false
    end

    -- Chỉ kích hoạt reset khi điểm Melee đang vượt trội hoàn toàn so với Sword (ví dụ Melee >= 800 mà Sword < 500)
    if melLv < 800 or swLv >= melLv * 0.6 then
        return false
    end

    local now = tick()
    getgenv()._lastStatResetAttempt = getgenv()._lastStatResetAttempt or 0
    if now - getgenv()._lastStatResetAttempt < 8.0 then
        return true
    end

    -- 1. Ưu tiên thử nhập Code Reset Stat miễn phí trước (nếu chưa dùng)
    local resetCodes = { "KITT_RESET", "Sub2UncleKizaru", "SUB2GAMERROBOT_RESET1", "RESET_5M", "NOOB2PRO" }
    for _, code in ipairs(resetCodes) do
        if not getgenv()["_tried_code_" .. code] then
            getgenv()["_tried_code_" .. code] = true
            getgenv()._lastStatResetAttempt = now
            CurrentFarmStatus = "[Reset Stats] Đang nhập Code " .. code .. " để Reset điểm sang Kiếm & Máu..."
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("RedeemCode", code)
            end)
            task.wait(0.5)
            pts = (data:FindFirstChild("Points") and data.Points.Value) or 0
            if pts > 500 then
                CurrentFarmStatus = "[Reset Stats] ✅ Reset điểm bằng Code " .. code .. " thành công!"
                return true
            end
        end
    end

    -- 2. Nếu Code không được -> Dùng 2,500 F tại Plokster (ở Sea 2 & Sea 3)
    if CurrentSeaNum >= 2 or World2 or World3 then
        local curFrags = (data:FindFirstChild("Fragments") and data.Fragments.Value) or 0
        -- Nếu thiếu F (< 2,500 F) -> Tự động đi Raid kiếm đủ 2,500 F!
        if curFrags < 2500 then
            getgenv()._raidTargetStyle = "Reset Stats Farm Kiếm"
            getgenv()._raidTargetFrags = 2500
            CurrentFarmStatus = "[Reset Stats] Thiếu F reset điểm (" .. FormatNumber(curFrags) .. "/2,500 F) -> Đang tự động đi Raid kiếm F..."
            DoAutoRaidStep(hrp, hum, curFrags, 2500, "Reset Stats Farm Kiếm")
            return true
        else
            -- Đã đủ 2,500 F -> Gọi Plokster Reset điểm!
            getgenv()._lastStatResetAttempt = now
            CurrentFarmStatus = "[Reset Stats] Đang dùng 2,500 F tại Plokster để Reset điểm sang Kiếm & Máu..."
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("BlackbeardReward", "Refund", "1")
                task.wait(0.2)
                ReplicatedStorage.Remotes.CommF_:InvokeServer("BlackbeardReward", "Refund", "2")
            end)
            task.wait(0.5)
            CurrentFarmStatus = "[Reset Stats] ✅ Đã Reset điểm thành công! Đang cộng điểm vào Kiếm & Máu..."
            return true
        end
    end

    return false
end

-- ==========================================
-- HỆ THỐNG AUTO MUA KỸ NĂNG HAKI & DI CHUYỂN (BUY ABILITIES)
-- (Tự động mua Air Jump, Aura/Buso, Flash Step ở mọi Sea khi đủ Beli; Instinct mua ở Sea 2+)
-- ==========================================
task.spawn(function()
    while task.wait(3) do
        pcall(function()
            -- Kiểm tra xem nhân vật đã có Aura chưa (nếu có HasBuso thì chắc chắn đã có Aura)
