                end
            end

            -- 2. Tự động mua Aura (Buso Haki - $25,000 Beli)
            if IsBuyAbilityEnabled("Aura") and not PurchasedAbilities["Aura"] then
                if curBeli >= 25000 then
                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("BuyHaki", "Buso")
                    end)
                    PurchasedAbilities["Aura"] = true
                    task.wait(0.5)
                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("Buso")
                    end)
                end
            end

            -- 3. Tự động mua Flash Step (Soru - $100,000 Beli)
            if IsBuyAbilityEnabled("Flash Step") and not PurchasedAbilities["Flash Step"] then
                if curBeli >= 100000 then
                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("BuyHaki", "Soru")
                    end)
                    PurchasedAbilities["Flash Step"] = true
                    task.wait(0.5)
                end
            end

            -- 4. Tự động mua Instinct (Ken Haki - $750,000 Beli)
            if IsBuyInstinctEnabled() and not HasInstinct() then
                if (World2 or World3 or CurrentSeaNum >= 2) and HasSaberSword() and curBeli >= 750000 then
                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("KenTalk", "Start")
                    end)
                    task.wait(0.2)
                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("KenTalk", "Buy")
                    end)
                    task.wait(0.5)
                    HasInstinct()
                end
            end
        end)
    end
end)

-- ==========================================
-- HỆ THỐNG ĐỔI SERVER (ROBLOX NATIVE HOP SERVER - CHỐNG TRIỆT ĐỂ LỖI 773 HẠN CHẾ ĐỊA ĐIỂM)
-- ==========================================
local HopServer -- Khai báo trước để các hook sự kiện bên dưới gọi được, tránh lỗi attempt to call a nil value

local HopSystem = {
    VisitedServers = getgenv().Z9_VisitedServers or {},
    IsHopping = false,
    LastHopTick = 0,
    NextAllowedHop = 0,
    RetryCount = 0,
}
getgenv().Z9_VisitedServers = HopSystem.VisitedServers
HopSystem.VisitedServers[tostring(game.JobId)] = true

-- Tự động dập tắt và vượt qua popup "Mã lỗi 773: Không thể đến 1 địa điểm bị hạn chế" / Lỗi Teleport Token
pcall(function()
    local CoreGui = game:GetService("CoreGui")
    local promptGui = CoreGui:FindFirstChild("RobloxPromptGui") or CoreGui:WaitForChild("RobloxPromptGui", 5)
    if promptGui then
        local promptOverlay = promptGui:FindFirstChild("promptOverlay") or promptGui:WaitForChild("promptOverlay", 5)
        if promptOverlay and not getgenv().Z9_PromptHooked then
            getgenv().Z9_PromptHooked = true
            local function handlePrompt(child)
                task.wait(0.2)
                pcall(function()
                    if child and (child:IsA("Frame") or child.Name == "ErrorPrompt") then
                        local msgLabel = child:FindFirstChild("ErrorMessage", true)
                        local msg = msgLabel and string.lower(tostring(msgLabel.Text or "")) or ""
                        if msg:find("processing") then
                            -- Teleport đang được xử lý, không can thiệp để Roblox tự chuyển server
                            return
                        end
                        if msg:find("773") or msg:find("hạn chế") or msg:find("restricted") or msg:find("teleport") or msg:find("không thể") or msg:find("token") then
                            local btn = child:FindFirstChild("Button", true) or child:FindFirstChild("LeaveButton", true) or child:FindFirstChild("OkButton", true)
                            if btn and firesignal then
                                firesignal(btn.MouseButton1Click)
                            end
                            child.Visible = false
                            HopSystem.IsHopping = false
                            HopSystem.RetryCount = (HopSystem.RetryCount or 0) + 1
                            if HopSystem.RetryCount <= 2 then
                                HopSystem.NextAllowedHop = tick() + 15
                                CurrentFarmStatus = "Đã dập popup lỗi (" .. HopSystem.RetryCount .. "/2), thử lại sau 15s..."
                                task.delay(15, function()
                                    if HopServer and HopSystem.RetryCount > 0 and HopSystem.RetryCount <= 2 and not HopSystem.IsHopping then
                                        HopServer("Vượt popup lỗi, thử lại (" .. HopSystem.RetryCount .. "/2)...")
                                    end
                                end)
                            else
                                HopSystem.RetryCount = 0
                                HopSystem.NextAllowedHop = tick() + 45
                                CurrentFarmStatus = "Tạm dừng đổi server (chống lag), tiếp tục farm tại server hiện tại..."
                            end
                        end
                    end
                end)
            end
            promptOverlay.ChildAdded:Connect(handlePrompt)
            for _, ch in ipairs(promptOverlay:GetChildren()) do
                handlePrompt(ch)
            end
        end
    end
end)

-- Lắng nghe TeleportInitFailed và chống vòng lặp spam lag game
pcall(function()
    if not getgenv().Z9_TeleportHooked then
        getgenv().Z9_TeleportHooked = true
        TeleportService.TeleportInitFailed:Connect(function(player, teleportResult, errorMessage)
            if player == plr then
                local errText = tostring(errorMessage or teleportResult or "Lỗi kết nối")
                local errLower = errText:lower()

                -- NẾU LỖI LÀ DO TELEPORT ĐANG ĐƯỢC XỬ LÝ (The previous teleport is in processing)
                -- -> Roblox ĐANG CHUYỂN SERVER! Tuyệt đối không retry, không reset IsHopping!
                if errLower:find("processing") or errLower:find("isteleporting") or teleportResult == Enum.TeleportResult.IsTeleporting then
                    HopSystem.IsHopping = true
                    HopSystem.NextAllowedHop = tick() + 60
                    CurrentFarmStatus = "Đang chuyển server (Roblox đang kết nối, vui lòng chờ...)..."
                    if getgenv().StopTween then getgenv().StopTween() end
                    return
                end

                HopSystem.IsHopping = false
                HopSystem.RetryCount = (HopSystem.RetryCount or 0) + 1
                if HopSystem.RetryCount <= 2 then
                    HopSystem.NextAllowedHop = tick() + 15
                    CurrentFarmStatus = "Đổi server lỗi (" .. errText .. "), thử lại (" .. HopSystem.RetryCount .. "/2) sau 15s..."
                    task.delay(15, function()
                        if HopServer and HopSystem.RetryCount > 0 and HopSystem.RetryCount <= 2 and not HopSystem.IsHopping then
                            HopServer("Thử lại (" .. HopSystem.RetryCount .. "/2)...")
                        end
                    end)
                else
                    HopSystem.RetryCount = 0
                    HopSystem.NextAllowedHop = tick() + 45
                    CurrentFarmStatus = "Tạm dừng đổi server (chống lag), tiếp tục farm tại server hiện tại..."
                end
            end
        end)
    end
end)

function HopSystem.Teleport(jobId)
    if not jobId or tostring(jobId) == "" then return end
    jobId = tostring(jobId):gsub("%s+", "")
    HopSystem.VisitedServers[jobId] = true

    -- Trong Blox Fruits, đổi server theo JobId BẮT BUỘC phải dùng Remote __ServerBrowser
    -- để server Blox Fruits cấp teleport token hợp lệ cho Roblox.
    -- Gọi trực tiếp TeleportToPlaceInstance ở client sẽ bị chặn lỗi: "Cannot teleport without a valid teleport token"
    local sb = ReplicatedStorage:FindFirstChild("__ServerBrowser")
    local remoteInvoked = false
    if sb then
        local ok = pcall(function()
            sb:InvokeServer("teleport", jobId)
        end)
        remoteInvoked = ok
    end

    if not remoteInvoked then
        pcall(function()
            TeleportService:TeleportToPlaceInstance(game.PlaceId, jobId, plr)
        end)
    end
end

-- ==========================================
-- REJOIN CONTROLLER THỐNG NHẤT + RELOAD SAU TELEPORT + NHỚ SERVER ĐÃ THỬ (chuyển từ bản v14)
-- Thay cho 3 handler cũ (ErrorMessageChanged / TeleportInitFailed / watchdog) vốn cùng gọi Teleport() liên tục.
-- Muốn script tự chạy lại sau hop/rejoin: getgenv().KaitunLoader = 'loadstring(game:HttpGet("URL"))()'
--   hoặc getgenv().KaitunLoaderFile = "ten_file.lua" (file trong workspace executor) hoặc dùng autoexec.
-- ==========================================
if not pcall(function()
    local TS = game:GetService("TeleportService")
    local HS = game:GetService("HttpService")
    local GS = game:GetService("GuiService")
    local G = getgenv()
    if type(G.Z9_RejoinStop) == "function" then pcall(G.Z9_RejoinStop) end

    local alive, conns = true, {}
    local R = { Busy = false, LastTeleportFail = 0, Queued = false }
    G.Z9_Rejoin = R
    G.Z9_RejoinStop = function()
        alive = false
        for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
    end

    -- ---------- Nhớ server đã thử (bền qua teleport) ----------
    local FILE = "Kaitun_TriedServers.json"
    local canFile = type(writefile) == "function" and type(readfile) == "function" and type(isfile) == "function"
    local stamp = {}
    HopSystem.VisitedServers = HopSystem.VisitedServers or {}
    local function Save()
        if canFile then pcall(function() writefile(FILE, HS:JSONEncode(stamp)) end) end
    end
    if canFile then
        pcall(function()
            if not isfile(FILE) then return end
            local t = HS:JSONDecode(readfile(FILE))
            local now = os.time()
            if type(t) == "table" then
                for id, ts in pairs(t) do
                    if type(id) == "string" and type(ts) == "number" and now - ts <= 1800 and ts <= now + 60 then
                        stamp[id] = ts
                        HopSystem.VisitedServers[id] = true
                    end
                end
            end
        end)
    end
    if game.JobId ~= "" then
        stamp[game.JobId] = os.time()
        HopSystem.VisitedServers[game.JobId] = true
    end
    Save()

    -- ---------- Xếp script chạy lại sau teleport ----------
    local function QueueReload()
        if R.Queued then return end
        local q = queue_on_teleport or (syn and syn.queue_on_teleport) or (fluxus and fluxus.queue_on_teleport)
        if not q then return end
        local loader, lf = G.KaitunLoader, G.KaitunLoaderFile
        if (type(loader) ~= "string" or loader == "") and type(lf) == "string" and lf ~= "" then
            loader = string.format("loadstring(readfile(%q))()", lf)
        end
        if type(loader) ~= "string" or loader == "" then return end
        local code = "if not game:IsLoaded() then game.Loaded:Wait() end\n"
            .. "getgenv().KaitunLoader=" .. string.format("%q", loader)
        if type(lf) == "string" and lf ~= "" then code = code .. "\ngetgenv().KaitunLoaderFile=" .. string.format("%q", lf) end
        code = code .. "\n" .. loader
        if pcall(q, code) then R.Queued = true end
    end
    if type(G.KaitunLoader) ~= "string" and type(G.KaitunLoaderFile) ~= "string" then
        warn("[Kaitun] Chưa đặt getgenv().KaitunLoader / KaitunLoaderFile: sau hop/rejoin script chỉ tự chạy lại nếu bạn dùng autoexec.")
    end

    -- Hop: xếp reload + ghi nhớ server đích trước khi teleport
    local origTeleport = HopSystem.Teleport
    HopSystem.Teleport = function(jobId, ...)
        local id = jobId and (tostring(jobId):gsub("%s+", "")) or nil
        if id and id ~= "" then
            stamp[id] = os.time()
            Save()
        end
        QueueReload()
        return origTeleport(jobId, ...)
    end

    -- ---------- Rejoin ----------
    local function Hopping()
        return HopSystem.IsHopping == true and tick() - (HopSystem.LastHopTick or 0) < 45
    end

    local function Rejoin(why)
        if not alive or R.Busy then return end
        R.Busy = true
        QueueReload()
        CurrentFarmStatus = "Rejoin: " .. tostring(why)
        task.spawn(function()
            for i = 1, 10 do
                if not alive then break end
                pcall(DismissRobloxErrorPrompt)
                pcall(function() TS:Teleport(game.PlaceId, plr) end)
                task.wait(math.min(8 + i * 3, 30))   -- chờ tăng dần, không spam Teleport
            end
            R.Busy = false
        end)
    end

    local function Trigger(why)
        if not alive or R.Busy or Hopping() then return end
        if tick() - R.LastTeleportFail < 8 then return end   -- thông báo lỗi do chính teleport hop thất bại
        task.delay(3, function()
            if alive and not R.Busy and not Hopping() then Rejoin(why) end
        end)
    end

    table.insert(conns, TS.TeleportInitFailed:Connect(function(player)
        if player == plr then R.LastTeleportFail = tick() end
    end))
    table.insert(conns, GS.ErrorMessageChanged:Connect(function(msg)
        if type(msg) ~= "string" or msg == "" then return end
        -- Error 273: tài khoản đang chạy ở thiết bị khác -> rejoin sẽ đá phiên kia, không tự vào lại
        if tonumber(msg:match("rror [Cc]ode:?%s*(%d+)")) == 273 then return end
        Trigger("lỗi: " .. msg)
    end))
    pcall(function()
        table.insert(conns, game:GetService("NetworkClient").ChildRemoved:Connect(function()
            Trigger("mất kết nối mạng")
        end))
    end)
    task.spawn(function()
        while alive do
            task.wait(1)
            pcall(function()
                local rp = game:GetService("CoreGui"):FindFirstChild("RobloxPromptGui")
                local ov = rp and rp:FindFirstChild("promptOverlay")
                local ep = ov and ov:FindFirstChild("ErrorPrompt")
                if ep and ep.Visible then Trigger("có ErrorPrompt") end
            end)
        end
    end)
end) then warn("[Kaitun] Rejoin controller lỗi khi khởi tạo") end

function HopServer(reason)
    if HopSystem.IsHopping then return end
    if tick() < (HopSystem.NextAllowedHop or 0) then return end
    HopSystem.IsHopping = true
    HopSystem.LastHopTick = tick()
    HopSystem.NextAllowedHop = tick() + 15
    if getgenv().StopTween then getgenv().StopTween() end

    CurrentFarmStatus = "Đang đổi server (" .. tostring(reason or "Hop Server") .. ")..."

    local hopSuccess = false

    -- 1. ƯU TIÊN 1: Cloudflare Worker API Hop Server Singapore (Token VIP bảo mật)
    pcall(function()
        local reqFn = (syn and syn.request) or (http and http.request) or http_request or request
        local apiUrl = "https://server.x9runner.workers.dev/api/hop?token=" .. tostring(HopSystem.Token) .. "&placeId=" .. tostring(game.PlaceId) .. "&exclude=" .. tostring(game.JobId)
        local bodyStr = nil

        if reqFn then
            local res = reqFn({
                Url = apiUrl,
                Method = "GET",
                Headers = {
                    ["x-hop-token"] = tostring(HopSystem.Token),
                    ["Content-Type"] = "application/json"
                }
            })
            if res and res.Body then bodyStr = res.Body end
        else
            bodyStr = game:HttpGet(apiUrl)
        end

        if bodyStr then
            local ok, parsed = pcall(function() return HttpService:JSONDecode(bodyStr) end)
            if ok and parsed and parsed.success and (parsed.jobId or (type(parsed.candidates) == "table" and #parsed.candidates > 0)) then
                local chosenId = parsed.jobId
                local chosenPing = parsed.ping or 99
                local chosenPlaying = parsed.playing or 0

                -- Nếu có danh sách candidates, chọn ngẫu nhiên 1 trong top 10 server ping tốt nhất chưa vào
                if type(parsed.candidates) == "table" and #parsed.candidates > 0 then
                    local validList = {}
                    for _, cand in ipairs(parsed.candidates) do
                        local cId = tostring(cand.id or "")
                        if cId ~= "" and cId ~= tostring(game.JobId) and not HopSystem.VisitedServers[cId] then
                            table.insert(validList, cand)
                        end
                    end
                    if #validList > 0 then
                        local pickPool = math.min(10, #validList)
                        local chosen = validList[math.random(1, pickPool)]
                        chosenId = chosen.id
                        chosenPing = chosen.ping
                        chosenPlaying = chosen.playing
                    end
                end

                if chosenId and chosenId ~= "" and not HopSystem.VisitedServers[chosenId] then
                    hopSuccess = true
                    CurrentFarmStatus = "Đang đổi sang Server Singapore Cloudflare (" .. tostring(chosenPing) .. "ms, " .. tostring(chosenPlaying) .. " người)..."
                    HopSystem.Teleport(chosenId)
                    task.wait(6)
                end
            end
        end
    end)

    -- 2. DỰ PHÒNG 2: Roblox Public Servers API chính thức (Nếu API backend chưa bật hoặc không có phản hồi)
    if not hopSuccess then
        pcall(function()
            local cursor = ""
            for attempt = 1, 3 do
                if hopSuccess then break end
                local url = "https://games.roblox.com/v1/games/" .. tostring(game.PlaceId) .. "/servers/Public?sortOrder=Asc&limit=100" .. (cursor ~= "" and ("&cursor=" .. cursor) or "")
                local reqFn = (syn and syn.request) or (http and http.request) or http_request or request
                local bodyStr = nil
                if reqFn then
                    local res = reqFn({ Url = url, Method = "GET" })
                    if res and res.Body then bodyStr = res.Body end
                else
                    bodyStr = game:HttpGet(url)
                end
                if bodyStr then
                    local ok, parsed = pcall(function() return HttpService:JSONDecode(bodyStr) end)
                    if ok and parsed and type(parsed.data) == "table" and #parsed.data > 0 then
                        local candidates = {}
                        for _, srv in ipairs(parsed.data) do
                            local sId = tostring(srv.id or "")
                            local playing = tonumber(srv.playing) or 0
                            local maxPlayers = tonumber(srv.maxPlayers) or (game.Players.MaxPlayers or 12)
                            local sPing = tonumber(srv.ping) or 999
                            if sId ~= "" and sId ~= tostring(game.JobId) and not HopSystem.VisitedServers[sId] then
                                if playing >= 1 and playing <= (maxPlayers - 1) and sPing <= 180 then
                                    table.insert(candidates, { id = sId, playing = playing, maxPlayers = maxPlayers, ping = sPing })
                                end
                            end
                        end

                        if #candidates > 0 then
                            local chosen = candidates[math.random(1, math.min(10, #candidates))]
                            hopSuccess = true
                            CurrentFarmStatus = "Đang đổi sang server Roblox (" .. tostring(chosen.ping) .. "ms, " .. tostring(chosen.playing) .. "/" .. tostring(chosen.maxPlayers) .. " người)..."
                            HopSystem.Teleport(chosen.id)
                            task.wait(6)
                            break
                        end

                        if parsed.nextPageCursor and tostring(parsed.nextPageCursor) ~= "" and tostring(parsed.nextPageCursor) ~= "null" then
                            cursor = tostring(parsed.nextPageCursor)
                        else
                            break
                        end
                    end
                end
            end
        end)
    end

    -- 3. DỰ PHÒNG 3: Dùng Remote __ServerBrowser tích hợp của Blox Fruits
    if not hopSuccess then
        pcall(function()
            local sb = ReplicatedStorage:FindFirstChild("__ServerBrowser")
            if sb then
                for page = 1, 5 do
                    if hopSuccess then break end
                    local ok, servers = pcall(function() return sb:InvokeServer(page) end)
                    if ok and type(servers) == "table" then
                        local sbCandidates = {}
                        for sJobId, sInfo in pairs(servers) do
                            sJobId = tostring(sJobId)
                            if sJobId ~= tostring(game.JobId) and not HopSystem.VisitedServers[sJobId] then
                                local count = (type(sInfo) == "table" and sInfo.Count and tonumber(sInfo.Count)) or 0
                                local maxP = (type(sInfo) == "table" and sInfo.MaxPlayers and tonumber(sInfo.MaxPlayers)) or (game.Players.MaxPlayers or 12)
                                if count >= 1 and count <= (maxP - 1) then
                                    table.insert(sbCandidates, { id = sJobId, count = count, maxP = maxP })
                                end
                            end
                        end
                        if #sbCandidates > 0 then
                            local chosen = sbCandidates[math.random(1, #sbCandidates)]
                            hopSuccess = true
                            CurrentFarmStatus = "Đang vào server qua Server Browser (" .. tostring(chosen.count) .. "/" .. tostring(chosen.maxP) .. " người)..."
                            sb:InvokeServer("teleport", chosen.id)
                            task.wait(6)
                            break
                        end
                    end
                end
            end
        end)
    end

    -- 4. DỰ PHÒNG 4: Tự động ghép phòng ngẫu nhiên của Roblox TeleportService
    if not hopSuccess then
        pcall(function()
            CurrentFarmStatus = "Đang đổi server qua TeleportService..."
            TeleportService:Teleport(game.PlaceId, plr)
            task.wait(6)
            hopSuccess = true
        end)
    end

    if not hopSuccess then
        HopSystem.NextAllowedHop = tick() + 30
        CurrentFarmStatus = "Không tìm thấy server phù hợp, tiếp tục farm tại server hiện tại..."
        task.wait(2)
        HopSystem.IsHopping = false
    else
        -- KHI ĐÃ GỌI TELEPORT THÀNH CÔNG:
        -- Roblox đang thực hiện chuyển server (in processing).
        -- TUYỆT ĐỐI GIỮ HopSystem.IsHopping = true để ngăn mọi tác vụ khác gọi teleport đè lên!
        HopSystem.NextAllowedHop = tick() + 90
        CurrentFarmStatus = "Đang chuyển sang server mới, vui lòng chờ Roblox kết nối..."
        if getgenv().StopTween then getgenv().StopTween() end

        -- Watchdog 60s: nếu sau 60s vẫn ở server cũ (teleport bị Roblox âm thầm bỏ qua mà không callback) -> reset để farm tiếp
        local currentJobId = tostring(game.JobId)
        task.delay(60, function()
            if HopSystem.IsHopping and tostring(game.JobId) == currentJobId then
                HopSystem.IsHopping = false
                HopSystem.NextAllowedHop = tick() + 30
                CurrentFarmStatus = "Thời gian chờ đổi server quá lâu (timeout), tiếp tục farm tại server hiện tại..."
            end
        end)
    end
end

