function HopSystem.GetChannelUrl(targetName)
    local slug = nil
    local placeId = game.PlaceId
    if targetName then
        local tLow = string.lower(tostring(targetName))
        for name, info in pairs(HopSystem.Channels) do
            if string.lower(name) == tLow or (info.Slug and string.lower(info.Slug) == tLow) then
                slug = info.Slug
                placeId = info.PlaceId or placeId
                break
            end
            if info.Aliases then
                for _, al in ipairs(info.Aliases) do
                    if string.lower(al) == tLow then
                        slug = info.Slug
                        placeId = info.PlaceId or placeId
                        break
                    end
                end
            end
            if slug then break end
        end
    end

    if slug then
        return string.format("%s/%s?token=%s&placeId=%s&exclude=%s",
            HopSystem.BaseUrl,
            slug,
            HopSystem.Token,
            tostring(placeId),
            tostring(game.JobId)
        ), slug
    end

    return string.format("%s/hop?token=%s&placeId=%s&exclude=%s",
        HopSystem.BaseUrl,
        HopSystem.Token,
        tostring(game.PlaceId),
        tostring(game.JobId)
    ), "hop"
end

local function CheckBossIsAliveInServer(bossName)
    local targetModels = { bossName }
    for canonical, info in pairs(HopSystem.Channels) do
        if canonical:lower() == bossName:lower() or (info.Slug and info.Slug:lower() == bossName:lower()) then
            targetModels = info.Models or targetModels
            break
        end
        if info.Aliases then
            for _, al in ipairs(info.Aliases) do
                if al:lower() == bossName:lower() then
                    targetModels = info.Models or targetModels
                    break
                end
            end
        end
    end
    local enemies = workspace:FindFirstChild("Enemies")
    if enemies then
        for _, enemy in ipairs(enemies:GetChildren()) do
            for _, mName in ipairs(targetModels) do
                if enemy.Name == mName then
                    local hum = enemy:FindFirstChildOfClass("Humanoid")
                    local hrp = enemy:FindFirstChild("HumanoidRootPart")
                    if hum and hrp and hum.Health > 0 then
                        return enemy
                    end
                end
            end
        end
    end
    for _, obj in ipairs(game:GetService("ReplicatedStorage"):GetChildren()) do
        for _, mName in ipairs(targetModels) do
            if obj.Name == mName then
                local hum = obj:FindFirstChildOfClass("Humanoid")
                local hrp = obj:FindFirstChild("HumanoidRootPart")
                if hum and hrp and hum.Health > 0 then
                    return obj
                end
            end
        end
    end
    return nil
end

local function HopBoss(bossName, reason, stopCondition)
    if not bossName or bossName == "" then
        return HopServer(reason)
    end

    if CheckBossIsAliveInServer(bossName) then
        return true
    end

    if HopSystem.IsHopping then return false end
    if tick() < (HopSystem.NextAllowedHop or 0) then return false end

    local function isCancelled()
        if type(stopCondition) == "function" then
            local ok, val = pcall(stopCondition)
            return ok and val == true
        end
        return false
    end
    if isCancelled() then return false end

    local reqUrl, channelSlug = HopSystem.GetChannelUrl(bossName)
    local reqFn = (syn and syn.request) or (http and http.request) or http_request or request
    local bodyStr = nil

    CurrentFarmStatus = string.format("Đang tìm server kênh riêng [%s] (%s) qua Cloudflare API...", tostring(channelSlug), tostring(bossName))

    pcall(function()
        if reqFn then
            local res = reqFn({
                Url = reqUrl,
                Method = "GET",
                Headers = {
                    ["x-hop-token"] = HopSystem.Token,
                    ["Content-Type"] = "application/json"
                }
            })
            if res and res.Body then bodyStr = res.Body end
        else
            bodyStr = game:HttpGet(reqUrl)
        end
    end)

    if bodyStr then
        local ok, parsed = pcall(function() return HttpService:JSONDecode(bodyStr) end)
        if ok and parsed and parsed.success and (parsed.jobId or (type(parsed.candidates) == "table" and #parsed.candidates > 0)) then
            local chosenId = parsed.jobId
            local chosenPing = parsed.ping or 60

            if type(parsed.candidates) == "table" and #parsed.candidates > 0 then
                for _, cand in ipairs(parsed.candidates) do
                    local cId = tostring(cand.jobId or cand.id or "")
                    if cId ~= "" and cId ~= tostring(game.JobId) and not HopSystem.VisitedServers[cId] then
                        chosenId = cId
                        chosenPing = cand.ping or chosenPing
                        break
                    end
                end
            end

            if chosenId and chosenId ~= "" and chosenId ~= tostring(game.JobId) and not isCancelled() then
                HopSystem.IsHopping = true
                HopSystem.LastHopTick = tick()
                HopSystem.NextAllowedHop = tick() + 90
                CurrentFarmStatus = string.format("Đã tìm thấy kênh [%s]! Đang đổi server (%sms)...", tostring(channelSlug), tostring(chosenPing))
                HopSystem.Teleport(chosenId)
                task.wait(6)
                return true
            end
        end
    end

    return HopServer(reason or ("Hop tìm kênh " .. tostring(channelSlug or bossName)))
end

-- VÒNG LẶP CHẠY NGẦM BÁO CÁO TOÀN BỘ 40 KÊNH BOSS, KIẾM TTK & SỰ KIỆN LÊN CLOUDFLARE WORKER
task.spawn(function()
    task.wait(5)
    local reported = {}
    local reqFn = (syn and syn.request) or (http and http.request) or http_request or request
    while true do
        pcall(function()
            local aliveNow = {}

            -- 1. Quét toàn bộ Boss trong 40 kênh
            for canonical, info in pairs(HopSystem.Channels) do
                if info.Category == "Boss" then
                    local obj = CheckBossIsAliveInServer(canonical)
                    if obj then
                        aliveNow[info.Slug] = canonical
                    end
                end
            end

            -- 2. Quét Legendary Sword Dealer & Kiếm TTK tại Sea 2
            if (World2 or CurrentSeaNum == 2 or game.PlaceId == 4442272183) then
                local dealerNpc = (workspace:FindFirstChild("NPCs") and workspace.NPCs:FindFirstChild("Legendary Sword Dealer"))
                    or (ReplicatedStorage:FindFirstChild("NPCs") and ReplicatedStorage.NPCs:FindFirstChild("Legendary Sword Dealer"))
                if dealerNpc then
                    aliveNow["ttk"] = "Legendary Sword Dealer"
                end
            end

            -- 3. Quét Mirage Island / Đảo Bí Ẩn tại Sea 3
            if (World3 or CurrentSeaNum == 3 or game.PlaceId == 7449423635) then
                local mirage = (workspace:FindFirstChild("_WorldOrigin") and workspace._WorldOrigin:FindFirstChild("Locations") and workspace._WorldOrigin.Locations:FindFirstChild("Mirage Island"))
                    or (workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("MysticIsland"))
                    or workspace:FindFirstChild("Mirage")
                if mirage then
                    aliveNow["mirage_island"] = "Mirage Island"
                end
            end

            -- 4. Báo cáo các kênh đang có mặt lên API POST /api/boss/report
            for slug, bossTitle in pairs(aliveNow) do
                if not reported[slug] or (tick() - (reported[slug] or 0) >= 25) then
                    reported[slug] = tick()
                    if reqFn then
                        pcall(function()
                            reqFn({
                                Url = HopSystem.ReportUrl,
                                Method = "POST",
                                Headers = {
                                    ["Content-Type"] = "application/json",
                                    ["x-hop-token"] = HopSystem.Token
                                },
                                Body = HttpService:JSONEncode({
                                    token = HopSystem.Token,
                                    placeId = tostring(game.PlaceId),
                                    jobId = tostring(game.JobId),
                                    boss = slug,
                                    name = tostring(bossTitle),
                                    ping = GetCurrentPingMs(),
                                    players = #Players:GetPlayers(),
                                    maxPlayers = Players.MaxPlayers or 12
                                })
                            })
                        end)
                    end
                end
            end

            -- 5. Xóa khỏi danh sách báo cáo nếu Boss/Vật thể đã biến mất
            for slug, _ in pairs(reported) do
                if not aliveNow[slug] then
                    reported[slug] = nil
                    if reqFn then
                        pcall(function()
                            reqFn({
                                Url = HopSystem.BaseUrl .. "/boss/remove",
                                Method = "POST",
                                Headers = {
                                    ["Content-Type"] = "application/json",
                                    ["x-hop-token"] = HopSystem.Token
                                },
                                Body = HttpService:JSONEncode({
                                    token = HopSystem.Token,
                                    jobId = tostring(game.JobId),
                                    boss = slug
                                })
                            })
                        end)
                    end
                end
            end
        end)
        task.wait(6)
    end
end)

getgenv().HopBoss = HopBoss
getgenv().HopChannel = HopBoss
getgenv().CheckBossIsAliveInServer = CheckBossIsAliveInServer

LastTravelAttempt = 0

local function DoAutoSaberStep(hrp, hum)
    if not hrp or not hum or hum.Health <= 0 then
        return false
    end

    if type(HasSaberSword) == "function" and HasSaberSword() then
        return true
    end

    local function doorsaber()
        local map = workspace:FindFirstChild("Map")
        local jungle = map and map:FindFirstChild("Jungle")
        local jungleFinal = jungle and jungle:FindFirstChild("Final")
        if not jungleFinal then
            return false
        end

        local parts = jungleFinal:GetChildren()
        if #parts == 0 then
            return false
        end

        for _, l in ipairs(parts) do
            if l:IsA("BasePart") and (not l.CanCollide or l.Transparency > 0.5) then
                return true
            end
        end

        return false
    end

    local isDoorOpen = doorsaber()
    -- TODO: Thêm các bước tiếp theo tại đây:
    -- 1. Nếu chưa mở cửa (not isDoorOpen): giải puzzle nút / đuốc ở Jungle
    -- 2. Nếu đã mở cửa (isDoorOpen): TP vào phòng trong Jungle và đánh Saber Expert (Shanks)

    return false
end

    local function doorcup()
        local desertBurn = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Desert") and workspace.Map.Desert:FindFirstChild("Burn")
        if desertBurn then
            local parts = desertBurn:GetChildren()
            if #parts == 0 then return true end
            for _, l in ipairs(parts) do
                if l:IsA("BasePart") and (not l.CanCollide or l.Transparency > 0.5) then
                    return true
                end
            end
        end
        return false
    end

    local function doortourch()
        local plates = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Jungle") and workspace.Map.Jungle:FindFirstChild("QuestPlates")
        if plates then
            for _, l in ipairs(plates:GetChildren()) do
                if l:IsA("Model") and l:FindFirstChild("Button") and l.Button:FindFirstChild("TouchInterest") then
                    return l
                end
            end
        end
        return nil
    end

    -- Hủy nhiệm vụ farm cấp thường nếu đang nhận dở để tập trung làm Saber
    if HasActiveQuest() then
        pcall(function()
            ReplicatedStorage.Remotes.CommF_:InvokeServer("AbandonQuest")
        end)
        ResetQuestSeen()
    end

    -- =========================================================================
    -- KIỂM TRA TOÀN DIỆN TIẾN TRÌNH NHIỆM VỤ SABER CỦA BẢN THÂN NGƯỜI CHƠI
    -- (Tuyệt đối không bỏ qua bước kể cả khi cửa Shanks đã bị người chơi khác mở trước)
    -- =========================================================================

    local unpressedPlate = doortourch()
    local platesDoor = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Jungle") and workspace.Map.Jungle:FindFirstChild("QuestPlates") and workspace.Map.Jungle.QuestPlates:FindFirstChild("Door")

    -- BƯỚC 1: Nếu còn nút Jungle chưa giẫm hoặc cửa hầm Jungle chưa mở
    if unpressedPlate or (platesDoor and platesDoor.CanCollide) then
        CurrentFarmStatus = "[Nhiệm vụ Saber - Bước 1/5] Đang giẫm 5 nút bấm bí mật tại Jungle..."
        if unpressedPlate and unpressedPlate:FindFirstChild("Button") then
            TweenTo(unpressedPlate.Button.CFrame)
            pcall(function()
                firetouchinterest(hrp, unpressedPlate.Button, 0)
                firetouchinterest(hrp, unpressedPlate.Button, 1)
            end)
        else
            local plateButtons = {
                CFrame.new(-1612.55, 36.98, 148.72),
                CFrame.new(-1448.24, 29.85, 50.85),
                CFrame.new(-1610.08, 36.85, 266.38),
                CFrame.new(-1750.68, 36.85, 8.68),
                CFrame.new(-1625.35, 36.85, -172.63),
            }
            for _, btnCF in ipairs(plateButtons) do
                TweenTo(btnCF * CFrame.new(0, 1.5, 0))
                task.wait(0.12)
            end
            local platesFolder = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Jungle") and workspace.Map.Jungle:FindFirstChild("QuestPlates")
            if platesFolder then
                for _, plate in ipairs(platesFolder:GetChildren()) do
                    if plate:IsA("Model") and plate:FindFirstChild("Button") then
                        pcall(function()
                            firetouchinterest(hrp, plate.Button, 0)
                            firetouchinterest(hrp, plate.Button, 1)
                        end)
                    end
                end
            end
        end
        return
    end

    -- BƯỚC 2: Nếu chưa có Cốc (Cup), chưa có Cổ Vật (Relic) VÀ cửa nhà sập Sa Mạc chưa cháy mở
    local torch = (plr.Character and plr.Character:FindFirstChild("Torch")) or (plr.Backpack and plr.Backpack:FindFirstChild("Torch"))
    local cup = (plr.Character and plr.Character:FindFirstChild("Cup")) or (plr.Backpack and plr.Backpack:FindFirstChild("Cup"))
    local relic = (plr.Character and plr.Character:FindFirstChild("Relic")) or (plr.Backpack and plr.Backpack:FindFirstChild("Relic"))
    if not cup and not relic and not doorcup() then
        if not torch then
            CurrentFarmStatus = "[Nhiệm vụ Saber - Bước 2/5] Đang xuống hầm Jungle nhặt Cây Đuốc (Torch)..."
            local torchItem = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Jungle") and workspace.Map.Jungle:FindFirstChild("Torch")
            local torchCF = torchItem and torchItem.CFrame or CFrame.new(-1610.0, 11.5, 164.0)
            TweenTo(torchCF)
            if torchItem and firetouchinterest then
                pcall(function()
                    firetouchinterest(hrp, torchItem, 0)
                    firetouchinterest(hrp, torchItem, 1)
                end)
            end
        else
            CurrentFarmStatus = "[Nhiệm vụ Saber - Bước 2/5] Đang cầm Đuốc đốt cửa nhà sập Sa Mạc..."
            if plr.Backpack and plr.Backpack:FindFirstChild("Torch") then
                hum:EquipTool(plr.Backpack.Torch)
            end
            local desertBurnCF = CFrame.new(1114.6, 5.0, 4350.2)
            TweenTo(desertBurnCF)
            local fire = (workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Desert") and workspace.Map.Desert:FindFirstChild("Burn") and workspace.Map.Desert.Burn:FindFirstChild("Fire"))
            if fire and firetouchinterest and plr.Character and plr.Character:FindFirstChild("Torch") then
                local handle = plr.Character.Torch:FindFirstChild("Handle") or hrp
                pcall(function()
                    firetouchinterest(handle, fire, 0)
                    firetouchinterest(handle, fire, 1)
                end)
            end
        end
        return
    end

    -- BƯỚC 3, 4, 5: Kiểm tra tiến trình của SickMan và RichSon từ Server
    local sickProg = nil
    pcall(function()
        sickProg = ReplicatedStorage.Remotes.CommF_:InvokeServer("ProQuestProgress", "SickMan")
    end)

    local richProg = nil
    pcall(function()
        richProg = ReplicatedStorage.Remotes.CommF_:InvokeServer("ProQuestProgress", "RichSon")
    end)

    local relic = (plr.Character and plr.Character:FindFirstChild("Relic")) or (plr.Backpack and plr.Backpack:FindFirstChild("Relic"))

    -- BƯỚC 3: Nếu SickMan chưa xong (sickProg ~= 0) VÀ bản thân chưa tiến tới RichSon
    if (richProg ~= 0 and richProg ~= 1) and (sickProg ~= 0) then
        local cup = (plr.Character and plr.Character:FindFirstChild("Cup")) or (plr.Backpack and plr.Backpack:FindFirstChild("Cup"))
        if not cup then
            CurrentFarmStatus = "[Nhiệm vụ Saber - Bước 3/5] Đang vào nhà Sa Mạc nhặt Cốc (Cup)..."
            local cupCF = CFrame.new(1113.6, 7.5, 4365.3)
            TweenTo(cupCF)
            local cupItem = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Desert") and workspace.Map.Desert:FindFirstChild("Cup")
            if cupItem and firetouchinterest then
                pcall(function()
                    firetouchinterest(cupItem, hrp, 0)
                    firetouchinterest(cupItem, hrp, 1)
                end)
            end
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("ProQuestProgress", "GetCup")
            end)
        else
            if plr.Backpack and plr.Backpack:FindFirstChild("Cup") then
                hum:EquipTool(plr.Backpack.Cup)
            end
            local cupTool = (plr.Character and plr.Character:FindFirstChild("Cup")) or (plr.Backpack and plr.Backpack:FindFirstChild("Cup"))
            local isCupEmpty = cupTool and cupTool:FindFirstChild("Handle") and cupTool.Handle:FindFirstChild("TouchInterest")

            if isCupEmpty then
                CurrentFarmStatus = "[Nhiệm vụ Saber - Bước 3/5] Đang hứng nước giọt băng tại Frozen Village..."
                TweenTo(CFrame.new(1395.77, 37.47, -1324.35))
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("ProQuestProgress", "FillCup", cupTool)
                end)
            else
                CurrentFarmStatus = "[Nhiệm vụ Saber - Bước 3/5] Đang đưa Cốc nước cho Người Bệnh (Sick Man)..."
                local sickManPos = Vector3.new(1457.88, 88.38, -1390.69)
                if (hrp.Position - sickManPos).Magnitude > 8 then
                    TweenTo(CFrame.new(sickManPos))
                else
                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("ProQuestProgress", "SickMan")
                    end)
                end
            end
        end
        return
    end

    -- BƯỚC 4: Nói chuyện với Rich Son lần đầu (khi richProg == nil)
    if richProg == nil then
        CurrentFarmStatus = "[Nhiệm vụ Saber - Bước 4/5] Đang nói chuyện với Rich Son tại Pirate Village..."
        local richSonPos = Vector3.new(-1404.08, 29.85, 5.27)
        if (hrp.Position - richSonPos).Magnitude > 8 then
            TweenTo(CFrame.new(richSonPos))
        else
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("ProQuestProgress", "RichSon")
            end)
        end
        return
    end

    -- BƯỚC 4.5: Tiêu diệt Boss Mob Leader [Lv. 120] (khi richProg == 0)
    if richProg == 0 then
        local mobLeader = nil
        for _, obj in ipairs(workspace.Enemies:GetChildren()) do
            local hum = obj:FindFirstChildOfClass("Humanoid")
            if obj.Name == "Mob Leader" and hum and hum.Health > 0 and obj:FindFirstChild("HumanoidRootPart") then
                mobLeader = obj
                break
            end
        end
        if not mobLeader then
            for _, obj in ipairs(ReplicatedStorage:GetChildren()) do
                local hum = obj:FindFirstChildOfClass("Humanoid")
                if obj.Name == "Mob Leader" and hum and hum.Health > 0 and obj:FindFirstChild("HumanoidRootPart") then
                    mobLeader = obj
                    break
                end
            end
        end

        if mobLeader then
            getgenv()._mobLeaderNotFoundTime = nil
            CurrentFarmStatus = "[Nhiệm vụ Saber - Bước 4/5] Đang tiêu diệt Mob Leader [Lv. 120] lấy lại tiền..."
            getgenv()._currentTargetMobName = "Mob Leader"
            DisableMobCollision(mobLeader)
            EnableBuso()
            EquipSelectedWeapon()
            TweenTo(mobLeader.HumanoidRootPart.CFrame * CFrame.new(0, 20, 0))
        else
            local mobLeaderCF = CFrame.new(-2967.6, -4.9, 5328.7)
            local distToMobLeader = (hrp.Position - mobLeaderCF.Position).Magnitude
            if distToMobLeader > 120 then
                getgenv()._mobLeaderNotFoundTime = nil
                CurrentFarmStatus = "[Nhiệm vụ Saber - Bước 4/5] Đang bay tới bãi spawn kiểm tra Boss Mob Leader..."
                TweenTo(mobLeaderCF * CFrame.new(0, 15, 0))
            else
                local now = tick()
                if not getgenv()._mobLeaderNotFoundTime then
                    getgenv()._mobLeaderNotFoundTime = now
                end
                local waitElapsed = now - getgenv()._mobLeaderNotFoundTime
                CurrentFarmStatus = "[Nhiệm vụ Saber - Bước 4/5] Đang quét kiểm tra Boss Mob Leader tại bãi spawn (" .. string.format("%.1f", math.max(0, 2.5 - waitElapsed)) .. "s)..."
                TweenTo(mobLeaderCF * CFrame.new(0, 15, 0))
                if waitElapsed >= 2.5 then
                    getgenv()._mobLeaderNotFoundTime = nil
                    if IsAutoHopEnabled() and tick() >= (HopSystem.NextAllowedHop or 0) then
                        CurrentFarmStatus = "[Nhiệm vụ Saber - Bước 4/5] Boss Mob Leader chưa spawn -> Đang Hop Server kênh [mob_leader]..."
                        HopBoss("Mob Leader", "Mob Leader chưa hồi sinh")
                    else
                        CurrentFarmStatus = "[Nhiệm vụ Saber - Bước 4/5] Đang chờ Boss Mob Leader hồi sinh trong server..."
                        TweenTo(mobLeaderCF * CFrame.new(0, 15, 0))
                    end
                end
            end
        end
        return
    end

    -- BƯỚC 5: Đã diệt Mob Leader (richProg == 1) -> Lấy Relic từ Rich Son
    if richProg == 1 and not relic and not doorsaber() then
        CurrentFarmStatus = "[Nhiệm vụ Saber - Bước 5/5] Đang nhận Cổ Vật (Relic) từ Rich Son tại Pirate Village..."
        local richSonPos = Vector3.new(-1404.08, 29.85, 5.27)
        if (hrp.Position - richSonPos).Magnitude > 8 then
            TweenTo(CFrame.new(richSonPos))
        else
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("ProQuestProgress", "RichSon")
            end)
        end
        return
    end

    -- BƯỚC 5.5: CHỈ cắm Relic nếu người chơi có Relic VÀ cửa phòng Shanks CHƯA mở (not doorsaber())
    -- NẾU CỬA ĐÃ MỞ (doorsaber() == true) -> TUYỆT ĐỐI KHÔNG CẦM HAY SPAM CHÌA KHÓA NỮA!
    if relic and not doorsaber() then
        CurrentFarmStatus = "[Nhiệm vụ Saber - Bước 5/5] Cửa chưa mở -> Đang cầm Relic tới CỔNG phòng Shanks để mở cửa..."
        if plr.Backpack and plr.Backpack:FindFirstChild("Relic") then
            hum:EquipTool(plr.Backpack.Relic)
        end

        local finalPart = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Jungle") and workspace.Map.Jungle:FindFirstChild("Final") and workspace.Map.Jungle.Final:FindFirstChild("Part")
        -- Tọa độ chuẩn của Cổng phòng Shanks (Shanks Room Gate) ở Jungle: (-1442.165, 29.879, -28.355)
        local gateCF = (finalPart and finalPart.CFrame) or CFrame.new(-1442.165, 29.879, -28.355)

        TweenTo(gateCF)

        if finalPart and firetouchinterest then
            pcall(function()
                local toolHandle = plr.Character and plr.Character:FindFirstChild("Relic") and plr.Character.Relic:FindFirstChild("Handle")
                firetouchinterest(toolHandle or hrp, finalPart, 0)
                firetouchinterest(toolHandle or hrp, finalPart, 1)
            end)
        end
        pcall(function()
            ReplicatedStorage.Remotes.CommF_:InvokeServer("ProQuestProgress", "PlaceRelic")
        end)
        return
    end

    -- =========================================================================
    -- BƯỚC CUỐI CÙNG: TOÀN BỘ CÁC BƯỚC TRÊN ĐÃ HOÀN THÀNH, CỬA ĐÁ ĐÃ MỞ (doorsaber() == true)!
    -- BÂY GIỜ MỚI TIÊU DIỆT BOSS SABER EXPERT [LV. 200] ĐỂ NHẬN KIẾM SABER!
    -- =========================================================================
    local saberBoss = nil
for _, obj in ipairs(workspace.Enemies:GetChildren()) do
    local hum = obj:FindFirstChildOfClass("Humanoid")
    if obj.Name == "Saber Expert" and hum and hum.Health > 0 and obj:FindFirstChild("HumanoidRootPart") then
        saberBoss = obj
        break
    end
end
if not saberBoss then
    for _, obj in ipairs(ReplicatedStorage:GetChildren()) do
        local hum = obj:FindFirstChildOfClass("Humanoid")
        if obj.Name == "Saber Expert" and hum and hum.Health > 0 and obj:FindFirstChild("HumanoidRootPart") then
            saberBoss = obj
            break
        end
    end
end

if saberBoss then
    getgenv()._saberBossNotFoundTime = nil
    local sbHum = saberBoss:FindFirstChildOfClass("Humanoid")
    CurrentFarmStatus = "[Nhiệm vụ Saber] Đã hoàn tất nhiệm vụ! Đang tiêu diệt Boss Saber Expert [Lv. 200] (HP: " .. math.floor(sbHum and sbHum.Health or 100) .. ")..."
    getgenv()._currentTargetMobName = "Saber Expert"
    DisableMobCollision(saberBoss)
    EnableBuso()
    EquipSelectedWeapon()
    -- Shanks room có trần thấp (~14 studs) nên chỉ đứng cao 8 studs để giữ nhân vật ở trọn trong phòng, tầm đánh chuẩn xác
    TweenTo(saberBoss.HumanoidRootPart.CFrame * CFrame.new(0, 8, 0))
else
    local bossRoomCF = CFrame.new(-1458.895, 29.887, -50.633)
    local distToSaber = (hrp.Position - bossRoomCF.Position).Magnitude
    if distToSaber > 100 then
        getgenv()._saberBossNotFoundTime = nil
        CurrentFarmStatus = "[Nhiệm vụ Saber] Cửa đã mở! Đang bay tới phòng Shanks kiểm tra Boss Saber Expert..."
        TweenTo(bossRoomCF * CFrame.new(0, 5, 0))
    else
        local now = tick()
        if not getgenv()._saberBossNotFoundTime then
            getgenv()._saberBossNotFoundTime = now
        end
        local waitElapsed = now - getgenv()._saberBossNotFoundTime
        CurrentFarmStatus = "[Nhiệm vụ Saber] Cửa đã mở! Đang quét kiểm tra Boss Saber Expert tại phòng (" .. string.format("%.1f", math.max(0, 2.5 - waitElapsed)) .. "s)..."
        TweenTo(bossRoomCF * CFrame.new(0, 5, 0))
        if waitElapsed >= 2.5 then
            getgenv()._saberBossNotFoundTime = nil
            if IsAutoHopEnabled() and tick() >= (HopSystem.NextAllowedHop or 0) then
                CurrentFarmStatus = "[Nhiệm vụ Saber] Boss Saber Expert chưa spawn -> Đang Hop Server kênh [saber_expert]..."
                HopBoss("Saber Expert", "Saber Expert chưa hồi sinh")
            else
                CurrentFarmStatus = "[Nhiệm vụ Saber] Cửa đã mở! Đang chờ Boss Saber Expert hồi sinh trong server..."
                TweenTo(bossRoomCF * CFrame.new(0, 5, 0))
            end
        end
    end
end

-- ==========================================
-- HỆ THỐNG TỰ ĐỘNG LÀM TỘC RACE V2 & RACE V3 (SEA 2 - LEVEL >= 1000)
-- ==========================================

local function DoAutoBartiloQuestStep(hrp, hum, contextTag)
    local tag = contextTag or "[Auto Quest Bartilo]"
    local bProg = nil
    pcall(function()
        bProg = ReplicatedStorage.Remotes.CommF_:InvokeServer("BartiloQuestProgress", "Bartilo")
    end)

    if bProg == 0 or bProg == nil then
        local hasSwanQuest = IsBartiloActiveQuest()
        if not hasSwanQuest or not HasActiveQuest() then
            -- Nếu đang nhận dở quest thường khác -> Hủy quest cũ để nhận BartiloQuest
            if HasActiveQuest() and not hasSwanQuest then
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("AbandonQuest")
                end)
                ResetQuestSeen()
                task.wait(0.2)
            end

            CurrentFarmStatus = tag .. " Đang nhận nhiệm vụ Bartilo (Tiêu diệt 50 Swan Pirate)..."
            local bartiloCF = CFrame.new(-456.29, 73.02, 299.9)
            if (hrp.Position - bartiloCF.Position).Magnitude > 8 then
                TweenTo(bartiloCF)
            else
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("StartQuest", "BartiloQuest", 1)
                end)
                task.wait(0.5)
            end
        else
            local mob = GetNearestAliveMob("Swan Pirate")
            if mob and mob:FindFirstChild("HumanoidRootPart") and mob:FindFirstChildOfClass("Humanoid") and mob.Humanoid.Health > 0 then
                getgenv()._currentTargetMobName = "Swan Pirate"
                CurrentFarmStatus = tag .. " Đang hạ Swan Pirate hoàn thành nhiệm vụ Bartilo..."
                DisableMobCollision(mob)
                EnableBuso()
                EquipSelectedWeapon()
                TweenTo(mob.HumanoidRootPart.CFrame * CFrame.new(0, 15, 0))
            else
                CurrentFarmStatus = tag .. " Đang bay tới khu vực Swan Pirate..."
                TweenTo(CFrame.new(980, 121, 1287))
            end
        end
        return true
    elseif bProg == 1 then
        local jeremy = GetNearestAliveMob("Jeremy")
        if jeremy and jeremy:FindFirstChild("HumanoidRootPart") and jeremy:FindFirstChildOfClass("Humanoid") and jeremy.Humanoid.Health > 0 then
            getgenv()._jeremyNotFoundTime = nil
            getgenv()._currentTargetMobName = "Jeremy"
            CurrentFarmStatus = tag .. " Đang tiêu diệt Boss Jeremy [Lv. 850] hoàn thành nhiệm vụ Bartilo..."
            DisableMobCollision(jeremy)
            EnableBuso()
            EquipSelectedWeapon()
            TweenTo(jeremy.HumanoidRootPart.CFrame * CFrame.new(0, 15, 0))
        else
            getgenv()._jeremyNotFoundTime = getgenv()._jeremyNotFoundTime or tick()
            local waitElapsed = tick() - getgenv()._jeremyNotFoundTime
            if waitElapsed < 5 then
                CurrentFarmStatus = tag .. " Đang kiểm tra Boss Jeremy tại Đấu Trường (" .. string.format("%.1f", 5 - waitElapsed) .. "s)..."
                TweenTo(CFrame.new(2006, 448, 853))
            else
                if IsAutoHopEnabled() and tick() >= (HopSystem.NextAllowedHop or 0) then
                    CurrentFarmStatus = tag .. " Boss Jeremy chưa xuất hiện -> Đang Hop Server kênh [jeremy]..."
                    HopBoss("Jeremy", "Boss Jeremy chưa hồi sinh")
                else
                    CurrentFarmStatus = tag .. " Đang chờ Boss Jeremy hồi sinh trong server..."
                    TweenTo(CFrame.new(2006, 448, 853))
                end
            end
        end
        return true
    elseif bProg == 2 then
        CurrentFarmStatus = tag .. " Đang giải mật mã 8 tấm bia Colosseum..."
        local plates = (workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("BartiloPlates"))
            or (workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Dressrosa") and workspace.Map.Dressrosa:FindFirstChild("BartiloPlates"))
        if plates then
            for i = 1, 8 do
                local p = plates:FindFirstChild("Plate" .. i)
                if p and p:IsA("BasePart") then
                    TweenTo(p.CFrame)
                    pcall(function()
                        firetouchinterest(hrp, p, 0)
                        firetouchinterest(hrp, p, 1)
                    end)
                    task.wait(0.2)
                end
            end
        end
        return true
    end
    return false
end

local function DoTrevorUnlockStep(hrp, hum, contextTag)
    local tag = contextTag or "[Auto Race V3]"
    if IsSwanRoomUnlocked() then return true end

    local fruitName, isHeld = GetFruitWorth1MPlus()
    if not fruitName then
        CurrentFarmStatus = tag .. " Cần 1 trái Ác Quỷ > $1,000,000 Beli để mở cổng Don Swan (Trevor). Đang chờ có trái..."
        return false
    end

    if not isHeld then
        CurrentFarmStatus = tag .. " Đang lấy trái " .. tostring(fruitName) .. " (>1M Beli) từ rương đồ để đưa Trevor..."
        pcall(function()
            ReplicatedStorage.Remotes.CommF_:InvokeServer("LoadFruit", fruitName)
        end)
        task.wait(0.8)
        return true
    end

    local fruitTool = (plr.Backpack and plr.Backpack:FindFirstChild(fruitName)) or (plr.Character and plr.Character:FindFirstChild(fruitName))
    if not fruitTool then
        for _, cont in ipairs({ plr.Backpack, plr.Character }) do
            if cont then
                for _, t in ipairs(cont:GetChildren()) do
                    if t:IsA("Tool") and (t.ToolTip == "Blox Fruit" or t.Name:find("Fruit") or t:FindFirstChild("EatRemote", true)) then
                        local p = GetFruitPriceFromItem(t.Name)
                        if p >= 1000000 then
                            fruitTool = t
                            break
                        end
                    end
                end
            end
            if fruitTool then break end
        end
    end
    if fruitTool and plr.Backpack and fruitTool.Parent == plr.Backpack then
        hum:EquipTool(fruitTool)
    end

    local trevorCF = CFrame.new(-339.798, 331.86, 643.83)
    if (hrp.Position - trevorCF.Position).Magnitude > 8 then
        CurrentFarmStatus = tag .. " Đang bay tới Trevor tại Mansion nộp trái " .. tostring(fruitName) .. " mở cổng phòng Don Swan..."
        TweenTo(trevorCF)
    else
        CurrentFarmStatus = tag .. " Đang nói chuyện với Trevor đưa trái ác quỷ để mở cổng..."
        pcall(function()
            ReplicatedStorage.Remotes.CommF_:InvokeServer("TalkTrevor", "1")
            task.wait(0.2)
            ReplicatedStorage.Remotes.CommF_:InvokeServer("TalkTrevor", "2")
            task.wait(0.2)
            ReplicatedStorage.Remotes.CommF_:InvokeServer("TalkTrevor", "3")
        end)
        task.wait(0.5)
        LastTrevorCheck = 0
    end
    return true
end

local function DoKillDonSwanStep(hrp, hum, contextTag)
    local tag = contextTag or "[Auto Race V3]"
    if IsDonSwanKilled() then return true end

    local swanRoomCF = CFrame.new(2286.2, 15.2, 863.8)
    local inRoom = (hrp.Position - swanRoomCF.Position).Magnitude < 300

    if not inRoom then
        CurrentFarmStatus = tag .. " Đang yêu cầu vào phòng Boss Don Swan [Lv. 1000]..."
        pcall(function()
            ReplicatedStorage.Remotes.CommF_:InvokeServer("requestEntrance", Vector3.new(2285, 15, 905))
        end)
        task.wait(0.3)
        TweenTo(swanRoomCF)
        return true
    end

    local donSwan = nil
    for _, obj in ipairs(workspace.Enemies:GetChildren()) do
        local hum = obj:FindFirstChildOfClass("Humanoid")
        if obj.Name == "Don Swan" and hum and hum.Health > 0 and obj:FindFirstChild("HumanoidRootPart") then
            donSwan = obj
            break
        end
    end
    if not donSwan then
        for _, obj in ipairs(ReplicatedStorage:GetChildren()) do
            local hum = obj:FindFirstChildOfClass("Humanoid")
            if obj.Name == "Don Swan" and hum and hum.Health > 0 and obj:FindFirstChild("HumanoidRootPart") then
                donSwan = obj
                break
            end
        end
    end

    local dsHum = donSwan and donSwan:FindFirstChildOfClass("Humanoid")
    if donSwan and donSwan:FindFirstChild("HumanoidRootPart") and dsHum and dsHum.Health > 0 then
        getgenv()._attackingSwan = true
        getgenv()._swanBossNotFoundTime = nil
        getgenv()._currentTargetMobName = "Don Swan"
        CurrentFarmStatus = tag .. " Đang tiêu diệt Boss Don Swan [Lv. 1000] (HP: " .. math.floor(dsHum.Health) .. ")..."
        DisableMobCollision(donSwan)
        EnableBuso()
        EquipSelectedWeapon()
        TweenTo(donSwan.HumanoidRootPart.CFrame * CFrame.new(0, 15, 0))
    else
        -- Nếu vừa đánh Don Swan xong và hắn biến mất (đã bị tiêu diệt) -> Ghi nhận ĐÃ HẠ THÀNH CÔNG!
        if getgenv()._attackingSwan then
            getgenv()._attackingSwan = false
            getgenv()["Z9_DonSwanKilled_" .. tostring(plr and plr.UserId or 0)] = true
            CurrentFarmStatus = tag .. " ✅ Đã tiêu diệt thành công Boss Don Swan! Chuyển sang nhiệm vụ Arowe..."
            task.wait(1)
            return true
        end

        local distToSwan = (hrp.Position - swanRoomCF.Position).Magnitude
        if distToSwan > 100 then
            getgenv()._swanBossNotFoundTime = nil
            CurrentFarmStatus = tag .. " Đang bay tới phòng Don Swan kiểm tra Boss..."
            TweenTo(swanRoomCF * CFrame.new(0, 10, 0))
            return true
        else
            local now = tick()
            if not getgenv()._swanBossNotFoundTime then
                getgenv()._swanBossNotFoundTime = now
            end
            local waitElapsed = now - getgenv()._swanBossNotFoundTime
            CurrentFarmStatus = tag .. " Đang quét kiểm tra Boss Don Swan tại phòng (" .. string.format("%.1f", math.max(0, 2.5 - waitElapsed) .. "s)...")
            TweenTo(swanRoomCF * CFrame.new(0, 10, 0))

            if waitElapsed >= 2.5 then
                getgenv()._swanBossNotFoundTime = nil
                if IsAutoHopEnabled() and tick() >= (HopSystem.NextAllowedHop or 0) then
                    CurrentFarmStatus = tag .. " Boss Don Swan chưa xuất hiện -> Đang Hop Server kênh [don_swan]..."
                    HopBoss("Don Swan", "Don Swan chưa hồi sinh")
                    return true
                else
                    CurrentFarmStatus = tag .. " Boss Don Swan chưa xuất hiện -> Tạm thời tiếp tục farm cấp/võ..."
                    return false
                end
            end
            return true
        end
    end
    return true
end

local function DoAutoThirdSeaStep(hrp, hum)
    if not (World2 or CurrentSeaNum == 2) then return false end
    local lv = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0
    if lv < 1500 then return false end

    -- Hủy quest thường cũ nếu đang nhận dở để tập trung làm nhiệm vụ qua Sea 3 (trừ nhiệm vụ Bartilo)
    if HasActiveQuest() and not IsBartiloActiveQuest() then
        pcall(function()
            ReplicatedStorage.Remotes.CommF_:InvokeServer("AbandonQuest")
        end)
        ResetQuestSeen()
    end

    -- 1. Kiểm tra xem đã hoàn thành toàn bộ nhiệm vụ qua Sea 3 chưa -> Nếu đã xong thì dịch chuyển qua Sea 3 (TravelZou)
    local zCheck = nil
    local zZou = nil
    pcall(function()
        zCheck = ReplicatedStorage.Remotes.CommF_:InvokeServer("ZQuestProgress", "Check")
        zZou = ReplicatedStorage.Remotes.CommF_:InvokeServer("ZQuestProgress", "Zou")
    end)

    if zCheck == 1 then
        CurrentFarmStatus = "[Nhiệm vụ Sea 3 - Bước 5/5] Đã hoàn thành! Đang dịch chuyển qua Sea 3 (TravelZou)..."
        if getgenv().StopTween then getgenv().StopTween() end
        pcall(function()
            ReplicatedStorage.Remotes.CommF_:InvokeServer("TravelZou")
        end)
        task.wait(1.5)
        local mrCap = (workspace:FindFirstChild("NPCs") and (workspace.NPCs:FindFirstChild("Mr. Captain") or workspace.NPCs:FindFirstChild("Mr Captain")))
        if mrCap and mrCap:FindFirstChild("HumanoidRootPart") then
            if (hrp.Position - mrCap.HumanoidRootPart.Position).Magnitude > 10 then
                TweenTo(mrCap.HumanoidRootPart.CFrame * CFrame.new(0, 0, 3))
            else
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("TravelZou")
                end)
            end
        end
        return true
    end

    -- BƯỚC 1: Hoàn thành Nhiệm Vụ Bartilo (Swan Pirates / Jeremy / Colosseum)
    if not IsBartiloDone() then
        return DoAutoBartiloQuestStep(hrp, hum, "[Nhiệm vụ Sea 3 - Bước 1/5]")
    end

    -- BƯỚC 2: Mở khóa phòng Don Swan với Trevor (Cần trái ác quỷ >= $1,000,000)
    if not IsSwanRoomUnlocked() then
        return DoTrevorUnlockStep(hrp, hum, "[Nhiệm vụ Sea 3 - Bước 2/5]")
    end

    -- BƯỚC 3: Tiêu diệt Boss Don Swan [Lv. 1000] trong Dinh Thự
    if not IsDonSwanKilled() or zCheck == nil or zCheck == false then
        return DoKillDonSwanStep(hrp, hum, "[Nhiệm vụ Sea 3 - Bước 3/5]")
    end

    -- BƯỚC 4: zCheck == 0 -> Gặp King Red Head tại Đấu Trường La Mã & Đánh bại rip_indra
    if zCheck == 0 then
        local indraMob = nil
        if workspace:FindFirstChild("Enemies") then
            indraMob = workspace.Enemies:FindFirstChild("rip_indra")
        end

        -- Nếu Boss rip_indra đang xuất hiện trên sàn đấu -> Tiêu diệt Boss
        local inHum = indraMob and indraMob:FindFirstChildOfClass("Humanoid")
        if indraMob and indraMob:FindFirstChild("HumanoidRootPart") and inHum and inHum.Health > 0 then
            getgenv()._currentTargetMobName = "rip_indra"
            CurrentFarmStatus = "[Nhiệm vụ Sea 3 - Bước 4/5] Đang đánh Boss rip_indra (HP: " .. math.floor(inHum.Health) .. ")..."
            DisableMobCollision(indraMob)
            EnableBuso()
            EquipSelectedWeapon()
            TweenTo(indraMob.HumanoidRootPart.CFrame * CFrame.new(0, 15, 0))
            return true
        end

        -- Nếu rip_indra không có trong workspace -> Kiểm tra xem nhiệm vụ đã hoàn thành chưa
        local reCheck = nil
        pcall(function()
            reCheck = ReplicatedStorage.Remotes.CommF_:InvokeServer("ZQuestProgress", "Check")
        end)
        if reCheck == 1 then
            CurrentFarmStatus = "[Nhiệm vụ Sea 3 - Bước 5/5] Đã hoàn thành thử thách rip_indra! Đang dịch chuyển qua Sea 3 (TravelZou)..."
            if getgenv().StopTween then getgenv().StopTween() end
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("TravelZou")
            end)
            task.wait(2)
            return true
        end

        -- Chưa hoàn thành và chưa có rip_indra -> Tới King Red Head tại Colosseum để kích hoạt
        local redHeadCF = CFrame.new(-1926.78772, 12.1678171, 1739.80884)
        local dist = (hrp.Position - redHeadCF.Position).Magnitude
        if dist > 8 then
            CurrentFarmStatus = "[Nhiệm vụ Sea 3 - Bước 4/5] Đang tới King Red Head (Colosseum) nhận thử thách rip_indra..."
            TweenTo(redHeadCF)
            return true
        else
            if getgenv().StopTween then getgenv().StopTween() end
            hrp.CFrame = redHeadCF
            CurrentFarmStatus = "[Nhiệm vụ Sea 3 - Bước 4/5] Đang nói chuyện với King Red Head mở cổng Indra..."
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("ZQuestProgress", "Begin")
            end)
            task.wait(1.5)
            return true
        end
    end

    return false
end

local function DoRaceV2Step(hrp, hum)
    local curBeli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
    if curBeli < 500000 then
        CurrentFarmStatus = "[Auto Race V2] Cần đủ $500,000 Beli để nâng cấp Race V2 (Hiện có $" .. FormatNumber(curBeli) .. ")..."
        return false
    end

    if not IsBartiloDone() then
        return DoAutoBartiloQuestStep(hrp, hum, "[Auto Race V2]")
    end

    local aProg = nil
    pcall(function()
        aProg = ReplicatedStorage.Remotes.CommF_:InvokeServer("Alchemist", "1")
    end)

    if aProg == -2 then
        CachedRaceVer = "V2"
        return true
    elseif aProg == 0 then
        CurrentFarmStatus = "[Auto Race V2] Đang gặp Alchemist tại Green Zone để nhận nhiệm vụ tìm hoa..."
        local alchemistCF = CFrame.new(-2777.6, 72.96, -3571.42)
        if (hrp.Position - alchemistCF.Position).Magnitude > 8 then
            TweenTo(alchemistCF)
        else
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("Alchemist", "2")
            end)
            task.wait(0.5)
        end
        return true
    elseif aProg == 1 then
        local hasFlower1 = (plr.Character and (plr.Character:FindFirstChild("Flower 1") or plr.Character:FindFirstChild("Flower1"))) or (plr.Backpack and (plr.Backpack:FindFirstChild("Flower 1") or plr.Backpack:FindFirstChild("Flower1")))
        local hasFlower2 = (plr.Character and (plr.Character:FindFirstChild("Flower 2") or plr.Character:FindFirstChild("Flower2"))) or (plr.Backpack and (plr.Backpack:FindFirstChild("Flower 2") or plr.Backpack:FindFirstChild("Flower2")))
        local hasFlower3 = (plr.Character and (plr.Character:FindFirstChild("Flower 3") or plr.Character:FindFirstChild("Flower3"))) or (plr.Backpack and (plr.Backpack:FindFirstChild("Flower 3") or plr.Backpack:FindFirstChild("Flower3")))

        if not hasFlower1 then
            local f1 = workspace:FindFirstChild("Flower1") or workspace:FindFirstChild("Flower 1")
            if f1 then
                CurrentFarmStatus = "[Auto Race V2] Đang bay đi nhặt Hoa Đỏ (Flower 1)..."
                local f1CF = f1:IsA("BasePart") and f1.CFrame or (f1:FindFirstChildWhichIsA("BasePart") and f1:FindFirstChildWhichIsA("BasePart").CFrame) or CFrame.new(-2777, 73, -3571)
                TweenTo(f1CF)
                pcall(function()
                    local targetPart = f1:IsA("BasePart") and f1 or f1:FindFirstChildWhichIsA("BasePart")
                    if targetPart then
                        firetouchinterest(hrp, targetPart, 0)
                        firetouchinterest(hrp, targetPart, 1)
                    end
                end)
                return true
            end
        end

        if not hasFlower2 then
            local f2 = workspace:FindFirstChild("Flower2") or workspace:FindFirstChild("Flower 2")
            if f2 then
                CurrentFarmStatus = "[Auto Race V2] Đang bay đi nhặt Hoa Xanh (Flower 2)..."
                local f2CF = f2:IsA("BasePart") and f2.CFrame or (f2:FindFirstChildWhichIsA("BasePart") and f2:FindFirstChildWhichIsA("BasePart").CFrame) or CFrame.new(-1835, 10, 1679)
                TweenTo(f2CF)
                pcall(function()
                    local targetPart = f2:IsA("BasePart") and f2 or f2:FindFirstChildWhichIsA("BasePart")
                    if targetPart then
                        firetouchinterest(hrp, targetPart, 0)
                        firetouchinterest(hrp, targetPart, 1)
                    end
                end)
                return true
            end
        end

        if not hasFlower3 then
            local mob = GetNearestAliveMob("Swan Pirate")
            if mob and mob:FindFirstChild("HumanoidRootPart") and mob:FindFirstChildOfClass("Humanoid") and mob.Humanoid.Health > 0 then
                getgenv()._currentTargetMobName = "Swan Pirate"
                CurrentFarmStatus = "[Auto Race V2] Đang hạ Swan Pirate để kiếm Hoa Vàng (Flower 3)..."
                DisableMobCollision(mob)
                EnableBuso()
                EquipSelectedWeapon()
                TweenTo(mob.HumanoidRootPart.CFrame * CFrame.new(0, 15, 0))
            else
                CurrentFarmStatus = "[Auto Race V2] Đang bay tới bãi quái Swan Pirate kiếm Hoa 3..."
                TweenTo(CFrame.new(980, 121, 1287))
            end
            return true
        end

        if hasFlower1 and hasFlower2 and hasFlower3 then
            CurrentFarmStatus = "[Auto Race V2] Đã nhặt đủ 3 hoa! Đang tới gặp Alchemist nộp $500,000 Beli để lên Tộc V2..."
            local alchemistCF = CFrame.new(-2777.6, 72.96, -3571.42)
            if (hrp.Position - alchemistCF.Position).Magnitude > 8 then
                TweenTo(alchemistCF)
            else
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("Alchemist", "3")
                end)
                task.wait(1)
                LastRaceCheck = 0
            end
            return true
        end

        CurrentFarmStatus = "[Auto Race V2] Đang đợi Hoa 1/2 xuất hiện (Ban ngày/Ban đêm)..."
        task.wait(1)
        return true
    elseif aProg == 2 then
        CurrentFarmStatus = "[Auto Race V2] Đã đủ 3 hoa! Đang tới gặp Alchemist nộp $500,000 Beli để lên Tộc V2..."
        local alchemistCF = CFrame.new(-2777.6, 72.96, -3571.42)
        if (hrp.Position - alchemistCF.Position).Magnitude > 8 then
            TweenTo(alchemistCF)
        else
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("Alchemist", "3")
            end)
            task.wait(1)
            LastRaceCheck = 0
        end
        return true
    end

    return false
end

local function DoRaceV3Step(hrp, hum)
    local wProg = nil
    pcall(function()
        wProg = ReplicatedStorage.Remotes.CommF_:InvokeServer("Wenlocktoad", "1")
    end)

    if wProg == -2 then
        CachedRaceVer = "V3"
        return true
    end

    if wProg == 0 then
        getgenv()._humanKilledBosses = {}
        CurrentFarmStatus = "[Auto Race V3] Đang nhận nhiệm vụ Race V3 từ Arowe (Wenlocktoad)..."
        pcall(function()
            ReplicatedStorage.Remotes.CommF_:InvokeServer("Wenlocktoad", "2")
        end)
        task.wait(0.5)
        return true
    end

    if wProg == 2 then
        getgenv()._humanKilledBosses = {}
        local curBeli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
        if curBeli < 2000000 then
            CurrentFarmStatus = "[Auto Race V3] Đã hoàn thành nhiệm vụ! Thiếu tiền trả Arowe (Cần $2,000,000 Beli, hiện có $" .. FormatNumber(curBeli) .. ")..."
            return false
        end
        CurrentFarmStatus = "[Auto Race V3] Đã hoàn thành nhiệm vụ! Đang trả $2,000,000 Beli cho Arowe để mở khóa Tộc V3..."
        pcall(function()
            ReplicatedStorage.Remotes.CommF_:InvokeServer("Wenlocktoad", "3")
        end)
        task.wait(1)
        LastRaceCheck = 0
        return true
    end

    if wProg == 1 then
        local pRace = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Race") and tostring(plr.Data.Race.Value)) or "Human"
        local isSupp, normRace = IsSupportedRace(pRace)
        if not isSupp then
            CurrentFarmStatus = "[Auto Race V3] Tộc " .. pRace .. " không được hỗ trợ nâng cấp"
            return false
        end

        if normRace == "Human" then
            getgenv()._humanKilledBosses = getgenv()._humanKilledBosses or {}

            -- 1. Kiểm tra nếu Boss đang đánh ở tick trước đã bị tiêu diệt
            if getgenv()._fightingHumanBossCanon then
                local fCanon = getgenv()._fightingHumanBossCanon
                local fMob = getgenv()._fightingHumanBossMob
                local fHum = fMob and fMob:FindFirstChildOfClass("Humanoid")
                local isDead = false
                if not fMob or not fMob.Parent or not fHum or fHum.Health <= 0 then
                    isDead = true
                end
                if isDead then
                    getgenv()._humanKilledBosses[fCanon] = true
                    getgenv()._fightingHumanBossCanon = nil
                    getgenv()._fightingHumanBossMob = nil
                    getgenv()._humanPatrolIndex = 1
                    getgenv()._humanPatrolArrivedTime = nil
                    getgenv()._humanCafeWaitUntil = nil
                end
            end

            local allHumanBosses = {
                { Canonical = "Diamond", Name = "Diamond", CF = CFrame.new(-1576, 198, 13), Display = "Diamond (Đồi Hoa)" },
                { Canonical = "Jeremy", Name = "Jeremy", CF = CFrame.new(2006, 448, 853), Display = "Jeremy (Đấu Trường)" },
                { Canonical = "Fajita", Name = "Fajita", Aliases = {"Orbitus", "Fajita"}, CF = CFrame.new(-2172, 103, -4015), Display = "Fajita (Green Zone)" },
            }

            -- LỌC MỤC TIÊU: Nếu đã hạ Boss trước đó thì KHÔNG check lại, chỉ check các Boss còn lại!
            local remainingBosses = {}
            for _, bInfo in ipairs(allHumanBosses) do
                if not getgenv()._humanKilledBosses[bInfo.Canonical] then
                    table.insert(remainingBosses, bInfo)
                end
            end

            -- Chuỗi hiển thị tiến độ các Boss đã hạ
            local killedNames = {}
            for k, v in pairs(getgenv()._humanKilledBosses) do
                if v then table.insert(killedNames, k) end
            end
            local killedStatusStr = #killedNames > 0 and (" [Đã hạ: " .. table.concat(killedNames, ", ") .. "]") or ""

            -- Nếu đã hạ đủ cả 3 Boss -> Lập tức đến gặp Arowe để trả Beli mở khóa Tộc V3
            if #remainingBosses == 0 then
                CurrentFarmStatus = "[Auto Race V3 - Human]" .. killedStatusStr .. " Đã hạ đủ 3 Boss! Đang gặp Arowe để mở khóa Tộc V3..."
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("Wenlocktoad", "3")
                end)
                task.wait(0.5)
                return true
            end

            -- Bước 1: Quét nhanh xem có boss nào trong remainingBosses ĐANG có sẵn trong workspace.Enemies không
            local bossToKill = nil
            local matchedBossInfo = nil
            for _, bInfo in ipairs(remainingBosses) do
                local checkNames = bInfo.Aliases or { bInfo.Name }
                for _, n in ipairs(checkNames) do
                    local bMob = GetNearestAliveMob(n)
                    if bMob and bMob:FindFirstChild("HumanoidRootPart") and bMob:FindFirstChildOfClass("Humanoid") and bMob.Humanoid.Health > 0 then
                        bossToKill = bMob
                        matchedBossInfo = bInfo
                        break
                    end
                end
                if bossToKill then break end
            end

            if bossToKill and matchedBossInfo then
                getgenv()._humanPatrolIndex = nil
                getgenv()._humanPatrolArrivedTime = nil
                getgenv()._humanCafeWaitUntil = nil
                getgenv()._currentTargetMobName = bossToKill.Name
                getgenv()._fightingHumanBossCanon = matchedBossInfo.Canonical
                getgenv()._fightingHumanBossMob = bossToKill

                local bkHum = bossToKill:FindFirstChildOfClass("Humanoid")
                -- Lắng nghe sự kiện Died để ghi nhận ngay khi Boss bị hạ gục
                pcall(function()
                    if bkHum and not bossToKill:FindFirstChild("_DeathHooked") then
                        local tag = Instance.new("BoolValue")
                        tag.Name = "_DeathHooked"
                        tag.Parent = bossToKill
                        bkHum.Died:Connect(function()
                            getgenv()._humanKilledBosses[matchedBossInfo.Canonical] = true
                        end)
                    end
                end)

                if not bkHum or bkHum.Health <= 0 then
                    getgenv()._humanKilledBosses[matchedBossInfo.Canonical] = true
                end

                CurrentFarmStatus = "[Auto Race V3 - Human]" .. killedStatusStr .. " Đang tiêu diệt Boss " .. tostring(bossToKill.Name) .. " (HP: " .. math.floor(bkHum and bkHum.Health or 100) .. ")..."
                DisableMobCollision(bossToKill)
                EnableBuso()
                EquipSelectedWeapon()
                TweenTo(bossToKill.HumanoidRootPart.CFrame * CFrame.new(0, 15, 0))
                return true
            end

            -- Bước 2: Do StreamingEnabled của Roblox, chỉ bay tuần tra qua các bãi Boss CÒN LẠI (bỏ qua bãi đã hạ)
            local now = tick()
            local cafeRoofCF = CFrame.new(-382, 132, 298)

            -- Nếu đang trong thời gian nghỉ ngơi tại Cafe
            if getgenv()._humanCafeWaitUntil and now < getgenv()._humanCafeWaitUntil then
                local remain = math.max(0, math.ceil(getgenv()._humanCafeWaitUntil - now))
                CurrentFarmStatus = "[Auto Race V3 - Human]" .. killedStatusStr .. " Đang đứng trên Nóc Cafe chờ Boss (" .. tostring(remain) .. "s)..."
                local dist = (hrp.Position - cafeRoofCF.Position).Magnitude
                if dist > 8 then
                    TweenTo(cafeRoofCF)
                else
                    if getgenv().StopTween then getgenv().StopTween() end
                    hrp.CFrame = cafeRoofCF
                    pcall(function() hrp.Velocity = Vector3.new(0, 0, 0) end)
                end
                return true
            end

            -- Tiến hành tuần tra lần lượt các Boss CÒN LẠI
            getgenv()._humanPatrolIndex = getgenv()._humanPatrolIndex or 1
            if getgenv()._humanPatrolIndex > #remainingBosses then
                -- Đã tuần tra xong các boss còn lại mà chưa con nào ra -> Về Nóc Cafe nghỉ 35 giây
                getgenv()._humanPatrolIndex = 1
                getgenv()._humanPatrolArrivedTime = nil
                getgenv()._humanCafeWaitUntil = now + 35
                TweenTo(cafeRoofCF)
                CurrentFarmStatus = "[Auto Race V3 - Human]" .. killedStatusStr .. " Các Boss còn lại chưa hồi sinh, đang về Nóc Cafe nghỉ 35s..."
                return true
            end

            local curTargetSpot = remainingBosses[getgenv()._humanPatrolIndex]
            local patrolCF = curTargetSpot.CF * CFrame.new(0, 25, 0)
            local distToSpot = (hrp.Position - patrolCF.Position).Magnitude

            if distToSpot > 120 then
                CurrentFarmStatus = "[Auto Race V3 - Human]" .. killedStatusStr .. " Đang bay kiểm tra Boss " .. curTargetSpot.Display .. " (" .. tostring(getgenv()._humanPatrolIndex) .. "/" .. tostring(#remainingBosses) .. ")..."
                TweenTo(patrolCF)
            else
                -- Đã đến bãi spawn của boss còn lại, đợi 2.5s để Roblox Streaming tải các model quái trong chunk
                if not getgenv()._humanPatrolArrivedTime then
                    getgenv()._humanPatrolArrivedTime = now
                end
                local waited = now - getgenv()._humanPatrolArrivedTime
                CurrentFarmStatus = "[Auto Race V3 - Human]" .. killedStatusStr .. " Đang quét kiểm tra Boss " .. curTargetSpot.Display .. " (" .. string.format("%.1f", math.max(0, 2.5 - waited)) .. "s)..."

                -- Quét lại lần nữa xem boss đã xuất hiện trong workspace.Enemies chưa
                local checkNames = curTargetSpot.Aliases or { curTargetSpot.Name }
                for _, n in ipairs(checkNames) do
                    local bMob = GetNearestAliveMob(n)
                    if bMob and bMob:FindFirstChild("HumanoidRootPart") and bMob:FindFirstChildOfClass("Humanoid") and bMob.Humanoid.Health > 0 then
                        getgenv()._humanPatrolIndex = nil
                        getgenv()._humanPatrolArrivedTime = nil
                        getgenv()._humanCafeWaitUntil = nil
                        return true
                    end
                end

                if waited >= 2.5 then
                    -- Boss này chưa spawn -> Chuyển sang boss còn lại tiếp theo
                    getgenv()._humanPatrolIndex = getgenv()._humanPatrolIndex + 1
                    getgenv()._humanPatrolArrivedTime = nil
                end
            end
            return true

        elseif normRace == "Rabbit" then
            CurrentFarmStatus = "[Auto Race V3 - Rabbit] Đang tự động nhặt rương tốc độ cao mở khóa Tộc V3..."
            local nearestChest = nil
            local minDist = math.huge
            if CollectionService then
                for _, chest in ipairs(CollectionService:GetTagged("_ChestTagged")) do
                    if chest:IsA("BasePart") and not chest:GetAttribute("IsDisabled") and not chest:FindFirstChild("Ignored") then
                        local d = (hrp.Position - chest.Position).Magnitude
                        if d < minDist then
                            minDist = d
                            nearestChest = chest
                        end
                    end
                end
            end

            if nearestChest then
                TweenTo(nearestChest.CFrame)
                if (hrp.Position - nearestChest.Position).Magnitude < 10 then
                    pcall(function()
                        firetouchinterest(hrp, nearestChest, 0)
                        firetouchinterest(hrp, nearestChest, 1)
                    end)
                    task.wait(0.1)
                end
            else
                task.wait(0.4)
            end
            return true

        elseif normRace == "Shark" then
            local seaBeast = nil
            local sbFolder = workspace:FindFirstChild("SeaBeasts")
            if sbFolder then
                for _, sb in ipairs(sbFolder:GetChildren()) do
                    local sbH = sb:FindFirstChildOfClass("Humanoid")
                    if sb:FindFirstChild("HumanoidRootPart") and sbH and sbH.Health > 0 then
                        seaBeast = sb
                        break
                    end
                end
            end
            if not seaBeast then
                for _, obj in ipairs(workspace.Enemies:GetChildren()) do
                    local objH = obj:FindFirstChildOfClass("Humanoid")
                    if (obj.Name:find("SeaBeast") or obj.Name:find("Sea Beast")) and obj:FindFirstChild("HumanoidRootPart") and objH and objH.Health > 0 then
                        seaBeast = obj
                        break
                    end
                end
            end

            local sHum = seaBeast and seaBeast:FindFirstChildOfClass("Humanoid")
            if seaBeast and seaBeast:FindFirstChild("HumanoidRootPart") and sHum and sHum.Health > 0 then
                CurrentFarmStatus = "[Auto Race V3 - Shark] Đang tiêu diệt Sea Beast mở khóa Tộc V3 (HP: " .. math.floor(sHum.Health) .. ")..."
                getgenv()._currentTargetMobName = seaBeast.Name
                DisableMobCollision(seaBeast)
                EnableBuso()
                EquipSelectedWeapon()
                TweenTo(seaBeast.HumanoidRootPart.CFrame * CFrame.new(0, 35, 0))
            else
                CurrentFarmStatus = "[Auto Race V3 - Shark] Đang di chuyển ra biển tìm/triệu hồi Sea Beast..."
                local seaZoneCF = CFrame.new(753.0, 25.0, 6994.5)
                TweenTo(seaZoneCF)
            end
            return true

        elseif normRace == "Cyborg" then
            local heldFruit = nil
            for _, it in ipairs(plr.Backpack:GetChildren()) do
                if it:IsA("Tool") and (it.ToolTip == "Blox Fruit" or it.Name:find("Fruit")) then
                    heldFruit = it
                    break
                end
            end
            if not heldFruit and plr.Character then
                for _, it in ipairs(plr.Character:GetChildren()) do
                    if it:IsA("Tool") and (it.ToolTip == "Blox Fruit" or it.Name:find("Fruit")) then
                        heldFruit = it
                        break
                    end
                end
            end

            if not heldFruit then
                local inv = nil
                pcall(function() inv = ReplicatedStorage.Remotes.CommF_:InvokeServer("getInventory") end)
                if inv and type(inv) == "table" then
                    for _, it in ipairs(inv) do
                        if type(it) == "table" and (it.Type == "Blox Fruit" or tostring(it.Name):find("Fruit")) then
                            pcall(function()
                                ReplicatedStorage.Remotes.CommF_:InvokeServer("LoadFruit", it.Name)
                            end)
                            break
                        end
                    end
                end
                CurrentFarmStatus = "[Auto Race V3 - Cyborg] Đang chuẩn bị trái Ác Quỷ nộp cho Arowe..."
                task.wait(0.5)
            else
                if plr.Backpack:FindFirstChild(heldFruit.Name) then
                    hum:EquipTool(heldFruit)
                end
                CurrentFarmStatus = "[Auto Race V3 - Cyborg] Đang nộp trái " .. tostring(heldFruit.Name) .. " cho Arowe..."
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("Wenlocktoad", "3")
                end)
                task.wait(0.5)
            end
            return true

        elseif normRace == "Ghoul" then
            -- Nhiệm vụ Ghoul V3: Tiêu diệt 5 Player
            local targetPlr = nil
            for _, otherPlr in ipairs(game.Players:GetPlayers()) do
                if otherPlr ~= plr and otherPlr.Character and otherPlr.Character:FindFirstChild("HumanoidRootPart") and otherPlr.Character:FindFirstChildOfClass("Humanoid") and otherPlr.Character.Humanoid.Health > 0 then
                    targetPlr = otherPlr
                    break
                end
            end
            if targetPlr and targetPlr.Character and targetPlr.Character:FindFirstChild("HumanoidRootPart") then
                CurrentFarmStatus = "[Auto Race V3 - Ghoul] Đang tiêu diệt Player (" .. targetPlr.DisplayName .. ") mở khóa V3 (Cần hạ 5 Player)..."
                local tHrp = targetPlr.Character.HumanoidRootPart
                EnableBuso()
                EquipSelectedWeapon()
                TweenTo(tHrp.CFrame * CFrame.new(0, 10, 0))
            else
                CurrentFarmStatus = "[Auto Race V3 - Ghoul] Cần tiêu diệt 5 Player để mở khóa V3 (Hãy nhờ bạn bè/acc phụ đứng yên)..."
                local cafeRoofCF = CFrame.new(-382, 132, 298)
                TweenTo(cafeRoofCF)
            end
            return true

        elseif normRace == "Angel" then
            -- Nhiệm vụ Angel V3: Tiêu diệt 1 Player tộc Angel
            local targetAngel = nil
            for _, otherPlr in ipairs(game.Players:GetPlayers()) do
                if otherPlr ~= plr and otherPlr.Character and otherPlr.Character:FindFirstChild("HumanoidRootPart") and otherPlr.Character:FindFirstChildOfClass("Humanoid") and otherPlr.Character.Humanoid.Health > 0 then
                    local oRace = (otherPlr:FindFirstChild("Data") and otherPlr.Data:FindFirstChild("Race") and tostring(otherPlr.Data.Race.Value)) or ""
                    if oRace:lower():find("angel") or oRace:lower():find("skypia") then
                        targetAngel = otherPlr
                        break
                    end
                end
            end
            if targetAngel and targetAngel.Character and targetAngel.Character:FindFirstChild("HumanoidRootPart") then
                CurrentFarmStatus = "[Auto Race V3 - Angel] Đang tiêu diệt Player tộc Angel (" .. targetAngel.DisplayName .. ") mở khóa V3..."
                local tHrp = targetAngel.Character.HumanoidRootPart
                EnableBuso()
                EquipSelectedWeapon()
                TweenTo(tHrp.CFrame * CFrame.new(0, 10, 0))
            else
                CurrentFarmStatus = "[Auto Race V3 - Angel] Cần tiêu diệt 1 Player tộc Angel để mở khóa V3 (Hãy nhờ 1 bạn tộc Angel đứng yên)..."
                local cafeRoofCF = CFrame.new(-382, 132, 298)
                TweenTo(cafeRoofCF)
            end
            return true
        end
    end

    return false
end

-- =========================================================================
-- HỆ THỐNG XỬ LÝ MỤC TIÊU SỰ KIỆN HALLOWEEN (HELLFIRE EVENT STEPPER)
-- =========================================================================
function HW.GetBoss()
    local bossNames = {
        "the great pumpkin king",
        "great pumpkin king",
        "pumpkin king",
        "hell rider",
        "unbound werewolf",
        "werewolf",
        "gray pumpkin",
        "living pumpkin",
        "hellfire gas",
    }
    local enemies = workspace:FindFirstChild("Enemies")
    if enemies then
        for _, obj in ipairs(enemies:GetChildren()) do
            local eHum = obj:FindFirstChildOfClass("Humanoid")
            if eHum and eHum.Health > 0 and obj:FindFirstChild("HumanoidRootPart") then
                local nl = obj.Name:lower()
                local disp = obj:GetAttribute("DisplayName")
                local dl = disp and tostring(disp):lower() or ""
                for _, bn in ipairs(bossNames) do
                    if nl == bn or nl:find(bn) or dl == bn or dl:find(bn) then
                        return obj
                    end
                end
            end
        end
    end
    -- Quét thêm trong HellfireBossRealm nếu Boss spawn trực tiếp bên trong realm (Chỉ quét GetChildren để không lag)
    local map = workspace:FindFirstChild("Map")
    local realm = map and map:FindFirstChild("HellfireBossRealm")
    if realm then
        for _, obj in ipairs(realm:GetChildren()) do
            if obj:IsA("Model") then
                local eHum = obj:FindFirstChildOfClass("Humanoid")
                if eHum and eHum.Health > 0 and obj:FindFirstChild("HumanoidRootPart") then
                    local nl = obj.Name:lower()
                    for _, bn in ipairs(bossNames) do
                        if nl == bn or nl:find(bn) then
                            return obj
                        end
                    end
                end
            end
        end
    end
    return nil
end

function HW.GetPivotCF(o)
    if not o or not o.Parent then return nil end
    if o:IsA("Model") then
        local p = o.PrimaryPart or o:FindFirstChildWhichIsA("BasePart")
        return p and p.CFrame or o:GetPivot()
    elseif o:IsA("BasePart") then
        return o.CFrame
    end
    return nil
end

function HW.IsValidEventDoor(d)
    if not d or not d.Parent then return false end
    if d.Name == "HalloweenDoor" then return true end
    if d:FindFirstChild("SceneWindow") then return true end
    if CollectionService and CollectionService:HasTag(d, "HalloweenDoor") then return true end
    return false
end

function HW.IsBossDoor(door)
    if not door or not door.Parent then return false end
    return door:FindFirstChild("SceneWindow") ~= nil
end

HW.CachedDoors = HW.CachedDoors or {}
HW.LastDoorsScan = HW.LastDoorsScan or 0

function HW.CollectDoors()
    local now = tick()
    if #HW.CachedDoors > 0 and (now - (HW.LastDoorsScan or 0)) < 3.0 then
        return HW.CachedDoors
    end
    HW.LastDoorsScan = now

    local list = {}
    local seen = {}
    local map = workspace:FindFirstChild("Map")
    if not map then return list end

    local function addDoor(d)
        if not d or not (d:IsA("Model") or d:IsA("BasePart")) then return end
        if d:IsA("BasePart") and d.Parent and d.Parent:IsA("Model") and d.Parent.Name == "HalloweenDoor" then
            d = d.Parent
        end
        if not seen[d] and HW.IsValidEventDoor(d) then
            local cf = HW.GetPivotCF(d)
            local posKey = cf and HW.GetDoorPosKey(cf)
            if posKey and not seen[posKey] then
                seen[posKey] = true
                seen[d] = true
                table.insert(list, d)
            elseif not posKey then
                seen[d] = true
                table.insert(list, d)
            end
        end
    end

    -- 1. Quét HalloweenDecor trong tất cả các đảo (chuẩn Blox Fruits)
    for _, island in ipairs(map:GetChildren()) do
        local decor = island:FindFirstChild("HalloweenDecor") or island:FindFirstChild("Halloween")
        if decor then
            for _, d in ipairs(decor:GetDescendants()) do
                if d.Name == "HalloweenDoor" or HW.IsValidEventDoor(d) then
                    addDoor(d)
                end
            end
        end
    end

    -- 2. Quét sâu các root chuyên biệt cho từng Sea (Quét GetChildren & GetDescendants để không bỏ sót cửa nào):
    -- Sea 3: Turtle -> IslandModel -> HalloweenHotel
    -- Sea 2: Dressrosa -> Dressrosa
    -- Sea 1: Middle Town / Town
    local extraRoots = {
        { "Turtle", "IslandModel", "HalloweenHotel" },
        { "Dressrosa", "Dressrosa" },
        { "Town" },
        { "MiddleTown" },
    }
    for _, p in ipairs(extraRoots) do
        local node = map
        for _, n in ipairs(p) do
            node = node and node:FindFirstChild(n)
        end
        if node then
            for _, d in ipairs(node:GetChildren()) do
                if d.Name == "HalloweenDoor" and (d:IsA("Model") or d:IsA("BasePart")) then
                    addDoor(d)
                end
            end
            for _, d in ipairs(node:GetDescendants()) do
                if d.Name == "HalloweenDoor" and (d:IsA("Model") or d:IsA("BasePart")) then
                    addDoor(d)
                end
            end
        end
    end

    -- 3. Quét CollectionService tag nếu có
    if CollectionService then
        for _, d in ipairs(CollectionService:GetTagged("HalloweenDoor")) do
            addDoor(d)
        end
    end

    HW.CachedDoors = list
    return list
end

function HW.GetBossDoor(hrp)
    local doors = HW.CollectDoors()
    local now = tick()
    for _, d in ipairs(doors) do
        local sw = d:FindFirstChild("SceneWindow")
        local cf = sw and (HW.GetPivotCF(sw) or HW.GetPivotCF(d))
        if sw and cf and not HW.IsDoorOnCooldown(d, cf) then
            if not (HW.IsNearSea1HiddenBoss and HW.IsNearSea1HiddenBoss(cf.Position)) then
                return d, sw
            end
        end
    end
    return nil, nil
end

function HW.GetNearestDoor(hrp)
    if not hrp then return nil end
    local best, bestDist = nil, math.huge
    local doors = HW.CollectDoors()
    for _, d in ipairs(doors) do
        -- Cửa có SceneWindow là Cổng Boss, không phải cửa Trick-or-Treat thường
        if not d:FindFirstChild("SceneWindow") then
            local cf = HW.GetPivotCF(d)
            if cf and not HW.IsDoorOnCooldown(d, cf) then
                if not (HW.IsNearSea1HiddenBoss and HW.IsNearSea1HiddenBoss(cf.Position)) then
                    local isSea1 = (World1 or CurrentSeaNum == 1)
                    local pLv = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0
                    local isAllowed = true
                    if isSea1 and pLv < 700 then
                        if (cf.Position - Vector3.new(-655, 35, 1436)).Magnitude > 1800 then
                            isAllowed = false
                        end
                    end
                    if isAllowed then
                        local dist = (cf.Position - hrp.Position).Magnitude
                        if dist < bestDist then
                            best = d
                            bestDist = dist
                        end
                    end
                end
            end
        end
    end
    return best
end

function HW.PickStandCF(door, cf, hrp)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { plr.Character, door }
    params.IgnoreWater = true
    local raw = { cf.LookVector, -cf.LookVector, cf.RightVector, -cf.RightVector }
    local bestDir, bestScore = cf.LookVector, 9999
    for _, v in ipairs(raw) do
        local d = Vector3.new(v.X, 0, v.Z)
        if d.Magnitude > 0.1 then
            d = d.Unit
            local pos = cf.Position + d * 3.5
            local score = 0
            pcall(function()
                local up = workspace:Raycast(pos + Vector3.new(0, 2, 0), Vector3.new(0, 60, 0), params)
                if up and up.Instance.Transparency < 1 then score = score + 2 end
                local toDoor = (cf.Position - pos) * 0.8
                if workspace:Raycast(pos, toDoor, params) then score = score + 3 end
            end)
            score = score + (hrp.Position - pos).Magnitude * 0.001
            if score < bestScore then
                bestScore = score
                bestDir = d
            end
        end
    end
    local standPos = cf.Position + bestDir * 3.5
    return CFrame.lookAt(standPos, Vector3.new(cf.Position.X, standPos.Y, cf.Position.Z))
end

function HW.GetDialogue()
    local pg = plr:FindFirstChild("PlayerGui")
    local dg = pg and pg:FindFirstChild("DialogueGui")
    if not dg or (dg:IsA("ScreenGui") and not dg.Enabled) then
        return nil, nil
    end
    local fallbackSc = nil
    for _, ol in ipairs(dg:GetDescendants()) do
        if ol.Name == "optionsList" then
            local sc = ol:FindFirstChild("scroller")
            if sc then
                fallbackSc = fallbackSc or sc
                for _, o in ipairs(sc:GetChildren()) do
                    if o:IsA("GuiObject") and o.Visible and o.AbsoluteSize.X > 0 and o.AbsoluteSize.Y > 0 then
                        local low = string.lower(o.Name)
                        if low:find("option1", 1, true) and not low:find("option1%d") then
                            return sc, o
                        end
                    end
                end
                for _, o in ipairs(sc:GetChildren()) do
                    if o:IsA("GuiObject") and o.Visible and o.AbsoluteSize.X > 0 and o.AbsoluteSize.Y > 0 then
                        if o:IsA("GuiButton") or o:FindFirstChildWhichIsA("GuiButton", true) then
                            return sc, o
                        end
                    end
                end
            end
        end
    end
    return fallbackSc, nil
end

function HW.GetDialogueFrame()
    local pg = plr:FindFirstChild("PlayerGui")
    local dg = pg and pg:FindFirstChild("DialogueGui")
    if not dg or (dg:IsA("ScreenGui") and not dg.Enabled) then
        return nil
    end
    for _, c in ipairs(dg:GetChildren()) do
        if string.sub(c.Name, 1, 6) == "table:" and (not c:IsA("GuiObject") or c.Visible) then
            return c
        end
    end
    return nil
end

function HW.ClickGui(o)
    if not o then return end
    local btn = o:IsA("GuiButton") and o or o:FindFirstChildWhichIsA("GuiButton", true)
    if btn and firesignal then
        pcall(function() firesignal(btn.MouseButton1Click) end)
        pcall(function() firesignal(btn.Activated) end)
    end
    pcall(function()
        local pos = o.AbsolutePosition + o.AbsoluteSize / 2
        local sg = o:FindFirstAncestorWhichIsA("ScreenGui")
        if sg and not sg.IgnoreGuiInset then
            pos = pos + game:GetService("GuiService"):GetGuiInset()
        end
        local vim = game:GetService("VirtualInputManager")
        if vim then
            vim:SendMouseButtonEvent(pos.X, pos.Y, 0, true, game, 1)
            vim:SendMouseButtonEvent(pos.X, pos.Y, 0, false, game, 1)
        end
    end)
    pcall(function()
        local vu = game:GetService("VirtualUser")
        if vu then
            vu:CaptureController()
            local pos = o.AbsolutePosition + o.AbsoluteSize / 2
            vu:ClickButton1(pos)
        end
    end)
end

function HW.ClickScreen()
    pcall(function()
        local vp = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(800, 600)
        local x = vp.X * 0.15
        local y = vp.Y * 0.15
        local vim = game:GetService("VirtualInputManager")
        if vim then
            vim:SendMouseButtonEvent(x, y, 0, true, game, 1)
            vim:SendMouseButtonEvent(x, y, 0, false, game, 1)
        end
    end)
    pcall(function()
        local vu = game:GetService("VirtualUser")
        if vu then
            vu:CaptureController()
            vu:Button1Down(Vector2.new(0, 0))
        end
    end)
end

-- Tự động theo dõi ProximityPrompt đang hiển thị trên màn hình
HW.ActivePrompt = nil
pcall(function()
    local pps = game:GetService("ProximityPromptService")
    if pps and not HW._promptHooked then
        HW._promptHooked = true
        pps.PromptShown:Connect(function(pr)
            if pr and pr.Enabled then
                HW.ActivePrompt = pr
            end
        end)
        pps.PromptHidden:Connect(function(pr)
            if HW.ActivePrompt == pr then
                HW.ActivePrompt = nil
            end
        end)
    end
end)

-- Tương tác cửa sự kiện hoàn toàn an toàn & tương thích mọi nền tảng (PC / Mobile / Giả lập Android)
function HW.InteractDoor(door, targetPart)
    local target = targetPart or door
    if not target then return end

    -- Tự động quét và xóa sạch thông báo "Try again soon." nếu có
    HW.ClearTryAgainNotification()

    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")

    -- 1. Tìm ProximityPrompt: Ưu tiên Prompt đang hiện trên màn hình, sau đó tìm trong target, door, door.Parent hoặc bán kính 25 xung quanh
    local prompt = nil
    if HW.ActivePrompt and HW.ActivePrompt.Parent and HW.ActivePrompt.Enabled then
        prompt = HW.ActivePrompt
    end
    if not prompt then
        prompt = target:FindFirstChildWhichIsA("ProximityPrompt", true)
            or (door and door:FindFirstChildWhichIsA("ProximityPrompt", true))
            or (door and door.Parent and door.Parent:FindFirstChildWhichIsA("ProximityPrompt", true))
            or (target and target.Parent and target.Parent:FindFirstChildWhichIsA("ProximityPrompt", true))
    end

    if prompt then
        pcall(function()
            prompt.RequiresLineOfSight = false
            prompt.MaxActivationDistance = 9999
            prompt.HoldDuration = 0
            prompt.Enabled = true
        end)

        -- Kích hoạt qua fireproximityprompt trên các executor hỗ trợ
        if fireproximityprompt and prompt.Enabled then
            pcall(fireproximityprompt, prompt)
            pcall(fireproximityprompt, prompt, 0)
            pcall(fireproximityprompt, prompt, math.huge)
            pcall(fireproximityprompt, prompt, 1, true)
        end

        -- Nhấn và giữ phím E qua VirtualInputManager (cho PC/Giả lập)
        task.spawn(function()
            pcall(function()
                local vim = game:GetService("VirtualInputManager")
                if vim then
                    vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)
                    task.wait(0.06)
                    vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)
                end
            end)
        end)

        -- Dự phòng InputHoldBegin / InputHoldEnd (cho Mobile/Android)
        task.spawn(function()
            pcall(function()
                prompt:InputHoldBegin()
                task.wait(0.05)
                prompt:InputHoldEnd()
            end)
        end)
    end

    -- 2. Kích hoạt ClickDetector nếu có
    local cd = target:FindFirstChildWhichIsA("ClickDetector", true)
        or (door and door:FindFirstChildWhichIsA("ClickDetector", true))
        or (door and door.Parent and door.Parent:FindFirstChildWhichIsA("ClickDetector", true))
    if cd and fireclickdetector then
        pcall(fireclickdetector, cd)
    end

    -- 3. Kích hoạt chạm Touch vật lý vào tất cả BasePart của cửa / cổng
    pcall(function()
        if hrp and firetouchinterest then
            local function touchPart(p)
                if p and p:IsA("BasePart") then
                    pcall(firetouchinterest, hrp, p, 0)
                    pcall(firetouchinterest, hrp, p, 1)
                end
            end
            local b1 = target:IsA("BasePart") and target or target:FindFirstChildWhichIsA("BasePart")
            if b1 then touchPart(b1) end
            local b2 = door:IsA("BasePart") and door or door:FindFirstChildWhichIsA("BasePart")
            if b2 then touchPart(b2) end
            if door and door:IsA("Model") then
                for _, sub in ipairs(door:GetChildren()) do
                    if sub:IsA("BasePart") then touchPart(sub) end
                end
            end
        end
    end)
end

function HW.IsSea1HiddenBoss(mob)
    if not mob then return false end
    local nl = string.lower(mob.Name)
    if AllBossMobs and AllBossMobs[nl] then
        return true
    end
    local sea1Bosses = {
        ["saber expert"] = true,
        ["mob leader"] = true,
        ["ice admiral"] = true,
        ["the gorilla king"] = true,
        ["gorilla king"] = true,
        ["bobby"] = true,
        ["the saw"] = true,
        ["saw"] = true,
        ["yeti"] = true,
        ["vice admiral"] = true,
        ["warden"] = true,
        ["chief warden"] = true,
        ["swan"] = true,
        ["magma admiral"] = true,
        ["fishman lord"] = true,
        ["wysper"] = true,
        ["thunder god"] = true,
        ["cyborg"] = true,
        ["greybeard"] = true,
    }
    if sea1Bosses[nl] then return true end
    for bName, _ in pairs(sea1Bosses) do
        if nl:find(bName, 1, true) then return true end
    end
    if mob:GetAttribute("Boss") == true or mob:GetAttribute("BossIndicatorAwakened") ~= nil then
        return true
    end
    return false
end

function HW.IsEventMob(mob)
    if not mob then return false end
    if HW.IsSea1HiddenBoss(mob) then return false end
    local name = tostring(mob.Name or "")
    local nl = string.lower(name)
    local raw = nl:gsub("[^%w]", "")

    -- TUYỆT ĐỐI LOẠI TRỪ các quái thường của game Blox Fruits:
    -- 1. Snowman ở Sea 1 (Frozen Village Lv. 100) - KHÔNG PHẢI quái Halloween!
    if raw == "snowman" or nl == "snowman" then
        return false
    end
    -- 2. Zombie / Vampire ở Sea 2 (Graveyard) - KHÔNG PHẢI quái Halloween!
    if raw == "zombie" or raw == "vampire" or nl == "zombie" or nl == "vampire" then
        return false
    end
    -- 3. Mummy / Skeleton ở Sea 3 (Haunted Castle) - KHÔNG PHẢI quái Halloween!
    if raw == "mummy" or raw == "livingzombie" or raw == "rebornskeleton" or raw == "demonicsoul" or raw == "posessedmummy" then
        return false
    end

    -- Khớp CHÍNH XÁC quái sự kiện Halloween thật:
    -- 1. Pumpkin Snowman (Người tuyết bí ngô của Halloween - bắt buộc phải có chữ pumpkin)
    if raw:find("pumpkinsnowman") or (nl:find("pumpkin") and nl:find("snowman")) then
        return true
    end
    -- 2. Jack O' Lantern
    if raw:find("jackolantern") or (nl:find("jack") and nl:find("lantern")) then
        return true
    end
    -- 3. Werewolf (Người sói từ cửa Trick-or-Treat)
    if nl:find("werewolf") then
        return true
    end
    -- 4. Hellfire Gas / Hell Rider / Pumpkin King / Gray Pumpkin
    if nl:find("hellfire") or nl:find("hellrider") or nl:find("hell rider") or nl:find("pumpkin king") or nl:find("gray pumpkin") or nl:find("grey pumpkin") then
        return true
    end
    -- 5. Quái trong không gian Hellfire Realm hoặc có parent là PumpkinHunt / GhostChase
    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    if hrp and HW.IsInHellfireRealm(hrp) then
        return true
    end
    if mob.Parent and (mob.Parent.Name == "PumpkinHunt" or mob.Parent.Name == "GhostChase") then
        return true
    end
    return false
end

function HW.FindJackMob(range)
    local char = plr.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local enemies = workspace:FindFirstChild("Enemies")
    if not hrp or not enemies then return nil end

    local maxDist = range or 800
    local bestMob, bestDist = nil, maxDist
    for _, m in ipairs(enemies:GetChildren()) do
        local mHum = m:FindFirstChildOfClass("Humanoid")
        if mHum and mHum.Health > 0 and m:FindFirstChild("HumanoidRootPart") then
            if not HW.IsSea1HiddenBoss(m) and HW.IsEventMob(m) then
                local d = (m.HumanoidRootPart.Position - hrp.Position).Magnitude
                if d <= bestDist then
                    bestDist = d
                    bestMob = m
                end
            end
        end
    end
    return bestMob
end

function HW.IsNearSea1HiddenBoss(pos)
    if not pos then return false end
    if not (World1 or CurrentSeaNum == 1) then return false end
    -- 1. Phòng Shanks / Boss Saber Expert (Jungle)
    if (pos - Vector3.new(-1458.895, 29.887, -50.633)).Magnitude <= 85 then return true end
    -- 2. Hang Mob Leader (Pirate Village)
    if (pos - Vector3.new(-2967.6, -4.9, 5328.7)).Magnitude <= 75 then return true end
    -- 3. Hang Băng Ice Admiral (Frozen Village)
    if (pos - Vector3.new(1348, -38, -1324)).Magnitude <= 75 then return true end
    -- 4. Đảo Gorilla King (Jungle)
    if (pos - Vector3.new(-1128, 40, -525)).Magnitude <= 60 then return true end
    -- 5. Đền thờ Wysper (SkyArea2)
    if (pos - Vector3.new(-7925, 5550, -640)).Magnitude <= 80 then return true end
    return false
end

function HW.FindNearbyMob(range)
    local char = plr.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local enemies = workspace:FindFirstChild("Enemies")
    if not hrp or not enemies then return nil end

    local boss = enemies:FindFirstChild("Hellfire Gas")
    local bHum = boss and boss:FindFirstChildOfClass("Humanoid")
    if boss and bHum and bHum.Health > 0 and boss:FindFirstChild("HumanoidRootPart") then
        return boss
    end

    local maxDist = range or 250
    local bestMob, bestDist = nil, maxDist
    for _, m in ipairs(enemies:GetChildren()) do
        local mHum = m:FindFirstChildOfClass("Humanoid")
        if mHum and mHum.Health > 0 and m:FindFirstChild("HumanoidRootPart") then
            -- TUYỆT ĐỐI NÉ KHÔNG ĐÁNH BOSS ẨN / BOSS THẾ GIỚI KHI ĐANG LÀM SỰ KIỆN Ở SEA 1
            if not HW.IsSea1HiddenBoss(m) and HW.IsEventMob(m) then
                local d = (m.HumanoidRootPart.Position - hrp.Position).Magnitude
                if d <= bestDist then
                    bestDist = d
                    bestMob = m
                end
            end
        end
    end
    return bestMob
end

-- Tự động đánh và gây sát thương trực tiếp lên quái / Boss sự kiện Halloween (Đảm bảo 100% gây damage, tối ưu mượt mà không chiếm chuột)
function HW.AttackTarget(targetMob, hrp, hum)
    if not targetMob or not targetMob.Parent then return end
    local mHum = targetMob:FindFirstChildOfClass("Humanoid")
    local mHrp = targetMob:FindFirstChild("HumanoidRootPart") or targetMob:FindFirstChild("Head")
    if not mHum or mHum.Health <= 0 or not mHrp then return end

    local char = plr.Character
    if not char then return end
    local tool = char:FindFirstChildOfClass("Tool")

    -- YÊU CẦU NGƯỜI DÙNG: "farm sự kiên vẫn là melee" -> Sự kiện Halloween luôn dùng Võ Thuật (Melee)
    if not tool or tool.ToolTip ~= "Melee" then
        for _, t in ipairs(plr.Backpack:GetChildren()) do
            if t:IsA("Tool") and t.ToolTip == "Melee" then
                if tool and hum then hum:UnequipTools() end
                if hum then hum:EquipTool(t) end
                tool = char:FindFirstChildOfClass("Tool")
                break
            end
        end
    end

    pcall(function()
        if type(EnableBuso) == "function" then EnableBuso() end
        if tool then tool:Activate() end

        local hitPart = targetMob:FindFirstChild("Head") or mHrp
        if hitPart then
            -- 1. Bắn LeftClickRemote nếu vũ khí hỗ trợ
            if tool and tool:FindFirstChild("LeftClickRemote") and hrp then
                local dir = (hitPart.Position - hrp.Position).Unit
                pcall(function() tool.LeftClickRemote:FireServer(dir, 1) end)
            end

            -- 2. Đăng ký đòn đánh trực tiếp (RegisterAttack + RegisterHit) nếu chưa có Fast Attack
            if RegisterAttack and RegisterHit and (tick() - (HW.LastHitTick or 0) >= 0.12) then
                HW.LastHitTick = tick()
                pcall(function()
                    RegisterAttack:FireServer(0)
                    RegisterHit:FireServer(hitPart, { { targetMob, hitPart } })
                end)
            end
        end
    end)
end

function HW.HandleGhostChase(hrp)
    local root = workspace:FindFirstChild("GhostChase")
    if not root then return false end
    local items = {}
    for _, c in ipairs(root:GetChildren()) do
        if c:IsA("Model") or c:IsA("BasePart") then
            table.insert(items, c)
        end
    end
    if #items == 0 then return false end

    local best, bestD = nil, math.huge
    for _, it in ipairs(items) do
        local cf = HW.GetPivotCF(it)
        if cf then
            local d = (cf.Position - hrp.Position).Magnitude
            if d < bestD then
                bestD = d
                best = it
            end
        end
    end

    if best then
        local targetCF = HW.GetPivotCF(best)
        if targetCF then
            CurrentFarmStatus = "[Sự Kiện Halloween] 👻 Đang bay đuổi bắt Ghost Chase..."
            HW.CurrentTask = "Đang đuổi bắt Ghost Chase"
            if type(TweenTo) == "function" then
                TweenTo(targetCF)
            end
            return true
        end
    end
    return false
end

HW.LastRealmCheck = 0
HW.IsInsideRealmCached = false

function HW.IsInHellfireRealm(hrp)
    if not hrp then return false end
    local now = tick()
    if (now - (HW.LastRealmCheck or 0)) < 1.5 then
        return HW.IsInsideRealmCached == true
    end
    HW.LastRealmCheck = now

    local map = workspace:FindFirstChild("Map")
    local realm = map and map:FindFirstChild("HellfireBossRealm")
    if not realm then
        HW.IsInsideRealmCached = false
        return false
    end
    local ok, inside = pcall(function()
        local cf = realm:GetPivot()
        local size = realm:GetExtentsSize()
        local rel = cf:PointToObjectSpace(hrp.Position)
        return math.abs(rel.X) <= size.X / 2 + 50
            and math.abs(rel.Y) <= size.Y / 2 + 120
            and math.abs(rel.Z) <= size.Z / 2 + 50
    end)
    HW.IsInsideRealmCached = (ok and inside == true)
    return HW.IsInsideRealmCached
end

