function HW.GetPumpkin()
    -- YÊU CẦU: Trong 10 phút đầu sự kiện (Harvest Moon): CHỈ farm cửa và đánh boss, TUYỆT ĐỐI KHÔNG farm bí ngô!
    if HW.IsHarvestMoonTime() then
        return nil, nil
    end

    -- GIỚI HẠN BÍ NGÔ: Nếu đã đạt đủ số Kẹo Ngô giới hạn (mặc định 500 kẹo để quay Spooky Gacha) -> Dừng bí ngô để quay lại farm cấp!
    if HW.GetEventCandies() >= HW.GetMaxCandy() then
        return nil, nil
    end

    -- Khóa mục tiêu quả bí ngô hiện tại (Sticky Target Lock) để chống hiện tượng đổi mục tiêu liên tục gây giật lùi / rung lắc (jitter)
    if HW.CurrentPumpkinTarget and HW.CurrentPumpkinTarget.Parent and HW.CurrentPumpkinPart and HW.CurrentPumpkinPart.Parent then
        if not HW.IgnoredPumpkins[HW.CurrentPumpkinTarget] and not HW.CurrentPumpkinTarget:FindFirstChild("Z9_BrokenPumpkin") then
            if (tick() - (HW.CurrentPumpkinStartTick or 0)) < 8.0 then
                return HW.CurrentPumpkinTarget, HW.CurrentPumpkinPart
            end
        end
    end

    local bestObj, bestPart, bestDist = nil, nil, math.huge -- Quét toàn bản đồ tìm bất kỳ quả Bí Ngô nào
    local char = plr.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local myPos = hrp and hrp.Position or Vector3.new(0, 0, 0)

    -- Dọn dẹp cache các quả bí ngô đã hết thời gian hồi sinh (hơn 60 giây) hoặc instance đã bị xóa (ngăn rò rỉ RAM)
    local curT = tick()
    for k, v in pairs(HW.IgnoredPumpkins) do
        if (typeof and typeof(k) == "Instance" and not k.Parent) or (type(k) == "userdata" and not k.Parent) then
            HW.IgnoredPumpkins[k] = nil
        elseif type(v) == "number" and (curT - v) > 60 then
            HW.IgnoredPumpkins[k] = nil
        end
    end

    local function isValidPumpkin(obj)
        if not obj or not obj.Parent then return false end
        if HW.IgnoredPumpkins[obj] then return false end
        if obj:FindFirstChild("Z9_BrokenPumpkin") then return false end
        -- Nếu nằm trong PumpkinHunt thì luôn là đối tượng sự kiện hợp lệ
        if (obj.Parent and obj.Parent.Name == "PumpkinHunt") or (obj.Parent and obj.Parent.Parent and obj.Parent.Parent.Name == "PumpkinHunt") then
            return true
        end
        local nl = string.lower(obj.Name)
        if nl:find("seed") or nl:find("pie") or nl:find("sword") or nl:find("fruit") or nl:find("door") then
            return false
        end
        -- Bắt toàn bộ bí ngô sự kiện trên mọi Sea (Pumpkin, Jack O' Lantern, Spooky Pumpkin, Snowman...)
        return (nl:find("pumpkin") or nl:find("jack o") or nl:find("jackolantern") or nl:find("spookypumpkin"))
    end

    local function checkCandidate(desc)
        if not desc or not desc.Parent then return end
        if isValidPumpkin(desc) then
            local part = (desc:IsA("BasePart") and desc) or desc:FindFirstChild("Hitbox") or desc:FindFirstChild("Handle") or desc:FindFirstChildWhichIsA("BasePart")
            if part and part.Position.Y > -200 then
                local d = (part.Position - myPos).Magnitude
                if d < bestDist then
                    bestDist = d
                    bestObj = desc
                    bestPart = part
                end
            end
        end
    end

    -- 1. Quét CollectionService tags chuyên biệt của sự kiện (Hỗ trợ toàn bộ Sea 1, 2, 3)
    if CollectionService then
        for _, tag in ipairs({"Pumpkin", "JackOLantern", "HalloweenEvent", "SpookyPumpkin", "PumpkinHunt", "EventPumpkin"}) do
            for _, obj in ipairs(CollectionService:GetTagged(tag)) do
                checkCandidate(obj)
            end
        end
    end
    if bestObj then
        HW.CurrentPumpkinTarget = bestObj
        HW.CurrentPumpkinPart = bestPart
        HW.CurrentPumpkinStartTick = tick()
        HW.IsSmashingCurrentPumpkin = false
        return bestObj, bestPart
    end

    -- 2. Quét sâu toàn bộ thư mục PumpkinHunt (bao gồm cả các thư mục con theo từng đảo)
    local pHunt = workspace:FindFirstChild("PumpkinHunt")
    if pHunt then
        for _, c in ipairs(pHunt:GetChildren()) do
            checkCandidate(c)
            if c:IsA("Folder") or c:IsA("Model") then
                for _, cc in ipairs(c:GetChildren()) do
                    checkCandidate(cc)
                end
            end
        end
    end
    if bestObj then
        HW.CurrentPumpkinTarget = bestObj
        HW.CurrentPumpkinPart = bestPart
        HW.CurrentPumpkinStartTick = tick()
        HW.IsSmashingCurrentPumpkin = false
        return bestObj, bestPart
    end

    -- 3. Quét các folder sự kiện chuyên biệt khác trong workspace
    for _, fName in ipairs({"Pumpkins", "JackOLanterns", "PumpkinPatch", "Halloween", "HalloweenEvent", "Event"}) do
        local f = workspace:FindFirstChild(fName)
        if f then
            for _, desc in ipairs(f:GetChildren()) do
                checkCandidate(desc)
                if desc:IsA("Folder") or desc:IsA("Model") then
                    for _, sub in ipairs(desc:GetChildren()) do
                        checkCandidate(sub)
                    end
                end
            end
        end
    end
    if bestObj then
        HW.CurrentPumpkinTarget = bestObj
        HW.CurrentPumpkinPart = bestPart
        HW.CurrentPumpkinStartTick = tick()
        HW.IsSmashingCurrentPumpkin = false
        return bestObj, bestPart
    end

    if bestObj and bestPart then
        HW.CurrentPumpkinTarget = bestObj
        HW.CurrentPumpkinPart = bestPart
        HW.CurrentPumpkinStartTick = tick()
        HW.IsSmashingCurrentPumpkin = false
    else
        HW.CurrentPumpkinTarget = nil
        HW.CurrentPumpkinPart = nil
        HW.IsSmashingCurrentPumpkin = false
    end

    return bestObj, bestPart
end

function HW.DoStep(hrp, hum)
    if not IsAutoHalloweenEnabled() then
        HW.IsDoingEvent = false
        return false
    end

    -- YÊU CẦU: Acc cấp 1 đi farm tầm cấp 50 rồi mới farm sự kiện
    local pLv = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0
    local minLevel = (HW.GetMinLevel and HW.GetMinLevel()) or 50
    if pLv < minLevel then
        HW.IsDoingEvent = false
        HW.CurrentTask = string.format("Cần đạt Cấp %d+ (Đang ưu tiên farm cấp: %d/%d)", minLevel, pLv, minLevel)
        return false
    end

    HW.EnsureBusyHook()
    HW.ClearTryAgainNotification()

    -- KIỂM TRA MỤC TIÊU SỰ KIỆN: Nếu sự kiện không hoạt động hoặc đã đủ 500 kẹo
    if not HW.IsEventActive(hrp) then
        HW.IsDoingEvent = false
        local curCandies = HW.GetEventCandies() or 0
        local maxCandies = HW.GetMaxCandy()
        if curCandies >= maxCandies then
            HW.CurrentTask = "Đã đủ " .. tostring(maxCandies) .. " Kẹo Ngô (Đang farm cấp/võ/tộc)"
            return false
        end
        HW.CurrentTask = "Đang farm cấp (Chờ sự kiện / Bí Ngô)"
        return false
    end

    HW.IsDoingEvent = true
    -- "farm sự kiên vẫn là melee" -> Sự kiện Halloween luôn ưu tiên dùng Võ Thuật (Melee)
    local char = plr.Character
    local curT = char and char:FindFirstChildOfClass("Tool")
    if not curT or curT.ToolTip ~= "Melee" then
        for _, t in ipairs(plr.Backpack:GetChildren()) do
            if t:IsA("Tool") and t.ToolTip == "Melee" then
                if curT and hum then hum:UnequipTools() end
                if hum then hum:EquipTool(t) end
                break
            end
        end
    end

    -- Hủy nhiệm vụ farm cấp nếu còn dính để tập trung 100% làm sự kiện (trừ Bartilo)
    if type(HasActiveQuest) == "function" and HasActiveQuest() and not (type(IsBartiloActiveQuest) == "function" and IsBartiloActiveQuest()) then
        pcall(function() ReplicatedStorage.Remotes.CommF_:InvokeServer("AbandonQuest") end)
        if type(ResetQuestSeen) == "function" then ResetQuestSeen() end
    end

    -- A. QUAY GACHA TỪ XA NẾU ĐỦ KẸO
    pcall(HW.ExecuteRemoteSpookyGacha)

    -- B. TRONG HELLFIRE BOSS REALM (KHÔNG GIAN ĐÁNH BOSS)
    if HW.IsInHellfireRealm(hrp) then
        local realmMob = HW.FindNearbyMob(500)
        local rHum = realmMob and realmMob:FindFirstChildOfClass("Humanoid")
        if realmMob and rHum and rHum.Health > 0 and realmMob:FindFirstChild("HumanoidRootPart") then
            CurrentFarmStatus = "[Sự Kiện Halloween] Đang đánh quái trong Hellfire Boss Realm: " .. tostring(realmMob.Name) .. "..."
            HW.CurrentTask = "Đánh quái trong Hellfire Realm"
            getgenv()._currentTargetMobName = realmMob.Name
            if type(DisableMobCollision) == "function" then DisableMobCollision(realmMob) end
            if type(EnableBuso) == "function" then EnableBuso() end
            if type(EquipSelectedWeapon) == "function" then EquipSelectedWeapon() end
            if type(TweenTo) == "function" then TweenTo(realmMob.HumanoidRootPart.CFrame * CFrame.new(0, 14, 0)) end
            HW.AttackTarget(realmMob, hrp, hum)
        else
            CurrentFarmStatus = "[Sự Kiện Halloween] Đang ở trong Hellfire Boss Realm..."
            HW.CurrentTask = "Trong Hellfire Realm"
            if type(TweenTo) == "function" then TweenTo(hrp.CFrame) end
        end
        return true
    end

    -- C. TIÊU DIỆT BOSS SỰ KIỆN (PUMPKIN KING, HELL RIDER, WEREWOLF, GRAY PUMPKIN, HELLFIRE GAS)
    local hwBoss = HW.GetBoss()
    local hwHum = hwBoss and hwBoss:FindFirstChildOfClass("Humanoid")
    if hwBoss and hwHum and hwHum.Health > 0 and hwBoss:FindFirstChild("HumanoidRootPart") then
        CurrentFarmStatus = "[Sự Kiện Halloween] 🔥 Đang tiêu diệt Boss sự kiện: " .. tostring(hwBoss.Name) .. " (HP: " .. math.floor(hwHum.Health) .. ")..."
        HW.CurrentTask = "Đang đánh Boss: " .. tostring(hwBoss.Name)
        getgenv()._currentTargetMobName = hwBoss.Name
        if type(DisableMobCollision) == "function" then DisableMobCollision(hwBoss) end
        if type(EnableBuso) == "function" then EnableBuso() end
        if type(EquipSelectedWeapon) == "function" then EquipSelectedWeapon() end
        if type(BringMobs) == "function" then BringMobs(hwBoss) end
        if type(TweenTo) == "function" then TweenTo(hwBoss.HumanoidRootPart.CFrame * CFrame.new(0, 14, 0)) end
        HW.AttackTarget(hwBoss, hrp, hum)
        return true
    end

    -- D. GHOST CHASE
    if HW.HandleGhostChase(hrp) then
        return true
    end

    -- E. TIÊU DIỆT QUÁI SỰ KIỆN GẦN (HELLFIRE GAS, JACK O' LANTERN, PUMPKIN SNOWMAN HOẶC QUÁI TỪ CỬA / BÍ NGÔ)
    -- TRONG 10 PHÚT HARVEST MOON: CHỈ ĐÁNH QUÁI SPAWN NGAY CẠNH CỬA (< 150 studs) HOẶC BOSS HELLFIRE GAS,
    -- TUYỆT ĐỐI KHÔNG BAY XA 800 STUDS ĐỂ DÀNH TRỌN 10 PHÚT GÕ CỬA!
    local isHM = HW.IsHarvestMoonTime()
    local nearMob = isHM and HW.FindNearbyMob(150) or (HW.FindJackMob(800) or HW.FindNearbyMob(300))
    local nHum = nearMob and nearMob:FindFirstChildOfClass("Humanoid")
    if nearMob and nHum and nHum.Health > 0 and nearMob:FindFirstChild("HumanoidRootPart") then
        CurrentFarmStatus = "[Sự Kiện Halloween] Đang tiêu diệt quái sự kiện: " .. tostring(nearMob.Name) .. "..."
        HW.CurrentTask = "Tiêu diệt " .. tostring(nearMob.Name)
        getgenv()._currentTargetMobName = nearMob.Name
        if type(DisableMobCollision) == "function" then DisableMobCollision(nearMob) end
        if type(EnableBuso) == "function" then EnableBuso() end
        if type(EquipSelectedWeapon) == "function" then EquipSelectedWeapon() end
        if type(BringMobs) == "function" then BringMobs(nearMob) end
        if type(TweenTo) == "function" then TweenTo(nearMob.HumanoidRootPart.CFrame * CFrame.new(0, 14, 0)) end
        HW.AttackTarget(nearMob, hrp, hum)
        return true
    end

    -- F. ĐỢI BOSS / QUÁI SPAWN TỪ CỬA VỪA GÕ (4.5 GIÂY)
    if HW.WaitingForDoorSpawnUntil and tick() < HW.WaitingForDoorSpawnUntil then
        if HW.GetBoss() ~= nil or HW.FindNearbyMob(150) ~= nil or HW.IsInHellfireRealm(hrp) then
            HW.WaitingForDoorSpawnUntil = nil
        else
            CurrentFarmStatus = "[Sự Kiện Halloween] ⏳ Đang đứng tại cửa đợi Boss / Quái xuất hiện..."
            HW.CurrentTask = "Đợi Boss / Quái xuất hiện"
            if HW.WaitingForDoorSpawnCF then
                if type(TweenTo) == "function" then TweenTo(HW.WaitingForDoorSpawnCF) end
            end
            return true
        end
    else
        HW.WaitingForDoorSpawnUntil = nil
    end

    -- G. GIAI ĐOẠN HARVEST MOON (10 PHÚT ĐẦU SỰ KIỆN): CHỈ FARM CỔNG BOSS & CỬA TRICK-OR-TREAT
    -- TUYỆT ĐỐI KHÔNG FARM BÍ NGÔ TRONG 10 PHÚT NÀY
    if HW.IsHarvestMoonTime() then
        -- G.1 CỔNG BOSS SCENEWINDOW
        local sceneDoor, sceneWin = HW.GetBossDoor(hrp)
        if sceneDoor and sceneWin then
            local swCF = HW.GetPivotCF(sceneWin) or HW.GetPivotCF(sceneDoor)
            if swCF then
                local standCF = HW.PickStandCF(sceneDoor, swCF, hrp)
                local dist = (hrp.Position - standCF.Position).Magnitude
                if HW.BossDoorTarget ~= sceneDoor then
                    HW.BossDoorTarget = sceneDoor
                    HW.BossDoorStartTick = tick()
                end

                if dist > 8 then
                    CurrentFarmStatus = "[Sự Kiện Halloween] 🔥 Phát hiện Cổng Boss SceneWindow -> Đang bay tới cổng vào..."
                    HW.CurrentTask = "Bay tới Cổng Boss SceneWindow"
                    if type(TweenTo) == "function" then TweenTo(standCF) end
                else
                    if getgenv().StopTween then getgenv().StopTween() end
                    if type(RefreshTeleportTag) == "function" then RefreshTeleportTag() end
                    hrp.CFrame = standCF
                    pcall(function()
                        if (hrp.Position - swCF.Position).Magnitude <= 12 then
                            -- Chạm trực tiếp vào trung tâm cổng portal
                            hrp.CFrame = swCF
                        end
                    end)

                    -- Kiểm tra Dialogue hội thoại nếu có
                    local sc, opt = HW.GetDialogue()
                    if opt then
                        CurrentFarmStatus = "[Sự Kiện Halloween] 🔥 Đang chọn vào Cổng Boss..."
                        HW.CurrentTask = "Chọn vào Cổng Boss"
                        HW.ClickGui(opt)
                    elseif HW.GetDialogueFrame() then
                        CurrentFarmStatus = "[Sự Kiện Halloween] 💬 Đang tương tác hội thoại Cổng Boss..."
                        HW.CurrentTask = "Hội thoại Cổng Boss"
                        if tick() - (HW.LastScreenClick or 0) >= 0.3 then
                            HW.LastScreenClick = tick()
                            HW.ClickScreen()
                        end
                    else
                        CurrentFarmStatus = "[Sự Kiện Halloween] 🔥 Đang tương tác nhấn E vào Cổng Boss..."
                        HW.CurrentTask = "Vào Cổng Boss Hellfire"
                        if tick() - (HW.LastKeyE or 0) >= 0.25 then
                            HW.LastKeyE = tick()
                            HW.InteractDoor(sceneDoor, sceneWin)
                        end
                    end

                    -- Kiểm tra nếu đã teleport vào realm hoặc đi xa > 50 studs
                    if (hrp.Position - swCF.Position).Magnitude > 50 or HW.IsInHellfireRealm(hrp) then
                        HW.DoorCooldowns[sceneDoor] = tick() + 180
                        HW.BossDoorTarget = nil
                        HW.BossDoorStartTick = nil
                        return true
                    end

                    -- Nếu đứng quá 6 giây không vào được -> Cổng đã hết / đóng, đặt cooldown 180s
                    if (HW.BossDoorStartTick and (tick() - HW.BossDoorStartTick >= 6.0)) then
                        HW.DoorCooldowns[sceneDoor] = tick() + 180
                        HW.BossDoorTarget = nil
                        HW.BossDoorStartTick = nil
                        HW.CurrentTask = "Cổng Boss đã hết"
                    end
                end
                return true
            end
        end

        -- G.2 CỬA TRICK-OR-TREAT (HALLOWEEN DOOR)
        -- 1. Kiểm tra target cửa hiện tại (Timeout 45s nếu đang bay xa hoặc cửa bị hủy -> dọn target)
        if HW.CurrentDoorTarget then
            local cf = HW.GetPivotCF(HW.CurrentDoorTarget)
            if not HW.CurrentDoorTarget.Parent or not cf or (tick() - (HW.CurrentDoorStartTick or 0) > 45.0) then
                if HW.CurrentDoorTarget and cf then
                    HW.SetDoorCooldown(HW.CurrentDoorTarget, cf, 120)
                end
                HW.CurrentDoorTarget = nil
                HW.CurrentDoorCF = nil
                HW.CurrentDoorArrivedTick = nil
                HW.DoorStandCF = nil
                HW.SawDoorDialogue = false
                HW.BusyAt = 0
            end
        end

        -- 2. Nếu chưa có target cửa -> Chọn cửa gần nhất chưa hồi chiêu
        if not HW.CurrentDoorTarget then
            local nextDoor = HW.GetNearestDoor(hrp)
            if nextDoor then
                local nextCF = HW.GetPivotCF(nextDoor)
                if nextCF then
                    HW.CurrentDoorTarget = nextDoor
                    HW.CurrentDoorCF = nextCF
                    HW.CurrentDoorStartTick = tick()
                    HW.CurrentDoorArrivedTick = nil
                    HW.DoorStandCF = HW.PickStandCF(nextDoor, nextCF, hrp)
                    HW.SawDoorDialogue = false
                    HW.BusyAt = 0
                end
            end
        end

        -- 3. Tiến hành tiếp cận và gõ cửa mục tiêu
        if HW.CurrentDoorTarget and HW.CurrentDoorCF then
            local door = HW.CurrentDoorTarget
            local doorCF = HW.CurrentDoorCF
            local standCF = HW.DoorStandCF or HW.PickStandCF(door, doorCF, hrp)
            local dist = (hrp.Position - standCF.Position).Magnitude

            -- Chỉ bay tới khi chưa từng chạm tới cửa
            if dist > 8 and not HW.CurrentDoorArrivedTick then
                CurrentFarmStatus = "[Sự Kiện Halloween] 🚪 Đang bay tới cửa HalloweenDoor (Trick-or-Treat)..."
                HW.CurrentTask = "Bay tới cửa HalloweenDoor"
                if type(TweenTo) == "function" then TweenTo(standCF) end
                return true
            end

            -- Đã tới cửa
            if getgenv().StopTween then getgenv().StopTween() end
            if type(RefreshTeleportTag) == "function" then RefreshTeleportTag() end
            hrp.CFrame = standCF
            if not HW.CurrentDoorArrivedTick then
                HW.CurrentDoorArrivedTick = tick()
                HW.BusyAt = 0
                HW.SawDoorDialogue = false
                HW.ClearTryAgainNotification()
            end

            -- A. Kiểm tra ngay nếu cửa đã báo "nobody is home" / "still busy" / "try again" (chỉ tính thông báo xuất hiện SAU KHI đã tới cửa này)
            if HW.HasNobodyHomeOrBusyNotification() or (HW.BusyAt and HW.BusyAt >= HW.CurrentDoorArrivedTick and (tick() - HW.BusyAt) <= 3.0) then
                CurrentFarmStatus = "[Sự Kiện Halloween] 🚪 Cửa không có người ở nhà -> Chuyển ngay sang cửa khác..."
                HW.SetDoorCooldown(door, doorCF, 120)
                HW.CurrentDoorTarget = nil
                HW.CurrentDoorCF = nil
                HW.CurrentDoorArrivedTick = nil
                HW.DoorStandCF = nil
                HW.SawDoorDialogue = false
                HW.BusyAt = 0
                HW.ClearTryAgainNotification()
                task.wait(0.08)
                return true
            end

            -- B. Kiểm tra đối thoại Trick-or-Treat
            local sc, opt = HW.GetDialogue()
            local dlgFrame = HW.GetDialogueFrame()
            if sc and opt then
                CurrentFarmStatus = "[Sự Kiện Halloween] 🍬 Đang chọn Trick-or-Treat nhận Kẹo Ngô..."
                HW.CurrentTask = "Chọn Trick-or-Treat"
                HW.SawDoorDialogue = true
                HW.CurrentDoorArrivedTick = tick()
                if tick() - (HW.LastOptClick or 0) >= 0.25 then
                    HW.LastOptClick = tick()
                    HW.ClickGui(opt)
                end
                return true
            elseif dlgFrame then
                CurrentFarmStatus = "[Sự Kiện Halloween] 💬 Đang tương tác trò chuyện với cửa..."
                HW.CurrentTask = "Nói chuyện với cửa"
                HW.SawDoorDialogue = true
                HW.CurrentDoorArrivedTick = tick()
                if tick() - (HW.LastScreenClick or 0) >= 0.3 then
                    HW.LastScreenClick = tick()
                    HW.ClickScreen()
                end
                return true
            elseif HW.SawDoorDialogue then
                -- Đã mở và đóng xong hội thoại -> Hoàn tất cửa này, đặt cooldown 120s và chờ quái/boss spawn!
                HW.SetDoorCooldown(door, doorCF, 120)
                HW.WaitingForDoorSpawnUntil = tick() + 4.5
                HW.WaitingForDoorSpawnCF = standCF
                HW.CurrentDoorTarget = nil
                HW.CurrentDoorCF = nil
                HW.CurrentDoorArrivedTick = nil
                HW.DoorStandCF = nil
                HW.SawDoorDialogue = false
                HW.BusyAt = 0
                return true
            else
                CurrentFarmStatus = "[Sự Kiện Halloween] 🚪 Đang nhấn E tương tác gõ cửa..."
                HW.CurrentTask = "Gõ cửa HalloweenDoor"
                if tick() - (HW.LastKeyE or 0) >= 0.35 then
                    HW.LastKeyE = tick()
                    HW.InteractDoor(door)
                end

                -- Kiểm tra lại ngay sau khi nhấn E xem game có hiện thông báo "nobody is home" không
                if HW.HasNobodyHomeOrBusyNotification() or (HW.BusyAt and HW.BusyAt >= HW.CurrentDoorArrivedTick and (tick() - HW.BusyAt) <= 3.0) then
                    HW.SetDoorCooldown(door, doorCF, 120)
                    HW.CurrentDoorTarget = nil
                    HW.CurrentDoorCF = nil
                    HW.CurrentDoorArrivedTick = nil
                    HW.DoorStandCF = nil
                    HW.SawDoorDialogue = false
                    HW.BusyAt = 0
                    HW.ClearTryAgainNotification()
                    task.wait(0.08)
                    return true
                end

                if (hrp.Position - standCF.Position).Magnitude > 50 or HW.IsInHellfireRealm(hrp) then
                    HW.SetDoorCooldown(door, doorCF, 120)
                    HW.CurrentDoorTarget = nil
                    HW.CurrentDoorCF = nil
                    HW.CurrentDoorArrivedTick = nil
                    HW.DoorStandCF = nil
                    HW.SawDoorDialogue = false
                    HW.BusyAt = 0
                    HW.WaitingForDoorSpawnUntil = tick() + 4.5
                    HW.WaitingForDoorSpawnCF = hrp.CFrame
                    return true
                end

                -- Nếu đã đứng gõ cửa mà sau 2.2s không mở đối thoại (hoặc cửa trống không ai ở nhà) -> Lập tức đặt cooldown 120s và sang cửa khác!
                if tick() - HW.CurrentDoorArrivedTick > 2.2 then
                    HW.SetDoorCooldown(door, doorCF, 120)
                    HW.CurrentDoorTarget = nil
                    HW.CurrentDoorCF = nil
                    HW.CurrentDoorArrivedTick = nil
                    HW.DoorStandCF = nil
                    HW.SawDoorDialogue = false
                    HW.BusyAt = 0
                    HW.ClearTryAgainNotification()
                    return true
                end
            end
            return true
        end

        -- TRONG 10 PHÚT SỰ KIỆN: ĐÃ GÕ HẾT CỬA / CỬA ĐANG HỒI CHIÊU -> ĐỢI CỬA HỒI CHIÊU, TUYỆT ĐỐI KHÔNG BỎ ĐI FARM CÁI KHÁC!
        local curCandies = HW.GetEventCandies() or 0
        local maxCandies = HW.GetMaxCandy()
        CurrentFarmStatus = "[Sự Kiện Halloween] ⏳ Đang đợi cửa Trick-or-Treat hồi chiêu (10 phút sự kiện)..."
        HW.CurrentTask = "Đợi cửa sự kiện hồi chiêu"
        local centerCF = (World1 or CurrentSeaNum == 1) and CFrame.new(-655, 35, 1436)
            or ((World2 or CurrentSeaNum == 2) and CFrame.new(-385, 80, 298)
            or CFrame.new(-13270, 340, -7625))
        if (hrp.Position - centerCF.Position).Magnitude > 150 then
            if type(TweenTo) == "function" then TweenTo(centerCF) end
        end
        return true
    end

    -- H. KHI HẾT 10 PHÚT SỰ KIỆN: NẾU CHƯA ĐỦ 500 KẸO NGÔ THÌ MỚI SĂN & ĐẬP BÍ NGÔ
    local curCandies = HW.GetEventCandies() or 0
    local maxCandies = HW.GetMaxCandy()
    if curCandies < maxCandies then
        -- ƯU TIÊN 1: NẾU CÓ QUÁI XUẤT HIỆN TỪ BÍ NGÔ (JACK O' LANTERN, PUMPKIN SNOWMAN HOẶC QUÁI GẦN) -> TIÊU DIỆT HẾT QUÁI TRƯỚC RỒI MỚI ĐẬP TIẾP!
        local jackMob = HW.FindJackMob(800) or HW.FindNearbyMob(300)
        local jHum = jackMob and jackMob:FindFirstChildOfClass("Humanoid")
        if jackMob and jHum and jHum.Health > 0 and jackMob:FindFirstChild("HumanoidRootPart") then
            CurrentFarmStatus = "[Sự Kiện Halloween] 🎃 Phát hiện quái từ Bí Ngô (" .. tostring(jackMob.Name) .. ") -> Đang tiêu diệt trước..."
            HW.CurrentTask = "Tiêu diệt quái Bí Ngô: " .. tostring(jackMob.Name)
            getgenv()._currentTargetMobName = jackMob.Name
            if type(DisableMobCollision) == "function" then DisableMobCollision(jackMob) end
            if type(EnableBuso) == "function" then EnableBuso() end
            if type(EquipSelectedWeapon) == "function" then EquipSelectedWeapon() end
            if type(BringMobs) == "function" then BringMobs(jackMob) end
            if type(TweenTo) == "function" then TweenTo(jackMob.HumanoidRootPart.CFrame * CFrame.new(0, 14, 0)) end
            HW.AttackTarget(jackMob, hrp, hum)
            return true
        end

        -- ƯU TIÊN 2: ĐANG CHỜ QUÁI XUẤT HIỆN TỪ BÍ NGÔ VỪA ĐẬP (2.0 GIÂY)
        if HW.WaitingForPumpkinSpawnUntil and tick() < HW.WaitingForPumpkinSpawnUntil then
            local spawnCheck = HW.FindJackMob(300) or HW.FindNearbyMob(150)
            if spawnCheck then
                HW.WaitingForPumpkinSpawnUntil = nil
                return true
            else
                CurrentFarmStatus = "[Sự Kiện Halloween] 🎃 Đã đập Bí Ngô -> Đang đợi quái xuất hiện..."
                HW.CurrentTask = "Đợi quái xuất hiện từ Bí Ngô"
                if HW.LastBrokenPumpkinPos then
                    if type(TweenTo) == "function" then TweenTo(CFrame.new(HW.LastBrokenPumpkinPos + Vector3.new(0, 8, 0))) end
                end
                return true
            end
        else
            HW.WaitingForPumpkinSpawnUntil = nil
        end

        local pumpkinObj, pumpkinPart = HW.GetPumpkin()
        if pumpkinObj and pumpkinPart then
            CurrentFarmStatus = "[Sự Kiện Halloween] 🎃 Hết giờ gõ cửa -> Đang đập Bí Ngô (" .. tostring(pumpkinObj.Name) .. ") gom Kẹo (" .. tostring(curCandies) .. "/" .. tostring(maxCandies) .. ")..."
            HW.CurrentTask = "Đập Bí Ngô: " .. tostring(pumpkinObj.Name)

            local pPos = pumpkinPart.Position
            local dist = (hrp.Position - pPos).Magnitude

            -- Cơ chế tiếp cận mượt mà chống giật lùi (anti-rubberband) và chống rung lắc camera (jitter)
            if not HW.IsSmashingCurrentPumpkin and dist > 8 then
                if type(TweenTo) == "function" then TweenTo(CFrame.new(pPos + Vector3.new(0, 4, 0))) end
            else
                HW.IsSmashingCurrentPumpkin = true
                if dist > 25 then
                    -- Nếu bị quái hoặc knockback đánh văng ra xa quá 25 studs -> Thoát trạng thái đập để bay lại
                    HW.IsSmashingCurrentPumpkin = false
                else
                    if getgenv().StopTween then getgenv().StopTween() end
                    if type(EquipSelectedWeapon) == "function" then EquipSelectedWeapon() end
                    if type(EnableBuso) == "function" then EnableBuso() end

                    -- Neo vị trí vững chắc phía trên quả bí ngô, triệt tiêu gia tốc rơi tự do
                    hrp.CFrame = CFrame.new(pPos + Vector3.new(0, 4, 0))
                    hrp.Velocity = Vector3.new(0, 0, 0)

                    -- Kiểm tra ngay nếu có quái vừa spawn từ quả bí ngô này -> Dừng đập, chuyển sang diệt quái ngay lập tức
                    local instantMob = HW.FindJackMob(150) or HW.FindNearbyMob(100)
                    if instantMob then
                        HW.CurrentPumpkinTarget = nil
                        HW.CurrentPumpkinPart = nil
                        HW.IsSmashingCurrentPumpkin = false
                        return true
                    end

                    pcall(function()
                        if firetouchinterest then
                            firetouchinterest(hrp, pumpkinPart, 0)
                            firetouchinterest(hrp, pumpkinPart, 1)
                        end
                    end)

                    -- Giới hạn tần suất gọi remote đập bí ngô (0.35s) và chạy bất đồng bộ trong task.spawn để không bao giờ làm khựng FPS / nghẽn mạng client
                    if tick() - (HW.LastPumpkinRemoteTick or 0) >= 0.35 then
                        HW.LastPumpkinRemoteTick = tick()
                        task.spawn(function()
                            pcall(function()
                                ReplicatedStorage.Remotes.CommF_:InvokeServer("SmashPumpkin", pumpkinObj)
                                ReplicatedStorage.Remotes.CommF_:InvokeServer("BreakPumpkin", pumpkinObj)
                                ReplicatedStorage.Remotes.CommF_:InvokeServer("HitPumpkin", pumpkinObj)
                            end)
                        end)
                    end

                    local char = plr.Character
                    local tool = char and char:FindFirstChildOfClass("Tool")
                    if tool then
                        pcall(function() tool:Activate() end)
                        if tool:FindFirstChild("LeftClickRemote") and (tick() - (HW.LastToolRemoteTick or 0) >= 0.15) then
                            HW.LastToolRemoteTick = tick()
                            pcall(function() tool.LeftClickRemote:FireServer((pumpkinPart.Position - hrp.Position).Unit, 1) end)
                        end
                        if RegisterAttack and RegisterHit and (tick() - (HW.LastPumpkinHitTick or 0) >= 0.15) then
                            HW.LastPumpkinHitTick = tick()
                            pcall(function()
                                RegisterAttack:FireServer(0)
                                RegisterHit:FireServer(pumpkinPart, {{pumpkinObj, pumpkinPart}})
                            end)
                        end
                    end

                    local pElapsed = tick() - (HW.CurrentPumpkinStartTick or tick())
                    local humP = pumpkinObj:FindFirstChildOfClass("Humanoid") or (pumpkinObj:IsA("Model") and pumpkinObj:FindFirstChild("Humanoid"))
                    local gotItemFromPumpkin = (HW.GotPumpkinItemAt and HW.GotPumpkinItemAt >= (HW.CurrentPumpkinStartTick or 0))
                    local isBroken = (not pumpkinObj.Parent) or (not pumpkinPart.Parent) or (humP and humP.Health <= 0) or gotItemFromPumpkin or (pElapsed >= 5.0)

                    if isBroken then
                        HW.IgnoredPumpkins[pumpkinObj] = tick()
                        pcall(function()
                            local tag = Instance.new("BoolValue")
                            tag.Name = "Z9_BrokenPumpkin"
                            tag.Parent = pumpkinObj
                        end)
                        HW.CurrentPumpkinTarget = nil
                        HW.CurrentPumpkinPart = nil
                        HW.IsSmashingCurrentPumpkin = false
                        -- Đặt thời gian chờ quái xuất hiện từ quả bí ngô vừa đập (2.0s)
                        HW.WaitingForPumpkinSpawnUntil = tick() + 2.0
                        HW.LastBrokenPumpkinPos = pPos
                    end
                end
            end
            return true
        end

        -- Nếu chưa đủ 500 kẹo mà quanh khu vực hiện tại chưa thấy Bí Ngô:
        -- TUẦN TRA LIÊN TỤC QUA CÁC ĐẢO CỦA SEA 1, SEA 2, SEA 3 ĐỂ TẢI MAP VÀ GOM SẠCH BÍ NGÔ TRÊN MỌI BẢN ĐỒ!
        local patrolWaypoints = HW.GetPatrolLocations()
        if patrolWaypoints and #patrolWaypoints > 0 then
            HW.PatrolIndex = ((HW.PatrolIndex or 1) - 1) % #patrolWaypoints + 1
            local targetCF = patrolWaypoints[HW.PatrolIndex]
            local pDist = (hrp.Position - targetCF.Position).Magnitude
            local curSeaNum = tostring(World3 and 3 or (World2 and 2 or 1))

            CurrentFarmStatus = string.format("[Sự Kiện Halloween] 🎃 Đang tuần tra các đảo Sea %s tìm Bí Ngô (Đảo %d/%d - Kẹo: %s/%s)...",
                curSeaNum,
                HW.PatrolIndex, #patrolWaypoints,
                tostring(curCandies), tostring(maxCandies)
            )
            HW.CurrentTask = string.format("Tuần tra đảo %d/%d Sea %s tìm Bí Ngô", HW.PatrolIndex, #patrolWaypoints, curSeaNum)

            if pDist > 100 then
                HW.PatrolStartTick = HW.PatrolStartTick or tick()
                if tick() - HW.PatrolStartTick > 7.0 then
                    HW.PatrolStartTick = tick()
                    HW.PatrolIndex = (HW.PatrolIndex % #patrolWaypoints) + 1
                else
                    if type(TweenTo) == "function" then TweenTo(targetCF) end
                end
            else
                HW.PatrolStartTick = nil
                HW.PatrolIndex = (HW.PatrolIndex % #patrolWaypoints) + 1
            end
            return true
        end

        CurrentFarmStatus = "[Sự Kiện Halloween] 🎃 Đang tìm kiếm Bí Ngô trên toàn bộ bản đồ (" .. tostring(curCandies) .. "/" .. tostring(maxCandies) .. ")..."
        HW.CurrentTask = "Tìm kiếm Bí Ngô trên toàn bộ bản đồ (" .. tostring(curCandies) .. "/" .. tostring(maxCandies) .. ")"
        return true
    end

    -- I. NẾU ĐÃ ĐỦ 500 KẸO NGÔ HOẶC HẾT MỤC TIÊU -> TRẢ VỀ FALSE ĐỂ TỰ ĐỘNG QUAY LẠI FARM CẤP / FARM VÕ!
    HW.IsDoingEvent = false
    HW.CurrentTask = (curCandies >= maxCandies) and ("Đã đủ " .. tostring(maxCandies) .. " Kẹo Ngô (Đang farm cấp/võ)") or "Đang farm cấp (Chờ khung giờ sự kiện)"
    return false
end

