function V1StyleLookup.ItemsSystem.RefreshInventory(force)
    local IS = V1StyleLookup.ItemsSystem
    local now = tick()
    if force or (now - (IS.LastInvCheck or 0) >= 3.0) then
        IS.LastInvCheck = now
        IS.CachedOwnedWeapons = IS.CachedOwnedWeapons or {}

        local newMap = {}
        local function parseInv(list)
            if type(list) == "table" then
                for _, item in pairs(list) do
                    if type(item) == "table" and item.Name then
                        local m = tonumber(item.Mastery) or tonumber(item.Level) or 0
                        newMap[item.Name] = {
                            Count = tonumber(item.Count) or 1,
                            Mastery = m,
                            Type = item.Type or "Weapon",
                        }
                        -- Tự động lưu vũ khí & phụ kiện đã sở hữu vĩnh viễn (Yama, Tushita, CDK, Saber, Serpent Bow, v.v...)
                        if item.Type == "Sword" or item.Type == "Gun" or item.Type == "Wear" or item.Type == "Accessory" or item.Name == "Yama" or item.Name == "Tushita" or item.Name == "Cursed Dual Katana" or item.Name == "Serpent Bow" then
                            IS.CachedOwnedWeapons[item.Name] = newMap[item.Name]
                        end
                    end
                end
            end
        end

        -- 1. Quét kho đồ vật phẩm & nguyên liệu (Hỗ trợ toàn diện getInventory, getInventoryMaterials, getMaterials, getStash)
        pcall(function()
            parseInv(ReplicatedStorage.Remotes.CommF_:InvokeServer("getInventory"))
        end)
        pcall(function()
            parseInv(ReplicatedStorage.Remotes.CommF_:InvokeServer("getInventoryMaterials"))
        end)
        pcall(function()
            parseInv(ReplicatedStorage.Remotes.CommF_:InvokeServer("getMaterials"))
        end)
        pcall(function()
            parseInv(ReplicatedStorage.Remotes.CommF_:InvokeServer("getStash"))
        end)
        pcall(function()
            parseInv(ReplicatedStorage.Remotes.CommF_:InvokeServer("getStashMaterials"))
        end)
        -- 2. Quét kho vũ khí & kiếm (getInventoryWeapons - rất quan trọng để nhận diện Yama/Tushita khi cất kho)
        pcall(function()
            parseInv(ReplicatedStorage.Remotes.CommF_:InvokeServer("getInventoryWeapons"))
        end)
        -- 2.5. Quét trực tiếp GUI Kho đồ (Items / Stash / Inventory) trên màn hình (đọc số lượng Cocoa, Dragon Scale, Fish Tail, Magma Ore...)
        pcall(function()
            local pg = plr:FindFirstChild("PlayerGui")
            if not pg then return end
            for _, desc in ipairs(pg:GetDescendants()) do
                local iName = desc:GetAttribute("ItemName") or desc:GetAttribute("Name") or desc.Name
                local rawN = tostring(iName or "")
                local isMat = rawN:find("Cocoa") or rawN:find("Fish Tail") or rawN:find("Dragon Scale") or rawN:find("Magma Ore") or rawN:find("Mystic Droplet")
                if not isMat and (desc:IsA("TextLabel") or desc:IsA("TextButton")) then
                    local t = tostring(desc.Text or "")
                    if t:find("Cocoa") or t:find("Fish Tail") or t:find("Dragon Scale") or t:find("Magma Ore") or t:find("Mystic Droplet") then
                        rawN = t
                        isMat = true
                    end
                end
                if isMat then
                    local matchedName = (rawN:find("Cocoa") and "Cocoa")
                        or (rawN:find("Fish Tail") and "Fish Tail")
                        or (rawN:find("Dragon Scale") and "Dragon Scale")
                        or (rawN:find("Magma Ore") and "Magma Ore")
                        or (rawN:find("Mystic Droplet") and "Mystic Droplet")
                    if matchedName then
                        local cAttr = desc:GetAttribute("Count") or desc:GetAttribute("Amount") or desc:GetAttribute("Quantity")
                        local cnt = tonumber(cAttr)
                        if not cnt then
                            for _, lbl in ipairs(desc:GetDescendants()) do
                                if lbl:IsA("TextLabel") then
                                    local n = tonumber(tostring(lbl.Text):gsub(",", ""):match("(%d+)"))
                                    if n and n > 0 and n < 100000 then cnt = n; break end
                                end
                            end
                        end
                        if cnt and cnt > 0 then
                            newMap[matchedName] = { Count = cnt, Mastery = 0, Type = "Material" }
                            if matchedName == "Cocoa" then newMap["Conjured Cocoa"] = newMap[matchedName] end
                        end
                    end
                end
            end
        end)
        -- 3. Quét hệ thống ItemReplication nếu có
        pcall(function()
            local irsObj = ReplicatedStorage:FindFirstChild("ItemReplicationService")
            local icObj = ReplicatedStorage:FindFirstChild("ItemConfig")
            if irsObj and icObj then
                local IRS = require(irsObj)
                local IC = require(icObj)
                local keys = IRS.KEYS
                local rawList = nil
                pcall(function() rawList = IRS:GetItems(keys.QUANTITY) end)
                if not rawList and IRS.GetItems then pcall(function() rawList = IRS:GetItems() end) end
                if type(rawList) == "table" then
                    for _, item in pairs(rawList) do
                        if type(item) == "table" and item.Value and item.Value > 0 then
                            local ok2, cfg = pcall(function() return IC.match(item.ItemId):unwrap() end)
                            if ok2 and cfg and cfg.Display then
                                local name = cfg.Display.Name or (cfg.Index and cfg.Index.StorageKey)
                                if name then
                                    newMap[name] = { Count = item.Value, Mastery = 0, Type = cfg.Display.Category or "Item" }
                                    if name == "Cocoa" or name == "Conjured Cocoa" then
                                        newMap["Cocoa"] = newMap[name]
                                        newMap["Conjured Cocoa"] = newMap[name]
                                    end
                                    if name == "Yama" or name == "Tushita" or name == "Cursed Dual Katana" then
                                        IS.CachedOwnedWeapons[name] = newMap[name]
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end)

        -- Duyệt lại các vũ khí đã từng xác nhận sở hữu để không bao giờ bị mất trạng thái
        for wName, entry in pairs(IS.CachedOwnedWeapons) do
            if not newMap[wName] then
                newMap[wName] = entry
            end
        end

        IS.InvMap = newMap
    end

    -- Đồng bộ trực tiếp các Tool đang cầm trong Backpack & Character
    for _, container in ipairs({ plr.Backpack, plr.Character }) do
        if container then
            for _, t in ipairs(container:GetChildren()) do
                if t:IsA("Tool") then
                    local isTemp = (t.Name == "God's Chalice" or t.Name == "Sweet Chalice" or t.Name == "Fist of Darkness"
                        or t.Name == "Fire Essence" or t.Name == "Hallow Essence" or t.Name == "Microchip"
                        or t.Name == "Library Key" or t.Name == "Water Key" or t.Name == "Hidden Key"
                        or t.Name == "Hellfire Torch" or t.Name == "Core Brain" or t.Name == "Holy Torch")
                    local lvObj = t:FindFirstChild("Level")
                    local liveMas = (lvObj and tonumber(lvObj.Value)) or 0
                    local entry = IS.InvMap[t.Name]
                    if not entry then
                        IS.InvMap[t.Name] = { Count = 1, Mastery = liveMas, Type = t.ToolTip or "Weapon" }
                    elseif liveMas > (entry.Mastery or 0) then
                        entry.Mastery = liveMas
                    end
                    -- Chỉ lưu vũ khí vĩnh viễn vào CachedOwnedWeapons (không lưu vật phẩm tạm thời)
                    if not isTemp then
                        IS.CachedOwnedWeapons[t.Name] = IS.InvMap[t.Name]
                    end
                end
            end
        end
    end
end

function V1StyleLookup.ItemsSystem.HasToolOnPlayer(toolName)
    if not toolName or toolName == "" then return false end
    local cleanTarget = string.lower(toolName):gsub("[%s_%-]+", "")
    if cleanTarget == "" then return false end
    for _, container in ipairs({ plr.Character, plr:FindFirstChild("Backpack") }) do
        if container then
            for _, item in ipairs(container:GetChildren()) do
                if item:IsA("Tool") then
                    local cName = string.lower(item.Name):gsub("[%s_%-]+", "")
                    if cName == cleanTarget or (cleanTarget:len() >= 4 and cName:find(cleanTarget, 1, true)) then
                        return true
                    end
                end
            end
        end
    end
    return false
end

function V1StyleLookup.ItemsSystem.HasItem(itemName)
    if not itemName or itemName == "" then return false end
    local IS = V1StyleLookup.ItemsSystem
    IS.CachedOwnedWeapons = IS.CachedOwnedWeapons or {}

    local cleanTarget = string.lower(itemName):gsub("[%s_%-]+", "")
    if cleanTarget == "" then return false end

    -- Vật phẩm quest tạm thời (không bao giờ lưu kho): chỉ kiểm tra trực tiếp trên người (Tool)
    local isTemp = (cleanTarget == "godschalice" or cleanTarget == "sweetchalice"
        or cleanTarget == "fistofdarkness" or cleanTarget == "fireessence"
        or cleanTarget == "hallowessence" or cleanTarget == "microchip"
        or cleanTarget == "librarykey" or cleanTarget == "waterkey"
        or cleanTarget == "hiddenkey" or cleanTarget == "hellfiretorch"
        or cleanTarget == "corebrain" or cleanTarget == "holytorch")
    if isTemp then
        return IS.HasToolOnPlayer(itemName)
    end

    -- 1. Nếu đang cầm trên người (Character & Backpack)
    if IS.HasToolOnPlayer(itemName) then
        IS.CachedOwnedWeapons[itemName] = { Count = 1, Mastery = IS.GetMastery(itemName), Type = "Weapon" }
        return true
    end

    -- 2. Kiểm tra trong bộ nhớ đệm vĩnh viễn (CachedOwnedWeapons)
    if IS.CachedOwnedWeapons[itemName] ~= nil then
        return true
    end
    for k, v in pairs(IS.CachedOwnedWeapons) do
        local cK = string.lower(tostring(k)):gsub("[%s_%-]+", "")
        if cK == cleanTarget or (cleanTarget:len() >= 4 and cK:find(cleanTarget, 1, true)) then
            return true
        end
    end

    -- 3. Làm mới kho đồ và kiểm tra trong InvMap
    IS.RefreshInventory(false)
    if IS.HasToolOnPlayer(itemName) then
        IS.CachedOwnedWeapons[itemName] = { Count = 1, Mastery = IS.GetMastery(itemName), Type = "Weapon" }
        return true
    end
    if IS.InvMap[itemName] ~= nil then
        IS.CachedOwnedWeapons[itemName] = IS.InvMap[itemName]
        return true
    end
    for k, v in pairs(IS.InvMap) do
        local cK = string.lower(tostring(k)):gsub("[%s_%-]+", "")
        if cK == cleanTarget or (cleanTarget:len() >= 4 and cK:find(cleanTarget, 1, true)) then
            IS.CachedOwnedWeapons[itemName] = v
            return true
        end
    end

    if itemName == "Conjured Cocoa" or itemName == "Cocoa" then
        return IS.InvMap["Conjured Cocoa"] ~= nil or IS.InvMap["Cocoa"] ~= nil
    end

    -- 4. Nếu là vũ khí đặc biệt (Yama, Tushita, Cursed Dual Katana):
    if itemName == "Yama" or itemName == "Tushita" or itemName == "Cursed Dual Katana" then
        if IS.HasToolOnPlayer(itemName) or IS.InvMap[itemName] ~= nil then
            IS.CachedOwnedWeapons[itemName] = IS.InvMap[itemName] or { Count = 1, Mastery = IS.GetMastery(itemName), Type = "Sword" }
            return true
        end
    end

    return false
end

function V1StyleLookup.ItemsSystem.GetCount(itemName)
    local IS = V1StyleLookup.ItemsSystem
    IS.RefreshInventory(false)
    local entry = IS.InvMap[itemName]
    if entry and tonumber(entry.Count) then
        return tonumber(entry.Count)
    end
    if itemName == "Conjured Cocoa" or itemName == "Cocoa" then
        local c1 = IS.InvMap["Conjured Cocoa"] and tonumber(IS.InvMap["Conjured Cocoa"].Count)
        local c2 = IS.InvMap["Cocoa"] and tonumber(IS.InvMap["Cocoa"].Count)
        local c = math.max(c1 or 0, c2 or 0)
        if c > 0 then return c end

        -- Dự phòng đọc trực tiếp từ ItemReplicationService
        pcall(function()
            local IRS = ItemReplicationService or (ReplicatedStorage:FindFirstChild("ItemReplicationService") and require(ReplicatedStorage.ItemReplicationService))
            if IRS then
                for _, nameKey in ipairs({ "Cocoa", "Conjured Cocoa", "ConjuredCocoa" }) do
                    local q = (IRS.GetItemQuantity and IRS:GetItemQuantity(nameKey)) or (IRS.GetItemCount and IRS:GetItemCount(nameKey))
                    if tonumber(q) and tonumber(q) > 0 then
                        c = tonumber(q)
                        IS.InvMap["Conjured Cocoa"] = { Count = c, Mastery = 0, Type = "Material" }
                        IS.InvMap["Cocoa"] = IS.InvMap["Conjured Cocoa"]
                        break
                    end
                end
            end
        end)
        if c > 0 then return c end
    end
    if IS.HasToolOnPlayer(itemName) then return 1 end
    return 0
end

function V1StyleLookup.ItemsSystem.GetMastery(itemName)
    local IS = V1StyleLookup.ItemsSystem
    IS.RefreshInventory(false)
    for _, container in ipairs({ plr.Character, plr.Backpack }) do
        local tool = container and container:FindFirstChild(itemName)
        if tool and tool:FindFirstChild("Level") then
            return tonumber(tool.Level.Value) or 0
        end
    end
    local entry = IS.InvMap[itemName]
    return (entry and tonumber(entry.Mastery)) or 0
end

function V1StyleLookup.ItemsSystem.HasAllGodhumanMaterials()
    local IS = V1StyleLookup.ItemsSystem
    IS.RefreshInventory(false)
    for _, mat in ipairs(IS.GodhumanMaterials) do
        if IS.GetCount(mat.Name) < mat.Need then
            return false
        end
    end
    return true
end

function V1StyleLookup.ItemsSystem.IsHoldingProtectedItem()
    local IS = V1StyleLookup.ItemsSystem
    return IS.HasToolOnPlayer("God's Chalice")
        or IS.HasToolOnPlayer("Sweet Chalice")
        or IS.HasToolOnPlayer("Holy Torch")
        or IS.HasToolOnPlayer("Fist of Darkness")
        or IS.HasToolOnPlayer("Fire Essence")
        or IS.HasToolOnPlayer("Hallow Essence")
        or (not IS.DeathStepDoorOpened and not getgenv().Z9_DeathStepDoorOpened and IS.HasToolOnPlayer("Library Key"))
        or (not IS.HiddenKeyUsed and not IS.HasItem("Rengoku") and IS.HasToolOnPlayer("Hidden Key"))
        or IS.HasToolOnPlayer("Water Key")
        or IS.HasToolOnPlayer("Hellfire Torch")
        or IS.HasToolOnPlayer("Core Brain")
        or IS.HasToolOnPlayer("Microchip")
end

function V1StyleLookup.ItemsSystem.IsTTKEnabled()
    local sf = getgenv().SettingFarm
    local gi = sf and sf["Get Items"]
    if type(gi) == "table" and gi["True Triple Katana"] ~= nil then
        return gi["True Triple Katana"] == true
    end
    return true
end

function V1StyleLookup.ItemsSystem.IsBonesOnCooldown()
    local IS = V1StyleLookup.ItemsSystem
    local now = tick()
    if (IS.BonesCooldownUntil or 0) > now then
        return true, math.max(0, math.floor(IS.BonesCooldownUntil - now))
    end
    return false, 0
end

function V1StyleLookup.ItemsSystem.CheckBonesCooldownFromServer(buyRes)
    local IS = V1StyleLookup.ItemsSystem
    local now = tick()
    local isOut = false
    local waitMinutes = 120

    -- 1. Phân tích kết quả trả về từ remote Buy
    if type(buyRes) == "string" then
        local low = string.lower(buyRes)
        -- Blox Fruits chỉ thông báo hết lượt khi chứa: "check back in", "maximum amount", hoặc "reached the limit"
        if low:find("check back") or low:find("maximum") or low:find("reached the limit") or (low:find("limit") and low:find("surprise")) then
            isOut = true
            local h = tonumber(low:match("(%d+)%s*hour") or low:match("(%d+)%s*h")) or 0
            local m = tonumber(low:match("(%d+)%s*min") or low:match("(%d+)%s*m")) or 0
            local totalMin = h * 60 + m
            if totalMin > 0 then
                waitMinutes = totalMin
            end
        end
    end

    -- 2. Kiểm tra thông báo đỏ từ Notifications trên màn hình
    if not isOut then
        local pg = plr:FindFirstChild("PlayerGui")
        local notif = pg and pg:FindFirstChild("Notifications")
        if notif then
            for _, desc in ipairs(notif:GetDescendants()) do
                if desc:IsA("TextLabel") and desc.Visible and desc.Text ~= "" then
                    local tLow = string.lower(desc.Text)
                    -- TUYỆT ĐỐI không match chữ "surprise" đứng lẻ vì khi quay thành công cũng hiện "Random Surprise: +..."
                    -- Chỉ match khi có thông báo "check back" hoặc "maximum amount of surprise" hoặc "đã đạt giới hạn"
                    if tLow:find("check back") or tLow:find("maximum amount") or tLow:find("giới hạn") or (tLow:find("limit") and tLow:find("surprise")) then
                        isOut = true
                        local h = tonumber(tLow:match("(%d+)%s*hour") or tLow:match("(%d+)%s*h")) or 0
                        local m = tonumber(tLow:match("(%d+)%s*min") or tLow:match("(%d+)%s*m")) or 0
                        local totalMin = h * 60 + m
                        if totalMin > 0 then
                            waitMinutes = totalMin
                        end
                        break
                    end
                end
            end
        end
    end

    if isOut then
        IS.BonesCooldownUntil = now + (waitMinutes * 60)
    else
        -- Không có thông báo hết lượt thật từ Server -> Xóa sạch cooldown!
        IS.BonesCooldownUntil = 0
    end

    return IS.IsBonesOnCooldown()
end

