function V1StyleLookup.ItemsSystem.EquipToolByName(toolName)
    local char = plr.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not char or not hum then return nil end
    local inChar = char:FindFirstChild(toolName)
    if inChar then return inChar end
    local inBp = plr.Backpack and plr.Backpack:FindFirstChild(toolName)
    if inBp then
        hum:EquipTool(inBp)
        return inBp
    end
    -- Tự động nạp vũ khí từ kho đồ vào Backpack nếu đang cất kho
    pcall(function()
        ReplicatedStorage.Remotes.CommF_:InvokeServer("LoadItem", toolName)
    end)
    local loadedBp = plr.Backpack and plr.Backpack:FindFirstChild(toolName)
    if loadedBp then
        hum:EquipTool(loadedBp)
        return loadedBp
    end
    return nil
end

function V1StyleLookup.ItemsSystem.HasDoubleExp()
    local pg = plr:FindFirstChild("PlayerGui")
    local main = pg and pg:FindFirstChild("Main")
    local lvFrame = main and main:FindFirstChild("Level")
    local expLbl = lvFrame and lvFrame:FindFirstChild("Exp")
    if expLbl and expLbl:IsA("TextLabel") then
        local txt = string.lower(expLbl.Text or "")
        if txt:find("2x") or txt:find("x2") then
            return true
        end
    end
    return false
end

