-- Vòng lặp ngầm:
-- 1. Tự động nhập Code X2 EXP thông minh (chỉ nhập từng code khi hết thời gian X2 EXP để tiết kiệm cho cả quá trình cày cấp)
-- 2. Tự động mặc Phụ Kiện (Accessory) mạnh nhất đang có trong kho đồ
-- 3. Tự động quay Xương (Death King Random Surprise) tại Sea 3 để lấy Fire Essence, Hallow Essence & X2 EXP miễn phí
-- 4. Tự động mua Kabucha (1,500F), Midnight Blade (100 Ectoplasm), 3 Kiếm Huyền Thoại TTK (Shisui, Wando, Saddi) & 3 Màu Haki triệu hồi rip_indra
task.spawn(function()
    task.wait(6)
    while task.wait(12) do
        pcall(function()
            local IS = V1StyleLookup.ItemsSystem
            IS.RefreshInventory(false)
            local curLv = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0
            local beli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
            local frags = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Fragments") and plr.Data.Fragments.Value) or 0

            -- [1] Auto Redeem Code X2 EXP thông minh
            if curLv < 2800 and not IS.AllCodesExhausted and not IS.HasDoubleExp() then
                local redeemRemote = ReplicatedStorage:FindFirstChild("Remotes") and ReplicatedStorage.Remotes:FindFirstChild("Redeem")
                if redeemRemote then
                    local redeemedAny = false
                    for _, code in ipairs(IS.ExpCodes) do
                        if not IS.UsedCodes[code] then
                            IS.UsedCodes[code] = true
                            redeemedAny = true
                            local res = nil
                            pcall(function()
                                res = redeemRemote:InvokeServer(code)
                            end)
                            task.wait(0.3)
                            if IS.HasDoubleExp() or (type(res) == "string" and string.find(string.upper(res), "SUCC")) then
                                break -- Đã kích hoạt X2 EXP thành công -> Dừng lại để dành các code còn lại!
                            end
                        end
                    end
                    if not redeemedAny then
                        IS.AllCodesExhausted = true
                    end
                end
            end

            -- [2] Auto Equip Best Accessory (Tự đeo phụ kiện tốt nhất trong kho)
            for _, accName in ipairs(IS.BestAccessories) do
                if IS.InvMap[accName] then
                    if IS.EquippedAccessory ~= accName then
                        IS.EquippedAccessory = accName
                        pcall(function()
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("LoadItem", accName)
                        end)
                    end
                    break
                end
            end

            -- [3] Auto Roll Bones (Death King - Sea 3) lấy Fire Essence / Hallow Essence / X2 EXP
            local autoBonesEnabled = true
            if getgenv().SettingFarm then
                local ab = getgenv().SettingFarm["Auto Bones"] or getgenv().SettingFarm.AutoBones
                if ab == false then
                    autoBonesEnabled = false
                elseif type(ab) == "table" then
                    if ab["Buy Random Surprise"] == false or ab["Enabled"] == false then
                        autoBonesEnabled = false
                    end
                end
            end
            if autoBonesEnabled and (World3 or CurrentSeaNum == 3) and tick() >= (IS.BonesCooldownUntil or 0) then
                local boneCount = IS.GetCount("Bones")
                local needSave500ForSG = (IsSettingGetItem("Skull Guitar") or IsSettingGetItem("Soul Guitar"))
                    and not IS.HasItem("Skull Guitar")
                    and curLv >= 2300
                    and type(IS.SGProg) == "table"
                    and IS.SGProg.Pipes == true
                local minBonesToRoll = needSave500ForSG and 550 or 50

                if boneCount >= minBonesToRoll then
                    local _, _, state, msg = ReplicatedStorage.Remotes.CommF_:InvokeServer("Bones", "Check")
                    if tonumber(state or 1) == 0 and type(msg) == "string" then
                        local parts = msg:split(":")
                        local h = tonumber(parts[1]) or 0
                        local m = tonumber(parts[2]) or 10
                        IS.BonesCooldownUntil = tick() + ((h * 60 + m) * 60)
                    else
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("Bones", "Buy", 1, 1)
                    end
                end
            end

            -- [4] Auto Buy Kabucha (1,500 Fragments) & Midnight Blade (100 Ectoplasm)
            if CurrentSeaNum >= 2 and not IS.HasItem("Kabucha") and (frags >= 6500 or (V1StyleLookup.IsPreGodhumanMastered() and frags >= 1500)) then
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("BlackbeardReward", "Slingshot", "1")
                    task.wait(0.2)
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("BlackbeardReward", "Slingshot", "2")
                end)
            end

            local ectoCount = IS.GetCount("Ectoplasm")
            local needSave250EctoForSG = (World3 or CurrentSeaNum == 3) and not IS.HasItem("Skull Guitar") and curLv >= 2300
            local minEctoForMidnight = needSave250EctoForSG and 350 or 100
            if CurrentSeaNum >= 2 and not IS.HasItem("Midnight Blade") and ectoCount >= minEctoForMidnight then
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("Ectoplasm", "Buy", 3)
                end)
            end

            -- [5] Auto Buy 3 Kiếm Huyền Thoại (Shisui, Wando, Saddi - $2M/thanh) từ Legendary Sword Dealer tại Sea 2
            if (World2 or CurrentSeaNum == 2) and IS.IsTTKEnabled() and not IS.HasItem("True Triple Katana") and beli >= 2000000 then
                if not (IS.HasItem("Shisui") and IS.HasItem("Wando") and IS.HasItem("Saddi")) then
                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("LegendarySwordDealer", "1")
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("LegendarySwordDealer", "2")
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("LegendarySwordDealer", "3")
                    end)
                end
            end

            -- [6] Auto Buy 3 Màu Haki Huyền Thoại (Pure Red, Winter Sky, Snow White) để tự triệu hồi rip_indra
            if CurrentSeaNum >= 2 and (frags >= 7500 or V1StyleLookup.IsPreGodhumanMastered()) then
                for _, colName in ipairs(IS.LegendaryHakiColors) do
                    if not IS.OwnedHakiColors[colName] then
                        pcall(function()
                            local net = ReplicatedStorage:FindFirstChild("Modules") and ReplicatedStorage.Modules:FindFirstChild("Net")
                            local rfBarista = net and net:FindFirstChild("RF/InteractBarista")
                            if rfBarista then
                                rfBarista:InvokeServer({ NPC = "Barista", Command = "Purchase", ColorName = colName })
                            end
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("ColorsDealer", "2")
                        end)
                    end
                end
            end

            -- [7] Auto Request Dojo Trainer Quest (Sea 3 - khi Dragon Talon >= 500 Mastery)
            local dojoEnabled = true
            if getgenv().SettingFarm then
                local dj = getgenv().SettingFarm["Dojo Trainer"]
                if dj == nil then dj = getgenv().SettingFarm.DojoTrainer end
                if dj == nil then dj = getgenv().SettingFarm["Auto Dojo"] end
                if dj == false or (type(dj) == "table" and dj["Enabled"] == false) then
                    dojoEnabled = false
                end
            end
            if dojoEnabled and (World3 or CurrentSeaNum == 3) and IS.GetMastery("Dragon Talon") >= 500 and not IS.DojoBlackBeltDone then
                if IS.HasItem("Dojo Belt (Black)") then
                    IS.DojoBlackBeltDone = true
                elseif tick() - (IS.LastDojoCheck or 0) >= 20.0 then
                    IS.LastDojoCheck = tick()
                    pcall(function()
                        local net = ReplicatedStorage:FindFirstChild("Modules")
                            and ReplicatedStorage.Modules:FindFirstChild("Net")
                            and ReplicatedStorage.Modules.Net:FindFirstChild("RF/InteractDragonQuest")
                        if net then
                            IS.DojoQuestData = net:InvokeServer({ NPC = "Dojo Trainer", Command = "RequestQuest" })
                        end
                    end)
                end
            end
        end)
    end
end)

function V1StyleLookup.ItemsSystem.CollectNearestChest(hrp)
    local IS = V1StyleLookup.ItemsSystem
    local bestChest, bestDist = nil, math.huge
    local function considerChest(v)
        if not v then return end
        local part = v:IsA("BasePart") and v or (v:IsA("Model") and (v.PrimaryPart or v:FindFirstChildWhichIsA("BasePart", true)))
        if part and not v:FindFirstChild("Z9_IgnoredChest") and not part:FindFirstChild("Z9_IgnoredChest") then
            local d = (part.Position - hrp.Position).Magnitude
            if d < bestDist then
                bestDist = d
                bestChest = part
            end
        end
    end

    if CollectionService then
        for _, c in ipairs(CollectionService:GetTagged("_ChestTagged")) do
            considerChest(c)
        end
    end
    local chestModels = workspace:FindFirstChild("ChestModels")
    if chestModels then
        for _, c in ipairs(chestModels:GetChildren()) do
            considerChest(c)
        end
    end
    if not bestChest then
        if not IS._cachedChests or (tick() - (IS._lastChestScan or 0) > 4.0) then
            IS._lastChestScan = tick()
            IS._cachedChests = {}
            local map = workspace:FindFirstChild("Map") or workspace
            for _, v in ipairs(map:GetDescendants()) do
                if v:IsA("BasePart") and string.find(v.Name, "Chest") and v:FindFirstChildOfClass("TouchTransmitter") then
                    table.insert(IS._cachedChests, v)
                end
            end
        end
        for _, v in ipairs(IS._cachedChests) do
            if v and v.Parent then
                considerChest(v)
            end
        end
    end
    if bestChest then
        CurrentFarmStatus = "[Săn Fist of Darkness] Đang bay nhặt Rương (" .. tostring(bestChest.Name) .. ") tìm Fist of Darkness..."
        if bestDist > 6 then
            TweenTo(bestChest.CFrame)
        else
            if getgenv().StopTween then getgenv().StopTween() end
            RefreshTeleportTag()
            hrp.CFrame = bestChest.CFrame
            pcall(function()
                if firetouchinterest then
                    firetouchinterest(hrp, bestChest, 0)
                    firetouchinterest(hrp, bestChest, 1)
                end
                local tag = Instance.new("BoolValue")
                tag.Name = "Z9_IgnoredChest"
                tag.Parent = bestChest
            end)
        end
        return true
    end
    return false
end

-- Kiểm tra và làm nhiệm vụ mở khóa ẩn cho 4 bộ Võ V2 (Death Step, Sharkman Karate, Electric Claw, Dragon Talon)
function V1StyleLookup.ItemsSystem.DoMeleeV2UnlockStep(hrp, hum, targetStyle)
    if not targetStyle then return false end
    local IS = V1StyleLookup.ItemsSystem
    local sName = targetStyle.Name
    local curLv = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0

    -- 1. Death Step: Cần Library Key mở cửa Phoeyu tại Ice Castle (Sea 2)
    if sName == "Death Step" then
        if IS.DeathStepDoorOpened or getgenv().Z9_DeathStepDoorOpened then
            return false
        end

        -- Nếu đã sở hữu hoặc từng có Mastery của Death Step -> Cửa đã mở từ lâu!
        if V1StyleLookup.FindMeleeTool("Death Step")
            or (V1StyleLookup.BoughtStyles and V1StyleLookup.BoughtStyles["Death Step"])
            or (V1StyleLookup.MasteredV2 and V1StyleLookup.MasteredV2["Death Step"])
            or (V1StyleLookup.RecordsV2 and (V1StyleLookup.RecordsV2["Death Step"] or 0) > 0) then
            IS.DeathStepDoorOpened = true
            getgenv().Z9_DeathStepDoorOpened = true
            MeleeStorage.Save()
            return false
        end

        -- Gọi remote Phoeyu kiểm tra trạng thái cửa thư viện (hoạt động từ mọi Sea)
        local deathCheck = nil
        pcall(function()
            deathCheck = ReplicatedStorage.Remotes.CommF_:InvokeServer("BuyDeathStep", true)
        end)
        -- Nếu Phoeyu phản hồi số (1: đã có, 2: thiếu tiền/F nhưng cửa ĐÃ MỞ, 3: sẵn sàng mua) hoặc phản hồi bất kỳ không nhắc đến key -> Cửa thư viện ĐÃ MỞ VĨNH VIỄN!
        if deathCheck == 1 or deathCheck == 2 or deathCheck == 3
            or deathCheck == "1" or deathCheck == "2" or deathCheck == "3"
            or (type(deathCheck) == "string" and not string.find(string.lower(deathCheck), "ready") and not string.find(string.lower(deathCheck), "key")) then
            IS.DeathStepDoorOpened = true
            getgenv().Z9_DeathStepDoorOpened = true
            MeleeStorage.Save()
            return false
        end

        -- Kiểm tra cửa vật lý nếu đang ở Sea 2
        local libDoor = nil
        if CurrentSeaNum == 2 and workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("IceCastle") then
            libDoor = workspace.Map.IceCastle:FindFirstChild("Hall")
                and workspace.Map.IceCastle.Hall:FindFirstChild("LibraryDoor")
                and workspace.Map.IceCastle.Hall.LibraryDoor:FindFirstChild("PhoeyuDoor")
            if not libDoor or libDoor.Transparency > 0.5 or libDoor.CanCollide == false then
                -- Cửa thư viện đã mở hoặc biến mất khỏi map hoặc không còn va chạm -> Đánh dấu hoàn tất
                IS.DeathStepDoorOpened = true
                getgenv().Z9_DeathStepDoorOpened = true
                MeleeStorage.Save()
                return false
            end
        end

        -- Nếu có chìa khóa Library Key trên người
        if IS.HasToolOnPlayer("Library Key") then
            if CurrentSeaNum ~= 2 then
                -- Đang ở Sea khác mà có Library Key -> Về Sea 2 mở cửa ngay
                if not IS.IsHoldingProtectedItem() and tick() - LastTravelAttempt >= 8 then
                    LastTravelAttempt = tick()
                    CurrentFarmStatus = "[Death Step] 🔑 Có Library Key -> Đang về Sea 2 mở vĩnh viễn cửa phòng Phoeyu..."
                    if getgenv().StopTween then getgenv().StopTween() end
                    pcall(function() ReplicatedStorage.Remotes.CommF_:InvokeServer("TravelDressrosa") end)
                    task.wait(2)
                    return true
                end
            else
                local libDoorCF = (libDoor and libDoor.CFrame) or CFrame.new(6371.20, 296.63, -6841.18)
                local distToDoor = (hrp.Position - libDoorCF.Position).Magnitude
                IS.EquipToolByName("Library Key")
                if distToDoor > 15 then
                    if distToDoor > 400 then LoadIslandByFakePoint(libDoorCF) end
                    CurrentFarmStatus = "[Death Step] 🔑 Có Library Key -> Đang bay tới mở vĩnh viễn cửa phòng Phoeyu..."
                    TweenTo(libDoorCF * CFrame.new(0, 0, -2))
                    return true
                else
                    if getgenv().StopTween then getgenv().StopTween() end
                    CurrentFarmStatus = "[Death Step] 🔑 Đang mở khóa vĩnh viễn cửa phòng Phoeyu..."
                    IS.EquipToolByName("Library Key")

                    local keyTool = (plr.Character and plr.Character:FindFirstChild("Library Key"))
                    local keyHandle = keyTool and keyTool:FindFirstChild("Handle")
                    for step = -3, 3, 2 do
                        hrp.CFrame = libDoorCF * CFrame.new(0, 0, step)
                        if libDoor and firetouchinterest then
                            if keyHandle then
                                pcall(firetouchinterest, keyHandle, libDoor, 0)
                                task.wait(0.02)
                                pcall(firetouchinterest, keyHandle, libDoor, 1)
                            end
                            pcall(firetouchinterest, hrp, libDoor, 0)
                            task.wait(0.02)
                            pcall(firetouchinterest, hrp, libDoor, 1)
                        end
                        task.wait(0.08)
                    end

                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("BuyDeathStep", true)
                    end)

                    getgenv()._libDoorTryCount = (getgenv()._libDoorTryCount or 0) + 1
                    local keyGone = not IS.HasToolOnPlayer("Library Key")
                    if keyGone or getgenv()._libDoorTryCount >= 8 then
                        IS.DeathStepDoorOpened = true
                        getgenv().Z9_DeathStepDoorOpened = true
                        getgenv()._libDoorTryCount = nil
                        pcall(function() hum:UnequipTools() end)
                        EquipSelectedWeapon()
                        CurrentFarmStatus = "[Death Step] ✅ Đã mở khóa vĩnh viễn cửa phòng Phoeyu! Tiếp tục farm..."
                        MeleeStorage.Save()
                        task.wait(0.3)
                        return false
                    else
                        task.wait(0.2)
                        return true
                    end
                end
            end
        else
            -- Chưa có Library Key và cửa chưa mở:
            local beli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
            local frags = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Fragments") and plr.Data.Fragments.Value) or 0
            -- Nếu đang ở Sea 3 mà CHƯA ĐỦ 5,000 F hoặc $2,500,000 Beli -> TUYỆT ĐỐI KHÔNG về Sea 2 để tránh tele qua lại vô nghĩa!
            if CurrentSeaNum ~= 2 then
                if frags < 5000 or beli < 2500000 then
                    return false
                elseif not IS.IsHoldingProtectedItem() and tick() - LastTravelAttempt >= 8 then
                    LastTravelAttempt = tick()
                    CurrentFarmStatus = "[Mở Khóa Death Step] Cần Library Key -> Đang về Sea 2 săn Awakened Ice Admiral..."
                    if getgenv().StopTween then getgenv().StopTween() end
                    pcall(function() ReplicatedStorage.Remotes.CommF_:InvokeServer("TravelDressrosa") end)
                    task.wait(2)
                    return true
                end
            elseif CurrentSeaNum == 2 then
                return IS.AttackMobsByList(
                    hrp,
                    hum,
                    { "Awakened Ice Admiral", "Icecle", "Arctic Warrior" },
                    CFrame.new(6473, 297, -6944),
                    "[Mở Khóa Death Step - Săn Library Key]",
                    nil
                )
            end
        end
    end

    -- 2. Sharkman Karate: Cần Water Key nộp cho Daigrock (Sea 2)
    if sName == "Sharkman Karate" then
        if IS.SharkmanKeySubmitted or getgenv().Z9_SharkmanKeySubmitted then
            return false
        end

        -- Nếu đã sở hữu hoặc từng có Mastery của Sharkman Karate -> Water Key đã nộp từ lâu!
        if V1StyleLookup.FindMeleeTool("Sharkman Karate")
            or (V1StyleLookup.BoughtStyles and V1StyleLookup.BoughtStyles["Sharkman Karate"])
            or (V1StyleLookup.MasteredV2 and V1StyleLookup.MasteredV2["Sharkman Karate"])
            or (V1StyleLookup.RecordsV2 and (V1StyleLookup.RecordsV2["Sharkman Karate"] or 0) > 0) then
            IS.SharkmanKeySubmitted = true
            getgenv().Z9_SharkmanKeySubmitted = true
            MeleeStorage.Save()
            return false
        end

        local res = nil
        pcall(function()
            res = ReplicatedStorage.Remotes.CommF_:InvokeServer("BuySharkmanKarate", true)
        end)
        -- res == 1 (đã có), 2 (thiếu tiền/F nhưng ĐÃ NỘP KEY), 3 (sẵn sàng mua) -> Water Key đã nộp!
        if res == 1 or res == 2 or res == 3 or res == "1" or res == "2" or res == "3"
            or (type(res) == "string" and not string.find(string.lower(res), "key") and not string.find(string.lower(res), "ready")) then
            IS.SharkmanKeySubmitted = true
            getgenv().Z9_SharkmanKeySubmitted = true
            MeleeStorage.Save()
            return false
        end

        if IS.HasToolOnPlayer("Water Key") then
            CurrentFarmStatus = "[Mở Khóa Sharkman Karate] Đang nộp Water Key cho sư phụ Daigrock..."
            IS.EquipToolByName("Water Key")
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("BuySharkmanKarate", true)
                ReplicatedStorage.Remotes.CommF_:InvokeServer("BuySharkmanKarate")
            end)
            IS.SharkmanKeySubmitted = true
            getgenv().Z9_SharkmanKeySubmitted = true
            MeleeStorage.Save()
            return true
        else
            local beli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
            local frags = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Fragments") and plr.Data.Fragments.Value) or 0
            if CurrentSeaNum ~= 2 then
                if frags < 5000 or beli < 2500000 then
                    return false
                elseif not IS.IsHoldingProtectedItem() and tick() - LastTravelAttempt >= 8 then
                    LastTravelAttempt = tick()
                    CurrentFarmStatus = "[Mở Khóa Sharkman Karate] Cần Water Key -> Đang về Sea 2 săn Boss Tide Keeper..."
                    if getgenv().StopTween then getgenv().StopTween() end
                    pcall(function() ReplicatedStorage.Remotes.CommF_:InvokeServer("TravelDressrosa") end)
                    task.wait(2)
                    return true
                end
            elseif CurrentSeaNum == 2 then
                return IS.AttackMobsByList(
                    hrp,
                    hum,
                    { "Tide Keeper", "Sea Soldier", "Water Fighter" },
                    CFrame.new(-3570, 123, -11555),
                    "[Mở Khóa Sharkman Karate - Săn Water Key]",
                    nil
                )
            end
        end
    end

    -- 3. Electric Claw: Cần hoàn thành thử thách chạy tới Mansion trong 30 giây của Previous Hero (Sea 3)
    if sName == "Electric Claw" and (World3 or CurrentSeaNum == 3) and not IS.ElectricClawQuestDone then
        pcall(function() ReplicatedStorage.Remotes.CommF_:InvokeServer("BuyElectricClaw") end)
        if not V1StyleLookup.EquipByName("Electric Claw") then
            local heroCF = CFrame.new(-10380, 332, -10130)
            local mansionCF = CFrame.new(-12548, 332.38, -7617)
            if not IS.StartedElectricClawRun then
                if (hrp.Position - heroCF.Position).Magnitude > 12 then
                    CurrentFarmStatus = "[Mở Khóa Electric Claw] Đang bay tới Previous Hero nhận thử thách chạy về Mansion..."
                    TweenTo(heroCF)
                    return true
                else
                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("BuyElectricClaw", "Start")
                    end)
                    IS.StartedElectricClawRun = tick()
                    return true
                end
            else
                if (hrp.Position - mansionCF.Position).Magnitude > 20 and (tick() - IS.StartedElectricClawRun < 25) then
                    CurrentFarmStatus = "[Mở Khóa Electric Claw] 🏃 Đang chạy tốc độ về Mansion hoàn thành thử thách Previous Hero..."
                    TweenTo(mansionCF)
                    return true
                else
                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("BuyElectricClaw")
                    end)
                    IS.StartedElectricClawRun = nil
                    IS.ElectricClawQuestDone = true
                end
            end
        else
            IS.ElectricClawQuestDone = true
        end
    end

    -- 4. Dragon Talon: Cần quay Xương (Bones) lấy Fire Essence nộp cho Uzoth (Sea 3)
    if sName == "Dragon Talon" and (World3 or CurrentSeaNum == 3) and not IS.DragonTalonEssenceDone then
        local uzothCF = CFrame.new(-9515.6, 399.7, 5543.2)
        local hasEssence = IS.HasToolOnPlayer("Fire Essence")
        if hasEssence then
            if (hrp.Position - uzothCF.Position).Magnitude > 12 then
                CurrentFarmStatus = "[Mở Khóa Dragon Talon] 🔥 Đang bay tới Uzoth để nộp Fire Essence..."
                TweenTo(uzothCF)
                return true
            else
                if getgenv().StopTween then getgenv().StopTween() end
                hrp.CFrame = uzothCF
                CurrentFarmStatus = "[Mở Khóa Dragon Talon] 🔥 Đang nộp Fire Essence cho Uzoth..."
                IS.EquipToolByName("Fire Essence")
                task.wait(0.2)
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("BuyDragonTalon", true)
                end)
                task.wait(0.25)
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("BuyDragonTalon")
                end)
                task.wait(0.4)
                if not IS.HasToolOnPlayer("Fire Essence") or (V1StyleLookup.FindMeleeTool and V1StyleLookup.FindMeleeTool("Dragon Talon") ~= nil) then
                    IS.DragonTalonEssenceDone = true
                    getgenv().Z9_DragonTalonUnlocked = true
                    MeleeStorage.Save(true)
                end
                return true
            end
        else
            -- Nếu đã sở hữu hoặc từng có Mastery của Dragon Talon -> Fire Essence đã nộp từ lâu!
            if V1StyleLookup.FindMeleeTool("Dragon Talon")
                or (V1StyleLookup.BoughtStyles and V1StyleLookup.BoughtStyles["Dragon Talon"])
                or (V1StyleLookup.MasteredV2 and V1StyleLookup.MasteredV2["Dragon Talon"])
                or (V1StyleLookup.RecordsV2 and (V1StyleLookup.RecordsV2["Dragon Talon"] or 0) > 0) then
                IS.DragonTalonEssenceDone = true
                getgenv().Z9_DragonTalonUnlocked = true
                MeleeStorage.Save()
                return false
            end

            -- [CHECK HẾT LƯỢT RANDOM XƯƠNG]:
            -- Nếu đang trong thời gian hồi lượt quay Death King -> Tạm dừng farm xương, nhường quyền đi Farm Cấp!
            local isOnCd, cdSec = IS.IsBonesOnCooldown()
            if isOnCd then
                return false
            end

            local boneCount = IS.GetCount("Bones")
            if boneCount >= 50 then
                local deathKingCF = CFrame.new(-9516.99, 172.02, 6078.47)
                if (hrp.Position - deathKingCF.Position).Magnitude > 15 then
                    CurrentFarmStatus = "[Mở Khóa Dragon Talon] 🔥 Đã có " .. tostring(boneCount) .. " Bones -> Đang bay tới Death King để quay Fire Essence..."
                    TweenTo(deathKingCF)
                    return true
                end

                if getgenv().StopTween then getgenv().StopTween() end
                hrp.CFrame = deathKingCF
                CurrentFarmStatus = "[Mở Khóa Dragon Talon] Đang quay Xương tại Death King tìm Fire Essence (" .. tostring(boneCount) .. " Bones)..."
                local prevBones = boneCount
                local buyRes = nil
                pcall(function()
                    buyRes = ReplicatedStorage.Remotes.CommF_:InvokeServer("Bones", "Buy", 1, 1)
                end)
                task.wait(0.4)
                IS.RefreshInventory(false)
                if IS.HasToolOnPlayer("Fire Essence") then
                    CurrentFarmStatus = "[Mở Khóa Dragon Talon] 🔥 QUAY RA FIRE ESSENCE! Đang bay gấp tới Uzoth để nộp..."
                    TweenTo(uzothCF)
                    return true
                end

                local afterBones = IS.GetCount("Bones")
                if afterBones < prevBones then
                    -- Quay thành công (đã bị trừ 50 xương)! Chắc chắn KHÔNG bị cooldown!
                    IS.BonesCooldownUntil = 0
                    return true
                else
                    -- Không bị trừ xương -> Kiểm tra xem có thực sự hết lượt quay từ Server hay không
                    IS.CheckBonesCooldownFromServer(buyRes)
                    if IS.IsBonesOnCooldown() then
                        return false -- Hết lượt rồi, chuyển ngay sang Farm Cấp!
                    end
                end
                return true
            end

            local boneQuest = nil
            local boneWaitCF = CFrame.new(-8763.72, 165.72, 6159.86)
            if curLv >= 2050 then
                boneQuest = { Name = "HauntedQuest2", Id = 2, Lv = 2050, NpcCF = CFrame.new(-9516.99, 172.02, 6078.47) }
                boneWaitCF = CFrame.new(-9582.02, 6.25, 6205.48)
            elseif curLv >= 2025 then
                boneQuest = { Name = "HauntedQuest2", Id = 1, Lv = 2025, NpcCF = CFrame.new(-9516.99, 172.02, 6078.47) }
                boneWaitCF = CFrame.new(-9505.87, 172.10, 6158.99)
            elseif curLv >= 2000 then
                boneQuest = { Name = "HauntedQuest1", Id = 2, Lv = 2000, NpcCF = CFrame.new(-9479.22, 141.22, 5566.09) }
                boneWaitCF = CFrame.new(-10144.13, 138.63, 5838.09)
            elseif curLv >= 1975 then
                boneQuest = { Name = "HauntedQuest1", Id = 1, Lv = 1975, NpcCF = CFrame.new(-9479.22, 141.22, 5566.09) }
                boneWaitCF = CFrame.new(-8763.72, 165.72, 6159.86)
            end

            return IS.AttackMobsByList(
                hrp,
                hum,
                { "Reborn Skeleton", "Living Zombie", "Demonic Soul", "Posessed Mummy" },
                boneWaitCF,
                "[Mở Khóa Dragon Talon - Farm Xương quay Fire Essence (" .. tostring(boneCount) .. "/50 Bones)]",
                boneQuest
            )
        end
    end

    return false
end

function V1StyleLookup.ItemsSystem.IsFarmLeverEnabled()
    if getgenv().SettingFarm and type(getgenv().SettingFarm["Auto Pull Lever"]) == "table" then
        local apl = getgenv().SettingFarm["Auto Pull Lever"]
        if apl["Farm Lever"] ~= nil then
            return apl["Farm Lever"] == true
        end
        if apl["FarmLever"] ~= nil then
            return apl["FarmLever"] == true
        end
    end
    return false
end

function V1StyleLookup.ItemsSystem.IsFullMoon()
    local lighting = game:GetService("Lighting")
    local sky = lighting and lighting:FindFirstChildOfClass("Sky")
    if not sky or not tostring(sky.MoonTextureId):find("9709149431") then
        return false
    end
    local ct = lighting.ClockTime
    return (ct > 18 or ct < 5)
end

function V1StyleLookup.ItemsSystem.FindAliveMobFromList(mobNames, checkReplicated)
    local enemies = workspace:FindFirstChild("Enemies")
    if enemies then
        for _, m in ipairs(enemies:GetChildren()) do
            local hum = m:FindFirstChildOfClass("Humanoid")
            local hrp = m:FindFirstChild("HumanoidRootPart")
            if hum and hrp and hum.Health > 0 then
                for _, name in ipairs(mobNames) do
                    if m.Name == name or string.find(m.Name, name, 1, true) then
                        return m
                    end
                end
            end
        end
    end
    if checkReplicated then
        for _, m in ipairs(ReplicatedStorage:GetChildren()) do
            if m:IsA("Model") then
                local hum = m:FindFirstChildOfClass("Humanoid")
                local hrp = m:FindFirstChild("HumanoidRootPart")
                if hum and hrp and hum.Health > 0 then
                    for _, name in ipairs(mobNames) do
                        if m.Name == name or string.find(m.Name, name, 1, true) then
                            return m
                        end
                    end
                end
            end
        end
    end
    return nil
end

function V1StyleLookup.ItemsSystem.FindNearestAliveMobFromList(mobNames, refPos)
    local enemies = workspace:FindFirstChild("Enemies")
    if not enemies then return nil end
    local myPos = (typeof(refPos) == "Vector3" and refPos)
        or (typeof(refPos) == "CFrame" and refPos.Position)
        or (refPos and refPos:IsA("BasePart") and refPos.Position)
        or nil
    local bestMob = nil
    local bestDist = math.huge
    for _, m in ipairs(enemies:GetChildren()) do
        local hum = m:FindFirstChildOfClass("Humanoid")
        local hrp = m:FindFirstChild("HumanoidRootPart")
        if hum and hrp and hum.Health > 0 then
            for _, name in ipairs(mobNames) do
                if m.Name == name or string.find(m.Name, name, 1, true) then
                    local dist = myPos and (hrp.Position - myPos).Magnitude or 0
                    if dist < bestDist then
                        bestDist = dist
                        bestMob = m
                    end
                    break
                end
            end
        end
    end
    return bestMob
end

function V1StyleLookup.ItemsSystem.IsActiveBossInCombat()
    local char = plr.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return false end

    -- 1. Boss đã được khóa mục tiêu chiến đấu gần đây (trong vòng 12 giây qua)
    local engaged = getgenv()._activeEngagedBossMob
    if engaged and engaged.Parent then
        local hum = engaged:FindFirstChildOfClass("Humanoid")
        local eHrp = engaged:FindFirstChild("HumanoidRootPart")
        if hum and hum.Health > 0 and eHrp then
            local dist = (hrp.Position - eHrp.Position).Magnitude
            if tick() - (getgenv()._lastBossEngageTick or 0) < 12 or (dist < 350 and hum.Health < hum.MaxHealth) then
                return true, engaged
            end
        end
    end

    -- 2. Đang có quái Boss (MaxHealth >= 30,000 hoặc tên chứa Boss) trong bán kính chiến đấu và đã bị đánh mất máu
    local curTarget = getgenv()._currentTargetMobName
    local enemies = workspace:FindFirstChild("Enemies")
    if enemies then
        for _, m in ipairs(enemies:GetChildren()) do
            local hum = m:FindFirstChildOfClass("Humanoid")
            local mHrp = m:FindFirstChild("HumanoidRootPart")
            if hum and hum.Health > 0 and mHrp then
                local cleanMob = string.lower(StripMobLevelTag(m.Name))
                local isBoss = (hum.MaxHealth >= 30000) or (m.Name:find("Boss") ~= nil) or (AllBossMobs and AllBossMobs[cleanMob] == true)
                if isBoss then
                    local dist = (hrp.Position - mHrp.Position).Magnitude
                    if (dist < 300 and hum.Health < hum.MaxHealth) or (curTarget and (m.Name == curTarget or cleanMob == string.lower(curTarget)) and dist < 200) then
                        getgenv()._activeEngagedBossMob = m
                        getgenv()._lastBossEngageTick = tick()
                        return true, m
                    end
                end
            end
        end
    end

    return false
end
V1StyleLookup.IsActiveBossInCombat = V1StyleLookup.ItemsSystem.IsActiveBossInCombat

function V1StyleLookup.ItemsSystem.IsTrainingMeleeOnHand()
    if not (IsSettingBuyMeleeV1() or IsSettingBuyMeleeV2() or IsSettingGetItem("Godhuman")) then
        return false
    end
    local targetStyle = V1StyleLookup.GetActiveTargetStyle()
    if not targetStyle then
        return false
    end
    local tool = V1StyleLookup.FindMeleeTool(targetStyle.Name)
    return tool ~= nil
end

