function V1StyleLookup.IsSettingBuySea1ShopEnabled()
    if getgenv().SettingFarm then
        local s1 = getgenv().SettingFarm["Buy Sea 1 Shop Items"]
        if s1 == nil then s1 = getgenv().SettingFarm.BuySea1ShopItems end
        if s1 == nil and type(getgenv().SettingFarm["Get Items"]) == "table" then
            s1 = getgenv().SettingFarm["Get Items"]["Sea1ShopItems"]
        end
        if s1 == false or (type(s1) == "table" and s1.Enabled == false) then
            return false
        end
    end
    return true
end

function V1StyleLookup.ItemsSystem.GetMissingSea1ShopItems()
    local IS = V1StyleLookup.ItemsSystem
    local missing = {}
    local totalCost = 0
    for _, item in ipairs(IS.Sea1ShopList or {}) do
        if not IS.HasItem(item.Name) then
            table.insert(missing, item)
            totalCost = totalCost + (item.Cost or 0)
        end
    end
    return missing, totalCost
end

function V1StyleLookup.ItemsSystem.DoBuySea1ShopStep(hrp, hum)
    local IS = V1StyleLookup.ItemsSystem
    if not V1StyleLookup.IsSettingBuySea1ShopEnabled() then return false end
    local curLv = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0
    if curLv < 600 then return false end
    local beli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
    local missing, totalCost = IS.GetMissingSea1ShopItems()
    if #missing == 0 then return false end

    local now = tick()
    getgenv()._lastSea1ShopBuy = getgenv()._lastSea1ShopBuy or 0
    if now - getgenv()._lastSea1ShopBuy < 1.5 then return false end

    for _, item in ipairs(missing) do
        if curLv >= (item.MinLv or 0) and beli >= item.Cost then
            getgenv()._lastSea1ShopBuy = now
            CurrentFarmStatus = string.format("[Shop Sea 1] Đang mua %s ($%s) - Còn thiếu %d vật phẩm...", item.Name, FormatNumber(item.Cost), #missing)
            pcall(function()
                if item.Remote == "BuyItem" then
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("BuyItem", item.Arg or item.Name)
                elseif item.Remote == "BlackCape" then
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("BlackCape")
                else
                    ReplicatedStorage.Remotes.CommF_:InvokeServer(item.Remote, item.Arg)
                end
            end)
            task.wait(0.3)
            IS.RefreshInventory(true)
            return true
        end
    end
    return false
end

function V1StyleLookup.ItemsSystem.NeedsToStayInSea1(curLv)
    local IS = V1StyleLookup.ItemsSystem
    curLv = tonumber(curLv) or 0
    if IS.IsHoldingProtectedItem() then
        return true
    end
    -- 1. Chưa lấy xong Saber ở Sea 1
    if IsSettingGetItem("Saber") and not HasSaberSword() and curLv >= 200 then
        return true
    end
    -- 2. Đã đạt Lv >= 2800 và đang ở Sea 1 để hoàn tất 39/39 Quest Ẩn mở giới hạn Lv 3000
    if curLv >= 2800 and IsSettingGetItem("Secret Quest") and type(IS.SecretQuest39) == "table" and not IS.SecretQuest39.All39ConfirmedDone then
        return true
    end
    -- 3. Đang mở khóa Sư Phụ Võ V1 (Electro / Fishman Karate) ở Sea 1
    if IsSettingBuyMeleeV1() or IsSettingGetItem("Godhuman") then
        local targetStyle, tier = V1StyleLookup.GetActiveTargetStyle()
        if targetStyle and tier == "V1" and not V1StyleLookup.IsStyleOwned(targetStyle.Name) then
            local beli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
            if beli >= (targetStyle.CostBeli or 0) and (targetStyle.Name == "Electro" or targetStyle.Name == "Fishman Karate" or targetStyle.Name == "Black Leg") then
                return true
            end
        end
    end
    -- 4. Nếu đạt Lv >= 600 ở Sea 1: Mua sạch toàn bộ vật phẩm Shop Sea 1 trước khi sang Sea 2
    if V1StyleLookup.IsSettingBuySea1ShopEnabled() and curLv >= 600 and (World1 or CurrentSeaNum == 1) and type(IS.GetMissingSea1ShopItems) == "function" then
        local missing = IS.GetMissingSea1ShopItems()
        if #missing > 0 then
            return true
        end
    end
    return false
end

function V1StyleLookup.ItemsSystem.NeedsToStayInSea2(curLv)
    local IS = V1StyleLookup.ItemsSystem
    curLv = tonumber(curLv) or 0
    if IS.IsHoldingProtectedItem() then
        return true
    end
    -- 1. Đang mở khóa Võ V2 ở Sea 2 (Superhuman / Death Step cần Library Key / Sharkman Karate cần Water Key)
    if IsSettingBuyMeleeV2() or IsSettingGetItem("Godhuman") then
        local targetStyle, tier = V1StyleLookup.GetActiveTargetStyle()
        if targetStyle and tier == "V2" and not V1StyleLookup.FindMeleeTool(targetStyle.Name) and not V1StyleLookup.IsStyleOwned(targetStyle.Name) then
            if targetStyle.Name == "Superhuman" then
                local beli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
                if beli >= (targetStyle.CostBeli or 3000000) then
                    return true
                end
            elseif targetStyle.Name == "Death Step" and not IS.DeathStepDoorOpened and not getgenv().Z9_DeathStepDoorOpened then
                return true
            elseif targetStyle.Name == "Sharkman Karate" and not IS.SharkmanKeySubmitted and not getgenv().Z9_SharkmanKeySubmitted then
                return true
            end
        end
    end
    -- 2. Đang gom nguyên liệu Godhuman thuộc Sea 2 (Magma Ore / Mystic Droplet)
    if (IsSettingGetItem("Godhuman") or IsSettingBuyMeleeV2())
        and V1StyleLookup.IsPreGodhumanMastered()
        and not V1StyleLookup.MasteredV2["Godhuman"]
        and not IS.HasItem("Godhuman") then
        if IS.GetCount("Magma Ore") < 20 or IS.GetCount("Mystic Droplet") < 10 then
            return true
        end
    end
    -- 3. Đang gom 250 Ectoplasm hoặc 1 Dark Fragment ở Sea 2 cho Skull Guitar (khi đã giải xong 5 bước Pipes ở Sea 3)
    if (IsSettingGetItem("Skull Guitar") or IsSettingGetItem("Soul Guitar"))
        and curLv >= 2300
        and not IS.HasItem("Skull Guitar")
        and type(IS.SGProg) == "table"
        and IS.SGProg.Pipes == true then
        if IS.GetCount("Ectoplasm") < 250 or IS.GetCount("Dark Fragment") < 1 then
            return true
        end
    end
    -- 4. Đã đủ 3 kiếm Shisui, Wando, Saddi >= 300 Mastery và $2,000,000 Beli để ghép True Triple Katana tại Sea 2
    if IS.IsTTKEnabled() and not IS.HasItem("True Triple Katana") then
        local all3 = IS.HasItem("Shisui") and IS.GetMastery("Shisui") >= 300
            and IS.HasItem("Wando") and IS.GetMastery("Wando") >= 300
            and IS.HasItem("Saddi") and IS.GetMastery("Saddi") >= 300
        local beli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
        if all3 and beli >= 2000000 then
            return true
        end
    end
    return false
end

function V1StyleLookup.ItemsSystem.AttackMobsByList(hrp, hum, mobNames, waitCF, statusPrefix, questData)
    local IS = V1StyleLookup.ItemsSystem
    local curLv = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0

    -- Kiểm tra nhiệm vụ hiện tại
    local activeQuestTargetMob = nil
    if HasActiveQuest() then
        local qTitle = (GetQuestTitle() or ""):lower()
        local qTxt = (GetQuestText() or ""):lower()
        local fullQ = qTitle .. " " .. qTxt
        if GuideModule and GuideModule.Data and GuideModule.Data.QuestData and GuideModule.Data.QuestData.Task then
            for tName, _ in pairs(GuideModule.Data.QuestData.Task) do
                fullQ = fullQ .. " " .. tostring(tName):lower()
            end
        end

        local matchedAny = (fullQ:gsub("%s+", "") == "")
        if not matchedAny then
            for _, mn in ipairs(mobNames) do
                local mnLow = string.lower(mn)
                if string.find(fullQ, mnLow, 1, true) then
                    matchedAny = true
                    activeQuestTargetMob = mn
                    break
                end
            end
        end

        -- Chỉ hủy nhiệm vụ cũ từ đảo khác nếu KHÔNG khớp quái trong bãi và đã trôi qua ít nhất 8s (tránh hủy nhầm quest vừa nhận)
        local timeSinceStart = tick() - (getgenv()._lastStartQuest or 0)
        if not matchedAny and timeSinceStart > 8.0 then
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("AbandonQuest")
            end)
            ResetQuestSeen()
            task.wait(0.2)
        end
    end

    -- Nếu có thông tin Quest đi kèm và đủ cấp nhận Quest
    if questData and curLv >= (questData.Lv or 0) then
        if not HasActiveQuest() then
            if (hrp.Position - questData.NpcCF.Position).Magnitude > 10 then
                CurrentFarmStatus = statusPrefix .. " Đang bay tới NPC nhận nhiệm vụ..."
                TweenTo(questData.NpcCF)
                return true
            else
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("StartQuest", questData.Name, questData.Id)
                end)
                getgenv()._lastStartQuest = tick()
                getgenv()._lastStartedQuestMob = (questData.Id == 2 and mobNames[2]) or mobNames[1]
                task.wait(0.3)
                return true
            end
        end
    end

    -- KHÓA MỤC TIÊU QUÁI ĐANG ĐÁNH DỞ (TARGET STICKINESS):
    -- Đánh duy nhất 1 con cho đến khi chết hẳn (HP <= 0), không đổi quái giữa chừng và không nhảy bãi lung tung!
    local lockedMob = getgenv()._lockedAttackMob
    local lHum = lockedMob and lockedMob.Parent and lockedMob:FindFirstChildOfClass("Humanoid")
    local lHrp = lockedMob and lockedMob.Parent and lockedMob:FindFirstChild("HumanoidRootPart")

    local targetMob = nil
    if lockedMob and lHum and lHum.Health > 0 and lHrp then
        targetMob = lockedMob
    else
        getgenv()._lockedAttackMob = nil
        -- Ưu tiên tìm đúng con quái trong nhiệm vụ (ví dụ Reborn Skeleton) nếu đang có quest
        if activeQuestTargetMob then
            targetMob = IS.FindNearestAliveMobFromList({ activeQuestTargetMob }, hrp or waitCF)
        end
        if not targetMob then
            targetMob = IS.FindNearestAliveMobFromList(mobNames, hrp or waitCF)
        end
        getgenv()._lockedAttackMob = targetMob
    end

    local tmHum = targetMob and targetMob:FindFirstChildOfClass("Humanoid")
    if targetMob and targetMob:FindFirstChild("HumanoidRootPart") and tmHum and tmHum.Health > 0 then
        getgenv()._currentTargetMobName = targetMob.Name
        CurrentFarmStatus = statusPrefix .. " Đang đánh " .. tostring(targetMob.Name) .. " (HP: " .. math.floor(tmHum.Health) .. ")..."
        DisableMobCollision(targetMob)
        local cleanName = string.lower(StripMobLevelTag(targetMob.Name))
        if not AllBossMobs[cleanName] then
            pcall(function() BringMobs(targetMob) end)
        end
        EnableBuso()
        EquipSelectedWeapon()
        TweenTo(targetMob.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
    else
        getgenv()._lockedAttackMob = nil
        CurrentFarmStatus = statusPrefix .. " Đang chờ quái hồi sinh..."
        TweenTo(waitCF)
    end
    return true
end

-- =========================================================================
-- 1. NHÁNH KHẨN CẤP (URGENT INTERRUPT):
-- Kích hoạt ngay lập tức khi có God's Chalice / Sweet Chalice / Dough King (Mirror Fractal),
-- hoặc Boss rip_indra / Longma / Elite Pirate (Yama & Tushita), hoặc Terrorshark (Shark Anchor)
-- =========================================================================
function V1StyleLookup.ItemsSystem.DoUrgentStep(hrp, hum)
    if getgenv()._isDoingRaidForF or HasSpecialMicrochip() or IsInRaid() then
        return false
    end
    local IS = V1StyleLookup.ItemsSystem
    IS.RefreshInventory(false)
    local curLv = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0

    -- [A] MIRROR FRACTAL (Sea 3: Khi có Dough King, Sweet Chalice, hoặc God's Chalice)
    if IsSettingGetItem("Mirror Fractal") and (World3 or CurrentSeaNum == 3) and not IS.HasItem("Mirror Fractal") then
        -- 1. ƯU TIÊN TIÊU DIỆT BOSS DOUGH KING NẾU ĐÃ XUẤT HIỆN
        local doughKing = IS.FindAliveMobFromList({ "Dough King" }, true)
        local dkHum = doughKing and doughKing:FindFirstChildOfClass("Humanoid")
        if doughKing and doughKing:FindFirstChild("HumanoidRootPart") and dkHum and dkHum.Health > 0 then
            getgenv()._currentTargetMobName = "Dough King"
            CurrentFarmStatus = "[Mirror Fractal] Đang tiêu diệt Boss Dough King [Lv. 2300] lấy Mirror Fractal (HP: " .. math.floor(dkHum.Health) .. ")..."
            DisableMobCollision(doughKing)
            EnableBuso()
            EquipSelectedWeapon()
            TweenTo(doughKing.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
            return true
        end

        -- 1.5. NẾU CÓ BOSS CAKE PRINCE TRONG ĐẤU TRƯỜNG -> HẠ LUÔN ĐỂ LÀM SẠCH ĐẤU TRƯỜNG & RESET CỔNG
        local cakePrince = IS.FindAliveMobFromList({ "Cake Prince" }, true)
        local cpHum = cakePrince and cakePrince:FindFirstChildOfClass("Humanoid")
        if cakePrince and cakePrince:FindFirstChild("HumanoidRootPart") and cpHum and cpHum.Health > 0 then
            getgenv()._currentTargetMobName = "Cake Prince"
            CurrentFarmStatus = "[Boss Cake Prince] Đang hạ Boss Cake Prince dọn sạch đấu trường (HP: " .. math.floor(cpHum.Health) .. ")..."
            DisableMobCollision(cakePrince)
            EnableBuso()
            EquipSelectedWeapon()
            TweenTo(cakePrince.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
            return true
        end

        -- 2. NẾU CÓ GOD'S CHALICE -> ƯU TIÊN ĐỔI NGAY SANG SWEET CHALICE (KHÔNG ĐƯỢC CHỜ ĐẾN 500 QUÁI MỚI ĐỔI)
        if IS.HasToolOnPlayer("God's Chalice") then
            local cocoaCount = IS.GetCount("Conjured Cocoa")
            if cocoaCount >= 10 then
                local sweetCrafter = (workspace:FindFirstChild("NPCs") and workspace.NPCs:FindFirstChild("Sweet Crafter"))
                    or workspace:FindFirstChild("Sweet Crafter", true)
                local scCF = (sweetCrafter and (sweetCrafter:FindFirstChild("HumanoidRootPart") or sweetCrafter:FindFirstChild("Head") or sweetCrafter:FindFirstChildWhichIsA("BasePart")) and (sweetCrafter:FindFirstChild("HumanoidRootPart") or sweetCrafter:FindFirstChild("Head") or sweetCrafter:FindFirstChildWhichIsA("BasePart")).CFrame)
                    or CFrame.new(233.2, 29.9, -12201.2)
                local dist = (hrp.Position - scCF.Position).Magnitude
                if dist > 15 then
                    CurrentFarmStatus = "[Mirror Fractal] 🏆 Có God's Chalice + " .. tostring(cocoaCount) .. "/10 Cocoa -> Bay tới Sweet Crafter đổi Sweet Chalice ngay..."
                    TweenTo(scCF * CFrame.new(0, 3, 0))
                    return true
                else
                    if getgenv().StopTween then getgenv().StopTween() end
                    hrp.CFrame = scCF
                    CurrentFarmStatus = "[Mirror Fractal] 🏆 Đang đứng trước Sweet Crafter đổi Sweet Chalice..."
                    local ch = IS.EquipToolByName("God's Chalice")
                    if not ch and not IS.HasToolOnPlayer("God's Chalice") then
                        return false
                    end
                    local res = nil
                    pcall(function()
                        res = ReplicatedStorage.Remotes.CommF_:InvokeServer("SweetChaliceNpc")
                    end)
                    task.wait(1)
                    IS.RefreshInventory(true)
                    if res == "Where are the items?" or not IS.HasToolOnPlayer("God's Chalice") then
                        task.wait(0.5)
                        return false
                    end
                    return true
                end
            else
                -- Chưa đủ 10 Cocoa -> Săn Cocoa để đủ 10 cái đổi chén
                return IS.AttackMobsByList(
                    hrp,
                    hum,
                    { "Cocoa Warrior", "Chocolate Bar Battler" },
                    CFrame.new(233, 25, -12199),
                    "[Mirror Fractal - Săn Cocoa (" .. tostring(cocoaCount) .. "/10) bảo vệ God's Chalice]",
                    nil
                )
            end
        end

        -- 3. NẾU ĐÃ CÓ SWEET CHALICE -> CHECK TIẾN TRÌNH CỔNG 500 QUÁI & MỞ CỔNG TRIỆU HỒI DOUGH KING
        if IS.HasToolOnPlayer("Sweet Chalice") then
            local now = tick()
            if now - (IS.LastSpawnerCheck or 0) >= 3.0 then
                IS.LastSpawnerCheck = now
                pcall(function()
                    local res = ReplicatedStorage.Remotes.CommF_:InvokeServer("CakePrinceSpawner")
                    IS.LastCakePrinceSpawnerMsg = res
                end)
            end

            local spawnerMsg = tostring(IS.LastCakePrinceSpawnerMsg or "")
            local enemiesLeft = nil
            if tonumber(IS.LastCakePrinceSpawnerMsg) then
                enemiesLeft = tonumber(IS.LastCakePrinceSpawnerMsg)
            else
                local num = string.match(spawnerMsg, "(%d+)")
                if num then
                    enemiesLeft = tonumber(num)
                end
            end

            local isPortalReady = false
            if enemiesLeft and enemiesLeft <= 0 then
                isPortalReady = true
            elseif string.find(string.lower(spawnerMsg), "open") or string.find(string.lower(spawnerMsg), "ready") or string.find(string.lower(spawnerMsg), "want to open") then
                isPortalReady = true
            end

            -- Vị trí drip_mama tại Đảo Bánh (Cake Land)
            local dripMama = (workspace:FindFirstChild("NPCs") and workspace.NPCs:FindFirstChild("drip_mama"))
                or workspace:FindFirstChild("drip_mama", true)
            local dmCF = (dripMama and (dripMama:FindFirstChild("HumanoidRootPart") or dripMama:FindFirstChild("Head") or dripMama:FindFirstChildWhichIsA("BasePart")) and (dripMama:FindFirstChild("HumanoidRootPart") or dripMama:FindFirstChild("Head") or dripMama:FindFirstChildWhichIsA("BasePart")).CFrame)
                or CFrame.new(-2021, 38, -12028)

            -- [3.1] NẾU CỔNG ĐÃ ĐỦ 500 QUÁI HOẶC SẴN SÀNG MỞ:
            if isPortalReady then
                local dist = (hrp.Position - dmCF.Position).Magnitude
                if dist > 15 then
                    CurrentFarmStatus = "[Mirror Fractal] 👑 Đã đủ 500 quái! Đang bay tới drip_mama cầm Sweet Chalice mở cổng Dough King..."
                    TweenTo(dmCF * CFrame.new(0, 3, 0))
                    return true
                else
                    if getgenv().StopTween then getgenv().StopTween() end
                    hrp.CFrame = dmCF
                    CurrentFarmStatus = "[Mirror Fractal] 👑 Đang mở cổng triệu hồi Boss Dough King bằng Sweet Chalice..."
                    local sw = IS.EquipToolByName("Sweet Chalice")
                    if not sw and not IS.HasToolOnPlayer("Sweet Chalice") then
                        return false
                    end
                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("CakePrinceSpawner", true)
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("CakePrinceSpawner")
                    end)
                    task.wait(1.5)
                    return true
                end
            end

            -- [3.2] NẾU CHƯA ĐỦ 500 QUÁI -> TIẾP TỤC FARM QUÁI ĐẢO BÁNH:
            -- Nếu quái còn lại <= 15: Cầm sẵn Sweet Chalice trên tay để khi đạt 500 quái là mở cổng Dough King ngay, không bị tự mở nhầm Cake Prince!
            if enemiesLeft and enemiesLeft <= 15 then
                IS.EquipToolByName("Sweet Chalice")
            end

            local killStatus = ""
            if enemiesLeft then
                killStatus = " (Còn: " .. tostring(enemiesLeft) .. " | Đã diệt: " .. tostring(math.max(0, 500 - enemiesLeft)) .. "/500)"
            end

            return IS.AttackMobsByList(
                hrp,
                hum,
                { "Cookie Crafter", "Cake Guard", "Baking Staff", "Head Baker" },
                CFrame.new(-2077, 252, -12373),
                "[Mirror Fractal - Sweet Chalice]" .. killStatus,
                { Name = "CakeQuest1", Id = 1, Lv = 2200, NpcCF = CFrame.new(-2021, 38, -12028) }
            )
        end
    end

    -- [B] CURSED DUAL KATANA - TUSHITA & YAMA (Sea 3: Bắt ngay khi có rip_indra / Longma / Elite Pirate)
    if (IsSettingGetItem("Cursed Dual Katana") or IsSettingGetItem("Yama") or IsSettingGetItem("Tushita")) and (World3 or CurrentSeaNum == 3) then
        -- 1. Tushita (Cấp >= 2000, khi chưa có Tushita)
        if (IsSettingGetItem("Cursed Dual Katana") or IsSettingGetItem("Tushita")) and not IS.HasItem("Tushita") and curLv >= 2000 then
            local now = tick()
            if now - (IS.LastTushitaCheck or 0) >= 8.0 or IS.TushitaProg == nil then
                IS.LastTushitaCheck = now
                pcall(function()
                    IS.TushitaProg = ReplicatedStorage.Remotes.CommF_:InvokeServer("TushitaProgress")
                end)
            end
            local tProg = IS.TushitaProg
            if type(tProg) == "table" and not tProg.OpenedDoor then
                local indra = IS.FindAliveMobFromList({ "rip_indra True Form", "rip_indra" }, true)
                if indra or IS.HasToolOnPlayer("Holy Torch") then
                    if not IS.HasToolOnPlayer("Holy Torch") then
                        CurrentFarmStatus = "[Tushita - CDK] Phát hiện Boss rip_indra! Đang bay vào cổng thác nước Hydra lấy Holy Torch..."
                        local wf = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Waterfall")
                        local secretDoor = wf and wf:FindFirstChild("SecretRoom")
                            and wf.SecretRoom:FindFirstChild("Room")
                            and wf.SecretRoom.Room:FindFirstChild("Door")
                            and wf.SecretRoom.Room.Door:FindFirstChild("Door")
                            and wf.SecretRoom.Room.Door.Door:FindFirstChild("Hitbox")
                        local portalCF = (secretDoor and secretDoor.CFrame) or CFrame.new(5714, 20, 256)
                        TweenTo(portalCF)
                        if (hrp.Position - portalCF.Position).Magnitude <= 12 and secretDoor and firetouchinterest then
                            pcall(function()
                                firetouchinterest(hrp, secretDoor, 0)
                                firetouchinterest(hrp, secretDoor, 1)
                            end)
                        end
                    else
                        IS.EquipToolByName("Holy Torch")
                        local torchFallbackCFs = {
                            CFrame.new(-10752, 417, -9366),
                            CFrame.new(-11672, 334, -9474),
                            CFrame.new(-12132, 521, -10655),
                            CFrame.new(-13336, 486, -6985),
                            CFrame.new(-13489, 332, -7925),
                        }
                        local qTorches = workspace:FindFirstChild("Map")
                            and workspace.Map:FindFirstChild("Turtle")
                            and workspace.Map.Turtle:FindFirstChild("QuestTorches")
                        local torchesArr = (type(tProg.Torches) == "table") and tProg.Torches or {}
                        local nextIdx = nil
                        for i = 1, 5 do
                            if not torchesArr[i] then
                                nextIdx = i
                                break
                            end
                        end
                        nextIdx = nextIdx or ((IS.CurrentTorchIdx or 0) % 5 + 1)
                        IS.CurrentTorchIdx = nextIdx
                        local torchPart = qTorches and qTorches:FindFirstChild("Torch" .. tostring(nextIdx))
                        local tCF = (torchPart and torchPart:IsA("BasePart") and torchPart.CFrame) or torchFallbackCFs[nextIdx]
                        CurrentFarmStatus = "[Tushita - CDK] 🔥 Đang cầm Holy Torch thắp ngọn đuốc số " .. tostring(nextIdx) .. "/5 trên đảo Rùa..."
                        if (hrp.Position - tCF.Position).Magnitude > 8 then
                            TweenTo(tCF)
                        else
                            if torchPart and firetouchinterest then
                                pcall(function()
                                    firetouchinterest(hrp, torchPart, 0)
                                    firetouchinterest(hrp, torchPart, 1)
                                end)
                            end
                            pcall(function()
                                ReplicatedStorage.Remotes.CommF_:InvokeServer("TushitaProgress", "Torch", nextIdx)
                            end)
                            IS.CurrentTorchIdx = (nextIdx % 5) + 1
                            IS.TushitaProg = nil
                            task.wait(0.4)
                        end
                    end
                    return true
                end
            elseif type(tProg) == "table" and tProg.OpenedDoor then
                local longma = IS.FindAliveMobFromList({ "Longma" }, true)
                local lmHum = longma and longma:FindFirstChildOfClass("Humanoid")
                if longma and longma:FindFirstChild("HumanoidRootPart") and lmHum and lmHum.Health > 0 then
                    IS.LongmaArriveTick = nil
                    getgenv()._currentTargetMobName = "Longma"
                    CurrentFarmStatus = "[Tushita - CDK] Đang tiêu diệt Boss Longma [Lv. 2000] lấy kiếm Tushita (HP: " .. math.floor(lmHum.Health) .. ")..."
                    DisableMobCollision(longma)
                    EnableBuso()
                    EquipSelectedWeapon()
                    TweenTo(longma.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
                    return true
                elseif not IS.IsHoldingProtectedItem() then
                    local longmaRoomCF = CFrame.new(-10238, 389, -9549)
                    if (hrp.Position - longmaRoomCF.Position).Magnitude > 25 then
                        IS.LongmaArriveTick = nil
                        CurrentFarmStatus = "[Tushita - CDK] Đã mở cửa hầm Longma -> Đang bay tới phòng Boss Longma kiểm tra..."
                        TweenTo(longmaRoomCF)
                        return true
                    else
                        IS.LongmaArriveTick = IS.LongmaArriveTick or tick()
                        if tick() - IS.LongmaArriveTick >= 3.5 then
                            IS.LongmaArriveTick = tick()
                            if IsAutoHopEnabled() and HopServer then
                                HopServer("Boss Longma chưa hồi sinh -> Đang đổi server lấy kiếm Tushita...")
                                return true
                            end
                        else
                            CurrentFarmStatus = "[Tushita - CDK] Đang kiểm tra Boss Longma trong phòng..."
                            return true
                        end
                    end
                end
            end
        end

        -- 2. Yama (Săn Elite Pirate khi xuất hiện, hoặc rút kiếm Yama khi đủ >= 30 Elite)
        if not IS.HasItem("Yama") then
            local now = tick()
            -- Cập nhật tiến trình số lượng Elite đã diệt từ server mỗi 10s
            if now - (IS.LastEliteCheck or 0) >= 10.0 or IS.EliteCount == nil then
                IS.LastEliteCheck = now
                pcall(function()
                    local prog = ReplicatedStorage.Remotes.CommF_:InvokeServer("EliteHunter", "Progress")
                    if tonumber(prog) then
                        IS.EliteCount = tonumber(prog)
                    end
                end)
            end

            -- [2.1] NẾU ĐÃ ĐỦ >= 30 ELITE -> XUỐNG THÁC NƯỚC HYDRA RÚT KIẾM YAMA
            if (IS.EliteCount or 0) >= 30 then
                -- Kiểm tra lại: nếu người chơi đã có Yama trong túi đồ / kho đồ -> Không đi rút nữa
                if IS.HasItem("Yama") then
                    return false
                end
                local wf = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Waterfall")
                local katana = wf and wf:FindFirstChild("SealedKatana")
                if not katana then
                    -- Không còn SealedKatana trên bàn thờ -> Kiếm đã được rút hoặc đã sở hữu!
                    IS.CachedOwnedWeapons["Yama"] = { Count = 1, Mastery = 0, Type = "Sword" }
                    IS.InvMap["Yama"] = IS.CachedOwnedWeapons["Yama"]
                    pcall(function() ReplicatedStorage.Remotes.CommF_:InvokeServer("LoadItem", "Yama") end)
                    return false
                end

                CurrentFarmStatus = "[Yama] Đã đủ " .. tostring(IS.EliteCount) .. "/30 Elite Pirate -> Đang xuống thác nước Hydra rút kiếm Yama..."
                local hitbox = katana and (katana:FindFirstChild("Hitbox") or katana:FindFirstChild("Handle") or katana:FindFirstChildWhichIsA("BasePart"))
                local cd = (hitbox and hitbox:FindFirstChildOfClass("ClickDetector"))
                    or (katana and katana:FindFirstChildWhichIsA("ClickDetector", true))
                local targetCF = (hitbox and hitbox.CFrame) or CFrame.new(5251.9, 17.18, 453.6)
                if (hrp.Position - targetCF.Position).Magnitude > 12 then
                    TweenTo(targetCF)
                else
                    if getgenv().StopTween then getgenv().StopTween() end
                    hrp.CFrame = targetCF
                    -- Tiêu diệt mob Ghost nếu có quấy rối trước bàn thờ
                    local ghostMob = IS.FindAliveMobFromList({ "Ghost" }, true)
                    if ghostMob and ghostMob:FindFirstChild("HumanoidRootPart") and (ghostMob.HumanoidRootPart.Position - hrp.Position).Magnitude <= 30 then
                        DisableMobCollision(ghostMob)
                        EnableBuso()
                        EquipSelectedWeapon()
                        TweenTo(ghostMob.HumanoidRootPart.CFrame * CFrame.new(0, 15, 0))
                        return true
                    end
                    -- Rút kiếm Yama: click 4 lần
                    if cd and fireclickdetector then
                        for _ = 1, 4 do
                            pcall(function() fireclickdetector(cd) end)
                            task.wait(0.4)
                        end
                    end
                    task.wait(0.5)
                    pcall(function() ReplicatedStorage.Remotes.CommF_:InvokeServer("LoadItem", "Yama") end)
                    IS.RefreshInventory(true)
                    if IS.HasItem("Yama") then
                        return false
                    end
                end
                return true
            else
                -- [2.2] NẾU CHƯA ĐỦ 30 ELITE -> KIỂM TRA XEM CÓ ELITE PIRATE ĐANG XUẤT HIỆN HAY KHÔNG
                local eliteMob = IS.FindAliveMobFromList({ "Diablo", "Deandre", "Urban" }, true)

                -- Định kỳ 12s gọi remote EliteHunter để nhận quest hoặc lấy thông tin đảo
                if now - (IS.LastEliteHunterCall or 0) >= 12.0 then
                    IS.LastEliteHunterCall = now
                    pcall(function()
                        local msg = ReplicatedStorage.Remotes.CommF_:InvokeServer("EliteHunter")
                        if type(msg) == "string" then
                            IS.LastEliteHunterMsg = msg
                        end
                    end)
                end

                local questGui = plr:FindFirstChild("PlayerGui")
                    and plr.PlayerGui:FindFirstChild("Main")
                    and plr.PlayerGui.Main:FindFirstChild("Quest")
                local hasEliteQuest = false
                if questGui and questGui.Visible and questGui:FindFirstChild("Container") then
                    pcall(function()
                        local qTitle = questGui.Container.QuestTitle.Title.Text
                        if string.find(qTitle, "Diablo") or string.find(qTitle, "Deandre") or string.find(qTitle, "Urban") then
                            hasEliteQuest = true
                        end
                    end)
                end

                -- Có Elite còn sống trên bản đồ
                local elHum = eliteMob and eliteMob:FindFirstChildOfClass("Humanoid")
                if eliteMob and eliteMob:FindFirstChild("HumanoidRootPart") and elHum and elHum.Health > 0 then
                    if not hasEliteQuest then
                        pcall(function()
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("EliteHunter")
                        end)
                    end
                    getgenv()._currentTargetMobName = eliteMob.Name
                    CurrentFarmStatus = "[Yama - Elite] ⚔️ Đang săn Elite Pirate " .. tostring(eliteMob.Name) .. " (" .. tostring(IS.EliteCount or 0) .. "/30)..."
                    DisableMobCollision(eliteMob)
                    EnableBuso()
                    EquipSelectedWeapon()
                    TweenTo(eliteMob.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
                    return true
                elseif hasEliteQuest or (IS.LastEliteHunterMsg and not string.find(IS.LastEliteHunterMsg, "Come back later") and not string.find(IS.LastEliteHunterMsg, "anything")) then
                    -- Elite đã spawn nhưng ở đảo khác chưa kịp stream vào workspace -> Bay tới đảo được chỉ định
                    local islandSpots = {
                        ["Port Town"] = CFrame.new(-290, 44, 5580),
                        ["Hydra"]     = CFrame.new(5228, 604, 345),
                        ["Turtle"]    = CFrame.new(-13274, 332, -7644),
                        ["Tree"]      = CFrame.new(2173, 29, -6741),
                    }
                    local targetIslandCF = nil
                    if IS.LastEliteHunterMsg then
                        for name, cf in pairs(islandSpots) do
                            if string.find(IS.LastEliteHunterMsg, name) then
                                targetIslandCF = cf
                                break
                            end
                        end
                    end
                    targetIslandCF = targetIslandCF or CFrame.new(-290, 44, 5580)
                    CurrentFarmStatus = "[Yama - Elite] 🧭 Đang bay tới đảo tìm Elite Pirate (" .. tostring(IS.EliteCount or 0) .. "/30)..."
                    TweenTo(targetIslandCF)
                    return true
                end

                -- KHÔNG CÓ ELITE NÀO ĐANG XUẤT HIỆN:
                -- Hoàn toàn không chặn luồng -> Để script tự động tiếp tục farm cấp / farm mastery bình thường!
            end
        end
    end

    -- [C] SHARK ANCHOR (Sea 3: Nếu Terrorshark đang xuất hiện trên biển, hoặc đang tuần tra biển lấy nguyên liệu Shark Anchor -> Đánh ngay!)
    if IsSettingGetItem("Shark Anchor") and (World3 or CurrentSeaNum == 3) and not IS.HasItem("Shark Anchor") then
        local terror = IS.FindAliveMobFromList({ "Terrorshark" }, false)
        local trHum = terror and terror:FindFirstChildOfClass("Humanoid")
        if terror and terror:FindFirstChild("HumanoidRootPart") and trHum and trHum.Health > 0 then
            getgenv()._currentTargetMobName = "Terrorshark"
            CurrentFarmStatus = "[Shark Anchor] ⚓ Đang tiêu diệt Terrorshark [Lv. 2000] (HP: " .. math.floor(trHum.Health) .. ")..."
            DisableMobCollision(terror)
            EnableBuso()
            EquipSelectedWeapon()
            TweenTo(terror.HumanoidRootPart.CFrame * CFrame.new(0, 35, 0))
            return true
        elseif IS.IsFarmingSharkAnchorSea then
            local seaMob = IS.FindAliveMobFromList({ "Shark", "Piranha", "Fish Crew Member", "Haunted Crew Member" }, false)
            local smHum = seaMob and seaMob:FindFirstChildOfClass("Humanoid")
            if seaMob and seaMob:FindFirstChild("HumanoidRootPart") and smHum and smHum.Health > 0 and (seaMob.HumanoidRootPart.Position - hrp.Position).Magnitude <= 900 then
                getgenv()._currentTargetMobName = seaMob.Name
                CurrentFarmStatus = "[Shark Anchor - Nguyên Liệu Biển] 🦈 Đang tiêu diệt " .. tostring(seaMob.Name) .. " thu thập Shark Tooth & Electric Wing..."
                DisableMobCollision(seaMob)
                EnableBuso()
                EquipSelectedWeapon()
                TweenTo(seaMob.HumanoidRootPart.CFrame * CFrame.new(0, 22, 0))
                return true
            end
        end
    end

    -- [D] KÍCH HOẠT NGAY CÁC VẬT PHẨM CHÌA KHÓA / TINH CHẤT KHI RƠI VÀO TÚI ĐỒ (Fire Essence, Hallow Essence, Library Key, Water Key, Hidden Key, Red Key)
    -- 1. XỬ LÝ FIRE ESSENCE (Tinh chất lửa nộp cho NPC Uzoth tại Haunted Castle để mở khóa vĩnh viễn võ Dragon Talon)
    if (World3 or CurrentSeaNum == 3) and IS.HasToolOnPlayer("Fire Essence") then
        local uzothCF = CFrame.new(-9515.6, 399.7, 5543.2)
        local distToUzoth = (hrp.Position - uzothCF.Position).Magnitude
        if distToUzoth > 15 then
            if distToUzoth > 400 then LoadIslandByFakePoint(uzothCF) end
            CurrentFarmStatus = "[Dragon Talon] 🔥 Đã có Fire Essence! Đang bay gấp tới NPC Uzoth (-9515, 400, 5543) để nộp mở khóa..."
            TweenTo(uzothCF)
            return true
        else
            if getgenv().StopTween then getgenv().StopTween() end
            hrp.CFrame = uzothCF
            CurrentFarmStatus = "[Dragon Talon] 🔥 Đang đứng trước Uzoth nộp Fire Essence mở khóa Dragon Talon..."
            IS.EquipToolByName("Fire Essence")
            task.wait(0.2)
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("BuyDragonTalon", true)
            end)
            task.wait(0.25)
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("BuyDragonTalon")
            end)
            task.wait(0.4)
            local stillHasEssence = IS.HasToolOnPlayer("Fire Essence")
            if not stillHasEssence or (V1StyleLookup.FindMeleeTool and V1StyleLookup.FindMeleeTool("Dragon Talon") ~= nil) then
                IS.DragonTalonEssenceDone = true
                getgenv().Z9_DragonTalonUnlocked = true
                MeleeStorage.Save(true)
                CurrentFarmStatus = "[Dragon Talon] ✅ Đã nộp thành công Fire Essence cho Uzoth! Tiếp tục farm..."
                pcall(function() hum:UnequipTools() end)
                EquipSelectedWeapon()
                task.wait(0.5)
                return false
            end
            return true
        end
    end

    -- 2. XỬ LÝ WATER KEY (Chìa khóa nộp cho Sharkman Teacher / Daigrock tại Forgotten Island để mở khóa Sharkman Karate)
    if (World2 or CurrentSeaNum == 2) and not IS.SharkmanKeySubmitted and IS.HasToolOnPlayer("Water Key") then
        local daigrockCF = CFrame.new(-2463.3, 73.4, -3203.2)
        local distToDaigrock = (hrp.Position - daigrockCF.Position).Magnitude
        if distToDaigrock > 15 then
            if distToDaigrock > 400 then LoadIslandByFakePoint(daigrockCF) end
            CurrentFarmStatus = "[Sharkman Karate] 🔑 Phát hiện Water Key -> Đang bay tới Daigrock để nộp..."
            TweenTo(daigrockCF)
            return true
        else
            if getgenv().StopTween then getgenv().StopTween() end
            hrp.CFrame = daigrockCF
            CurrentFarmStatus = "[Sharkman Karate] 🔑 Đang nộp Water Key cho Daigrock mở khóa..."
            IS.EquipToolByName("Water Key")
            task.wait(0.2)
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("BuySharkmanKarate", true)
                ReplicatedStorage.Remotes.CommF_:InvokeServer("BuySharkmanKarate")
            end)
            task.wait(0.4)
            local stillHasKey = IS.HasToolOnPlayer("Water Key")
            if not stillHasKey or (V1StyleLookup.FindMeleeTool and V1StyleLookup.FindMeleeTool("Sharkman Karate") ~= nil) then
                IS.SharkmanKeySubmitted = true
                getgenv().Z9_SharkmanKeySubmitted = true
                MeleeStorage.Save(true)
                pcall(function() hum:UnequipTools() end)
                EquipSelectedWeapon()
                task.wait(0.5)
                return false
            end
            return true
        end
    end

    -- 1. XỬ LÝ LIBRARY KEY (Chìa khóa mở vĩnh viễn cửa thư viện Phoeyu - Death Step tại Ice Castle - Sea 2)
    local hasLibKey = IS.HasToolOnPlayer("Library Key")
    local isDoorAlreadyOpen = IS.DeathStepDoorOpened or getgenv().Z9_DeathStepDoorOpened == true
    local libDoorModel = workspace:FindFirstChild("Map")
        and workspace.Map:FindFirstChild("IceCastle")
        and workspace.Map.IceCastle:FindFirstChild("Hall")
        and workspace.Map.IceCastle.Hall:FindFirstChild("LibraryDoor")

    if libDoorModel and not libDoorModel:FindFirstChild("PhoeyuDoor") then
        isDoorAlreadyOpen = true
        IS.DeathStepDoorOpened = true
        getgenv().Z9_DeathStepDoorOpened = true
    end

    if isDoorAlreadyOpen and hasLibKey then
        pcall(function() hum:UnequipTools() end)
        EquipSelectedWeapon()
        hasLibKey = false
    end

    if (World2 or CurrentSeaNum == 2) and not isDoorAlreadyOpen and hasLibKey then
        local phoeyuDoor = libDoorModel and libDoorModel:FindFirstChild("PhoeyuDoor")
        local libDoorCF = (phoeyuDoor and phoeyuDoor.CFrame)
            or (libDoorModel and libDoorModel:FindFirstChildWhichIsA("BasePart") and libDoorModel:FindFirstChildWhichIsA("BasePart").CFrame)
            or CFrame.new(6371.20, 296.63, -6841.18)

        local distToDoor = (hrp.Position - libDoorCF.Position).Magnitude
        IS.EquipToolByName("Library Key")

        if distToDoor > 15 then
            if distToDoor > 400 then LoadIslandByFakePoint(libDoorCF) end
            CurrentFarmStatus = "[Death Step] 🔑 Phát hiện Library Key -> Đang bay tới mở vĩnh viễn cửa phòng Phoeyu..."
            TweenTo(libDoorCF * CFrame.new(0, 0, -2))
            return true
        else
            if getgenv().StopTween then getgenv().StopTween() end
            CurrentFarmStatus = "[Death Step] 🔑 Đang mở khóa vĩnh viễn cửa phòng Phoeyu..."
            IS.EquipToolByName("Library Key")

            local keyTool = (plr.Character and plr.Character:FindFirstChild("Library Key"))
            local keyHandle = keyTool and keyTool:FindFirstChild("Handle")
            for step = -3, 3, 2 do
                hrp.CFrame = libDoorCF * CFrame.new(0, 0, step)
                if phoeyuDoor and firetouchinterest then
                    if keyHandle then
                        pcall(firetouchinterest, keyHandle, phoeyuDoor, 0)
                        task.wait(0.02)
                        pcall(firetouchinterest, keyHandle, phoeyuDoor, 1)
                    end
                    pcall(firetouchinterest, hrp, phoeyuDoor, 0)
                    task.wait(0.02)
                    pcall(firetouchinterest, hrp, phoeyuDoor, 1)
                end
                task.wait(0.08)
            end

            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("BuyDeathStep", true)
            end)

            getgenv()._libDoorTryCount = (getgenv()._libDoorTryCount or 0) + 1
            local keyGone = not IS.HasToolOnPlayer("Library Key")
            local doorGone = libDoorModel and not libDoorModel:FindFirstChild("PhoeyuDoor")
            if keyGone or doorGone or getgenv()._libDoorTryCount >= 8 then
                IS.DeathStepDoorOpened = true
                getgenv().Z9_DeathStepDoorOpened = true
                getgenv()._libDoorTryCount = nil
                pcall(function() hum:UnequipTools() end)
                EquipSelectedWeapon()
                CurrentFarmStatus = "[Death Step] ✅ Đã mở khóa vĩnh viễn cửa phòng Phoeyu! Tiếp tục farm..."
                task.wait(0.3)
                return false
            else
                task.wait(0.2)
                return true
            end
        end
    end

    -- 2. XỬ LÝ HIDDEN KEY (Chìa khóa mở rương bí mật lấy kiếm Rengoku tại Ice Castle - Sea 2)
    local hasHiddenKey = IS.HasToolOnPlayer("Hidden Key")
    if IS.HiddenKeyUsed or IS.HasItem("Rengoku") then
        if hasHiddenKey then
            pcall(function() hum:UnequipTools() end)
            EquipSelectedWeapon()
            hasHiddenKey = false
        end
    end

    if (World2 or CurrentSeaNum == 2) and hasHiddenKey and not IS.HiddenKeyUsed and not IS.HasItem("Rengoku") then
        local rengokuChestCF = CFrame.new(6535.5, 296.8, -6984.5)
        local distToChest = (hrp.Position - rengokuChestCF.Position).Magnitude
        IS.EquipToolByName("Hidden Key")

        if distToChest > 15 then
            if distToChest > 400 then LoadIslandByFakePoint(rengokuChestCF) end
            CurrentFarmStatus = "[Kiếm Rengoku] 🔑 Phát hiện Hidden Key -> Đang bay tới mở rương lấy kiếm Rengoku..."
            TweenTo(rengokuChestCF)
            return true
        else
            if getgenv().StopTween then getgenv().StopTween() end
            CurrentFarmStatus = "[Kiếm Rengoku] 🔑 Đang mở rương lấy kiếm Rengoku..."
            IS.EquipToolByName("Hidden Key")

            local chestModel = workspace:FindFirstChild("Map")
                and workspace.Map:FindFirstChild("IceCastle")
                and (workspace.Map.IceCastle:FindFirstChild("Chest") or workspace.Map.IceCastle:FindFirstChild("SecretChest"))
            local chestPart = chestModel and chestModel:FindFirstChildWhichIsA("BasePart")
            local keyTool = (plr.Character and plr.Character:FindFirstChild("Hidden Key"))
            local keyHandle = keyTool and keyTool:FindFirstChild("Handle")

            for step = -2, 2, 2 do
                hrp.CFrame = rengokuChestCF * CFrame.new(0, 0, step)
                if chestPart and firetouchinterest then
                    if keyHandle then
                        pcall(firetouchinterest, keyHandle, chestPart, 0)
                        task.wait(0.02)
                        pcall(firetouchinterest, keyHandle, chestPart, 1)
                    end
                    pcall(firetouchinterest, hrp, chestPart, 0)
                    task.wait(0.02)
                    pcall(firetouchinterest, hrp, chestPart, 1)
                end
                task.wait(0.08)
            end

            getgenv()._hiddenKeyTryCount = (getgenv()._hiddenKeyTryCount or 0) + 1
            local keyGone = not IS.HasToolOnPlayer("Hidden Key")
            local hasRengoku = IS.HasItem("Rengoku")
            if keyGone or hasRengoku or getgenv()._hiddenKeyTryCount >= 8 then
                IS.HiddenKeyUsed = true
                getgenv().Z9_HiddenKeyUsed = true
                getgenv()._hiddenKeyTryCount = nil
                pcall(function() hum:UnequipTools() end)
                EquipSelectedWeapon()
                CurrentFarmStatus = "[Kiếm Rengoku] ✅ Đã mở rương kiếm Rengoku! Tiếp tục farm..."
                task.wait(0.3)
                return false
            else
                task.wait(0.2)
                return true
            end
        end
    end

    if not IS.RedKeyUsed and IS.HasToolOnPlayer("Red Key") then
        CurrentFarmStatus = "[Raid Dough] 🔑 Phát hiện Red Key -> Đang mở khóa Cake Scientist..."
        local rkTool = IS.EquipToolByName("Red Key")
        pcall(function()
            ReplicatedStorage.Remotes.CommF_:InvokeServer("CakeScientist", "Check")
            if rkTool then rkTool:Destroy() end
        end)
        IS.RedKeyUsed = true
        task.wait(0.5)
        return true
    end

    if (World3 or CurrentSeaNum == 3) and IS.HasToolOnPlayer("Hallow Essence") then
        CurrentFarmStatus = "[Soul Reaper] 💀 Phát hiện Hallow Essence -> Đang bay tới bệ thờ Haunted Castle triệu hồi Boss Soul Reaper..."
        IS.EquipToolByName("Hallow Essence")
        local sumDet = workspace:FindFirstChild("Map")
            and workspace.Map:FindFirstChild("Haunted Castle")
            and workspace.Map["Haunted Castle"]:FindFirstChild("Summoner")
            and workspace.Map["Haunted Castle"].Summoner:FindFirstChild("Detection")
        local targetCF = (sumDet and sumDet.CFrame) or CFrame.new(-8932, 146, 6063)
        TweenTo(targetCF)
        if sumDet and (hrp.Position - sumDet.Position).Magnitude <= 10 and firetouchinterest then
            pcall(function()
                firetouchinterest(hrp, sumDet, 0)
                firetouchinterest(hrp, sumDet, 1)
            end)
        end
        return true
    end

    -- [D.2] MỞ KHÓA TỘC GHOUL (HELLFIRE TORCH + 100 ECTOPLASM) & TỘC CYBORG (CORE BRAIN) TẠI SEA 2
    if (World2 or CurrentSeaNum == 2) then
        -- 1. Khi có Hellfire Torch trong túi đồ -> Nộp cho Experimic mở khóa Tộc Ghoul (nếu thiếu Ectoplasm thì cày đủ 100 Ectoplasm ngay)
        if not IS.GhoulUnlocked and IS.HasToolOnPlayer("Hellfire Torch") then
            local ecto = IS.GetCount("Ectoplasm")
            if ecto >= 100 then
                CurrentFarmStatus = "[Mở Khóa Tộc Ghoul] 🔥 Đã có Hellfire Torch & " .. tostring(ecto) .. "/100 Ectoplasm -> Đang mở khóa Tộc Ghoul..."
                IS.EquipToolByName("Hellfire Torch")
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("Ectoplasm", "Change", 4)
                end)
                IS.GhoulUnlocked = true
                task.wait(0.5)
                return true
            else
                return IS.AttackMobsByList(
                    hrp,
                    hum,
                    { "Ship Deckhand", "Ship Engineer", "Ship Steward", "Ship Officer" },
                    CFrame.new(911, 126, 33159),
                    "[Mở Khóa Tộc Ghoul - Giữ Hellfire Torch & Gom Ectoplasm (" .. tostring(ecto) .. "/100)]",
                    nil
                )
            end
        end

        -- 2. Khi có Core Brain trong túi đồ -> Đưa vào máy Secret Lab mở khóa Tộc Cyborg
        if not IS.CyborgUnlocked and IS.HasToolOnPlayer("Core Brain") then
            CurrentFarmStatus = "[Mở Khóa Tộc Cyborg] 🧠 Đã có Core Brain -> Đang lắp vào máy Secret Lab mở khóa Tộc Cyborg..."
            local labBtn = workspace:FindFirstChild("Map")
                and workspace.Map:FindFirstChild("CircleIsland")
                and workspace.Map.CircleIsland:FindFirstChild("RaidSummon")
                and workspace.Map.CircleIsland.RaidSummon:FindFirstChild("Button")
                and workspace.Map.CircleIsland.RaidSummon.Button:FindFirstChild("Main")
            local targetCF = (labBtn and labBtn.CFrame) or CFrame.new(-5917.27, 29.0, -5096.81)
            if (hrp.Position - targetCF.Position).Magnitude > 10 then
                TweenTo(targetCF)
            else
                IS.EquipToolByName("Core Brain")
                if labBtn then
                    local cd = labBtn:FindFirstChildOfClass("ClickDetector")
                    if cd and fireclickdetector then
                        pcall(function() fireclickdetector(cd) end)
                    end
                end
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("CyborgTrainer", "Buy")
                end)
                IS.CyborgUnlocked = true
                task.wait(0.5)
            end
            return true
        end

        -- 3. Nếu Boss Order (Law Raid) đang sống -> Hạ ngay để lấy Koko, Zebra Cap & Core Brain
        local orderBoss = IS.FindAliveMobFromList({ "Order" }, true)
        local ordHum = orderBoss and orderBoss:FindFirstChildOfClass("Humanoid")
        if orderBoss and orderBoss:FindFirstChild("HumanoidRootPart") and ordHum and ordHum.Health > 0 then
            getgenv()._currentTargetMobName = "Order"
            CurrentFarmStatus = "[Auto Law Raid] Đang tiêu diệt Boss Order [Lv. 1250] lấy Kiếm Koko, Mũ Zebra Cap & Core Brain (HP: " .. math.floor(ordHum.Health) .. ")..."
            DisableMobCollision(orderBoss)
            EnableBuso()
            EquipSelectedWeapon()
            TweenTo(orderBoss.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
            return true
        end

        -- 4. Nếu Boss Cursed Captain đang sống trong Cursed Ship -> Hạ ngay để lấy Hellfire Torch (Tộc Ghoul)
        if not IS.GhoulUnlocked and not IS.HasToolOnPlayer("Hellfire Torch") then
            local cursedCap = IS.FindAliveMobFromList({ "Cursed Captain" }, true)
            local capHum = cursedCap and cursedCap:FindFirstChildOfClass("Humanoid")
            if cursedCap and cursedCap:FindFirstChild("HumanoidRootPart") and capHum and capHum.Health > 0 then
                getgenv()._currentTargetMobName = "Cursed Captain"
                CurrentFarmStatus = "[Mở Khóa Tộc Ghoul] Đang hạ Boss Cursed Captain [Lv. 1325] lấy Hellfire Torch (HP: " .. math.floor(capHum.Health) .. ")..."
                DisableMobCollision(cursedCap)
                EnableBuso()
                EquipSelectedWeapon()
                TweenTo(cursedCap.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
                return true
            end
        end
    end

    -- [E] SĂN DARKBEARD & DÙNG FIST OF DARKNESS (NẠP MÁY CYBORG LAB HOẶC TRIỆU HỒI DARKBEARD TẠI SEA 2)
    if (World2 or CurrentSeaNum == 2) then
        local darkbeard = IS.FindAliveMobFromList({ "Darkbeard" }, true)
        local dbHum = darkbeard and darkbeard:FindFirstChildOfClass("Humanoid")
        if darkbeard and darkbeard:FindFirstChild("HumanoidRootPart") and dbHum and dbHum.Health > 0 then
            getgenv()._currentTargetMobName = "Darkbeard"
            CurrentFarmStatus = "[Dark Fragment] Đang tiêu diệt Boss Darkbeard [Lv. 1000] lấy Dark Fragment (HP: " .. math.floor(dbHum.Health) .. ")..."
            DisableMobCollision(darkbeard)
            EnableBuso()
            EquipSelectedWeapon()
            TweenTo(darkbeard.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
            return true
        end

        if IS.HasToolOnPlayer("Fist of Darkness") then
            -- Nếu đã có Dark Fragment và chưa nạp Fist of Darkness vào máy Cyborg Lab -> Nạp vào máy Cyborg trước!
            if not IS.CyborgFistInserted and IS.GetCount("Dark Fragment") >= 1 then
                local labBtn = workspace:FindFirstChild("Map")
                    and workspace.Map:FindFirstChild("CircleIsland")
                    and workspace.Map.CircleIsland:FindFirstChild("RaidSummon")
                    and workspace.Map.CircleIsland.RaidSummon:FindFirstChild("Button")
                    and workspace.Map.CircleIsland.RaidSummon.Button:FindFirstChild("Main")
                local labCF = (labBtn and labBtn.CFrame) or CFrame.new(-5917.27, 29.0, -5096.81)
                CurrentFarmStatus = "[Mở Khóa Tộc Cyborg] 👊 Đang nạp Fist of Darkness vào máy Secret Lab (Bước 1 Cyborg)..."
                if (hrp.Position - labCF.Position).Magnitude > 10 then
                    TweenTo(labCF)
                    return true
                else
                    if labBtn then
                        local cd = labBtn:FindFirstChildOfClass("ClickDetector")
                        if cd and fireclickdetector then
                            pcall(function() fireclickdetector(cd) end)
                        end
                    end
                    IS.CyborgFistInserted = true
                    task.wait(0.5)
                    if not IS.HasToolOnPlayer("Fist of Darkness") then
                        return true
                    end
                end
            end

            CurrentFarmStatus = "[Dark Fragment] 👊 Đã có Fist of Darkness -> Đang tới Dark Arena triệu hồi Boss Darkbeard..."
            local dbDet = workspace:FindFirstChild("Map")
                and workspace.Map:FindFirstChild("DarkbeardArena")
                and workspace.Map.DarkbeardArena:FindFirstChild("Summoner")
                and workspace.Map.DarkbeardArena.Summoner:FindFirstChild("Detection")
            local targetCF = (dbDet and dbDet.CFrame) or CFrame.new(3777, 15, -3498)
            if (hrp.Position - targetCF.Position).Magnitude > 8 then
                TweenTo(targetCF)
            else
                local fistTool = IS.EquipToolByName("Fist of Darkness")
                if dbDet and firetouchinterest then
                    pcall(function()
                        if fistTool and fistTool:FindFirstChild("Handle") then
                            firetouchinterest(fistTool.Handle, dbDet, 0)
                            firetouchinterest(fistTool.Handle, dbDet, 1)
                        end
                        firetouchinterest(hrp, dbDet, 0)
                        firetouchinterest(hrp, dbDet, 1)
                    end)
                end
            end
            return true
        end
    end

    -- [F] SEA 3: TỰ ĐỘNG BẤM 3 NÚT HAKI & DÙNG GOD'S CHALICE TRIỆU HỒI RIP_INDRA + SĂN CAKE PRINCE / SOUL REAPER
    if (World3 or CurrentSeaNum == 3) then
        -- 1. Nếu có God's Chalice và đã có Mirror Fractal (hoặc đang cần Valkyrie Helm / Tushita) -> Bấm 3 nút Haki & Triệu hồi rip_indra!
        if IS.HasToolOnPlayer("God's Chalice") and (IS.HasItem("Mirror Fractal") or not IsSettingGetItem("Mirror Fractal")) then
            local boatCastle = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Boat Castle")
            local sumFolder = boatCastle and boatCastle:FindFirstChild("Summoner")
            local circleFolder = sumFolder and sumFolder:FindFirstChild("Circle")
            if circleFolder then
                local colorMap = {
                    ["Really red"]          = "Pure Red",
                    ["Bright red"]          = "Pure Red",
                    ["Hot pink"]            = "Winter Sky",
                    ["Magenta"]             = "Winter Sky",
                    ["Institutional white"] = "Snow White",
                    ["White"]               = "Snow White",
                }
                for _, plate in ipairs(circleFolder:GetChildren()) do
                    if plate:IsA("BasePart") then
                        local statusPart = plate:FindFirstChild("Part")
                        local isLit = statusPart and statusPart:IsA("BasePart") and statusPart.BrickColor.Name == "Lime green"
                        local reqColor = colorMap[plate.BrickColor.Name]
                        if not isLit and reqColor and not IS.TriedIndraPlate[reqColor] then
                            CurrentFarmStatus = "[Triệu Hồi rip_indra] 🎨 Đang bật màu Haki (" .. reqColor .. ") & giẫm nút mở khóa tại Castle on the Sea..."
                            pcall(function()
                                ReplicatedStorage.Remotes.CommF_:InvokeServer("activateColor", reqColor)
                            end)
                            EnableBuso()
                            if (hrp.Position - plate.Position).Magnitude > 6 then
                                TweenTo(plate.CFrame)
                            else
                                hrp.CFrame = plate.CFrame
                                if firetouchinterest then
                                    pcall(function()
                                        firetouchinterest(hrp, plate, 0)
                                        firetouchinterest(hrp, plate, 1)
                                    end)
                                end
                                IS.TriedIndraPlate[reqColor] = true
                                task.wait(0.3)
                            end
                            return true
                        end
                    end
                end
            end

            -- Đặt God's Chalice lên bệ thờ Castle on the Sea triệu hồi rip_indra
            local indraDet = sumFolder and sumFolder:FindFirstChild("Detection")
            local pedigreeCF = (indraDet and indraDet.CFrame) or CFrame.new(-5560.4, 314.2, -2664.2)
            CurrentFarmStatus = "[Triệu Hồi rip_indra] 🏆 Đang đặt God's Chalice lên bệ thờ Castle on the Sea triệu hồi Boss rip_indra..."
            if (hrp.Position - pedigreeCF.Position).Magnitude > 8 then
                TweenTo(pedigreeCF)
            else
                local chTool = IS.EquipToolByName("God's Chalice")
                if indraDet and firetouchinterest then
                    pcall(function()
                        if chTool and chTool:FindFirstChild("Handle") then
                            firetouchinterest(chTool.Handle, indraDet, 0)
                            firetouchinterest(chTool.Handle, indraDet, 1)
                        end
                        firetouchinterest(hrp, indraDet, 0)
                        firetouchinterest(hrp, indraDet, 1)
                    end)
                end
            end
            return true
        else
            IS.TriedIndraPlate = {}
        end

        -- 2. Nếu Boss rip_indra đang xuất hiện trên server (và đã xong Holy Torch hoặc chưa có Valkyrie Helm / Dark Dagger) -> Hạ ngay!
        local indraBoss = IS.FindAliveMobFromList({ "rip_indra True Form", "rip_indra" }, true)
        local inHum = indraBoss and indraBoss:FindFirstChildOfClass("Humanoid")
        if indraBoss and indraBoss:FindFirstChild("HumanoidRootPart") and inHum and inHum.Health > 0 then
            getgenv()._currentTargetMobName = indraBoss.Name
            CurrentFarmStatus = "[Boss rip_indra] Đang tiêu diệt Boss " .. tostring(indraBoss.Name) .. " lấy Valkyrie Helm & Dark Dagger (HP: " .. math.floor(inHum.Health) .. ")..."
            DisableMobCollision(indraBoss)
            EnableBuso()
            EquipSelectedWeapon()
            TweenTo(indraBoss.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
            return true
        end

        local cakePrince = IS.FindAliveMobFromList({ "Cake Prince" }, true)
        local cpHum = cakePrince and cakePrince:FindFirstChildOfClass("Humanoid")
        if cakePrince and cakePrince:FindFirstChild("HumanoidRootPart") and cpHum and cpHum.Health > 0 then
            getgenv()._currentTargetMobName = "Cake Prince"
            CurrentFarmStatus = "[Boss Cake Prince] Đang hạ Boss Cake Prince lấy Pale Scarf & Spikey Trident (HP: " .. math.floor(cpHum.Health) .. ")..."
            DisableMobCollision(cakePrince)
            EnableBuso()
            EquipSelectedWeapon()
            TweenTo(cakePrince.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
            return true
        end

        local isYamaTrial3 = (type(IS.CDKProg) == "table" and (tonumber(IS.CDKProg.Evil) == 2 or tonumber(IS.CDKProg.Evil) == -1) and IS.HasItem("Yama") and IS.GetMastery("Yama") >= 350)
        if not isYamaTrial3 then
            local soulReaper = IS.FindAliveMobFromList({ "Soul Reaper" }, true)
            local srHum = soulReaper and soulReaper:FindFirstChildOfClass("Humanoid")
            if soulReaper and soulReaper:FindFirstChild("HumanoidRootPart") and srHum and srHum.Health > 0 then
                getgenv()._currentTargetMobName = "Soul Reaper"
                CurrentFarmStatus = "[Boss Soul Reaper] Đang hạ Boss Soul Reaper lấy Hallow Scythe & Holy Crown (HP: " .. math.floor(srHum.Health) .. ")..."
                DisableMobCollision(soulReaper)
                EnableBuso()
                EquipSelectedWeapon()
                TweenTo(soulReaper.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
                return true
            end
        end
    end

    -- [G] AUTO PULL LEVER (FARM LEVER): KHI ĐẢO BÍ ẨN (MIRAGE ISLAND / MYSTIC ISLAND) XUẤT HIỆN TRÊN SERVER
    if (World3 or CurrentSeaNum == 3) and IS.IsFarmLeverEnabled() and not IS.LeverPulledDone and IS.HasItem("Mirror Fractal") and IS.HasItem("Valkyrie Helm") then
        local mystic = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("MysticIsland")
        if mystic then
            local blueGear = nil
            local highPoint = nil
            for _, d in ipairs(mystic:GetDescendants()) do
                if d:IsA("MeshPart") then
                    if d.MeshId == "rbxassetid://10153114969" then
                        blueGear = d
                    elseif d.MeshId == "rbxassetid://6745037796" then
                        highPoint = d
                    end
                end
            end

            if blueGear and blueGear.Transparency < 1 then
                CurrentFarmStatus = "[Auto Pull Lever] ⚙️ Đã xuất hiện Blue Gear trên đảo Mirage! Đang bay tới nhặt Blue Gear..."
                TweenTo(blueGear.CFrame)
                return true
            elseif highPoint then
                local topCF = highPoint.CFrame * CFrame.new(0, 211.88, 0)
                if (hrp.Position - topCF.Position).Magnitude > 10 then
                    CurrentFarmStatus = "[Auto Pull Lever] 🏝️ Đảo Mirage đang xuất hiện -> Đang bay lên đỉnh cao nhất của Mirage..."
                    TweenTo(topCF)
                    return true
                else
                    local lighting = game:GetService("Lighting")
                    local ct = lighting and lighting.ClockTime or 12
                    if ct > 18 or ct < 5 then
                        CurrentFarmStatus = "[Auto Pull Lever] 🌕 Đang nhìn Trăng & bật Tộc V3 cộng hưởng Mirror Fractal gọi Blue Gear..."
                        pcall(function()
                            local cam = workspace.CurrentCamera
                            if cam and lighting then
                                cam.CFrame = CFrame.new(cam.CFrame.Position, cam.CFrame.Position + lighting:GetMoonDirection())
                            end
                            ReplicatedStorage.Remotes.CommE:FireServer("ActivateAbility")
                            local vim = game:GetService("VirtualInputManager")
                            if vim then
                                vim:SendKeyEvent(true, Enum.KeyCode.T, false, game)
                                task.wait(0.1)
                                vim:SendKeyEvent(false, Enum.KeyCode.T, false, game)
                            end
                        end)
                        return true
                    end
                end
            end
        end
    end

    -- [H] AUTO PIRATE RAID (HẢI TẶC TẤN CÔNG LÂU ĐÀI CASTLE ON THE SEA - SEA 3: LẤY 100 FRAGMENTS & TRÁI ÁC QUỶ)
    local pirateRaidEnabled = true
    if getgenv().SettingFarm then
        local pr = getgenv().SettingFarm["Pirate Raid"]
        if pr == nil then pr = getgenv().SettingFarm.PirateRaid end
        if pr == false or (type(pr) == "table" and pr["Enabled"] == false) then
            pirateRaidEnabled = false
        end
    end
    if pirateRaidEnabled and (World3 or CurrentSeaNum == 3) and not IS.IsHoldingProtectedItem() then
        local castleCenter = Vector3.new(-5543.53, 313.80, -2964.26)

        -- 1. Kiểm tra thông báo trên màn hình để nhận diện trạng thái Pirate Raid (bắt đầu / kết thúc)
        pcall(function()
            local pg = plr:FindFirstChild("PlayerGui")
            local notif = pg and pg:FindFirstChild("Notifications")
            if notif then
                for _, desc in ipairs(notif:GetDescendants()) do
                    if desc:IsA("TextLabel") and desc.Visible and desc.Text ~= "" then
                        local t = string.lower(desc.Text)
                        if t:find("pirates have been spotted") or t:find("hải tặc đang tiến đến") or t:find("pirates are raiding") then
                            IS.IsPirateRaidActive = true
                            IS.LastPirateRaidTick = tick()
                        elseif t:find("pirates have been defeated") or t:find("hải tặc đã bị tiêu diệt") or t:find("raid ended") or t:find("raid over") then
                            IS.IsPirateRaidActive = false
                            IS.LastPirateRaidTick = nil
                        end
                    end
                end
            end
        end)

        -- 2. Quét quái Hải Tặc trong toàn bộ phạm vi đảo Castle on the Sea (bán kính 850 studs)
        local raidMob, bestDist = nil, 850
        local raidCount = 0
        local enemies = workspace:FindFirstChild("Enemies")
        if enemies then
            for _, m in ipairs(enemies:GetChildren()) do
                local mHum = m:FindFirstChildOfClass("Humanoid")
                local mHrp = m:FindFirstChild("HumanoidRootPart")
                if mHum and mHrp and mHum.Health > 0 and m.Name ~= "Training Dummy" then
                    local dCastle = (mHrp.Position - castleCenter).Magnitude
                    if dCastle <= 850 then
                        raidCount = raidCount + 1
                        if dCastle < bestDist then
                            bestDist = dCastle
                            raidMob = m
                        end
                    end
                end
            end
        end

        if raidMob then
            IS.IsPirateRaidActive = true
            IS.LastPirateRaidTick = tick()
            getgenv()._currentTargetMobName = raidMob.Name
            CurrentFarmStatus = "[Pirate Raid] 🏴‍☠️ Đang tiêu diệt Hải Tặc (" .. tostring(raidMob.Name) .. " - Còn " .. tostring(raidCount) .. " con) lấy 100F & Trái Ác Quỷ..."
            DisableMobCollision(raidMob)
            EnableBuso()
            EquipSelectedWeapon()
            pcall(function() BringMobs(raidMob) end)
            TweenTo(raidMob.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
            return true
        elseif (IS.IsPirateRaidActive or (IS.LastPirateRaidTick and (tick() - IS.LastPirateRaidTick < 30.0))) then
            -- Nếu vừa dọn xong 1 đợt nhưng chưa quá 30s: TIẾP TỤC Ở LẠI LÂU ĐÀI CHỜ ĐỢT HẢI TẶC TIẾP THEO (KHÔNG ĐƯỢC BỎ ĐI)!
            local waitTimeLeft = math.max(1, math.ceil(30.0 - (tick() - (IS.LastPirateRaidTick or tick()))))
            CurrentFarmStatus = "[Pirate Raid] 🏴‍☠️ Đang canh giữ Lâu Đài, chờ đợt Hải Tặc tiếp theo (" .. tostring(waitTimeLeft) .. "s)..."
            TweenTo(CFrame.new(castleCenter) * CFrame.new(0, 30, 0))
            return true
        else
            -- Đã quá 30s không còn quái Hải Tặc -> Pirate Raid đã kết thúc
            if IS.IsPirateRaidActive then
                IS.IsPirateRaidActive = false
                IS.LastPirateRaidTick = nil
                pcall(function() IS.RefreshInventory(true) end)
            end
        end
    end

    -- [I] AUTO SĂN BOSS RƠI VŨ KHÍ & PHỤ KIỆN SƯU TẦM (POLE V1, RENGOKU, DRAGON TRIDENT, BUDDY SWORD, CANVANDER, TWIN HOOKS)
    -- Khi đang cày Mastery Kiếm/Súng chủ lực (_targetSwordName ~= nil) -> Tuyệt đối không bay đi săn boss sưu tầm lẻ tẻ để tập trung 100% farm cấp!
    local autoBossDrop = true
    if getgenv().SettingFarm then
        local fbd = getgenv().SettingFarm["Farm Boss Drops"] or getgenv().SettingFarm.FarmBossDrops or getgenv().SettingFarm["Boss Drops"]
        if fbd ~= nil then
            if type(fbd) == "boolean" then
                autoBossDrop = fbd
            elseif type(fbd) == "table" and fbd["Enabled"] ~= nil then
                autoBossDrop = (fbd["Enabled"] == true)
            end
        end
    end
    local isMeleeUnlockInProgress = false
    if type(V1StyleLookup) == "table" and type(V1StyleLookup.GetActiveTargetStyle) == "function" then
        local actStyle = V1StyleLookup.GetActiveTargetStyle()
        if actStyle ~= nil then
            local hasT = (V1StyleLookup.FindMeleeTool and V1StyleLookup.FindMeleeTool(actStyle.Name) ~= nil)
            if not hasT then
                isMeleeUnlockInProgress = true
            end
        end
    end

    if autoBossDrop and not IS.IsHoldingProtectedItem() and not isMeleeUnlockInProgress and not getgenv()._isDoingRaidForF and getgenv()._raidTargetStyle == nil and getgenv()._targetSwordName == nil then
        local bossTargets = nil
        if (World1 or CurrentSeaNum == 1) then
            bossTargets = {
                { Boss = "The Saw", Item = "Shark Saw", MinLv = 100 },
                { Boss = "Wysper", Item = "Bazooka", MinLv = 500 },
                { Boss = "Thunder God", Item = "Pole (1st Form)", MinLv = 575 },
                { Boss = "Cyborg", Item = "Cool Shades", MinLv = 675 },
            }
        elseif (World2 or CurrentSeaNum == 2) then
            bossTargets = {
                { Boss = "Fajita", Item = "Gravity Cane", MinLv = 925 },
                { Boss = "Don Swan", Item = "Swan Glasses", MinLv = 1000 },
                { Boss = "Smoke Admiral", Item = "Jitte", MinLv = 1150 },
                { Boss = "Cursed Captain", Item = "Hellfire Torch", MinLv = 1325 },
                { Boss = "Awakened Ice Admiral", Item = "Rengoku", MinLv = 1400 },
                { Boss = "Tide Keeper", Item = "Dragon Trident", MinLv = 1475 },
            }
        elseif (World3 or CurrentSeaNum == 3) then
            bossTargets = {
                { Boss = "Stone", Item = "Pilot Helmet", MinLv = 1550 },
                { Boss = "Island Empress", Item = "Serpent Bow", MinLv = 1675 },
                { Boss = "Hydra Leader", Item = "Serpent Bow", MinLv = 1675 },
                { Boss = "Kilo Admiral", Item = "Lei", MinLv = 1750 },
                { Boss = "Captain Elephant", Item = "Twin Hooks", MinLv = 1875 },
                { Boss = "Beautiful Pirate", Item = "Canvander", MinLv = 1950 },
                { Boss = "Soul Reaper", Item = "Hallow Scythe", MinLv = 2100 },
                { Boss = "Cake Queen", Item = "Buddy Sword", MinLv = 2175 },
                { Boss = "Cake Prince", Item = "Spikey Trident", MinLv = 2200 },
            }
        end

        if bossTargets then
            local curSeaKey = "Sea " .. tostring(CurrentSeaNum or 1)
            local seaOk = true
            if getgenv().SettingFarm then
                local fbd = getgenv().SettingFarm["Farm Boss Drops"] or getgenv().SettingFarm.FarmBossDrops or getgenv().SettingFarm["Boss Drops"]
                if type(fbd) == "table" and fbd[curSeaKey] ~= nil then
                    seaOk = (fbd[curSeaKey] == true)
                end
            end
            if seaOk then
                for _, bt in ipairs(bossTargets) do
                    local itemOk = true
                    if getgenv().SettingFarm then
                        local fbd = getgenv().SettingFarm["Farm Boss Drops"] or getgenv().SettingFarm.FarmBossDrops or getgenv().SettingFarm["Boss Drops"]
                        if type(fbd) == "table" then
                            if fbd[bt.Item] ~= nil then
                                itemOk = (fbd[bt.Item] == true)
                            elseif bt.Item == "Gravity Cane" and fbd["Gravity Blade"] ~= nil then
                                itemOk = (fbd["Gravity Blade"] == true)
                            elseif bt.Item == "Pole (1st Form)" and fbd["Pole"] ~= nil then
                                itemOk = (fbd["Pole"] == true)
                            end
                        end
                    end
                    if itemOk and curLv >= (bt.MinLv or 0) and not IS.HasItem(bt.Item) then
                    local bMob = IS.FindAliveMobFromList({ bt.Boss }, true)
                    local bmHum = bMob and bMob:FindFirstChildOfClass("Humanoid")
                    if bMob and bMob:FindFirstChild("HumanoidRootPart") and bmHum and bmHum.Health > 0 then
                        getgenv()._currentTargetMobName = bMob.Name
                        getgenv()._activeEngagedBossMob = bMob
                        getgenv()._lastBossEngageTick = tick()
                        CurrentFarmStatus = "[Săn Boss Sưu Tầm] Đang hạ Boss " .. tostring(bMob.Name) .. " lấy " .. tostring(bt.Item) .. " (HP: " .. math.floor(bmHum.Health) .. ")..."
                        DisableMobCollision(bMob)
                        EnableBuso()
                        EquipSelectedWeapon()
                        TweenTo(bMob.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
                        return true
                    end
                end
            end
            end
        end
    end

    return false
end

-- =========================================================================
-- 2. NHÁNH TIẾN TRÌNH THEO THỨ TỰ (PROGRESSION STEP):
-- Godhuman Materials -> CDK (Luyện 350 Mas & 6 Thử Thách) -> Skull Guitar (Lv 2300+) -> Shark Anchor
-- =========================================================================
function V1StyleLookup.ItemsSystem.DoProgressionStep(hrp, hum)
    if getgenv()._isDoingRaidForF or HasSpecialMicrochip() or IsInRaid() then
        return false
    end

    -- Nếu đang có võ Melee mục tiêu (như Dragon Talon) chưa sở hữu / đang mở khóa:
    -- BẮT BUỘC ưu tiên 100% hoàn thành mở khóa và mua võ trước, không ngắt quãng đi làm Rainbow Haki hay vật phẩm phụ!
    local actStyle = (type(V1StyleLookup) == "table" and type(V1StyleLookup.GetActiveTargetStyle) == "function" and V1StyleLookup.GetActiveTargetStyle())
    if actStyle ~= nil then
        local hasTool = (V1StyleLookup.FindMeleeTool and V1StyleLookup.FindMeleeTool(actStyle.Name) ~= nil)
        if not hasTool then
            return false
        end
    end
    local IS = V1StyleLookup.ItemsSystem
    IS.RefreshInventory(false)
    local curLv = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0

    local trainingMeleeNow = IS.IsTrainingMeleeOnHand()
    -- Nếu KHÔNG có kiếm/súng mục tiêu nào đang cần farm mastery -> dùng Melee farm cấp
    if trainingMeleeNow and getgenv()._targetSwordName == nil then
        SetSettingWeapon("Melee")
    end

    -- =========================================================================
    -- MỐC 1: GODHUMAN (KHI ĐÃ FULL VÕ V1 & 5 VÕ V2 ĐẠT >= 400 MASTERY)
    -- Tự động gom đủ 4 nguyên liệu (20 Fish Tail, 10 Dragon Scale, 20 Magma Ore, 10 Mystic Droplet)
    -- =========================================================================
    if (IsSettingGetItem("Godhuman") or IsSettingBuyMeleeV2())
        and V1StyleLookup.IsPreGodhumanMastered()
        and not V1StyleLookup.MasteredV2["Godhuman"]
        and not IS.HasItem("Godhuman")
        and not V1StyleLookup.EquipByName("Godhuman") then

        if not IS.HasAllGodhumanMaterials() then
            -- Ưu tiên farm nguyên liệu ở Sea hiện tại trước để tránh dịch chuyển Sea nhiều lần
            local targetMat = nil
            for _, mat in ipairs(IS.GodhumanMaterials) do
                if mat.Sea == CurrentSeaNum and IS.GetCount(mat.Name) < mat.Need then
                    targetMat = mat
                    break
                end
            end
            if not targetMat then
                for _, mat in ipairs(IS.GodhumanMaterials) do
                    if IS.GetCount(mat.Name) < mat.Need then
                        targetMat = mat
                        break
                    end
                end
            end

            if targetMat then
                local haveCount = IS.GetCount(targetMat.Name)
                if CurrentSeaNum ~= targetMat.Sea then
                    if not IS.IsHoldingProtectedItem() and tick() - LastTravelAttempt >= 8 then
                        LastTravelAttempt = tick()
                        local travelCmd = (targetMat.Sea == 3 and "TravelZou") or (targetMat.Sea == 2 and "TravelDressrosa") or "TravelMain"
                        CurrentFarmStatus = "[Godhuman] Thiếu nguyên liệu " .. targetMat.Name .. " (" .. tostring(haveCount) .. "/" .. tostring(targetMat.Need) .. ") -> Đang qua Sea " .. tostring(targetMat.Sea) .. "..."
                        if getgenv().StopTween then getgenv().StopTween() end
                        pcall(function()
                            ReplicatedStorage.Remotes.CommF_:InvokeServer(travelCmd)
                        end)
                        task.wait(2)
                        return true
                    end
                else
                    return IS.AttackMobsByList(
                        hrp,
                        hum,
                        targetMat.Mobs,
                        targetMat.WaitCF,
                        "[Godhuman - " .. targetMat.Name .. " (" .. tostring(haveCount) .. "/" .. tostring(targetMat.Need) .. ")]",
                        targetMat.Quest
                    )
                end
            end
        elseif CurrentSeaNum ~= 3 and not IS.IsHoldingProtectedItem() and tick() - LastTravelAttempt >= 8 then
            -- Đã gom đủ 4 nguyên liệu Godhuman ở Sea 2 -> Quay lại Sea 3 để mua Godhuman!
            LastTravelAttempt = tick()
            CurrentFarmStatus = "[Godhuman] ✅ Đã gom đủ 4 nguyên liệu Godhuman! Đang quay về Sea 3 để mua Godhuman..."
            if getgenv().StopTween then getgenv().StopTween() end
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("TravelZou")
            end)
            task.wait(2)
            return true
        end
    end

    -- =========================================================================
    -- MỐC 2: CURSED DUAL KATANA - CDK (SEA 3 - LV 2200+)
    -- Điều kiện tiên quyết: Phải Full 400 Mastery toàn bộ võ V2 (trừ Godhuman) bằng Melee trước!
    -- Bước A: Khi full võ V2 -> Luyện Yama & Tushita lên 350 Mastery (Ưu tiên số 1 cho Yama)
    -- Bước B: Khi đủ Lv 2200+ & cả 2 kiếm >= 350 Mastery -> Mở đền CDK & làm 6 thử thách ghép kiếm
    -- =========================================================================
    local isPreGhMastered = (type(V1StyleLookup) == "table" and type(V1StyleLookup.IsPreGodhumanMastered) == "function" and V1StyleLookup.IsPreGodhumanMastered())
    if isPreGhMastered and (IsSettingGetItem("Cursed Dual Katana") or IsSettingGetItem("Tushita") or IsSettingGetItem("Yama")) and (World3 or CurrentSeaNum == 3) and not IS.HasItem("Cursed Dual Katana") then
        local inRaid = (getgenv()._isDoingRaidForF == true)
            or (type(V1StyleLookup) == "table" and V1StyleLookup.IsInRaid and V1StyleLookup.IsInRaid())
        local isStatsInMelee = false
        pcall(function()
            local data = plr:FindFirstChild("Data")
            local statsFolder = data and data:FindFirstChild("Stats")
            if statsFolder then
                local swLv = GetStatCurrentLevel(statsFolder, "Sword")
                local melLv = GetStatCurrentLevel(statsFolder, "Melee")
                if melLv >= 800 and swLv < melLv * 0.5 then
                    isStatsInMelee = true
                end
            end
        end)

        -- KHI ĐANG TRONG RAID HOẶC STATS CHƯA RESET SANG KIẾM (ĐIỂM ĐANG Ở MELEE & MÁU):
        -- TUYỆT ĐỐI KHÔNG DÙNG KIẾM! HỦY _targetSwordName VÀ DÙNG MELEE FARM CHO NHANH!
        if inRaid or isStatsInMelee then
            if getgenv()._targetSwordName == "Yama" or getgenv()._targetSwordName == "Tushita" then
                getgenv()._targetSwordName = nil
                SetSettingWeapon("Melee")
            end
            return false
        end

        local hasYama = IS.HasItem("Yama")
        local yamaMas = IS.GetMastery("Yama")
        local hasTushita = IS.HasItem("Tushita")
        local tushitaMas = IS.GetMastery("Tushita")

        if hasYama and yamaMas < 350 then
            getgenv()._targetSwordName = "Yama"
            SetSettingWeapon("Sword")
            V1StyleLookup.EnsureSwordEquipped("Yama")
            -- Trả về false để vòng lặp farm cấp/xương phía dưới dùng Yama chém quái lên 350 Mastery
            return false
        elseif hasTushita and tushitaMas < 350 then
            getgenv()._targetSwordName = "Tushita"
            SetSettingWeapon("Sword")
            V1StyleLookup.EnsureSwordEquipped("Tushita")
            -- Trả về false để vòng lặp farm cấp/xương phía dưới dùng Tushita chém quái lên 350 Mastery
            return false
        elseif (hasYama and yamaMas >= 350) and (hasTushita and tushitaMas >= 350) then
            if getgenv()._targetSwordName == "Yama" or getgenv()._targetSwordName == "Tushita" then
                getgenv()._targetSwordName = nil
                SetSettingWeapon("Melee")
            end
            local now = tick()
            if now - (IS.LastCDKCheck or 0) >= 5.0 or IS.CDKProg == nil then
                IS.LastCDKCheck = now
                pcall(function()
                    IS.CDKProg = ReplicatedStorage.Remotes.CommF_:InvokeServer("CDKQuest", "Progress")
                end)
            end
            local cdk = IS.CDKProg
            local cursedFolder = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Turtle") and workspace.Map.Turtle:FindFirstChild("Cursed")

            -- 1. Mở cửa đền CDK nếu chưa mở
            if (cursedFolder and cursedFolder:FindFirstChild("Breakable")) or (type(cdk) == "table" and not cdk.Opened) then
                CurrentFarmStatus = "[Cursed Dual Katana] Đã đủ Yama & Tushita (350+ Mas) -> Đang mở cửa đền CDK sau Mansion..."
                local doorCF = (cursedFolder and cursedFolder:FindFirstChild("Breakable") and cursedFolder.Breakable.CFrame) or CFrame.new(-12131, 578, -6707)
                if (hrp.Position - doorCF.Position).Magnitude > 10 then
                    TweenTo(doorCF)
                else
                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("CDKQuest", "OpenDoor")
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("CDKQuest", "OpenDoor", true)
                    end)
                    if cursedFolder and cursedFolder:FindFirstChild("Breakable") then
                        pcall(function() cursedFolder.Breakable:Destroy() end)
                    end
                    IS.CDKProg = nil
                end
                return true
            end

            -- 2. Kiểm tra если đang ở trong Hell Dimension hoặc Heavenly Dimension -> Thắp 3 đuốc & đánh quái mở cổng Exit
            for _, dimName in ipairs({ "HellDimension", "HeavenlyDimension" }) do
                local dimFolder = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild(dimName)
                if dimFolder then
                    for _, obj in ipairs(dimFolder:GetChildren()) do
                        if string.find(obj.Name, "Torch") and obj:FindFirstChild("ProximityPrompt") and obj.ProximityPrompt.Enabled then
                            CurrentFarmStatus = "[Cursed Dual Katana] Đang thắp đuốc trong " .. dimName .. "..."
                            TweenTo(obj.CFrame)
                            if (hrp.Position - obj.Position).Magnitude <= 12 and fireproximityprompt then
                                pcall(function()
                                    obj.ProximityPrompt.HoldDuration = 0
                                    fireproximityprompt(obj.ProximityPrompt)
                                end)
                            end
                            return true
                        end
                    end
                    local dimMob = IS.FindAliveMobFromList({ "Hell's Messenger", "Heaven's Guardian", "Cursed Skeleton", "Soul" }, false)
                    if dimMob and dimMob:FindFirstChild("HumanoidRootPart") then
                        CurrentFarmStatus = "[Cursed Dual Katana] Đang tiêu diệt quái bảo vệ trong " .. dimName .. "..."
                        DisableMobCollision(dimMob)
                        EnableBuso()
                        EquipSelectedWeapon()
                        TweenTo(dimMob.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
                        return true
                    end
                    local exitPart = dimFolder:FindFirstChild("Exit")
                    if exitPart and exitPart:IsA("BasePart") then
                        CurrentFarmStatus = "[Cursed Dual Katana] Đang bước qua cổng Exit rời khỏi " .. dimName .. "..."
                        TweenTo(exitPart.CFrame)
                        return true
                    end
                end
            end

            -- 3. Nếu Boss Cursed Skeleton [Lv. 2225] đã xuất hiện -> Dùng Yama/Tushita tiêu diệt để nhận CDK!
            local cursedBoss = IS.FindAliveMobFromList({ "Cursed Skeleton" }, true)
            local cbHum = cursedBoss and cursedBoss:FindFirstChildOfClass("Humanoid")
            if cursedBoss and cursedBoss:FindFirstChild("HumanoidRootPart") and cbHum and cbHum.Health > 0 then
                getgenv()._targetSwordName = IS.HasToolOnPlayer("Yama") and "Yama" or "Tushita"
                SetSettingWeapon("Sword")
                getgenv()._currentTargetMobName = "Cursed Skeleton"
                CurrentFarmStatus = "[Cursed Dual Katana] Đang hạ Boss Cursed Skeleton [Lv. 2225] ghép Song Kiếm Oden (HP: " .. math.floor(cbHum.Health) .. ")..."
                DisableMobCollision(cursedBoss)
                EnableBuso()
                EquipSelectedWeapon()
                TweenTo(cursedBoss.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
                return true
            end

            -- 4. Kiểm tra các bệ thờ Pedestal1..3 hoặc nhận Trial Good / Evil
            if type(cdk) == "table" then
                if cursedFolder then
                    for pIdx = 1, 3 do
                        local ped = cursedFolder:FindFirstChild("Pedestal" .. pIdx)
                        if ped and ped:FindFirstChild("ProximityPrompt") and ped.ProximityPrompt.Enabled then
                            CurrentFarmStatus = "[Cursed Dual Katana] Đang kích hoạt bệ thờ Pedestal" .. tostring(pIdx) .. "..."
                            if (hrp.Position - ped.Position).Magnitude > 8 then
                                TweenTo(ped.CFrame)
                            elseif fireproximityprompt then
                                pcall(function() fireproximityprompt(ped.ProximityPrompt) end)
                                IS.CDKProg = nil
                                task.wait(0.8)
                            end
                            return true
                        end
                    end
                end

                local evilStep = tonumber(cdk.Evil) or 0
                local goodStep = tonumber(cdk.Good) or 0
                if evilStep < 3 and evilStep ~= 4 then
                    if not IS.HasToolOnPlayer("Yama") then
                        pcall(function() ReplicatedStorage.Remotes.CommF_:InvokeServer("LoadItem", "Yama") end)
                    end
                    if evilStep >= 0 then
                        pcall(function() ReplicatedStorage.Remotes.CommF_:InvokeServer("CDKQuest", "StartTrial", "Evil") end)
                    end
                    if evilStep == 0 or evilStep == 1 or evilStep == -3 then
                        getgenv()._pauseFastAttackUntil = tick() + 2.0
                        IS.EquipToolByName("Yama")
                        local fp = IS.FindAliveMobFromList({ "Forest Pirate" }, false)
                        CurrentFarmStatus = "[CDK - Yama Trial 1] Đang cầm Yama tới Forest Pirate chịu đòn hoàn thành thử thách 1..."
                        TweenTo((fp and fp:FindFirstChild("HumanoidRootPart") and fp.HumanoidRootPart.CFrame) or CFrame.new(-13206, 332, -7905))
                        return true
                    elseif evilStep == 2 or evilStep == -2 then
                        local hazeFolder = plr:FindFirstChild("QuestHaze")
                        if hazeFolder then
                            for _, hVal in ipairs(hazeFolder:GetChildren()) do
                                if tonumber(hVal.Value) and tonumber(hVal.Value) > 0 then
                                    local hSpawnCF = FindMobSpawnCFrame and FindMobSpawnCFrame(hVal.Name)
                                    local hPart = (not hSpawnCF and DetectPartSpawnMob and DetectPartSpawnMob(hVal.Name, false)) or nil
                                    local waitHazeCF = hSpawnCF or (hPart and hPart.CFrame) or CFrame.new(-13206, 332, -7905)
                                    return IS.AttackMobsByList(hrp, hum, { hVal.Name }, waitHazeCF, "[CDK - Yama Trial 2 (Haze: " .. tostring(hVal.Name) .. ")]", nil)
                                end
                            end
                        end
                    else
                        local sr = IS.FindAliveMobFromList({ "Soul Reaper" }, true)
                        if sr and sr:FindFirstChild("HumanoidRootPart") then
                            getgenv()._pauseFastAttackUntil = tick() + 2.0
                            CurrentFarmStatus = "[CDK - Yama Trial 3] Đang chạm Boss Soul Reaper để vào Hell Dimension..."
                            TweenTo(sr.HumanoidRootPart.CFrame)
                            return true
                        else
                            return IS.AttackMobsByList(
                                hrp,
                                hum,
                                { "Reborn Skeleton", "Living Zombie", "Demonic Soul", "Posessed Mummy" },
                                CFrame.new(-9506, 172, 6078),
                                "[CDK - Yama Trial 3 (Farm Xương quay Hallow Essence gọi Soul Reaper)]",
                                { Name = "HauntedQuest2", Id = 1, Lv = 2025, NpcCF = CFrame.new(-9515, 172, 6078) }
                            )
                        end
                    end
                elseif goodStep < 3 and goodStep ~= 4 then
                    if not IS.HasToolOnPlayer("Tushita") then
                        pcall(function() ReplicatedStorage.Remotes.CommF_:InvokeServer("LoadItem", "Tushita") end)
                    end
                    if goodStep >= 0 then
                        pcall(function() ReplicatedStorage.Remotes.CommF_:InvokeServer("CDKQuest", "StartTrial", "Good") end)
                    end
                    if goodStep == 0 or goodStep == 1 or goodStep == -3 then
                        CurrentFarmStatus = "[CDK - Tushita Trial 1] Đang đi qua 3 Luxury Boat Dealer nhận Pardon me..."
                        local boatSpots = {
                            CFrame.new(-4602, 16, 5290),
                            CFrame.new(-9531, 7, -8376),
                            CFrame.new(5156, 6, 1105),
                            CFrame.new(-5530, 314, -2850),
                        }
                        IS.BoatTrialIdx = ((IS.BoatTrialIdx or 0) % #boatSpots) + 1
                        local bCF = boatSpots[IS.BoatTrialIdx]
                        if (hrp.Position - bCF.Position).Magnitude > 15 then
                            TweenTo(bCF)
                        else
                            pcall(function()
                                local npcObj = (workspace:FindFirstChild("NPCs") and workspace.NPCs:FindFirstChild("Luxury Boat Dealer"))
                                    or (ReplicatedStorage:FindFirstChild("NPCs") and ReplicatedStorage.NPCs:FindFirstChild("Luxury Boat Dealer"))
                                if npcObj then
                                    ReplicatedStorage.Remotes.CommF_:InvokeServer("CDKQuest", "BoatQuest", npcObj, "Check")
                                    task.wait(0.2)
                                    ReplicatedStorage.Remotes.CommF_:InvokeServer("CDKQuest", "BoatQuest", npcObj)
                                end
                            end)
                            IS.CDKProg = nil
                            task.wait(0.5)
                        end
                        return true
                    elseif goodStep == -2 then
                        CurrentFarmStatus = "[CDK - Tushita Trial 2] Đang canh Hải Tặc tấn công Lâu Đài (Pirate Raid) tại Castle on the Sea..."
                        TweenTo(CFrame.new(-5543.53, 313.80, -2964.26))
                        return true
                    elseif goodStep == 2 or goodStep == -1 then
                        local cq = IS.FindAliveMobFromList({ "Cake Queen" }, true)
                        if cq and cq:FindFirstChild("HumanoidRootPart") then
                            IS.CakeQueenArriveTick = nil
                            getgenv()._currentTargetMobName = "Cake Queen"
                            CurrentFarmStatus = "[CDK - Tushita Trial 3] Đang hạ Boss Cake Queen mở cổng Heavenly Dimension..."
                            DisableMobCollision(cq)
                            EnableBuso()
                            EquipSelectedWeapon()
                            TweenTo(cq.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
                            return true
                        else
                            local cqCF = CFrame.new(-710, 382, -11150)
                            if (hrp.Position - cqCF.Position).Magnitude > 25 then
                                IS.CakeQueenArriveTick = nil
                                CurrentFarmStatus = "[CDK - Tushita Trial 3] Đang bay tới Đảo Kem kiểm tra Boss Cake Queen..."
                                TweenTo(cqCF)
                                return true
                            else
                                IS.CakeQueenArriveTick = IS.CakeQueenArriveTick or tick()
                                if tick() - IS.CakeQueenArriveTick >= 3.5 and IsAutoHopEnabled() and HopServer and not IS.IsHoldingProtectedItem() then
                                    IS.CakeQueenArriveTick = tick()
                                    HopServer("Boss Cake Queen chưa hồi sinh (CDK Trial 3) -> Đang đổi server...")
                                    return true
                                end
                                CurrentFarmStatus = "[CDK - Tushita Trial 3] Đang đợi Boss Cake Queen..."
                                return true
                            end
                        end
                    end
                else
                    -- Đã hoàn thành cả 6 thử thách (evilStep >= 3 & goodStep >= 3) -> Kích hoạt bệ thờ chính để triệu hồi Cursed Skeleton!
                    local mainAltarCF = CFrame.new(-12361, 603, -6550)
                    CurrentFarmStatus = "[Cursed Dual Katana] ⚔️ Đã hoàn tất 6/6 thử thách! Đang kích hoạt Bệ Thờ Chính triệu hồi Boss Cursed Skeleton..."
                    if (hrp.Position - mainAltarCF.Position).Magnitude > 12 then
                        TweenTo(mainAltarCF)
                    else
                        if cursedFolder and fireproximityprompt then
                            for _, desc in ipairs(cursedFolder:GetDescendants()) do
                                if desc:IsA("ProximityPrompt") and desc.Enabled then
                                    pcall(function()
                                        desc.HoldDuration = 0
                                        fireproximityprompt(desc)
                                    end)
                                end
                            end
                        end
                        IS.CDKProg = nil
                        task.wait(0.8)
                    end
                    return true
                end
            end
        end
    end

    -- =========================================================================
    -- MỐC 3: SKULL GUITAR / SOUL GUITAR (LV 2300+)
    -- Giải 6 bước câu đố tại Haunted Castle (Full Moon) & gom nguyên liệu (500 Bones + 250 Ectoplasm + 1 Dark Fragment)
    -- =========================================================================
    if (IsSettingGetItem("Skull Guitar") or IsSettingGetItem("Soul Guitar")) and curLv >= 2300 and not IS.HasItem("Skull Guitar") then
        -- 1. Kiểm tra nếu thiếu 250 Ectoplasm và đã có Dark Fragment -> Qua Sea 2 farm đủ 250 Ectoplasm
        local ectoCount = IS.GetCount("Ectoplasm")
        local boneCount = IS.GetCount("Bones")
        local hasDarkFrag = IS.GetCount("Dark Fragment") >= 1

        if (World3 or CurrentSeaNum == 3) then
            local now = tick()
            if now - (IS.LastSGCheck or 0) >= 6.0 then
                IS.LastSGCheck = now
                pcall(function()
                    IS.SGProg = ReplicatedStorage.Remotes.CommF_:InvokeServer("GuitarPuzzleProgress", "Check")
                end)
            end
            local sg = IS.SGProg

            -- Nếu chưa mở câu đố (sg == nil) và đang có Trăng Tròn (Full Moon) -> Cầu nguyện tại Bia Mộ ngay!
            if sg == nil and IS.IsFullMoon() then
                local graveCF = CFrame.new(-8654, 140, 6167)
                CurrentFarmStatus = "[Skull Guitar] 🌕 Phát hiện Full Moon (Lv. 2300+)! Đang cầu nguyện tại Bia Mộ mở nhiệm vụ Đàn Linh Hồn..."
                if (hrp.Position - graveCF.Position).Magnitude > 8 then
                    TweenTo(graveCF)
                else
                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("gravestoneEvent", 2)
                        task.wait(0.2)
                        IS.SGProg = ReplicatedStorage.Remotes.CommF_:InvokeServer("gravestoneEvent", 2, true)
                    end)
                end
                return true
            elseif type(sg) == "table" then
                local hc = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Haunted Castle")
                if not sg.Swamp then
                    -- Bước 1: Hạ 6 con Living Zombie cùng lúc
                    return IS.AttackMobsByList(
                        hrp,
                        hum,
                        { "Living Zombie" },
                        CFrame.new(-10160, 138, 5955),
                        "[Skull Guitar - Bước 1/5 (Hạ 6 Living Zombie)]",
                        nil
                    )
                elseif not sg.Gravestones then
                    -- Bước 2: Chỉnh 7 bảng gỗ nghĩa địa (Placards 1..7)
                    local placCF = CFrame.new(-8800, 178, 6033)
                    CurrentFarmStatus = "[Skull Guitar - Bước 2/5] Đang chỉnh 7 bảng mộ tại Nghĩa Địa Haunted Castle..."
                    if (hrp.Position - placCF.Position).Magnitude > 12 then
                        TweenTo(placCF)
                    elseif hc then
                        local ans = {
                            Placard1 = "Right",
                            Placard2 = "Right",
                            Placard3 = "Left",
                            Placard4 = "Right",
                            Placard5 = "Left",
                            Placard6 = "Left",
                            Placard7 = "Left",
                        }
                        for pName, side in pairs(ans) do
                            pcall(function()
                                local cd = hc[pName][side]:FindFirstChildOfClass("ClickDetector")
                                if cd and fireclickdetector then fireclickdetector(cd) end
                            end)
                        end
                        IS.SGProg = nil
                        task.wait(0.5)
                    end
                    return true
                elseif not sg.Ghost then
                    -- Bước 3: Bay tới NPC Ghost trong Lâu Đài & nói chuyện
                    local ghostCF = CFrame.new(-9755, 271, 6291)
                    CurrentFarmStatus = "[Skull Guitar - Bước 3/5] Đang tới NPC Ghost trong Lâu Đài Haunted Castle..."
                    if (hrp.Position - ghostCF.Position).Magnitude > 12 then
                        TweenTo(ghostCF)
                    else
                        pcall(function()
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("GuitarPuzzleProgress", "Ghost")
                        end)
                        IS.SGProg = nil
                        task.wait(0.5)
                    end
                    return true
                elseif not sg.Trophies then
                    -- Bước 4: Xoay bảng đá dưới hầm khớp hướng 5 chiếc Cúp (Trophies)
                    local tabCF = CFrame.new(-9530, 6, 6055)
                    CurrentFarmStatus = "[Skull Guitar - Bước 4/5] Đang giải câu đố Bảng Đá & Cúp Vàng dưới tầng hầm..."
                    if (hrp.Position - tabCF.Position).Magnitude > 25 then
                        TweenTo(tabCF)
                    elseif hc and hc:FindFirstChild("Tablet") and hc:FindFirstChild("Trophies") then
                        local tab = hc.Tablet
                        for _, segName in ipairs(IS.BlankTablets) do
                            pcall(function()
                                local seg = tab:FindFirstChild(segName)
                                if seg and seg:FindFirstChild("Line") and seg.Line.Rotation.Z ~= 0 and fireclickdetector then
                                    fireclickdetector(seg.ClickDetector)
                                end
                            end)
                        end
                        for segName, trName in pairs(IS.TrophyMap) do
                            pcall(function()
                                local tr = hc.Trophies.Quest:FindFirstChild(trName)
                                local seg = tab:FindFirstChild(segName)
                                if tr and tr:FindFirstChild("Handle") and seg and seg:FindFirstChild("Line") and fireclickdetector then
                                    local cfParts = tostring(tr.Handle.CFrame):split(", ")
                                    local rVal = cfParts[4]
                                    local targetRot = (rVal == "1" or rVal == "-1") and "90" or "180"
                                    if not string.find(tostring(seg.Line.Rotation.Z), targetRot, 1, true) then
                                        fireclickdetector(seg.ClickDetector)
                                    end
                                end
                            end)
                        end
                        IS.SGProg = nil
                        task.wait(0.3)
                    end
                    return true
                elseif not sg.Pipes then
                    -- Bước 5: Chỉnh màu 10 ống nước dưới sàn hầm
                    local pipeCF = CFrame.new(-9530, 6, 6055)
                    CurrentFarmStatus = "[Skull Guitar - Bước 5/5] Đang chỉnh màu Ống Nước dưới tầng hầm..."
                    if (hrp.Position - pipeCF.Position).Magnitude > 25 then
                        TweenTo(pipeCF)
                    elseif hc and hc:FindFirstChild("Lab Puzzle") then
                        local cModel = hc["Lab Puzzle"]:FindFirstChild("ColorFloor") and hc["Lab Puzzle"].ColorFloor:FindFirstChild("Model")
                        if cModel then
                            for partName, targetColor in pairs(IS.PipesMap) do
                                pcall(function()
                                    local p = cModel:FindFirstChild(partName)
                                    if p and p.BrickColor.Name ~= targetColor and fireclickdetector then
                                        fireclickdetector(p.ClickDetector)
                                    end
                                end)
                            end
                        end
                        IS.SGProg = nil
                        task.wait(0.4)
                    end
                    return true
                else
                    -- Đã giải xong cả 5 bước câu đố -> Kiểm tra nguyên liệu để mua Skull Guitar!
                    if boneCount < 500 then
                        local boneQuest = nil
                        local boneWaitCF = CFrame.new(-8763.72, 165.72, 6159.86)
                        if curLv >= 2050 then
                            boneQuest = { Name = "HauntedQuest2", Id = 2, Lv = 2050, NpcCF = CFrame.new(-9516.99, 172.02, 6078.47) }
                            boneWaitCF = CFrame.new(-9582.02, 6.25, 6205.48)
                        elseif curLv >= 2025 then
                            boneQuest = { Name = "HauntedQuest2", Id = 1, Lv = 2025, NpcCF = CFrame.new(-9516.99, 172.02, 6078.47) }
                            boneWaitCF = CFrame.new(-9505.87, 172.10, 6158.99)
                        elseif curLv >= 2000 then
                            boneQuest = { Name = "HauntedQuest1", Id = 2, Lv = 2000, NpcCF = CFrame.new(-9479.22, 141.22, 5566.09) }
                            boneWaitCF = CFrame.new(-10144.13, 138.63, 5838.09)
                        elseif curLv >= 1975 then
                            boneQuest = { Name = "HauntedQuest1", Id = 1, Lv = 1975, NpcCF = CFrame.new(-9479.22, 141.22, 5566.09) }
                            boneWaitCF = CFrame.new(-8763.72, 165.72, 6159.86)
                        end
                        return IS.AttackMobsByList(
                            hrp,
                            hum,
                            { "Reborn Skeleton", "Living Zombie", "Demonic Soul", "Posessed Mummy" },
                            boneWaitCF,
                            "[Skull Guitar - Farm Xương (" .. tostring(boneCount) .. "/500 Bones)]",
                            boneQuest
                        )
                    elseif ectoCount < 250 and not IS.IsHoldingProtectedItem() and tick() - LastTravelAttempt >= 8 then
                        LastTravelAttempt = tick()
                        CurrentFarmStatus = "[Skull Guitar] Thiếu Ectoplasm (" .. tostring(ectoCount) .. "/250) -> Đang qua Sea 2 (Cursed Ship) để farm..."
                        if getgenv().StopTween then getgenv().StopTween() end
                        pcall(function()
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("TravelDressrosa")
                        end)
                        task.wait(2)
                        return true
                    elseif not hasDarkFrag and not IS.IsHoldingProtectedItem() and tick() - LastTravelAttempt >= 8 then
                        LastTravelAttempt = tick()
                        CurrentFarmStatus = "[Skull Guitar] Thiếu 1 Dark Fragment -> Đang qua Sea 2 săn Fist of Darkness & Darkbeard..."
                        if getgenv().StopTween then getgenv().StopTween() end
                        pcall(function()
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("TravelDressrosa")
                        end)
                        task.wait(2)
                        return true
                    elseif hasDarkFrag then
                        local curFrags = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Fragments") and plr.Data.Fragments.Value) or 0
                        if curFrags < 5000 then
                            getgenv()._raidTargetStyle = "Skull Guitar"
                            getgenv()._raidTargetFrags = 5000
                            DoAutoRaidStep(hrp, hum, curFrags, 5000, "Skull Guitar")
                            return true
                        end
                        CurrentFarmStatus = "[Skull Guitar] 🎸 Đã đủ nguyên liệu & giải xong câu đố -> Đang chế tạo Skull Guitar..."
                        pcall(function()
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("soulGuitarBuy")
                        end)
                        IS.RefreshInventory(true)
                        task.wait(0.8)
                        return true
                    end
                end
            elseif sg == nil and boneCount < 500 then
                -- Khi đang đợi Full Moon để mở câu đố Skull Guitar nhưng chưa đủ 500 Bones -> Chủ động farm trước 500 Bones tại Haunted Castle!
                local boneQuest = nil
                local boneWaitCF = CFrame.new(-8763.72, 165.72, 6159.86)
                if curLv >= 2050 then
                    boneQuest = { Name = "HauntedQuest2", Id = 2, Lv = 2050, NpcCF = CFrame.new(-9516.99, 172.02, 6078.47) }
                    boneWaitCF = CFrame.new(-9582.02, 6.25, 6205.48)
                elseif curLv >= 2025 then
                    boneQuest = { Name = "HauntedQuest2", Id = 1, Lv = 2025, NpcCF = CFrame.new(-9516.99, 172.02, 6078.47) }
                    boneWaitCF = CFrame.new(-9505.87, 172.10, 6158.99)
                elseif curLv >= 2000 then
                    boneQuest = { Name = "HauntedQuest1", Id = 2, Lv = 2000, NpcCF = CFrame.new(-9479.22, 141.22, 5566.09) }
                    boneWaitCF = CFrame.new(-10144.13, 138.63, 5838.09)
                elseif curLv >= 1975 then
                    boneQuest = { Name = "HauntedQuest1", Id = 1, Lv = 1975, NpcCF = CFrame.new(-9479.22, 141.22, 5566.09) }
                    boneWaitCF = CFrame.new(-8763.72, 165.72, 6159.86)
                end
                return IS.AttackMobsByList(
                    hrp,
                    hum,
                    { "Reborn Skeleton", "Living Zombie", "Demonic Soul", "Posessed Mummy" },
                    boneWaitCF,
                    "[Skull Guitar - Tích Trữ Xương Chờ Full Moon (" .. tostring(boneCount) .. "/500 Bones)]",
                    boneQuest
                )
            end
        elseif (World2 or CurrentSeaNum == 2) then
            if ectoCount < 250 then
                return IS.AttackMobsByList(
                    hrp,
                    hum,
                    { "Ship Deckhand", "Ship Engineer", "Ship Steward", "Ship Officer" },
                    CFrame.new(919, 125, 32869),
                    "[Skull Guitar - Farm Ectoplasm (" .. tostring(ectoCount) .. "/250)]",
                    nil
                )
            elseif not hasDarkFrag then
                if IS.CollectNearestChest(hrp) then
                    return true
                end
            elseif ectoCount >= 250 and hasDarkFrag and not IS.IsHoldingProtectedItem() and tick() - LastTravelAttempt >= 8 then
                LastTravelAttempt = tick()
                CurrentFarmStatus = "[Skull Guitar] ✅ Đã đủ 250 Ectoplasm & Dark Fragment -> Đang quay về Sea 3 để mua Skull Guitar..."
                if getgenv().StopTween then getgenv().StopTween() end
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("TravelZou")
                end)
                task.wait(2)
                return true
            end
        end
    end

    -- =========================================================================
    -- MỐC 3.5: AUTO PULL LEVER - FARM LEVER (GẠT CẦN TỘC V4 TẠI TEMPLE OF TIME)
    -- Khi bật ["Farm Lever"] = true & đã có Mirror Fractal + Valkyrie Helm ở Sea 3: Đọc bia Sealed King -> Vào Temple of Time -> Gạt Cần
    -- =========================================================================
    if (World3 or CurrentSeaNum == 3) and IS.IsFarmLeverEnabled() and not IS.LeverPulledDone and IS.HasItem("Mirror Fractal") and IS.HasItem("Valkyrie Helm") then
        local now = tick()
        if now - (IS.LastTempleCheck or 0) >= 12.0 then
            IS.LastTempleCheck = now
            pcall(function()
                IS.TempleDoorOpened = ReplicatedStorage.Remotes.CommF_:InvokeServer("CheckTempleDoor")
                if not IS.TempleDoorOpened then
                    IS.V4ProgStep = ReplicatedStorage.Remotes.CommF_:InvokeServer("RaceV4Progress", "Check")
                end
            end)
        end

        if not IS.TempleDoorOpened then
            local v4Step = IS.V4ProgStep
            if v4Step == 1 then
                CurrentFarmStatus = "[Auto Pull Lever] Đang đọc Bia Đá Sealed King mở nhiệm vụ Tộc V4..."
                pcall(function() ReplicatedStorage.Remotes.CommF_:InvokeServer("RaceV4Progress", "Begin") end)
                IS.LastTempleCheck = 0
                return true
            elseif v4Step == 2 then
                local treeTopCF = CFrame.new(3032.78, 2280.85, -7325.48)
                CurrentFarmStatus = "[Auto Pull Lever] Đang bay lên đỉnh Great Tree vào Temple of Time..."
                if (hrp.Position - treeTopCF.Position).Magnitude > 8 then
                    TweenTo(treeTopCF)
                else
                    pcall(function() ReplicatedStorage.Remotes.CommF_:InvokeServer("RaceV4Progress", "Teleport") end)
                    IS.LastTempleCheck = 0
                end
                return true
            elseif v4Step == 3 then
                CurrentFarmStatus = "[Auto Pull Lever] Đang nói chuyện với NPC trong Temple of Time..."
                pcall(function() ReplicatedStorage.Remotes.CommF_:InvokeServer("RaceV4Progress", "Continue") end)
                IS.LastTempleCheck = 0
                return true
            end
        else
            -- Đã lấy xong Blue Gear trên đảo Mirage -> Vào Temple of Time gạt cần (Pull Lever)!
            local templeCF = CFrame.new(28282.57, 14896.85, 105.10)
            local leverPrompt = nil
            pcall(function()
                for _, d in ipairs(workspace:GetDescendants()) do
                    if d:IsA("ProximityPrompt") and d.Parent and d.Parent.Name == "Prompt" and d.Parent.Parent and d.Parent.Parent.Name == "Lever" then
                        leverPrompt = d
                        break
                    end
                end
            end)
            if not leverPrompt and (hrp.Position - templeCF.Position).Magnitude > 300 then
                CurrentFarmStatus = "[Auto Pull Lever] Đã có Blue Gear -> Đang dịch chuyển vào Temple of Time để Gạt Cần..."
                TweenTo(templeCF)
                return true
            elseif leverPrompt and leverPrompt.Parent and leverPrompt.Parent:IsA("BasePart") then
                local lCF = leverPrompt.Parent.CFrame
                if (hrp.Position - lCF.Position).Magnitude > 8 then
                    CurrentFarmStatus = "[Auto Pull Lever] Đang tiến tới Cần Gạt (Lever) trong Temple of Time..."
                    TweenTo(lCF)
                else
                    CurrentFarmStatus = "[Auto Pull Lever] ✅ Đang Gạt Cần (Pull Lever) mở khóa Tộc V4..."
                    if fireproximityprompt then
                        pcall(function() fireproximityprompt(leverPrompt) end)
                    end
                    task.wait(1)
                    IS.LeverPulledDone = true
                end
                return true
            else
                IS.LeverPulledDone = true
            end
        end
    end

    -- =========================================================================
    -- MỐC 4: SHARK ANCHOR (SEA 3 - ĐẢO TIKI OUTPOST)
    -- Tự động chế tạo Monster Necklace -> Terror Jaw -> Monster Magnet tại Beast Hunter
    -- Khi có Monster Magnet hoặc thiếu nguyên liệu biển -> Tuần tra biển Tiki săn Shark, Piranha, Terrorshark
    -- =========================================================================
    IS.IsFarmingSharkAnchorSea = false
    if IsSettingGetItem("Shark Anchor") and (World3 or CurrentSeaNum == 3) and curLv >= 2300 and not IS.HasItem("Shark Anchor") then
        local now = tick()
        local canCraftNecklace = not IS.HasItem("Monster Necklace") and IS.GetCount("Mutant Tooth") >= 1 and IS.GetCount("Shark Tooth") >= 5
        local canCraftJaw = not IS.HasItem("Terror Jaw") and IS.GetCount("Terror Eyes") >= 1 and IS.GetCount("Mutant Tooth") >= 2 and IS.GetCount("Fool's Gold") >= 10 and IS.GetCount("Shark Tooth") >= 5
        local canCraftMagnet = not IS.HasItem("Monster Magnet") and IS.HasItem("Monster Necklace") and IS.HasItem("Terror Jaw") and IS.GetCount("Terror Eyes") >= 2 and IS.GetCount("Electric Wing") >= 8 and IS.GetCount("Fool's Gold") >= 20 and IS.GetCount("Shark Tooth") >= 10

        if (canCraftNecklace or canCraftJaw or canCraftMagnet) and (now - (IS.LastCraftCheck or 0) >= 8.0) then
            local bhCF = CFrame.new(-16235, 9, 439)
            CurrentFarmStatus = "[Shark Anchor] 🔨 Đã đủ nguyên liệu -> Đang tới NPC Beast Hunter (Tiki Outpost) chế tạo..."
            if (hrp.Position - bhCF.Position).Magnitude > 12 then
                TweenTo(bhCF)
                return true
            else
                IS.LastCraftCheck = now
                pcall(function()
                    if canCraftNecklace then
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("CraftItem", "Craft", "Monster Necklace")
                    end
                    if canCraftJaw then
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("CraftItem", "Craft", "Terror Jaw")
                    end
                    if canCraftMagnet then
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("CraftItem", "Craft", "Monster Magnet")
                    end
                end)
                IS.RefreshInventory(true)
                task.wait(0.5)
                return true
            end
        end

        IS.IsFarmingSharkAnchorSea = true
        if IS.HasItem("Monster Magnet") then
            CurrentFarmStatus = "[Shark Anchor] ⚓ Đã có Monster Magnet -> Đang tuần tra vùng biển Tiki Outpost gọi Terrorshark Mỏ Neo..."
        else
            CurrentFarmStatus = "[Shark Anchor] 🌊 Đang tuần tra biển Tiki Outpost săn Terrorshark/Shark/Piranha gom nguyên liệu chế tạo Monster Magnet..."
        end
        local seaPoints = {
            CFrame.new(-16930, 30, 1150),
            CFrame.new(-17650, 30, 1450),
            CFrame.new(-18500, 30, 1850),
        }
        IS.SeaPatrolIdx = IS.SeaPatrolIdx or 1
        local targetSeaCF = seaPoints[IS.SeaPatrolIdx]
        if (hrp.Position - targetSeaCF.Position).Magnitude < 30 then
            IS.SeaPatrolIdx = (IS.SeaPatrolIdx % #seaPoints) + 1
            targetSeaCF = seaPoints[IS.SeaPatrolIdx]
        end
        TweenTo(targetSeaCF)
        return true
    end

    -- =========================================================================
    -- MỐC 5: AUTO RAINBOW HAKI (RAINBOW SAVIOUR - SEA 3, LV. 1950+)
    -- Nhận quest Horned Man -> Diệt 5 Boss (Stone, Island Empress, Kilo Admiral, Captain Elephant, Beautiful Pirate)
    -- CHỈ kích hoạt khi bật "Get Items" -> "Rainbow Haki" / "Rainbow Saviour"
    -- Tuyệt đối không can thiệp khi đang đi Raid, hoặc đang mở khóa/mua võ Melee V2 (Dragon Talon, Godhuman)
    -- =========================================================================
    local isMeleeUnlockInProgress = false
    if type(V1StyleLookup) == "table" and type(V1StyleLookup.GetActiveTargetStyle) == "function" then
        local actStyle = V1StyleLookup.GetActiveTargetStyle()
        if actStyle ~= nil then
            local hasT = (V1StyleLookup.FindMeleeTool and V1StyleLookup.FindMeleeTool(actStyle.Name) ~= nil)
            if not hasT then
                isMeleeUnlockInProgress = true
            end
        end
    end

    if not getgenv()._isDoingRaidForF and getgenv()._raidTargetStyle == nil and not isMeleeUnlockInProgress and not HasSpecialMicrochip() and not IsInRaid() and (IsSettingGetItem("Rainbow Haki") or IsSettingGetItem("Rainbow Saviour")) and (World3 or CurrentSeaNum == 3) and curLv >= 1950 and not IS.RainbowHakiDone then
        local now = tick()
        if now - (IS.LastHornedCheck or 0) >= 20.0 then
            IS.LastHornedCheck = now
            pcall(function()
                if ReplicatedStorage.Remotes.CommF_:InvokeServer("HornedMan") == 1 then
                    IS.RainbowHakiDone = true
                end
            end)
        end

        if not IS.RainbowHakiDone then
            local rbBosses = { "Stone", "Island Empress", "Hydra Leader", "Kilo Admiral", "Captain Elephant", "Beautiful Pirate" }
            local qFullText = string.lower(GetQuestText() or "")
            local activeRbBoss = nil

            -- 1. Ưu tiên kiểm tra trực tiếp qua Task của game
            if GuideModule and GuideModule.Data and GuideModule.Data.QuestData and GuideModule.Data.QuestData.Task then
                for bTaskName, _ in pairs(GuideModule.Data.QuestData.Task) do
                    local bTaskLow = string.lower(tostring(bTaskName))
                    for _, rb in ipairs(rbBosses) do
                        local rbLow = string.lower(rb)
                        if bTaskLow == rbLow or string.find(bTaskLow, rbLow, 1, true) or string.find(rbLow, bTaskLow, 1, true) then
                            activeRbBoss = rb
                            break
                        end
                    end
                    if activeRbBoss then break end
                end
            end

            -- 2. Kiểm tra toàn bộ text hiển thị trên UI nhiệm vụ
            if not activeRbBoss and qFullText ~= "" then
                for _, bName in ipairs(rbBosses) do
                    local bLow = string.lower(bName)
                    if string.find(qFullText, bLow, 1, true) then
                        activeRbBoss = bName
                        break
                    end
                end
            end

            if activeRbBoss then
                local bList = (activeRbBoss == "Island Empress" or activeRbBoss == "Hydra Leader") and { "Island Empress", "Hydra Leader" } or { activeRbBoss }
                local bossMob = IS.FindAliveMobFromList(bList, true)
                local bmHum = bossMob and bossMob:FindFirstChildOfClass("Humanoid")
                if bossMob and bossMob:FindFirstChild("HumanoidRootPart") and bmHum and bmHum.Health > 0 then
                    IS.RbBossArriveTick = nil
                    getgenv()._currentTargetMobName = bossMob.Name
                    CurrentFarmStatus = "[Rainbow Haki] 🌈 Đang tiêu diệt Boss " .. tostring(bossMob.Name) .. " làm nhiệm vụ Haki Cầu Vồng (HP: " .. math.floor(bmHum.Health) .. ")..."
                    DisableMobCollision(bossMob)
                    EnableBuso()
                    EquipSelectedWeapon()
                    TweenTo(bossMob.HumanoidRootPart.CFrame * CFrame.new(0, 18, 0))
                    return true
                else
                    local bossSpots = {
                        ["Stone"] = CFrame.new(-1052, 44, 5551),
                        ["Island Empress"] = CFrame.new(5730, 602, 199),
                        ["Hydra Leader"] = CFrame.new(5730, 602, 199),
                        ["Kilo Admiral"] = CFrame.new(2889, 424, -7233),
                        ["Captain Elephant"] = CFrame.new(-13376, 319, -8423),
                        ["Beautiful Pirate"] = CFrame.new(-12030, 332, -8750),
                    }
                    local bSpot = bossSpots[activeRbBoss] or CFrame.new(-1052, 44, 5551)
                    if (hrp.Position - bSpot.Position).Magnitude > 30 then
                        IS.RbBossArriveTick = nil
                        CurrentFarmStatus = "[Rainbow Haki] 🌈 Đang bay tới kiểm tra Boss " .. tostring(activeRbBoss) .. "..."
                        TweenTo(bSpot)
                        return true
                    else
                        IS.RbBossArriveTick = IS.RbBossArriveTick or tick()
                        if tick() - IS.RbBossArriveTick >= 3.5 and IsAutoHopEnabled() and HopServer and not IS.IsHoldingProtectedItem() then
                            IS.RbBossArriveTick = tick()
                            HopServer("Boss " .. tostring(activeRbBoss) .. " (Rainbow Haki) chưa hồi sinh -> Đang đổi server...")
                            return true
                        else
                            CurrentFarmStatus = "[Rainbow Haki] 🌈 Đang đợi Boss " .. tostring(activeRbBoss) .. " hồi sinh..."
                            return false
                        end
                    end
                end
            elseif not HasActiveQuest() then
                local now = tick()
                if not IS.LastHornedTalkAttempt or (now - IS.LastHornedTalkAttempt >= 15.0) then
                    local hornedCF = CFrame.new(-11892, 930, -8760)
                    if (hrp.Position - hornedCF.Position).Magnitude > 10 then
                        CurrentFarmStatus = "[Rainbow Haki] 🌈 Đang bay tới Horned Man nhận nhiệm vụ Haki Cầu Vồng..."
                        TweenTo(hornedCF)
                        return true
                    else
                        IS.LastHornedTalkAttempt = now
                        pcall(function()
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("HornedMan", "Bet")
                        end)
                        IS.TalkedToHornedMan = true
                        task.wait(0.5)
                        return true
                    end
                end
            end
        end
    end

    -- =========================================================================
    -- MỐC 6: AUTO CITIZEN QUEST & NÂNG CẤP INSTINCT V2 (KEN HAKI V2 - SEA 3, LV. 1800+)
    -- Hạ 50 Forest Pirate -> Hạ Captain Elephant -> Lấy Musketeer Hat -> Gom 3 Quả đổi Fruit Bowl -> Mua Ken V2 ($5,000,000)
    -- =========================================================================
    local isKenV2Setting = IsSettingGetItem("Instinct V2") or IsSettingGetItem("Observation V2")
    if isKenV2Setting and (World3 or CurrentSeaNum == 3) and curLv >= 1800 and not IS.InstinctV2Done then
        local now = tick()
        if now - (IS.LastCitizenCheck or 0) >= 15.0 then
            IS.LastCitizenCheck = now
            pcall(function()
                IS.CitizenStep = ReplicatedStorage.Remotes.CommF_:InvokeServer("CitizenQuestProgress", "Citizen")
            end)
        end

        local cStep = IS.CitizenStep
        local citizenCF = CFrame.new(-12441.59, 331.49, -7676.20)
        if cStep == 0 then
            return IS.AttackMobsByList(
                hrp,
                hum,
                { "Forest Pirate" },
                CFrame.new(-13246, 332, -7625),
                "[Citizen Quest - Bước 1/3: Hạ 50 Forest Pirate]",
                { Name = "CitizenQuest", Id = 1, Lv = 1800, NpcCF = citizenCF }
            )
        elseif cStep == 1 then
            local capEle = IS.FindAliveMobFromList({ "Captain Elephant" }, true)
            if capEle then
                return IS.AttackMobsByList(
                    hrp,
                    hum,
                    { "Captain Elephant" },
                    CFrame.new(-13376, 319, -8423),
                    "[Citizen Quest - Bước 2/3: Hạ Boss Captain Elephant]",
                    { Name = "CitizenQuest", Id = 1, Lv = 1800, NpcCF = citizenCF }
                )
            else
                local eleCF = CFrame.new(-13376, 319, -8423)
                if (hrp.Position - eleCF.Position).Magnitude > 30 then
                    IS.CapEleArriveTick = nil
                    CurrentFarmStatus = "[Citizen Quest] 🐘 Đang bay tới vị trí Boss Captain Elephant..."
                    TweenTo(eleCF)
                    return true
                else
                    IS.CapEleArriveTick = IS.CapEleArriveTick or tick()
                    if tick() - IS.CapEleArriveTick >= 3.5 and IsAutoHopEnabled() and HopServer and not IS.IsHoldingProtectedItem() then
                        IS.CapEleArriveTick = tick()
                        HopServer("Boss Captain Elephant chưa hồi sinh (Citizen Quest) -> Đang đổi server...")
                        return true
                    else
                        CurrentFarmStatus = "[Citizen Quest] 🐘 Đang đợi Boss Captain Elephant hồi sinh..."
                        return true
                    end
                end
            end
        elseif cStep == 2 then
            local hatWallCF = CFrame.new(-12513.8, 336.17, -9872.91)
            CurrentFarmStatus = "[Citizen Quest - Bước 3/3] Đang bay vào phòng bí mật lấy mũ Musketeer Hat..."
            TweenTo(hatWallCF)
            IS.LastCitizenCheck = 0
            return true
        elseif cStep == 3 then
            if now - (IS.LastKenStatusCheck or 0) >= 30.0 then
                IS.LastKenStatusCheck = now
                pcall(function()
                    local st = ReplicatedStorage.Remotes.CommF_:InvokeServer("KenTalk", "Status")
                    if type(st) == "string" then
                        local num = tonumber((string.gsub(st, "%D", "")))
                        if num then IS.KenExp = num end
                    end
                end)
            end

            local beli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
            if (IS.KenExp or 0) >= 5000 and beli >= 5000000 then
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("KenTalk2", "Start")
                end)
                if IS.HasItem("Fruit Bowl") or (IS.HasItem("Apple") and IS.HasItem("Banana") and IS.HasItem("Pineapple")) then
                    CurrentFarmStatus = "[Instinct V2] 👁️ Đã đủ 3 loại Quả & $5,000,000 -> Đang đổi Fruit Bowl & nâng cấp Ken Haki V2..."
                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("CitizenQuestProgress", "Citizen")
                        task.wait(0.2)
                        local buyRes = ReplicatedStorage.Remotes.CommF_:InvokeServer("KenTalk2", "Buy")
                        if buyRes then
                            IS.InstinctV2Done = true
                        end
                    end)
                    IS.InstinctV2Done = true
                    return true
                else
                    local fruitSpawners = {
                        { Spawner = "AppleSpawner", Fruit = "Apple" },
                        { Spawner = "BananaSpawner", Fruit = "Banana" },
                        { Spawner = "PineappleSpawner", Fruit = "Pineapple" },
                    }
                    for _, fs in ipairs(fruitSpawners) do
                        if not IS.HasItem(fs.Fruit) then
                            local spObj = workspace:FindFirstChild(fs.Spawner)
                            local fTool = spObj and spObj:FindFirstChildOfClass("Tool")
                            local fHandle = fTool and fTool:FindFirstChild("Handle")
                            if fHandle then
                                CurrentFarmStatus = "[Instinct V2] 🍍 Đang bay nhặt " .. fs.Fruit .. " làm nhiệm vụ Hungry Man..."
                                if (hrp.Position - fHandle.Position).Magnitude > 6 then
                                    TweenTo(fHandle.CFrame)
                                else
                                    hrp.CFrame = fHandle.CFrame
                                    if firetouchinterest then
                                        pcall(function()
                                            firetouchinterest(hrp, fHandle, 0)
                                            firetouchinterest(hrp, fHandle, 1)
                                        end)
                                    end
                                end
                                return true
                            end
                        end
                    end
                end
            end
        end
    end

    -- =========================================================================
    -- MỐC 7: AUTO DOJO TRAINER QUEST (8 ĐAI VÕ ĐƯỜNG RỒNG HYDRA ISLAND - SEA 3)
    -- Khi Dragon Talon >= 500 Mastery & hoàn thành tiến độ Đai -> Tự tới Dojo Trainer nhận Đai mới
    -- =========================================================================
    local dojoEnabled = true
    if getgenv().SettingFarm then
        local dj = getgenv().SettingFarm["Dojo Trainer"]
        if dj == nil then dj = getgenv().SettingFarm.DojoTrainer end
        if dj == nil then dj = getgenv().SettingFarm["Auto Dojo"] end
        if dj == false or (type(dj) == "table" and dj["Enabled"] == false) then
            dojoEnabled = false
        end
    end
    if dojoEnabled and (World3 or CurrentSeaNum == 3) and IS.GetMastery("Dragon Talon") >= 500 and not IS.DojoBlackBeltDone then
        local dqData = IS.DojoQuestData
        local dq = (type(dqData) == "table" and type(dqData.Quest) == "table") and dqData.Quest or nil
        if dq and tonumber(dq.Progress or 0) >= tonumber(dq.Goal or 1) then
            local dojoCF = CFrame.new(5868.45, 1211.78, 868.82)
            CurrentFarmStatus = "[Dojo Trainer] 🥋 Đã hoàn thành nhiệm vụ Đai " .. tostring(dq.BeltName or "") .. " -> Đang tới Dojo Trainer nhận Đai..."
            if (hrp.Position - dojoCF.Position).Magnitude > 10 then
                TweenTo(dojoCF)
            else
                pcall(function()
                    local net = ReplicatedStorage:FindFirstChild("Modules")
                        and ReplicatedStorage.Modules:FindFirstChild("Net")
                        and ReplicatedStorage.Modules.Net:FindFirstChild("RF/InteractDragonQuest")
                    if net then
                        net:InvokeServer({ NPC = "Dojo Trainer", Command = "ClaimQuest" })
                    end
                end)
                IS.LastDojoCheck = 0
                IS.DojoQuestData = nil
            end
            return true
        end
    end

    -- =========================================================================
    -- MỐC 7.1: KIẾM HUYỀN THOẠI SEA 2 (TRUE TRIPLE KATANA - TTK: SHISUI, WANDO, SADDI 300 MAS)
    -- YÊU CẦU: "đưa ghép TTK ở cuối cấp farm hết mas cho 3 kiếm"
    -- 1. Từng thanh kiếm (Shisui, Wando, Saddi) phải cày đủ 300 Mastery trước khi ghép
    -- 2. Chỉ quay về Sea 2 ghép TTK khi đã đạt Cuối Cấp (Lv >= 2550) hoặc đang ở Sea 2!
    -- =========================================================================
    if IS.IsTTKEnabled() and not IS.HasItem("True Triple Katana") then
        if not trainingMeleeNow then
            for _, ttkSw in ipairs(IS.TTKSwords) do
                if IS.HasItem(ttkSw) and IS.GetMastery(ttkSw) < 300 then
                    getgenv()._targetSwordName = ttkSw
                    SetSettingWeapon("Sword")
                    V1StyleLookup.EnsureSwordEquipped(ttkSw)
                    -- Trả về false để vòng lặp farm quái bên dưới dùng kiếm này chém lên 300 Mastery
                    return false
                end
            end
        end

        local all3Ready = IS.HasItem("Shisui") and IS.GetMastery("Shisui") >= 300
            and IS.HasItem("Wando") and IS.GetMastery("Wando") >= 300
            and IS.HasItem("Saddi") and IS.GetMastery("Saddi") >= 300
        local beli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0

        if all3Ready and beli >= 2000000 then
            if World2 or CurrentSeaNum == 2 then
                local mmCF = CFrame.new(-2573.8, 306.8, -3956.4)
                CurrentFarmStatus = "[True Triple Katana] ⚔️ Đã đủ 3 kiếm 300 Mas & $2M -> Đang tới Mysterious Man ghép True Triple Katana..."
                if (hrp.Position - mmCF.Position).Magnitude > 12 then
                    TweenTo(mmCF)
                else
                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("MysteriousMan", "1")
                        task.wait(0.2)
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("MysteriousMan", "2")
                    end)
                    task.wait(0.5)
                    IS.RefreshInventory(true)
                end
                return true
            elseif curLv >= 2550 and not trainingMeleeNow and not IS.IsHoldingProtectedItem() and tick() - LastTravelAttempt >= 10 then
                LastTravelAttempt = tick()
                CurrentFarmStatus = "[True Triple Katana] ⚔️ Đạt cuối cấp (Lv 2,550) & đủ 3 kiếm 300 Mas -> Đang về Sea 2 gặp Mysterious Man ghép TTK..."
                if getgenv().StopTween then getgenv().StopTween() end
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("TravelDressrosa")
                end)
                task.wait(2)
                return true
            end
        end
    end

    -- =========================================================================
    -- MỐC 7.2: AUTO LAW RAID (BOSS ORDER - SEA 2: LẤY KIẾM KOKO, MŨ ZEBRA CAP & CORE BRAIN)
    -- =========================================================================
    if (World2 or CurrentSeaNum == 2) and curLv >= 1100 and not IS.IsHoldingProtectedItem() then
        local frags = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Fragments") and plr.Data.Fragments.Value) or 0
        local needLawDrops = (not IS.HasItem("Koko")) or (not IS.HasItem("Zebra Cap")) or (not IS.CyborgUnlocked and IS.CyborgFistInserted)
        local hasMicrochip = IS.HasToolOnPlayer("Microchip")

        if hasMicrochip or (needLawDrops and frags >= 6000 and tick() - (IS.LastLawRaidAttempt or 0) >= 20.0) then
            if not hasMicrochip then
                IS.LastLawRaidAttempt = tick()
                pcall(function()
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("BlackbeardReward", "Microchip", "1")
                    task.wait(0.2)
                    ReplicatedStorage.Remotes.CommF_:InvokeServer("BlackbeardReward", "Microchip", "2")
                end)
            end

            if IS.HasToolOnPlayer("Microchip") then
                local labBtn = workspace:FindFirstChild("Map")
                    and workspace.Map:FindFirstChild("CircleIsland")
                    and workspace.Map.CircleIsland:FindFirstChild("RaidSummon")
                    and workspace.Map.CircleIsland.RaidSummon:FindFirstChild("Button")
                    and workspace.Map.CircleIsland.RaidSummon.Button:FindFirstChild("Main")
                local labCF = (labBtn and labBtn.CFrame) or CFrame.new(-5917.27, 29.0, -5096.81)
                CurrentFarmStatus = "[Auto Law Raid] ⚡ Đã có Microchip -> Đang tới tháp Secret Lab triệu hồi Boss Order..."
                if (hrp.Position - labCF.Position).Magnitude > 10 then
                    TweenTo(labCF)
                else
                    pcall(function() hum:UnequipTools() end)
                    if labBtn then
                        local cd = labBtn:FindFirstChildOfClass("ClickDetector")
                        if cd and fireclickdetector then
                            pcall(function() fireclickdetector(cd) end)
                        end
                    end
                    task.wait(0.8)
                end
                return true
            end
        end
    end

    -- =========================================================================
    -- MỐC 8: 39 QUEST ẨN SEA 1 (FIRST SEA SECRETS - MỞ KHÓA SECRETS MASTER & LV. 3000)
    -- Ở Sea 1 (Lv 650+): Làm hết các quest ẩn sẵn sàng; khi đã đạt Lv 2800+ (xong đồ Sea 3) -> Về Sea 1 hoàn tất 39/39 Sao!
    -- =========================================================================
    if IsSettingGetItem("Secret Quest") and type(IS.SecretQuest39) == "table" then
        if World1 or CurrentSeaNum == 1 then
            local done39 = IS.SecretQuest39.GetSummary()
            if done39 >= 39 then
                IS.SecretQuest39.All39ConfirmedDone = true
            elseif curLv >= 650 then
                if IS.SecretQuest39.DoStep(curLv >= 2800) then
                    return true
                end
            end
        elseif curLv >= 2800 and not IS.SecretQuest39.All39ConfirmedDone and not IS.IsHoldingProtectedItem() and tick() - LastTravelAttempt >= 10 then
            LastTravelAttempt = tick()
            CurrentFarmStatus = "[39 Quest Ẩn Sea 1] Đã đạt Lv. " .. tostring(curLv) .. " & xong mục tiêu Sea 3 -> Đang về Sea 1 hoàn tất 39 Quest Ẩn (Lv. 3000)..."
            if getgenv().StopTween then getgenv().StopTween() end
            pcall(function()
                ReplicatedStorage.Remotes.CommF_:InvokeServer("TravelMain")
            end)
            task.wait(2)
            return true
        end
    end

    -- =========================================================================
    -- MỐC 9: TỰ ĐỘNG LUYỆN FULL SKILL VŨ KHÍ CHỦ LỰC (CDK 375, SHARK ANCHOR 350, TTK 350, SKULL GUITAR 300, MIDNIGHT BLADE 325, RENGOKU 350, KOKO 350)
    -- Khi không còn bận luyện Võ V1/V2 -> Tự trang bị từng Vũ Khí Chủ Lực chưa đủ Mastery để cày mở khóa 100% kỹ năng (Z, X)!
    -- =========================================================================
    local activeMeleeTarget = V1StyleLookup.GetActiveTargetStyle()
    if not activeMeleeTarget then
        local foundUnmasteredWeapon = false
        for _, wp in ipairs(IS.MasteryWeapons) do
            if IS.HasItem(wp.Name) and IS.GetMastery(wp.Name) < wp.TargetMas then
                foundUnmasteredWeapon = true
                if not IS.HasToolOnPlayer(wp.Name) then
                    pcall(function()
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("LoadItem", wp.Name)
                    end)
                end
                getgenv()._targetSwordName = wp.Name
                SetSettingWeapon(wp.WeaponType or "Sword")
                break
            end
        end
        if not foundUnmasteredWeapon and getgenv()._targetSwordName then
            getgenv()._targetSwordName = nil
            SetSettingWeapon("Melee")
        end
    end

    return false
end

