    H.RunFishingCycle = function()
        pcall(function()
            local ch = plr.Character
            local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
            local rod = H.DetectRod()
            if not hrp or not rod then return end
            if rod.Parent == plr.Backpack then
