                if hum then hum:EquipTool(rod) end
                task.wait(0.4)
                return
            end
            local fishReq = ReplicatedStorage:FindFirstChild("FishReplicated") and ReplicatedStorage.FishReplicated:FindFirstChild("FishingRequest")
            if not fishReq then return end
            local st = rod:GetAttribute("ServerState")
            if not st or st == "ReeledIn" then
                fishReq:InvokeServer("StartCasting")
                task.wait(0.6)
                local castPos = hrp.Position + hrp.CFrame.LookVector * 35
                fishReq:InvokeServer("CastLineAtLocation", castPos, 98, true)
            elseif st == "Biting" or st == "SpawnFishOnBob" then
