	}

	H.GetHiddenProgress = function(arg)
		local flag

		if arg then
			flag = arg
		else
			local checked = H.HiddenEvent.checked
			flag = os.clock() - checked > 15
		end

		if flag then
			H.HiddenEvent.checked = os.clock()

			local ok, result = pcall(function()
				return ReplicatedStorage.Modules.Net["RF/RequestBonusMomentReplication"]:InvokeServer({ Type = "GetMomentProgress" })
			end)

			if ok and type(result) == "table" and type(result.Data) == "table" then
				for k, v in pairs(result.Data) do
					if type(v) == "table" and v.Completed == true then
						result.Data[k] = true
					end
				end
				H.ReportHiddenDone(H.HiddenEvent.progress, result.Data)
				H.HiddenEvent.progress = result.Data
			end
		end

		return H.HiddenEvent.progress
	end

	H.ReportHiddenDone = function(arg, arg2)
		local done = 0

		for k, v6 in pairs(arg2) do
			if v6 == true or (type(v6) == "table" and v6.Completed) then
				done = done + (1)
				local flag = type(arg) == "table" and arg[k]

				if flag ~= true and (type(flag) ~= "table" or not flag.Completed) then
					H.HiddenNotify((tostring(k):match("([^/]+)$") or tostring(k)) .. " completed", "done" .. tostring(k), "reward", { SubContent = done .. "/39 secret quests", Duration = 8 })
				end
			end
		end

		H.HiddenEvent.done = done
	end

	H.HiddenNotify = function(arg, key, arg2, arg3)
