		H.HiddenEvent.lastNotify[key] = os.clock()
		local tbl9 = arg3 or {}
		tbl9.Key = key
		H.VxezeNotify("Hidden Event", arg, arg2 or "info", tbl9)
	end

	H.SetHiddenStep = function(step)
