	H.HiddenHold = function(arg)
		local humanoidRootPart = H.localPlayer.Character and H.localPlayer.Character:FindFirstChild("HumanoidRootPart")
		if not humanoidRootPart then
			return
		end

		if (humanoidRootPart.Position - arg.Position).Magnitude > 3 then
			H.HiddenMove(arg)
			return
		end

		if H.HiddenEvent.anchored ~= humanoidRootPart then
			humanoidRootPart.AssemblyLinearVelocity = Vector3.zero
			humanoidRootPart.Anchored = true
			H.HiddenEvent.anchored = humanoidRootPart
		end

		H.HiddenEvent.holdTime = tick()
		H.TweenHoldUntil = tick() + 1
	end

	H.SweepHiddenTrigger = function(arg, arg2, arg3)
		H.HiddenRelease()
		local character = H.localPlayer.Character
		local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
		character = character and character:FindFirstChildOfClass("Humanoid")
		if not humanoidRootPart or not character then
			return
		end
		H.HiddenEvent.walking = true
		local floatForce = humanoidRootPart:FindFirstChild("FloatForce")
		local maxForce = floatForce and floatForce.MaxForce

		if floatForce then
			floatForce.MaxForce = Vector3.zero
		end

		for k in pairs(H.NoclipChanged) do
			if k.Parent then
				k.CanCollide = true
			end
		end

		table.clear(H.NoclipChanged)
		humanoidRootPart.CFrame = CFrame.new(arg2)
		humanoidRootPart.AssemblyLinearVelocity = Vector3.zero
		task.wait(0.4)
		character:MoveTo(arg3)
		local now = tick()

		while true do local __brk = false repeat 
			task.wait(0.1)
			H.tbl3.LastCall = tick()
			H.TweenHoldUntil = tick() + 1
			if not ((humanoidRootPart.Position - arg3).Magnitude < 6 or tick() - now > 6 or not humanoidRootPart.Parent) then
				break
			end
			__brk = true break
		until true if __brk then break end end

		if floatForce and floatForce.Parent then
			floatForce.MaxForce = maxForce
		end

		H.HiddenEvent.walking = false
	end

