	H.BuyHiddenFishingGear = function(arg)
		local selectBait = arg or H.Settings["Select Bait"] or "Basic Bait"
		if H.DetectRod() and H.CountFishingBait(selectBait) > 0 then
			return true
		end

		if not H.GoToFisherman() then
			return false
		end

		if tick() - (H.HiddenEvent.rodAsked or 0) < 20 then
			return H.DetectRod() ~= nil
		end
		H.HiddenEvent.rodAsked = tick()

		if not H.DetectRod() then
			H.TalkFishermanDialogue({ "Thanks" }, function()
				return H.DetectRod() ~= nil
			end, 15)
		end

		if H.DetectRod() and H.CountFishingBait(selectBait) <= 0 then
			local v6 = H.CountFishingBait(selectBait)

			H.TalkFishermanDialogue({ "Bait", selectBait, "Craft", "Buy", "Confirm", "Yes" }, function()
				return H.CountFishingBait(selectBait) > v6
			end, 20)
		end

		return H.DetectRod() ~= nil
	end

	H.RunHiddenFishing = function()
		if not H.DetectRod() then
			if not H.BuyHiddenFishingGear() then
				H.HiddenNotify("Getting a Fishing Rod from the Fisherman for Chef's Kiss", "chefrod", "start")
				return "Get a Fishing Rod from the Fisherman"
			end
			H.DetectRod()
		end

		local selectBait = H.Settings["Select Bait"] or "Basic Bait"
		local fishingData = H.localPlayer.Data:FindFirstChild("FishingData")
		fishingData = fishingData and fishingData:GetAttribute("SelectedBait")

		if not fishingData or fishingData == "None" then
			if H.CountFishingBait(selectBait) > 0 then
				H.CommF:InvokeServer("LoadItem", selectBait, { "Usables" })
				task.wait(0.5)
			elseif not H.BuyHiddenFishingGear(selectBait) then
				return "Buy fishing bait from the Fisherman"
			end
		end

		local fishSpot = H.HiddenEvent.fishSpot

		if fishSpot then
			fishSpot = tick() - (H.HiddenEvent.fishSpotAt or 0) > 120
		end

		if fishSpot then
			H.HiddenEvent.fishSpot = nil
		end

		if not H.HiddenEvent.fishSpot then
			local v6 = H.HiddenEvent
			local v7 = H.HiddenEvent
			local v8, v9 = H.FindHiddenWaterSpot()
			v6.fishSpot = v8
			v7.fishWater = v9
			H.HiddenEvent.fishSpotAt = tick()
		end

		local fishSpot2 = H.HiddenEvent.fishSpot
		if not fishSpot2 then
			return "Looking for a shore to fish from"
		end

		if H.localPlayer:DistanceFromCharacter(fishSpot2) > 10 then
			H.HiddenMove(CFrame.new(fishSpot2, H.HiddenEvent.fishWater or fishSpot2 + Vector3.new(0, 0, 5)))
			return "Go to the shore to fish"
		end
		H.HiddenHold(CFrame.new(fishSpot2, H.HiddenEvent.fishWater or fishSpot2 + Vector3.new(0, 0, 5)))
		pcall(H.RunFishingCycle)
		task.wait(0.4)
		return "Fishing at the shore for Chef's Kiss"
	end

