	H.PrepareHiddenChef = function(arg)
		if arg["Sea1/Pirate Village/Chef's Kiss"] == true then
			return
		end

		if H.CountHiddenMaterial("Yeti Fur") < 1 then
			H.HiddenEvent.current = "Chef's Kiss"
			H.HiddenEvent.prepUntil = tick() + 60
			H.SetHiddenStep(H.FarmHiddenMaterial("Yeti Fur", 1) or "Farm Yeti Fur for Chef's Kiss")
			return true
		end

		if H.GetHiddenFishCount() < 1 then
			H.HiddenEvent.current = "Chef's Kiss"
			H.HiddenEvent.prepUntil = tick() + 60
			H.SetHiddenStep(H.RunHiddenFishing() or "Fishing for Chef's Kiss")
			return true
		end

		H.HiddenEvent.prepUntil = nil
	end

	H.GatherChefIngredients = function()
		local text = H.HiddenEvent.chefMissing and H.HiddenEvent.chefMissing.text or ""
		local v6 = string.lower(text)

		for k in pairs(H.HiddenMaterialMobs) do
			if string.find(text, k, 1, true) and H.CountHiddenMaterial(k) < 1 then
