	H.OnHiddenEnemyAnimation = function(c)if c.Looped then return;end;local n,L=c.Animation and c.Animation.AnimationId or"",tick();local U=H.HiddenDodge.animations[n];if not U or L-U.since>20 then U={count=0,since=L};H.HiddenDodge.animations[n]=U;end;U.count=U.count+1;if U.count>4 then return;end;task.wait(0.05);if c.IsPlaying and c.Length>=0.9 then H.TriggerHiddenDodge(c.Length/math.max(c.Speed,0.1)+0.3);end;end
