	H.WatchHiddenEnemy = function(target)
		if H.HiddenDodge.target == target then
			return
		end
		H.StopHiddenDodge()
		H.HiddenDodge.target = target
		local humanoid = target:FindFirstChildOfClass("Humanoid")

		if humanoid then
			humanoid = humanoid:FindFirstChildOfClass("Animator") or humanoid
		end

		if humanoid then
			H.HiddenDodge.connection = humanoid.AnimationPlayed:Connect(H.OnHiddenEnemyAnimation)
		end

		if not H.HiddenDodge.watching then
			H.HiddenDodge.watching = true
			workspace.Enemies.DescendantAdded:Connect(H.OnHiddenEnemySkill)
		end
	end

