		H.HiddenEvent.rewardSeen = H.HiddenEvent.rewardSeen or {}

		if typeof(target) == "Vector3" then
			H.HiddenEvent.rewardSeen[tostring(target)] = { position = target, time = tick() }
		end

		local rewardLock = H.HiddenEvent.rewardLock
		local v7 = rewardLock and H.HiddenEvent.rewardSeen[tostring(rewardLock)]
		local flag = not v7
		local flag2

		if flag then
			flag2 = flag
		else
			local time_ = v7.time
			flag2 = tick() - time_ > 8
		end

		if not flag2 then
			flag2 = tick() < (H.HiddenEvent.skipped["Reward:" .. tostring(rewardLock)] or 0)
		end

		if flag2 then
			local v8 = nil
			rewardLock = nil

			for k, v9 in pairs(H.HiddenEvent.rewardSeen) do
				local v10 = H.localPlayer:DistanceFromCharacter(v9.position)
				local time_ = v9.time
				local flag3 = tick() - time_ <= 8

				if flag3 then
					flag3 = tick() >= (H.HiddenEvent.skipped["Reward:" .. k] or 0)
				end

				if flag3 and (not v8 or v10 < v8) then
					rewardLock = v9.position
					v8 = v10
				end
			end

			H.HiddenEvent.rewardLock = rewardLock
		end

		if typeof(rewardLock) ~= "Vector3" then
			return false
		end
		local reward = tostring(rewardLock)
		local v8 = H.FindHiddenNpc(rewardLock, 15)
		H.HiddenEvent.current = "Claim Reward"
		H.SetHiddenStep("Talk to " .. (v8 and v8.Name or "the quest giver") .. " for reward")
		if not v8 then
			H.HiddenGoTo(rewardLock + Vector3.new(0, 5, 0), 20)
			return true
		end

		if H.HiddenSettle(rewardLock + Vector3.new(0, 1.5, 4), 10) then
			H.HiddenEvent.dialogueBusy = tick() + 12

			pcall(function()
				local v9 = H.HiddenModules.NpcList.List[v8.Name].DialogueCallback()

				if type(v9) == "table" and type(v9.Get) == "function" then
					v9:Get()
				end
			end)

			task.wait(1)
			local v9 = H.HiddenModules.Guide.getRewardTracker()
			local v10 = H.GetHiddenDialogueKey(v8.Name)

			if v10 and v9 and v9.Options and v9.Options.Target == rewardLock then
				H.HiddenModules.Guide.interactQuestGiver(v10)
			end

			H.HiddenEvent.checked = 0
			H.HiddenEvent.rewardSeen[tostring(rewardLock)] = nil
			H.HiddenEvent.rewardLock = nil
			local flag3 = false

			for i_ = 1, 8 do
				task.wait(0.5)
				local v11 = H.HiddenModules.Guide.getRewardTracker()
				flag3 = flag3 or v11 and v11.Options and v11.Options.Target == rewardLock
			end

			if flag3 then
				H.HiddenEvent.skipped["Reward:" .. reward] = tick() + 300
				H.HiddenNotify("Could not claim the reward from " .. v8.Name .. ", retry later", nil, "warning")
			else
				H.HiddenNotify("Claimed reward from " .. v8.Name, nil, "reward")
			end
		end

		return true
	end

