		end
		local v6 = H.FindHiddenFruitTool()

		if not v6 then
			local v7 = H.TakeFruitInventory()
			if not v7 then
				return false, "no Blox Fruit in backpack or inventory, skipping this quest"
			end
			H.VxezeNotify("Hidden Event", "Loading " .. v7 .. " from inventory to eat for " .. tostring(arg), "info", { Key = "hiddenloadfruit" })
			game:GetService("ReplicatedStorage").Remotes.CommF_:InvokeServer("LoadFruit", v7)
			local now = tick()

			while true do local __brk = false repeat 
				task.wait(0.3)
				v6 = H.FindHiddenFruitTool()
				if not (v6 or tick() - now > 4) then
					break
				end
				__brk = true break
			until true if __brk then break end end

			if not v6 then
				return false, "could not load a Blox Fruit from inventory, skipping this quest"
			end
		end

		pcall(function()
			H.localPlayer.Character.Humanoid:EquipTool(v6)
		end)

		task.wait(0.4)
		local eatRemote = v6:FindFirstChild("EatRemote")

		if eatRemote then
			pcall(function()
				eatRemote:InvokeServer("Eat")
			end)
		end

		local now = tick()

		while true do local __brk = false repeat 
			task.wait(0.3)
			if not (H.localPlayer.Data.DevilFruit.Value ~= "" or tick() - now > 4) then
				break
			end
			__brk = true break
		until true if __brk then break end end

		if H.localPlayer.Data.DevilFruit.Value == "" then
			return false, "could not eat the Blox Fruit, skipping this quest"
		end
		H.VxezeNotify("Hidden Event", "Ate " .. tostring(H.localPlayer.Data.DevilFruit.Value) .. " for " .. tostring(arg), "success", { Key = "hiddenatefruit" })
		task.wait(1.5)
		if not H.GetHiddenFruitM1() then
			return false, "the eaten fruit has no M1 attack"
		end
		return true
	end

