	H.GetHiddenRaidHint = function()
		local flag = not H.HiddenEvent.hint

		if not flag then
			local time_ = H.HiddenEvent.hint.time
			flag = tick() - time_ > 20
		end

		if flag then
			local ok, result = pcall(function()
				return ReplicatedStorage.Modules.Net["RF/RequestNextRaidHint"]:InvokeServer()
			end)

			H.HiddenEvent.hint = { time = tick(), data = ok and type(result) == "table" and result or {} }

			if H.HiddenEvent.hint.data.Island and tonumber(H.HiddenEvent.hint.data.Seconds) then
				H.HiddenEvent.expectedBoss = {
					key = os.date("!%Y%m%d%H", os.time() + tonumber(H.HiddenEvent.hint.data.Seconds) + 5),
					hint = H.HiddenEvent.hint.data,
				}
			end
		end

		local expectedBoss = H.HiddenEvent.expectedBoss
		if not H.HiddenEvent.hint.data.Island and expectedBoss and expectedBoss.key == os.date("!%Y%m%d%H") and os.date("!*t").min < 8 then
			return { Island = expectedBoss.hint.Island, Boss = expectedBoss.hint.Boss, State = "Triggered", Seconds = 0 }
		end
		return H.HiddenEvent.hint.data
	end

