	H.HitHiddenTriggers = function(arg, arg2)
		local v6 = nil
		local v7 = nil

		for _, v8 in ipairs(arg) do
			local descendants = v8 and v8:GetDescendants() or {}
			table.insert(descendants, v8)

			for _, descendant in ipairs(descendants) do
				if descendant:IsA("BasePart") and descendant:HasTag("M1HitRegistry") and (arg2 or descendant.Transparency < 1) then
					local v9 = H.localPlayer:DistanceFromCharacter(descendant.Position)

					if not v6 or v9 < v6 then
						v6 = v9
						v7 = descendant
					end
				end
			end
		end

		if v7 then
			H.HitHiddenPart(v7)
			return true
		end
	end

	H.GetHiddenBossHour = function()
		local v6 = os.date("!%Y%m%d%H")

		if not H.HiddenEvent.bossHour or H.HiddenEvent.bossHour.key ~= v6 then
			H.HiddenEvent.bossHour = { key = v6, checked = {}, active = nil }
			local expectedBoss = H.HiddenEvent.expectedBoss

			if expectedBoss and expectedBoss.key == v6 then
				for _, v7 in ipairs(H.HiddenQuests) do
					if v7.BossNames and not H.IsHiddenBossHinted(expectedBoss.hint, v7.HintIsland, v7.BossNames) then
						H.HiddenEvent.bossHour.checked[v7.Name] = true
					end
				end
			end
		end

		return H.HiddenEvent.bossHour
	end

	H.IsHiddenBossHinted = function(arg, arg2, arg3)
		if not arg.Island then
			return false
		end

		if table.find(arg3, arg.Boss) then
			return true
		end

		for _, v6 in ipairs(H.HiddenQuests) do
			if v6.BossNames and table.find(v6.BossNames, arg.Boss) then
				return false
			end
		end

		return arg.Island == arg2
	end

	H.IsHiddenHourUseful = function(arg)
		local v6 = H.GetHiddenRaidHint()
		if not v6 or not v6.Island or not v6.Boss then
			return true
		end

		for _, v7 in ipairs(H.HiddenQuests) do repeat 
			if arg["Sea1/" .. v7.Island .. "/" .. v7.Name] ~= true then
				if v7.BossNames then
					if H.IsHiddenBossHinted(v6, v7.HintIsland or v7.Island, v7.BossNames) then
						return true
					end
					break
				end

				if v6.Island == (v7.HintIsland or v7.Island) then
					return true
				end
			end
		until true end

		return false
	end

	H.ListHiddenServers = function()
		local tbl9 = {}

		local ok, result = pcall(function()
			return ReplicatedStorage.__ServerBrowser:InvokeServer(1)
		end)

		if ok and type(result) == "table" then
			for k in pairs(result) do
				if type(k) == "string" then
					tbl9[k] = true
				end
			end
		end

		return tbl9
	end

	H.QueueHiddenReload = function()
		return true
	end

	H.HopHiddenServer = function(reason)
		if HopServer and not (V1StyleLookup.ItemsSystem and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem()) then
			HopServer(reason or "Hop server tìm Boss")
			return true
		end
		H.HiddenEvent.hopped = H.HiddenEvent.hopped or {}
		H.QueueHiddenReload()
		local v6 = H.ListHiddenServers()

		for i_ = 1, 2 do
			for k in pairs(v6) do
				if k ~= game.JobId and not H.HiddenEvent.hopped[k] then
					H.HiddenEvent.hopped[k] = true
					H.HiddenNotify("Dead boss hour, switching server", "hop" .. k, "travel")

					local function fn()
						ReplicatedStorage.__ServerBrowser:InvokeServer("teleport", k)
					end

					pcall(fn)
					return true
				end
			end

			H.HiddenEvent.hopped = {}
		end

		return false
	end

	H.RunChefsKiss = function(arg)
		local chefMissing = H.HiddenEvent.chefMissing
		local flag

		if chefMissing then
			local time_ = H.HiddenEvent.chefMissing.time
			flag = tick() - time_ < 300
		else
			flag = chefMissing
		end

		if flag then
			local v6 = H.GatherChefIngredients(arg)
			if v6 then
				return v6
			end
			H.HiddenEvent.chefMissing = nil
			H.HiddenEvent.cooked = 0
		end

		local cauldronMoment = workspace.Map.Pirate:FindFirstChild("Cauldron_Moment")

		if cauldronMoment then
			cauldronMoment = cauldronMoment:FindFirstChild("Cauldron") or cauldronMoment:FindFirstChildWhichIsA("BasePart", true)
		end

		local flag2 = not cauldronMoment

		if not flag2 then
			flag2 = tick() - (H.HiddenEvent.cooked or 0) <= 15
		end

		if flag2 then
			return
		end

		if not H.HiddenSettle(cauldronMoment:GetPivot().Position + Vector3.new(0, 3, 6), 10) then
			return "Go to the tavern cauldron"
		end
		H.HiddenEvent.cooked = tick()
		local response = arg:InvokeServer("OpenCauldron")
		if type(response) ~= "table" then
			return "Waiting for the cauldron to open"
		end
		local tbl9 = {}
		local v6 = ipairs
		local slots = response.Slots or {}

		for _, slot in v6(slots) do
			if not response.Placed[slot] then
				local v7 = pairs
				local owned = response.Owned and response.Owned[slot] or {}
				local flag3 = nil

				for k, v8 in v7(owned) do
					if not (v8 > 0) then
						flag3 = nil
					else
						local response2 = arg:InvokeServer("Insert", k)

						if type(response2) == "table" then
							flag3 = true
							response = response2
							break
						else
							flag3 = nil
						end
					end
				end

				if not flag3 then
					table.insert(tbl9, tostring(response.Examples and response.Examples[slot] and response.Examples[slot][1] or slot))
				end
			end
		end

		if #tbl9 > 0 then
			arg:FireServer("CloseCauldron")
			H.HiddenNotify("Chef's Kiss needs: " .. table.concat(tbl9, ", "), "chefmissing", "warning")
			H.HiddenEvent.chefMissing = { time = tick(), text = "Chef's Kiss needs " .. table.concat(tbl9, ", "), needs = response.Slots }
			return H.HiddenEvent.chefMissing.text, true
		end

		local response2 = arg:InvokeServer("Cook")
		arg:FireServer("CloseCauldron")
		H.HiddenEvent.awakened = H.HiddenEvent.awakened or {}

		if response2 == "Cooked" then
			H.HiddenEvent.awakened["Chef's Kiss"] = tick()
			H.HiddenNotify("Chef's Kiss: recipe cooked, the Chef is awakening", "chefcooked", "success")
		end

		return "Cook the Chef's recipe"
	end

	H.CreateBossQuest = function(arg, active, arg2, arg3, arg4, arg5)
		return {
			Island = arg,
			Name = active,
			HintIsland = arg2,
			BossNames = arg3,
			RetryDelay = 300,
			Precheck = function(arg6)
				local v6 = H.GetHiddenBossHour()
				local flag = H.IsHiddenBossHinted(arg6, arg2, arg3) or v6.active == active
				local flag2

				if flag then
					flag2 = flag
				else
					flag2 = tick() - ((H.HiddenEvent.announced or {})[active] or 0) < 400
				end

				if flag2 then
					return true
				end

				if v6.active then
					return false, "awakened boss is on " .. tostring(v6.active) .. " this hour"
				end
				return false, "waiting for the XX:50 boss hint"
			end,
			Run = function(arg6)
				local v6 = H.GetHiddenIsland(arg)
				local position = v6 and v6.World.Position or H.localPlayer.Character:GetPivot().Position
				H.FindHiddenBoss(arg3, position)
				H.HiddenEvent.awakened = H.HiddenEvent.awakened or {}
				local v7 = H.FindAwakenedBoss(position, arg3)

				if v7 then
					H.GetHiddenBossHour().active = active
