					H.KillHiddenEnemy(v7)
					H.HiddenEvent.checked = 0
					return "Defeat the awakened " .. v7.Name
				end

				local v8 = H.GetHiddenBossHour()
				local v9 = H.GetHiddenRaidHint()
				local v10 = H.IsHiddenBossHinted(v9, arg2, arg3)

				if arg6.Active and not v10 and os.date("!*t").min >= 12 then
					v8.checked[active] = true
					v8.active = nil
					if H.AllowParkIdle and IsAutoHopEnabled() and HopServer and not (V1StyleLookup.ItemsSystem and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem()) then
						HopServer("Boss " .. tostring(arg3[1]) .. " đã qua giờ -> Đang đổi server...")
					end
					return arg3[1] .. " window passed this hour, wait for XX:50 hint", true
				end

				if arg6.Active then
					v8.active = active

					if arg4 then
						local v11, v12 = arg4(arg6)
						if v11 then
							return v11, v12
						end
					end

					if H.AllowParkIdle and IsAutoHopEnabled() and HopServer and not (V1StyleLookup.ItemsSystem and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem()) then
						HopServer("Đang đợi boss " .. tostring(arg3[1]) .. " -> Đang đổi server...")
					end
					return "Waiting for " .. arg3[1] .. " to awaken", true
				end

				if v8.active == active then
					v8.active = nil
				end

				if v10 then
					local num = tonumber(v9.Seconds)
					local flag = arg5

					if arg5 then
						flag = v9.State == "Triggered"

						if not flag then
							flag = (num or math.huge) <= 0
						end
					end

					if flag then
						local v11, v12 = arg5(arg6)
						if v11 then
							return v11, v12
						end
					end

					if H.AllowParkIdle and IsAutoHopEnabled() and HopServer and not (V1StyleLookup.ItemsSystem and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem()) then
						HopServer("Boss " .. tostring(arg3[1]) .. " chưa hồi sinh (" .. (num and H.FormatMagnetTime(num) or "chưa ra") .. ") -> Đang đổi server...")
					end
					return arg3[1] .. " stirs on " .. arg .. (num and " in ~" .. H.FormatMagnetTime(num) or " soon"), (num or 0) > 180
				end

				v8.checked[active] = true
				if H.AllowParkIdle and IsAutoHopEnabled() and HopServer and not (V1StyleLookup.ItemsSystem and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem()) then
					HopServer("Không có boss " .. tostring(arg3[1]) .. " giờ này -> Đang đổi server...")
				end
				return "No awakened " .. arg3[1] .. " this hour", true
			end,
		}
	end

