	H.NearestHiddenSpawn = function(arg)
		local playerSpawns = workspace._WorldOrigin:FindFirstChild("PlayerSpawns")
		local v6, v7, v8 = ipairs(playerSpawns and playerSpawns:GetDescendants() or {})
		local v9 = nil
		local v10 = nil

		for _, v11 in v6, v7, v8 do
			if v11:IsA("BasePart") then
				local magnitude = (v11.Position - arg).Magnitude

				if not v9 or magnitude < v9 then
					v9 = magnitude
					v10 = v11
				end
			end
		end

		return v10 and v10.Position + Vector3.new(0, 4, 0), v9
	end

	H.PickHiddenParkSpot = function(arg)
		local tbl9 = {}

		for _, v6 in ipairs(H.HiddenQuests) do
			local island = H.HiddenPresenceQuests[v6.Name] and v6.Island

			if island and arg["Sea1/" .. v6.Island .. "/" .. v6.Name] ~= true and (not v6.Requires or arg[v6.Requires] == true) and not table.find(tbl9, island) then
				table.insert(tbl9, island)
			end
		end

		local park = H.HiddenEvent.park
		local flag

		if park then
			flag = not table.find(tbl9, park.island)

			if not flag then
				local since = park.since
				flag = tick() - since > 900
			end
		else
			flag = park
		end

		if flag then
			local n = (table.find(tbl9, park.island) or 0) % math.max(#tbl9, 1) + 1
			park = tbl9[n] and { island = tbl9[n], since = tick() } or nil
		elseif not park and #tbl9 > 0 then
			park = { island = tbl9[1], since = tick() }
		end

		H.HiddenEvent.park = park

		if park then
			local v6 = H.GetHiddenIsland(park.island)

			if v6 then
				local v7, v8 = H.NearestHiddenSpawn(v6.World.Position)
				if v7 and v8 < 2500 then
					return v7
				end
				return v6.TeleportPoints[1].Position + Vector3.new(0, 4, 0)
			end
		end

		return H.NearestHiddenSpawn(H.localPlayer.Character:GetPivot().Position) or Vector3.new(-826, 30, 1613)
	end

	H.HiddenSkipFile = "Vxeze Hub/hidden_skip.json"

	H.SaveHiddenSkip = function()
		if type(writefile) ~= "function" then
			return
		end
		local tbl9 = { user = H.localPlayer.UserId, skips = {} }

		for k, v6 in pairs(H.HiddenEvent.skipped) do
			if type(k) == "string" and not k:find("^Reward:") and v6 > tick() then
				local floor = math.floor
				tbl9.skips[k] = os.time() + floor(v6 - tick())
			end
		end

		pcall(function()
			writefile(H.HiddenSkipFile, game:GetService("HttpService"):JSONEncode(tbl9))
		end)
	end

	H.LoadHiddenSkip = function()
		if H.HiddenEvent.skipLoaded then
			return
		end
		H.HiddenEvent.skipLoaded = true

		pcall(function()
			if type(isfile) == "function" and isfile(H.HiddenSkipFile) then
				local data = game:GetService("HttpService"):JSONDecode(readfile(H.HiddenSkipFile))

				if data.user == H.localPlayer.UserId then
					local v6 = pairs
					local skips = data.skips or {}

					for k, skip in v6(skips) do
						local n = skip - os.time()

						if n > 0 and not H.HiddenEvent.skipped[k] then
							H.HiddenEvent.skipped[k] = tick() + n
						end
					end
				end
			end
		end)
	end

	H.HiddenRetryDelay = function(arg)
		local readyAt = H.HiddenEvent.readyAt and H.HiddenEvent.readyAt[arg.Name]
		if readyAt then
			return math.max(readyAt - tick(), 5)
		end
		local retryOverride = H.HiddenEvent.retryOverride and H.HiddenEvent.retryOverride[arg.Name]
		if retryOverride then
			H.HiddenEvent.retryOverride[arg.Name] = nil
			return math.max(retryOverride, 120)
		end
		local retryDelay = arg.RetryDelay or 420
		if H.HiddenAnnounceDriven[arg.Name] then
			return math.max(retryDelay, 3600)
		end
		return retryDelay
	end

	H.OnHiddenAnnouncement = function(arg)
		local v6 = string.lower(tostring(arg))

		for _, v7 in ipairs(H.HiddenAnnouncements) do
			if string.find(v6, v7[1], 1, true) then
				H.HiddenEvent.announced = H.HiddenEvent.announced or {}
				H.HiddenEvent.announced[v7[2]] = tick()
				H.HiddenEvent.skipped[v7[2]] = nil
			end
		end
	end

	H.WatchHiddenAnnouncements = function()
		if H.HiddenEvent.watching then
			return
		end
		H.HiddenEvent.watching = true
		H.HiddenEvent.momentEvent = {}

		ReplicatedStorage.Remotes.BonusMomentsRemoteEvent.OnClientEvent:Connect(function(arg)
			H.HiddenEvent.momentEvent[tostring(arg)] = tick()
		end)

		local notifications = H.localPlayer.PlayerGui:WaitForChild("Notifications", 10)

		if notifications then
			notifications.DescendantAdded:Connect(function(descendant)
				if descendant:IsA("TextLabel") then
					task.wait(0.1)
					H.OnHiddenAnnouncement(descendant.Text)
				end
			end)
		end

		pcall(function()
			game:GetService("TextChatService").MessageReceived:Connect(function(arg)
				if not arg.TextSource then
					H.OnHiddenAnnouncement(arg.Text)
				end
			end)
		end)
	end

	H.CheckHiddenStall = function()
		local current = H.HiddenEvent.current
		local humanoidRootPart = H.localPlayer.Character and H.localPlayer.Character:FindFirstChild("HumanoidRootPart")
		if not current or not humanoidRootPart then
			H.HiddenEvent.stall = nil
			return
		end
		local stall = H.HiddenEvent.stall
		local position = humanoidRootPart.Position
		local parent = not stall or stall.quest ~= current or stall.step ~= H.HiddenEvent.step or (position - stall.position).Magnitude > 25 or H.HiddenEvent.fighting and H.HiddenEvent.fighting.Parent

		if not parent then
			parent = tick() < (H.HiddenEvent.stallGrace or 0)
		end

		local flag

		if parent then
			flag = parent
		else
			flag = tick() - (H.HiddenEvent.momentEvent and H.HiddenEvent.momentEvent[current] or 0) < 20
		end

		local flag2

		if flag then
			flag2 = flag
		else
			flag2 = tick() - (H.HiddenEvent.announced and H.HiddenEvent.announced[current] or 0) < 420
		end

		if flag2 then
			H.HiddenEvent.stall = { quest = current, step = H.HiddenEvent.step, position = position, time = tick() }
			return
		end

		if os.date("!*t").min < 8 and string.find(tostring(H.HiddenEvent.step), "awaken", 1, true) then
			return
		end
		local time_ = stall.time
		if tick() - time_ < 60 then
			return
		end
		H.HiddenEvent.stall = nil
		H.HiddenEvent.skipped[current] = tick() + 120
		H.HiddenEvent.current = nil
		H.HiddenEvent.arrived = nil
		H.HiddenEvent.islandArrived = nil
		H.HiddenEvent.waitingSince = nil
		H.LeaveHiddenCannon()
		pcall(require(ReplicatedStorage.DialogueController).close)
		H.HiddenNotify(current .. " got stuck on \"" .. tostring(stall.step) .. "\", trying another quest", current .. "stall", "warning")
	end

	H.HiddenWakeBoost = function(name)
		H.HiddenEvent.readyBoost = H.HiddenEvent.readyBoost or {}
		return tick() < (H.HiddenEvent.readyBoost[name] or 0)
	end

	H.WakeHiddenQuests = function(progress, hint)
		H.HiddenEvent.waiting = H.HiddenEvent.waiting or {}
		H.HiddenEvent.readyBoost = H.HiddenEvent.readyBoost or {}
		H.HiddenEvent.readyAt = H.HiddenEvent.readyAt or {}
		H.HiddenEvent.wokeMoment = H.HiddenEvent.wokeMoment or {}
		H.HiddenEvent.wakeCheck = H.HiddenEvent.wakeCheck or {}

		local function wake(quest, why)
			if H.HiddenEvent.current == quest.Name then
				return
			end
			H.HiddenEvent.skipped[quest.Name] = nil
			H.HiddenEvent.readyAt[quest.Name] = nil
			H.HiddenEvent.readyBoost[quest.Name] = tick() + 300
			H.HiddenEvent.wakeCheck[quest.Name] = tick() + 60
			H.HiddenNotify(quest.Name .. " is ready (" .. why .. "), going back", quest.Name .. "wake", "found")
		end

		for _, quest in ipairs(H.HiddenQuests) do
			local name = quest.Name
			local key = "Sea1/" .. quest.Island .. "/" .. name
			local skipped = (H.HiddenEvent.skipped[name] or 0) > tick()
			local blocked = H.HiddenEvent.waiting[name] ~= nil or H.HiddenEvent.readyAt[name] ~= nil

			if progress[key] ~= true and skipped and blocked and tick() >= (H.HiddenEvent.wakeCheck[name] or 0) then
				local readyAt = H.HiddenEvent.readyAt[name]
				if readyAt and tick() >= readyAt then
					wake(quest, "timer done")
				else
					local moment = H.GetHiddenMoment(name)
					local up = moment and (not quest.HintIsland or moment.Active)
					if up and H.HiddenEvent.wokeMoment[name] ~= moment then
						H.HiddenEvent.wokeMoment[name] = moment
						wake(quest, "quest appeared")
					elseif not up then
						H.HiddenEvent.wokeMoment[name] = nil
						if quest.Precheck and not readyAt and tick() >= (H.HiddenEvent.precheckAt and H.HiddenEvent.precheckAt[name] or 0) then
							H.HiddenEvent.precheckAt = H.HiddenEvent.precheckAt or {}
							H.HiddenEvent.precheckAt[name] = tick() + 10
							local ok, pass = pcall(quest.Precheck, hint)
							if ok and pass == true then
								wake(quest, "conditions met")
							end
						end
					end
				end
			end
		end
	end

	H.AutoHiddenEvent = function()
		H.WatchHiddenAnnouncements()
		H.LoadHiddenSkip()
		local v6 = H.GetHiddenProgress()
		H.SweepHiddenRemote(v6)
		if H.ClaimHiddenReward() then
			return
		end
		local v7 = H.GetHiddenRaidHint()
		local flag = v7.State == "Arming" or v7.State == "Armed" or v7.State == "Triggered"

		if not flag then
			flag = (tonumber(v7.Seconds) or math.huge) < 300
		end

		local flag2 = v7.State ~= "Triggered"

		if flag2 then
			flag2 = (tonumber(v7.Seconds) or 0) > 180
		end

		pcall(H.WakeHiddenQuests, v6, v7)

		local tbl9 = {}
		local tbl10 = {}
		local tbl11 = {}

		for k, v8 in pairs(v6) do
			local flag3 = v8 == true and string.match(k, "^Sea1/([^/]+)/")

			if flag3 then
				tbl11[flag3] = (tbl11[flag3] or 0) + 1
			end
		end

		for _, v8 in ipairs(H.HiddenQuests) do
			local active = H.GetHiddenMoment(v8.Name)
			local flag3 = v8.Name == "Rescue Hasan" and active

			if flag3 then
				flag3 = tick() - (H.HiddenEvent.hasanHelped or 0) < 150
			end

			if flag3 then
				tbl10[v8] = -2
				H.HiddenEvent.skipped[v8.Name] = nil
			else
				local hintIsland = v8.HintIsland
				local readyBoost = H.HiddenWakeBoost(v8.Name)

				if hintIsland then
					active = active and active.Active

					if active then
						local name_ = v8.Name
						hintIsland = not H.GetHiddenBossHour().checked[name_]
					else
						hintIsland = active
					end

					hintIsland = hintIsland or flag and not flag2 and H.IsHiddenBossHinted(v7, v8.HintIsland, v8.BossNames)
				end

				if readyBoost then
					tbl10[v8] = -1.5
				elseif hintIsland then
					tbl10[v8] = -1
					H.HiddenEvent.skipped[v8.Name] = nil
				elseif tick() - ((H.HiddenEvent.announced or {})[v8.Name] or 0) < 600 then
					tbl10[v8] = -0.5
				elseif v8.Name == H.HiddenEvent.current then
					tbl10[v8] = 0
				else
					local n = H.GetHiddenIsland(v8.Island)
					n = n and H.localPlayer:DistanceFromCharacter(n.World.Position) or 1000000

					if v8.Island == H.HiddenEvent.currentIsland then
						n = n * (0.0001)
					end

					tbl10[v8] = 1 + math.max(n - (tbl11[v8.Island] or 0) * 4000, 0)
				end
			end

			if not H.HiddenEvent.only or H.HiddenEvent.only[v8.Name] then
				table.insert(tbl9, v8)
			end
		end

		table.sort(tbl9, function(arg, arg2)
			return tbl10[arg] < tbl10[arg2]
		end)

		H.HiddenEvent.waiting = H.HiddenEvent.waiting or {}
		local n = 0

		for _, v8 in ipairs(tbl9) do repeat 
			local str2 = "Sea1/" .. v8.Island .. "/" .. v8.Name

			if v6[str2] ~= true then
				n = n + (1)
			end

			local flag3 = (v6[str2] ~= true or (H.HiddenEvent.only and H.HiddenEvent.only[v8.Name])) and (not v8.Requires or v6[v8.Requires] == true)

			if flag3 then
				flag3 = (H.HiddenEvent.only and H.HiddenEvent.only[v8.Name]) or tick() >= (H.HiddenEvent.skipped[v8.Name] or 0)
			end

			if flag3 then
				flag3 = not (tick() < (H.HiddenEvent.prepUntil or 0) and tbl10[v8] >= 1)
			end

			if flag3 then
				local v9 = H.GetHiddenMoment(v8.Name)
				local v10 = H.HiddenRemoteChecks[v8.Name]
				local flag4 = v10 and H.HiddenPresenceQuests[v8.Name] and not v8.HintIsland and not v9

				if flag4 then
					flag4 = tick() - ((H.HiddenEvent.announced or {})[v8.Name] or 0) > 900
				end

				if flag4 then
					local flag5 = v8.Name == "Rescue Hasan"

					if flag5 then
						flag5 = tick() - (H.HiddenEvent.hasanHelped or 0) < 150
					end

					flag4 = not flag5
				end

				local flag5 = true
				local awakenedBossQuests = nil

				if flag4 then
					local ok, result = pcall(v10)
					ok = ok and not result
					awakenedBossQuests = nil

					if ok then
						flag5 = false
						awakenedBossQuests = "not up yet (checked from afar)"
					end
				end

				if flag5 and v8.Precheck and (not v9 or v8.HintIsland and not v9.Active) then
					flag5, awakenedBossQuests = v8.Precheck(v7)
				end

				if not flag5 then
					if H.HiddenEvent.waiting[v8.Name] ~= awakenedBossQuests then
						if v8.HintIsland then
							H.HiddenNotify("Awakened boss quests: " .. awakenedBossQuests, "bosshint", "found")
						else
							H.HiddenNotify(v8.Name .. ": " .. awakenedBossQuests, v8.Name .. awakenedBossQuests)
						end
					end

					H.HiddenEvent.waiting[v8.Name] = awakenedBossQuests
					H.HiddenEvent.skipped[v8.Name] = tick() + 30
					break
				end

				if H.HiddenEvent.current ~= v8.Name then
					H.HiddenEvent.current = v8.Name
					H.HiddenEvent.currentIsland = v8.Island
					H.HiddenEvent.waitingSince = nil
					H.HiddenEvent.arrived = nil
					H.HiddenEvent.islandArrived = nil
					H.HiddenNotify("Start " .. v8.Name .. " (" .. v8.Island .. ")", v8.Name, "start")
				end

				H.HiddenEvent.idleSince = nil
				local flag6 = not v9

				if flag6 and v8.BossNames then
					for _, child in ipairs(workspace.Enemies:GetChildren()) do
						if child:GetAttribute("BossIndicatorAwakened") and H.IsHiddenTarget(child) then
							for _, bossName in ipairs(v8.BossNames) do
								if string.find(child.Name, bossName, 1, true) and H.localPlayer:DistanceFromCharacter(child:GetPivot().Position) < 2500 then
									H.SetHiddenStep("Defeat the awakened " .. child.Name)
									H.KillHiddenEnemy(child)
									H.HiddenEvent.checked = 0
									return
								end
							end
						end
					end
				end

				if flag6 and v8.NoMoment then
					local v11 = v8.NoMoment()
					if v11 then
						H.SetHiddenStep(v11)
						return
					end
				end

				if flag6 then
					if H.HiddenGoToIsland(v8.Island) then
						H.HiddenEvent.islandArrived = H.HiddenEvent.islandArrived or tick()
						local islandArrived = H.HiddenEvent.islandArrived

						if tick() - islandArrived > 8 then
							H.HiddenEvent.islandArrived = nil

							if v8.HintIsland then
								local name_ = v8.Name
								H.GetHiddenBossHour().checked[name_] = true
							end

							H.HiddenEvent.skipped[v8.Name] = math.max(H.HiddenEvent.skipped[v8.Name] or 0, tick() + H.HiddenRetryDelay(v8))
							H.SaveHiddenSkip()
							H.HiddenEvent.waiting[v8.Name] = v8.Name .. " is not happening on " .. v8.Island
							H.HiddenEvent.current = nil
							H.HiddenNotify(H.HiddenEvent.waiting[v8.Name] .. " yet, checking again later", v8.Name .. "notloaded", "warning")
						end
					else
						H.HiddenEvent.islandArrived = nil
					end

					return
				end

				H.HiddenEvent.islandArrived = nil
				local v11, v12 = v8.Run(v9)
				H.SetHiddenStep(v11 or "Working")

				if v12 then
					H.HiddenEvent.waitingSince = H.HiddenEvent.waitingSince or tick()
					local announced = H.HiddenEvent.announced and H.HiddenEvent.announced[v8.Name]
					local waitingSince = H.HiddenEvent.waitingSince
					local n3 = tick() - waitingSince
					announced = announced and tick() - announced < 420

					if announced then
						announced = v9 and v9.Active and 420 or 60
					end

					if (announced or 6) < n3 then
						H.HiddenEvent.waiting[v8.Name] = v11
						H.HiddenEvent.skipped[v8.Name] = math.max(H.HiddenEvent.skipped[v8.Name] or 0, tick() + H.HiddenRetryDelay(v8))
						H.SaveHiddenSkip()
						H.HiddenEvent.current = nil
						local name_ = v8.Name
						H.HiddenNotify(v8.Name .. ": " .. tostring(v11) .. ", switching to another quest", name_ .. tostring(v11), "warning")
					end
				else
					H.HiddenEvent.waiting[v8.Name] = nil
					H.HiddenEvent.waitingSince = nil
					if H.HiddenEvent.readyAt then
						H.HiddenEvent.readyAt[v8.Name] = nil
					end
				end

				return
			end
		until true end

		H.HiddenEvent.current = nil

		if n == 0 and H.HiddenEvent.only then
			H.SetHiddenStep("Targeted quest finished")
			H.HiddenEvent.checked = 0
			return
		end

		if n == 0 then
			H.SetHiddenStep("All 39 secrets are complete")
			H.SaveSettings("Auto Secret Quest", false)

			if getgenv().ToggleSecretQuest and getgenv().ToggleSecretQuest.SetStage then
				getgenv().ToggleSecretQuest:SetStage(false)
			end

			H.HiddenNotify("All 39 secret quests are done, turning off", "secretalldone", "success")
			return
		end

		H.HiddenEvent.idleSince = H.HiddenEvent.idleSince or tick()

		if tick() - (H.HiddenEvent.idleNotified or 0) > 300 then
			H.HiddenEvent.idleNotified = tick()
			H.HiddenNotify("No secret quest is available right now (" .. n .. " left), checking again soon", "idle", "warning")
		end

		local tbl12 = {}

		for k in pairs(H.HiddenEvent.waiting) do
			local str2 = nil

			for _, v8 in ipairs(H.HiddenQuests) do
				if v8.Name == k then
					str2 = "Sea1/" .. v8.Island .. "/" .. v8.Name
				end
			end

			if str2 and v6[str2] ~= true then
				table.insert(tbl12, k)
			end
		end

		local v8 = nil

		for _, v9 in pairs(H.HiddenEvent.skipped) do
			if v9 > tick() and (not v8 or v9 < v8) then
				v8 = v9
			end
		end

		if H.PrepareHiddenChef(v6) then
			return
		end
		if not H.AllowParkIdle then H.SetHiddenStep("Waiting " .. n .. " quests: " .. table.concat(tbl12, ", ")); return end
		local min = os.date("!*t").min
		local flag3 = H.Settings["Hidden Hop Dead Hour"] ~= false and min >= 50 and min <= 58

		if flag3 then
			flag3 = tick() - (H.HiddenEvent.hopAt or 0) > 100
		end

		if flag3 and not H.IsHiddenHourUseful(v6) then
			H.HiddenEvent.hopAt = tick()
			if H.HopHiddenServer() then
				H.SetHiddenStep("Next awakened boss is not needed here, switching server")
				return
			end
		end

		local park = H.HiddenEvent.park
		local flag4 = H.Settings["Hidden Hop Dead Hour"] ~= false and park
		local flag5

		if flag4 then
			flag5 = tick() - (H.HiddenEvent.idleSince or tick()) > 1200
		else
			flag5 = flag4
		end

		flag5 = flag5 and min >= 5 and min < 45

		if flag5 then
			flag5 = tick() - (H.HiddenEvent.hopAt or 0) > 1200
		end

		if flag5 then
			H.HiddenEvent.hopAt = tick()
			if H.HopHiddenServer() then
				H.SetHiddenStep("Nothing triggered on " .. park.island .. " for 20 min, switching server")
				return
			end
		end

		if H.localPlayer.Character and H.localPlayer.Character:FindFirstChild("HumanoidRootPart") then
			local v9 = H.PickHiddenParkSpot(v6)
			H.HiddenEvent.idlePark = v9

			if H.HiddenGoTo(v9, 60) then
				H.HiddenHold(CFrame.new(v9))
			end
		end

		H.SetHiddenStep("Waiting " .. n .. " quests" .. (v8 and " (next check in " .. math.ceil(v8 - tick()) .. "s)" or "") .. ": " .. table.concat(tbl12, ", "))
	end

end

    H.BuyMeleeQuestDefs = {
        ["Electro"] = { Name = "Electric Fighting Teacher", Island = "Sky" },
        ["Fishman Karate"] = { Name = "Fishman Karate", Island = "Underwater City" },
    }

    function H.IsMeleeQuestDone(styleName, force)
        local def = H.BuyMeleeQuestDefs[styleName]
        if not def then return true end
        if V1StyleLookup.EquipByName(styleName) then return true end
        if not (World1 or CurrentSeaNum == 1) then return true end
        if styleName == "Electro" then
            -- Nếu chưa có võ Electro thì quest bắt buộc phải làm để mở khóa mua võ
            return false
        end
        local key = "Sea1/" .. def.Island .. "/" .. def.Name
        local ok, prog = pcall(H.GetHiddenProgress, force)
        if not ok or type(prog) ~= "table" then return false end
        if next(prog) == nil then return false end
        local v = prog[key]
        if v == true or (type(v) == "table" and v.Completed == true) then
            return true
        end
        return false
    end

    function H.GetSummary()
        if not (World1 or CurrentSeaNum == 1) then
            return H.CachedDoneCount or 0, 39, H.HiddenEvent.current, H.HiddenEvent.step
        end
        local ok, prog = pcall(H.GetHiddenProgress, false)
        local doneCount = 0
        if ok and type(prog) == "table" then
            for _, v in pairs(prog) do
                if v == true or (type(v) == "table" and v.Completed == true) then
                    doneCount = doneCount + 1
                end
            end
            H.CachedDoneCount = doneCount
        end
        return H.CachedDoneCount or 0, 39, H.HiddenEvent.current, H.HiddenEvent.step
    end

    function H.DoMeleeUnlockStep(styleName)
        if not (World1 or CurrentSeaNum == 1) then return false end
        local def = H.BuyMeleeQuestDefs[styleName]
        if not def then return false end
        if H.IsMeleeQuestDone(styleName, false) then
            if H.HiddenEvent.only and H.HiddenEvent.only[def.Name] then
                H.HiddenEvent.only = nil
                pcall(H.HiddenRelease)
            end
            return false
        end
        H.ForceActive = true
        H.AllowParkIdle = false
        if H.HiddenEvent.current and H.HiddenEvent.current ~= def.Name then
            H.HiddenEvent.current = nil
            H.HiddenEvent.waitingSince = nil
            pcall(H.HiddenRelease)
        end
        H.HiddenEvent.only = { [def.Name] = true }
        pcall(H.AutoHiddenDialogue)
        pcall(H.AutoHiddenEvent)
        pcall(function()
            if H.CheckHiddenStall then H.CheckHiddenStall() end
            if H.HiddenEvent.anchored and tick() - (H.HiddenEvent.holdTime or 0) > 0.6 then
                H.HiddenRelease()
            end
        end)
        if H.HiddenEvent.current or (H.HiddenEvent.only and H.HiddenEvent.only[def.Name]) then
            CurrentFarmStatus = string.format("[Mở Khóa Võ %s - Quest Ẩn Sea 1] 🔥 %s: %s", tostring(styleName), tostring(H.HiddenEvent.current or def.Name), tostring(H.HiddenEvent.step or "Đang làm"))
            return true
        end
        pcall(H.HiddenRelease)
        return false
    end

    function H.DoStep(allowParkIdle)
        if not (World1 or CurrentSeaNum == 1) then return false end
        -- Nếu đang thiếu võ V1 (Electro / Fishman Karate) thì ưu tiên mở khóa võ trước, tuyệt đối không chờ đợi boss ở 39 quest
        local isSys = V1StyleLookup and V1StyleLookup.ItemsSystem
        if (IsSettingBuyMeleeV1() or IsSettingGetItem("Godhuman")) and type(isSys) == "table" then
            local targetStyle, tier = V1StyleLookup.GetActiveTargetStyle()
            if targetStyle and tier == "V1" and not V1StyleLookup.FindMeleeTool(targetStyle.Name) then
                local beli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
                if beli >= (targetStyle.CostBeli or 0) and H.BuyMeleeQuestDefs[targetStyle.Name] then
                    return H.DoMeleeUnlockStep(targetStyle.Name)
                end
            end
        end
        local doneCount = H.GetSummary()
        if doneCount >= 39 then
            pcall(H.HiddenRelease)
            return false
        end
        H.ForceActive = true
        H.AllowParkIdle = (allowParkIdle == true)
        H.HiddenEvent.only = nil
        pcall(H.AutoHiddenDialogue)
        pcall(H.AutoHiddenEvent)
        pcall(function()
            if H.CheckHiddenStall then H.CheckHiddenStall() end
            if H.HiddenEvent.anchored and tick() - (H.HiddenEvent.holdTime or 0) > 0.6 then
                H.HiddenRelease()
            end
        end)
        local curQ = H.HiddenEvent.current
        local curStep = tostring(H.HiddenEvent.step or "")
        if curQ ~= nil then
            CurrentFarmStatus = string.format("[39 Quest Ẩn Sea 1 - %d/39] 🔥 %s: %s", doneCount, tostring(curQ), curStep)
            return true
        end
        if allowParkIdle and doneCount < 39 then
            CurrentFarmStatus = string.format("[39 Quest Ẩn Sea 1 - %d/39] ⏳ %s", doneCount, curStep)
            return true
        end
        pcall(H.HiddenRelease)
        return false
    end
end)()

function V1StyleLookup.ItemsSystem.GetStatusText(lv, beli, frags)
    local IS = V1StyleLookup.ItemsSystem
    IS.RefreshInventory(false)
    lv = tonumber(lv) or 0
    local lines = {}

    -- 1. Saber (Sea 1 - Lv. 200+)
    if not IsSettingGetItem("Saber") then
        table.insert(lines, "• 1. Saber: Tắt")
    elseif HasSaberSword() then
        table.insert(lines, "• 1. Saber: Đã sở hữu (Mastery: " .. tostring(IS.GetMastery("Saber")) .. "/200)")
    elseif lv < 200 then
        table.insert(lines, "• 1. Saber: Cần Cấp 200+ (" .. tostring(lv) .. "/200)")
    else
        table.insert(lines, "• 1. Saber: Đang làm chuỗi nhiệm vụ Shanks")
    end

    -- 2. Secret Quest (39 Sao Sea 1 - Mở khóa Lv. 3000)
    if not IsSettingGetItem("Secret Quest") then
        table.insert(lines, "• 2. Secret Quest (39 Sao Sea 1): Tắt")
    elseif type(IS.SecretQuest39) == "table" then
        local d39, total39, curQ39, step39 = IS.SecretQuest39.GetSummary()
        if d39 >= 39 or IS.SecretQuest39.All39ConfirmedDone then
            table.insert(lines, "• 2. Secret Quest (39 Sao Sea 1): Đã hoàn thành 39/39 Sao")
        elseif curQ39 then
            table.insert(lines, string.format("• 2. Secret Quest (39 Sao Sea 1): Đang làm %d/%d Sao (%s - %s)", d39, total39, tostring(curQ39), tostring(step39 or "")))
        else
            table.insert(lines, string.format("• 2. Secret Quest (39 Sao Sea 1): Đã xong %d/%d Sao (%s)", d39, total39, tostring(step39 or "Chờ ở Sea 1")))
        end
    end

    -- 3. True Triple Katana (Sea 2 - Shisui, Wando, Saddi 300 Mas)
    if not IS.IsTTKEnabled() then
        table.insert(lines, "• 3. True Triple Katana: Tắt")
    elseif IS.HasItem("True Triple Katana") then
        table.insert(lines, "• 3. True Triple Katana: Đã sở hữu (Mastery: " .. tostring(IS.GetMastery("True Triple Katana")) .. "/350)")
    else
        local s1 = IS.HasItem("Shisui") and ("Có (" .. tostring(IS.GetMastery("Shisui")) .. "/300 Mas)") or "Chưa có"
        local s2 = IS.HasItem("Wando") and ("Có (" .. tostring(IS.GetMastery("Wando")) .. "/300 Mas)") or "Chưa có"
        local s3 = IS.HasItem("Saddi") and ("Có (" .. tostring(IS.GetMastery("Saddi")) .. "/300 Mas)") or "Chưa có"
        table.insert(lines, string.format("• 3. True Triple Katana: Shisui [%s] | Wando [%s] | Saddi [%s]", s1, s2, s3))
    end

    -- 4. Mirror Fractal (Sea 3 - Boss Dough King)
    if not IsSettingGetItem("Mirror Fractal") then
        table.insert(lines, "• 4. Mirror Fractal: Tắt")
    elseif IS.HasItem("Mirror Fractal") then
        table.insert(lines, "• 4. Mirror Fractal: Đã sở hữu")
    elseif IS.FindAliveMobFromList({ "Dough King" }, true) then
        table.insert(lines, "• 4. Mirror Fractal: Đang tiêu diệt Boss Dough King!")
    elseif IS.HasToolOnPlayer("Sweet Chalice") then
        local left = nil
        if tonumber(IS.LastCakePrinceSpawnerMsg) then
            left = tonumber(IS.LastCakePrinceSpawnerMsg)
        elseif type(IS.LastCakePrinceSpawnerMsg) == "string" then
            local n = string.match(IS.LastCakePrinceSpawnerMsg, "(%d+)")
            if n then left = tonumber(n) end
        end
        local progStr = (left and string.format("Đã diệt %d/500 quái (Còn %d quái)", math.max(0, 500 - left), left)) or "Đang farm quái mở cổng"
        table.insert(lines, "• 4. Mirror Fractal: Đã có Sweet Chalice -> " .. progStr)
    elseif IS.HasToolOnPlayer("God's Chalice") then
        local cocoa = IS.GetCount("Conjured Cocoa")
        if cocoa >= 10 then
            table.insert(lines, "• 4. Mirror Fractal: Đã có God's Chalice + " .. tostring(cocoa) .. "/10 Cocoa -> Đang đổi Sweet Chalice")
        else
            table.insert(lines, "• 4. Mirror Fractal: Đã có God's Chalice (Thiếu " .. tostring(10 - cocoa) .. " Cocoa [" .. tostring(cocoa) .. "/10])")
        end
    else
        table.insert(lines, "• 4. Mirror Fractal: Chờ God's Chalice (Cocoa: " .. tostring(IS.GetCount("Conjured Cocoa")) .. "/10)")
    end

    -- 5. Godhuman (Sea 3 - Full 9 Võ 400 Mastery)
    if not IsSettingGetItem("Godhuman") and not IsSettingBuyMeleeV2() then
        table.insert(lines, "• 5. Godhuman: Tắt")
    elseif V1StyleLookup.MasteredV2["Godhuman"] or IS.GetMastery("Godhuman") >= 400 then
        table.insert(lines, "• 5. Godhuman: Đã sở hữu (Max 400 Mastery)")
    elseif IS.HasItem("Godhuman") or V1StyleLookup.EquipByName("Godhuman") then
        table.insert(lines, "• 5. Godhuman: Đã sở hữu (Mastery: " .. tostring(IS.GetMastery("Godhuman")) .. "/400)")
    else
        local ft = IS.GetCount("Fish Tail")
        local ds = IS.GetCount("Dragon Scale")
        local mo = IS.GetCount("Magma Ore")
        local md = IS.GetCount("Mystic Droplet")
        local matStr = string.format("FishTail %d/20 | Scale %d/10 | Magma %d/20 | Droplet %d/10", ft, ds, mo, md)
        if V1StyleLookup.IsPreGodhumanMastered() then
            table.insert(lines, "• 5. Godhuman: Đã đủ 9 Võ 400 Mas -> Gom Nguyên Liệu (" .. matStr .. ")")
        else
            table.insert(lines, "• 5. Godhuman: Cần Max 9 Võ V1 & V2 400 Mas (" .. matStr .. ")")
        end
    end

    -- 6. Cursed Dual Katana / Yama / Tushita (Sea 3 - Lv. 2000+)
    if not IsSettingGetItem("Cursed Dual Katana") and not IsSettingGetItem("Tushita") and not IsSettingGetItem("Yama") then
        table.insert(lines, "• 6. Cursed Dual Katana: Tắt")
    elseif IS.HasItem("Cursed Dual Katana") then
        table.insert(lines, "• 6. Cursed Dual Katana: Đã sở hữu (Mastery: " .. tostring(IS.GetMastery("Cursed Dual Katana")) .. "/375)")
    else
        local yamaDesc = IS.HasItem("Yama")
            and ("Yama: " .. tostring(IS.GetMastery("Yama")) .. "/350 Mas")
            or ("Yama: Elite " .. tostring(IS.EliteCount or 0) .. "/30")
        local tushitaDesc = IS.HasItem("Tushita")
            and ("Tushita: " .. tostring(IS.GetMastery("Tushita")) .. "/350 Mas")
            or (lv >= 2000 and "Tushita: Chờ rip_indra/Longma" or "Tushita: Cần Lv 2000+")
        if IS.HasItem("Yama") and IS.GetMastery("Yama") >= 350 and IS.HasItem("Tushita") and IS.GetMastery("Tushita") >= 350 then
            if lv < 2200 then
                table.insert(lines, "• 6. Cursed Dual Katana: Đủ 2 kiếm 350 Mas -> Cần Lv 2200+ (" .. tostring(lv) .. "/2200)")
            else
                local cdk = IS.CDKProg
                local eStep = (type(cdk) == "table" and tonumber(cdk.Evil)) or 0
                local gStep = (type(cdk) == "table" and tonumber(cdk.Good)) or 0
                table.insert(lines, string.format("• 6. Cursed Dual Katana: Đang giải thử thách Oden (Evil: %d/3 | Good: %d/3)", eStep, gStep))
            end
        else
            table.insert(lines, "• 6. Cursed Dual Katana: " .. yamaDesc .. " | " .. tushitaDesc)
        end
    end

    -- 7. Skull Guitar (Sea 3 - Lv. 2300+)
    if not IsSettingGetItem("Skull Guitar") and not IsSettingGetItem("Soul Guitar") then
        table.insert(lines, "• 7. Skull Guitar: Tắt")
    elseif IS.HasItem("Skull Guitar") then
        table.insert(lines, "• 7. Skull Guitar: Đã sở hữu (Mastery: " .. tostring(IS.GetMastery("Skull Guitar")) .. "/300)")
    else
        local bones = IS.GetCount("Bones")
        local ecto = IS.GetCount("Ectoplasm")
        local df = IS.GetCount("Dark Fragment")
        local matSG = string.format("Bones %d/500 | Ecto %d/250 | DarkFrag %d/1", bones, ecto, df)
        if lv < 2300 then
            table.insert(lines, "• 7. Skull Guitar: Cần Lv 2300+ (" .. tostring(lv) .. "/2300) [" .. matSG .. "]")
        elseif type(IS.SGProg) == "table" then
            local sg = IS.SGProg
            local stepStr = (not sg.Swamp and "Bước 1/5: Zombie")
                or (not sg.Gravestones and "Bước 2/5: Bảng Mộ")
                or (not sg.Ghost and "Bước 3/5: Ghost")
                or (not sg.Trophies and "Bước 4/5: Cúp Vàng")
                or (not sg.Pipes and "Bước 5/5: Ống Nước")
                or "Đã giải xong 5/5 bước câu đố"
            table.insert(lines, "• 7. Skull Guitar: " .. stepStr .. " [" .. matSG .. "]")
        else
            table.insert(lines, "• 7. Skull Guitar: Chờ Full Moon để cầu nguyện [" .. matSG .. "]")
        end
    end

    -- 8. Shark Anchor (Sea 3 - Đảo Tiki)
    if not IsSettingGetItem("Shark Anchor") then
        table.insert(lines, "• 8. Shark Anchor: Tắt")
    elseif IS.HasItem("Shark Anchor") then
        table.insert(lines, "• 8. Shark Anchor: Đã sở hữu (Mastery: " .. tostring(IS.GetMastery("Shark Anchor")) .. "/350)")
    elseif IS.HasItem("Monster Magnet") then
        table.insert(lines, "• 8. Shark Anchor: Đã có Monster Magnet -> Đang săn Terrorshark Mỏ Neo")
    else
        local te = IS.GetCount("Terror Eyes")
        local ew = IS.GetCount("Electric Wing")
        local fg = IS.GetCount("Fool's Gold")
        local st = IS.GetCount("Shark Tooth")
        local neck = IS.HasItem("Monster Necklace") and "Xong" or "Chưa"
        local jaw = IS.HasItem("Terror Jaw") and "Xong" or "Chưa"
        table.insert(lines, string.format("• 8. Shark Anchor: Necklace [%s] | Jaw [%s] (Eyes %d/2, Wing %d/8, Gold %d/20, Tooth %d/10)", neck, jaw, te, ew, fg, st))
    end

    return table.concat(lines, "\n")
end

