task.spawn(function()
    while task.wait(0.1) do
        if IsAutoFarmActive() then
            local ok, loopErr = pcall(function()
                local char = plr.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                if not hrp or not hum or hum.Health <= 0 then
                    CurrentFarmStatus = "Đang đợi nhân vật hồi sinh..."
                    return
                end

                -- ƯU TIÊN 0: Nếu đang ở trong Raid (hoặc đang làm Raid kiếm F) -> Bắt buộc đánh xong Raid, KHÔNG đi nhặt trái hay làm việc khác
                if IsInRaid() or getgenv()._isDoingRaidForF or HasSpecialMicrochip() or getgenv()._waitingForRaidTeleport then
                    local curFrags = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Fragments") and plr.Data.Fragments.Value) or 0
                    local rStyle = getgenv()._raidTargetStyle
                    local rFrag = getgenv()._raidTargetFrags
                    if V1StyleLookup.FindMeleeTool("Superhuman") or (V1StyleLookup.RecordsV2 and (V1StyleLookup.RecordsV2["Superhuman"] or 0) > 0) or (V1MasteryRecord and (V1MasteryRecord["Superhuman"] or 0) > 0) then
                        if V1MasteryRecord then
                            V1MasteryRecord["Dragon Breath"] = math.max(V1MasteryRecord["Dragon Breath"] or 0, 300)
                            V1MasteryRecord["Dragon Claw"] = math.max(V1MasteryRecord["Dragon Claw"] or 0, 300)
                        end
                        if V1StyleLookup.BoughtStyles then
                            V1StyleLookup.BoughtStyles["Dragon Claw"] = true
                        end
                        getgenv()["Z9_MeleeBought_Dragon Claw"] = true
                    end
                    if (not rStyle or not rFrag or rStyle == "Dragon Claw") and type(V1StyleLookup) == "table" and type(V1StyleLookup.GetActiveTargetStyle) == "function" then
                        local tStyle, tier = V1StyleLookup.GetActiveTargetStyle()
                        if tStyle then
                            local cF = tStyle.CostFrag or 0
                            if cF > 0 then
                                rStyle = tStyle.Name
                                rFrag = cF
                            end
                        end
                    end
                    DoAutoRaidStep(hrp, hum, curFrags, rFrag or 1500, rStyle or "Dragon Claw")
                    return
                end

                -- ƯU TIÊN 0.5: TỰ ĐỘNG RESET STAT SANG KIẾM & MÁU (THỪA DỒN MELEE, THIẾU F TỰ ĐI RAID)
                if not getgenv()._isDoingRaidForF and CurrentTargetFruit == nil and type(V1StyleLookup) == "table" and type(V1StyleLookup.CheckAndResetStatsForSword) == "function" then
                    if V1StyleLookup.CheckAndResetStatsForSword(hrp, hum) then
                        return
                    end
                end

                -- ƯU TIÊN 0.6: TỰ ĐỘNG RAID TÍCH LŨY FRAGMENTS (NẾU BẬT CẤU HÌNH FARM FRAGMENTS)
                if not getgenv()._isDoingRaidForF and CurrentTargetFruit == nil and (World2 or World3 or CurrentSeaNum >= 2) then
                    local ffCfg = getgenv().SettingFarm and (getgenv().SettingFarm["Farm Fragments"] or getgenv().SettingFarm.FarmFragments)
                    local isFarmFrag = false
                    local targetF = 50000
                    if ffCfg == true then
                        isFarmFrag = true
                    elseif type(ffCfg) == "table" and ffCfg["Enabled"] == true then
                        isFarmFrag = true
                        targetF = tonumber(ffCfg["TargetFragment"] or ffCfg.TargetFragments) or 50000
                    end
                    if isFarmFrag then
                        local curFrags = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Fragments") and plr.Data.Fragments.Value) or 0
                        local isHoldingUrgent = (type(V1StyleLookup) == "table" and type(V1StyleLookup.ItemsSystem) == "table" and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem()) or false
                        if curFrags < targetF and not isHoldingUrgent then
                            DoAutoRaidStep(hrp, hum, curFrags, targetF, "Tích Lũy Fragments")
                            return
                        end
                    end
                end

                -- ƯU TIÊN 1: Nếu có Trái Ác Quỷ spawn trên Map (Chỉ nhặt khi KHÔNG ở trong chế độ Raid kiếm điểm F)
                if IsSettingFruitGrab() and not getgenv()._isDoingRaidForF then
                    local mapFruit = GetSpawnedFruitOnMap()
                    if mapFruit and mapFruit:FindFirstChild("Handle") then
                        local handle = mapFruit.Handle
                        if CurrentTargetFruit ~= mapFruit then
                            CurrentTargetFruit = mapFruit
                            FruitTouchTimer = nil
                        end

                        CurrentFarmStatus = "Đang bay đi nhặt trái trên Map: " .. tostring(mapFruit.Name)
                        local dist = (handle.Position - hrp.Position).Magnitude
                        if dist > 10 then
                            TweenTo(handle.CFrame)
                        else
                            if getgenv().StopTween then getgenv().StopTween() end
                            FruitTouchTimer = FruitTouchTimer or tick()
                            RefreshTeleportTag()
                            hrp.CFrame = handle.CFrame
                            hum.Jump = true
                            pcall(function()
                                if firetouchinterest then
                                    firetouchinterest(hrp, handle, 0)
                                    firetouchinterest(hrp, handle, 1)
                                end
                            end)
                            task.wait(0.3)
                            AutoStoreAllFruits()

                            -- Sau khi chạm nhặt & cất (hoặc quá 1.2s), đánh dấu đã xử lý xong trái này để quay lại farm cấp ngay lập tức
                            if not mapFruit.Parent or not handle:FindFirstChildOfClass("TouchTransmitter") or (tick() - FruitTouchTimer >= 1.2) then
                                IgnoredMapFruits[mapFruit] = true
                                pcall(function()
                                    local tag = Instance.new("BoolValue")
                                    tag.Name = "Z9_IgnoreFruit"
                                    tag.Parent = mapFruit
                                end)
                                CurrentTargetFruit = nil
                                FruitTouchTimer = nil
                                AutoStoreAllFruits()
                            end
                        end
                        return
                    else
                        CurrentTargetFruit = nil
                        FruitTouchTimer = nil
                    end
                end

                -- =========================================================================
                -- ƯU TIÊN 1.1: TỰ ĐỘNG LÀM SỰ KIỆN HALLOWEEN (HELLFIRE HALLOWEEN EVENT)
                -- YÊU CẦU: Acc cấp 1 đi farm tầm cấp Min Level rồi mới farm sự kiện!
                -- =========================================================================
                -- ĐỒNG BỘ ƯU TIÊN VŨ KHÍ MỤC TIÊU (KIẾM CHỦ LỰC / YAMA / TUSHITA / CDK / TTK)
                if type(V1StyleLookup) == "table" and V1StyleLookup.SyncTargetWeaponPriority then
                    V1StyleLookup.SyncTargetWeaponPriority()
                end

                -- [TÍNH NĂNG NÂNG CAO]: TỰ ĐỘNG ĂN TRÁI MỤC TIÊU & DUY TRÌ FORM BUDDHA KHỔNG LỒ
                if type(V1StyleLookup) == "table" then
                    if V1StyleLookup.CheckAndEatTargetFruit and V1StyleLookup.CheckAndEatTargetFruit() then
                        return
                    end
                    if V1StyleLookup.CheckAndMaintainBuddhaForm then
                        V1StyleLookup.CheckAndMaintainBuddhaForm(hrp, hum)
                    end
                end

                local pLv = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0
                local pBeli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0

                -- [TÍNH NĂNG NÂNG CAO]: NHẶT RƯƠNG CHO ACC MỚI SEA 1 NẾU THIẾU TIỀN MUA GEPPO/BUSO
                if type(V1StyleLookup) == "table" and V1StyleLookup.DoEarlyChestFarmStep then
                    if V1StyleLookup.DoEarlyChestFarmStep(hrp, pLv, pBeli) then
                        return
                    end
                end
                local minHwLv = (HW and HW.GetMinLevel and HW.GetMinLevel()) or 50
                local isDoingHalloween = IsAutoHalloweenEnabled() and (pLv >= minHwLv) and ((HW.GetEventCandies() or 0) < HW.GetMaxCandy())
                if isDoingHalloween and not getgenv()._isDoingRaidForF and CurrentTargetFruit == nil then
                    HW.DoStep(hrp, hum)
                    return -- TUYỆT ĐỐI ƯU TIÊN SỰ KIỆN 100%, KHÔNG LÀM BẤT KỲ VIỆC GÌ KHÁC CHO ĐẾN KHI ĐỦ KẸO!
                end

                -- =========================================================================
                -- ƯU TIÊN 1.2: TỰ ĐỘNG RANDOM TRÁI ÁC QUỶ TẠI NPC ZIOLES (COUSIN GACHA)
                -- (Cấp >= 50, đủ Beli, hết 2h hồi chiêu -> Tới Zioles roll & cất kho rồi tiếp tục farm)
                -- =========================================================================
                if not isDoingHalloween and IsSettingFruitRandom() and not getgenv()._isDoingRaidForF and CurrentTargetFruit == nil then
                    if type(GachaSystem) == "table" and type(GachaSystem.DoStep) == "function" then
                        local handledGacha = GachaSystem.DoStep(hrp, hum)
                        if handledGacha then
                            return
                        end
                    end
                end

                -- =========================================================================
                -- ƯU TIÊN 1.3: TỰ ĐỘNG THU THẬP BERRY TRONG BỤI CÂY (AUTO COLLECT BERRIES)
                -- YÊU CẦU: Nếu có Berry xuất hiện trong bụi -> DỪNG FARM CẤP để nhặt hết Berry.
                -- Khi hết toàn bộ Berry trên map -> Tự động quay lại farm như cũ! Có lưu tiến độ.
                -- TUYỆT ĐỐI KHÔNG CHẠY KHI ĐANG ƯU TIÊN SỰ KIỆN HALLOWEEN (CHƯA ĐỦ 500 KẸO NGÔ)!
                -- =========================================================================
                if not isDoingHalloween and IsAutoBerriesEnabled() and not getgenv()._isDoingRaidForF and CurrentTargetFruit == nil then
                    local handledBerry = BerrySystem.DoStep(hrp, hum)
                    if handledBerry then
                        return -- Dừng farm cấp / việc khác để ưu tiên nhặt hết Berry trên map
                    end
                end

                -- ƯU TIÊN 1.5: Tự động làm chuỗi nhiệm vụ lấy Kiếm Saber (Shanks Quest)
                -- CHỈ kích hoạt khi người dùng bật "Get Items" -> "Saber" VÀ chưa có Kiếm Saber!
                -- TUYỆT ĐỐI không ép quay lại Sea 1 chỉ vì Buy Instinct để tránh kick người chơi khỏi Sea 2
                if not isDoingHalloween and IsSettingGetItem("Saber") and not HasSaberSword() and not getgenv()._isDoingRaidForF and CurrentTargetFruit == nil then
                    if World1 then
                        if plr.Data.Level.Value >= 200 then
                            DoAutoSaberStep(hrp, hum)
                            return
                        end
                    else
                        -- Đang ở Sea 2 hoặc Sea 3: Saber có thể đang được cất trong Kho Đồ (Inventory Storage) khi cầm kiếm khác như TTK
                        -- Kiểm tra kỹ nếu người chơi đã có bất kỳ kiếm nâng cao nào (TTK, Shisui, Saddi, Wando, CDK, Shark Anchor...)
                        local isSys = V1StyleLookup and V1StyleLookup.ItemsSystem
                        local hasAnyAdvancedSword = false
                        if isSys and type(isSys.InvMap) == "table" then
                            for _, swName in ipairs({ "Shisui", "Wando", "Saddi", "True Triple Katana", "Cursed Dual Katana", "Shark Anchor", "Hallow Scythe", "Dark Dagger" }) do
                                if isSys.InvMap[swName] or (plr.Character and plr.Character:FindFirstChild(swName)) or (plr.Backpack and plr.Backpack:FindFirstChild(swName)) then
                                    hasAnyAdvancedSword = true
                                    break
                                end
                            end
                        end

                        if not hasAnyAdvancedSword then
                            getgenv()._scriptStartTime = getgenv()._scriptStartTime or tick()
                            if (tick() - getgenv()._scriptStartTime > 30) and tick() - LastTravelAttempt >= 8 then
                                if HasSaberSword(true) then
                                    -- Đã tìm thấy Saber trong kho đồ sau khi ép refresh!
                                    return
                                end
                                LastTravelAttempt = tick()
                                CurrentFarmStatus = "[Nhiệm vụ Saber] Chưa có Kiếm Saber -> Đang tự động quay lại Sea 1 (TravelMain) để làm quest..."
                                if HasActiveQuest() then
                                    pcall(function()
                                        ReplicatedStorage.Remotes.CommF_:InvokeServer("AbandonQuest")
                                    end)
                                    ResetQuestSeen()
                                end
                                if getgenv().StopTween then getgenv().StopTween() end
                                pcall(function()
                                    ReplicatedStorage.Remotes.CommF_:InvokeServer("TravelMain")
                                end)
                                task.wait(2)
                                return
                            end
                        end
                    end
                end

                -- ƯU TIÊN 1.55: Nếu đang ở Sea 2 hoặc Sea 3 mà chưa sở hữu Võ V1 (Electro / Fishman Karate / Black Leg / Dragon Claw) và đủ tiền & F
                -- -> Tương tác và mua trực tiếp tại NPC ở Sea 2 (Hot & Cold / Sabi) hoặc Sea 3 (Castle on the Sea), TUYỆT ĐỐI không TravelMain về Sea 1!
                -- TUYỆT ĐỐI KHÔNG ngắt quãng nếu đang đánh dở dang Boss (như Tide Keeper, Don Swan, v.v.)
                local isBossEngaged155 = (V1StyleLookup and V1StyleLookup.IsActiveBossInCombat and V1StyleLookup.IsActiveBossInCombat())
                if not World1 and (CurrentSeaNum == 2 or CurrentSeaNum == 3 or World2 or World3) and not getgenv()._isDoingRaidForF and CurrentTargetFruit == nil and not isBossEngaged155 then
                    local isSys = V1StyleLookup and V1StyleLookup.ItemsSystem
                    if (IsSettingBuyMeleeV1() or IsSettingGetItem("Godhuman")) and type(isSys) == "table" and not isSys.IsHoldingProtectedItem() then
                        local targetStyle, tier = V1StyleLookup.GetActiveTargetStyle()
                        if targetStyle and tier == "V1" and not V1StyleLookup.IsStyleOwned(targetStyle.Name) then
                            getgenv()._meleeUnlockFails = getgenv()._meleeUnlockFails or {}
                            local failCount = getgenv()._meleeUnlockFails[targetStyle.Name] or 0
                            local lastFailTick = getgenv()._meleeUnlockFailTick or 0
                            if failCount < 4 or (tick() - lastFailTick > 120) then
                                local beli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
                                local frags = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Fragments") and plr.Data.Fragments.Value) or 0
                                local reqBeli = targetStyle.CostBeli or 0
                                local reqFrag = targetStyle.CostFrag or 0
                                -- Bắt buộc phải KIỂM TRA ĐỦ CẢ F VÀ BELI mới được phép chạy đến NPC mua võ!
                                -- Ví dụ Dragon Claw cần 1,500 F -> nếu frags < 1500 tuyệt đối KHÔNG chạy đến NPC Sabi vì Sabi sẽ báo "Go away."!
                                if (reqBeli <= 0 or beli >= reqBeli) and (reqFrag <= 0 or frags >= reqFrag) then
                                    local npcCF = V1StyleLookup.GetNpcCFrame(targetStyle)
                                    if npcCF then
                                        local dist = (hrp.Position - npcCF.Position).Magnitude
                                        if dist > 15 then
                                            CurrentFarmStatus = string.format("[Mở Khóa Võ %s] Đang di chuyển tới %s tại Sea %d để mở khóa...", tostring(targetStyle.Name), tostring(targetStyle.NpcName), CurrentSeaNum or 2)
                                            TweenTo(npcCF)
                                            return
                                        else
                                            if getgenv().StopTween then getgenv().StopTween() end
                                            hrp.CFrame = npcCF
                                            CurrentFarmStatus = string.format("[Mở Khóa Võ %s] Đang tương tác với %s để mở khóa/trang bị...", tostring(targetStyle.Name), tostring(targetStyle.NpcName))
                                            local okBuy = V1StyleLookup.InteractAndBuy(targetStyle)
                                            task.wait(0.3)
                                            V1StyleLookup.UpdateAllMasteries()
                                            if V1StyleLookup.FindMeleeTool(targetStyle.Name) or V1StyleLookup.IsStyleOwned(targetStyle.Name) then
                                                getgenv()._meleeUnlockFails[targetStyle.Name] = 0
                                            else
                                                getgenv()._meleeUnlockFails[targetStyle.Name] = failCount + 1
                                                getgenv()._meleeUnlockFailTick = tick()
                                            end
                                            return
                                        end
                                    end
                                end
                            end
                        end
                    end
                end

                -- ƯU TIÊN 1.56: Nếu ở Sea 1 mà chưa sở hữu Võ V1 mục tiêu (Electro / Fishman Karate) và đủ tiền & F -> Ưu tiên TUYỆT ĐỐI mở khóa & mua võ trước mọi quest ẩn khác!
                if (World1 or CurrentSeaNum == 1) and not getgenv()._isDoingRaidForF and CurrentTargetFruit == nil and not isBossEngaged155 then
                    local isSys = V1StyleLookup and V1StyleLookup.ItemsSystem
                    if (IsSettingBuyMeleeV1() or IsSettingGetItem("Godhuman")) and type(isSys) == "table" and type(isSys.SecretQuest39) == "table" then
                        local targetStyle, tier = V1StyleLookup.GetActiveTargetStyle()
                        if targetStyle and tier == "V1" and not V1StyleLookup.IsStyleOwned(targetStyle.Name) then
                            local beli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
                            local frags = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Fragments") and plr.Data.Fragments.Value) or 0
                            local reqBeli = targetStyle.CostBeli or 0
                            local reqFrag = targetStyle.CostFrag or 0
                            if beli >= reqBeli and frags >= reqFrag then
                                if isSys.SecretQuest39.DoMeleeUnlockStep(targetStyle.Name) then
                                    return
                                end
                            end
                        end
                    end
                end

                -- ƯU TIÊN 1.6: Tự động giải các nhiệm vụ trong 39 Quest Ẩn Sea 1 đang sẵn sàng (khi đạt Lv >= 650 ở Sea 1 trước khi qua Sea 2)
                if World1 and plr.Data.Level.Value >= 650 and IsSettingGetItem("Secret Quest") and not getgenv()._isDoingRaidForF and CurrentTargetFruit == nil then
                    if type(V1StyleLookup.ItemsSystem) == "table" and type(V1StyleLookup.ItemsSystem.SecretQuest39) == "table" then
                        if V1StyleLookup.ItemsSystem.SecretQuest39.DoStep(plr.Data.Level.Value >= 2800) then
                            return
                        end
                    end
                end

                -- ƯU TIÊN 1.7: Tự động gom Beli & mua sạch toàn bộ vật phẩm Shop Sea 1 (Kiếm, Súng, Phụ Kiện) khi đạt Lv >= 600 trước khi qua Sea 2
                if V1StyleLookup.IsSettingBuySea1ShopEnabled() and (World1 or CurrentSeaNum == 1) and plr.Data.Level.Value >= 600 and not getgenv()._isDoingRaidForF and CurrentTargetFruit == nil and not isBossEngaged155 then
                    if type(V1StyleLookup.ItemsSystem) == "table" and type(V1StyleLookup.ItemsSystem.DoBuySea1ShopStep) == "function" then
                        if V1StyleLookup.ItemsSystem.DoBuySea1ShopStep(hrp, hum) then
                            return
                        end
                    end
                end

                -- ƯU TIÊN 2: Khi đạt Cấp >= 700 ở Sea 1 -> Tự động làm nhiệm vụ qua Sea 2 (Dressrosa)
                -- (Chỉ chuyển đi khi KHÔNG còn việc bắt buộc tại Sea 1 như Saber, 39 Quest Ẩn ở Lv 2800+, hoặc mở khóa Sư Phụ Võ V1)
                local isSysCheck = V1StyleLookup and V1StyleLookup.ItemsSystem
                local staySea1 = (type(isSysCheck) == "table" and isSysCheck.NeedsToStayInSea1 and isSysCheck.NeedsToStayInSea1(plr.Data.Level.Value)) or false
                if World1 and plr.Data.Level.Value >= 700 and IsAutoThirdWorldEnabled() and not staySea1 then
                    -- Nếu người chơi đã ở mốc cấp Sea 3 (>= 1500) vừa về Sea 1 làm xong nhiệm vụ (Saber / 39 Quest Ẩn) -> Bay thẳng về Sea 3 (TravelZou) luôn!
                    if plr.Data.Level.Value >= 1500 then
                        CurrentFarmStatus = "[Chuyển Thế Giới] Đã hoàn tất nhiệm vụ tại Sea 1 -> Đang quay về Sea 3 (TravelZou)..."
                        if getgenv().StopTween then getgenv().StopTween() end
                        pcall(function()
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("TravelZou")
                        end)
                        task.wait(1.5)
                        return
                    end
                    -- Nếu có bật lấy Saber ở Sea 1 thì hoàn thành Saber trước khi qua Sea 2
                    if IsSettingGetItem("Saber") and not HasSaberSword() then
                        DoAutoSaberStep(hrp, hum)
                        return
                    end

                    -- Hủy nhiệm vụ farm quái cũ nếu đang nhận dở
                    if HasActiveQuest() then
                        pcall(function()
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("AbandonQuest")
                        end)
                        ResetQuestSeen()
                    end

                    local prog = nil
                    pcall(function()
                        prog = ReplicatedStorage.Remotes.CommF_:InvokeServer("DressrosaQuestProgress", "Dressrosa")
                    end)

                    -- Nếu đã hoàn thành xong nhiệm vụ qua Sea 2 (prog == 0 hoặc UsedKey + KilledIceBoss) -> Dịch chuyển sang Sea 2 ngay
                    if prog == 0 or (type(prog) == "table" and prog.UsedKey == true and prog.KilledIceBoss == true) then
                        CachedSea2Progress.Completed = true
                        CurrentFarmStatus = "[Nhiệm vụ Sea 2 - Bước 4/4] Đã hoàn thành! Đang dịch chuyển qua Sea 2 (TravelDressrosa)..."
                        if getgenv().StopTween then getgenv().StopTween() end
                        pcall(function()
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("TravelDressrosa")
                        end)
                        task.wait(1.5)
                        return
                    end

                    local iceDoor = workspace:FindFirstChild("Map")
                        and workspace.Map:FindFirstChild("Ice")
                        and workspace.Map.Ice:FindFirstChild("Door")
                    local doorClosed = (iceDoor and iceDoor.CanCollide == true and iceDoor.Transparency == 0)
                    if type(prog) == "table" and prog.UsedKey == true then
                        doorClosed = false
                    end

                    if doorClosed then
                        local keyTool = (plr.Character and plr.Character:FindFirstChild("Key"))
                            or (plr.Backpack and plr.Backpack:FindFirstChild("Key"))

                        if not keyTool then
                            -- Bước 1: Đi gặp Military Detective tại Nhà Tù (Prison) để lấy Chìa Khóa (Key)
                            CurrentFarmStatus = "[Nhiệm vụ Sea 2 - Bước 1/4] Đang bay tới Military Detective (Prison) lấy Chìa Khóa (Key)..."
                            local detectiveCF = CFrame.new(4852.2895507813, 5.651451587677, 718.53070068359)
                            pcall(function()
                                for _, folder in ipairs({workspace:FindFirstChild("NPCs"), ReplicatedStorage:FindFirstChild("NPCs")}) do
                                    if folder then
                                        local det = folder:FindFirstChild("Military Detective")
                                        if det and det:FindFirstChild("HumanoidRootPart") then
                                            detectiveCF = det.HumanoidRootPart.CFrame
                                            break
                                        end
                                    end
                                end
                            end)

                            if (hrp.Position - detectiveCF.Position).Magnitude > 6 then
                                TweenTo(detectiveCF)
                            else
                                if getgenv().StopTween then getgenv().StopTween() end
                                hrp.CFrame = detectiveCF
                                task.wait(0.3)
                                pcall(function()
                                    ReplicatedStorage.Remotes.CommF_:InvokeServer("DressrosaQuestProgress", "Detective")
                                end)
                                CachedSea2Progress.TalkedDetective = true
                                task.wait(0.3)
                                local newKey = plr.Backpack and plr.Backpack:FindFirstChild("Key")
                                if newKey then
                                    hum:EquipTool(newKey)
                                    CachedSea2Progress.HasKey = true
                                end
                            end
                        else
                            -- Bước 2: Cầm Chìa Khóa (Key) đi mở cửa gỗ hầm băng tại Đảo Tuyết (Frozen Village)
                            CurrentFarmStatus = "[Nhiệm vụ Sea 2 - Bước 2/4] Đang cầm Key đi mở cửa hầm băng tại Đảo Tuyết..."
                            CachedSea2Progress.HasKey = true
                            if not plr.Character:FindFirstChild("Key") then
                                hum:EquipTool(keyTool)
                            end
                            local doorCF = (iceDoor and iceDoor.CFrame) or CFrame.new(1347.7124, 37.3751602, -1325.6488)
                            if (hrp.Position - doorCF.Position).Magnitude > 6 then
                                TweenTo(doorCF)
                            else
                                if getgenv().StopTween then getgenv().StopTween() end
                                RefreshTeleportTag()
                                hrp.CFrame = doorCF
                                pcall(function()
                                    if firetouchinterest and iceDoor then
                                        firetouchinterest(hrp, iceDoor, 0)
                                        firetouchinterest(hrp, iceDoor, 1)
                                        local kHandle = keyTool:FindFirstChild("Handle")
                                        if kHandle then
                                            firetouchinterest(kHandle, iceDoor, 0)
                                            firetouchinterest(kHandle, iceDoor, 1)
                                        end
                                    end
                                end)
                                task.wait(0.3)
                            end
                        end
                    else
                        -- Bước 3: Cửa đã mở -> Tìm và tiêu diệt Boss Ice Admiral [Lv. 700]
                        CachedSea2Progress.DoorOpened = true
                        local bossSpawnPart = DetectPartSpawnMob("Ice Admiral", false)
                        local waitBossCF = (bossSpawnPart and bossSpawnPart.CFrame) or CFrame.new(1347.7124, 37.3751602, -1325.6488)
                        local distToBoss = (hrp.Position - waitBossCF.Position).Magnitude

                        -- 1. Quét xem Boss Ice Admiral đã có sẵn trong workspace.Enemies chưa
                        local iceBoss = GetNearestAliveMob("Ice Admiral")
                        if not iceBoss then
                            for _, m in ipairs(ReplicatedStorage:GetChildren()) do
                                local mH = m:IsA("Model") and m.Name == "Ice Admiral" and m:FindFirstChildOfClass("Humanoid")
                                if mH and mH.Health > 0 then
                                    iceBoss = m
                                    break
                                end
                            end
                        end

                        local ibHum = iceBoss and iceBoss:FindFirstChildOfClass("Humanoid")
                        if iceBoss and iceBoss:FindFirstChild("HumanoidRootPart") and ibHum and ibHum.Health > 0 then
                            getgenv()._iceAdmiralArrivedTime = nil
                            getgenv()._currentTargetMobName = "Ice Admiral"
                            CurrentFarmStatus = "[Nhiệm vụ Sea 2 - Bước 3/4] Đang hạ Boss Ice Admiral (HP: " .. math.floor(ibHum.Health) .. ")..."
                            DisableMobCollision(iceBoss)
                            EnableBuso()
                            EquipSelectedWeapon()
                            TweenTo(iceBoss.HumanoidRootPart.CFrame * CFrame.new(0, 20, 0))
                        else
                            -- 2. Nếu chưa thấy Boss: Phải bay trực tiếp tới bãi spawn giống nâng cấp tộc Human V3
                            if distToBoss > 120 then
                                getgenv()._iceAdmiralArrivedTime = nil
                                CurrentFarmStatus = "[Nhiệm vụ Sea 2 - Bước 3/4] Đang bay tới bãi spawn kiểm tra Boss Ice Admiral..."
                                TweenTo(waitBossCF * CFrame.new(0, 15, 0))
                            else
                                -- Đã tới bãi spawn của Ice Admiral (dist <= 120 studs)
                                -- Đợi 2.5s để Roblox Streaming tải chunk và mob
                                local now = tick()
                                if not getgenv()._iceAdmiralArrivedTime then
                                    getgenv()._iceAdmiralArrivedTime = now
                                end
                                local waited = now - getgenv()._iceAdmiralArrivedTime
                                CurrentFarmStatus = "[Nhiệm vụ Sea 2 - Bước 3/4] Đang quét kiểm tra Boss Ice Admiral tại bãi spawn (" .. string.format("%.1f", math.max(0, 2.5 - waited)) .. "s)..."
                                TweenTo(waitBossCF * CFrame.new(0, 15, 0))

                                if waited >= 2.5 then
                                    -- Đã đứng trực tiếp tại bãi spawn 2.5s mà Boss không có -> Boss CHƯA HỒI SINH THẬT SỰ!
                                    getgenv()._iceAdmiralArrivedTime = nil
                                    pcall(function()
                                        ReplicatedStorage.Remotes.CommF_:InvokeServer("DressrosaQuestProgress", "Detective")
                                    end)
                                    CurrentFarmStatus = "[Nhiệm vụ Sea 2 - Bước 3/4] Boss Ice Admiral chưa hồi sinh -> Đang Hop Server kênh [awakened_ice_admiral]..."
                                    if HopBoss and not (V1StyleLookup.ItemsSystem and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem()) then
                                        HopBoss("Ice Admiral", "Boss Ice Admiral chưa hồi sinh -> Đổi server...")
                                        return
                                    end
                                end
                            end
                        end
                    end
                    return
                end

                -- ƯU TIÊN 2.1: Khi đạt Cấp >= 1500 ở Sea 2 -> Tự động làm chuỗi nhiệm vụ và dịch chuyển qua Sea 3 (Zou)
                -- (Chỉ chuyển đi khi KHÔNG bận làm nhiệm vụ bắt buộc tại Sea 2 như mở khóa Death Step/Sharkman, gom NL Godhuman/Skull Guitar, ghép TTK hoặc giữ Fist/Torch/Core Brain)
                local staySea2 = (type(isSysCheck) == "table" and isSysCheck.NeedsToStayInSea2 and isSysCheck.NeedsToStayInSea2(plr.Data.Level.Value)) or false
                if (World2 or CurrentSeaNum == 2) and plr.Data.Level.Value >= 1500 and IsAutoThirdWorldEnabled() and not staySea2 then
                    local didSea3 = DoAutoThirdSeaStep(hrp, hum)
                    if didSea3 then return end
                end

                -- Gacha Trái Ác Quỷ (Cousin) được xử lý tại Ưu Tiên 1.1 (kết hợp cả di chuyển đến Zioles lẫn tương tác UI/Remote)

                -- ƯU TIÊN 2.5: TỰ ĐỘNG MUA INSTINCT (HAKI QUAN SÁT - $750,000 BELI)
                -- Yêu cầu nghiêm ngặt: Phải có kiếm Saber trước, sau khi lên Sea 2 thì tự động mua Instinct!
                if IsBuyInstinctEnabled() and not HasInstinct() and HasSaberSword() then
                    local curBeli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
                    if curBeli >= 750000 then
                        -- Hủy nhiệm vụ farm quái dở để tập trung mua Instinct
                        if HasActiveQuest() then
                            pcall(function()
                                ReplicatedStorage.Remotes.CommF_:InvokeServer("AbandonQuest")
                            end)
                            ResetQuestSeen()
                        end

                        getgenv()._lastInstinctBuyAttempt = getgenv()._lastInstinctBuyAttempt or 0
                        if tick() - getgenv()._lastInstinctBuyAttempt >= 2 then
                            getgenv()._lastInstinctBuyAttempt = tick()
                            getgenv()._instinctRemoteTries = (getgenv()._instinctRemoteTries or 0) + 1

                            CurrentFarmStatus = "[Mua Instinct] Đang thực hiện mua Haki Quan Sát ($750K)..."
                            pcall(function()
                                ReplicatedStorage.Remotes.CommF_:InvokeServer("KenTalk", "Start")
                            end)
                            task.wait(0.2)
                            pcall(function()
                                ReplicatedStorage.Remotes.CommF_:InvokeServer("KenTalk", "Buy")
                            end)
                            task.wait(0.2)
                            pcall(function()
                                ReplicatedStorage.Remotes.CommF_:InvokeServer("KenTalk")
                            end)
                            task.wait(0.4)
                            LastInstinctCheck = 0

                            if HasInstinct() then
                                CurrentFarmStatus = "[Mua Instinct] ✅ Đã mua thành công Haki Quan Sát!"
                                return
                            end

                            -- Nếu ở Sea 1 và cần mua trực tiếp từ Lord of Destruction tại Upper Skylands
                            if World1 and getgenv()._instinctRemoteTries >= 2 then
                                -- Bay lên Upper Skylands gặp Lord of Destruction tại (-7894.62, 5545.49, -380.25)
                                CurrentFarmStatus = "[Mua Instinct] Đang bay tới Upper Skylands gặp Lord of Destruction để mua Haki Quan Sát..."
                                local teacherCF = CFrame.new(-7894.62, 5545.49, -380.25)
                                if hrp.Position.Y < 3000 then
                                    pcall(function()
                                        ReplicatedStorage.Remotes.CommF_:InvokeServer("requestEntrance", Vector3.new(-7894.6201171875, 5545.49169921875, -380.2467346191406))
                                    end)
                                    task.wait(0.5)
                                end

                                if (hrp.Position - teacherCF.Position).Magnitude > 25 then
                                    TweenTo(teacherCF * CFrame.new(0, 3, 0))
                                else
                                    if getgenv().StopTween then getgenv().StopTween() end
                                    CurrentFarmStatus = "[Mua Instinct] Đang nói chuyện trực tiếp với Lord of Destruction mua Haki Quan Sát..."
                                    pcall(function()
                                        ReplicatedStorage.Remotes.CommF_:InvokeServer("KenTalk", "Start")
                                    end)
                                    task.wait(0.3)
                                    pcall(function()
                                        ReplicatedStorage.Remotes.CommF_:InvokeServer("KenTalk", "Buy")
                                    end)
                                    task.wait(0.5)
                                    LastInstinctCheck = 0
                                    if HasInstinct() then
                                        CurrentFarmStatus = "[Mua Instinct] ✅ Đã mua thành công Haki Quan Sát!"
                                        getgenv().Z9_PurchasedInstinct = true
                                    end
                                end
                                return
                            end
                        end
                        return
                    end
                end

                -- ƯU TIÊN 2.5: VẬT PHẨM KHẨN CẤP & CHÌA KHÓA RƠI RA (Library Key, Hidden Key, Water Key, Fire Essence...)
                -- Khi đánh boss rơi chìa khóa, lập tức ưu tiên cao nhất mở khóa cửa/rương ngay để không bị mất khi chết hoặc hop server!
                if CurrentTargetFruit == nil and type(V1StyleLookup.ItemsSystem) == "table" and V1StyleLookup.ItemsSystem.IsHoldingProtectedItem() then
                    if V1StyleLookup.ItemsSystem.DoUrgentStep(hrp, hum) then
                        return
                    end
                end

                -- ƯU TIÊN 2.6: TỰ ĐỘNG NÂNG CẤP TỘC (RACE V2 & RACE V3)
                -- Ưu tiên làm xong Tộc trước, khi hoàn thành Tộc V3 sẽ tự động quay lại farm bình thường như cũ!
                -- CHỈ HỖ TRỢ CÁC TỘC: Human, Rabbit (Mink), Shark (Fishman), Cyborg
                -- KHÔNG HỖ TRỢ: Draco, Angel (Skypiea), Ghoul (Bỏ qua không nâng cấp để tránh kẹt bot)
                if IsAutoRaceV3Enabled() and (World2 or CurrentSeaNum == 2) and not getgenv()._isDoingRaidForF and CurrentTargetFruit == nil then
                    local pRace = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Race") and tostring(plr.Data.Race.Value)) or "Human"
                    local isSupp, normRace = IsSupportedRace(pRace)
                    if isSupp then
                        local raceTier = GetRaceVersion()
                        local curLv = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Level") and plr.Data.Level.Value) or 0

                        -- GIAI ĐOẠN 1: Nếu còn là Tộc V1 và đã đạt Cấp >= 850 -> Ưu tiên nâng cấp Tộc V2 trước!
                        if raceTier == "V1" and curLv >= 850 then
                            if HasActiveQuest() and not IsBartiloActiveQuest() then
                                pcall(function()
                                    ReplicatedStorage.Remotes.CommF_:InvokeServer("AbandonQuest")
                                end)
                                ResetQuestSeen()
                            end
                            local okV2 = DoRaceV2Step(hrp, hum)
                            if okV2 then return end

                        -- GIAI ĐOẠN 2: Đã đạt Tộc V2 và đạt Cấp >= 1000 -> Ưu tiên nâng cấp Tộc V3!
                        elseif raceTier == "V2" and curLv >= 1000 then
                            local swanUnlocked = IsSwanRoomUnlocked()
                            local hasFruitForTrevor = false
                            if not swanUnlocked then
                                local fruitName = GetFruitWorth1MPlus()
                                hasFruitForTrevor = (fruitName ~= nil)
                            end

                            -- Kiểm tra xem hiện tại có thể tiến hành Race V3 không:
                            -- 1. Nếu chưa mở cổng Don Swan: CHỈ LÀM khi đã có sẵn trái ác quỷ >= $1M!
                            --    Nếu chưa có trái >= $1M -> Bỏ qua, để bot tiếp tục Farm cấp & Võ bình thường (không hủy quest farm)!
                            -- 2. Nếu đã mở cổng Don Swan: Luôn làm (đánh Boss Don Swan hoặc làm nhiệm vụ Arowe)
                            local canProgressV3 = swanUnlocked or hasFruitForTrevor

                            if canProgressV3 then
                                if HasActiveQuest() and not IsBartiloActiveQuest() then
                                    pcall(function()
                                        ReplicatedStorage.Remotes.CommF_:InvokeServer("AbandonQuest")
                                    end)
                                    ResetQuestSeen()
                                end

                                -- Bước 1: Mở cổng phòng Don Swan qua Trevor (khi có trái >= $1M)
                                if not swanUnlocked then
                                    local okTrevor = DoTrevorUnlockStep(hrp, hum, "[Auto Race V3]")
                                    if okTrevor then return end
                                -- Bước 2: Tiêu diệt Boss Don Swan [Lv. 1000]
                                elseif not IsDonSwanKilled() then
                                    local swanBusy = DoKillDonSwanStep(hrp, hum, "[Auto Race V3]")
                                    if swanBusy then return end
                                -- Bước 3: Đã hạ Don Swan -> Làm nhiệm vụ Arowe (Wenlocktoad) + $2,000,000 Beli để lên Tộc V3
                                else
                                    local okV3 = DoRaceV3Step(hrp, hum)
                                    if okV3 then return end
                                end
                            end
                        end
                    end
                end

                -- ƯU TIÊN 2.8: VẬT PHẨM KHẨN CẤP SEA 3 (Mirror Fractal khi có Chalice/Dough King, Tushita khi có rip_indra/Longma, Yama khi có Elite Pirate, Shark Anchor khi có Terrorshark)
                if not getgenv()._isDoingRaidForF and not HasSpecialMicrochip() and not IsInRaid() and CurrentTargetFruit == nil and type(V1StyleLookup.ItemsSystem) == "table" then
                    if V1StyleLookup.ItemsSystem.DoUrgentStep(hrp, hum) then
                        return
                    end
                end

                -- ƯU TIÊN KIẾM CHỦ LỰC (Yama 350 / Tushita 350 / CDK / TTK):
                -- Kích hoạt khi tất cả võ V2 đã hoàn thành 400 Mas HOẶC khi đang chờ Dragon Talon (chờ Fire Essence nhưng ĐANG HẾT LƯỢT RANDOM XƯƠNG) và toàn bộ võ đang sở hữu đã đạt 400 Mas!
                if type(V1StyleLookup) == "table" and type(V1StyleLookup.ItemsSystem) == "table" then
                    local isSys = V1StyleLookup.ItemsSystem
                    local isPreGhDone = (type(V1StyleLookup.IsPreGodhumanMastered) == "function" and V1StyleLookup.IsPreGodhumanMastered())
                    local targetStyle = type(V1StyleLookup.GetActiveTargetStyle) == "function" and V1StyleLookup.GetActiveTargetStyle()

                    local isDtCooldown = false
                    if targetStyle and targetStyle.Name == "Dragon Talon" and type(isSys.IsBonesOnCooldown) == "function" then
                        isDtCooldown = isSys.IsBonesOnCooldown()
                    end

                    local isWaitingDT = (targetStyle and targetStyle.Name == "Dragon Talon" and not V1StyleLookup.FindMeleeTool("Dragon Talon") and isDtCooldown)
                    local unmasteredMelee = (type(V1StyleLookup.GetUnmasteredOwnedMelee) == "function" and V1StyleLookup.GetUnmasteredOwnedMelee())
                    local allowSwordTraining = isPreGhDone or (isWaitingDT and not unmasteredMelee)

                    local isStatsInMelee = false
                    pcall(function()
                        local data = plr:FindFirstChild("Data")
                        local statsFolder = data and data:FindFirstChild("Stats")
                        if statsFolder then
                            local swLv = GetStatCurrentLevel(statsFolder, "Sword")
                            local melLv = GetStatCurrentLevel(statsFolder, "Melee")
                            if melLv >= 800 and swLv < melLv * 0.5 then
                                isStatsInMelee = true
                            end
                        end
                    end)

                    if allowSwordTraining and not isStatsInMelee and (IsSettingGetItem("Cursed Dual Katana") or IsSettingGetItem("Yama")) and (World3 or CurrentSeaNum == 3) and not isSys.HasItem("Cursed Dual Katana") then
                        local hasYama = isSys.HasItem("Yama")
                        local yamaMas = isSys.GetMastery("Yama")
                        local hasTushita = isSys.HasItem("Tushita")
                        local tushitaMas = isSys.GetMastery("Tushita")
                        if hasYama and yamaMas < 350 then
                            getgenv()._targetSwordName = "Yama"
                            SetSettingWeapon("Sword")
                            V1StyleLookup.EnsureSwordEquipped("Yama")
                        elseif hasTushita and tushitaMas < 350 then
                            getgenv()._targetSwordName = "Tushita"
                            SetSettingWeapon("Sword")
                            V1StyleLookup.EnsureSwordEquipped("Tushita")
                        elseif (hasYama and yamaMas >= 350) and (hasTushita and tushitaMas >= 350) then
                            if getgenv()._targetSwordName == "Yama" or getgenv()._targetSwordName == "Tushita" then
                                getgenv()._targetSwordName = nil
                            end
                        end
                    else
                        if not allowSwordTraining then
                            if getgenv()._targetSwordName == "Yama" or getgenv()._targetSwordName == "Tushita" then
                                getgenv()._targetSwordName = nil
                                SetSettingWeapon("Melee")
                            end
                        end
                    end
                end

                -- ƯU TIÊN 3: Tự động mua Võ & Farm Thông Thạo (Mastery) đến 400 mới sang mua võ tiếp theo (V1 & V2 & Godhuman)
                -- Nếu đang trong chế độ luyện Kiếm/Súng chủ lực (getgenv()._targetSwordName ~= nil), không ép đổi lại về Melee để tránh xung đột rút kiếm!
                if GetSettingWeapon() == "Melee" and getgenv()._targetSwordName == nil and (IsSettingBuyMeleeV1() or IsSettingBuyMeleeV2() or IsSettingGetItem("Godhuman")) then
                    V1StyleLookup.UpdateAllMasteries()

                    local targetStyle, tier = V1StyleLookup.GetActiveTargetStyle()

                    if targetStyle then
                        -- 2. Kiểm tra xem đã sở hữu võ này trong Character hoặc Backpack chưa
                        local hasTargetTool = V1StyleLookup.EquipByName(targetStyle.Name)
                        if hasTargetTool then
                            -- Đang cầm trên tay đúng võ mục tiêu -> Tiếp tục farm cấp để cày Mastery!
                            getgenv()._isDoingRaidForF = false
                            getgenv()._holdingFruitForRaidChip = false
                            SetSettingWeapon("Melee")
                        else
                            -- Chưa có võ mục tiêu trên người -> Tiến hành MUA / TRANG BỊ
                            local isBossEngaged3 = (V1StyleLookup and V1StyleLookup.IsActiveBossInCombat and V1StyleLookup.IsActiveBossInCombat())
                            local beli = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Beli") and plr.Data.Beli.Value) or 0
                            local frags = (plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Fragments") and plr.Data.Fragments.Value) or 0

                            local hasTool = (V1StyleLookup.FindMeleeTool(targetStyle.Name) ~= nil)
                            local hasMas = ((V1MasteryRecord[targetStyle.Name] or 0) > 0)
                                or (targetStyle.Name == "Dragon Claw" and ((V1MasteryRecord["Dragon Breath"] or 0) > 0 or (V1MasteryRecord["DragonClaw"] or 0) > 0))

                            local isBought = hasTool or hasMas
                                or (V1StyleLookup.BoughtStyles and V1StyleLookup.BoughtStyles[targetStyle.Name] == true)
                                or (getgenv()["Z9_MeleeBought_" .. tostring(targetStyle.Name)] == true)
                                or V1StyleLookup.IsStyleOwned(targetStyle.Name)

                            -- KIỂM TRA ĐIỀU KIỆN F NGHIÊM NGẶT:
                            -- Nếu chưa có Tool và chưa từng có Mastery > 0 mà võ yêu cầu F (Dragon Claw cần 1,500 F):
                            -- Nếu F trong người chưa đủ (frags < targetStyle.CostFrag) -> TUYỆT ĐỐI KHÔNG ĐƯỢC COI LÀ ĐÃ MUA!
                            -- Xóa sạch mọi cờ lưu sai để tránh bot chạy đến NPC Sabi khi chưa đủ 1,500 F!
                            local reqFrag = targetStyle.CostFrag or 0
                            local reqBeli = targetStyle.CostBeli or 0
                            if not hasTool and not hasMas and reqFrag > 0 and frags < reqFrag then
                                isBought = false
                                if V1StyleLookup.BoughtStyles then V1StyleLookup.BoughtStyles[targetStyle.Name] = nil end
                                getgenv()["Z9_MeleeBought_" .. tostring(targetStyle.Name)] = nil
                                getgenv()._isFetchingMelee = nil
                                MeleeStorage.Save()
                            end

                            -- Chỉ khi đã sở hữu (isBought) HOẶC đủ cả Beli VÀ F mới được phép chạy đi lấy võ!
                            if isBought or (beli >= reqBeli and frags >= reqFrag) then
                                getgenv()._isDoingRaidForF = false
                                getgenv()._holdingFruitForRaidChip = false

                                -- 1. Nếu đã mua rồi (isBought) -> Thử gọi remote đổi/trang bị từ xa (miễn phí 0 Beli, 0 F).
                                -- TUYỆT ĐỐI KHÔNG gọi remote mua từ xa khi chưa sở hữu (not isBought) vì Blox Fruits kiểm tra khoảng cách NPC:
                                -- gọi từ xa sẽ bị trừ F mà server từ chối cấp võ, gây mất sạch điểm F oan uổng!
                                if isBought then
                                    local now = tick()
                                    getgenv()._lastMeleeRemoteBuy = getgenv()._lastMeleeRemoteBuy or 0
                                    if now - getgenv()._lastMeleeRemoteBuy >= 1.5 then
                                        getgenv()._lastMeleeRemoteBuy = now
                                        pcall(function()
                                            if targetStyle.Remote == "DragonClaw" then
                                                ReplicatedStorage.Remotes.CommF_:InvokeServer("BlackbeardReward", "DragonClaw", "1")
                                            elseif targetStyle.Remote == "BuyGodhuman" then
                                                ReplicatedStorage.Remotes.CommF_:InvokeServer("BuyGodhuman")
                                            else
                                                ReplicatedStorage.Remotes.CommF_:InvokeServer(targetStyle.Remote)
                                            end
                                        end)
                                    end
                                end

                                -- 2. Kiểm tra xem đã trang bị được chưa
                                if V1StyleLookup.EquipByName(targetStyle.Name) then
                                    SetSettingWeapon("Melee")
                                    CurrentFarmStatus = "Đã trang bị võ " .. targetStyle.Name .. " [" .. tostring(tier or "V1") .. "] thành công!"
                                    V1StyleLookup.BoughtStyles = V1StyleLookup.BoughtStyles or {}
                                    V1StyleLookup.BoughtStyles[targetStyle.Name] = true
                                    getgenv()["Z9_MeleeBought_" .. tostring(targetStyle.Name)] = true
                                    getgenv()._isFetchingMelee = nil
                                    MeleeStorage.Save()
                                else
                                    -- 2.4. Nếu là Võ V1 ở Sea 1 (Electro / Fishman Karate) cần giải Quest Ẩn mở khóa Sư Phụ -> Giải Quest Ẩn của Sư Phụ trước!
                                    if tier == "V1" and (World1 or CurrentSeaNum == 1) and type(V1StyleLookup.ItemsSystem) == "table" and type(V1StyleLookup.ItemsSystem.SecretQuest39) == "table" then
                                        if V1StyleLookup.ItemsSystem.SecretQuest39.DoMeleeUnlockStep(targetStyle.Name) then
                                            return
                                        end
                                    end

                                    -- 2.5. Nếu là Võ V2 và chưa mở khóa điều kiện ẩn (Library Key, Water Key, Chạy 30s, Fire Essence) -> Luôn làm nhiệm vụ mở khóa trước!
                                    if tier == "V2" and type(V1StyleLookup.ItemsSystem) == "table" and V1StyleLookup.ItemsSystem.DoMeleeV2UnlockStep then
                                        if V1StyleLookup.ItemsSystem.DoMeleeV2UnlockStep(hrp, hum, targetStyle) then
                                            return
                                        end
                                    end

                                    -- 3. Đến tận nơi đứng sát NPC để mua/lấy võ (CHỈ KHI ĐÃ SỞ HỮU HOẶC ĐÃ MỞ KHÓA ĐIỀU KIỆN ẨN)
                                    local canGoToNpcToBuy = isBought
                                    if not canGoToNpcToBuy then
                                        local isV2Unlocked = true
                                        local IS = V1StyleLookup.ItemsSystem
                                        if tier == "V2" and type(IS) == "table" then
                                            if targetStyle.Name == "Dragon Talon" then
                                                isV2Unlocked = (IS.DragonTalonEssenceDone == true or getgenv().Z9_DragonTalonUnlocked == true)
                                            elseif targetStyle.Name == "Electric Claw" then
                                                isV2Unlocked = (IS.ElectricClawQuestDone == true)
                                            elseif targetStyle.Name == "Death Step" then
                                                isV2Unlocked = (IS.DeathStepDoorOpened == true or getgenv().Z9_DeathStepDoorOpened == true)
                                            elseif targetStyle.Name == "Sharkman Karate" then
                                                isV2Unlocked = (IS.SharkmanKeySubmitted == true or getgenv().Z9_SharkmanKeySubmitted == true)
                                            end
                                        end
                                        canGoToNpcToBuy = isV2Unlocked
                                    end

                                    if not canGoToNpcToBuy then
                                        getgenv()._isFetchingMelee = nil
                                    end

                                    if canGoToNpcToBuy and not isBossEngaged3 then
                                        local npcCF = V1StyleLookup.GetNpcCFrame(targetStyle)
                                        if npcCF then
                                            local dist = (hrp.Position - npcCF.Position).Magnitude
                                            local costLabel = isBought and "Đã sở hữu -> Miễn phí" or ((targetStyle.CostBeli > 0 and ("$" .. FormatNumber(targetStyle.CostBeli))) or "")
                                            if not isBought and targetStyle.CostFrag > 0 then
                                                costLabel = costLabel .. (costLabel ~= "" and " + " or "") .. "ƒ" .. FormatNumber(targetStyle.CostFrag)
                                            end

                                            if dist > 10 then
                                                getgenv()._isFetchingMelee = targetStyle.Name
                                                CurrentFarmStatus = "Đang tới NPC " .. targetStyle.NpcName .. " lấy/trang bị võ " .. targetStyle.Name .. " [" .. tostring(tier or "V1") .. "] (" .. costLabel .. ")..."
                                                TweenTo(npcCF)
                                                return
                                            else
                                                if getgenv().StopTween then getgenv().StopTween() end
                                                getgenv()._lastTargetArriveTick = tick()
                                                hrp.CFrame = npcCF
                                                task.wait(0.05)
                                                CurrentFarmStatus = "Đang tương tác lấy võ " .. targetStyle.Name .. " [" .. tostring(tier or "V1") .. "] với NPC " .. targetStyle.NpcName .. "..."
                                                local okBought = V1StyleLookup.InteractAndBuy(targetStyle)
                                                if okBought or V1StyleLookup.EquipByName(targetStyle.Name) then
                                                    SetSettingWeapon("Melee")
                                                    CurrentFarmStatus = "Đã lấy & trang bị võ " .. targetStyle.Name .. " thành công! Bắt đầu farm..."
                                                    V1StyleLookup.BoughtStyles = V1StyleLookup.BoughtStyles or {}
                                                    V1StyleLookup.BoughtStyles[targetStyle.Name] = true
                                                    getgenv()["Z9_MeleeBought_" .. tostring(targetStyle.Name)] = true
                                                    getgenv()._isFetchingMelee = nil
                                                    MeleeStorage.Save()
                                                else
                                                    getgenv()._isFetchingMelee = nil
                                                    getgenv()._lastMeleeBuyFail = tick()
                                                    if V1StyleLookup.BoughtStyles then V1StyleLookup.BoughtStyles[targetStyle.Name] = nil end
                                                    getgenv()["Z9_MeleeBought_" .. tostring(targetStyle.Name)] = nil
                                                    if targetStyle.Name == "Dragon Talon" and type(V1StyleLookup.ItemsSystem) == "table" then
                                                        V1StyleLookup.ItemsSystem.DragonTalonEssenceDone = false
                                                        getgenv().Z9_DragonTalonUnlocked = false
                                                    end
                                                    MeleeStorage.Save()
                                                    task.wait(0.2)
                                                    return
                                                end
                                            end
                                        end
                                    end
                                end
                            elseif not isBought and reqFrag > 0 and frags < reqFrag and CurrentSeaNum >= 2 then
                                -- Ở Sea 2/3 cần mua võ bằng điểm F (Dragon Claw cần 1,500 F, V2 cần 5,000 F) nhưng chưa đủ F:
                                -- Xóa cờ fetching, chuyển ngay sang Auto Raid kiếm đủ F trước khi quay lại NPC!
                                getgenv()._isFetchingMelee = nil
                                getgenv()._raidTargetStyle = targetStyle.Name
                                getgenv()._raidTargetFrags = reqFrag
                                if not isBossEngaged3 then
                                    DoAutoRaidStep(hrp, hum, frags, reqFrag, targetStyle.Name)
                                    return
                                end
                            else
                                -- Chưa đủ Beli/F mua võ tiếp theo -> Cầm võ hiện tại farm cấp & cày tiền cho tới khi đủ Beli
                                if getgenv()._raidTargetStyle == nil or getgenv()._raidTargetStyle == targetStyle.Name then
                                    getgenv()._isDoingRaidForF = false
                                    getgenv()._holdingFruitForRaidChip = false
                                end
                                SetSettingWeapon("Melee")
                            end
                        end
                    else
                        -- Tất cả võ mục tiêu (V1 hoặc V2) đều đã đạt >= 400 Mastery -> Dùng võ hiện tại farm cấp
                        if getgenv()._raidTargetStyle == nil or getgenv()._raidTargetStyle == "Melee" then
                            getgenv()._isDoingRaidForF = false
                            getgenv()._holdingFruitForRaidChip = false
                        end
                        SetSettingWeapon("Melee")
                    end
                end

                -- ƯU TIÊN 3.5: TIẾN TRÌNH LẤY VẬT PHẨM THEO THỨ TỰ (Godhuman Materials -> CDK -> Skull Guitar -> Shark Anchor)
                if not getgenv()._isDoingRaidForF and CurrentTargetFruit == nil and type(V1StyleLookup.ItemsSystem) == "table" then
                    if V1StyleLookup.ItemsSystem.DoProgressionStep(hrp, hum) then
                        return
                    end
                end

                -- BẬT / TẮT TỰ ĐỘNG FARM CẤP (AUTO FARM LEVEL)
                if type(V1StyleLookup) == "table" and type(V1StyleLookup.IsAutoFarmLevelEnabled) == "function" then
                    if not V1StyleLookup.IsAutoFarmLevelEnabled() then
                        CurrentFarmStatus = "[Farm Cấp: Tắt] Đang chờ nhiệm vụ sự kiện hoặc vật phẩm..."
                        return
                    end
                end

                -- MỞ KHÓA VÕ MỤC TIÊU (V2 / Dragon Talon / v.v.):
                -- Nếu võ mục tiêu chưa sở hữu:
                -- - Nếu là Dragon Talon: kiểm tra xem có đang hết lượt random xương hay không.
                --   + Nếu CÒN LƯỢT quay xương -> Tiếp tục làm bước mở khóa võ (DoMeleeV2UnlockStep: farm xương, nộp Fire Essence)!
                --   + Nếu HẾT LƯỢT quay xương -> Tự động chạy tiếp xuống dưới để Farm Cấp / Luyện Kiếm cho tới khi hồi lượt quay!
                if type(V1StyleLookup) == "table" and type(V1StyleLookup.GetActiveTargetStyle) == "function" then
                    local actStyle = V1StyleLookup.GetActiveTargetStyle()
                    if actStyle ~= nil then
                        local hasTool = (V1StyleLookup.FindMeleeTool and V1StyleLookup.FindMeleeTool(actStyle.Name) ~= nil)
                        if not hasTool then
                            local hasEssence = (type(V1StyleLookup.ItemsSystem) == "table" and V1StyleLookup.ItemsSystem.HasToolOnPlayer("Fire Essence"))
                            local isDtCooldown = false
                            if actStyle.Name == "Dragon Talon" and not hasEssence and type(V1StyleLookup.ItemsSystem) == "table" and V1StyleLookup.ItemsSystem.IsBonesOnCooldown then
                                isDtCooldown = V1StyleLookup.ItemsSystem.IsBonesOnCooldown()
                            end

                            -- Nếu còn lượt quay (không bị cooldown) hoặc đang có sẵn Fire Essence -> Thực hiện bước mở khóa võ (DoMeleeV2UnlockStep)
                            if not isDtCooldown or hasEssence then
                                if type(V1StyleLookup.ItemsSystem) == "table" and V1StyleLookup.ItemsSystem.DoMeleeV2UnlockStep then
                                    if V1StyleLookup.ItemsSystem.DoMeleeV2UnlockStep(hrp, hum, actStyle) then
                                        return
                                    end
                                end
                            end
                            -- Nếu hết lượt quay xương (isDtCooldown == true) và chưa có Fire Essence -> Tự động cho phép chạy xuống Auto Farm Level / Kiếm bình thường!
                        end
                    end
                end

                local qInfo = GetQuestByLevel()
                if not qInfo then
                    CurrentFarmStatus = "Đang tìm thông tin nhiệm vụ..."
                    return
                end

                -- Nếu ở Sea 3 cấp >= 2600 cần xuống Submerged Island
                if qInfo.Submerged and not IsInSubmergedIsland() then
                    CurrentFarmStatus = "Đang di chuyển tới tàu ngầm (Submerged Island)..."
                    local subNpcPos = CFrame.new(-16269.704, 25.228, 1373.659)
                    if (hrp.Position - subNpcPos.Position).Magnitude > 10 then
                        TweenTo(subNpcPos)
                    else
                        if getgenv().StopTween then getgenv().StopTween() end
                        task.wait(0.5)
                        pcall(function()
                            Net:FindFirstChild("RF/SubmarineWorkerSpeak"):InvokeServer("TravelToSubmergedIsland")
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("SetLastSpawnPoint", "SubmergedIsland")
                        end)
                        task.wait(2)
                    end
                    return
                end

                -- Kiểm tra nhiệm vụ hiện tại (chống lỗi nhận nhiệm vụ xong hủy ngay)
                local hasQuest = HasActiveQuest()
                local activeMob = qInfo.Mob

                if hasQuest then
                    local isProtectedProgressionBoss = false
                    local qTextCheck = GetQuestText():lower()
                    local rbList = { "stone", "island empress", "hydra leader", "kilo admiral", "captain elephant", "beautiful pirate" }
                    for _, rb in ipairs(rbList) do
                        if string.find(qTextCheck, rb, 1, true) then
                            isProtectedProgressionBoss = true
                            break
                        end
                    end
                    if not isProtectedProgressionBoss and string.find(qTextCheck, "captain elephant", 1, true) then
                        isProtectedProgressionBoss = true
                    end

                    -- Nếu nhiệm vụ hiện tại là nhiệm vụ Boss -> Hủy ngay lập tức và quay lại nhận nhiệm vụ quái thường (trừ khi là nhiệm vụ Boss tiến trình Rainbow Haki / Instinct V2)
                    local isBossQuest, bossName = IsActiveQuestBoss(qInfo.Mob)
                    if isBossQuest then
                        local isCurrentFarmMob = false
                        local validList = qInfo.Mobs or { qInfo.Mob }
                        for _, vm in ipairs(validList) do
                            local vLow = string.lower(vm)
                            local bLow = string.lower(tostring(bossName))
                            if vLow == bLow or string.find(vLow, bLow, 1, true) or string.find(bLow, vLow, 1, true) then
                                isCurrentFarmMob = true
                                break
                            end
                        end

                        if not isProtectedProgressionBoss and bossName then
                            local bLow = string.lower(tostring(bossName))
                            for _, rb in ipairs(rbList) do
                                if bLow == rb or string.find(bLow, rb, 1, true) then
                                    isProtectedProgressionBoss = true
                                    break
                                end
                            end
                        end

                        if not isCurrentFarmMob and not isProtectedProgressionBoss and (getgenv()._lastStartedQuestMob ~= qInfo.Mob or (tick() - (getgenv()._lastStartQuest or 0) >= 300)) then
                            CurrentFarmStatus = "Bỏ qua nhiệm vụ Boss (" .. tostring(bossName) .. "), quay lại farm quái..."
                            pcall(function()
                                ReplicatedStorage.Remotes.CommF_:InvokeServer("AbandonQuest")
                            end)
                            ResetQuestSeen()
                            task.wait(0.4)
                            return
                        end
                    end

                    local guiMob = GetActiveQuestMob()
                    local qText = GetQuestText():lower()
                    local validList = qInfo.Mobs or { qInfo.Mob }
                    local isValid = false

                    if guiMob then
                        for _, m in ipairs(validList) do
                            if string.lower(m) == string.lower(guiMob) then
                                isValid = true
                                activeMob = guiMob
                                break
                            end
                        end
                    elseif qText ~= "" then
                        for _, m in ipairs(validList) do
                            if string.find(qText, string.lower(m), 1, true) then
                                isValid = true
                                activeMob = m
                                break
                            end
                        end
                    else
                        -- UI đang load sau khi nhận quest, tạm coi là hợp lệ
                        isValid = true
                    end

                    -- Chống lỗi dịch tự động tiếng Việt của Roblox khiến tên quái trên UI không khớp tên tiếng Anh trong code:
                    -- Nếu bot vừa nhận quest này trong vòng 5 phút (300 giây), nó CHẮC CHẮN là nhiệm vụ hợp lệ!
                    if not isValid and getgenv()._lastStartedQuestMob == qInfo.Mob and (tick() - (getgenv()._lastStartQuest or 0) < 300) then
                        isValid = true
                        activeMob = qInfo.Mob
                    end

                    -- Nếu chưa nhận dạng được text UI nhưng bot đã nhận quest từ server, không hủy
                    if not isValid and (guiMob == nil and qText == "") then
                        isValid = true
                        activeMob = qInfo.Mob
                    end

                    -- Tuyệt đối không hủy nếu đây là nhiệm vụ tiến trình được bảo vệ (Rainbow Haki / Instinct V2 / v.v.)
                    if isProtectedProgressionBoss then
                        isValid = true
                    end

                    -- Chỉ hủy nhiệm vụ nếu ĐÃ XÁC ĐỊNH RÕ RÀNG là nhiệm vụ cũ thuộc đảo/quái khác (và không phải do bot vừa nhận)
                    if not isValid and not isProtectedProgressionBoss and (tick() - (getgenv()._lastStartQuest or 0) > 8) then
                        getgenv()._staleQuestSince = getgenv()._staleQuestSince or tick()
                        if tick() - getgenv()._staleQuestSince >= 2.0 and tick() - (getgenv()._lastAbandonQuest or 0) >= 4 then
                            CurrentFarmStatus = "Hủy nhiệm vụ cũ không khớp (" .. tostring(guiMob or qText) .. ")..."
                            getgenv()._lastAbandonQuest = tick()
                            getgenv()._staleQuestSince = nil
                            pcall(function()
                                ReplicatedStorage.Remotes.CommF_:InvokeServer("AbandonQuest")
                            end)
                            ResetQuestSeen()
                            task.wait(0.5)
                        end
                        return
                    else
                        getgenv()._staleQuestSince = nil
                    end
                end

                -- ĐÁNH HẾT QUÁI ĐÃ GOM: Kiểm tra xem quanh người chơi (<= 45 studs) có quái gom nào đang còn sống không
                local clusterMob = nil
                local enemiesFolder = workspace:FindFirstChild("Enemies")
                if enemiesFolder and hrp then
                    for _, em in ipairs(enemiesFolder:GetChildren()) do
                        if not Players:GetPlayerFromCharacter(em) and not Players:FindFirstChild(em.Name) and not em:FindFirstChild("PlayerGui") and not em:FindFirstChild("Backpack") and (not em.Parent or em.Parent.Name ~= "Characters") then
                            local hum = em:FindFirstChildOfClass("Humanoid")
                            local eHrp = em:FindFirstChild("HumanoidRootPart")
                            if hum and eHrp and hum.Health > 0 and (eHrp.Position - hrp.Position).Magnitude <= 45 then
                                if not AllBossMobs[string.lower(StripMobLevelTag(em.Name))] and not em:FindFirstChildWhichIsA("ProximityPrompt", true) then
                                    clusterMob = em
                                    break
                                end
                            end
                        end
                    end
                end

                -- Nếu chưa có nhiệm vụ: CHỈ bay đi nhận nhiệm vụ khi ĐÃ ĐÁNH HẾT toàn bộ quái gom xung quanh!
                if not hasQuest then
                    if clusterMob then
                        getgenv()._currentTargetMobName = StripMobLevelTag(clusterMob.Name)
                        EnableBuso()
                        EquipSelectedWeapon()
                        BringMobs(clusterMob)
                        TweenTo(clusterMob.HumanoidRootPart.CFrame * CFrame.new(0, 20, 0))
                        CurrentFarmStatus = "Đánh nốt quái đã gom: " .. tostring(clusterMob.Name) .. " (HP: " .. math.floor(clusterMob.Humanoid.Health) .. ")"
                        return
                    end

                    CurrentFarmStatus = "Đang đi nhận nhiệm vụ: " .. tostring(qInfo.Mob)
                    local distToQuest = (hrp.Position - qInfo.QuestPos.Position).Magnitude
                    if distToQuest > 12 then
                        TweenTo(qInfo.QuestPos * CFrame.new(0, 4, 2))
                    else
                        if getgenv().StopTween then getgenv().StopTween() end
                        hrp.CFrame = qInfo.QuestPos * CFrame.new(0, 4, 2)
                        task.wait(0.4)
                        getgenv()._lastStartQuest = tick()
                        getgenv()._lastStartedQuestMob = qInfo.Mob
                        getgenv()._lastStartedQuestName = tostring(qInfo.QuestName)
                        getgenv()._lastStartedQuestId = qInfo.QuestId
                        getgenv()._staleQuestSince = nil
                        ReplicatedStorage.Remotes.CommF_:InvokeServer("StartQuest", tostring(qInfo.QuestName), qInfo.QuestId)
                        pcall(function()
                            ReplicatedStorage.Remotes.CommF_:InvokeServer("SetSpawnPoint")
                        end)
                        for _ = 1, 15 do
                            if HasActiveQuest() then
                                break
                            end
                            task.wait(0.15)
                        end
                    end
                    return
                end

                -- Đã có nhiệm vụ -> Tìm và đánh quái (ưu tiên đánh dứt điểm quái đã gom ở gần trước khi đi tìm con khác)
                getgenv()._currentTargetMobName = activeMob
                local targetMob = clusterMob or GetNearestAliveMob(activeMob)
                local tHum = targetMob and targetMob:FindFirstChildOfClass("Humanoid")
                if targetMob and tHum and tHum.Health > 0 and targetMob:FindFirstChild("HumanoidRootPart") then
                    local curMobHP = tHum.Health
                    CurrentFarmStatus = "Đang Farm: " .. tostring(activeMob) .. " (HP: " .. math.floor(curMobHP) .. ")"
                    getgenv()._currentWaitSpawnPart = nil
                    getgenv()._waitSpawnSince = nil

                    -- Nếu game hiện thông báo "Confront the prisoner before attacking!" -> Quái này là NPC nhiệm vụ ẩn (Escaped Prisoner) -> Lập tức bỏ qua quái này để chuyển sang quái thường
                    if HasConfrontPrisonerNotification() then
                        pcall(function()
                            if not targetMob:FindFirstChild("Z9_IgnoreMob") then
                                local ig = Instance.new("BoolValue")
                                ig.Name = "Z9_IgnoreMob"
                                ig.Parent = targetMob
                            end
                        end)
                        getgenv()._stuckMobRef = nil
                        getgenv()._stuckMobHP = nil
                        getgenv()._stuckMobSince = nil
                        getgenv()._pauseFastAttackUntil = tick() + 0.5
                        return
                    end

                    EnableBuso()
                    EquipSelectedWeapon()
                    BringMobs(targetMob)
                    TweenTo(targetMob.HumanoidRootPart.CFrame * CFrame.new(0, 20, 0))

                    -- Kiểm tra sát thương thực tế khi áp sát mục tiêu:
                    if (hrp.Position - targetMob.HumanoidRootPart.Position).Magnitude <= 35 then
                        if getgenv()._stuckMobRef ~= targetMob then
                            getgenv()._stuckMobRef = targetMob
                            getgenv()._stuckMobHP = curMobHP
                            getgenv()._stuckMobSince = tick()
                        elseif curMobHP < (getgenv()._stuckMobHP or curMobHP) then
                            getgenv()._stuckMobHP = curMobHP
                            getgenv()._stuckMobSince = tick()
                        else
                            local elapsed = tick() - (getgenv()._stuckMobSince or tick())
                            -- Chỉ tạm thời chuyển quái khác nếu đã đánh liên tục 8.0s mà không mất máu (tránh nhầm lẫn khi quái né Observation Haki)
                            if elapsed >= 8.0 then
                                pcall(function()
                                    if not targetMob:FindFirstChild("Z9_IgnoreMob") then
                                        local ig = Instance.new("NumberValue")
                                        ig.Name = "Z9_IgnoreMob"
                                        ig.Value = tick() + 3.0 -- Chỉ tạm bỏ qua 3 giây rồi thử lại nếu không có quái khác
                                        ig.Parent = targetMob
                                    end
                                end)
                                getgenv()._stuckMobRef = nil
                                getgenv()._stuckMobHP = nil
                                getgenv()._stuckMobSince = nil
                            end
                        end
                    end
                else
                    getgenv()._stuckMobRef = nil
                    getgenv()._stuckMobHP = nil
                    getgenv()._stuckMobSince = nil
                    CurrentFarmStatus = "Đang đợi quái xuất hiện: " .. tostring(activeMob)
                    -- Ưu tiên tuyệt đối điểm EnemySpawns thực tế trên đảo (tuần tra qua từng bãi spawn của quái)
                    local spawnPart = DetectPartSpawnMob(activeMob, true)
                    if not spawnPart then
                        ClearVisitedMobSpawns(activeMob)
                        spawnPart = DetectPartSpawnMob(activeMob, false)
                    end

                    if spawnPart then
                        if getgenv()._currentWaitSpawnPart ~= spawnPart then
                            getgenv()._currentWaitSpawnPart = spawnPart
                            getgenv()._waitSpawnSince = nil
                        end
                        TweenTo(spawnPart.CFrame * CFrame.new(0, 45, 0))
                        if (spawnPart.Position - hrp.Position).Magnitude <= 90 then
                            getgenv()._waitSpawnSince = getgenv()._waitSpawnSince or tick()
                            if tick() - getgenv()._waitSpawnSince >= 1.2 then
                                pcall(function()
                                    if not spawnPart:FindFirstChild("Z9_SpawnVisited") then
                                        local v = Instance.new("IntValue")
                                        v.Name = "Z9_SpawnVisited"
                                        v.Parent = spawnPart
                                    end
                                end)
                                getgenv()._currentWaitSpawnPart = nil
                                getgenv()._waitSpawnSince = nil
                            end
                        end
                    else
                        local fallbackPos = FindMobSpawnCFrame(activeMob) or qInfo.MobPos or qInfo.QuestPos
                        if fallbackPos then
                            TweenTo(fallbackPos * CFrame.new(0, 35, 0))
                        end
                    end
                end
            end)
            if not ok then
                warn("[AutoFarm Loop Error]: " .. tostring(loopErr))
            end
        end
    end
end)

-- ==========================================
-- HỆ THỐNG THÔNG BÁO WEBHOOK ĐỊNH KỲ (5 PHÚT / LẦN)
-- ==========================================
local WebhookSystem = {
    StartTime = getgenv().Z9_ScriptStartTime or tick(),
}
getgenv().Z9_ScriptStartTime = WebhookSystem.StartTime

function WebhookSystem.FormatUptime(seconds)
    seconds = math.max(0, math.floor(seconds or 0))
    local h = math.floor(seconds / 3600)
    local m = math.floor((seconds % 3600) / 60)
    local s = seconds % 60
    return string.format("%02dh %02dm %02ds", h, m, s)
end

function WebhookSystem.GetHttpFunc()
    return (syn and syn.request)
        or (http and http.request)
        or http_request
        or (fluxus and fluxus.request)
        or request
end

function WebhookSystem.GetStoredFruitsSummaryText()
    local storedMap = GetStoredFruitsCountMap(false)
    local items = {}
    for fruitName, count in pairs(storedMap) do
        table.insert(items, tostring(fruitName) .. " (x" .. tostring(count) .. ")")
    end
    table.sort(items)
    if #items == 0 then
        return "Trống (Chưa có trái nào trong kho)"
    end
    local text = table.concat(items, ", ")
    if #text > 950 then
        text = string.sub(text, 1, 950) .. "..."
    end
    return text
end

local function SendKaitunWebhook()
    local cfg = getgenv().SettingFarm and getgenv().SettingFarm["Webhook"]
    if type(cfg) ~= "table" or cfg["Enabled"] ~= true then
        return false
    end

    local url = tostring(cfg["WebhookUrl"] or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if url == "" or not string.find(url, "^https?://") then
        return false
    end

    local reqFunc = WebhookSystem.GetHttpFunc()
    if not reqFunc then
        return false
    end

    local data = plr:FindFirstChild("Data")
    local lv = (data and data:FindFirstChild("Level") and data.Level.Value) or 0
    local beli = (data and data:FindFirstChild("Beli") and data.Beli.Value) or 0
    local frags = (data and data:FindFirstChild("Fragments") and data.Fragments.Value) or 0
    local race = (data and data:FindFirstChild("Race") and data.Race.Value) or "Unknown"
    local fruit = (data and data:FindFirstChild("DevilFruit") and data.DevilFruit.Value) or ""
    local fruitText = (fruit ~= "" and fruit) or "Không có"

    if fruit ~= "" then
        local fTool = (plr.Backpack and plr.Backpack:FindFirstChild(fruit)) or (plr.Character and plr.Character:FindFirstChild(fruit))
        if fTool and fTool:FindFirstChild("Level") then
            fruitText = fruit .. " (Mas. " .. tostring(fTool.Level.Value) .. ")"
        end
    end

    local _, meleeName, meleeMas = GetCurrentMeleeTool()
    local statsFolder = data and data:FindFirstChild("Stats")
    local meleeLv = (statsFolder and statsFolder:FindFirstChild("Melee") and statsFolder.Melee:FindFirstChild("Level") and statsFolder.Melee.Level.Value) or 0
    local defLv = (statsFolder and statsFolder:FindFirstChild("Defense") and statsFolder.Defense:FindFirstChild("Level") and statsFolder.Defense.Level.Value) or 0
    local swordLv = (statsFolder and statsFolder:FindFirstChild("Sword") and statsFolder.Sword:FindFirstChild("Level") and statsFolder.Sword.Level.Value) or 0
    local fruitLv = (statsFolder and statsFolder:FindFirstChild("Demon Fruit") and statsFolder["Demon Fruit"]:FindFirstChild("Level") and statsFolder["Demon Fruit"].Level.Value) or 0
    local statPts = (data and data:FindFirstChild("Points") and data.Points.Value) or 0

    local seaLabel = (World3 and "Sea 3 (Third Sea)") or (World2 and "Sea 2 (Dressrosa)") or "Sea 1 (Old World)"
    local uptimeStr = WebhookSystem.FormatUptime(tick() - WebhookSystem.StartTime)
    local v1Text = GetV1MeleeStatusText(beli, frags)
    local storedFruitsText = WebhookSystem.GetStoredFruitsSummaryText()

    local payload = {
        username = "Z9 KaiTun Monitor",
        embeds = {
            {
                title = "⚡ Z9 KaiTun — Báo Cáo Tiến Trình Tự Động",
                description = "**Trạng thái hiện tại:**\n```yaml\n" .. tostring(CurrentFarmStatus) .. "\n```",
                color = 0xFF2A5F,
                fields = {
                    {
                        name = "👤 Tài Khoản & Máy Chủ",
                        value = "• **Player:** ||" .. tostring(plr.Name) .. "||\n"
                            .. "• **Khu vực:** `" .. seaLabel .. "`\n"
                            .. "• **Thời gian treo:** `" .. uptimeStr .. "`",
                        inline = true,
                    },
                    {
                        name = "💰 Cấp Độ & Tài Sản",
                        value = "• **Cấp (Level):** `" .. FormatNumber(lv) .. "`\n"
                            .. "• **Beli:** `$" .. FormatNumber(beli) .. "`\n"
                            .. "• **Fragments:** `ƒ" .. FormatNumber(frags) .. "`\n"
                            .. "• **Tộc (Race):** `" .. tostring(race) .. " [" .. GetRaceVersion() .. "]`",
                        inline = true,
                    },
                    {
                        name = "🥊 Vũ Khí & Chỉ Số (Stats)",
                        value = "• **Võ đang cầm:** `" .. tostring(meleeName) .. " (Mas. " .. tostring(meleeMas) .. ")`\n"
                            .. "• **Trái đang ăn:** `" .. tostring(fruitText) .. "`\n"
                            .. "• **Stats:** `Melee: " .. tostring(meleeLv) .. " | Def: " .. tostring(defLv) .. " | Sword: " .. tostring(swordLv) .. " | Fruit: " .. tostring(fruitLv) .. "` (Dư: `" .. tostring(statPts) .. "`)",
                        inline = false,
                    },
                    {
                        name = "🏆 Tiến Trình Võ V1 (Mục tiêu: 400 Mastery)",
                        value = v1Text,
                        inline = false,
                    },
                    {
                        name = "🍎 Kho Trái Ác Quỷ (Inventory)",
                        value = "```" .. storedFruitsText .. "```",
                        inline = false,
                    },
                },
                footer = {
                    text = "Z9 KaiTun Hub • Tự động báo cáo mỗi 5 phút",
                },
                timestamp = DateTime.now():ToIsoDate(),
            }
        }
    }

    local ok = pcall(function()
        reqFunc({
            Url = url,
            Method = "POST",
            Headers = {
                ["Content-Type"] = "application/json",
            },
            Body = HttpService:JSONEncode(payload),
        })
    end)
    return ok
end

-- Vòng lặp kiểm tra & gửi thông báo Webhook mỗi 5 phút (300 giây) khi ["Webhook"]["Enabled"] = true
task.spawn(function()
    local lastWebhookSent = 0
    local WEBHOOK_INTERVAL = 300 -- 5 phút = 300 giây
    while task.wait(2) do
        pcall(function()
            local cfg = getgenv().SettingFarm and getgenv().SettingFarm["Webhook"]
            if type(cfg) == "table" and cfg["Enabled"] == true and tostring(cfg["WebhookUrl"] or "") ~= "" then
                if tick() - lastWebhookSent >= WEBHOOK_INTERVAL then
                    if SendKaitunWebhook() then
                        lastWebhookSent = tick()
                    end
                end
            end
        end)
    end
end)

-- ==========================================
-- HỆ THỐNG TỰ ĐỘNG ĐỔI SERVER KHI PING > 200MS
-- ==========================================
local function HopHighPingServer(currentPing)
    if not IsAutoHopEnabled() then return end
    HopServer("Ping cao " .. tostring(currentPing) .. "ms")
end

task.spawn(function()
    -- Đợi 15s đầu sau khi vào game để Ping ổn định
    task.wait(15)
    local highPingStreak = 0

    while task.wait(3) do
        pcall(function()
            if not IsAutoFarmActive() then
                highPingStreak = 0
                return
            end

            -- Kiểm tra công tắc cấu hình Auto Hop và Hop ping
            if not IsAutoHopEnabled() or not IsHopPingEnabled() then
                highPingStreak = 0
                return
            end

            -- Không đổi server khi đang ở trong Raid, đang cầm Microchip, đang cầm Key mở hầm băng Sea 2, hoặc đang làm nhiệm vụ Human V3
            local hasKey = (plr.Character and plr.Character:FindFirstChild("Key")) or (plr.Backpack and plr.Backpack:FindFirstChild("Key"))
            local isDoingHumanV3 = (CachedRaceVer ~= "V3" and IsAutoRaceV3Enabled())
            if IsInRaid() or HasSpecialMicrochip() or hasKey or CurrentTargetFruit ~= nil or isDoingHumanV3 then
                highPingStreak = 0
                return
            end

            local curPing = GetCurrentPingMs()
            if curPing > 200 then
                highPingStreak = highPingStreak + 1
                -- Nếu Ping > 200ms liên tục 3 lần kiểm tra (~9 giây) -> Đổi sang Server khác ngay
                if highPingStreak >= 3 then
                    highPingStreak = 0
                    HopHighPingServer(curPing)
                end
            else
                highPingStreak = 0
            end
        end)
    end
end)
